function normaliseLlmExecutionContextString(value) {
    return (typeof value === 'string' && value.trim()) ? value.trim() : null;
}

function normaliseLlmExecutionContextModel(value) {
    const clean = normaliseLlmExecutionContextString(value);
    if (!clean) return null;
    return clean.replace(/^(?:openai|openrouter|ollama|gemini)[/:]/i, '');
}

function inferLlmProviderFromModelReference(value) {
    const clean = normaliseLlmExecutionContextString(value);
    if (!clean) return null;
    const matched = clean.match(/^(openai|openrouter|ollama|gemini)[/:]/i);
    return matched ? matched[1].toLowerCase() : null;
}

function buildLlmExecutionConfigurationBinding(requestedLlm = null) {
    const source = requestedLlm && typeof requestedLlm === 'object' ? requestedLlm : {};
    const model = normaliseLlmExecutionContextModel(source.model || source.requestModel);
    const provider = normaliseLlmExecutionContextString(source.provider)
        || inferLlmProviderFromModelReference(source.requestModel || source.model);
    const host = normaliseLlmExecutionContextString(source.host);
    const modelParameters = source.model_parameters && typeof source.model_parameters === 'object'
        ? JSON.parse(JSON.stringify(source.model_parameters))
        : null;
    return {
        provider: provider ? provider.toLowerCase() : null,
        model,
        host,
        model_parameters: modelParameters,
    };
}

function readCurrentLlmExecutionContextSnapshot(sessionId = activeChatSessionId) {
    const namespaceContext = buildConversationTelemetryNamespaceContext();
    const localPreference = getEffectiveLocalModelPreference();
    const configuration = buildLlmExecutionConfigurationBinding(localPreference?.requestedLlm);
    return {
        window_session_id: normaliseLlmExecutionContextString(getWindowSessionId()),
        user_concept_id: normaliseLlmExecutionContextString(namespaceContext.user_id),
        organisation_concept_id: normaliseLlmExecutionContextString(namespaceContext.org_id),
        conversation_session_id: normaliseLlmExecutionContextString(sessionId),
        configuration,
    };
}

function publishCurrentLlmExecutionContextBinding(snapshot) {
    try {
        window.__vonCurrentLlmExecutionContextBinding = snapshot;
    } catch (_) {
        // Ignore non-writable globals in constrained environments.
    }
}

function invalidatePublishedLlmExecutionTelemetry(reason = 'execution_context_changed') {
    try {
        window.__vonLatestLlmExecutionTelemetry = null;
    } catch (_) {
        // Ignore non-writable globals in constrained environments.
    }
    try {
        document.dispatchEvent(new CustomEvent('von:latestLlmExecutionTelemetryUpdated', {
            detail: null,
        }));
    } catch (_) {
        // Telemetry invalidation should not block normal flow.
    }
    console.debug('[chatTab] Invalidated latest LLM execution telemetry', { reason });
}

function synchroniseLlmExecutionContext({ force = false, reason = 'context_refresh' } = {}) {
    const current = readCurrentLlmExecutionContextSnapshot();
    const signature = JSON.stringify(current);
    const changed = llmExecutionContextSignature !== null && signature !== llmExecutionContextSignature;
    if (llmExecutionContextSignature === null) {
        llmExecutionContextGeneration = 1;
    } else if (force || changed) {
        llmExecutionContextGeneration += 1;
        invalidatePublishedLlmExecutionTelemetry(reason);
    }
    llmExecutionContextSignature = signature;
    const bound = {
        schema_version: LLM_EXECUTION_CONTEXT_BINDING_SCHEMA_VERSION,
        generation: llmExecutionContextGeneration,
        ...current,
    };
    publishCurrentLlmExecutionContextBinding(bound);
    synchroniseConversationRuntimeCostContext({ force, reason });
    return bound;
}

function deriveLlmExecutionContextBinding(debugData, baseBinding = null) {
    const binding = {
        ...(baseBinding && typeof baseBinding === 'object'
            ? baseBinding
            : synchroniseLlmExecutionContext()),
    };
    const namespaceReport = debugData?.namespace_report && typeof debugData.namespace_report === 'object'
        ? debugData.namespace_report
        : null;
    if (namespaceReport && Object.prototype.hasOwnProperty.call(namespaceReport, 'user_concept_id')) {
        const reportedUser = normaliseLlmExecutionContextString(namespaceReport.user_concept_id);
        if (reportedUser) binding.user_concept_id = reportedUser;
    }
    if (namespaceReport && Object.prototype.hasOwnProperty.call(namespaceReport, 'organisation_concept_id')) {
        const reportedOrganisation = normaliseLlmExecutionContextString(
            namespaceReport.organisation_concept_id,
        );
        if (reportedOrganisation) binding.organisation_concept_id = reportedOrganisation;
    }
    const historySessionId = normaliseLlmExecutionContextString(
        debugData?.history_location?.session_id
        || debugData?.turn_execution_diagnostics?.history_location?.session_id,
    );
    if (historySessionId) {
        binding.conversation_session_id = historySessionId;
    }

    const llmInteraction = debugData?.llm_interaction && typeof debugData.llm_interaction === 'object'
        ? debugData.llm_interaction
        : null;
    const requestedModel = normaliseLlmExecutionContextString(
        llmInteraction?.requested_model || debugData?.model,
    );
    if (requestedModel) {
        const interactionCalls = Array.isArray(llmInteraction?.calls) ? llmInteraction.calls : [];
        const requestedModelForComparison = normaliseLlmExecutionContextModel(requestedModel)?.toLowerCase();
        const matchingRequestedCall = [...interactionCalls].reverse().find((call) => (
            normaliseLlmExecutionContextModel(call?.model)?.toLowerCase() === requestedModelForComparison
        ));
        const recordedProvider = normaliseLlmExecutionContextString(
            matchingRequestedCall?.provider
            || (interactionCalls.length === 1 ? interactionCalls[0]?.provider : null),
        );
        const requestedProvider = normaliseLlmExecutionContextString(llmInteraction?.requested_provider)
            || inferLlmProviderFromModelReference(requestedModel)
            || recordedProvider
            || binding.configuration?.provider
            || null;
        binding.configuration = {
            ...(binding.configuration && typeof binding.configuration === 'object'
                ? binding.configuration
                : {}),
            provider: requestedProvider ? requestedProvider.toLowerCase() : null,
            model: normaliseLlmExecutionContextModel(requestedModel),
        };
    }
    binding.configuration_fingerprint = JSON.stringify(binding.configuration || {});
    return binding;
}

function setLlmDebugDataEntry(turnId, debugData, executionContextBinding = null) {
    if (!turnId) {
        return;
    }
    llmDebugData.set(turnId, debugData);
    const existingBinding = llmDebugExecutionContextBindings.get(turnId) || null;
    llmDebugExecutionContextBindings.set(
        turnId,
        deriveLlmExecutionContextBinding(
            debugData,
            executionContextBinding || existingBinding,
        ),
    );
    refreshConversationInfoCopyButtonState();
    publishLatestLlmExecutionTelemetry();
}

function clearLlmDebugDataEntries() {
    llmDebugData.clear();
    llmDebugExecutionContextBindings.clear();
    refreshConversationInfoCopyButtonState();
    publishLatestLlmExecutionTelemetry();
}

function normaliseTelemetryStringArray(values) {
    if (!Array.isArray(values)) {
        return [];
    }
    const normalised = [];
    const seen = new Set();
    for (const value of values) {
        if (typeof value !== 'string') {
            continue;
        }
        const cleaned = value.trim();
        if (!cleaned) {
            continue;
        }
        const dedupeKey = cleaned.toLowerCase();
        if (seen.has(dedupeKey)) {
            continue;
        }
        seen.add(dedupeKey);
        normalised.push(cleaned);
    }
    return normalised;
}

function readLlmExecutionFailureCandidate(candidate) {
    if (!candidate || typeof candidate !== 'object') {
        return null;
    }
    const failureKind = (typeof candidate.failure_kind === 'string' && candidate.failure_kind.trim())
        ? candidate.failure_kind.trim()
        : null;
    const failureReason = (typeof candidate.error === 'string' && candidate.error.trim())
        ? candidate.error.trim()
        : null;
    if (!failureKind && !failureReason) {
        return null;
    }
    return { failureKind, failureReason };
}

function isSuccessfulLlmExecutionCall(call) {
    if (!call || typeof call !== 'object') {
        return false;
    }
    if (call.success === true) {
        return true;
    }
    if (call.success === false) {
        return false;
    }
    const status = (typeof call.status === 'string') ? call.status.trim().toLowerCase() : '';
    if (['ok', 'success', 'succeeded', 'completed'].includes(status)) {
        return true;
    }
    if (['error', 'failed', 'failure', 'cancelled', 'timed_out', 'timeout'].includes(status)) {
        return false;
    }
    if (
        (typeof call.error === 'string' && call.error.trim())
        || (typeof call.failure_kind === 'string' && call.failure_kind.trim())
    ) {
        return false;
    }
    // Successful orchestrator call records currently omit status/success, while
    // failed records carry explicit failure fields. A recorded model/provider is
    // therefore positive completion evidence when no failure marker is present.
    return !!(
        (typeof call.model === 'string' && call.model.trim())
        || (typeof call.provider === 'string' && call.provider.trim())
    );
}

function extractLatestLlmExecutionFailure(auxCalls = [], rawCalls = []) {
    const policyStages = Array.isArray(auxCalls)
        ? auxCalls.filter((entry) => entry && typeof entry === 'object' && entry.type === 'workflow_model_policy_stage')
        : [];
    const calls = Array.isArray(rawCalls)
        ? rawCalls.filter((entry) => entry && typeof entry === 'object')
        : [];
    const terminalCall = calls.length ? calls[calls.length - 1] : null;
    const terminalCallSucceeded = isSuccessfulLlmExecutionCall(terminalCall);
    const terminalCallStage = (typeof terminalCall?.stage === 'string' && terminalCall.stage.trim())
        ? terminalCall.stage.trim()
        : null;
    let latestStage = null;
    if (terminalCall && terminalCallStage) {
        for (let index = policyStages.length - 1; index >= 0; index -= 1) {
            if (policyStages[index]?.stage === terminalCallStage) {
                latestStage = policyStages[index];
                break;
            }
        }
    }
    if (!terminalCall && policyStages.length) {
        latestStage = policyStages[policyStages.length - 1];
    }

    let latestObservedFailure = null;
    let fallbackUsed = calls.some((call) => (
        typeof call?.note === 'string'
        && call.note.toLowerCase().includes('trying fallback')
    ));
    for (const stageEntry of policyStages) {
        const errors = Array.isArray(stageEntry.errors) ? stageEntry.errors : [];
        const fallbackAttempts = Array.isArray(stageEntry.fallback_attempts) ? stageEntry.fallback_attempts : [];
        fallbackUsed = fallbackUsed || !!stageEntry.fallback_used || errors.length > 0;
        const candidates = [...errors, ...fallbackAttempts].reverse();
        for (const candidate of candidates) {
            const failure = readLlmExecutionFailureCandidate(candidate);
            if (failure) {
                latestObservedFailure = failure;
                break;
            }
        }
    }

    const latestFallbackAttempts = Array.isArray(latestStage?.fallback_attempts)
        ? latestStage.fallback_attempts
        : [];
    const latestStageSucceeded = !!(
        latestStage?.selected
        && typeof latestStage.selected === 'object'
    ) || latestFallbackAttempts.some((attempt) => {
        const status = (typeof attempt?.status === 'string') ? attempt.status.trim().toLowerCase() : '';
        return ['ok', 'success', 'succeeded', 'completed'].includes(status) || attempt?.success === true;
    });
    const latestStageErrors = Array.isArray(latestStage?.errors) ? latestStage.errors : [];
    const latestStageFailureCandidates = [
        ...latestStageErrors,
        ...latestFallbackAttempts,
    ].reverse();
    let latestStageFailure = null;
    for (const candidate of latestStageFailureCandidates) {
        latestStageFailure = readLlmExecutionFailureCandidate(candidate);
        if (latestStageFailure) {
            break;
        }
    }

    const terminalCallFailure = readLlmExecutionFailureCandidate(terminalCall);
    const executionSucceeded = terminalCall
        ? terminalCallSucceeded
        : latestStageSucceeded;
    if (executionSucceeded) {
        return {
            executionSucceeded: true,
            fallbackUsed,
            failureKind: null,
            failureReason: null,
            recoveredFailureKind: latestObservedFailure?.failureKind || null,
            recoveredFailureReason: latestObservedFailure?.failureReason || null,
        };
    }

    const terminalFailure = terminalCallFailure || latestStageFailure;
    return {
        executionSucceeded: false,
        fallbackUsed,
        failureKind: terminalFailure?.failureKind || null,
        failureReason: terminalFailure?.failureReason || null,
        recoveredFailureKind: null,
        recoveredFailureReason: null,
    };
}

function extractLatestStageModelSelection(auxCalls = []) {
    const policyStages = Array.isArray(auxCalls)
        ? auxCalls.filter((entry) => entry && typeof entry === 'object' && entry.type === 'workflow_model_policy_stage')
        : [];

    for (let index = policyStages.length - 1; index >= 0; index -= 1) {
        const entry = policyStages[index];
        const selected = entry && typeof entry.selected === 'object' ? entry.selected : null;
        const requestedModel = (typeof entry?.requested_model === 'string' && entry.requested_model.trim())
            ? entry.requested_model.trim()
            : null;
        const requestedProvider = (typeof entry?.requested_provider === 'string' && entry.requested_provider.trim())
            ? entry.requested_provider.trim()
            : null;
        const actualModel = (typeof selected?.model_resolved === 'string' && selected.model_resolved.trim())
            ? selected.model_resolved.trim()
            : ((typeof selected?.model === 'string' && selected.model.trim()) ? selected.model.trim() : null);
        const actualProvider = (typeof selected?.provider === 'string' && selected.provider.trim())
            ? selected.provider.trim()
            : null;
        const selectionMode = (typeof entry?.selection_mode === 'string' && entry.selection_mode.trim())
            ? entry.selection_mode.trim()
            : null;
        const overrideOrigin = (typeof entry?.explicit_stage_model_override_origin === 'string'
            && entry.explicit_stage_model_override_origin.trim())
            ? entry.explicit_stage_model_override_origin.trim()
            : null;
        const stage = (typeof entry?.stage === 'string' && entry.stage.trim()) ? entry.stage.trim() : null;
        const policyStage = (typeof entry?.policy_stage === 'string' && entry.policy_stage.trim())
            ? entry.policy_stage.trim()
            : stage;
        return {
            stage,
            policyStage,
            requestedModel,
            requestedProvider,
            actualModel,
            actualProvider,
            selectionMode,
            followsActiveLlm: entry?.follows_active_llm === true,
            explicitStageModelOverride: entry?.explicit_stage_model_override === true,
            explicitStageModelOverrideOrigin: overrideOrigin,
        };
    }

    return {
        stage: null,
        policyStage: null,
        requestedModel: null,
        requestedProvider: null,
        actualModel: null,
        actualProvider: null,
        selectionMode: null,
        followsActiveLlm: false,
        explicitStageModelOverride: false,
        explicitStageModelOverrideOrigin: null,
    };
}

function normaliseTurnOutputHealth(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }
    if (value.schema_version !== 'turn_output_health_v1') {
        return null;
    }
    const rawIssues = Array.isArray(value.issues) ? value.issues : [];
    const issues = rawIssues
        .filter((issue) => issue && typeof issue === 'object')
        .map((issue) => ({
            category: (typeof issue.category === 'string' && issue.category.trim()) ? issue.category.trim() : null,
            code: (typeof issue.code === 'string' && issue.code.trim()) ? issue.code.trim() : null,
            severity: (typeof issue.severity === 'string' && issue.severity.trim()) ? issue.severity.trim() : null,
            message: (typeof issue.message === 'string' && issue.message.trim()) ? issue.message.trim() : null,
            fallbackUsed: (typeof issue.fallback_used === 'string' && issue.fallback_used.trim()) ? issue.fallback_used.trim() : null,
        }))
        .filter((issue) => issue.message);
    return {
        schemaVersion: value.schema_version,
        status: (typeof value.status === 'string' && value.status.trim()) ? value.status.trim() : 'ok',
        issues,
    };
}

function getTurnOutputHealth(debugData) {
    if (!debugData || typeof debugData !== 'object') {
        return null;
    }
    return normaliseTurnOutputHealth(debugData.turn_output_health)
        || normaliseTurnOutputHealth(debugData.metadata?.turn_output_health)
        || null;
}

function getTurnOutputHealthMessages(turnOutputHealth) {
    if (!turnOutputHealth || !Array.isArray(turnOutputHealth.issues)) {
        return [];
    }
    return Array.from(new Set(
        turnOutputHealth.issues
            .map((issue) => issue.message)
            .filter((message) => typeof message === 'string' && message.trim())
    ));
}

function getTurnOutputHealthLlmExecutionFailure(turnOutputHealth) {
    if (!turnOutputHealth || !Array.isArray(turnOutputHealth.issues)) {
        return null;
    }
    const issue = turnOutputHealth.issues.find((candidate) => (
        candidate?.category === 'llm_execution'
        && ['error', 'fatal'].includes(candidate?.severity)
        && typeof candidate?.message === 'string'
        && candidate.message.trim()
    ));
    return issue ? issue.message.trim() : null;
}

function buildLatestLlmExecutionTelemetrySummary(turnId, debugData, executionContextBinding = null) {
    if (!debugData || typeof debugData !== 'object') {
        return null;
    }

    const llmInteraction = (debugData.llm_interaction && typeof debugData.llm_interaction === 'object')
        ? debugData.llm_interaction
        : ((debugData.metadata?.llm_interaction && typeof debugData.metadata.llm_interaction === 'object')
            ? debugData.metadata.llm_interaction
            : null);
    const rawCalls = Array.isArray(llmInteraction?.calls) ? llmInteraction.calls : [];
    const callModels = [];
    const callProviders = [];
    let actualModel = null;
    let actualProvider = null;
    let credentialSource = null;
    let credentialFailoverUsed = false;
    let primaryCredentialFailureKind = null;

    for (const call of rawCalls) {
        if (!call || typeof call !== 'object') {
            continue;
        }
        const model = (typeof call.model === 'string' && call.model.trim())
            ? call.model.trim()
            : null;
        const provider = (typeof call.provider === 'string' && call.provider.trim())
            ? call.provider.trim()
            : null;
        if (model) {
            callModels.push(model);
            actualModel = model;
        }
        if (provider) {
            callProviders.push(provider);
            actualProvider = provider;
        }
        const transportCandidates = [
            call.transport,
            call.transport_metadata,
            call.candidate?.transport_metadata,
            call.candidate?.llm_transport,
            call.metadata?.transport_metadata,
        ];
        for (const transport of transportCandidates) {
            if (!transport || typeof transport !== 'object') {
                continue;
            }
            const source = (typeof transport.credential_source === 'string')
                ? transport.credential_source.trim().toLowerCase()
                : '';
            if (source === 'primary' || source === 'backup') {
                credentialSource = source;
            }
            if (transport.credential_failover_used === true || source === 'backup') {
                credentialFailoverUsed = true;
            }
            if (
                typeof transport.primary_credential_failure_kind === 'string'
                && transport.primary_credential_failure_kind.trim()
            ) {
                primaryCredentialFailureKind = transport.primary_credential_failure_kind.trim();
            }
        }
    }

    const fallbackCallModels = normaliseTelemetryStringArray(llmInteraction?.call_models);
    if (!actualModel && fallbackCallModels.length > 0) {
        actualModel = fallbackCallModels[fallbackCallModels.length - 1];
    }

    const fallbackCallProviders = normaliseTelemetryStringArray(llmInteraction?.call_providers);
    if (!actualProvider && fallbackCallProviders.length > 0) {
        actualProvider = fallbackCallProviders[fallbackCallProviders.length - 1];
    }

    const uniqueCallModels = normaliseTelemetryStringArray([...callModels, ...fallbackCallModels]);
    const uniqueCallProviders = normaliseTelemetryStringArray([...callProviders, ...fallbackCallProviders]);
    const requestedModel = (typeof llmInteraction?.requested_model === 'string' && llmInteraction.requested_model.trim())
        ? llmInteraction.requested_model.trim()
        : ((typeof debugData.model === 'string' && debugData.model.trim()) ? debugData.model.trim() : null);
    const topLevelError = (typeof debugData.error === 'string' && debugData.error.trim())
        ? debugData.error.trim()
        : null;
    const turnOutputHealth = getTurnOutputHealth(debugData);
    const warnings = deriveLlmDebugWarnings(debugData);
    const failure = extractLatestLlmExecutionFailure(debugData.aux_llm_calls, rawCalls);
    const stageSelection = extractLatestStageModelSelection(debugData.aux_llm_calls);
    const fallbackUsed = !!failure.fallbackUsed;
    const outputHealthLlmFailure = getTurnOutputHealthLlmExecutionFailure(turnOutputHealth);
    const primaryFailureReason = topLevelError || outputHealthLlmFailure || failure.failureReason || null;
    const primaryFailureKind = (
        failure.failureKind
        && (!topLevelError || topLevelError === failure.failureReason)
        && (!outputHealthLlmFailure || outputHealthLlmFailure === failure.failureReason)
    ) ? failure.failureKind : null;

    const effectiveRequestedModel = requestedModel || stageSelection.requestedModel || null;
    const effectiveActualModel = actualModel || stageSelection.actualModel || null;
    const effectiveActualProvider = actualProvider || stageSelection.actualProvider || null;

    if (
        !effectiveRequestedModel
        && !effectiveActualModel
        && !effectiveActualProvider
        && !primaryFailureReason
        && !failure.recoveredFailureReason
        && !credentialFailoverUsed
        && warnings.length === 0
    ) {
        return null;
    }

    return {
        schema_version: LATEST_LLM_EXECUTION_TELEMETRY_SCHEMA_VERSION,
        context_binding: executionContextBinding && typeof executionContextBinding === 'object'
            ? { ...executionContextBinding }
            : null,
        turn_id: typeof turnId === 'string' ? turnId : null,
        timestamp: debugData.timestamp ?? null,
        requested_model: effectiveRequestedModel,
        actual_model: effectiveActualModel,
        actual_provider: effectiveActualProvider,
        call_models: uniqueCallModels,
        call_providers: uniqueCallProviders,
        execution_succeeded: failure.executionSucceeded === true,
        fallback_used: fallbackUsed,
        credential_source: credentialSource,
        credential_failover_used: credentialFailoverUsed,
        primary_credential_failure_kind: primaryCredentialFailureKind,
        primary_failure_kind: primaryFailureKind,
        primary_failure_reason: primaryFailureReason,
        recovered_failure_kind: failure.recoveredFailureKind || null,
        recovered_failure_reason: failure.recoveredFailureReason || null,
        error: topLevelError,
        execution_stage: stageSelection.stage,
        policy_stage: stageSelection.policyStage,
        selection_mode: stageSelection.selectionMode,
        follows_active_llm: stageSelection.followsActiveLlm,
        explicit_stage_model_override: stageSelection.explicitStageModelOverride,
        explicit_stage_model_override_origin: stageSelection.explicitStageModelOverrideOrigin,
        warnings: warnings.slice(0, 5),
    };
}

function publishLatestLlmExecutionTelemetry() {
    const latestEntry = getLatestLlmDebugEntryForExport();
    const currentBinding = synchroniseLlmExecutionContext();
    let summary = latestEntry
        ? buildLatestLlmExecutionTelemetrySummary(
            latestEntry.turnId,
            latestEntry.debugData,
            latestEntry.executionContextBinding,
        )
        : null;
    if (
        summary?.context_binding?.generation
        && summary.context_binding.generation !== currentBinding.generation
    ) {
        summary = null;
    }

    try {
        window.__vonLatestLlmExecutionTelemetry = summary;
    } catch (_) {
        // Ignore non-writable globals in constrained environments.
    }

    try {
        document.dispatchEvent(new CustomEvent('von:latestLlmExecutionTelemetryUpdated', {
            detail: summary,
        }));
    } catch (_) {
        // Telemetry publication should not block normal flow.
    }

    return summary;
}

function isDocumentVisibleForRealtimeConnections() {
    try {
        if (typeof document === 'undefined') return true;
        if (typeof document.visibilityState === 'string') {
            return document.visibilityState !== 'hidden';
        }
        return !document.hidden;
    } catch (_) {
        return true;
    }
}

function shouldRunSharedSessionBadgePollingForInputs({
    isVisible
} = {}) {
    return !!isVisible;
}

function shouldRunSharedSessionBadgePolling() {
    return shouldRunSharedSessionBadgePollingForInputs({
        isVisible: isDocumentVisibleForRealtimeConnections()
    });
}

function shouldMaintainSharedConversationStreamForInputs({
    sessionId,
    activeSessionId,
    isVisible,
    isSharedSession
} = {}) {
    const sid = String(sessionId || '').trim();
    if (!sid) return false;
    if (!isVisible) return false;
    if (String(activeSessionId || '').trim() !== sid) return false;
    return !!isSharedSession;
}

function shouldMaintainSharedConversationStream(sessionId) {
    const sid = String(sessionId || '').trim();
    return shouldMaintainSharedConversationStreamForInputs({
        sessionId: sid,
        activeSessionId: activeChatSessionId,
        isVisible: isDocumentVisibleForRealtimeConnections(),
        isSharedSession: isSharedConversationSession(sid)
    });
}

function shouldMaintainWorkflowStatusStream() {
    const { panel } = getWorkflowStatusElements();
    if (!panel || typeof EventSource === 'undefined') return false;
    return isDocumentVisibleForRealtimeConnections();
}

function buildRealtimeConnectionTelemetrySnapshot(source = 'unknown') {
    const eventSource = (typeof source === 'string' && source.trim()) ? source.trim() : 'unknown';
    const visibilityState = (typeof document !== 'undefined' && typeof document.visibilityState === 'string')
        ? document.visibilityState
        : null;
    return {
        schemaVersion: REALTIME_CONNECTION_TELEMETRY_SCHEMA_VERSION,
        generatedAtMs: Date.now(),
        generatedAtIso: new Date().toISOString(),
        eventSource,
        visibilityState,
        documentVisible: isDocumentVisibleForRealtimeConnections(),
        activeChatSessionId: activeChatSessionId || null,
        sharedStreamCount: sharedConversationStreams.size,
        sharedStreamSessionIds: Array.from(sharedConversationStreams.keys()),
        sharedReconnectTrackedCount: sharedConversationReconnectAttempts.size,
        workflowStreamConnected: !!workflowStatusStreamState.eventSource,
        workflowReconnectScheduled: !!workflowStatusStreamState.reconnectTimeoutId,
        incomingInvitePollingActive: !!incomingInvitePollTimerId,
        sharedSessionBadgePollingActive: !!sharedSessionBadgePollTimerId,
    };
}

function publishRealtimeConnectionTelemetry(source = 'unknown') {
    const snapshot = buildRealtimeConnectionTelemetrySnapshot(source);
    try {
        window.__vonRealtimeConnectionTelemetry = snapshot;
    } catch (_) {
        // Ignore non-writable globals in constrained environments.
    }
    try {
        document.dispatchEvent(new CustomEvent('von:realtimeConnectionTelemetryUpdated', { detail: snapshot }));
    } catch (_) {
        // Telemetry dispatch should not block normal flow.
    }
    return snapshot;
}

// Lightweight client-side telemetry for chat session tab loading (elapsed + ETA).
// Stored locally only; intended to feed future introspection.
const LS_CHAT_TABS_LOAD_STATS = 'von:chatSessionTabsLoadStats';
let chatTabsFirstLoadStartPerfMs = null;
let chatTabsFirstLoadStartEpochMs = null;
let chatTabsLoadingTickerId = null;
let chatTabsLoadingTickerLastRenderedSec = -1;
let chatSessionMenuEl = null;
let chatSessionMenuReturnFocusEl = null;
let activeHistoryRequest = null;
let historyRequestCounter = 0;
const HISTORY_SEGMENT_SIZE = 200;
const HISTORY_TAIL_SEGMENT_SIZE = 30;

// JVNAUTOSCI-1014: Hidden conversations (localStorage per user)
const LS_HIDDEN_CHAT_SESSIONS_PREFIX = 'von:hiddenChatSessionIds';
const LS_PINNED_CHAT_SESSIONS_PREFIX = 'von:pinnedChatSessionIds';
const LS_CHAT_SESSION_LAST_ACCESSED_PREFIX = 'von:chatSessionLastAccessed';
const LS_AGENT_CREATED_CHAT_SESSIONS_VISIBLE_PREFIX = 'von:showAgentCreatedChatSessions';
const LS_CHAT_SESSION_TABS_LAYOUT_PREFIX = 'von:chatSessionTabsLayout';
const CHAT_SESSION_TABS_LAYOUT_HORIZONTAL = 'horizontal';
const CHAT_SESSION_TABS_LAYOUT_VERTICAL = 'vertical';
const CHAT_SESSION_TABS_NARROW_MEDIA_QUERY = '(max-width: 800px)';
const CHAT_SESSION_TABS_FETCH_LIMIT = 200;
const AGENT_CREATED_CHAT_SESSION_ORIGIN_KINDS = new Set([
    'browser_test_fixture',
    'benchmark_harness',
    'coding_agent_test',
    'coding_agent',
    'agent_test'
]);
let hiddenChatSessionIds = new Set();
let pinnedChatSessionIds = new Set();
let showHiddenSessions = false;
let showAgentCreatedSessions = false;
let _hiddenSessionsUserKey = null; // Track current user's localStorage key
let _pinnedSessionsUserKey = null; // Track current user's localStorage key
let _agentCreatedSessionsVisibleUserKey = null;
let chatSessionLastAccessedMap = new Map();
let _chatSessionLastAccessedUserKey = null;
let chatSessionTabsLayout = CHAT_SESSION_TABS_LAYOUT_HORIZONTAL;
let chatSessionTabsLayoutMediaQuery = null;
let chatSessionTabsLayoutMediaListenerBound = false;
let agentCreatedSessionVisibilityState = {
    totalCount: 0,
    hiddenCount: 0,
    newestVisibleSessionId: null
};
let serverAgentCreatedSessionVisibilityState = null;
let serverConversationHistoryRecencyState = null;
let expandedConversationHistoryLimit = null;
let expandedConversationHistoryBaseLimit = null;

/**
 * Get the user-scoped localStorage key for hidden sessions.
 * Falls back to global key if no user is logged in.
 */
function buildUserScopedStorageKey(prefix) {
    if (typeof prefix !== 'string' || !prefix.trim()) {
        return prefix;
    }
    const userConceptId = getCurrentUserConceptId();
    if (userConceptId) {
        // Sanitise concept_id to be safe for localStorage key
        const sanitised = String(userConceptId).replace(/[^a-zA-Z0-9_#-]/g, '_');
        return `${prefix}:${sanitised}`;
    }
    return prefix;
}

function getHiddenSessionsStorageKey() {
    return buildUserScopedStorageKey(LS_HIDDEN_CHAT_SESSIONS_PREFIX);
}

function getPinnedSessionsStorageKey() {
    return buildUserScopedStorageKey(LS_PINNED_CHAT_SESSIONS_PREFIX);
}

function getAgentCreatedSessionsVisibleStorageKey() {
    return buildUserScopedStorageKey(LS_AGENT_CREATED_CHAT_SESSIONS_VISIBLE_PREFIX);
}

function getChatSessionTabsLayoutStorageKey() {
    // This controls the browser's navigation chrome rather than user-owned
    // conversation data, so it deliberately survives authentication changes.
    return LS_CHAT_SESSION_TABS_LAYOUT_PREFIX;
}

function normaliseChatSessionTabsLayout(value) {
    return value === CHAT_SESSION_TABS_LAYOUT_VERTICAL
        ? CHAT_SESSION_TABS_LAYOUT_VERTICAL
        : CHAT_SESSION_TABS_LAYOUT_HORIZONTAL;
}

function isChatSessionTabsNarrowViewport() {
    try {
        return typeof window.matchMedia === 'function'
            && window.matchMedia(CHAT_SESSION_TABS_NARROW_MEDIA_QUERY).matches;
    } catch (_) {
        return false;
    }
}

function getEffectiveChatSessionTabsLayout(preferredLayout = chatSessionTabsLayout) {
    const preferred = normaliseChatSessionTabsLayout(preferredLayout);
    if (preferred !== CHAT_SESSION_TABS_LAYOUT_VERTICAL) {
        return CHAT_SESSION_TABS_LAYOUT_HORIZONTAL;
    }
    if (isChatSessionTabsNarrowViewport()) {
        return CHAT_SESSION_TABS_LAYOUT_HORIZONTAL;
    }
    return CHAT_SESSION_TABS_LAYOUT_VERTICAL;
}

function getChatSessionTabsLayoutMenuLabel() {
    if (chatSessionTabsLayout === CHAT_SESSION_TABS_LAYOUT_VERTICAL) {
        return isChatSessionTabsNarrowViewport()
            ? 'Use conversation tabs across top on wider screens'
            : 'Move conversation tabs to top';
    }
    return isChatSessionTabsNarrowViewport()
        ? 'Use conversation tabs on left on wider screens'
        : 'Move conversation tabs to left';
}

function applyChatSessionTabsLayout(layout = chatSessionTabsLayout) {
    const preferred = normaliseChatSessionTabsLayout(layout);
    const effective = getEffectiveChatSessionTabsLayout(preferred);
    chatSessionTabsLayout = preferred;

    const workspace = document.getElementById('conversationWorkspace');
    const chatTab = document.getElementById('chatTab');
    const tabs = getChatSessionTabsContainer();

    if (workspace) {
        workspace.dataset.tabsLayout = preferred;
        workspace.dataset.effectiveTabsLayout = effective;
    }
    if (chatTab) {
        chatTab.dataset.conversationTabsLayout = preferred;
    }
    if (tabs) {
        tabs.setAttribute('aria-orientation', effective === CHAT_SESSION_TABS_LAYOUT_VERTICAL ? 'vertical' : 'horizontal');
    }

    try {
        document.dispatchEvent(new CustomEvent('von:conversation-tabs-layout-changed', {
            detail: { preferred, effective }
        }));
    } catch (_) {
        // Layout still applies in constrained test environments without CustomEvent.
    }

    return { preferred, effective };
}

function loadChatSessionTabsLayoutPreference() {
    const storageKey = getChatSessionTabsLayoutStorageKey();
    let stored = null;
    try {
        stored = localStorage.getItem(storageKey);
    } catch (e) {
        console.warn('[chatTab] Failed to load conversation tab layout from localStorage:', e);
    }
    return applyChatSessionTabsLayout(normaliseChatSessionTabsLayout(stored));
}

function saveChatSessionTabsLayoutPreference() {
    const storageKey = getChatSessionTabsLayoutStorageKey();
    try {
        localStorage.setItem(storageKey, normaliseChatSessionTabsLayout(chatSessionTabsLayout));
    } catch (e) {
        console.warn('[chatTab] Failed to save conversation tab layout to localStorage:', e);
    }
}

function setChatSessionTabsLayout(layout, options = {}) {
    const result = applyChatSessionTabsLayout(layout);
    if (options.persist !== false) {
        saveChatSessionTabsLayoutPreference();
    }
    if (options.announce === true) {
        let message;
        if (result.preferred === CHAT_SESSION_TABS_LAYOUT_VERTICAL
            && result.effective === CHAT_SESSION_TABS_LAYOUT_HORIZONTAL) {
            message = 'Left conversation tabs saved for wider screens.';
        } else if (result.preferred === CHAT_SESSION_TABS_LAYOUT_VERTICAL) {
            message = 'Conversation tabs moved to the left.';
        } else {
            message = 'Conversation tabs set across the top.';
        }
        showToast(message, 'success');
    }
    return result;
}

function toggleChatSessionTabsLayout(options = {}) {
    const next = chatSessionTabsLayout === CHAT_SESSION_TABS_LAYOUT_VERTICAL
        ? CHAT_SESSION_TABS_LAYOUT_HORIZONTAL
        : CHAT_SESSION_TABS_LAYOUT_VERTICAL;
    return setChatSessionTabsLayout(next, options);
}

function setupChatSessionTabsResponsiveLayout() {
    if (chatSessionTabsLayoutMediaListenerBound || typeof window.matchMedia !== 'function') {
        return;
    }
    chatSessionTabsLayoutMediaQuery = window.matchMedia(CHAT_SESSION_TABS_NARROW_MEDIA_QUERY);
    const handleChange = () => {
        applyChatSessionTabsLayout(chatSessionTabsLayout);
    };
    if (typeof chatSessionTabsLayoutMediaQuery.addEventListener === 'function') {
        chatSessionTabsLayoutMediaQuery.addEventListener('change', handleChange);
        chatSessionTabsLayoutMediaListenerBound = true;
    } else if (typeof chatSessionTabsLayoutMediaQuery.addListener === 'function') {
        chatSessionTabsLayoutMediaQuery.addListener(handleChange);
        chatSessionTabsLayoutMediaListenerBound = true;
    }
}

function loadHiddenChatSessionIds() {
    const storageKey = getHiddenSessionsStorageKey();
    _hiddenSessionsUserKey = storageKey;
    try {
        const stored = localStorage.getItem(storageKey);
        if (stored) {
            const parsed = JSON.parse(stored);
            if (Array.isArray(parsed)) {
                hiddenChatSessionIds = new Set(parsed.filter(id => typeof id === 'string'));
                console.log(`[chatTab] Loaded ${hiddenChatSessionIds.size} hidden sessions for key: ${storageKey}`);
                return;
            }
        }
    } catch (e) {
        console.warn('[chatTab] Failed to load hidden session IDs from localStorage:', e);
    }
    hiddenChatSessionIds = new Set();
}

function saveHiddenChatSessionIds() {
    // Use the key we loaded with, or get current key
    const storageKey = _hiddenSessionsUserKey || getHiddenSessionsStorageKey();
    try {
        localStorage.setItem(storageKey, JSON.stringify([...hiddenChatSessionIds]));
    } catch (e) {
        console.warn('[chatTab] Failed to save hidden session IDs to localStorage:', e);
    }
}

function getChatSessionLastAccessedStorageKey() {
    return buildUserScopedStorageKey(LS_CHAT_SESSION_LAST_ACCESSED_PREFIX);
}

function loadPinnedChatSessionIds() {
    const storageKey = getPinnedSessionsStorageKey();
    _pinnedSessionsUserKey = storageKey;
    try {
        const stored = localStorage.getItem(storageKey);
        if (stored) {
            const parsed = JSON.parse(stored);
            if (Array.isArray(parsed)) {
                pinnedChatSessionIds = new Set(parsed.filter(id => typeof id === 'string'));
                return;
            }
        }
    } catch (e) {
        console.warn('[chatTab] Failed to load pinned session IDs from localStorage:', e);
    }
    pinnedChatSessionIds = new Set();
}

function savePinnedChatSessionIds() {
    const storageKey = _pinnedSessionsUserKey || getPinnedSessionsStorageKey();
    try {
        localStorage.setItem(storageKey, JSON.stringify([...pinnedChatSessionIds]));
    } catch (e) {
        console.warn('[chatTab] Failed to save pinned session IDs to localStorage:', e);
    }
}

function reconcileServerConversationPreferences(sessions) {
    let hiddenChanged = false;
    let pinnedChanged = false;
    (Array.isArray(sessions) ? sessions : []).forEach((session) => {
        const sid = (typeof session?.session_id === 'string') ? session.session_id.trim() : '';
        const preference = session?.conversation_preference;
        if (!sid || !preference || preference.preference_present !== true) {
            return;
        }
        const shouldHide = preference.hidden === true;
        const shouldPin = preference.pinned === true;
        if (shouldHide !== hiddenChatSessionIds.has(sid)) {
            hiddenChanged = true;
            if (shouldHide) hiddenChatSessionIds.add(sid); else hiddenChatSessionIds.delete(sid);
        }
        if (shouldPin !== pinnedChatSessionIds.has(sid)) {
            pinnedChanged = true;
            if (shouldPin) pinnedChatSessionIds.add(sid); else pinnedChatSessionIds.delete(sid);
        }
    });
    if (hiddenChanged) saveHiddenChatSessionIds();
    if (pinnedChanged) savePinnedChatSessionIds();
}

async function persistConversationPreferenceAction(sessionId, action) {
    const sid = (typeof sessionId === 'string') ? sessionId.trim() : '';
    if (!sid) return false;
    try {
        const response = await fetch('/von/api/session/conversation_preference', {
            method: 'POST',
            headers: buildChatFetchHeaders({ 'Content-Type': 'application/json' }),
            body: JSON.stringify({ session_id: sid, action })
        });
        const data = await response.json();
        if (!response.ok) {
            throw new Error(data?.error || `Unable to ${action} conversation.`);
        }
        return true;
    } catch (error) {
        console.warn('[chatTab] Conversation preference saved in this browser only:', error);
        showToast('Saved in this browser only; server sync failed.', 'info');
        return false;
    }
}

function loadAgentCreatedSessionsVisibilityPreference() {
    const storageKey = getAgentCreatedSessionsVisibleStorageKey();
    _agentCreatedSessionsVisibleUserKey = storageKey;
    try {
        showAgentCreatedSessions = localStorage.getItem(storageKey) === 'true';
    } catch (e) {
        console.warn('[chatTab] Failed to load agent-created session visibility from localStorage:', e);
        showAgentCreatedSessions = false;
    }
}

function saveAgentCreatedSessionsVisibilityPreference() {
    const storageKey = _agentCreatedSessionsVisibleUserKey || getAgentCreatedSessionsVisibleStorageKey();
    try {
        localStorage.setItem(storageKey, showAgentCreatedSessions ? 'true' : 'false');
    } catch (e) {
        console.warn('[chatTab] Failed to save agent-created session visibility to localStorage:', e);
    }
}

function buildChatSessionTabsFetchUrl() {
    const params = new URLSearchParams();
    const conversationHistorySettings = loadConversationHistorySettings((key) => safeLocalStorageGet(key));
    params.set('limit', String(CHAT_SESSION_TABS_FETCH_LIMIT));
    params.set('summary', 'light');
    params.set('agent_visibility', showAgentCreatedSessions ? 'include' : 'exclude');
    params.set('keep_newest_agent_created', 'true');
    params.set('recent_window_days', String(conversationHistorySettings.recentWindowDays));
    return `/von/history/sessions?${params.toString()}`;
}

function readNonNegativeCount(value) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? Math.max(0, Math.trunc(parsed)) : 0;
}

function normaliseServerAgentCreatedVisibilityState(data) {
    if (!data || data.agent_visibility_applied !== true) {
        return null;
    }
    const newestId = (
        typeof data.newest_visible_agent_created_session_id === 'string'
        && data.newest_visible_agent_created_session_id.trim()
    )
        ? data.newest_visible_agent_created_session_id.trim()
        : null;
    return {
        applied: true,
        visibility: (
            typeof data.agent_visibility === 'string' && data.agent_visibility.trim()
                ? data.agent_visibility.trim()
                : (showAgentCreatedSessions ? 'include' : 'exclude')
        ),
        totalCount: readNonNegativeCount(data.agent_created_session_total),
        hiddenCount: readNonNegativeCount(data.hidden_agent_created_session_count),
        newestVisibleSessionId: newestId,
        totalAfterVisibility: readNonNegativeCount(data.total_after_agent_visibility),
        hiddenByLimitCount: readNonNegativeCount(data.hidden_by_limit_count),
        rawSessionCount: readNonNegativeCount(data.raw_session_count)
    };
}

function normaliseServerConversationHistoryRecencyState(data) {
    const recentWindowDays = Number(data?.recent_window_days);
    const olderThanWindowCount = Number(data?.older_than_window_count);
    if (!Number.isFinite(recentWindowDays) || !Number.isFinite(olderThanWindowCount)) {
        return null;
    }
    return {
        recentWindowDays: Math.max(1, Math.trunc(recentWindowDays)),
        olderThanWindowCount: Math.max(0, Math.trunc(olderThanWindowCount))
    };
}

function loadChatSessionLastAccessedMap() {
    const storageKey = getChatSessionLastAccessedStorageKey();
    _chatSessionLastAccessedUserKey = storageKey;
    try {
        const stored = localStorage.getItem(storageKey);
        if (!stored) {
            chatSessionLastAccessedMap = new Map();
            return;
        }

        const parsed = JSON.parse(stored);
        if (!parsed || typeof parsed !== 'object') {
            chatSessionLastAccessedMap = new Map();
            return;
        }

        const next = new Map();
        Object.entries(parsed).forEach(([sessionId, isoTimestamp]) => {
            if (typeof sessionId !== 'string' || !sessionId.trim()) {
                return;
            }
            if (typeof isoTimestamp !== 'string' || !isoTimestamp.trim()) {
                return;
            }
            if (parseIsoTimestampMs(isoTimestamp) === null) {
                return;
            }
            next.set(sessionId, isoTimestamp);
        });
        chatSessionLastAccessedMap = next;
    } catch (e) {
        console.warn('[chatTab] Failed to load conversation last-accessed map from localStorage:', e);
        chatSessionLastAccessedMap = new Map();
    }
}

function saveChatSessionLastAccessedMap() {
    const storageKey = _chatSessionLastAccessedUserKey || getChatSessionLastAccessedStorageKey();
    try {
        const payload = {};
        chatSessionLastAccessedMap.forEach((isoTimestamp, sessionId) => {
            payload[sessionId] = isoTimestamp;
        });
        localStorage.setItem(storageKey, JSON.stringify(payload));
    } catch (e) {
        console.warn('[chatTab] Failed to save conversation last-accessed map to localStorage:', e);
    }
}

function markConversationSessionAccessed(sessionId) {
    const sid = (typeof sessionId === 'string') ? sessionId.trim() : '';
    if (!sid) {
        return;
    }

    chatSessionLastAccessedMap.set(sid, new Date().toISOString());

    // Keep this cache bounded to avoid unbounded localStorage growth.
    if (chatSessionLastAccessedMap.size > 1000) {
        const ordered = Array.from(chatSessionLastAccessedMap.entries())
            .sort((a, b) => (parseIsoTimestampMs(b[1]) || 0) - (parseIsoTimestampMs(a[1]) || 0));
        chatSessionLastAccessedMap = new Map(ordered.slice(0, 1000));
    }

    saveChatSessionLastAccessedMap();
}

function getConversationHistoryAccessLookup(sessions) {
    const lookup = {};
    if (Array.isArray(sessions)) {
        sessions.forEach((session) => {
            const sid = (typeof session?.session_id === 'string') ? session.session_id.trim() : '';
            if (!sid) {
                return;
            }
            const localIso = chatSessionLastAccessedMap.get(sid);
            if (typeof localIso === 'string' && localIso.trim()) {
                lookup[sid] = localIso;
            }
        });
    }
    return lookup;
}

function normaliseChatSessionOriginKind(value) {
    return (typeof value === 'string' && value.trim())
        ? value.trim().toLowerCase().replace(/[-\s]+/g, '_')
        : '';
}

function isAgentCreatedConversation(session) {
    const originKind = normaliseChatSessionOriginKind(session?.origin_kind);
    return Boolean(
        session?.is_agent_created === true
        || AGENT_CREATED_CHAT_SESSION_ORIGIN_KINDS.has(originKind)
        || (typeof session?.test_artifact_kind === 'string' && session.test_artifact_kind.trim())
    );
}

function getConversationRecencyMs(session) {
    const candidates = [
        session?.recency_timestamp,
        session?.last_message_at,
        session?.updated_at,
        session?.created_at,
        session?.shared_accepted_at
    ];
    for (const candidate of candidates) {
        const parsed = parseIsoTimestampMs(candidate);
        if (parsed !== null) {
            return parsed;
        }
    }
    return 0;
}

function filterAgentCreatedSessionsForDefaultView(sessions) {
    const source = Array.isArray(sessions) ? sessions : [];
    const agentSessions = source.filter(isAgentCreatedConversation);
    if (agentSessions.length === 0) {
        return {
            sessions: source,
            newestVisibleSession: null,
            totalCount: 0,
            hiddenCount: 0
        };
    }

    if (showAgentCreatedSessions) {
        return {
            sessions: source,
            newestVisibleSession: null,
            totalCount: agentSessions.length,
            hiddenCount: 0
        };
    }

    const newestVisibleSession = agentSessions.reduce((best, session) => {
        if (!best) {
            return session;
        }
        const currentMs = getConversationRecencyMs(session);
        const bestMs = getConversationRecencyMs(best);
        return currentMs > bestMs ? session : best;
    }, null);
    const newestVisibleSessionId = (
        typeof newestVisibleSession?.session_id === 'string'
        ? newestVisibleSession.session_id.trim()
        : ''
    );
    const filtered = source.filter((session) => {
        if (!isAgentCreatedConversation(session)) {
            return true;
        }
        const sid = (typeof session?.session_id === 'string') ? session.session_id.trim() : '';
        return sid && sid === newestVisibleSessionId;
    });

    return {
        sessions: filtered,
        newestVisibleSession,
        totalCount: agentSessions.length,
        hiddenCount: Math.max(0, agentSessions.length - (newestVisibleSessionId ? 1 : 0))
    };
}

function hideConversation(sessionId) {
    if (!sessionId) return;
    hiddenChatSessionIds.add(sessionId);
    saveHiddenChatSessionIds();
    // Re-render tabs to apply filter
    if (Array.isArray(sessionTabsCache)) {
        renderChatSessionTabs(sessionTabsCache, activeChatSessionId);
    }
    void persistConversationPreferenceAction(sessionId, 'hide');
}

function unhideConversation(sessionId) {
    if (!sessionId) return;
    hiddenChatSessionIds.delete(sessionId);
    saveHiddenChatSessionIds();
    // Re-render tabs to update styling
    if (Array.isArray(sessionTabsCache)) {
        renderChatSessionTabs(sessionTabsCache, activeChatSessionId);
    }
    void persistConversationPreferenceAction(sessionId, 'unhide');
}

function isConversationHidden(sessionId) {
    return hiddenChatSessionIds.has(sessionId);
}

function isConversationPinned(sessionId) {
    return pinnedChatSessionIds.has(sessionId);
}

function pinConversation(sessionId) {
    if (!sessionId) return;
    pinnedChatSessionIds.add(sessionId);
    savePinnedChatSessionIds();
    if (Array.isArray(sessionTabsCache)) {
        renderChatSessionTabs(sessionTabsCache, activeChatSessionId);
    }
    void persistConversationPreferenceAction(sessionId, 'pin');
}

function unpinConversation(sessionId) {
    if (!sessionId) return;
    pinnedChatSessionIds.delete(sessionId);
    savePinnedChatSessionIds();
    if (Array.isArray(sessionTabsCache)) {
        renderChatSessionTabs(sessionTabsCache, activeChatSessionId);
    }
    void persistConversationPreferenceAction(sessionId, 'unpin');
}

function toggleConversationPinned(sessionId) {
    if (!sessionId) return;
    if (isConversationPinned(sessionId)) {
        unpinConversation(sessionId);
        return;
    }
    pinConversation(sessionId);
}

function buildConversationReferencePayload(session) {
    const orgContext = getSessionScopedOrgContext();
    return buildSharedConversationReferencePayload(session, {
        currentUserConceptId: getCurrentUserConceptId() || null,
        namespace: getSessionScopedNamespace() || null,
        organisationConceptId: (
            typeof orgContext?.concept_id === 'string' && orgContext.concept_id.trim()
                ? orgContext.concept_id.trim()
                : (typeof orgContext?.id === 'string' && orgContext.id.trim() ? orgContext.id.trim() : null)
        ),
    });
}

async function copyConversationReferenceToClipboard(session) {
    const payload = buildConversationReferencePayload(session);
    if (!payload) {
        showToast('No conversation ID is available.', 'info');
        return false;
    }
    let text;
    try {
        text = JSON.stringify(payload, null, 2);
    } catch (err) {
        console.error('[chatTab] Failed to serialize conversation reference:', err);
        showToast('Failed to prepare conversation reference.', 'error');
        return false;
    }
    const copied = await copyTextToClipboard(text);
    showToast(
        copied ? 'Copied conversation reference.' : 'Failed to copy conversation reference.',
        copied ? 'success' : 'error'
    );
    return copied;
}

function rememberConceptQaSession(value, defaults = {}) {
    const projection = normaliseConceptQaSession(value, defaults);
    if (!projection) return null;
    conceptQaSessionsByChatSession.set(projection.chat_session_id, projection);
    if (projection.session_id !== projection.chat_session_id) {
        conceptQaSessionsByChatSession.set(projection.session_id, projection);
    }
    return projection;
}

function getConceptQaSessionForChat(sessionId = activeChatSessionId) {
    const sid = normaliseHistorySessionId(sessionId);
    if (!sid) return null;
    const remembered = conceptQaSessionsByChatSession.get(sid);
    if (remembered) return remembered;
    const session = sessionTabsCache.find((row) => normaliseHistorySessionId(row?.session_id) === sid);
    if (!isConceptQaSession(session)) return null;
    const focalConceptId = Array.isArray(session?.focal_concept_ids)
        ? session.focal_concept_ids.find((value) => typeof value === 'string' && value.trim())
        : null;
    return rememberConceptQaSession(session, { conceptId: focalConceptId, sessionId: sid });
}

function conceptQaReceiptsChangedKnowledge(value) {
    const receipts = normaliseConceptQaReceipts(value);
    const exactStatus = String(receipts.exact_input?.status || '').toLowerCase();
    const formalisationStatus = String(receipts.formalisation?.status || '').toLowerCase();
    const notesStatus = String(receipts.notes?.status || '').toLowerCase();
    return ['stored', 'asserted', 'succeeded', 'success'].includes(exactStatus)
        || ['candidate', 'proposed', 'tentative', 'uncertain', 'stored', 'asserted', 'succeeded', 'success'].includes(formalisationStatus)
        || ['updated', 'stored', 'succeeded', 'success'].includes(notesStatus);
}

function dispatchConceptQaKnowledgeChange(session, receipts, reason = 'concept_q_and_a_turn') {
    if (!session?.concept_id || !conceptQaReceiptsChangedKnowledge(receipts)) return;
    document.dispatchEvent(new CustomEvent('von:conceptKnowledgeChanged', {
        detail: {
            conceptId: session.concept_id,
            sessionId: session.session_id,
            reason,
            receipts: normaliseConceptQaReceipts(receipts),
        },
    }));
    document.dispatchEvent(new CustomEvent('concept-updated', {
        detail: {
            conceptId: session.concept_id,
            reason,
            source: 'concept_q_and_a',
        },
    }));
}

function getConceptQaConfirmationUiState(
    receipt = null,
    session = getConceptQaSessionForChat(),
) {
    if (!session) {
        return {
            available: false,
            label: 'Confirmation unavailable',
            reason: 'Open the concept Q&A conversation that recorded this tentative relation.',
        };
    }
    if (session.lifecycle === 'cancelled') {
        return {
            available: false,
            label: 'Unavailable — Q&A cancelled',
            reason: 'This concept Q&A was cancelled, so this receipt can no longer confirm the tentative relation.',
        };
    }
    if (
        session.lifecycle === 'finished'
        && receipt?.confirmation?.available_after_finish !== true
    ) {
        return {
            available: false,
            label: 'Unavailable — Q&A finished',
            reason: 'This finished Q&A receipt does not permit post-finish confirmation.',
        };
    }
    if (!['active', 'finished'].includes(session.lifecycle)) {
        return {
            available: false,
            label: `Unavailable — Q&A ${session.lifecycle}`,
            reason: `This concept Q&A is ${session.lifecycle}; confirmation is not available in this lifecycle state.`,
        };
    }
    if (conceptQaTransitionInFlight.has(session.session_id)) {
        return {
            available: false,
            label: 'Confirmation unavailable',
            reason: 'Wait for the current Q&A confirmation or lifecycle change to finish.',
        };
    }
    return { available: true };
}

function updateVisibleConceptQaConfirmationUi(session = getConceptQaSessionForChat()) {
    const scrollableField = document.getElementById('scrollableField');
    if (!scrollableField) return;
    updateConceptQaReceiptConfirmationState(
        scrollableField,
        (receipt) => getConceptQaConfirmationUiState(receipt, session),
    );
}

function updateConceptQaComposerUi() {
    const session = getConceptQaSessionForChat();
    const promptInput = getPromptInputElement();
    if (!promptInput) return;
    if (!promptInput.dataset.nativePlaceholder) {
        promptInput.dataset.nativePlaceholder = promptInput.getAttribute('placeholder') || 'Talk with Von here...';
    }
    if (!session) {
        if (!isExternalConversationReadOnly()) {
            promptInput.disabled = false;
            promptInput.setAttribute('placeholder', promptInput.dataset.nativePlaceholder);
        }
        return;
    }
    const busy = conceptQaSubmitInFlight.has(session.session_id)
        || conceptQaTransitionInFlight.has(session.session_id);
    const terminal = session.lifecycle !== 'active';
    const awaitingInitialQuestion = session.lifecycle === 'active'
        && !conceptQaActionAllowed(session, 'submit_turn');
    const readOnly = isExternalConversationReadOnly();
    promptInput.disabled = readOnly || terminal || awaitingInitialQuestion || busy;
    promptInput.setAttribute(
        'placeholder',
        readOnly
            ? 'Imported snapshot — choose Continue to add new turns.'
            : terminal
            ? `Concept Q&A ${session.lifecycle}; the transcript remains available.`
            : awaitingInitialQuestion
            ? 'Retry the initial question from the concept card before answering.'
            : (busy ? 'Saving this Q&A turn…' : 'Answer the current concept question…'),
    );
}

function renderConceptQaConversationControls() {
    const mount = document.getElementById('conceptQaConversationControls');
    if (!mount) return;
    const session = getConceptQaSessionForChat();
    if (!session) {
        mount.replaceChildren();
        mount.classList.add('hidden');
        updateVisibleConceptQaConfirmationUi(null);
        updateConceptQaComposerUi();
        return;
    }

    mount.classList.remove('hidden');
    mount.replaceChildren();
    const header = document.createElement('div');
    header.className = 'concept-qa-conversation-header';
    const title = document.createElement('strong');
    title.textContent = 'Concept Q&A';
    const status = document.createElement('span');
    status.className = 'concept-qa-conversation-status';
    const awaitingInitialQuestion = session.lifecycle === 'active'
        && !conceptQaActionAllowed(session, 'submit_turn');
    status.textContent = session.lifecycle === 'active' && awaitingInitialQuestion
        ? 'Needs retry · return to the concept card to generate the initial question.'
        : session.lifecycle === 'active'
        ? 'Active · answers and representation outcomes are saved in this conversation.'
        : `${session.lifecycle === 'finished' ? 'Finished' : 'Cancelled'} · transcript and prior knowledge are retained.`;
    header.append(title, status);
    mount.appendChild(header);

    const gapText = describeConceptQaElicitationGap(session);
    if (gapText) {
        const gap = document.createElement('p');
        gap.className = 'concept-qa-conversation-gap';
        gap.textContent = gapText;
        mount.appendChild(gap);
    }

    const actions = document.createElement('div');
    actions.className = 'concept-qa-conversation-actions';
    const busy = conceptQaTransitionInFlight.has(session.session_id);

    const copy = document.createElement('button');
    copy.type = 'button';
    copy.className = 'btn-mini';
    copy.textContent = 'Copy reference';
    copy.disabled = busy;
    copy.addEventListener('click', () => void copyConversationReferenceToClipboard(session));
    actions.appendChild(copy);

    if (session.lifecycle === 'active') {
        const finish = document.createElement('button');
        finish.type = 'button';
        finish.className = 'btn-mini concept-qa-finish';
        finish.textContent = busy ? 'Saving…' : 'Finish Q&A';
        finish.disabled = busy || !conceptQaActionAllowed(session, 'finish');
        finish.addEventListener('click', () => void transitionActiveConceptQa('finish'));

        const cancel = document.createElement('button');
        cancel.type = 'button';
        cancel.className = 'btn-mini concept-qa-cancel';
        cancel.textContent = 'Cancel Q&A';
        cancel.title = 'Stop future Q&A turns. The transcript and already recorded knowledge are retained.';
        cancel.disabled = busy || !conceptQaActionAllowed(session, 'cancel');
        cancel.addEventListener('click', () => void transitionActiveConceptQa('cancel'));
        actions.append(finish, cancel);
    }
    mount.appendChild(actions);
    const errorText = conceptQaErrorBySession.get(session.session_id);
    if (errorText) {
        const message = document.createElement('p');
        message.className = 'concept-qa-conversation-error';
        message.textContent = errorText;
        mount.appendChild(message);
    }
    updateVisibleConceptQaConfirmationUi(session);
    updateConceptQaComposerUi();
    updateSendButtonForCurrentChatState();
}

async function transitionActiveConceptQa(action) {
    const current = getConceptQaSessionForChat();
    if (!current?.concept_id || !current?.session_id) return false;
    const key = current.session_id;
    if (conceptQaTransitionInFlight.has(key)) return false;
    conceptQaTransitionInFlight.add(key);
    conceptQaErrorBySession.delete(key);
    renderConceptQaConversationControls();
    try {
        const updated = await transitionConceptQaSession({
            conceptId: current.concept_id,
            sessionId: current.session_id,
            action,
        });
        rememberConceptQaSession(updated);
        const cacheIndex = sessionTabsCache.findIndex((row) => row?.session_id === current.chat_session_id);
        if (cacheIndex >= 0) {
            sessionTabsCache[cacheIndex] = normaliseConversationSessionViewModel({
                ...sessionTabsCache[cacheIndex],
                ...updated,
                is_completed: updated.lifecycle !== 'active',
            });
        }
        showToast(
            action === 'finish'
                ? 'Concept Q&A finished. Its transcript is retained.'
                : 'Concept Q&A cancelled. Its transcript and prior knowledge are retained.',
            'success',
        );
        document.dispatchEvent(new CustomEvent('von:conceptQaLifecycleChanged', {
            detail: { conceptId: updated.concept_id, session: updated },
        }));
        scheduleChatSessionTabsRefresh(true);
        return true;
    } catch (error) {
        conceptQaErrorBySession.set(
            key,
            error?.status === 409
                ? 'This Q&A changed elsewhere. Reload the conversation status and try again.'
                : (error?.message || 'The Q&A state could not be changed. Try again.'),
        );
        return false;
    } finally {
        conceptQaTransitionInFlight.delete(key);
        renderConceptQaConversationControls();
    }
}

function renderConceptQaTurns(session) {
    const turns = Array.isArray(session?.turns) ? session.turns : [];
    const scrollableField = document.getElementById('scrollableField');
    if (!turns.length || !scrollableField) return false;
    historySegmentsShown = 1;
    totalHistorySegments = 1;
    rehydrateHistory(scrollableField, turns, {
        scrollToBottom: true,
        preserveScroll: false,
        showResetNotice: false,
        forceScrollToBottom: true,
    });
    displayedHistorySessionId = session.chat_session_id;
    return true;
}

export async function openConceptQaConversation(value) {
    const session = rememberConceptQaSession(value);
    if (!session) return { ok: false, error: 'Concept Q&A session is missing.' };
    const existing = sessionTabsCache.find((row) => row?.session_id === session.chat_session_id);
    const viewModel = normaliseConversationSessionViewModel({
        ...existing,
        ...session,
        session_id: session.chat_session_id,
        session_name: session.session_name || existing?.session_name || 'Concept Q&A',
        focal_concept_ids: session.concept_id ? [session.concept_id] : existing?.focal_concept_ids,
        is_completed: session.lifecycle !== 'active',
    });
    sessionTabsCache = normaliseConversationSessionViewModels([
        viewModel,
        ...sessionTabsCache.filter((row) => row?.session_id !== session.chat_session_id),
    ]);
    activateTab('chatTab');
    const switched = await switchToChatSession(session.chat_session_id);
    if (!switched?.ok && !renderConceptQaTurns(session)) return switched;
    setActiveChatSession(session.chat_session_id, viewModel?.session_name || 'Concept Q&A');
    if (session.turns.length) renderConceptQaTurns(session);
    renderChatSessionTabs(sessionTabsCache, session.chat_session_id);
    renderConceptQaConversationControls();
    return { ok: true, session };
}

async function submitActiveConceptQaPrompt({ session, promptInput, promptRaw }) {
    if (!session?.concept_id || !session?.session_id) return false;
    if (session.lifecycle !== 'active') {
        showToast(`This concept Q&A is ${session.lifecycle}; its transcript remains available.`, 'info');
        renderConceptQaConversationControls();
        return false;
    }
    if (!conceptQaActionAllowed(session, 'submit_turn')) {
        showToast('Retry the initial concept question before submitting an answer.', 'info');
        renderConceptQaConversationControls();
        return false;
    }
    const key = session.session_id;
    if (conceptQaSubmitInFlight.has(key)) return false;
    conceptQaSubmitInFlight.add(key);
    conceptQaErrorBySession.delete(key);
    renderConceptQaConversationControls();
    try {
        const result = await submitConceptQaTurn({
            conceptId: session.concept_id,
            sessionId: session.session_id,
            answer: promptRaw,
        });
        const updated = rememberConceptQaSession(result.session);
        if (!updated) throw new Error('The Q&A response did not include session read-back.');
        rememberLastSubmittedUserPrompt(promptRaw);
        setPromptComposerValue('', { promptInput });
        invalidateSessionHistoryCache(updated.chat_session_id);
        if (!renderConceptQaTurns(updated)) {
            await loadChatHistory({
                segments: Math.max(historySegmentsShown, 1),
                scrollToBottom: true,
                preserveScroll: false,
                showResetNotice: false,
                forceScrollToBottom: true,
            });
        }
        dispatchConceptQaKnowledgeChange(updated, result.receipts);
        if (updated.lifecycle !== 'active') scheduleChatSessionTabsRefresh(true);
        return true;
    } catch (error) {
        const readBack = normaliseConceptQaSession(error?.payload, {
            conceptId: session.concept_id,
            sessionId: session.session_id,
        });
        if (error?.status === 409 && readBack) rememberConceptQaSession(readBack);
        conceptQaErrorBySession.set(
            key,
            error?.status === 409
                ? 'This Q&A is no longer active. Its current state and transcript have been retained.'
                : (error?.message || 'This Q&A turn could not be saved. Your draft remains in the composer.'),
        );
        return false;
    } finally {
        conceptQaSubmitInFlight.delete(key);
        renderConceptQaConversationControls();
    }
}

function conceptQaConfirmationDenialText({
    denial = {},
    requiredConfirmer = '',
    reason = '',
    reconciliationRequired = false,
} = {}) {
    const sentence = (value) => {
        const text = String(value || '').trim();
        if (!text) return '';
        return /[.!?]$/.test(text) ? text : `${text}.`;
    };
    const whoCanAddMembership = String(denial?.who_can_add_membership || '').trim();
    const membershipManagementPath = String(denial?.membership_management_path || '').trim();
    const originalActorNextStep = String(denial?.original_actor_next_step || '').trim();
    const genericConfirmer = String(
        denial?.who_can_confirm
        || denial?.required_confirmer
        || requiredConfirmer
        || '',
    ).trim();
    const permissions = Array.isArray(denial?.required_permissions)
        ? denial.required_permissions.filter(Boolean).join(', ')
        : '';
    const membershipHandoff = whoCanAddMembership
        ? sentence([
            'Membership handoff:',
            whoCanAddMembership,
            membershipManagementPath ? `must add the membership through ${membershipManagementPath}` : '',
        ].filter(Boolean).join(' '))
        : (membershipManagementPath
            ? sentence(`Use ${membershipManagementPath} to add the membership`)
            : '');

    return [
        'The tentative relation was retained.',
        reconciliationRequired
            ? 'A governed activation may have completed and needs reconciliation.'
            : '',
        membershipHandoff,
        denial?.same_q_and_a_action_available_to_other_actor === false
            ? 'The authorised membership manager cannot use this actor-scoped Q&A Confirm action on behalf of the original actor.'
            : '',
        originalActorNextStep
            ? `Next step for the original Q&A actor: ${sentence(originalActorNextStep)}`
            : '',
        !whoCanAddMembership && genericConfirmer
            ? sentence(`Confirmation requires ${genericConfirmer}`)
            : '',
        permissions ? sentence(`Required permission: ${permissions}`) : '',
        reason
            ? sentence(`Reason: ${reason}`)
            : 'Confirmation did not complete; try again.',
    ].filter(Boolean).join(' ');
}

async function confirmActiveConceptQaFormalisation(receipt) {
    const session = getConceptQaSessionForChat();
    const assertionId = typeof receipt?.assertion_id === 'string' ? receipt.assertion_id.trim() : '';
    if (!session?.concept_id || !session?.session_id || !assertionId) return false;
    const key = session.session_id;
    if (receipt?.confirmation?.available !== true) {
        conceptQaErrorBySession.set(
            key,
            'This receipt no longer offers confirmation; reload the conversation for current status.',
        );
        renderConceptQaConversationControls();
        return false;
    }
    const confirmationState = getConceptQaConfirmationUiState(receipt, session);
    if (!confirmationState.available) {
        conceptQaErrorBySession.set(
            key,
            `${confirmationState.reason} The tentative relation was not changed.`,
        );
        renderConceptQaConversationControls();
        return false;
    }
    if (conceptQaTransitionInFlight.has(key)) return false;
    conceptQaTransitionInFlight.add(key);
    conceptQaErrorBySession.delete(key);
    renderConceptQaConversationControls();
    try {
        const result = await confirmConceptQaFormalisation({
            conceptId: session.concept_id,
            sessionId: session.session_id,
            assertionId,
            confirmation: receipt.confirmation,
        });
        const updated = rememberConceptQaSession(result.session);
        if (updated?.turns?.length) {
            renderConceptQaTurns(updated);
        } else {
            invalidateSessionHistoryCache(session.chat_session_id);
            await loadChatHistory({
                segments: Math.max(historySegmentsShown, 1),
                scrollToBottom: false,
                preserveScroll: true,
                showResetNotice: false,
            });
        }
        const formalisation = result.receipts?.formalisation;
        const formalisationStatus = String(formalisation?.status || '').toLowerCase();
        const confirmationOutcome = result.payload?.confirmation;
        const canonicalReadBack = confirmationOutcome?.canonical_read_back
            ?? formalisation?.confirmation?.last_attempt?.canonical_read_back
            ?? formalisation?.canonical_read_back
            ?? formalisation?.read_back;
        const readBackStatus = String(
            canonicalReadBack?.epistemic_status || canonicalReadBack?.status || '',
        ).toLowerCase();
        const confirmed = result.payload?.success !== false
            && ['asserted', 'succeeded', 'success'].includes(formalisationStatus)
            && (canonicalReadBack === true
                || canonicalReadBack?.verified === true
                || ['asserted', 'verified', 'succeeded'].includes(readBackStatus));
        if (!confirmed) {
            const denial = formalisation?.actionable_denial
                || result.payload?.actionable_denial
                || result.payload?.confirmation?.actionable_denial
                || {};
            const reason = formalisation?.error_code
                || result.payload?.error_code
                || result.payload?.reason;
            conceptQaErrorBySession.set(
                key,
                conceptQaConfirmationDenialText({ denial, reason }),
            );
            return false;
        }
        dispatchConceptQaKnowledgeChange(
            updated || session,
            result.receipts,
            'concept_q_and_a_formalisation_confirmed',
        );
        showToast('Tentative relation confirmed and read back.', 'success');
        return true;
    } catch (error) {
        const readBack = normaliseConceptQaSession(error?.payload, {
            conceptId: session.concept_id,
            sessionId: session.session_id,
        });
        if (readBack) {
            rememberConceptQaSession(readBack);
            if (readBack.turns?.length) renderConceptQaTurns(readBack);
        }
        const confirmation = error?.payload?.confirmation;
        const denial = confirmation?.actionable_denial
            || error?.payload?.actionable_denial
            || {};
        const requiredConfirmer = denial.who_can_confirm
            || denial.required_confirmer
            || error?.payload?.required_confirmer
            || confirmation?.required_confirmer;
        const detail = confirmation?.error_code
            || error?.payload?.error_code
            || error?.payload?.reason
            || error?.payload?.detail
            || error?.message;
        conceptQaErrorBySession.set(
            key,
            conceptQaConfirmationDenialText({
                denial,
                requiredConfirmer,
                reason: detail,
                reconciliationRequired: confirmation?.reconciliation_required === true,
            }),
        );
        return false;
    } finally {
        conceptQaTransitionInFlight.delete(key);
        renderConceptQaConversationControls();
    }
}

function toggleShowHiddenSessions() {
    showHiddenSessions = !showHiddenSessions;
    // Re-render tabs to show/hide hidden conversations
    if (Array.isArray(sessionTabsCache)) {
        renderChatSessionTabs(sessionTabsCache, activeChatSessionId);
    }
}

function toggleShowAgentCreatedSessions() {
    showAgentCreatedSessions = !showAgentCreatedSessions;
    saveAgentCreatedSessionsVisibilityPreference();
    serverAgentCreatedSessionVisibilityState = null;
    scheduleChatSessionTabsRefresh(true);
}

async function deleteConversation(sessionId) {
    if (!sessionId) return;
    try {
        const resp = await fetch('/von/api/session/delete_chat_session', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                ...buildChatFetchHeaders()
            },
            body: JSON.stringify({ session_id: sessionId })
        });
        let data = null;
        try {
            data = await resp.json();
        } catch (_) {
            // Preserve the HTTP failure below when a proxy or route returns HTML.
        }
        if (!resp.ok) {
            const errorMsg = data?.error
                || `Failed to move conversation to Trash (HTTP ${resp.status || 'unknown'})`;
            showToast(errorMsg, 'error');
            return false;
        }
        if (data?.status !== 'trashed' || data?.trashed !== true || data?.recoverable !== true) {
            showToast(
                data?.error || 'Moving the conversation to Trash could not be verified',
                'error'
            );
            return false;
        }
        // Remove from cache and re-render
        sessionTabsCache = normaliseConversationSessionViewModels(
            sessionTabsCache.filter(s => s?.session_id !== sessionId)
        );
        // Also remove from hidden set if present
        hiddenChatSessionIds.delete(sessionId);
        pinnedChatSessionIds.delete(sessionId);
        saveHiddenChatSessionIds();
        savePinnedChatSessionIds();
        // If deleted the active session, switch to first available or null
        if (activeChatSessionId === sessionId) {
            const nextSession = sessionTabsCache.find(s => s?.session_id);
            if (nextSession) {
                await switchToChatSession(nextSession.session_id);
            } else {
                setActiveChatSession(null, null);
            }
        }
        renderChatSessionTabs(sessionTabsCache, activeChatSessionId);
        showToast('Conversation moved to Trash', 'success');
        document.dispatchEvent(new CustomEvent('von:conversation-trash-changed', {
            detail: { action: 'trashed', sessionId }
        }));
        return true;
    } catch (e) {
        console.error('[chatTab] moveConversationToTrash error:', e);
        showToast('Failed to move conversation to Trash', 'error');
        return false;
    }
}

async function openConversationSearchResult(row) {
    const sessionId = String(row?.session_id || row?.id || '').trim();
    if (!sessionId) return { ok: false, error: 'session_id required' };
    const existing = sessionTabsCache.find(session => session?.session_id === sessionId) || {};
    const canonical = normaliseConversationSessionViewModel({ ...existing, ...row, session_id: sessionId });
    sessionTabsCache = normaliseConversationSessionViewModels([
        ...sessionTabsCache.filter(session => session?.session_id !== sessionId),
        canonical
    ]);
    activateTab('chatTab');
    if (activeChatSessionId === sessionId) {
        renderChatSessionTabs(sessionTabsCache, sessionId);
        return { ok: true, alreadyActive: true };
    }
    return switchToChatSession(sessionId);
}

