function isPlainObject(value) {
    return !!value && typeof value === 'object' && !Array.isArray(value);
}

function cloneThinkingCriticObject(value) {
    if (!isPlainObject(value)) {
        return null;
    }
    try {
        return JSON.parse(JSON.stringify(value));
    } catch (_) {
        return { ...value };
    }
}

function normaliseThinkingCriticText(value, maxChars = 320) {
    const text = normaliseThinkingActivityString(value);
    return text ? truncateThinkingCardSummary(text, maxChars) : '';
}

function normaliseThinkingCriticTextList(value, maxItems = 8) {
    const values = [];
    const append = (candidate) => {
        const text = normaliseThinkingCriticText(candidate, 420);
        if (text && !values.includes(text)) {
            values.push(text);
        }
    };

    if (Array.isArray(value)) {
        value.forEach((item) => {
            if (isPlainObject(item)) {
                append(formatThinkingCriticObjectSummary(item));
            } else {
                append(item);
            }
        });
    } else if (isPlainObject(value)) {
        append(formatThinkingCriticObjectSummary(value));
    } else {
        append(value);
    }

    return values.slice(0, maxItems);
}

function collectThinkingCriticStringValues(target, value, maxItems = 12) {
    if (!Array.isArray(target) || target.length >= maxItems) {
        return;
    }
    if (Array.isArray(value)) {
        value.forEach((item) => collectThinkingCriticStringValues(target, item, maxItems));
        return;
    }
    const text = normaliseThinkingCriticText(value, 160);
    if (text && !target.includes(text)) {
        target.push(text);
    }
}

function formatThinkingCriticObjectSummary(value) {
    if (!isPlainObject(value)) {
        return normaliseThinkingCriticText(value);
    }
    const priorityKeys = [
        'failure_code',
        'status',
        'status_reason',
        'decision_reason',
        'blocker_source',
        'reason',
        'detail',
        'description',
        'message',
        'evidence_note',
        'summary'
    ];
    const bits = [];
    priorityKeys.forEach((key) => {
        const text = normaliseThinkingCriticText(value[key], key === 'summary' ? 260 : 160);
        if (text && !bits.includes(text)) {
            bits.push(text);
        }
    });
    if (bits.length === 0) {
        Object.entries(value).slice(0, 4).forEach(([key, item]) => {
            if (Array.isArray(item) || isPlainObject(item)) {
                return;
            }
            const text = normaliseThinkingCriticText(item, 140);
            if (text) {
                bits.push(`${key}: ${text}`);
            }
        });
    }
    return bits.join(' · ');
}

function collectThinkingCriticBlockerObjects(criticOutput) {
    const blockers = [];
    const append = (candidate) => {
        if (Array.isArray(candidate)) {
            candidate.forEach(append);
            return;
        }
        if (!isPlainObject(candidate)) {
            const text = normaliseThinkingCriticText(candidate, 420);
            if (text && !blockers.includes(text)) {
                blockers.push(text);
            }
            return;
        }
        const text = formatThinkingCriticObjectSummary(candidate);
        if (text && !blockers.includes(text)) {
            blockers.push(text);
        }
    };

    append(criticOutput.blockers);
    append(criticOutput.blocking_failures);
    append(criticOutput.answer_consistency_blocker);
    append(criticOutput.required_evidence_answer_consistency_blocker);
    append(criticOutput.evidence_payload?.answer_consistency_blocker);
    append(criticOutput.completion_gate?.blocking_blockers);
    append(criticOutput.summary?.blockers);
    return blockers.slice(0, 8);
}

function hasMeaningfulThinkingCriticOutput(value) {
    if (!isPlainObject(value)) {
        return false;
    }
    const meaningfulKeys = [
        'verdict',
        'assessment_summary',
        'assessment',
        'summary',
        'recommendations',
        'blockers',
        'blocking_failures',
        'required_evidence_answer_consistency_blocker',
        'failure_code',
        'failure_codes',
        'blocking_failure_codes',
        'has_unresolved_checks',
        'unresolved_check_count',
        'evidence_payload',
        'completion_gate'
    ];
    return meaningfulKeys.some((key) => {
        const candidate = value[key];
        if (candidate === undefined || candidate === null) {
            return false;
        }
        if (typeof candidate === 'boolean') {
            return true;
        }
        if (typeof candidate === 'number') {
            return Number.isFinite(candidate);
        }
        if (typeof candidate === 'string') {
            return candidate.trim().length > 0;
        }
        if (Array.isArray(candidate)) {
            return candidate.length > 0;
        }
        return isPlainObject(candidate) && Object.keys(candidate).length > 0;
    });
}

function extractThinkingCriticOutput(source) {
    if (!source || typeof source !== 'object') {
        return null;
    }
    const candidates = [
        source.criticOutput,
        source.critic_verdict,
        source.critic?.verdict,
        source.turnExecutionDiagnostics?.critic_verdict,
        source.turnExecutionDiagnostics?.critic?.verdict,
        source.turn_execution_diagnostics?.critic_verdict,
        source.turn_execution_diagnostics?.critic?.verdict,
        source.latestProgress?.critic_verdict,
        source.latestProgress?.turn_execution_diagnostics?.critic_verdict
    ];
    for (const candidate of candidates) {
        const cloned = cloneThinkingCriticObject(candidate);
        if (hasMeaningfulThinkingCriticOutput(cloned)) {
            return cloned;
        }
    }
    return null;
}

function syncThinkingCriticOutputFromSource(request, source) {
    if (!request || typeof request !== 'object') {
        return null;
    }
    const criticOutput = extractThinkingCriticOutput(source);
    if (criticOutput) {
        request.criticOutput = criticOutput;
    }
    return criticOutput;
}

function ensureThinkingCriticPanelId(request) {
    if (request && typeof request === 'object' && request.thinkingCriticPanelId) {
        return request.thinkingCriticPanelId;
    }
    const raw = normaliseThinkingActivityString(
        request?.resultTurnId || request?.clientRequestId || request?.latestProgress?.request_id
    );
    const suffix = raw.replace(/[^a-zA-Z0-9_-]+/g, '-') || 'active';
    const panelId = `thinkingCriticPanel-${suffix}`;
    if (request && typeof request === 'object') {
        request.thinkingCriticPanelId = panelId;
    }
    return panelId;
}

function buildThinkingCriticViewModel(request) {
    const criticOutput = extractThinkingCriticOutput(request);
    if (!criticOutput) {
        return null;
    }

    const failureCodes = [];
    collectThinkingCriticStringValues(failureCodes, criticOutput.failure_code);
    collectThinkingCriticStringValues(failureCodes, criticOutput.failure_codes);
    collectThinkingCriticStringValues(failureCodes, criticOutput.blocking_failure_codes);
    collectThinkingCriticStringValues(
        failureCodes,
        criticOutput.evidence_payload?.answer_consistency_blocker?.failure_code
    );
    collectThinkingCriticStringValues(
        failureCodes,
        criticOutput.evidence_payload?.answer_consistency_blocker?.failure_codes
    );
    collectThinkingCriticStringValues(
        failureCodes,
        criticOutput.required_evidence_answer_consistency_blocker?.failure_code
    );
    collectThinkingCriticStringValues(
        failureCodes,
        criticOutput.required_evidence_answer_consistency_blocker?.failure_codes
    );
    collectThinkingCriticStringValues(failureCodes, criticOutput.completion_gate?.blocking_failure_codes);
    collectThinkingCriticStringValues(failureCodes, criticOutput.summary?.failure_codes);

    const recommendations = [
        ...normaliseThinkingCriticTextList(criticOutput.recommendations, 8),
        ...normaliseThinkingCriticTextList(criticOutput.summary?.recommendations, 8)
    ].filter((value, index, array) => value && array.indexOf(value) === index).slice(0, 8);

    const blockers = collectThinkingCriticBlockerObjects(criticOutput);
    const unresolvedBits = [];
    if (criticOutput.has_unresolved_checks !== undefined) {
        unresolvedBits.push(`unresolved checks: ${criticOutput.has_unresolved_checks ? 'yes' : 'no'}`);
    }
    if (criticOutput.unresolved_check_count !== undefined && criticOutput.unresolved_check_count !== null) {
        unresolvedBits.push(`count: ${normaliseThinkingCriticText(criticOutput.unresolved_check_count, 40)}`);
    }

    return {
        panelId: ensureThinkingCriticPanelId(request),
        verdict: normaliseThinkingCriticText(criticOutput.verdict || criticOutput.summary?.verdict, 120),
        assessmentSummary: normaliseThinkingCriticText(
            criticOutput.assessment_summary
            || criticOutput.assessment
            || criticOutput.summary?.assessment_summary,
            720
        ),
        recommendations,
        blockers,
        failureCodes,
        unresolvedSummary: unresolvedBits.join(' · '),
        source: normaliseThinkingCriticText(criticOutput.source, 180),
        raw: criticOutput
    };
}

function renderThinkingCriticListHTML(items) {
    if (!Array.isArray(items) || items.length === 0) {
        return '';
    }
    return `<ul class="thinking-card-diagnostic-list">${items
        .map((item) => `<li>${escapeHtml(item)}</li>`)
        .join('')}</ul>`;
}

function renderThinkingCriticPanelHTML(request) {
    if (!request || request.thinkingCriticPanelOpen !== true) {
        return '';
    }
    const viewModel = buildThinkingCriticViewModel(request);
    if (!viewModel) {
        return '';
    }
    const facts = [];
    if (viewModel.verdict) {
        facts.push(`<div class="thinking-card-diagnostic-fact"><dt>Verdict</dt><dd>${escapeHtml(viewModel.verdict)}</dd></div>`);
    }
    if (viewModel.assessmentSummary) {
        facts.push(`<div class="thinking-card-diagnostic-fact"><dt>Assessment</dt><dd>${escapeHtml(viewModel.assessmentSummary)}</dd></div>`);
    }
    if (viewModel.unresolvedSummary) {
        facts.push(`<div class="thinking-card-diagnostic-fact"><dt>Unresolved checks</dt><dd>${escapeHtml(viewModel.unresolvedSummary)}</dd></div>`);
    }
    if (viewModel.source) {
        facts.push(`<div class="thinking-card-diagnostic-fact"><dt>Source</dt><dd><span class="thinking-card-diagnostic-inline-code">${escapeHtml(viewModel.source)}</span></dd></div>`);
    }

    const recommendationsHtml = viewModel.recommendations.length > 0
        ? `<div class="thinking-card-diagnostic-section"><div class="thinking-card-diagnostic-section-title">Recommendations</div>${renderThinkingCriticListHTML(viewModel.recommendations)}</div>`
        : '';
    const blockersHtml = viewModel.blockers.length > 0
        ? `<div class="thinking-card-diagnostic-section"><div class="thinking-card-diagnostic-section-title">Blockers</div>${renderThinkingCriticListHTML(viewModel.blockers)}</div>`
        : '';
    const failureCodesHtml = viewModel.failureCodes.length > 0
        ? `<div class="thinking-card-diagnostic-section"><div class="thinking-card-diagnostic-section-title">Failure codes</div>${renderThinkingCriticListHTML(viewModel.failureCodes)}</div>`
        : '';

    return `<section class="thinking-card-critic-panel" id="${escapeHtml(viewModel.panelId)}" data-thinking-critic-panel>
        <div class="thinking-card-diagnostic-section-title">Critic review</div>
        ${facts.length > 0 ? `<dl class="thinking-card-diagnostic-facts">${facts.join('')}</dl>` : ''}
        ${recommendationsHtml}${blockersHtml}${failureCodesHtml}
        <div class="thinking-card-critic-actions">
            <button type="button" class="btn thinking-card-action" aria-hidden="false" data-thinking-action="critic-copy">${escapeHtml(THINKING_CRITIC_COPY_BUTTON_LABEL)}</button>
        </div>
    </section>`;
}

function syncThinkingCriticControlStateToDom(request = getThinkingCardDisplayRequest(), cardRoot = null) {
    const criticButton = getThinkingCardCriticButtonEl(cardRoot);
    if (!(criticButton instanceof HTMLButtonElement)) {
        return;
    }
    const viewModel = buildThinkingCriticViewModel(request);
    const visible = !!viewModel;
    criticButton.setAttribute('aria-hidden', visible ? 'false' : 'true');
    criticButton.disabled = !visible;
    criticButton.setAttribute('aria-expanded', visible && request?.thinkingCriticPanelOpen === true ? 'true' : 'false');
    criticButton.setAttribute('aria-controls', viewModel?.panelId || getLoadingIndicatorDetailEl(cardRoot)?.id || '');
    criticButton.setAttribute(
        'title',
        visible && request?.thinkingCriticPanelOpen === true ? 'Hide critic review' : 'Show critic review'
    );
    criticButton.setAttribute(
        'aria-label',
        visible && request?.thinkingCriticPanelOpen === true ? 'Hide critic review' : 'Show critic review'
    );
}

function toggleThinkingCriticPanel(request = getThinkingCardDisplayRequest(), cardRoot = null) {
    if (!request || typeof request !== 'object' || !extractThinkingCriticOutput(request)) {
        return false;
    }
    request.thinkingCriticPanelOpen = request.thinkingCriticPanelOpen !== true;
    if (request.thinkingCriticPanelOpen) {
        const state = normaliseThinkingCardDisplayState(request.thinkingCardDisplayState);
        request.thinkingCardDisplayState = {
            ...state,
            expanded: true
        };
    }
    refreshThinkingCardProgressUi(request, cardRoot);
    return true;
}

function buildThinkingCriticCopyPayload(request) {
    const viewModel = buildThinkingCriticViewModel(request);
    if (!viewModel) {
        return null;
    }
    const latestProgress = isPlainObject(request?.latestProgress) ? request.latestProgress : null;
    return {
        schema_version: THINKING_CRITIC_OUTPUT_SCHEMA_VERSION,
        generated_at_utc: new Date().toISOString(),
        request_id: request?.clientRequestId || latestProgress?.request_id || null,
        turn_id: request?.resultTurnId || null,
        critic_view: {
            verdict: viewModel.verdict || null,
            assessment_summary: viewModel.assessmentSummary || null,
            recommendations: viewModel.recommendations,
            blockers: viewModel.blockers,
            failure_codes: viewModel.failureCodes,
            unresolved_summary: viewModel.unresolvedSummary || null,
            source: viewModel.source || null
        },
        critic_verdict: viewModel.raw
    };
}

async function copyThinkingCriticDetails(button = null, request = getThinkingCardDisplayRequest()) {
    const payload = buildThinkingCriticCopyPayload(request);
    if (!payload) {
        showToast('No critic details are available for this turn.', 'info');
        return false;
    }
    const text = JSON.stringify(payload, null, 2);
    if (button instanceof HTMLButtonElement) {
        return copyJsonTextWithButtonFeedback(button, text, {
            fallbackLabel: THINKING_CRITIC_COPY_BUTTON_LABEL
        });
    }
    return copyTextToClipboard(text);
}

function normaliseThinkingCardMode(mode) {
    const cleanMode = (typeof mode === 'string') ? mode.trim().toLowerCase() : '';
    return THINKING_CARD_MODES.has(cleanMode) ? cleanMode : THINKING_CARD_MODE_DEFAULT;
}

function loadStoredThinkingCardMode() {
    return normaliseThinkingCardMode(safeLocalStorageGet(THINKING_CARD_MODE_STORAGE_KEY));
}

function saveStoredThinkingCardMode(mode) {
    const nextMode = normaliseThinkingCardMode(mode);
    safeLocalStorageSet(THINKING_CARD_MODE_STORAGE_KEY, nextMode);
    return nextMode;
}

function getThinkingCardMode(request = getThinkingCardDisplayRequest(), options = {}) {
    if (options && Object.prototype.hasOwnProperty.call(options, 'mode')) {
        return normaliseThinkingCardMode(options.mode);
    }
    if (
        request
        && typeof request === 'object'
        && Object.prototype.hasOwnProperty.call(request, 'thinkingCardMode')
    ) {
        return normaliseThinkingCardMode(request.thinkingCardMode);
    }
    return loadStoredThinkingCardMode();
}

function syncThinkingCardModeClass(wrapper, mode) {
    if (!(wrapper instanceof HTMLElement)) {
        return;
    }
    const nextMode = normaliseThinkingCardMode(mode);
    THINKING_CARD_MODE_CLASS_NAMES.forEach((className) => wrapper.classList.remove(className));
    wrapper.classList.add(`thinking-card-mode-${nextMode}`);
    wrapper.classList.toggle('is-expert-mode', nextMode === THINKING_CARD_MODE_EXPERT);
}

function isThinkingCardFreeHeightMode(request = getThinkingCardDisplayRequest(), cardRoot = null) {
    const wrapper = getThinkingCardWrapperEl(cardRoot);
    return !!wrapper
        && wrapper.classList.contains('is-active-turn')
        && getThinkingCardMode(request) === THINKING_CARD_MODE_EXPERT;
}

function setThinkingCardMode(request = getThinkingCardDisplayRequest(), mode = THINKING_CARD_MODE_DEFAULT, cardRoot = null) {
    const nextMode = saveStoredThinkingCardMode(mode);
    if (!request || typeof request !== 'object') {
        updateThinkingCardModeControls(request, cardRoot);
        return nextMode;
    }
    request.thinkingCardMode = nextMode;
    refreshThinkingCardProgressUi(request, cardRoot);
    return nextMode;
}

function updateThinkingCardModeControls(request = getThinkingCardDisplayRequest(), cardRoot = null) {
    const wrapper = getThinkingCardWrapperEl(cardRoot);
    const buttons = getThinkingCardModeButtons(cardRoot);
    const activeMode = getThinkingCardMode(request);
    syncThinkingCardModeClass(wrapper, activeMode);
    if (buttons.length === 0) {
        return;
    }

    const visible = !!wrapper && wrapper.getAttribute('aria-hidden') !== 'true';
    buttons.forEach((button) => {
        if (!(button instanceof HTMLButtonElement)) {
            return;
        }
        const buttonMode = normaliseThinkingCardMode(button.dataset.thinkingMode);
        const isActive = buttonMode === activeMode;
        button.setAttribute('aria-hidden', visible ? 'false' : 'true');
        button.setAttribute('aria-pressed', isActive ? 'true' : 'false');
        button.classList.toggle('is-active', isActive);
    });
}

function clampThinkingCardBodyHeightPx(value) {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) {
        return THINKING_CARD_BODY_DEFAULT_HEIGHT_PX;
    }
    return Math.max(
        THINKING_CARD_BODY_MIN_HEIGHT_PX,
        Math.min(THINKING_CARD_BODY_MAX_HEIGHT_PX, Math.round(numeric))
    );
}

function getThinkingCardInitialBodyHeightPx(detailEl = null) {
    const contentHeight = (detailEl instanceof HTMLElement && Number.isFinite(detailEl.scrollHeight))
        ? detailEl.scrollHeight
        : THINKING_CARD_BODY_DEFAULT_HEIGHT_PX;
    return clampThinkingCardBodyHeightPx(
        Math.max(contentHeight, THINKING_CARD_BODY_DEFAULT_HEIGHT_PX)
    );
}

function ensureThinkingCardBodyHeightPx(request, detailEl = null) {
    if (!request || typeof request !== 'object') {
        return getThinkingCardInitialBodyHeightPx(detailEl);
    }

    const existingHeight = Number(request.thinkingCardBodyHeightPx);
    if (Number.isFinite(existingHeight)) {
        request.thinkingCardBodyHeightPx = clampThinkingCardBodyHeightPx(existingHeight);
        return request.thinkingCardBodyHeightPx;
    }

    request.thinkingCardBodyHeightPx = getThinkingCardInitialBodyHeightPx(detailEl);
    return request.thinkingCardBodyHeightPx;
}

function resolveThinkingCardBodyHeightPxFromDom(detailEl) {
    if (!(detailEl instanceof HTMLElement)) {
        return null;
    }

    const inlineHeight = Number.parseFloat(detailEl.style.height);
    if (Number.isFinite(inlineHeight) && inlineHeight > 0) {
        return clampThinkingCardBodyHeightPx(inlineHeight);
    }

    const rectHeight = detailEl.getBoundingClientRect().height;
    if (Number.isFinite(rectHeight) && rectHeight > 0) {
        return clampThinkingCardBodyHeightPx(rectHeight);
    }

    return null;
}

function applyThinkingCardBodyHeightPx(nextHeightPx, request = getThinkingCardDisplayRequest(), cardRoot = null) {
    const detailEl = getLoadingIndicatorDetailEl(cardRoot);
    if (!(detailEl instanceof HTMLElement)) {
        return null;
    }

    const clampedHeightPx = clampThinkingCardBodyHeightPx(nextHeightPx);
    if (request && typeof request === 'object') {
        request.thinkingCardBodyHeightPx = clampedHeightPx;
    }
    detailEl.style.height = `${clampedHeightPx}px`;
    updateThinkingCardResizeControls(request, cardRoot);
    return clampedHeightPx;
}

function setLoadingIndicatorText(text, cardRoot = null) {
    const el = getLoadingIndicatorTextEl(cardRoot);
    if (!el) {
        return;
    }
    el.textContent = String(text ?? '').trim() || DEFAULT_THINKING_TEXT;
}

function setLoadingIndicatorTooltip(text, cardRoot = null) {
    const detailEl = getLoadingIndicatorDetailEl(cardRoot);
    if (detailEl) {
        return;
    }

    const value = String(text ?? '').trim();
    const wrapper = getLoadingIndicatorEl(cardRoot);
    if (wrapper) {
        // Opt out of suppressTooltips.js for this element.
        // Important: set before `title`, otherwise the MutationObserver may strip it.
        wrapper.setAttribute('data-keep-title', 'true');
        wrapper.title = value;
        wrapper.setAttribute('aria-label', value);
        wrapper.setAttribute('data-original-title', value);
    }

    const textEl = getLoadingIndicatorTextEl(cardRoot);
    if (textEl) {
        textEl.setAttribute('data-keep-title', 'true');
        textEl.title = value;
        textEl.setAttribute('aria-label', value);
        textEl.setAttribute('data-original-title', value);
    }
}

/**
 * Update the thinking card body with tool history HTML.
 */
function setLoadingIndicatorDetailHtml(html, request = getThinkingCardDisplayRequest(), cardRoot = null) {
    const detailEl = getLoadingIndicatorDetailEl(cardRoot);
    if (!detailEl) {
        return;
    }
    snapshotThinkingDiagnosticExpansionState(detailEl, request);
    const value = String(html ?? '').trim();
    detailEl.innerHTML = value;
    bindConceptSelectionClicks(detailEl, {
        selector: '.thinking-card-concept-link',
        datasetKey: 'conceptLinkBound'
    });
    bindThinkingDiagnosticToggles(detailEl, request);
    bindThinkingLlmCallLogExpansionCache(detailEl, request);

    // Update wrapper to show/hide tool list
    const wrapper = getThinkingCardWrapperEl(cardRoot);
    if (wrapper) {
        if (value) {
            wrapper.classList.add('has-tools');
        } else {
            wrapper.classList.remove('has-tools');
        }
    }

    syncThinkingCardExpandedStateToDom(request, cardRoot);
}

/**
 * Legacy function - redirects to HTML version.
 */
function _setLoadingIndicatorDetailText(text, cardRoot = null) {
    // For plain text, escape and wrap
    const detailEl = getLoadingIndicatorDetailEl(cardRoot);
    if (!detailEl) {
        return;
    }
    const value = String(text ?? '').trim();
    if (value) {
        // Convert plain text to simple pre-formatted display
        detailEl.innerHTML = `<div style="white-space: pre-line;">${escapeHtml(value)}</div>`;
    } else {
        detailEl.innerHTML = '';
    }

    const wrapper = getThinkingCardWrapperEl(cardRoot);
    if (wrapper) {
        if (value) {
            wrapper.classList.add('has-tools');
        } else {
            wrapper.classList.remove('has-tools');
        }
    }

    syncThinkingCardExpandedStateToDom(getThinkingCardDisplayRequest(), cardRoot);
}

function createThinkingCardDisplayState() {
    return {
        expanded: true,
        autoFurlApplied: false
    };
}

function normaliseThinkingCardDisplayState(state) {
    if (!state || typeof state !== 'object') {
        return createThinkingCardDisplayState();
    }
    return {
        expanded: state.expanded !== false,
        autoFurlApplied: state.autoFurlApplied === true
    };
}

function normaliseThinkingProgressStatusValue(value) {
    return (typeof value === 'string') ? value.trim().toLowerCase() : '';
}

function canonicalThinkingTerminalStatus(value) {
    const status = normaliseThinkingProgressStatusValue(value);
    if (!THINKING_TERMINAL_PROGRESS_STATUSES.has(status)) {
        return null;
    }
    if (status === 'completed' || status === 'complete' || status === 'done') {
        return THINKING_STATUS_COMPLETED;
    }
    if (
        status === 'follow_up_required'
        || status === 'follow-up-required'
        || status === 'follow up required'
        || status === 'escalation_required'
        || status === 'escalation-required'
        || status === 'escalation required'
    ) {
        return THINKING_STATUS_FOLLOW_UP_REQUIRED;
    }
    if (status === 'error' || status === 'failed') {
        return THINKING_STATUS_FAILED;
    }
    if (status === 'cancelled' || status === 'canceled' || status === 'aborted') {
        return THINKING_STATUS_CANCELLED;
    }
    if (status === 'terminated') {
        return THINKING_STATUS_TERMINATED;
    }
    return null;
}

function terminalThinkingProgressStateToRowState(value) {
    const terminalStatus = canonicalThinkingTerminalStatus(value);
    if (terminalStatus === THINKING_STATUS_COMPLETED) {
        return 'success';
    }
    if (
        terminalStatus === THINKING_STATUS_FAILED
        || terminalStatus === THINKING_STATUS_CANCELLED
        || terminalStatus === THINKING_STATUS_TERMINATED
    ) {
        return 'failure';
    }
    return null;
}

function resolveThinkingTerminalStatus(progress) {
    if (!progress || typeof progress !== 'object') {
        return null;
    }
    const candidates = [
        progress.status,
        progress.orchestrator_status,
        progress.terminal_status,
        progress.final_status
    ];
    for (const value of candidates) {
        const canonical = canonicalThinkingTerminalStatus(value);
        if (canonical) {
            return canonical;
        }
    }
    return null;
}

function getWorkflowSelectionSnapshot(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }

    const workflowSelection = (
        value.workflow_selection
        && typeof value.workflow_selection === 'object'
    )
        ? value.workflow_selection
        : (
            value.workflowSelection
            && typeof value.workflowSelection === 'object'
                ? value.workflowSelection
                : null
        );

    if (workflowSelection) {
        return workflowSelection;
    }

    if (
        typeof value.selected_workflow_id === 'string'
        || typeof value.selected_workflow_name === 'string'
        || typeof value.workflow_selector_verdict === 'string'
        || typeof value.workflow_selector_source === 'string'
        || Number.isFinite(value.workflow_match_count)
        || Number.isFinite(value.workflow_candidate_count)
    ) {
        return value;
    }

    return null;
}

function getWorkflowRoutingDiagnostics(progressLike) {
    if (!progressLike || typeof progressLike !== 'object') {
        return null;
    }

    const directDiagnostics = (
        progressLike.workflow_routing_diagnostics
        && typeof progressLike.workflow_routing_diagnostics === 'object'
    )
        ? progressLike.workflow_routing_diagnostics
        : (
            progressLike.workflowRoutingDiagnostics
            && typeof progressLike.workflowRoutingDiagnostics === 'object'
                ? progressLike.workflowRoutingDiagnostics
                : null
        );

    if (directDiagnostics) {
        return directDiagnostics;
    }

    if (
        progressLike.schema_version === 'workflow_routing_diagnostics.v1'
        || (progressLike.selector && typeof progressLike.selector === 'object')
        || (progressLike.dispatch && typeof progressLike.dispatch === 'object')
    ) {
        return progressLike;
    }

    return null;
}

function buildThinkingSelectorDiagnosticsSnapshot(workflowRoutingDiagnostics) {
    const routingDiagnostics = getWorkflowRoutingDiagnostics(workflowRoutingDiagnostics);
    const selector = (
        routingDiagnostics?.selector
        && typeof routingDiagnostics.selector === 'object'
    )
        ? routingDiagnostics.selector
        : null;
    if (!selector) {
        return null;
    }

    const prompt = normaliseThinkingDiagnosticCapture(selector.prompt);
    const candidateList = normaliseThinkingDiagnosticCapture(selector.candidate_list);
    const response = normaliseThinkingDiagnosticCapture(selector.response);
    const promptId = normaliseThinkingActivityString(selector.prompt_id) || null;
    const requestedPromptIds = Array.isArray(selector.requested_prompt_ids)
        ? selector.requested_prompt_ids
            .map((value) => normaliseThinkingActivityString(value))
            .filter(Boolean)
        : [];
    const promptProvenance = (
        selector.prompt_provenance
        && typeof selector.prompt_provenance === 'object'
    )
        ? { ...selector.prompt_provenance }
        : null;

    if (
        !prompt
        && !candidateList
        && !response
        && !promptId
        && requestedPromptIds.length === 0
        && !promptProvenance
    ) {
        return null;
    }

    return {
        prompt_id: promptId,
        requested_prompt_ids: requestedPromptIds,
        prompt_provenance: promptProvenance,
        prompt,
        candidate_list: candidateList,
        response
    };
}

function compactThinkingDiagnosticCaptureForLocator(capture) {
    if (!capture || typeof capture !== 'object') {
        return null;
    }
    const text = normaliseThinkingActivityString(capture.text);
    const preview = normaliseThinkingActivityString(capture.preview);
    const chosenPreview = preview || (text ? `${text.slice(0, 240)}${text.length > 240 ? '...' : ''}` : null);
    const charCount = Number.isFinite(capture.char_count)
        ? Number(capture.char_count)
        : (text ? text.length : null);
    if (!chosenPreview && !Number.isFinite(charCount)) {
        return null;
    }
    return {
        preview: chosenPreview,
        char_count: Number.isFinite(charCount) ? charCount : null,
        preview_truncated: capture.preview_truncated === true || Boolean(text && text.length > 240)
    };
}

function compactThinkingSelectorDiagnosticsForLocator(selector) {
    if (!selector || typeof selector !== 'object') {
        return null;
    }
    return {
        prompt_id: selector.prompt_id || null,
        requested_prompt_ids: Array.isArray(selector.requested_prompt_ids)
            ? selector.requested_prompt_ids.slice()
            : [],
        prompt_provenance: selector.prompt_provenance || null,
        prompt: compactThinkingDiagnosticCaptureForLocator(selector.prompt),
        candidate_list: compactThinkingDiagnosticCaptureForLocator(selector.candidate_list),
        response: compactThinkingDiagnosticCaptureForLocator(selector.response)
    };
}

function buildWorkflowRoutingDiagnosticsLocatorSnapshot(progressLike) {
    const routingDiagnostics = getWorkflowRoutingDiagnostics(progressLike);
    if (!routingDiagnostics) {
        return null;
    }

    const selector = buildThinkingSelectorDiagnosticsSnapshot(routingDiagnostics);
    const selectedWorkflowId = deriveSelectedWorkflowIdFromRoutingDiagnostics(routingDiagnostics);
    const selectorVerdict = deriveWorkflowSelectorVerdictFromRoutingDiagnostics(routingDiagnostics);
    const selectorSource = deriveWorkflowSelectorSourceFromRoutingDiagnostics(routingDiagnostics);

    if (!selector && !selectedWorkflowId && !selectorVerdict && !selectorSource) {
        return null;
    }

    return {
        schema_version: normaliseThinkingActivityString(routingDiagnostics.schema_version)
            || 'workflow_routing_diagnostics.v1',
        selected_workflow_id: selectedWorkflowId || null,
        selector_verdict: selectorVerdict || null,
        selector_source: selectorSource || null,
        selector: compactThinkingSelectorDiagnosticsForLocator(selector)
    };
}

function resolveLlmDebugPromptPreview({ debugData, turnExecutionDiagnostics }) {
    const candidates = [
        turnExecutionDiagnostics?.prompt_preview,
        debugData?.prompt_preview,
        debugData?.llm_prompt_preview,
        debugData?.prompt_text
    ];
    for (const candidate of candidates) {
        if (typeof candidate === 'string' && candidate.trim()) {
            return candidate;
        }
        if (candidate && typeof candidate === 'object') {
            const text = typeof candidate.text === 'string' ? candidate.text : '';
            if (text.trim()) {
                return text;
            }
            const preview = typeof candidate.preview === 'string' ? candidate.preview : '';
            if (preview.trim()) {
                return preview;
            }
        }
    }
    return null;
}

function resolveLlmDebugWorkflowRoutingDiagnostics({ debugData, turnExecutionDiagnostics }) {
    const sources = [
        turnExecutionDiagnostics,
        debugData,
        turnExecutionDiagnostics?.workflow_routing_diagnostics,
        debugData?.workflow_routing_diagnostics
    ];
    for (const source of sources) {
        const routingDiagnostics = getWorkflowRoutingDiagnostics(source);
        if (routingDiagnostics) {
            return routingDiagnostics;
        }
    }
    return null;
}

function deriveSelectedWorkflowIdFromRoutingDiagnostics(workflowRoutingDiagnostics) {
    if (!workflowRoutingDiagnostics || typeof workflowRoutingDiagnostics !== 'object') {
        return null;
    }

    const directCandidates = [
        workflowRoutingDiagnostics.selected_workflow_id,
        workflowRoutingDiagnostics.dispatch_workflow_id,
        workflowRoutingDiagnostics?.selector?.selected_workflow_id,
        workflowRoutingDiagnostics?.dispatch?.dispatch_workflow_id
    ];
    for (const candidate of directCandidates) {
        const cleanCandidate = normaliseThinkingActivityString(candidate);
        if (cleanCandidate) {
            return cleanCandidate;
        }
    }

    const overrideEvents = Array.isArray(workflowRoutingDiagnostics?.selector?.override_events)
        ? workflowRoutingDiagnostics.selector.override_events
        : [];
    for (let index = overrideEvents.length - 1; index >= 0; index -= 1) {
        const cleanCandidate = normaliseThinkingActivityString(
            overrideEvents[index]?.selected_workflow_id
        );
        if (cleanCandidate) {
            return cleanCandidate;
        }
    }

    return null;
}

function deriveWorkflowSelectorVerdictFromRoutingDiagnostics(workflowRoutingDiagnostics) {
    if (!workflowRoutingDiagnostics || typeof workflowRoutingDiagnostics !== 'object') {
        return null;
    }

    const candidates = [
        workflowRoutingDiagnostics.workflow_selector_verdict,
        workflowRoutingDiagnostics.selector_verdict,
        workflowRoutingDiagnostics?.selector?.workflow_selector_verdict,
        workflowRoutingDiagnostics?.selector?.selector_verdict,
        workflowRoutingDiagnostics?.selector?.verdict
    ];
    for (const candidate of candidates) {
        const cleanCandidate = normaliseThinkingActivityString(candidate);
        if (cleanCandidate) {
            return cleanCandidate;
        }
    }

    return null;
}

function deriveWorkflowSelectorSourceFromRoutingDiagnostics(workflowRoutingDiagnostics) {
    if (!workflowRoutingDiagnostics || typeof workflowRoutingDiagnostics !== 'object') {
        return null;
    }

    const candidates = [
        workflowRoutingDiagnostics.workflow_selector_source,
        workflowRoutingDiagnostics.selector_source,
        workflowRoutingDiagnostics?.selector?.workflow_selector_source,
        workflowRoutingDiagnostics?.selector?.selector_source,
        workflowRoutingDiagnostics?.selector?.source
    ];
    for (const candidate of candidates) {
        const cleanCandidate = normaliseThinkingActivityString(candidate);
        if (cleanCandidate) {
            return cleanCandidate;
        }
    }

    return null;
}

function buildThinkingWorkflowSelectionSnapshot(sourceLike) {
    const workflowSelection = getWorkflowSelectionSnapshot(sourceLike);
    if (!workflowSelection) {
        return null;
    }

    const selectedWorkflowId = normaliseThinkingActivityString(
        workflowSelection.selected_workflow_id
    ) || null;
    const selectedWorkflowName = normaliseThinkingActivityString(
        workflowSelection.selected_workflow_name
    ) || null;
    const selectorVerdict = normaliseThinkingActivityString(
        workflowSelection.selector_verdict ?? workflowSelection.workflow_selector_verdict
    ) || null;
    const selectorSource = normaliseThinkingActivityString(
        workflowSelection.selector_source ?? workflowSelection.workflow_selector_source
    ) || null;
    const workflowMatchCount = Number.isFinite(workflowSelection.workflow_match_count)
        ? Math.max(0, Number(workflowSelection.workflow_match_count))
        : null;
    const workflowCandidateCount = Number.isFinite(workflowSelection.workflow_candidate_count)
        ? Math.max(0, Number(workflowSelection.workflow_candidate_count))
        : null;

    if (
        !selectedWorkflowId
        && !selectedWorkflowName
        && !selectorVerdict
        && !selectorSource
        && workflowMatchCount === null
        && workflowCandidateCount === null
    ) {
        return null;
    }

    return {
        ...(workflowSelection && typeof workflowSelection === 'object' ? workflowSelection : {}),
        selected_workflow_id: selectedWorkflowId,
        selected_workflow_name: selectedWorkflowName,
        selector_verdict: selectorVerdict,
        selector_source: selectorSource,
        workflow_match_count: workflowMatchCount,
        workflow_candidate_count: workflowCandidateCount
    };
}

function buildCanonicalWorkflowRoutingProgress(request, stageDiagnostic = null) {
    const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const workflowSelection = buildThinkingWorkflowSelectionSnapshot(
        (request?.workflowSelection && typeof request.workflowSelection === 'object')
            ? request.workflowSelection
            : latestProgress
    );
    const workflowRoutingDiagnostics = getWorkflowRoutingDiagnostics(
        (request?.workflowRoutingDiagnostics && typeof request.workflowRoutingDiagnostics === 'object')
            ? request.workflowRoutingDiagnostics
            : latestProgress
    );

    return {
        ...(latestProgress && typeof latestProgress === 'object' ? latestProgress : {}),
        workflow_selection: workflowSelection || null,
        workflow_routing_diagnostics: workflowRoutingDiagnostics || null,
        selected_workflow_id: normaliseThinkingActivityString(stageDiagnostic?.selected_workflow_id)
            || normaliseThinkingActivityString(latestProgress?.selected_workflow_id)
            || normaliseThinkingActivityString(workflowSelection?.selected_workflow_id)
            || deriveSelectedWorkflowIdFromRoutingDiagnostics(workflowRoutingDiagnostics)
            || null,
        selected_workflow_name: normaliseThinkingActivityString(stageDiagnostic?.selected_workflow_name)
            || normaliseThinkingActivityString(latestProgress?.selected_workflow_name)
            || normaliseThinkingActivityString(workflowSelection?.selected_workflow_name)
            || null,
        workflow_selector_verdict: normaliseThinkingActivityString(stageDiagnostic?.workflow_selector_verdict)
            || normaliseThinkingActivityString(latestProgress?.workflow_selector_verdict)
            || normaliseThinkingActivityString(workflowSelection?.selector_verdict)
            || deriveWorkflowSelectorVerdictFromRoutingDiagnostics(workflowRoutingDiagnostics)
            || null,
        workflow_selector_source: normaliseThinkingActivityString(stageDiagnostic?.workflow_selector_source)
            || normaliseThinkingActivityString(latestProgress?.workflow_selector_source)
            || normaliseThinkingActivityString(workflowSelection?.selector_source)
            || deriveWorkflowSelectorSourceFromRoutingDiagnostics(workflowRoutingDiagnostics)
            || null,
        workflow_match_count: Number.isFinite(stageDiagnostic?.workflow_match_count)
            ? Number(stageDiagnostic.workflow_match_count)
            : (
                Number.isFinite(latestProgress?.workflow_match_count)
                    ? Number(latestProgress.workflow_match_count)
                    : workflowSelection?.workflow_match_count
            ),
        workflow_candidate_count: Number.isFinite(stageDiagnostic?.workflow_candidate_count)
            ? Number(stageDiagnostic.workflow_candidate_count)
            : (
                Number.isFinite(latestProgress?.workflow_candidate_count)
                    ? Number(latestProgress.workflow_candidate_count)
                    : workflowSelection?.workflow_candidate_count
            )
    };
}

function getWorkflowRoutingDispatchDiagnostics(progressLike) {
    const workflowRoutingDiagnostics = getWorkflowRoutingDiagnostics(progressLike);
    const dispatchDiagnostics = workflowRoutingDiagnostics?.dispatch;
    return (dispatchDiagnostics && typeof dispatchDiagnostics === 'object')
        ? dispatchDiagnostics
        : null;
}

function resolveThinkingWorkflowDispatchRowState(progressLike) {
    const dispatchDiagnostics = getWorkflowRoutingDispatchDiagnostics(progressLike);
    const dispatchState = terminalThinkingProgressStateToRowState(
        dispatchDiagnostics?.dispatch_terminal_status
    );
    if (dispatchState) {
        return dispatchState;
    }

    const resultSummary = normaliseThinkingActivityString(progressLike?.result_summary).toLowerCase();
    if (resultSummary.endsWith(':failed')) {
        return 'failure';
    }

    return null;
}

function resolveThinkingLatestStageRowState(progressLike, stageId) {
    if (!progressLike || typeof progressLike !== 'object') {
        return null;
    }
    const cleanStageId = canonicaliseThinkingDiagnosticStageId(stageId);
    if (cleanStageId === 'workflow_dispatch') {
        const dispatchState = resolveThinkingWorkflowDispatchRowState(progressLike);
        if (dispatchState) {
            return dispatchState;
        }
    }

    return terminalThinkingProgressStateToRowState(resolveThinkingTerminalStatus(progressLike));
}

function isTerminalThinkingProgress(progress) {
    return resolveThinkingTerminalStatus(progress) !== null;
}

function reduceThinkingCardDisplayState(state, event = {}) {
    const current = normaliseThinkingCardDisplayState(state);
    const type = (event && typeof event.type === 'string') ? event.type.trim() : '';

    if (type === 'reset_for_active') {
        return createThinkingCardDisplayState();
    }

    if (type === 'manual_toggle') {
        return {
            ...current,
            expanded: !current.expanded
        };
    }

    if (type === 'manual_set') {
        if (typeof event.expanded !== 'boolean') {
            return current;
        }
        return {
            ...current,
            expanded: event.expanded
        };
    }

    if (type === 'progress_update') {
        if (!isTerminalThinkingProgress(event.progress)) {
            return {
                ...current,
                expanded: true
            };
        }

        if (!current.autoFurlApplied) {
            return {
                expanded: false,
                autoFurlApplied: true
            };
        }
        return current;
    }

    return current;
}

export function __testOnly_reduceThinkingCardDisplayState(state, event = {}) {
    return reduceThinkingCardDisplayState(state, event);
}

function ensureThinkingCardDisplayState(request) {
    if (!request || typeof request !== 'object') {
        return null;
    }

    request.thinkingCardDisplayState = normaliseThinkingCardDisplayState(request.thinkingCardDisplayState);
    return request.thinkingCardDisplayState;
}

function getThinkingCardDisplayRequest() {
    return activeChatRequest || lastFinishedThinkingCard;
}

function getThinkingDiagnosticsDisplayRequest(requestOverride = null) {
    if (requestOverride && typeof requestOverride === 'object') {
        return requestOverride;
    }
    return getThinkingCardDisplayRequest();
}

function shouldDisableThinkingCardToggle(request) {
    if (!request || typeof request !== 'object') {
        return false;
    }
    return request === activeChatRequest && !isTerminalThinkingProgress(request.latestProgress);
}

function persistThinkingCardBodyHeightFromDom(request = getThinkingCardDisplayRequest(), cardRoot = null) {
    const wrapper = getThinkingCardWrapperEl(cardRoot);
    const detailEl = getLoadingIndicatorDetailEl(cardRoot);
    if (!wrapper || !(detailEl instanceof HTMLElement) || !request || typeof request !== 'object') {
        return null;
    }

    const state = ensureThinkingCardDisplayState(request) || createThinkingCardDisplayState();
    const shouldPersistHeight = wrapper.classList.contains('has-tools')
        && state.expanded !== false
        && wrapper.getAttribute('aria-hidden') !== 'true';
    if (!shouldPersistHeight) {
        return Number.isFinite(request.thinkingCardBodyHeightPx)
            ? clampThinkingCardBodyHeightPx(request.thinkingCardBodyHeightPx)
            : null;
    }
    if (isThinkingCardFreeHeightMode(request, cardRoot)) {
        detailEl.style.height = '';
        return Number.isFinite(request.thinkingCardBodyHeightPx)
            ? clampThinkingCardBodyHeightPx(request.thinkingCardBodyHeightPx)
            : null;
    }

    const measuredHeightPx = resolveThinkingCardBodyHeightPxFromDom(detailEl);
    if (!Number.isFinite(measuredHeightPx)) {
        return null;
    }

    return applyThinkingCardBodyHeightPx(measuredHeightPx, request, cardRoot);
}

function syncThinkingCardBodyHeightToDom(request = getThinkingCardDisplayRequest(), cardRoot = null) {
    const wrapper = getThinkingCardWrapperEl(cardRoot);
    const detailEl = getLoadingIndicatorDetailEl(cardRoot);
    if (!wrapper || !detailEl) {
        return;
    }

    const state = ensureThinkingCardDisplayState(request) || createThinkingCardDisplayState();
    const shouldShowBody = wrapper.classList.contains('has-tools') && state.expanded !== false;
    if (!shouldShowBody) {
        if (!wrapper.classList.contains('has-tools')) {
            detailEl.style.height = '';
        }
        return;
    }
    if (isThinkingCardFreeHeightMode(request, cardRoot)) {
        detailEl.style.height = '';
        updateThinkingCardResizeControls(request, cardRoot);
        return;
    }

    const nextHeightPx = ensureThinkingCardBodyHeightPx(request, detailEl);
    applyThinkingCardBodyHeightPx(nextHeightPx, request, cardRoot);
}

function updateThinkingCardResizeControls(request = getThinkingCardDisplayRequest(), cardRoot = null) {
    const wrapper = getThinkingCardWrapperEl(cardRoot);
    const detailEl = getLoadingIndicatorDetailEl(cardRoot);
    const decreaseButton = getThinkingCardSizeDecreaseButtonEl(cardRoot);
    const increaseButton = getThinkingCardSizeIncreaseButtonEl(cardRoot);
    if (!decreaseButton && !increaseButton) {
        return;
    }

    const visible = !!wrapper && wrapper.getAttribute('aria-hidden') !== 'true';
    const state = ensureThinkingCardDisplayState(request) || createThinkingCardDisplayState();
    const enabled = visible
        && !!wrapper
        && wrapper.classList.contains('has-tools')
        && state.expanded !== false
        && detailEl instanceof HTMLElement
        && !isThinkingCardFreeHeightMode(request, cardRoot);
    const currentHeight = enabled
        ? clampThinkingCardBodyHeightPx(
            Number.parseFloat(detailEl.style.height)
            || detailEl.getBoundingClientRect().height
            || ensureThinkingCardBodyHeightPx(request, detailEl)
        )
        : THINKING_CARD_BODY_DEFAULT_HEIGHT_PX;

    [decreaseButton, increaseButton].forEach((button) => {
        if (!(button instanceof HTMLButtonElement)) {
            return;
        }
        button.setAttribute('aria-hidden', visible ? 'false' : 'true');
        button.disabled = !enabled;
    });

    if (decreaseButton instanceof HTMLButtonElement) {
        decreaseButton.disabled = !enabled || currentHeight <= THINKING_CARD_BODY_MIN_HEIGHT_PX;
    }
    if (increaseButton instanceof HTMLButtonElement) {
        increaseButton.disabled = !enabled || currentHeight >= THINKING_CARD_BODY_MAX_HEIGHT_PX;
    }
}

function adjustThinkingCardBodyHeight(request = getThinkingCardDisplayRequest(), deltaPx = 0, cardRoot = null) {
    const detailEl = getLoadingIndicatorDetailEl(cardRoot);
    if (!(detailEl instanceof HTMLElement)) {
        return;
    }
    if (isThinkingCardFreeHeightMode(request, cardRoot)) {
        detailEl.style.height = '';
        updateThinkingCardResizeControls(request, cardRoot);
        return;
    }

    const baseHeight = (request && Number.isFinite(request.thinkingCardBodyHeightPx))
        ? Number(request.thinkingCardBodyHeightPx)
        : (
            Number.parseFloat(detailEl.style.height)
            || detailEl.getBoundingClientRect().height
            || ensureThinkingCardBodyHeightPx(request, detailEl)
        );
    applyThinkingCardBodyHeightPx(baseHeight + deltaPx, request, cardRoot);
}

function bindThinkingCardBodyResizePersistence(cardRoot = null, options = {}) {
    const explicitRoot = cardRoot instanceof HTMLElement;
    const wrapper = getThinkingCardWrapperEl(cardRoot);
    if (!wrapper && explicitRoot) {
        return;
    }
    const rootRef = explicitRoot ? wrapper : null;
    const detailEl = getLoadingIndicatorDetailEl(rootRef);
    if (!(detailEl instanceof HTMLElement) || detailEl.dataset.resizePersistenceBound === '1') {
        return;
    }

    const requestResolver = (typeof options.requestResolver === 'function')
        ? options.requestResolver
        : (() => getThinkingCardDisplayRequest());
    const persistCurrentHeight = () => {
        persistThinkingCardBodyHeightFromDom(requestResolver(), rootRef);
    };

    detailEl.dataset.resizePersistenceBound = '1';
    ['mouseup', 'pointerup', 'touchend'].forEach((eventName) => {
        detailEl.addEventListener(eventName, persistCurrentHeight);
    });

    if (typeof ResizeObserver === 'function' && !detailEl._thinkingCardResizeObserver) {
        // Track native CSS-resize handle changes so rerenders reuse the user's chosen height.
        detailEl._thinkingCardResizeObserver = new ResizeObserver(() => {
            persistCurrentHeight();
        });
        detailEl._thinkingCardResizeObserver.observe(detailEl);
    }
}

function syncThinkingCardExpandedStateToDom(request = getThinkingCardDisplayRequest(), cardRoot = null) {
    const wrapper = getThinkingCardWrapperEl(cardRoot);
    const detailEl = getLoadingIndicatorDetailEl(cardRoot);
    const toggleButton = getThinkingCardToggleButtonEl(cardRoot);
    if (!wrapper) {
        return;
    }

    const state = ensureThinkingCardDisplayState(request) || createThinkingCardDisplayState();
    const hasTools = wrapper.classList.contains('has-tools');
    const expanded = state.expanded !== false;

    wrapper.classList.toggle('is-collapsed', !expanded);
    wrapper.classList.toggle('is-expanded', expanded);

    if (detailEl) {
        const showBody = expanded && hasTools;
        detailEl.setAttribute('aria-hidden', showBody ? 'false' : 'true');
    }

    if (toggleButton) {
        toggleButton.disabled = shouldDisableThinkingCardToggle(request);
        toggleButton.setAttribute('aria-expanded', expanded ? 'true' : 'false');
        if (expanded) {
            toggleButton.setAttribute('aria-label', THINKING_CARD_TOGGLE_ARIA_LABEL_EXPANDED);
            toggleButton.title = THINKING_CARD_TOGGLE_ARIA_LABEL_EXPANDED;
        } else {
            toggleButton.setAttribute('aria-label', THINKING_CARD_TOGGLE_ARIA_LABEL_COLLAPSED);
            toggleButton.title = THINKING_CARD_TOGGLE_ARIA_LABEL_COLLAPSED;
        }
    }

    syncThinkingCardBodyHeightToDom(request, cardRoot);
    updateThinkingCardResizeControls(request, cardRoot);
}

function applyThinkingCardDisplayStateUpdate(request, event = {}, cardRoot = null) {
    if (!request || typeof request !== 'object') {
        return null;
    }

    const previous = normaliseThinkingCardDisplayState(request.thinkingCardDisplayState);
    const next = reduceThinkingCardDisplayState(previous, event);
    request.thinkingCardDisplayState = next;

    if (previous.expanded !== next.expanded || previous.autoFurlApplied !== next.autoFurlApplied) {
        syncThinkingCardExpandedStateToDom(request, cardRoot);
    }

    return next;
}

function toggleThinkingCardExpanded(request = getThinkingCardDisplayRequest(), cardRoot = null) {
    if (!request || typeof request !== 'object') {
        return;
    }

    if (shouldDisableThinkingCardToggle(request)) {
        applyThinkingCardDisplayStateUpdate(request, {
            type: 'manual_set',
            expanded: true
        }, cardRoot);
        return;
    }

    applyThinkingCardDisplayStateUpdate(request, { type: 'manual_toggle' }, cardRoot);
}

function normaliseThinkingSemanticText(value, maxChars = THINKING_SEMANTIC_OPERATION_MAX_TEXT_CHARS) {
    return truncateThinkingCardSummary(value, Math.max(1, Number(maxChars) || THINKING_SEMANTIC_OPERATION_MAX_TEXT_CHARS));
}

function normaliseThinkingSemanticScalar(value, maxChars = THINKING_SEMANTIC_OPERATION_MAX_TEXT_CHARS) {
    if (typeof value === 'boolean') {
        return value;
    }
    if (Number.isFinite(value)) {
        return Number(value);
    }
    const text = normaliseThinkingSemanticText(value, maxChars);
    return text || null;
}

function normaliseThinkingSemanticArgument(rawArgument) {
    if (!rawArgument || typeof rawArgument !== 'object') {
        return null;
    }
    const role = normaliseThinkingSemanticText(rawArgument.role, 40).toLowerCase();
    const label = THINKING_SEMANTIC_ARGUMENT_LABELS.get(role);
    if (!label) {
        return null;
    }
    const value = normaliseThinkingSemanticScalar(rawArgument.value);
    if (value === null) {
        return null;
    }
    const valueKind = normaliseThinkingSemanticText(rawArgument.value_kind || rawArgument.valueKind, 40).toLowerCase();
    if (!THINKING_SEMANTIC_ARGUMENT_VALUE_KINDS.has(valueKind)) {
        return null;
    }
    const display = normaliseThinkingSemanticText(rawArgument.display) || String(value);
    const conceptId = normaliseThinkingSemanticText(rawArgument.concept_id || rawArgument.conceptId);
    return {
        role,
        label,
        sourceArgument: normaliseThinkingSemanticText(
            rawArgument.source_argument || rawArgument.sourceArgument,
            80
        ),
        valueKind,
        value,
        display,
        conceptId
    };
}

function normaliseThinkingSemanticFocus(rawFocus) {
    if (!rawFocus || typeof rawFocus !== 'object') {
        return null;
    }
    const role = normaliseThinkingSemanticText(rawFocus.role, 40).toLowerCase();
    const spec = THINKING_SEMANTIC_FOCUS_SPECS.get(role);
    const label = THINKING_SEMANTIC_FOCUS_LABELS.get(role);
    if (!spec || !label) {
        return null;
    }
    const sourceArgument = normaliseThinkingSemanticText(
        rawFocus.source_argument || rawFocus.sourceArgument,
        80
    );
    const valueKind = normaliseThinkingSemanticText(
        rawFocus.value_kind || rawFocus.valueKind,
        40
    ).toLowerCase();
    const sourceMatches = spec.sourceArguments instanceof Set
        ? spec.sourceArguments.has(sourceArgument)
        : sourceArgument === spec.sourceArgument;
    if (!sourceMatches || valueKind !== spec.valueKind) {
        return null;
    }
    const value = normaliseThinkingSemanticScalar(rawFocus.value);
    if (value === null) {
        return null;
    }
    return {
        role,
        label,
        sourceArgument,
        valueKind,
        value,
        display: normaliseThinkingSemanticText(rawFocus.display) || String(value),
        conceptId: normaliseThinkingSemanticText(rawFocus.concept_id || rawFocus.conceptId)
    };
}

function normaliseThinkingSemanticObservation(rawObservation) {
    if (!rawObservation || typeof rawObservation !== 'object') {
        return null;
    }
    const countSource = normaliseThinkingSemanticText(
        rawObservation.count_source || rawObservation.countSource,
        80
    );
    const countLabel = THINKING_SEMANTIC_OBSERVATION_COUNT_LABELS.get(countSource) || '';
    const rawCount = rawObservation.count;
    const count = countLabel && Number.isFinite(rawCount)
        ? Math.max(0, Math.trunc(Number(rawCount)))
        : null;
    const collectionSource = normaliseThinkingSemanticText(
        rawObservation.collection_source || rawObservation.collectionSource,
        80
    );
    const items = Array.isArray(rawObservation.items)
        ? rawObservation.items
            .slice(0, THINKING_SEMANTIC_OPERATION_MAX_OBSERVATION_ITEMS)
            .map((rawItem) => {
                if (!rawItem || typeof rawItem !== 'object') {
                    return null;
                }
                const name = normaliseThinkingSemanticText(rawItem.name, 120);
                if (!name) {
                    return null;
                }
                const identifier = normaliseThinkingSemanticText(rawItem.identifier, 160);
                const identifierKind = normaliseThinkingSemanticText(
                    rawItem.identifier_kind || rawItem.identifierKind,
                    40
                ).toLowerCase();
                const identifierAllowed = identifier.startsWith('#V#') || (
                    THINKING_SEMANTIC_OBSERVATION_IDENTIFIER_KINDS.has(identifierKind)
                    && THINKING_SEMANTIC_BOUNDED_IDENTIFIER_PATTERN.test(identifier)
                );
                return {
                    name,
                    identifier: identifierAllowed ? identifier : '',
                    identifierKind: identifierAllowed && !identifier.startsWith('#V#')
                        ? identifierKind
                        : ''
                };
            })
            .filter(Boolean)
        : [];
    const details = Array.isArray(rawObservation.details)
        ? rawObservation.details
            .slice(0, THINKING_SEMANTIC_OPERATION_MAX_OBSERVATION_DETAILS)
            .map((rawDetail) => {
                if (!rawDetail || typeof rawDetail !== 'object') {
                    return null;
                }
                const sourceField = normaliseThinkingSemanticText(
                    rawDetail.source_field || rawDetail.sourceField,
                    80
                );
                const spec = THINKING_SEMANTIC_OBSERVATION_DETAIL_SPECS.get(sourceField);
                const value = normaliseThinkingSemanticText(rawDetail.value, 160);
                if (!spec || !value) {
                    return null;
                }
                return {
                    label: spec.label,
                    sourceField,
                    valueKind: spec.valueKind,
                    value
                };
            })
            .filter(Boolean)
        : [];
    if (count === null && items.length === 0 && details.length === 0) {
        return null;
    }
    return {
        count,
        countLabel,
        countSource: count !== null ? countSource : '',
        countIsLowerBound: rawObservation.count_is_lower_bound === true
            || rawObservation.countIsLowerBound === true,
        collectionSource: THINKING_SEMANTIC_OBSERVATION_COLLECTIONS.has(collectionSource)
            ? collectionSource
            : '',
        items,
        details
    };
}

function normaliseThinkingSemanticOutcome(rawOutcome) {
    if (!rawOutcome || typeof rawOutcome !== 'object') {
        return null;
    }
    const outcome = {};
    const textFields = [
        ['status', 'status'],
        ['effectStatus', 'effect_status'],
        ['mutationOutcome', 'mutation_outcome'],
        ['outcomeFinality', 'outcome_finality'],
        ['errorCode', 'error_code'],
        ['workflowId', 'workflow_id'],
        ['instanceId', 'instance_id'],
        ['finalStatus', 'final_status']
    ];
    for (const [targetKey, sourceKey] of textFields) {
        const value = normaliseThinkingSemanticText(rawOutcome[sourceKey] ?? rawOutcome[targetKey]);
        if (value) {
            outcome[targetKey] = value;
        }
    }
    if (typeof rawOutcome.success === 'boolean') {
        outcome.success = rawOutcome.success;
    }
    if (typeof rawOutcome.changed === 'boolean') {
        outcome.changed = rawOutcome.changed;
    }
    const targetIds = Array.isArray(rawOutcome.result_target_ids)
        ? rawOutcome.result_target_ids
        : rawOutcome.resultTargetIds;
    if (Array.isArray(targetIds)) {
        outcome.resultTargetIds = targetIds
            .slice(0, THINKING_SEMANTIC_OPERATION_MAX_ARGUMENTS)
            .map((value) => normaliseThinkingSemanticText(value))
            .filter(Boolean);
    }
    return Object.keys(outcome).length > 0 ? outcome : null;
}

function normaliseThinkingSemanticVerification(rawVerification) {
    if (!rawVerification || typeof rawVerification !== 'object') {
        return null;
    }
    const status = normaliseThinkingSemanticText(rawVerification.status, 40).toLowerCase();
    const source = normaliseThinkingSemanticText(rawVerification.source, 40);
    const readBackPresent = rawVerification.canonical_read_back_present
        ?? rawVerification.canonicalReadBackPresent;
    if (typeof readBackPresent !== 'boolean') {
        return null;
    }
    const isValid = (
        status === 'verified'
        && readBackPresent
        && source === 'canonical_read_back'
    ) || (
        status === 'receipt_only'
        && source === 'effect_receipt'
    ) || (
        status === 'unknown'
        && !readBackPresent
        && source === 'none'
    );
    return isValid
        ? { status, source, canonicalReadBackPresent: readBackPresent }
        : null;
}

function normaliseThinkingSemanticOperation(rawOperation) {
    if (!rawOperation || typeof rawOperation !== 'object') {
        return null;
    }
    const schemaVersion = normaliseThinkingSemanticText(rawOperation.schema_version || rawOperation.schemaVersion, 80);
    const visibility = normaliseThinkingSemanticText(rawOperation.visibility, 40).toLowerCase();
    if (schemaVersion !== THINKING_SEMANTIC_OPERATION_SCHEMA_VERSION || visibility !== 'conversation_scope') {
        return null;
    }
    const rawCapability = rawOperation.capability && typeof rawOperation.capability === 'object'
        ? rawOperation.capability
        : {};
    const capabilityId = normaliseThinkingSemanticText(rawCapability.id);
    const operationId = normaliseThinkingSemanticText(rawOperation.operation_id || rawOperation.operationId);
    const lifecycleStatus = normaliseThinkingSemanticText(
        rawOperation.lifecycle_status || rawOperation.lifecycleStatus,
        80
    );
    if (!operationId || !lifecycleStatus || !capabilityId) {
        return null;
    }
    const capability = {
        id: capabilityId,
        label: normaliseThinkingSemanticText(rawCapability.label) || formatThinkingActivityFallbackLabel(capabilityId),
        kind: normaliseThinkingSemanticText(rawCapability.kind, 80),
        executionMethod: normaliseThinkingSemanticText(
            rawCapability.execution_method || rawCapability.executionMethod
        )
    };
    const seenRoles = new Set();
    const argumentsList = [];
    if (Array.isArray(rawOperation.arguments)) {
        for (const rawArgument of rawOperation.arguments.slice(0, THINKING_SEMANTIC_OPERATION_MAX_ARGUMENTS)) {
            const argument = normaliseThinkingSemanticArgument(rawArgument);
            if (!argument || seenRoles.has(argument.role)) {
                continue;
            }
            seenRoles.add(argument.role);
            argumentsList.push(argument);
        }
    }
    const operation = {
        schemaVersion,
        operationId,
        lifecycleStatus,
        capability,
        arguments: argumentsList,
        focus: normaliseThinkingSemanticFocus(rawOperation.focus),
        observation: normaliseThinkingSemanticObservation(rawOperation.observation),
        summary: normaliseThinkingSemanticText(rawOperation.summary, THINKING_SEMANTIC_OPERATION_MAX_SUMMARY_CHARS),
        visibility,
        outcome: normaliseThinkingSemanticOutcome(rawOperation.outcome),
        verification: normaliseThinkingSemanticVerification(
            rawOperation.verification || rawOperation.outcome?.verification
        )
    };
    if (
        !operation.summary
        && argumentsList.length === 0
        && !operation.focus
        && !operation.observation
    ) {
        return null;
    }
    return operation;
}

function getThinkingSemanticOperation(source) {
    if (!source || typeof source !== 'object') {
        return null;
    }
    return normaliseThinkingSemanticOperation(source.semanticOperation || source.semantic_operation);
}

function getThinkingCapabilityDescriptor(source) {
    if (!source || typeof source !== 'object') {
        return null;
    }
    const semanticOperation = getThinkingSemanticOperation(source);
    const capabilityId = normaliseThinkingActivityString(
        semanticOperation?.capability?.id || source.tool || source.workflowTask
    );
    const workflowArgument = semanticOperation?.arguments?.find(
        (argument) => argument?.role === 'workflow'
    );
    const workflowId = normaliseThinkingActivityString(
        source.represented_workflow_id
        || source.representedWorkflowId
        || source.workflow_id
        || source.workflowId
        || semanticOperation?.outcome?.workflowId
        || workflowArgument?.value
    );
    const capabilityKind = normaliseThinkingActivityString(
        semanticOperation?.capability?.kind || source.capability_kind || source.capabilityKind
    ) || (workflowId && capabilityId.startsWith('represented_workflow_')
        ? 'represented_workflow'
        : '');
    const suppliedDisplayName = normaliseThinkingActivityString(
        source.capability_display_name || source.capabilityDisplayName
    );
    const projectedLabel = normaliseThinkingActivityString(
        semanticOperation?.capability?.label
    );
    const generatedCapabilityLabel = formatThinkingActivityFallbackLabel(capabilityId);
    const workflowFallbackLabel = workflowId
        ? formatWorkflowName(workflowId).replace(/\b\w/g, (character) => (
            character.toUpperCase()
        ))
        : '';
    const projectedLabelIsOpaque = (
        capabilityKind === 'represented_workflow'
        && projectedLabel.toLowerCase() === generatedCapabilityLabel.toLowerCase()
    );
    const label = suppliedDisplayName
        || (projectedLabelIsOpaque ? workflowFallbackLabel : projectedLabel)
        || workflowFallbackLabel
        || generatedCapabilityLabel;
    if (!capabilityId && !label) {
        return null;
    }
    return {
        capabilityId,
        capabilityKind,
        generatedCapabilityLabel,
        label,
        opaqueCapabilityLabel: projectedLabelIsOpaque
            ? projectedLabel
            : generatedCapabilityLabel,
        semanticOperation,
        workflowId
    };
}

function replaceOpaqueThinkingCapabilityLabel(summary, descriptor) {
    const cleanSummary = normaliseThinkingActivityString(summary);
    if (
        !cleanSummary
        || descriptor?.capabilityKind !== 'represented_workflow'
        || !descriptor.label
        || !descriptor.opaqueCapabilityLabel
        || descriptor.label === descriptor.opaqueCapabilityLabel
    ) {
        return cleanSummary;
    }
    return cleanSummary.split(descriptor.opaqueCapabilityLabel).join(descriptor.label);
}

function cloneThinkingToolHistoryEntry(entry) {
    const copy = { ...entry };
    const semanticOperation = getThinkingSemanticOperation(entry);
    delete copy.semantic_operation;
    delete copy.semanticOperation;
    if (semanticOperation) {
        copy.semanticOperation = semanticOperation;
    }
    return copy;
}

function cloneThinkingToolHistory(history) {
    if (!Array.isArray(history)) {
        return [];
    }
    return history
        .filter((entry) => entry && typeof entry === 'object')
        .map((entry) => cloneThinkingToolHistoryEntry(entry));
}

function cloneThinkingStructuredHistory(history) {
    if (!Array.isArray(history)) {
        return [];
    }
    return history
        .filter((entry) => entry && typeof entry === 'object')
        .map((entry) => ({ ...entry }));
}

function getCanonicalThinkingToolHistory(request) {
    if (!request || typeof request !== 'object') {
        return [];
    }

    const latestProgress = (request.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    if (latestProgress && Array.isArray(latestProgress.tool_history)) {
        return cloneThinkingToolHistory(latestProgress.tool_history);
    }

    return cloneThinkingToolHistory(request.toolUseProgressHistory);
}

function syncThinkingToolHistoryFromProgress(request, progress) {
    if (!request || typeof request !== 'object' || !progress || typeof progress !== 'object') {
        return false;
    }
    if (!Array.isArray(progress.tool_history)) {
        return false;
    }

    request.toolUseProgressHistory = cloneThinkingToolHistory(progress.tool_history);
    return true;
}

function syncThinkingCanonicalHistoriesFromProgress(request, progress) {
    if (!request || typeof request !== 'object' || !progress || typeof progress !== 'object') {
        return false;
    }

    let updated = false;

    if (Array.isArray(progress.phase_history)) {
        request.phaseHistory = cloneThinkingStructuredHistory(progress.phase_history);
        updated = true;
    }

    if (Array.isArray(progress.progress_events)) {
        request.progressEvents = cloneThinkingStructuredHistory(progress.progress_events);
        updated = true;
    }

    if (Array.isArray(progress.activity_history)) {
        request.activityHistory = cloneThinkingStructuredHistory(progress.activity_history);
        updated = true;
    }

    if (Array.isArray(progress.stage_diagnostics)) {
        request.stageDiagnostics = cloneThinkingStructuredHistory(progress.stage_diagnostics);
        updated = true;
    }

    const timingSummary = cloneThinkingTimingSummary(progress.timing_summary);
    if (timingSummary) {
        request.timingSummary = timingSummary;
        updated = true;
    }

    return updated;
}

function syncThinkingCanonicalStateFromTurnExecutionDiagnostics(request, diagnostics) {
    if (!request || typeof request !== 'object' || !diagnostics || typeof diagnostics !== 'object') {
        return false;
    }

    let updated = false;

    if (diagnostics.latest_progress && typeof diagnostics.latest_progress === 'object') {
        request.latestProgress = cloneThinkingLatestProgress(diagnostics.latest_progress);
        updated = true;
    }

    if (diagnostics.workflow_stage_path && typeof diagnostics.workflow_stage_path === 'object') {
        request.workflowStagePath = {
            ...diagnostics.workflow_stage_path,
            path: Array.isArray(diagnostics.workflow_stage_path.path)
                ? diagnostics.workflow_stage_path.path.map((entry) => ({ ...entry }))
                : []
        };
        updated = true;
    }

    if (diagnostics.workflow_discovery && typeof diagnostics.workflow_discovery === 'object') {
        request.workflowDiscovery = { ...diagnostics.workflow_discovery };
        updated = true;
    }

    if (diagnostics.workflow_selection && typeof diagnostics.workflow_selection === 'object') {
        request.workflowSelection = { ...diagnostics.workflow_selection };
        updated = true;
    }

    if (
        diagnostics.workflow_routing_diagnostics
        && typeof diagnostics.workflow_routing_diagnostics === 'object'
    ) {
        request.workflowRoutingDiagnostics = {
            ...diagnostics.workflow_routing_diagnostics
        };
        updated = true;
    }

    if (Array.isArray(diagnostics.phase_history)) {
        request.phaseHistory = cloneThinkingStructuredHistory(diagnostics.phase_history);
        updated = true;
    }

    if (Array.isArray(diagnostics.progress_events)) {
        request.progressEvents = cloneThinkingStructuredHistory(diagnostics.progress_events);
        updated = true;
    }

    if (Array.isArray(diagnostics.activity_history)) {
        request.activityHistory = cloneThinkingStructuredHistory(diagnostics.activity_history);
        updated = true;
    }

    if (Array.isArray(diagnostics.stage_diagnostics)) {
        request.stageDiagnostics = cloneThinkingStructuredHistory(diagnostics.stage_diagnostics);
        updated = true;
    }

    const timingSummary = cloneThinkingTimingSummary(diagnostics.timing_summary);
    if (timingSummary) {
        request.timingSummary = timingSummary;
        updated = true;
    }

    const timingBreakdown = cloneThinkingTimingBreakdown(diagnostics.timing_breakdown);
    if (timingBreakdown) {
        request.timingBreakdown = timingBreakdown;
        updated = true;
    }

    return updated;
}

function buildSyntheticThinkingTerminalProgress(request) {
    if (!request || typeof request !== 'object') {
        return null;
    }

    const turnOutcome = (request.turnOutcome && typeof request.turnOutcome === 'object')
        ? request.turnOutcome
        : null;
    if (!turnOutcome) {
        return null;
    }

    const outcomeStatus = normaliseThinkingProgressStatusValue(turnOutcome.status) || 'completed';
    const terminalStatus = outcomeStatus === 'error' || outcomeStatus === 'failed'
        ? 'error'
        : (
            outcomeStatus === 'follow_up_required'
                ? 'follow_up_required'
                : (
                    outcomeStatus === 'cancelled' || outcomeStatus === 'canceled' || outcomeStatus === 'aborted'
                        ? 'cancelled'
                        : (outcomeStatus === 'terminated' ? 'terminated' : 'completed')
                )
        );
    const phaseLabel = normaliseThinkingActivityString(turnOutcome.phase_label)
        || (terminalStatus === 'error'
            ? 'Turn failed'
            : (
                terminalStatus === 'follow_up_required'
                    ? 'Follow-up required'
                    : (
                        terminalStatus === 'cancelled'
                            ? 'Turn stopped'
                            : (terminalStatus === 'terminated' ? 'Turn terminated' : 'Turn completed')
                    )
            ));
    const resultSummary = normaliseThinkingActivityString(turnOutcome.result_summary)
        || normaliseThinkingActivityString(turnOutcome.summary);
    const thinkingStartedAtMs = Number.isFinite(request.thinkingStartedAtMs)
        ? Number(request.thinkingStartedAtMs)
        : null;
    const thinkingFinishedAtMs = Number.isFinite(request.thinkingFinishedAtMs)
        ? Number(request.thinkingFinishedAtMs)
        : Date.now();
    const elapsedMs = thinkingStartedAtMs !== null
        ? Math.max(0, Math.round(thinkingFinishedAtMs - thinkingStartedAtMs))
        : null;

    return {
        status: terminalStatus,
        liveness_state: terminalStatus === 'error' ? 'failed' : terminalStatus,
        phase: terminalStatus,
        stage: terminalStatus,
        phase_label: phaseLabel,
        stage_label: phaseLabel,
        current_activity: resultSummary || phaseLabel,
        result_summary: resultSummary || null,
        elapsed_ms: elapsedMs
    };
}

function redactSensitiveChatFailureText(value) {
    return String(value ?? '')
        .replace(/\bsk-(?:proj-)?[A-Za-z0-9_*.-]{8,}\b/g, '[redacted OpenAI API key]')
        .replace(/\bBearer\s+[A-Za-z0-9._~+/-]+=*\b/g, 'Bearer [redacted token]');
}

function normaliseChatFailureText(value) {
    const cleanValue = normaliseThinkingActivityString(value).replace(/\s+/g, ' ').trim();
    return cleanValue ? truncateThinkingCardSummary(redactSensitiveChatFailureText(cleanValue), 260) : '';
}

function isThinkingFailureProgress(progress) {
    if (!progress || typeof progress !== 'object') {
        return false;
    }
    const terminalStatus = resolveThinkingTerminalStatus(progress);
    if (
        terminalStatus === THINKING_STATUS_FAILED
        || terminalStatus === THINKING_STATUS_CANCELLED
        || terminalStatus === THINKING_STATUS_TERMINATED
    ) {
        return true;
    }
    const livenessState = normaliseThinkingProgressStatusValue(progress.liveness_state);
    return livenessState === 'error' || livenessState === 'failed';
}

function resolveChatFailureSummaryFromProgress(progress) {
    if (!isThinkingFailureProgress(progress)) {
        return '';
    }
    return normaliseChatFailureText(
        progress.result_summary
        || progress.error
        || progress.failure_reason
        || progress.failure_detail
        || progress.message
    );
}

function resolveGenerateCatchFailureSummary(request, error) {
    const progressSummary = resolveChatFailureSummaryFromProgress(request?.latestProgress);
    if (progressSummary) {
        return progressSummary;
    }

    const errorMessage = normaliseChatFailureText(error?.message || error);
    if (errorMessage && !/^(failed to fetch|load failed|networkerror when attempting to fetch resource)$/i.test(errorMessage)) {
        return errorMessage;
    }

    return 'The final response did not return from Von.';
}

function retainGenerateFailureSummaryInLatestProgress(request, summary) {
    if (!request || typeof request !== 'object' || !isThinkingFailureProgress(request.latestProgress)) {
        return;
    }
    const failureSummary = normaliseChatFailureText(summary);
    if (!failureSummary) {
        return;
    }
    request.latestProgress = {
        ...request.latestProgress,
        result_summary: normaliseThinkingActivityString(request.latestProgress.result_summary) || failureSummary
    };
}

function normaliseThinkingProgressUpdatedAtMs(progress) {
    if (!progress || typeof progress !== 'object') {
        return null;
    }

    const updatedAtEpochRaw = Number(progress.updated_at_epoch);
    if (Number.isFinite(updatedAtEpochRaw)) {
        return Math.round(
            updatedAtEpochRaw > 10_000_000_000
                ? updatedAtEpochRaw
                : updatedAtEpochRaw * 1000
        );
    }

    const updatedAt = typeof progress.updated_at === 'string' ? progress.updated_at.trim() : '';
    if (!updatedAt) {
        return null;
    }

    const parsed = Date.parse(updatedAt);
    return Number.isFinite(parsed) ? parsed : null;
}

function getThinkingProgressOrderingMetadata(progress) {
    if (!progress || typeof progress !== 'object') {
        return {
            sequenceNo: null,
            updatedAtMs: null,
            elapsedMs: null,
            hasOrdering: false
        };
    }

    const sequenceNoRaw = Number(progress.sequence_no);
    const sequenceNo = Number.isFinite(sequenceNoRaw)
        ? Math.max(0, Math.round(sequenceNoRaw))
        : null;
    const updatedAtMs = normaliseThinkingProgressUpdatedAtMs(progress);
    const elapsedMsRaw = Number(progress.elapsed_ms);
    const elapsedMs = Number.isFinite(elapsedMsRaw)
        ? Math.max(0, Math.round(elapsedMsRaw))
        : null;

    return {
        sequenceNo,
        updatedAtMs,
        elapsedMs,
        hasOrdering: sequenceNo !== null || updatedAtMs !== null || elapsedMs !== null
    };
}

function shouldAcceptThinkingProgressUpdate(currentProgress, nextProgress) {
    if (!nextProgress || typeof nextProgress !== 'object') {
        return false;
    }
    if (!currentProgress || typeof currentProgress !== 'object') {
        return true;
    }

    const current = getThinkingProgressOrderingMetadata(currentProgress);
    const next = getThinkingProgressOrderingMetadata(nextProgress);

    if (current.sequenceNo !== null && next.sequenceNo !== null) {
        return next.sequenceNo >= current.sequenceNo;
    }
    if (current.updatedAtMs !== null && next.updatedAtMs !== null) {
        return next.updatedAtMs >= current.updatedAtMs;
    }
    if (current.elapsedMs !== null && next.elapsedMs !== null) {
        return next.elapsedMs >= current.elapsedMs;
    }

    if (current.hasOrdering && !next.hasOrdering) {
        const nextStatus = normaliseThinkingProgressStatusValue(nextProgress.status);
        if (!isTerminalThinkingProgress(nextProgress) || nextStatus === 'pending') {
            return false;
        }
    }

    if (isTerminalThinkingProgress(currentProgress) && !isTerminalThinkingProgress(nextProgress)) {
        return false;
    }

    return true;
}

function applyThinkingProgressUpdate(request, nextProgress) {
    if (!request || typeof request !== 'object') {
        return false;
    }
    if (!shouldAcceptThinkingProgressUpdate(request.latestProgress, nextProgress)) {
        return false;
    }

    request.latestProgress = cloneThinkingLatestProgress(nextProgress) || nextProgress;
    const liveCostSummary = (
        nextProgress?.llm_usage_cost_summary
        && typeof nextProgress.llm_usage_cost_summary === 'object'
    ) ? nextProgress.llm_usage_cost_summary : null;
    setConversationRuntimeCostLiveSummary(request, liveCostSummary, {
        active: !isTerminalThinkingProgress(nextProgress),
        reason: 'live_progress'
    });
    const workflowSelection = buildThinkingWorkflowSelectionSnapshot(nextProgress);
    if (workflowSelection) {
        request.workflowSelection = workflowSelection;
    }
    const workflowRoutingDiagnostics = getWorkflowRoutingDiagnostics(nextProgress);
    if (workflowRoutingDiagnostics) {
        request.workflowRoutingDiagnostics = { ...workflowRoutingDiagnostics };
    }
    applyThinkingCardDisplayStateUpdate(request, {
        type: 'progress_update',
        progress: nextProgress
    });
    return true;
}

function applyImmediateThinkingTerminalOutcome(request) {
    if (!request || typeof request !== 'object' || !request.turnOutcome) {
        return null;
    }

    if (!Number.isFinite(request.thinkingFinishedAtMs)) {
        request.thinkingFinishedAtMs = Date.now();
    }

    const currentProgress = (request.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    if (isTerminalThinkingProgress(currentProgress)) {
        applyThinkingCardDisplayStateUpdate(request, {
            type: 'progress_update',
            progress: currentProgress
        });
    } else {
        const syntheticProgress = buildSyntheticThinkingTerminalProgress(request);
        if (syntheticProgress) {
            applyThinkingProgressUpdate(
                request,
                currentProgress
                    ? { ...currentProgress, ...syntheticProgress }
                    : syntheticProgress
            );
        }
    }

    refreshThinkingCardProgressUi(request);
    return request.latestProgress || null;
}

function refreshThinkingCardProgressUi(request, cardRoot = null) {
    if (!request || typeof request !== 'object') {
        return;
    }
    if (!(cardRoot instanceof HTMLElement) && !isRequestInActiveChatSession(request)) {
        return;
    }

    persistThinkingCardBodyHeightFromDom(request, cardRoot);
    setLoadingIndicatorText(formatToolUseProgressText(request.latestProgress, request), cardRoot);
    setLoadingIndicatorDetailHtml(renderThinkingCardBodyHTML(request), request, cardRoot);
    updateThinkingCardMeta(request, request.latestProgress || null, cardRoot);
    updateThinkingCardModeControls(request, cardRoot);
    syncThinkingCriticControlStateToDom(request, cardRoot);
}

function createThinkingCardHistorySnapshot(request) {
    if (!request || typeof request !== 'object') {
        return null;
    }

    const currentLatestProgress = (request.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const syntheticTerminalProgress = buildSyntheticThinkingTerminalProgress(request);
    const latestProgress = currentLatestProgress
        ? (
            isTerminalThinkingProgress(currentLatestProgress) || !syntheticTerminalProgress
                ? cloneThinkingLatestProgress(currentLatestProgress)
                : { ...syntheticTerminalProgress }
        )
        : (syntheticTerminalProgress ? cloneThinkingLatestProgress(syntheticTerminalProgress) : null);
    const activityHistory = Array.isArray(request.activityHistory)
        ? request.activityHistory.map((entry) => ({ ...entry }))
        : [];
    const progressEvents = Array.isArray(request.progressEvents)
        ? request.progressEvents.map((entry) => ({ ...entry }))
        : [];
    const phaseHistory = Array.isArray(request.phaseHistory)
        ? request.phaseHistory.map((entry) => ({ ...entry }))
        : [];
    const toolHistory = getCanonicalThinkingToolHistory(request);
    const workflowDiscovery = (request.workflowDiscovery && typeof request.workflowDiscovery === 'object')
        ? {
            ...request.workflowDiscovery,
            matches: Array.isArray(request.workflowDiscovery.matches)
                ? request.workflowDiscovery.matches.map((match) => ({ ...match }))
                : [],
            candidates: Array.isArray(request.workflowDiscovery.candidates)
                ? request.workflowDiscovery.candidates.map((match) => ({ ...match }))
                : [],
            routing_matches: Array.isArray(request.workflowDiscovery.routing_matches)
                ? request.workflowDiscovery.routing_matches.map((match) => ({ ...match }))
                : [],
            search_sources: Array.isArray(request.workflowDiscovery.search_sources)
                ? request.workflowDiscovery.search_sources.slice()
                : []
        }
        : null;
    const workflowSelection = (request.workflowSelection && typeof request.workflowSelection === 'object')
        ? { ...request.workflowSelection }
        : null;
    const workflowRoutingDiagnostics = (
        request.workflowRoutingDiagnostics
        && typeof request.workflowRoutingDiagnostics === 'object'
    )
        ? { ...request.workflowRoutingDiagnostics }
        : null;
    const workflowStagePath = (request.workflowStagePath && typeof request.workflowStagePath === 'object')
        ? {
            ...request.workflowStagePath,
            path: Array.isArray(request.workflowStagePath.path)
                ? request.workflowStagePath.path.map((entry) => ({ ...entry }))
                : []
        }
        : null;
    const stageDiagnostics = Array.isArray(request.stageDiagnostics)
        ? request.stageDiagnostics.map((entry) => ({ ...entry }))
        : [];
    const timingBreakdown = cloneThinkingTimingBreakdown(request.timingBreakdown);
    const timingSummary = cloneThinkingTimingSummary(request.timingSummary);
    const criticOutput = extractThinkingCriticOutput(request);

    const effectiveProgressForTerminal = latestProgress || { status: 'completed' };
    const completedDisplayState = reduceThinkingCardDisplayState(
        request.thinkingCardDisplayState,
        { type: 'progress_update', progress: effectiveProgressForTerminal }
    );

    return {
        clientRequestId: typeof request.clientRequestId === 'string' ? request.clientRequestId : null,
        promptRaw: typeof request.promptRaw === 'string' ? request.promptRaw : '',
        resultTurnId: typeof request.resultTurnId === 'string' ? request.resultTurnId : null,
        activityHistory,
        progressEvents,
        phaseHistory,
        toolUseProgressHistory: toolHistory,
        workflowDiscovery,
        workflowSelection,
        workflowRoutingDiagnostics,
        workflowStagePath,
        stageDiagnostics,
        timingBreakdown,
        timingSummary,
        llmUsageCostSummary: (
            request.llmUsageCostSummary
            && typeof request.llmUsageCostSummary === 'object'
        ) ? { ...request.llmUsageCostSummary } : null,
        criticOutput: criticOutput ? cloneThinkingCriticObject(criticOutput) : null,
        thinkingCriticPanelOpen: request.thinkingCriticPanelOpen === true,
        thinkingCriticPanelId: request.thinkingCriticPanelId || null,
        latestProgress,
        thinkingCardMode: getThinkingCardMode(request),
        expandedThinkingDiagnosticKeys: request.expandedThinkingDiagnosticKeys instanceof Set
            ? Array.from(request.expandedThinkingDiagnosticKeys)
            : (Array.isArray(request.expandedThinkingDiagnosticKeys)
                ? request.expandedThinkingDiagnosticKeys.slice()
                : []),
        thinkingLlmCallLog: cloneThinkingLlmCallLogStateForSnapshot(request.thinkingLlmCallLog),
        thinkingCardBodyHeightPx: Number.isFinite(request.thinkingCardBodyHeightPx)
            ? clampThinkingCardBodyHeightPx(request.thinkingCardBodyHeightPx)
            : null,
        thinkingStartedAtMs: Number.isFinite(request.thinkingStartedAtMs) ? Number(request.thinkingStartedAtMs) : null,
        thinkingFinishedAtMs: Date.now(),
        thinkingCardDisplayState: completedDisplayState
    };
}

function getMessageContainerByTurnId(turnId) {
    const cleanTurnId = String(turnId || '').trim();
    if (!cleanTurnId) {
        return null;
    }
    return document.querySelector(`.message-container[data-turn-id="${cssEscape(cleanTurnId)}"]`);
}

function getThinkingCardSlotForTurn(turnId) {
    const messageContainer = getMessageContainerByTurnId(turnId);
    if (!(messageContainer instanceof HTMLElement)) {
        return null;
    }
    return messageContainer.querySelector('.thinking-card-inline-slot');
}

function buildRetainedThinkingCardDetailId(turnId) {
    const cleanTurnId = String(turnId || '').trim().replace(/[^a-zA-Z0-9_-]+/g, '-');
    return `thinkingCardDetailRetained-${cleanTurnId || `card-${Date.now()}`}`;
}

function hasTurnExecutionDiagnostics(debugData) {
    return Boolean(
        debugData
        && typeof debugData === 'object'
        && debugData.turn_execution_diagnostics
        && typeof debugData.turn_execution_diagnostics === 'object'
    );
}

function hasLoadableThinkingHistoryLocation(debugData) {
    const historyLocation = (
        debugData
        && typeof debugData === 'object'
        && debugData.history_location
        && typeof debugData.history_location === 'object'
    )
        ? debugData.history_location
        : null;
    return Boolean(
        historyLocation
        && historyLocation.session_id
        && historyLocation.history_index !== undefined
        && historyLocation.history_index !== null
    );
}

function renderRetainedThinkingUnavailableState(turnId, message = 'Thinking details not stored for this turn') {
    const slot = getThinkingCardSlotForTurn(turnId);
    if (!(slot instanceof HTMLElement)) {
        return false;
    }
    const notice = document.createElement('div');
    notice.className = 'thinking-card-history-placeholder is-unavailable';
    notice.setAttribute('role', 'status');
    notice.textContent = message;
    slot.replaceChildren(notice);
    return true;
}

function renderLoadableRetainedThinkingPlaceholder(turnId, debugData = null) {
    if (!turnId || hasTurnExecutionDiagnostics(debugData) || !hasLoadableThinkingHistoryLocation(debugData)) {
        return false;
    }
    const slot = getThinkingCardSlotForTurn(turnId);
    if (!(slot instanceof HTMLElement)) {
        return false;
    }

    const wrapper = document.createElement('div');
    wrapper.className = 'thinking-card-history-placeholder';
    wrapper.setAttribute('role', 'group');
    wrapper.setAttribute('aria-label', 'Stored Thinking details');

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'btn thinking-card-history-load-button';
    button.textContent = 'Thinking available, load details';
    button.title = 'Load stored Thinking details for this turn';
    button.addEventListener('click', async (event) => {
        event.preventDefault();
        event.stopPropagation();
        const originalText = button.textContent;
        const originalTitle = button.title;
        button.disabled = true;
        button.classList.add('loading');
        button.textContent = 'Loading Thinking details...';
        button.title = 'Loading stored Thinking details';
        try {
            const loaded = await loadLlmDebugDataForTurn(turnId, { button: null });
            if (!renderRetainedThinkingCardForDebugData(turnId, loaded)) {
                renderRetainedThinkingUnavailableState(turnId);
            }
        } finally {
            if (button.isConnected) {
                button.disabled = false;
                button.classList.remove('loading');
                button.textContent = originalText || 'Thinking available, load details';
                button.title = originalTitle || 'Load stored Thinking details for this turn';
            }
        }
    });

    wrapper.appendChild(button);
    slot.replaceChildren(wrapper);
    return true;
}

function createRetainedThinkingCardWrapper(turnId) {
    const detailId = buildRetainedThinkingCardDetailId(turnId);
    const wrapper = document.createElement('div');
    wrapper.className = 'thinking-card-wrapper retained-thinking-card is-retained-turn';
    wrapper.setAttribute('aria-hidden', 'false');
    wrapper.innerHTML = `
        <div class="thinking-card" role="group" aria-label="Thinking details for this turn">
            <div class="thinking-card-header" data-thinking-role="header">
                <span class="thinking-card-dot" aria-hidden="true"></span>
                <span class="thinking-card-phase loading-indicator-text" data-thinking-role="phase">Thinking...</span>
                <span class="thinking-card-status active" data-thinking-role="status" aria-hidden="true">Active</span>
                <span class="thinking-card-meta" data-thinking-role="meta"></span>
                <div class="thinking-card-mode-switch" role="group" aria-label="Thinking detail mode">
                    <button class="thinking-card-mode-button is-active" type="button"
                        data-thinking-role="mode" data-thinking-mode="default"
                        aria-hidden="false" aria-pressed="true" title="Default thinking details">Default</button>
                    <button class="thinking-card-mode-button" type="button"
                        data-thinking-role="mode" data-thinking-mode="expert"
                        aria-hidden="false" aria-pressed="false" title="Expert thinking details">Expert</button>
                    <button class="thinking-card-mode-button" type="button"
                        data-thinking-role="mode" data-thinking-mode="debug"
                        aria-hidden="false" aria-pressed="false" title="Debug thinking details">Debug</button>
                </div>
                <button class="btn thinking-card-action thinking-card-toggle" type="button"
                    data-thinking-role="toggle" aria-hidden="false" aria-expanded="true"
                    aria-controls="${escapeHtml(detailId)}"
                    aria-label="${escapeHtml(THINKING_CARD_TOGGLE_ARIA_LABEL_EXPANDED)}"
                    title="${escapeHtml(THINKING_CARD_TOGGLE_ARIA_LABEL_EXPANDED)}">
                    <span class="thinking-card-toggle-icon" aria-hidden="true">
                        <svg viewBox="0 0 16 16" focusable="false">
                            <path d="M4 6l4 4 4-4"></path>
                        </svg>
                    </span>
                    <span class="visually-hidden">Toggle thinking details</span>
                </button>
                <button class="btn thinking-card-action thinking-card-size-button" type="button"
                    data-thinking-role="size-decrease" aria-hidden="false"
                    aria-label="Show fewer thinking details" title="Show fewer thinking details">−</button>
                <button class="btn thinking-card-action thinking-card-size-button" type="button"
                    data-thinking-role="size-increase" aria-hidden="false"
                    aria-label="Show more thinking details" title="Show more thinking details">+</button>
                <button class="btn thinking-card-action thinking-card-critic-button" type="button"
                    data-thinking-role="critic" aria-hidden="true" aria-expanded="false"
                    aria-controls="${escapeHtml(detailId)}"
                    aria-label="Show critic review" title="Show critic review">Critic</button>
                <button class="btn thinking-card-action" type="button"
                    data-thinking-role="copy" aria-hidden="false"
                    aria-label="Copy diagnostic snapshot" title="Copy diagnostic snapshot">Copy diagnostic snapshot</button>
            </div>
            <div class="thinking-card-body" data-thinking-role="detail" id="${escapeHtml(detailId)}" aria-live="polite"></div>
        </div>
    `;
    return wrapper;
}

function renderRetainedThinkingCardForTurn(request, turnId) {
    if (!request || typeof request !== 'object') {
        return false;
    }

    const slot = getThinkingCardSlotForTurn(turnId);
    if (!(slot instanceof HTMLElement)) {
        return false;
    }

    const detailHtml = renderThinkingCardBodyHTML(request);
    if (!detailHtml) {
        slot.replaceChildren();
        return false;
    }

    let wrapper = slot.querySelector('.thinking-card-wrapper');
    if (!(wrapper instanceof HTMLElement)) {
        wrapper = createRetainedThinkingCardWrapper(turnId);
        slot.replaceChildren(wrapper);
    }

    wrapper._thinkingCardRequest = request;
    wrapper.classList.add('is-retained-turn');
    wrapper.classList.remove('is-active-turn');
    bindThinkingCardControls(wrapper, {
        requestResolver: () => wrapper._thinkingCardRequest
    });
    setLoadingIndicatorText(formatToolUseProgressText(request.latestProgress, request), wrapper);
    setLoadingIndicatorDetailHtml(detailHtml, request, wrapper);
    updateThinkingCardMeta(request, request.latestProgress || null, wrapper);
    updateThinkingCardModeControls(request, wrapper);
    syncThinkingCriticControlStateToDom(request, wrapper);
    syncThinkingCardExpandedStateToDom(request, wrapper);
    return true;
}

function buildRetainedThinkingCardRequestFromDebugData(turnId, debugData) {
    if (!turnId || !debugData || typeof debugData !== 'object') {
        return null;
    }

    const diagnostics = hasTurnExecutionDiagnostics(debugData)
        ? debugData.turn_execution_diagnostics
        : null;
    const criticOutput = extractThinkingCriticOutput(debugData) || extractThinkingCriticOutput(diagnostics);
    if (!diagnostics && !criticOutput) {
        return null;
    }

    const timestampMs = parseIsoTimestampMs(
        debugData.timestamp || diagnostics?.completed_at_utc || diagnostics?.started_at_utc
    );
    const requestId = normaliseThinkingActivityString(diagnostics?.request_id || debugData.request_id);
    const request = {
        clientRequestId: requestId || null,
        resultTurnId: turnId,
        promptRaw: normaliseThinkingActivityString(debugData.prompt || debugData.user_prompt) || '',
        activityHistory: [],
        progressEvents: [],
        phaseHistory: [],
        toolUseProgressHistory: [],
        workflowDiscovery: null,
        workflowSelection: null,
        workflowRoutingDiagnostics: null,
        workflowStagePath: null,
        stageDiagnostics: [],
        timingBreakdown: null,
        latestProgress: null,
        turnExecutionDiagnostics: diagnostics,
        turn_execution_diagnostics: diagnostics,
        llmUsageCostSummary: (
            debugData.llm_usage_cost_summary
            && typeof debugData.llm_usage_cost_summary === 'object'
        ) ? { ...debugData.llm_usage_cost_summary } : null,
        criticOutput: criticOutput ? cloneThinkingCriticObject(criticOutput) : null,
        thinkingCriticPanelOpen: false,
        thinkingCardMode: loadStoredThinkingCardMode(),
        thinkingStartedAtMs: Number.isFinite(timestampMs) ? timestampMs : null,
        thinkingFinishedAtMs: Date.now(),
        thinkingCardDisplayState: reduceThinkingCardDisplayState(null, { type: 'reset_for_finished' })
    };

    if (diagnostics) {
        syncThinkingCanonicalStateFromTurnExecutionDiagnostics(request, diagnostics);
    }
    if (!isTerminalThinkingProgress(request.latestProgress)) {
        const archivedTerminalStatus = canonicalThinkingTerminalStatus(
            diagnostics?.completion_gate?.decision
            || diagnostics?.completion_gate_decision
            || diagnostics?.terminal_status
            || debugData.terminal_status
        ) || (
            debugData.success === false
            || (
                debugData.error !== undefined
                && debugData.error !== null
                && debugData.error !== ''
            )
                ? THINKING_STATUS_FAILED
                : THINKING_STATUS_COMPLETED
        );
        request.turnOutcome = {
            status: archivedTerminalStatus,
            summary: 'Loaded from Conversation history'
        };
        applyImmediateThinkingTerminalOutcome(request);
    }
    request.thinkingCardDisplayState = reduceThinkingCardDisplayState(
        request.thinkingCardDisplayState,
        { type: 'progress_update', progress: request.latestProgress || { status: 'completed' } }
    );
    return request;
}

function renderRetainedThinkingCardForDebugData(turnId, debugData) {
    const request = buildRetainedThinkingCardRequestFromDebugData(turnId, debugData);
    if (!request) {
        return false;
    }
    return renderRetainedThinkingCardForTurn(request, turnId);
}

function persistFinishedThinkingCard(request) {
    const snapshot = createThinkingCardHistorySnapshot(request);
    if (!snapshot) {
        setFinishedThinkingCardForSession(request?.sessionId, null);
        return false;
    }

    const detailHtml = renderThinkingCardBodyHTML(snapshot);
    if (!detailHtml) {
        setFinishedThinkingCardForSession(request?.sessionId, null);
        return false;
    }

    setFinishedThinkingCardForSession(request?.sessionId, snapshot);
    if (!isRequestInActiveChatSession(snapshot)) {
        return true;
    }
    return renderRetainedThinkingCardForTurn(snapshot, request.resultTurnId);
}

function createClientRequestId() {
    try {
        if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
            return crypto.randomUUID();
        }
    } catch (_) {
        // Ignore.
    }
    return `req-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function _normaliseConversationSituationInteger(value, fallback = 0) {
    return Number.isInteger(value) && value >= 0 ? value : fallback;
}

function _normaliseConversationSituationDescriptor(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        return null;
    }
    const descriptor = {
        text: (typeof value.text === 'string' && value.text.trim()) ? value.text : null,
        revision: _normaliseConversationSituationInteger(value.revision),
        source: (typeof value.source === 'string' && value.source.trim()) ? value.source.trim() : null,
        updated_by: (typeof value.updated_by === 'string' && value.updated_by.trim())
            ? value.updated_by.trim()
            : null,
        updated_at: (typeof value.updated_at === 'string' && value.updated_at.trim())
            ? value.updated_at.trim()
            : null
    };
    if (typeof value.source_request_id === 'string' && value.source_request_id.trim()) {
        descriptor.source_request_id = value.source_request_id.trim();
    }
    return descriptor;
}

function _normaliseConversationObservation(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        return null;
    }
    const observation = {};
    Object.entries(value).forEach(([key, rawValue]) => {
        if (
            typeof rawValue === 'string'
            || typeof rawValue === 'boolean'
            || (typeof rawValue === 'number' && Number.isFinite(rawValue))
            || rawValue === null
        ) {
            observation[key] = rawValue;
        }
    });
    const observationId = typeof observation.observation_id === 'string'
        ? observation.observation_id.trim()
        : '';
    const kind = typeof observation.kind === 'string' ? observation.kind.trim() : '';
    if (!observationId || !kind) {
        return null;
    }
    observation.observation_id = observationId;
    observation.kind = kind;
    return observation;
}

function _normaliseConversationObservationState(value, retainedCount) {
    const fallbackRetained = _normaliseConversationSituationInteger(retainedCount);
    const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
    const retained = _normaliseConversationSituationInteger(
        source.retained_count,
        fallbackRetained
    );
    const total = Math.max(
        retained,
        _normaliseConversationSituationInteger(source.total_count, retained)
    );
    return {
        schema_version: (
            typeof source.schema_version === 'string'
            && source.schema_version.trim()
        )
            ? source.schema_version.trim()
            : 'conversation_observation_state.v1',
        retained_count: retained,
        total_count: total,
        omitted_count: Math.max(
            0,
            _normaliseConversationSituationInteger(
                source.omitted_count,
                total - retained
            )
        ),
        retention_limit: _normaliseConversationSituationInteger(
            source.retention_limit,
            Math.max(retained, 12)
        )
    };
}

function _conversationSituationPayloadHasCarrierState(payload) {
    if (!payload || typeof payload !== 'object') {
        return false;
    }
    return Object.prototype.hasOwnProperty.call(payload, 'conversation_situation')
        || Object.prototype.hasOwnProperty.call(payload, 'conversation_observations')
        || Object.prototype.hasOwnProperty.call(payload, 'conversation_observation_state');
}

function _conversationSituationPayloadHasCompleteCarrierState(payload) {
    return _conversationSituationPayloadHasCarrierState(payload)
        && Object.prototype.hasOwnProperty.call(payload, 'conversation_situation')
        && Object.prototype.hasOwnProperty.call(payload, 'conversation_observations')
        && Object.prototype.hasOwnProperty.call(payload, 'conversation_observation_state');
}

function _acceptConversationSituationPayload(payload, sessionId, options = {}) {
    const sid = normaliseHistorySessionId(sessionId);
    if (!sid || !_conversationSituationPayloadHasCarrierState(payload)) {
        return null;
    }
    const authoritativeSnapshot = options.authoritativeSnapshot === true;

    const incomingSituation = _normaliseConversationSituationDescriptor(
        payload.conversation_situation
    );
    const incomingObservations = Array.isArray(payload.conversation_observations)
        ? payload.conversation_observations
            .map(_normaliseConversationObservation)
            .filter(Boolean)
        : [];
    const incomingObservationState = _normaliseConversationObservationState(
        payload.conversation_observation_state,
        incomingObservations.length
    );
    const existing = conversationSituationStateBySession.get(sid);
    const existingRevision = _normaliseConversationSituationInteger(
        existing?.situation?.revision
    );
    const incomingRevision = _normaliseConversationSituationInteger(
        incomingSituation?.revision
    );
    const existingObservationTotal = _normaliseConversationSituationInteger(
        existing?.observationState?.total_count
    );
    const canonicalSituationRevision = Number.isInteger(
        existing?.canonicalSituationRevision
    )
        ? existing.canonicalSituationRevision
        : null;
    const incomingPredatesCanonicalSituation = (
        !authoritativeSnapshot
        && canonicalSituationRevision !== null
        && incomingRevision < canonicalSituationRevision
    );
    const useIncomingSituation = (
        authoritativeSnapshot
        || !existing
        || incomingRevision >= existingRevision
    );
    const useIncomingObservations = (
        !incomingPredatesCanonicalSituation
        && (
            authoritativeSnapshot
            || !existing
            || incomingObservationState.total_count >= existingObservationTotal
        )
    );

    const accepted = {
        sessionId: sid,
        // Asynchronous generate responses merge their monotonic dimensions
        // independently so a slow response cannot regress either half of the
        // carrier. Guarded canonical history reads replace the whole snapshot,
        // including deliberate resets to a lower revision or total.
        situation: useIncomingSituation
            ? incomingSituation
            : existing.situation,
        observations: useIncomingObservations
            ? incomingObservations
            : existing.observations,
        observationState: useIncomingObservations
            ? incomingObservationState
            : existing.observationState,
        canonicalSituationRevision: authoritativeSnapshot
            ? incomingRevision
            : canonicalSituationRevision,
        availability: 'ready',
        notice: typeof options.notice === 'string' ? options.notice : '',
        loadedAtMs: Date.now()
    };
    conversationSituationStateBySession.set(sid, accepted);
    if (sid === activeChatSessionId) {
        _renderConversationSituationForActiveSession();
        _renderLateWorkflowOutcomesForActiveSession();
    }
    return accepted;
}

function _markConversationSituationLoading(sessionId, message = 'Loading the shared situation…') {
    const sid = normaliseHistorySessionId(sessionId);
    if (!sid) {
        return null;
    }
    const existing = conversationSituationStateBySession.get(sid);
    const nextState = existing
        ? {
            ...existing,
            availability: 'refreshing',
            notice: message
        }
        : {
            sessionId: sid,
            situation: null,
            observations: [],
            observationState: _normaliseConversationObservationState(null, 0),
            availability: 'loading',
            notice: message,
            loadedAtMs: null
        };
    conversationSituationStateBySession.set(sid, nextState);
    if (sid === activeChatSessionId) {
        _renderConversationSituationForActiveSession();
    }
    return nextState;
}

function _markConversationSituationUnavailable(sessionId, message) {
    const sid = normaliseHistorySessionId(sessionId);
    if (!sid) {
        return null;
    }
    const existing = conversationSituationStateBySession.get(sid);
    const hasRetainedState = Boolean(
        existing?.situation
        || (Array.isArray(existing?.observations) && existing.observations.length > 0)
    );
    const nextState = {
        sessionId: sid,
        situation: existing?.situation || null,
        observations: Array.isArray(existing?.observations) ? existing.observations : [],
        observationState: existing?.observationState
            || _normaliseConversationObservationState(null, 0),
        canonicalSituationRevision: Number.isInteger(
            existing?.canonicalSituationRevision
        )
            ? existing.canonicalSituationRevision
            : null,
        availability: hasRetainedState ? 'stale' : 'unavailable',
        notice: message || 'The shared situation is temporarily unavailable.',
        loadedAtMs: existing?.loadedAtMs || null
    };
    conversationSituationStateBySession.set(sid, nextState);
    if (sid === activeChatSessionId) {
        _renderConversationSituationForActiveSession();
    }
    return nextState;
}

function _setConversationSituationPanelOpen(isOpen) {
    const panel = document.getElementById('conversationSituationPanel');
    const toggle = document.getElementById('conversationSituationToggleBtn');
    const open = Boolean(isOpen);
    if (panel) {
        panel.classList.toggle('hidden', !open);
    }
    if (toggle) {
        toggle.setAttribute('aria-expanded', String(open));
    }
}

function _humaniseConversationSituationField(value) {
    const cleaned = String(value || '').trim().replace(/[_-]+/g, ' ');
    if (!cleaned) {
        return 'Observation';
    }
    return cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
}

function _formatConversationSituationValue(key, value) {
    if (typeof value === 'boolean') {
        return value ? 'Yes' : 'No';
    }
    if (value === null || value === undefined || value === '') {
        return '—';
    }
    if (
        typeof value === 'string'
        && (
            key.endsWith('_at')
            || key.endsWith('_at_utc')
            || key === 'updated_at'
            || key === 'completed_at'
        )
    ) {
        return formatAbsoluteTimestamp(value) || value;
    }
    return String(value);
}

function _appendConversationSituationDefinitionRow(list, label, value, key = '') {
    if (!list || value === null || value === undefined || value === '') {
        return;
    }
    const term = document.createElement('dt');
    term.textContent = label;
    const description = document.createElement('dd');
    description.textContent = _formatConversationSituationValue(key, value);
    if (typeof value === 'string' && description.textContent !== value) {
        description.title = value;
    }
    list.appendChild(term);
    list.appendChild(description);
}

function _renderConversationObservation(observation) {
    const card = document.createElement('article');
    card.className = 'chat-situation-observation';

    const title = document.createElement('h4');
    title.className = 'chat-situation-observation-title';
    title.textContent = _humaniseConversationSituationField(observation.kind);
    card.appendChild(title);

    const fields = document.createElement('dl');
    fields.className = 'chat-situation-observation-fields';
    const preferredKeys = [
        'observation_id',
        'observed_at_utc',
        'terminal_status',
        'effect_status',
        'domain_postcondition_status',
        'outcome_finality',
        'final_state',
        'capability_name',
        'workflow_id',
        'execution_id',
        'instance_id',
        'request_id',
        'effect_id',
        'call_id',
        'completed_at',
        'execution_trace_id',
        'changed',
        'failure_detail_available'
    ];
    const excludedKeys = new Set(['schema_version', 'kind']);
    const orderedKeys = [
        ...preferredKeys.filter(key => Object.prototype.hasOwnProperty.call(observation, key)),
        ...Object.keys(observation)
            .filter(key => !preferredKeys.includes(key) && !excludedKeys.has(key))
            .sort()
    ];
    orderedKeys.forEach((key) => {
        _appendConversationSituationDefinitionRow(
            fields,
            _humaniseConversationSituationField(key),
            observation[key],
            key
        );
    });
    card.appendChild(fields);
    return card;
}

function _lateWorkflowOutcomeLead(observation) {
    const status = String(observation?.terminal_status || '').trim().toLowerCase();
    const workflowLabel = String(
        observation?.capability_name || observation?.workflow_id || 'Background workflow'
    ).trim();
    if (status === 'completed' || status === 'succeeded' || status === 'success') {
        return `${workflowLabel} completed after the original response.`;
    }
    if (status === 'cancelled' || status === 'canceled') {
        return `${workflowLabel} was cancelled after the original response.`;
    }
    if (status === 'failed') {
        return `${workflowLabel} failed after the original response.`;
    }
    return `${workflowLabel} reached terminal status ${status || 'unknown'} after the original response.`;
}

function _renderLateWorkflowOutcome(observation, sessionId) {
    const card = document.createElement('aside');
    card.className = 'message-container assistant-turn chat-late-workflow-outcome';
    card.setAttribute('role', 'status');
    card.setAttribute('aria-live', 'polite');
    card.dataset.conversationObservationId = observation.observation_id;
    card.dataset.sessionId = sessionId;

    const header = document.createElement('div');
    header.className = 'message-header chat-late-workflow-outcome-header';
    header.textContent = 'Workflow update';
    const observedAt = String(
        observation.completed_at || observation.observed_at_utc || ''
    ).trim();
    if (observedAt) {
        header.textContent += ` • ${formatChatTimestamp(observedAt)}`;
        setUnambiguousTimestampTooltip(header, observedAt, 'Observed: ');
    }

    const lead = document.createElement('p');
    lead.className = 'chat-late-workflow-outcome-lead';
    lead.textContent = _lateWorkflowOutcomeLead(observation);

    const qualification = document.createElement('p');
    qualification.className = 'chat-late-workflow-outcome-qualification';
    qualification.textContent = (
        observation.domain_postcondition_status === 'verified'
            ? 'The linked requested postconditions were canonically verified.'
            : 'This confirms the workflow execution status only; it does not by itself prove every requested knowledge change.'
    );

    const details = document.createElement('details');
    details.className = 'chat-late-workflow-outcome-details';
    const summary = document.createElement('summary');
    summary.textContent = 'Exact outcome details';
    details.appendChild(summary);
    const fields = document.createElement('dl');
    fields.className = 'chat-situation-observation-fields';
    [
        'terminal_status',
        'effect_status',
        'domain_postcondition_status',
        'workflow_id',
        'instance_id',
        'request_id',
        'effect_id',
        'completed_at',
        'execution_trace_id'
    ].forEach((key) => {
        _appendConversationSituationDefinitionRow(
            fields,
            _humaniseConversationSituationField(key),
            observation[key],
            key
        );
    });
    details.appendChild(fields);

    const message = document.createElement('div');
    message.className = 'chat-message-text';
    message.appendChild(lead);
    message.appendChild(qualification);
    message.appendChild(details);

    card.appendChild(header);
    card.appendChild(message);
    return card;
}

function _renderLateWorkflowOutcomesForActiveSession() {
    const sid = normaliseHistorySessionId(activeChatSessionId);
    const scrollableField = document.getElementById('scrollableField');
    if (!sid || !scrollableField) {
        return 0;
    }
    if (displayedHistorySessionId && displayedHistorySessionId !== sid) {
        return 0;
    }
    const state = conversationSituationStateBySession.get(sid);
    const observations = Array.isArray(state?.observations) ? state.observations : [];
    const existingIds = new Set(
        Array.from(
            scrollableField.querySelectorAll('[data-conversation-observation-id]')
        ).map(element => String(element.dataset.conversationObservationId || '').trim())
            .filter(Boolean)
    );
    let appended = 0;
    observations.forEach((observation) => {
        if (
            observation?.kind !== 'durable_workflow_terminal'
            || !observation.observation_id
            || existingIds.has(observation.observation_id)
        ) {
            return;
        }
        scrollableField.appendChild(_renderLateWorkflowOutcome(observation, sid));
        existingIds.add(observation.observation_id);
        appended += 1;
    });
    if (appended > 0) {
        updateScrollToEndButtonVisibility(scrollableField);
    }
    return appended;
}

function _renderConversationSituationForActiveSession() {
    const body = document.getElementById('conversationSituationBody');
    const status = document.getElementById('conversationSituationStatus');
    const badge = document.getElementById('conversationSituationBadge');
    const refreshButton = document.getElementById('conversationSituationRefreshBtn');
    const copyButton = document.getElementById('conversationSituationCopyBtn');
    if (!body) {
        return;
    }
    body.textContent = '';

    const sid = normaliseHistorySessionId(activeChatSessionId);
    const state = sid ? conversationSituationStateBySession.get(sid) : null;
    const revision = _normaliseConversationSituationInteger(state?.situation?.revision);
    const retainedCount = _normaliseConversationSituationInteger(
        state?.observationState?.retained_count,
        state?.observations?.length || 0
    );
    const hasCarrierContent = Boolean(state?.situation || retainedCount > 0);
    const isBusy = Boolean(
        sid
        && (!state || ['loading', 'refreshing'].includes(state.availability))
    );

    body.setAttribute('aria-busy', String(isBusy));
    if (status) {
        if (!sid) {
            status.textContent = '';
        } else if (!state || state.availability === 'loading') {
            status.textContent = state?.notice || 'Loading the shared situation…';
        } else if (state.availability === 'refreshing') {
            status.textContent = state.notice || 'Refreshing the shared situation…';
        } else if (
            state.availability === 'stale'
            || state.availability === 'unavailable'
        ) {
            status.textContent = (
                state.notice
                || 'The shared situation is temporarily unavailable.'
            );
        } else {
            status.textContent = state.notice || '';
        }
    }

    if (badge) {
        if (hasCarrierContent) {
            badge.textContent = revision > 0 ? `r${revision}` : String(retainedCount);
            badge.classList.remove('hidden');
            badge.title = revision > 0
                ? `Conversation situation revision ${revision}`
                : `${retainedCount} retained observations`;
        } else {
            badge.textContent = '';
            badge.classList.add('hidden');
            badge.removeAttribute('title');
        }
    }
    if (refreshButton) {
        refreshButton.disabled = !sid || ['loading', 'refreshing'].includes(state?.availability);
    }
    if (copyButton) {
        copyButton.disabled = !sid || !state || state.availability === 'loading';
    }

    if (!sid) {
        const empty = document.createElement('p');
        empty.className = 'chat-situation-empty';
        empty.textContent = 'Select or start a conversation to inspect its shared situation.';
        body.appendChild(empty);
        return;
    }

    if (!state || state.availability === 'loading') {
        const loading = document.createElement('p');
        loading.className = 'chat-situation-notice';
        loading.textContent = state?.notice || 'Loading the shared situation…';
        body.appendChild(loading);
        return;
    }

    if (state.availability === 'refreshing') {
        const refreshing = document.createElement('p');
        refreshing.className = 'chat-situation-notice';
        refreshing.textContent = state.notice || 'Refreshing the shared situation…';
        body.appendChild(refreshing);
    } else if (state.availability === 'stale' || state.availability === 'unavailable') {
        const warning = document.createElement('p');
        warning.className = 'chat-situation-notice is-warning';
        warning.textContent = state.notice || 'The shared situation is temporarily unavailable.';
        body.appendChild(warning);
    }

    const situation = state.situation;
    if (situation?.text) {
        const textSection = document.createElement('section');
        const label = document.createElement('h4');
        label.className = 'chat-situation-section-label';
        label.textContent = 'Current description';
        const text = document.createElement('pre');
        text.className = 'chat-situation-text';
        text.textContent = situation.text;
        textSection.appendChild(label);
        textSection.appendChild(text);
        body.appendChild(textSection);
    } else {
        const empty = document.createElement('p');
        empty.className = 'chat-situation-empty';
        empty.textContent = revision > 0
            ? 'This conversation currently has no situation description; the prior description was cleared.'
            : 'No shared situation description has been recorded for this conversation yet.';
        body.appendChild(empty);
    }

    if (situation) {
        const metadataSection = document.createElement('section');
        const label = document.createElement('h4');
        label.className = 'chat-situation-section-label';
        label.textContent = 'Revision and provenance';
        const metadata = document.createElement('dl');
        metadata.className = 'chat-situation-metadata';
        _appendConversationSituationDefinitionRow(
            metadata,
            'Revision',
            situation.revision,
            'revision'
        );
        _appendConversationSituationDefinitionRow(metadata, 'Source', situation.source, 'source');
        _appendConversationSituationDefinitionRow(
            metadata,
            'Updated by',
            situation.updated_by,
            'updated_by'
        );
        _appendConversationSituationDefinitionRow(
            metadata,
            'Updated',
            situation.updated_at,
            'updated_at'
        );
        _appendConversationSituationDefinitionRow(
            metadata,
            'Source request',
            situation.source_request_id,
            'source_request_id'
        );
        metadataSection.appendChild(label);
        metadataSection.appendChild(metadata);
        body.appendChild(metadataSection);
    }

    const observations = Array.isArray(state.observations) ? state.observations : [];
    const observationState = state.observationState
        || _normaliseConversationObservationState(null, observations.length);
    const details = document.createElement('details');
    details.className = 'chat-situation-observations';
    const summary = document.createElement('summary');
    summary.textContent = `Recent exact observations (${observationState.retained_count})`;
    const summaryMeta = document.createElement('span');
    summaryMeta.className = 'chat-situation-observation-summary-meta';
    summaryMeta.textContent = `${observationState.total_count} total · limit ${observationState.retention_limit}`;
    summary.appendChild(summaryMeta);
    details.appendChild(summary);

    const observationList = document.createElement('div');
    observationList.className = 'chat-situation-observation-list';
    if (observationState.omitted_count > 0) {
        const omission = document.createElement('p');
        omission.className = 'chat-situation-observation-omission';
        omission.textContent = `${observationState.omitted_count} older observation${observationState.omitted_count === 1 ? ' was' : 's were'} omitted by retention.`;
        observationList.appendChild(omission);
    }
    if (observations.length === 0) {
        const empty = document.createElement('p');
        empty.className = 'chat-situation-empty';
        empty.textContent = 'No exact observations are currently retained.';
        observationList.appendChild(empty);
    } else {
        observations.forEach(observation => {
            observationList.appendChild(_renderConversationObservation(observation));
        });
    }
    details.appendChild(observationList);
    body.appendChild(details);
}

function _buildConversationSituationExportPayload(sessionId = activeChatSessionId) {
    const sid = normaliseHistorySessionId(sessionId);
    const state = sid ? conversationSituationStateBySession.get(sid) : null;
    return {
        schema_version: CONVERSATION_SITUATION_EXPORT_SCHEMA_VERSION,
        generated_at_utc: new Date().toISOString(),
        session_id: sid,
        session_name: sid === activeChatSessionId ? activeChatSessionName : null,
        availability: state?.availability || 'unavailable',
        conversation_situation: state?.situation || null,
        conversation_observations: state?.observations || [],
        conversation_observation_state: state?.observationState || null
    };
}

async function _copyActiveConversationSituation(button) {
    if (!(button instanceof HTMLButtonElement)) {
        return false;
    }
    const payload = _buildConversationSituationExportPayload();
    return copyJsonTextWithButtonFeedback(
        button,
        JSON.stringify(payload, null, 2),
        { fallbackLabel: 'Copy JSON' }
    );
}

async function refreshConversationSituationForSession(sessionId = activeChatSessionId) {
    const sid = normaliseHistorySessionId(sessionId);
    if (!sid) {
        _renderConversationSituationForActiveSession();
        return false;
    }

    const requestId = ++conversationSituationRefreshRequestCounter;
    _markConversationSituationLoading(sid, 'Refreshing the shared situation…');
    try {
        await _ensureInviteSessionContext();
        const userContext = getUserContext();
        const params = new URLSearchParams({
            session_id: sid,
            segments: '1',
            segment_size: '1',
            tail_limit: '1',
            include_debug: '0'
        });
        if (userContext?.user_id) {
            params.append('user_id', userContext.user_id);
        }
        const response = await fetch(`/von/history?${params.toString()}`, {
            headers: buildChatFetchHeaders()
        });
        const data = await response.json().catch(() => ({}));
        if (requestId !== conversationSituationRefreshRequestCounter) {
            return false;
        }
        if (!response.ok || data?.degraded === true || data?.authenticated === false) {
            const message = data?.authenticated === false
                ? 'Sign in to inspect this conversation situation.'
                : describeHistoryUnavailable(data);
            _markConversationSituationUnavailable(sid, message);
            return false;
        }
        if (!_conversationSituationPayloadHasCompleteCarrierState(data)) {
            _markConversationSituationUnavailable(
                sid,
                'The server did not return conversation situation state; try refreshing again.'
            );
            return false;
        }
        return Boolean(_acceptConversationSituationPayload(data, sid, {
            authoritativeSnapshot: true,
            notice: 'Conversation situation refreshed.'
        }));
    } catch (error) {
        if (requestId !== conversationSituationRefreshRequestCounter) {
            return false;
        }
        _markConversationSituationUnavailable(
            sid,
            'The shared situation could not be refreshed; try again.'
        );
        console.warn('[chatTab] Unable to refresh conversation situation:', error);
        return false;
    }
}

function _clearConversationSituationState(options = {}) {
    conversationSituationRefreshRequestCounter += 1;
    conversationSituationStateBySession.clear();
    if (options.closePanel === true) {
        _setConversationSituationPanelOpen(false);
    }
    _renderConversationSituationForActiveSession();
}

function initializeConversationSituationPanel() {
    const toggle = document.getElementById('conversationSituationToggleBtn');
    const closeButton = document.getElementById('conversationSituationCloseBtn');
    const refreshButton = document.getElementById('conversationSituationRefreshBtn');
    const copyButton = document.getElementById('conversationSituationCopyBtn');
    if (!toggle || toggle.dataset.situationPanelWired === 'true') {
        _renderConversationSituationForActiveSession();
        return;
    }
    toggle.dataset.situationPanelWired = 'true';
    toggle.addEventListener('click', () => {
        const willOpen = toggle.getAttribute('aria-expanded') !== 'true';
        _setConversationSituationPanelOpen(willOpen);
        _renderConversationSituationForActiveSession();
        if (willOpen && activeChatSessionId) {
            void refreshConversationSituationForSession(activeChatSessionId);
        }
        if (willOpen) {
            document.getElementById('conversationSituationPanel')?.focus({
                preventScroll: true
            });
        }
    });
    closeButton?.addEventListener('click', () => {
        _setConversationSituationPanelOpen(false);
        toggle.focus();
    });
    refreshButton?.addEventListener('click', () => {
        void refreshConversationSituationForSession(activeChatSessionId);
    });
    copyButton?.addEventListener('click', () => {
        void _copyActiveConversationSituation(copyButton);
    });
    document.addEventListener('keydown', (event) => {
        if (
            event.key === 'Escape'
            && toggle.getAttribute('aria-expanded') === 'true'
        ) {
            _setConversationSituationPanelOpen(false);
            toggle.focus();
        }
    });
    _renderConversationSituationForActiveSession();
}

function updateSessionHistoryCache(sessionId, history, meta = {}) {
    const sid = String(sessionId || '').trim();
    if (!sid || !Array.isArray(history)) {
        return;
    }
    sessionHistoryCache.set(sid, {
        session_id: sid,
        history,
        message_count: meta.message_count ?? null,
        last_message_at: meta.last_message_at ?? null,
        segments: meta.segments ?? null,
        total_segments: meta.total_segments ?? null,
        cached_at_ms: Date.now()
    });
}

function getSessionHistoryCache(sessionId) {
    const sid = String(sessionId || '').trim();
    if (!sid) {
        return null;
    }
    return sessionHistoryCache.get(sid) || null;
}

function canReuseSessionHistory(sessionId) {
    const sid = String(sessionId || '').trim();
    if (!sid) {
        return false;
    }
    if (getLiveChatRequestForSession(sid) || getFinishedThinkingCardForSession(sid)) {
        return false;
    }
    const cached = getSessionHistoryCache(sid);
    if (!cached) {
        return false;
    }
    const sessionMeta = sessionTabsCache.find(
        session => String(session?.session_id || '') === sid
    );
    if (!sessionMeta) {
        return false;
    }
    const cachedCount = cached.message_count;
    const cachedLast = cached.last_message_at;
    const currentCount = sessionMeta.message_count;
    const currentLast = sessionMeta.last_message_at;
    if (cachedCount == null || cachedLast == null || currentCount == null || currentLast == null) {
        return false;
    }
    return cachedCount === currentCount && cachedLast === currentLast;
}

function rehydrateFromCache(scrollableField, cached) {
    if (!scrollableField || !cached || !Array.isArray(cached.history)) {
        return false;
    }
    historySegmentsShown = Number.isInteger(cached.segments) && cached.segments > 0 ? cached.segments : 1;
    totalHistorySegments = Number.isInteger(cached.total_segments) && cached.total_segments > 0
        ? cached.total_segments
        : historySegmentsShown;
    rehydrateHistory(scrollableField, cached.history, {
        scrollToBottom: true,
        preserveScroll: false,
        showResetNotice: false,
        forceScrollToBottom: true
    });
    updateHistoryBanner();
    return true;
}

function normaliseHistorySessionId(sessionId) {
    return (typeof sessionId === 'string' && sessionId.trim())
        ? sessionId.trim()
        : null;
}

function getChatRequestSessionKey(sessionId = null) {
    return normaliseHistorySessionId(sessionId) || LEGACY_CHAT_REQUEST_SESSION_KEY;
}

function getLiveChatRequestForSession(sessionId = activeChatSessionId) {
    return liveChatRequestsBySession.get(getChatRequestSessionKey(sessionId)) || null;
}

function hasLiveChatRequestForSession(sessionId = activeChatSessionId) {
    return Boolean(getLiveChatRequestForSession(sessionId));
}

function getFinishedThinkingCardForSession(sessionId = activeChatSessionId) {
    return finishedThinkingCardsBySession.get(getChatRequestSessionKey(sessionId)) || null;
}

function syncActiveChatRequestPointers() {
    activeChatRequest = getLiveChatRequestForSession(activeChatSessionId);
    lastFinishedThinkingCard = getFinishedThinkingCardForSession(activeChatSessionId);
}

function hasAnyLiveChatRequest() {
    return liveChatRequestsBySession.size > 0;
}

function shouldDeferWorkflowStatusSnapshotRefresh({ silent = false } = {}) {
    return Boolean(silent) && hasAnyLiveChatRequest();
}

function isLiveChatRequest(request) {
    if (!request || typeof request !== 'object') {
        return false;
    }
    return liveChatRequestsBySession.get(request.sessionKey) === request;
}

function isRequestInActiveChatSession(request) {
    if (!request || typeof request !== 'object') {
        return false;
    }
    const organisationGeneration = Number.isInteger(request.organisationGeneration)
        ? request.organisationGeneration
        : chatOrganisationGeneration;
    return isChatOrganisationRequestCurrent(organisationGeneration)
        && request.sessionKey === getChatRequestSessionKey(activeChatSessionId);
}

function getQueuedChatPromptCountForSession(sessionId = activeChatSessionId) {
    const sessionKey = getChatRequestSessionKey(sessionId);
    return queuedChatPrompts.filter((entry) => entry?.sessionKey === sessionKey).length;
}

function getQueuedChatPromptSubmissionInFlight(sessionId = activeChatSessionId) {
    return queuedChatPromptSubmissionsInFlight.get(
        getChatRequestSessionKey(sessionId)
    ) || null;
}

function isRestartableChatPromptQueueEntry(entry) {
    if (!entry || entry.status !== CHAT_PROMPT_QUEUE_STATUS_IN_PROGRESS) {
        return false;
    }
    if (isServerDispatchedChatPromptQueueEntry(entry)) {
        return false;
    }
    if (getLiveChatRequestForPromptQueueRecord(entry.queueId)) {
        return false;
    }
    const recordServerInstanceId = (typeof entry.serverInstanceId === 'string' && entry.serverInstanceId.trim())
        ? entry.serverInstanceId.trim()
        : null;
    if (!recordServerInstanceId) {
        return true;
    }
    return Boolean(
        chatPromptQueueAdmissionServerInstanceId
        && recordServerInstanceId !== chatPromptQueueAdmissionServerInstanceId
    );
}

function isRunningChatPromptQueueEntry(entry) {
    return Boolean(
        entry
        && entry.status === CHAT_PROMPT_QUEUE_STATUS_IN_PROGRESS
        && !isRestartableChatPromptQueueEntry(entry)
    );
}

function getChatPromptQueueCountsForSession(sessionId = activeChatSessionId) {
    const sessionKey = getChatRequestSessionKey(sessionId);
    const counts = {
        total: 0,
        running: 0,
        queued: 0,
        restartable: 0,
        failed: 0
    };
    queuedChatPrompts.forEach((entry) => {
        if (!entry || entry.sessionKey !== sessionKey || entry.enqueueFailed === true) {
            return;
        }
        counts.total += 1;
        if (entry.status === CHAT_PROMPT_QUEUE_STATUS_FAILED) {
            counts.failed += 1;
        } else if (isRestartableChatPromptQueueEntry(entry)) {
            counts.restartable += 1;
        } else if (entry.status === CHAT_PROMPT_QUEUE_STATUS_IN_PROGRESS) {
            counts.running += 1;
        } else {
            counts.queued += 1;
        }
    });
    return counts;
}

function getQueuedChatPromptSessionLabel(entry) {
    const explicitName = (typeof entry?.sessionName === 'string' && entry.sessionName.trim())
        ? entry.sessionName.trim()
        : '';
    if (explicitName) {
        return explicitName;
    }
    const sid = normaliseHistorySessionId(entry?.sessionId);
    if (!sid) {
        return 'Current conversation';
    }
    const session = sessionTabsCache.find(
        candidate => String(candidate?.session_id || '') === sid
    );
    return getSessionDisplayName(session || { session_id: sid, session_name: null });
}

function refreshChatSessionTabActivityIndicators() {
    const container = getChatSessionTabsContainer();
    if (!container || !Array.isArray(sessionTabsCache) || sessionTabsCache.length === 0) {
        return;
    }
    renderChatSessionTabs(sessionTabsCache, activeChatSessionId);
}

function invalidateSessionHistoryCache(sessionId) {
    const sid = normaliseHistorySessionId(sessionId);
    if (!sid) {
        return;
    }
    sessionHistoryCache.delete(sid);
}

function setLiveChatRequestForSession(sessionId, request = null) {
    const hadAnyLiveChatRequest = hasAnyLiveChatRequest();
    const sessionKey = getChatRequestSessionKey(sessionId);
    if (request && typeof request === 'object') {
        request.sessionId = normaliseHistorySessionId(sessionId);
        request.sessionKey = sessionKey;
        liveChatRequestsBySession.set(sessionKey, request);
    } else {
        liveChatRequestsBySession.delete(sessionKey);
    }
    syncActiveChatRequestPointers();
    refreshChatSessionTabActivityIndicators();
    if (
        hadAnyLiveChatRequest
        && !request
        && !hasAnyLiveChatRequest()
    ) {
        scheduleWorkflowStatusLiveRefresh();
    }
}

function setFinishedThinkingCardForSession(sessionId, request = null) {
    const sessionKey = getChatRequestSessionKey(sessionId);
    if (request && typeof request === 'object') {
        request.sessionId = normaliseHistorySessionId(sessionId);
        request.sessionKey = sessionKey;
        finishedThinkingCardsBySession.set(sessionKey, request);
    } else {
        finishedThinkingCardsBySession.delete(sessionKey);
    }
    syncActiveChatRequestPointers();
    refreshChatSessionTabActivityIndicators();
}

function getExternalConversationMetadata(sessionId = activeChatSessionId) {
    const sid = normaliseHistorySessionId(sessionId);
    if (!sid) {
        return null;
    }
    if (sid === activeChatSessionId && activeExternalConversationMetadata?.read_only === true) {
        return activeExternalConversationMetadata;
    }
    const session = sessionTabsCache.find(
        candidate => normaliseHistorySessionId(candidate?.session_id) === sid
    );
    const metadata = session?.external_conversation;
    return metadata && typeof metadata === 'object' && metadata.read_only === true
        ? metadata
        : null;
}

function isExternalConversationReadOnly(sessionId = activeChatSessionId) {
    return getExternalConversationMetadata(sessionId)?.read_only === true;
}

function updateExternalConversationUi() {
    const metadata = getExternalConversationMetadata();
    const readOnly = metadata?.read_only === true;
    const promptInput = document.getElementById('promptInput');
    const continueButton = document.getElementById('continueImportedConversationBtn');
    const resetButton = document.getElementById('resetButton');
    const uploadButton = document.getElementById('uploadFileButton');
    const dictateButton = document.getElementById('dictateButton');

    if (continueButton) {
        continueButton.classList.toggle('hidden', !readOnly);
        continueButton.disabled = !readOnly;
    }
    if (promptInput) {
        if (!promptInput.dataset.nativePlaceholder) {
            promptInput.dataset.nativePlaceholder = promptInput.getAttribute('placeholder') || 'Talk with Von here...';
        }
        promptInput.disabled = readOnly;
        promptInput.setAttribute(
            'placeholder',
            readOnly
                ? 'Imported snapshot — choose Continue to add new turns.'
                : promptInput.dataset.nativePlaceholder
        );
    }
    [resetButton, uploadButton, dictateButton].forEach((button) => {
        if (button) {
            button.disabled = readOnly;
        }
    });
    // Session-list refreshes also pass through this function. Reapply the
    // stronger concept-Q&A lifecycle state so a finished or cancelled Q&A is
    // not made editable just because it is an ordinary (non-imported) chat.
    updateConceptQaComposerUi();
    updateSendButtonForCurrentChatState();
}

function updateSendButtonForCurrentChatState() {
    const sendButton = document.getElementById('sendButton');
    if (!sendButton) {
        return;
    }
    const chatCreationInFlight = Boolean(newChatCreationInFlight);
    const uploadInFlight = !!getInFlightUploadStateForSession(activeChatSessionId);
    const queueSubmissionInFlight = !!getQueuedChatPromptSubmissionInFlight(
        activeChatSessionId
    );
    const queueCounts = getChatPromptQueueCountsForSession(activeChatSessionId);
    const sessionBusy = hasLiveChatRequestForSession(activeChatSessionId)
        || queueCounts.running > 0
        || queueCounts.queued > 0
        || queueCounts.restartable > 0;
    const readOnly = isExternalConversationReadOnly();
    const conceptQaSession = getConceptQaSessionForChat();
    const conceptQaBusy = Boolean(
        conceptQaSession
        && (
            conceptQaSubmitInFlight.has(conceptQaSession.session_id)
            || conceptQaTransitionInFlight.has(conceptQaSession.session_id)
        )
    );
    const conceptQaTerminal = Boolean(conceptQaSession && conceptQaSession.lifecycle !== 'active');
    const conceptQaAwaitingInitialQuestion = Boolean(
        conceptQaSession
        && conceptQaSession.lifecycle === 'active'
        && !conceptQaActionAllowed(conceptQaSession, 'submit_turn')
    );
    sendButton.disabled = chatCreationInFlight
        || uploadInFlight
        || queueSubmissionInFlight
        || readOnly
        || conceptQaBusy
        || conceptQaTerminal
        || conceptQaAwaitingInitialQuestion;
    sendButton.setAttribute(
        'aria-busy',
        chatCreationInFlight || queueSubmissionInFlight || conceptQaBusy ? 'true' : 'false'
    );
    if (chatCreationInFlight) {
        sendButton.textContent = 'Creating conversation…';
        sendButton.title = 'Waiting for the new conversation to be ready.';
        return;
    }
    if (readOnly) {
        sendButton.textContent = 'Read-only import';
        sendButton.title = 'Continue this imported snapshot before sending a new message.';
        return;
    }
    if (conceptQaSession) {
        if (conceptQaTerminal) {
            sendButton.textContent = `Q&A ${conceptQaSession.lifecycle}`;
        } else if (conceptQaAwaitingInitialQuestion) {
            sendButton.textContent = 'Retry question first';
        } else {
            sendButton.textContent = conceptQaBusy ? 'Saving Q&A…' : 'Submit answer';
        }
        if (conceptQaAwaitingInitialQuestion) {
            sendButton.title = 'Return to the concept card and retry the initial question before answering.';
            return;
        }
        sendButton.title = conceptQaTerminal
            ? 'The transcript remains available, but this concept Q&A no longer accepts turns.'
            : (conceptQaBusy ? 'Saving this turn and its representation receipts.' : 'Submit this answer to concept Q&A.');
        return;
    }
    sendButton.textContent = queueSubmissionInFlight
        ? 'Queueing…'
        : (sessionBusy ? 'Queue Prompt' : 'Send Prompt');
    if (queueSubmissionInFlight) {
        sendButton.title = 'Saving this prompt to the conversation queue.';
    } else if (uploadInFlight) {
        sendButton.title = ATTACHMENT_UPLOAD_SEND_BLOCK_MESSAGE;
    } else {
        sendButton.removeAttribute('title');
    }
}

function syncActiveChatSessionThinkingState() {
    syncActiveChatRequestPointers();

    if (activeChatRequest) {
        setThinkingState(true, activeChatRequest, { resetDisplayState: false });
        refreshThinkingCardProgressUi(activeChatRequest);
        updateSendButtonForCurrentChatState();
        return;
    }

    if (lastFinishedThinkingCard) {
        let renderedInline = false;
        if (typeof lastFinishedThinkingCard.resultTurnId === 'string' && lastFinishedThinkingCard.resultTurnId) {
            renderedInline = renderRetainedThinkingCardForTurn(
                lastFinishedThinkingCard,
                lastFinishedThinkingCard.resultTurnId
            );
        }
        if (renderedInline) {
            setThinkingState(false, null);
        } else {
            setThinkingState(false, lastFinishedThinkingCard, {
                preserveFinishedCard: true,
                resetDisplayState: false
            });
            refreshThinkingCardProgressUi(lastFinishedThinkingCard);
        }
        updateSendButtonForCurrentChatState();
        return;
    }

    setThinkingState(false, null);
    updateSendButtonForCurrentChatState();
}

function clearHistoryLoadState({ sessionId = null } = {}) {
    const normalisedSessionId = normaliseHistorySessionId(sessionId);
    if (
        normalisedSessionId
        && historyLoadState.sessionId
        && historyLoadState.sessionId !== normalisedSessionId
    ) {
        return;
    }
    historyLoadState.degraded = false;
    historyLoadState.message = '';
    historyLoadState.retryable = false;
    historyLoadState.detail = '';
    historyLoadState.sessionId = null;
}

function describeHistoryUnavailable(data, fallbackMessage = '') {
    const reason = (typeof data?.history_unavailable_reason === 'string')
        ? data.history_unavailable_reason.trim()
        : '';
    if (reason === 'not_authenticated') {
        return 'Sign in to load conversation history.';
    }
    if (reason === 'not_authorised') {
        return 'This conversation is not available for the selected user or organisation.';
    }
    if (reason === 'transient_chat_history_error') {
        return 'Conversation history storage is temporarily unavailable; please retry.';
    }
    if (typeof data?.error === 'string' && data.error.trim()) {
        return data.error.trim();
    }
    return (typeof fallbackMessage === 'string' && fallbackMessage.trim())
        ? fallbackMessage.trim()
        : 'Conversation history temporarily unavailable; please retry.';
}

function setHistoryLoadState({
    sessionId = null,
    message = '',
    retryable = false,
    detail = ''
} = {}) {
    historyLoadState.degraded = true;
    historyLoadState.message = (typeof message === 'string' && message.trim())
        ? message.trim()
        : 'Conversation history temporarily unavailable; please retry.';
    historyLoadState.retryable = Boolean(retryable);
    historyLoadState.detail = (typeof detail === 'string' && detail.trim())
        ? detail.trim()
        : '';
    historyLoadState.sessionId = normaliseHistorySessionId(sessionId);
}

function isHistoryLoadStateActiveForSession(sessionId = null) {
    if (!historyLoadState.degraded) {
        return false;
    }
    const normalisedSessionId = normaliseHistorySessionId(sessionId);
    if (!normalisedSessionId || !historyLoadState.sessionId) {
        return historyLoadState.degraded;
    }
    return historyLoadState.sessionId === normalisedSessionId;
}

function shouldPreserveRenderedHistoryForSession(scrollableField, sessionId) {
    const normalisedSessionId = normaliseHistorySessionId(sessionId);
    if (!scrollableField || !normalisedSessionId || displayedHistorySessionId !== normalisedSessionId) {
        return false;
    }
    return Boolean(scrollableField.querySelector('.message-container'));
}

async function refreshToolUseDuringThinkingSetting(force = false) {
    const now = Date.now();
    if (!force && now - lastToolUseSettingRefreshMs < TOOL_USE_SETTING_REFRESH_COOLDOWN_MS) {
        return showToolUseDuringThinkingSetting;
    }

    lastToolUseSettingRefreshMs = now;
    try {
        const resp = await fetch('/api/settings/', { method: 'GET' });
        if (!resp || !resp.ok) {
            return showToolUseDuringThinkingSetting;
        }
        const data = await resp.json();
        if (data && typeof data.show_tool_use_during_thinking !== 'undefined') {
            showToolUseDuringThinkingSetting = !!data.show_tool_use_during_thinking;
            if (!showToolUseDuringThinkingSetting) {
                liveChatRequestsBySession.forEach((request) => {
                    stopToolUseProgressPolling(request);
                });
                setLoadingIndicatorText(DEFAULT_THINKING_TEXT);
            }
        }
    } catch (_) {
        // Ignore.
    }
    return showToolUseDuringThinkingSetting;
}

function toTitleCaseWords(value) {
    const text = String(value ?? '').trim();
    if (!text) {
        return '';
    }
    return text
        .split(/[_\s]+/)
        .filter(Boolean)
        .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
        .join(' ');
}

function normaliseThinkingLivenessState(progress) {
    const value = (progress && typeof progress.liveness_state === 'string')
        ? progress.liveness_state.trim().toLowerCase()
        : '';
    if (value === THINKING_STATUS_STALLED) {
        return THINKING_STATUS_STALLED;
    }
    if (value === THINKING_STATUS_WAITING) {
        return THINKING_STATUS_WAITING;
    }
    return THINKING_STATUS_ACTIVE;
}

function thinkingLivenessLabel(state) {
    if (state === THINKING_STATUS_STALLED) return 'Stalled';
    if (state === THINKING_STATUS_WAITING) return 'Waiting';
    return 'Active';
}

function thinkingTerminalLabel(status) {
    if (status === THINKING_STATUS_COMPLETED) return 'Complete';
    if (status === THINKING_STATUS_FOLLOW_UP_REQUIRED) return 'Follow-up required';
    if (status === THINKING_STATUS_FAILED) return 'Failed';
    if (status === THINKING_STATUS_CANCELLED) return 'Cancelled';
    if (status === THINKING_STATUS_TERMINATED) return 'Terminated';
    return 'Complete';
}

function formatAbsoluteTimestamp(value) {
    if (!value) {
        return '';
    }
    const parsed = new Date(value);
    if (Number.isNaN(parsed.getTime())) {
        return '';
    }
    try {
        return new Intl.DateTimeFormat('en-NZ', {
            year: 'numeric',
            month: 'short',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            hour12: false,
            timeZoneName: 'shortOffset'
        }).format(parsed);
    } catch (_) {
        return parsed.toISOString();
    }
}

function setUnambiguousTimestampTooltip(element, value, prefix = '') {
    if (!(element instanceof Element)) {
        return;
    }
    const absoluteLabel = formatAbsoluteTimestamp(value);
    if (!absoluteLabel) {
        element.removeAttribute('title');
        element.removeAttribute('aria-label');
        element.removeAttribute('data-original-title');
        return;
    }
    const tooltip = prefix ? `${prefix}${absoluteLabel}` : absoluteLabel;
    element.setAttribute('data-keep-title', 'true');
    element.setAttribute('title', tooltip);
    element.setAttribute('aria-label', tooltip);
    element.setAttribute('data-original-title', tooltip);
}

function resolveLastActivityTimestampMs(progress) {
    if (!progress || typeof progress !== 'object') {
        return null;
    }
    if (typeof progress.last_activity_at_utc === 'string' && progress.last_activity_at_utc.trim()) {
        const parsed = Date.parse(progress.last_activity_at_utc);
        if (Number.isFinite(parsed)) {
            return parsed;
        }
    }
    let idleMs = null;
    if (Number.isFinite(progress.activity_idle_ms)) {
        idleMs = Number(progress.activity_idle_ms);
    } else if (Number.isFinite(progress.idle_ms)) {
        idleMs = Number(progress.idle_ms);
    }
    if (!Number.isFinite(idleMs)) {
        return null;
    }
    return Date.now() - Math.max(0, Number(idleMs));
}

function formatLastActivityText(progress) {
    if (!progress || typeof progress !== 'object') {
        return null;
    }

    const lastActivityMs = resolveLastActivityTimestampMs(progress);
    if (!Number.isFinite(lastActivityMs)) {
        return null;
    }

    const safeIdleMs = Math.max(0, Date.now() - Number(lastActivityMs));
    return `Last activity ${formatThinkingDuration(safeIdleMs)} ago`;
}

function resolveThinkingEtaMs(progress) {
    if (!progress || typeof progress !== 'object') {
        return null;
    }
    if (Number.isFinite(progress.eta_ms)) {
        return Math.max(0, Number(progress.eta_ms));
    }
    if (Number.isFinite(progress.eta_seconds)) {
        return Math.max(0, Number(progress.eta_seconds) * 1000);
    }
    return null;
}

function formatThinkingEtaText(progress) {
    const etaMs = resolveThinkingEtaMs(progress);
    if (!Number.isFinite(etaMs)) {
        return null;
    }
    if (etaMs < 1000) {
        return 'ETA <1s';
    }
    const roundedMs = Math.ceil(etaMs / 1000) * 1000;
    return `ETA ~${formatThinkingDuration(roundedMs)}`;
}

function normaliseThinkingComparisonText(value) {
    return normaliseThinkingActivityString(value)
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase();
}

function normaliseThinkingSynopsisIdentity(value) {
    const normalised = normaliseThinkingComparisonText(value);
    const wrappedUserRequest = normalised.match(/^user request:\s*(?:"(.*)"|“(.*)”)$/);
    return wrappedUserRequest
        ? normaliseThinkingComparisonText(wrappedUserRequest[1] ?? wrappedUserRequest[2])
        : normalised;
}

function shouldDistinguishThinkingRequestAndStep(promptRaw, goalLabel) {
    const prompt = normaliseThinkingComparisonText(promptRaw);
    const goal = normaliseThinkingComparisonText(goalLabel);
    return Boolean(
        prompt
        && goal
        && prompt !== goal
        && !prompt.includes(goal)
        && !goal.includes(prompt)
    );
}

function buildThinkingGoalPrefix(goalLabel, request = null) {
    const cleanGoal = truncateThinkingCardSummary(goalLabel, 180);
    if (!cleanGoal) {
        return '';
    }
    const cleanPrompt = truncateThinkingCardSummary(request?.promptRaw, 140);
    if (shouldDistinguishThinkingRequestAndStep(cleanPrompt, cleanGoal)) {
        return `Request: ${cleanPrompt} | Step: ${cleanGoal}`;
    }
    return `Goal: ${cleanGoal}`;
}

function buildThinkingProgressPresentation(progress, request = null) {
    const terminalStatus = resolveThinkingTerminalStatus(progress);
    const livenessState = terminalStatus || normaliseThinkingLivenessState(progress);
    const livenessLabel = terminalStatus
        ? thinkingTerminalLabel(terminalStatus)
        : thinkingLivenessLabel(livenessState);

    if (!progress || typeof progress !== 'object') {
        return {
            livenessState,
            livenessLabel,
            stageText: DEFAULT_THINKING_TEXT,
            lastActivityText: null
        };
    }

    const stage = (typeof progress.stage === 'string' && progress.stage.trim())
        ? progress.stage.trim()
        : ((typeof progress.phase === 'string' && progress.phase.trim()) ? progress.phase.trim() : null);
    const phaseLabel = (typeof progress.phase_label === 'string' && progress.phase_label.trim())
        ? progress.phase_label.trim()
        : null;
    const stageLabel = (typeof progress.stage_label === 'string' && progress.stage_label.trim())
        ? progress.stage_label.trim()
        : null;
    const goalLabel = (typeof progress.goal_label === 'string' && progress.goal_label.trim())
        ? progress.goal_label.trim()
        : null;
    const tool = (typeof progress.tool === 'string' && progress.tool.trim()) ? progress.tool.trim() : null;
    const resultSummary = (typeof progress.result_summary === 'string' && progress.result_summary.trim())
        ? progress.result_summary.trim()
        : null;
    let subtask = (typeof progress.subtask === 'string' && progress.subtask.trim())
        ? progress.subtask.trim()
        : ((typeof progress.workflow_task === 'string' && progress.workflow_task.trim()) ? progress.workflow_task.trim() : null);
    const workflowDiscovery = (progress.workflow_discovery && typeof progress.workflow_discovery === 'object')
        ? progress.workflow_discovery
        : ((request?.workflowDiscovery && typeof request.workflowDiscovery === 'object') ? request.workflowDiscovery : null);
    const routingNarrative = buildWorkflowRoutingNarrative(progress, workflowDiscovery, {
        includeNoMatchTransition: true,
    });

    if ((stage === 'workflow_dispatch' || stage === 'plain_response') && !subtask) {
        subtask = routingNarrative.text || subtask;
    } else if (stage === 'workflow_discovery_complete') {
        const matchCount = getWorkflowDiscoveryMatchCount(workflowDiscovery);
        const candidateCount = getWorkflowDiscoveryCandidateCount(workflowDiscovery);
        if (matchCount === 0 && routingNarrative.context.hasSelection) {
            subtask = routingNarrative.text;
        } else if (matchCount === 0 && candidateCount > 0) {
            const primaryCandidate = normaliseWorkflowDiscoveryCandidates(workflowDiscovery)[0] || null;
            const primaryCandidateLabel = formatWorkflowDisplayText(
                primaryCandidate?.concept_id,
                primaryCandidate?.name,
                workflowDiscovery
            );
            subtask = primaryCandidateLabel
                ? `Candidate found: ${primaryCandidateLabel}`
                : 'Relevant workflow candidates found';
        } else if (matchCount === 0) {
            subtask = 'No direct workflow match found';
        } else if (matchCount > 0 && !subtask) {
            const primaryMatch = normaliseWorkflowDiscoveryMatches(workflowDiscovery)[0] || null;
            subtask = formatWorkflowDisplayText(
                primaryMatch?.concept_id,
                primaryMatch?.name,
                workflowDiscovery
            ) || subtask;
        }
    }

    let stageText = phaseLabel || stageLabel || (stage ? toTitleCaseWords(stage) : DEFAULT_THINKING_TEXT);
    const detail = tool || subtask || resultSummary;
    if (detail && !stageText.toLowerCase().includes(detail.toLowerCase())) {
        stageText = `${stageText}: ${detail}`;
    }
    const goalPrefix = buildThinkingGoalPrefix(goalLabel, request);
    if (goalPrefix && !stageText.toLowerCase().includes(goalLabel.toLowerCase())) {
        stageText = stageText ? `${goalPrefix} | ${stageText}` : goalPrefix;
    }

    if (terminalStatus) {
        stageText = routingNarrative.text
            ? `${livenessLabel}: ${routingNarrative.text}`
            : livenessLabel;
    } else if (livenessState === THINKING_STATUS_STALLED) {
        stageText = stageText ? `Stalled: ${stageText}` : 'Stalled';
    } else if (livenessState === THINKING_STATUS_WAITING) {
        stageText = stageText ? `Waiting: ${stageText}` : 'Waiting';
    } else if (stage && stage !== 'completed' && stage !== 'error') {
        stageText += '...';
    }

    return {
        livenessState,
        livenessLabel,
        stageText,
        lastActivityText: formatLastActivityText(progress),
        requestId: request && typeof request.clientRequestId === 'string' ? request.clientRequestId : null
    };
}

