function updateThinkingCardStatusBadge(progress, cardRoot = null) {
    const badgeEl = getThinkingCardStatusBadgeEl(cardRoot);
    if (!badgeEl) {
        return;
    }

    const presentation = buildThinkingProgressPresentation(progress);
    badgeEl.textContent = presentation.livenessLabel;
    THINKING_STATUS_CLASS_NAMES.forEach((stateClass) => badgeEl.classList.remove(stateClass));
    badgeEl.classList.add(presentation.livenessState);
    badgeEl.setAttribute('aria-hidden', 'false');
}

function formatToolUseProgressText(progress, request = null) {
    const presentation = buildThinkingProgressPresentation(progress, request);
    return presentation.stageText || DEFAULT_THINKING_TEXT;
}

function firstThinkingCardText(...values) {
    for (const value of values) {
        const cleanValue = normaliseThinkingActivityString(value);
        if (cleanValue) {
            return cleanValue;
        }
    }
    return '';
}

function truncateThinkingCardSummary(value, maxChars = 220) {
    const cleanValue = normaliseThinkingActivityString(value).replace(/\s+/g, ' ').trim();
    if (!cleanValue || cleanValue.length <= maxChars) {
        return cleanValue;
    }
    return `${cleanValue.slice(0, Math.max(0, maxChars - 3)).trimEnd()}...`;
}

function summarisePromptForThinkingCard(promptRaw, prefix = 'Prompt focus') {
    const prompt = truncateThinkingCardSummary(promptRaw, 180);
    return prompt ? `${prefix}: "${prompt}"` : '';
}

function normaliseThinkingCardSummaryList(value) {
    if (Array.isArray(value)) {
        return value
            .map((item) => normaliseThinkingActivityString(item))
            .filter(Boolean);
    }
    const singleValue = normaliseThinkingActivityString(value);
    return singleValue ? [singleValue] : [];
}

function normaliseThinkingCardSelectedWorkflow(value, workflowDiscovery = null) {
    if (!value || typeof value !== 'object') {
        return null;
    }
    const workflowId = normaliseThinkingActivityString(
        value.workflow_id || value.selected_workflow_id || value.id || value.concept_id
    ) || null;
    const workflowName = normaliseThinkingActivityString(
        value.workflow_name || value.selected_workflow_name || value.name || value.label
    ) || null;
    const label = formatWorkflowDisplayText(workflowId, workflowName, workflowDiscovery);
    if (!workflowId && !workflowName && !label) {
        return null;
    }
    return {
        workflow_id: workflowId,
        workflow_name: workflowName,
        label: label || workflowName || workflowId || null
    };
}

function findLatestNonFinalisingStageLabel(request) {
    const workflowStagePath = (request?.workflowStagePath && typeof request.workflowStagePath === 'object')
        ? request.workflowStagePath
        : null;
    const path = Array.isArray(workflowStagePath?.path)
        ? workflowStagePath.path
        : [];
    const finalisingStages = new Set(['response_finalising', 'completed', 'follow_up_required', 'error']);

    for (let index = path.length - 1; index >= 0; index -= 1) {
        const entry = path[index];
        if (!entry || typeof entry !== 'object') {
            continue;
        }
        const stageId = normaliseThinkingActivityString(entry.stage_id || entry.runtime_stage_normalised);
        if (!stageId || finalisingStages.has(stageId)) {
            continue;
        }
        return normaliseThinkingActivityString(entry.stage_label)
            || formatThinkingActivityFallbackLabel(stageId)
            || null;
    }
    return null;
}

function canonicaliseThinkingRecoveryStage(value) {
    const clean = normaliseThinkingActivityString(value)
        .replace(/[-\s]+/g, '_')
        .toLowerCase();
    if (!clean) {
        return '';
    }
    if (THINKING_RECOVERY_STAGE_IDS.has(clean)) {
        return clean;
    }
    return THINKING_RECOVERY_STAGE_ALIASES.get(clean) || '';
}

function isThinkingRecoveryStage(value) {
    return Boolean(canonicaliseThinkingRecoveryStage(value));
}

function normaliseThinkingRecoveryFailure(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }
    const stage = normaliseThinkingActivityString(value.stage);
    const failure = {
        schema_version: normaliseThinkingActivityString(value.schema_version)
            || 'thinking_recovery_failure_summary.v1',
        status: normaliseThinkingActivityString(value.status) || null,
        stage: stage || null,
        stage_label: normaliseThinkingActivityString(value.stage_label)
            || (stage ? formatThinkingActivityFallbackLabel(stage) : null),
        tool: normaliseThinkingActivityString(value.tool) || null,
        workflow_task: normaliseThinkingActivityString(value.workflow_task) || null,
        error_code: normaliseThinkingActivityString(value.error_code) || null,
        error_class: normaliseThinkingActivityString(value.error_class) || null,
        failure_kind: normaliseThinkingActivityString(value.failure_kind) || null,
        error: normaliseThinkingActivityString(value.error) || null
    };
    const hasContent = [
        failure.status,
        failure.stage,
        failure.tool,
        failure.workflow_task,
        failure.error_code,
        failure.error_class,
        failure.failure_kind,
        failure.error
    ].some(Boolean);
    return hasContent ? failure : null;
}

function normaliseThinkingPromptContextDiagnostics(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }
    const copy = { ...value };
    return Object.keys(copy).length > 0 ? copy : null;
}

function normaliseThinkingLargeLlmCallAlert(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }
    const promptCharCount = toThinkingCardOptionalNonNegativeInteger(
        value.prompt_char_count || value.max_prompt_char_count
    );
    if (promptCharCount === null || promptCharCount < THINKING_LARGE_LLM_PROMPT_CHAR_THRESHOLD) {
        return null;
    }
    const stage = normaliseThinkingActivityString(value.stage || value.stage_id);
    const alert = {
        schema_version: normaliseThinkingActivityString(value.schema_version)
            || 'thinking_large_llm_call_alert.v1',
        stage: stage || null,
        stage_label: normaliseThinkingActivityString(value.stage_label)
            || (stage ? formatThinkingActivityFallbackLabel(stage) : null),
        model: normaliseThinkingActivityString(value.model) || null,
        provider: normaliseThinkingActivityString(value.provider) || null,
        duration_ms: toThinkingCardOptionalNonNegativeInteger(value.duration_ms),
        prompt_char_count: promptCharCount,
        threshold_prompt_chars: toThinkingCardOptionalNonNegativeInteger(value.threshold_prompt_chars)
            || THINKING_LARGE_LLM_PROMPT_CHAR_THRESHOLD,
        reason: normaliseThinkingActivityString(value.reason) || 'prompt_chars_exceeded_threshold',
        call_id: normaliseThinkingActivityString(value.call_id || value.llm_call_id) || null,
        prompt_context_diagnostics: normaliseThinkingPromptContextDiagnostics(
            value.prompt_context_diagnostics
        )
    };
    return alert;
}

function normaliseThinkingLargeLlmCallAlerts(value) {
    return Array.isArray(value)
        ? value
            .map(normaliseThinkingLargeLlmCallAlert)
            .filter(Boolean)
        : [];
}

function normaliseThinkingRecoveryProgress(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }
    const latestRecoveryStage = canonicaliseThinkingRecoveryStage(
        value.latest_recovery_stage_id
    );
    const currentStage = normaliseThinkingActivityString(value.current_stage_id);
    const latestFailure = normaliseThinkingRecoveryFailure(value.latest_failure);
    const promptContextDiagnostics = normaliseThinkingPromptContextDiagnostics(
        value.prompt_context_diagnostics
    );
    const alerts = normaliseThinkingLargeLlmCallAlerts(value.large_llm_call_alerts);
    const attemptCount = toThinkingCardOptionalNonNegativeInteger(value.attempt_count);
    const recovery = {
        schema_version: normaliseThinkingActivityString(value.schema_version)
            || 'thinking_recovery_progress.v1',
        active: value.active === true || isThinkingRecoveryStage(currentStage),
        recent: value.recent === true || Boolean(latestRecoveryStage),
        finalising_after_recovery: value.finalising_after_recovery === true,
        current_stage_id: currentStage || null,
        latest_recovery_stage_id: latestRecoveryStage || null,
        latest_recovery_stage_label: normaliseThinkingActivityString(
            value.latest_recovery_stage_label
        ) || (latestRecoveryStage ? formatThinkingActivityFallbackLabel(latestRecoveryStage) : null),
        attempt_count: attemptCount,
        latest_failure: latestFailure,
        prompt_context_diagnostics: promptContextDiagnostics,
        large_llm_call_alerts: alerts
    };
    const hasContent = recovery.active
        || recovery.recent
        || recovery.finalising_after_recovery
        || Boolean(recovery.latest_recovery_stage_id)
        || Boolean(recovery.latest_failure)
        || Boolean(recovery.prompt_context_diagnostics)
        || recovery.large_llm_call_alerts.length > 0;
    return hasContent ? recovery : null;
}

function deriveThinkingRecoveryProgress(request = null) {
    const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const candidates = [
        request?.recoveryProgress,
        request?.recovery_progress,
        request?.thinking_interpretability?.recovery_progress,
        latestProgress?.recovery_progress,
        latestProgress?.thinking_interpretability?.recovery_progress,
        latestProgress?.progress_view_model?.recovery_progress
    ];
    for (const candidate of candidates) {
        const recovery = normaliseThinkingRecoveryProgress(candidate);
        if (recovery) {
            return recovery;
        }
    }
    return null;
}

function getThinkingLlmPromptCharCount(entry) {
    if (!entry || typeof entry !== 'object') {
        return null;
    }
    const direct = toThinkingCardOptionalNonNegativeInteger(
        entry.prompt_char_count || entry.max_prompt_char_count
    );
    if (direct !== null) {
        return direct;
    }
    const promptCapture = entry.prompt && typeof entry.prompt === 'object'
        ? entry.prompt
        : null;
    if (promptCapture) {
        const captureCount = toThinkingCardOptionalNonNegativeInteger(
            promptCapture.char_count || promptCapture.content_char_count
        );
        if (captureCount !== null) {
            return captureCount;
        }
        const promptText = normaliseThinkingActivityString(promptCapture.text || promptCapture.preview);
        if (promptText) {
            return promptText.length;
        }
    }
    return null;
}

function buildThinkingLargeLlmCallAlertKey(alert) {
    return [
        normaliseThinkingActivityString(alert?.call_id),
        normaliseThinkingActivityString(alert?.stage),
        normaliseThinkingActivityString(alert?.model),
        String(alert?.prompt_char_count ?? '')
    ].join('::');
}

function collectThinkingLargeLlmCallAlerts(request = null, viewModel = null) {
    const alerts = [];
    const addAlert = (candidate) => {
        const alert = normaliseThinkingLargeLlmCallAlert(candidate);
        if (alert) {
            alerts.push(alert);
        }
    };
    normaliseThinkingLargeLlmCallAlerts(viewModel?.large_llm_call_alerts).forEach(addAlert);
    normaliseThinkingLargeLlmCallAlerts(viewModel?.recovery_progress?.large_llm_call_alerts).forEach(addAlert);
    normaliseThinkingLargeLlmCallAlerts(request?.latestProgress?.large_llm_call_alerts).forEach(addAlert);
    normaliseThinkingLargeLlmCallAlerts(request?.latestProgress?.recovery_progress?.large_llm_call_alerts).forEach(addAlert);

    for (const row of getThinkingTimingRows(request)) {
        addAlert({
            stage: row.stage || row.stage_id,
            model: row.model,
            provider: row.provider,
            duration_ms: row.duration_ms,
            prompt_char_count: row.max_prompt_char_count || row.prompt_char_count
        });
    }
    for (const row of getThinkingModelPromptTimingRows(request)) {
        addAlert({
            stage: row.stage || row.stage_id,
            model: row.model,
            provider: row.provider,
            duration_ms: row.duration_ms,
            prompt_char_count: row.max_prompt_char_count || row.prompt_char_count
        });
    }

    for (const entry of collectThinkingLiveLlmCallLogEntries(request)) {
        const promptCharCount = getThinkingLlmPromptCharCount(entry);
        addAlert({
            stage: entry.stage,
            model: entry.model,
            provider: entry.provider,
            duration_ms: entry.duration_ms,
            prompt_char_count: promptCharCount,
            call_id: entry.call_id || entry.llm_call_id
        });
    }

    const seen = new Set();
    return alerts.filter((alert) => {
        const key = buildThinkingLargeLlmCallAlertKey(alert);
        if (seen.has(key)) {
            return false;
        }
        seen.add(key);
        return true;
    });
}

function formatThinkingLargeLlmCallAlert(alert) {
    const promptCharCount = toThinkingCardOptionalNonNegativeInteger(alert?.prompt_char_count);
    if (promptCharCount === null) {
        return '';
    }
    const stage = normaliseThinkingActivityString(alert.stage_label)
        || normaliseThinkingActivityString(alert.stage)
        || 'LLM call';
    const model = [alert.provider, alert.model].filter(Boolean).join('/');
    const duration = formatThinkingDiagnosticDuration(alert.duration_ms);
    return [
        `${stage}: ${promptCharCount.toLocaleString()} prompt chars`,
        model,
        duration
    ].filter(Boolean).join(' · ');
}

function buildThinkingRecoveryFailureSummary(recoveryProgress) {
    const failure = recoveryProgress?.latest_failure;
    if (!failure || typeof failure !== 'object') {
        return '';
    }
    const tool = normaliseThinkingActivityString(failure.tool || failure.workflow_task);
    const code = normaliseThinkingActivityString(failure.error_code || failure.failure_kind);
    const error = normaliseThinkingActivityString(failure.error);
    return [
        tool,
        code,
        error && error !== code ? error : ''
    ].filter(Boolean).join(' · ');
}

function buildThinkingRecoveryProgressSummary(recoveryProgress) {
    if (!recoveryProgress || typeof recoveryProgress !== 'object') {
        return '';
    }
    const label = normaliseThinkingActivityString(recoveryProgress.latest_recovery_stage_label)
        || normaliseThinkingActivityString(recoveryProgress.latest_recovery_stage_id)
        || 'Recovery';
    const attemptCount = toThinkingCardOptionalNonNegativeInteger(recoveryProgress.attempt_count);
    const state = recoveryProgress.active
        ? 'active'
        : (recoveryProgress.finalising_after_recovery ? 'finalising after recovery' : 'recent');
    return [
        label,
        state,
        attemptCount !== null ? `attempt ${attemptCount}` : ''
    ].filter(Boolean).join(' · ');
}

function normaliseThinkingExecutionInterpretation(value, request = null) {
    if (!value || typeof value !== 'object') {
        return null;
    }

    const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const workflowDiscovery = (request?.workflowDiscovery && typeof request.workflowDiscovery === 'object')
        ? request.workflowDiscovery
        : null;
    const selectedWorkflow = normaliseThinkingCardSelectedWorkflow({
        selected_workflow_id: value.selected_workflow_id,
        selected_workflow_name: value.selected_workflow_name,
    }, workflowDiscovery);

    const stage = normaliseThinkingActivityString(value.stage)
        || normaliseThinkingActivityString(latestProgress?.stage || latestProgress?.phase)
        || null;
    const stageLabel = normaliseThinkingActivityString(value.stage_label)
        || normaliseThinkingActivityString(latestProgress?.stage_label || latestProgress?.phase_label)
        || (stage ? formatThinkingActivityFallbackLabel(stage) : null);
    const identitySummary = firstThinkingCardText(
        value.identity_summary,
        selectedWorkflow?.label ? `Selected workflow: ${selectedWorkflow.label}` : ''
    ) || null;
    const latestCoreStageLabel = findLatestNonFinalisingStageLabel(request);
    let stepSummary = firstThinkingCardText(
        value.step_summary,
        latestProgress?.result_summary,
        latestProgress?.subtask,
        latestProgress?.workflow_task,
        stageLabel
    );
    if (!value.step_summary && stage === 'response_finalising' && latestCoreStageLabel) {
        const postProcessDetail = firstThinkingCardText(
            latestProgress?.result_summary,
            latestProgress?.subtask
        );
        stepSummary = [
            `Finalising response after ${latestCoreStageLabel}`,
            postProcessDetail
        ].filter(Boolean).join(' · ');
    }

    const blockerSummary = firstThinkingCardText(
        value.blocker_summary,
        latestProgress?.error,
        latestProgress?.pending_reason,
        latestProgress?.failure_kind
    ) || null;
    const recoveryProgress = normaliseThinkingRecoveryProgress(value.recovery_progress)
        || deriveThinkingRecoveryProgress(request);

    if (!identitySummary && !stepSummary && !blockerSummary && !stageLabel && !recoveryProgress) {
        return null;
    }

    return {
        schema_version: normaliseThinkingActivityString(value.schema_version) || 'thinking_interpretability.v1',
        execution_family: normaliseThinkingActivityString(value.execution_family) || null,
        progress_kind: normaliseThinkingActivityString(value.progress_kind) || null,
        identity_summary: identitySummary,
        step_summary: stepSummary || null,
        blocker_summary: blockerSummary,
        selected_workflow_id: selectedWorkflow?.workflow_id
            || normaliseThinkingActivityString(value.selected_workflow_id)
            || null,
        selected_workflow_name: selectedWorkflow?.workflow_name
            || normaliseThinkingActivityString(value.selected_workflow_name)
            || null,
        stage,
        stage_label: stageLabel,
        post_processing_only: value.post_processing_only === true,
        progress_contract: normaliseThinkingProgressContract(value.progress_contract),
        recovery_progress: recoveryProgress
    };
}

function deriveThinkingExecutionInterpretation(request = null) {
    const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;

    const explicitCandidates = [
        request?.thinking_interpretability,
        latestProgress?.thinking_interpretability,
        latestProgress?.progress_view_model?.thinking_interpretability,
    ];
    for (const candidate of explicitCandidates) {
        const interpreted = normaliseThinkingExecutionInterpretation(candidate, request);
        if (interpreted) {
            return interpreted;
        }
    }

    const workflowDiscovery = (request?.workflowDiscovery && typeof request.workflowDiscovery === 'object')
        ? request.workflowDiscovery
        : null;
    const selectedWorkflow = normaliseThinkingCardSelectedWorkflow({
        selected_workflow_id: normaliseThinkingActivityString(latestProgress?.selected_workflow_id),
        selected_workflow_name: normaliseThinkingActivityString(latestProgress?.selected_workflow_name)
    }, workflowDiscovery);
    const toolHistory = getCanonicalThinkingToolHistory(request);
    const representedWorkflowCapability = toolHistory
        .map((entry) => getThinkingCapabilityDescriptor(entry))
        .find((descriptor) => descriptor?.capabilityKind === 'represented_workflow') || null;
    const uniqueToolNames = [...new Set(toolHistory
        .map((entry) => {
            const descriptor = getThinkingCapabilityDescriptor(entry);
            return normaliseThinkingActivityString(descriptor?.label);
        })
        .filter(Boolean))];
    const stage = normaliseThinkingActivityString(latestProgress?.stage || latestProgress?.phase);
    const stageLabel = normaliseThinkingActivityString(latestProgress?.stage_label || latestProgress?.phase_label)
        || (stage ? formatThinkingActivityFallbackLabel(stage) : null);
    const isToolCentricStage = Boolean(stage && stage.startsWith('tool_'));

    let executionFamily = 'chat_response';
    let progressKind = 'chat_generation';
    let identitySummary = 'Direct chat response';
    if (selectedWorkflow?.workflow_id) {
        executionFamily = 'selected_workflow';
        progressKind = 'workflow_execution';
        identitySummary = `Selected workflow: ${selectedWorkflow.label}`;
    } else if (representedWorkflowCapability) {
        executionFamily = 'selected_workflow';
        progressKind = 'workflow_execution';
        identitySummary = `Workflow: ${representedWorkflowCapability.label}`;
    } else if (uniqueToolNames.length > 0 || isToolCentricStage) {
        executionFamily = 'tool_orchestration';
        progressKind = 'tool_execution';
        if (uniqueToolNames.length > 0) {
            const preview = uniqueToolNames.slice(0, 3).join(', ');
            const suffix = uniqueToolNames.length > 3 ? ` +${uniqueToolNames.length - 3} more` : '';
            identitySummary = `General tool use: ${preview}${suffix}`;
        } else {
            identitySummary = 'General tool use';
        }
    }

    const latestCoreStageLabel = findLatestNonFinalisingStageLabel(request);
    const recoveryProgress = deriveThinkingRecoveryProgress(request);
    let stepSummary = firstThinkingCardText(
        latestProgress?.result_summary,
        latestProgress?.subtask,
        latestProgress?.workflow_task,
        stageLabel
    );
    let postProcessingOnly = false;
    if (stage === 'response_finalising' && latestCoreStageLabel) {
        progressKind = 'post_processing';
        postProcessingOnly = true;
        const postProcessDetail = firstThinkingCardText(
            latestProgress?.result_summary,
            latestProgress?.subtask
        );
        stepSummary = [
            `Finalising response after ${latestCoreStageLabel}`,
            postProcessDetail
        ].filter(Boolean).join(' · ');
    }
    if (recoveryProgress) {
        progressKind = stage === 'response_finalising'
            ? 'post_recovery_finalising'
            : 'recovery';
        stepSummary = stepSummary || buildThinkingRecoveryProgressSummary(recoveryProgress);
    }

    return {
        schema_version: 'thinking_interpretability.v1',
        execution_family: executionFamily,
        progress_kind: progressKind,
        identity_summary: identitySummary,
        step_summary: stepSummary || null,
        blocker_summary: firstThinkingCardText(
            latestProgress?.error,
            latestProgress?.pending_reason,
            latestProgress?.failure_kind
        ) || null,
        selected_workflow_id: selectedWorkflow?.workflow_id || null,
        selected_workflow_name: selectedWorkflow?.workflow_name || null,
        stage,
        stage_label: stageLabel,
        post_processing_only: postProcessingOnly,
        progress_contract: normaliseThinkingProgressContract(latestProgress?.thinking_interpretability?.progress_contract),
        recovery_progress: recoveryProgress
    };
}

function normaliseThinkingProgressContract(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }
    const precedence = Array.isArray(value.default_row_precedence)
        ? value.default_row_precedence
            .map((item) => normaliseThinkingActivityString(item))
            .filter(Boolean)
        : [];
    const sources = Array.isArray(value.selected_workflow_evidence_sources)
        ? value.selected_workflow_evidence_sources
            .map((item) => normaliseThinkingActivityString(item))
            .filter(Boolean)
        : [];
    return {
        schema_version: normaliseThinkingActivityString(value.schema_version) || 'thinking_progress_contract.v1',
        precedence_rule: normaliseThinkingActivityString(value.precedence_rule)
            || 'selected_workflow_execution_before_finalisation',
        default_row_precedence: precedence,
        selected_workflow_evidence_present: value.selected_workflow_evidence_present === true,
        selected_workflow_evidence_sources: sources,
        blocker_present: value.blocker_present === true,
        finalisation_demoted: value.finalisation_demoted === true
    };
}

function normaliseThinkingCardLlmLifecycle(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }
    const llmRequest = (value.llm_request && typeof value.llm_request === 'object')
        ? value.llm_request
        : null;
    const state = normaliseThinkingActivityString(
        value.state || value.llm_request_state || value.request_state
    ) || null;
    const promptPreview = normaliseThinkingDiagnosticCapture(
        value.prompt_preview || value.llm_prompt_preview || value.prompt || value.prepared_input || llmRequest?.prompt
    );
    const responsePreview = normaliseThinkingDiagnosticCapture(
        value.response_preview || value.llm_response_preview || value.output_preview
    );
    const contextSummary = (value.context_summary && typeof value.context_summary === 'object')
        ? { ...value.context_summary }
        : ((value.llm_context_summary && typeof value.llm_context_summary === 'object')
            ? { ...value.llm_context_summary }
        : ((llmRequest?.context_summary && typeof llmRequest.context_summary === 'object')
            ? { ...llmRequest.context_summary }
                : null));
    const model = normaliseThinkingActivityString(
        value.model || value.selected_model || value.llm_selected_model
    ) || null;
    const provider = normaliseThinkingActivityString(
        value.provider || value.selected_provider || value.llm_selected_provider
    ) || null;
    const fallbackAttemptNo = Number.isFinite(value.fallback_attempt_no)
        ? Number(value.fallback_attempt_no)
        : (Number.isFinite(value.llm_fallback_attempt_no) ? Number(value.llm_fallback_attempt_no) : null);
    const fallbackCandidateCount = Number.isFinite(value.fallback_candidate_count)
        ? Number(value.fallback_candidate_count)
        : (Number.isFinite(value.llm_fallback_candidate_count) ? Number(value.llm_fallback_candidate_count) : null);

    if (
        !state
        && !promptPreview
        && !responsePreview
        && !contextSummary
        && !model
        && !provider
        && fallbackAttemptNo === null
        && fallbackCandidateCount === null
    ) {
        return null;
    }

    return {
        state,
        label: state ? formatThinkingLlmRequestState(state) : null,
        prompt_preview: promptPreview,
        response_preview: responsePreview,
        context_summary: contextSummary,
        context_summary_text: normaliseThinkingActivityString(value.context_summary_text) || null,
        context_message_count: Number.isFinite(value.context_message_count)
            ? Number(value.context_message_count)
            : (Number.isFinite(value.llm_context_message_count)
                ? Number(value.llm_context_message_count)
                : (Number.isFinite(llmRequest?.context_message_count) ? Number(llmRequest.context_message_count) : null)),
        tool_definition_count: Number.isFinite(value.tool_definition_count)
            ? Number(value.tool_definition_count)
            : (Number.isFinite(value.llm_tool_definition_count)
                ? Number(value.llm_tool_definition_count)
                : (Number.isFinite(llmRequest?.tool_count) ? Number(llmRequest.tool_count) : null)),
        model,
        provider,
        prepared_at_utc: normaliseThinkingActivityString(
            value.prepared_at_utc || value.llm_request_prepared_at_utc
        ) || null,
        sent_at_utc: normaliseThinkingActivityString(
            value.sent_at_utc || value.llm_request_sent_at_utc
        ) || null,
        first_output_at_utc: normaliseThinkingActivityString(
            value.first_output_at_utc || value.llm_first_output_at_utc
        ) || null,
        fallback_attempt_no: fallbackAttemptNo,
        fallback_candidate_count: fallbackCandidateCount
    };
}

function buildThinkingCardContextSummaryText(llmLifecycle) {
    if (!llmLifecycle || typeof llmLifecycle !== 'object') {
        return '';
    }
    if (normaliseThinkingActivityString(llmLifecycle.context_summary_text)) {
        return normaliseThinkingActivityString(llmLifecycle.context_summary_text);
    }
    const bits = [];
    if (Number.isFinite(llmLifecycle.context_message_count)) {
        bits.push(formatThinkingCountLabel(Number(llmLifecycle.context_message_count), 'context message'));
    } else {
        const contextLines = buildThinkingLlmContextSummaryLines(llmLifecycle.context_summary);
        const messageLine = contextLines.find((line) => /\bcontext messages?\b/i.test(line));
        if (messageLine) {
            bits.push(messageLine);
        }
    }
    if (Number.isFinite(llmLifecycle.tool_definition_count) && Number(llmLifecycle.tool_definition_count) > 0) {
        bits.push(formatThinkingCountLabel(Number(llmLifecycle.tool_definition_count), 'available tool definition'));
    }
    return bits.join('; ');
}

function buildThinkingCardLlmLifecycleText(llmLifecycle, options = {}) {
    if (!llmLifecycle || typeof llmLifecycle !== 'object') {
        return '';
    }

    const bits = [];
    const state = normaliseThinkingActivityString(llmLifecycle.state).toLowerCase();
    if (state === 'prepared') {
        bits.push('LLM input prepared');
    } else if (state === 'sent') {
        bits.push(llmLifecycle.first_output_at_utc
            ? 'LLM input sent; first output received'
            : 'LLM input sent; waiting for model output');
    } else if (state === 'received_output') {
        bits.push('First model output received');
    } else if (state === 'completed') {
        bits.push('LLM call completed');
    } else if (state === 'failed') {
        bits.push('LLM call failed');
    } else if (llmLifecycle.label) {
        bits.push(llmLifecycle.label);
    }

    if (llmLifecycle.model) {
        bits.push(`Model: ${llmLifecycle.model}`);
    }
    if (options.includeProvider && llmLifecycle.provider) {
        bits.push(`Provider: ${llmLifecycle.provider}`);
    }
    if (
        Number.isFinite(llmLifecycle.fallback_attempt_no)
        && Number.isFinite(llmLifecycle.fallback_candidate_count)
        && Number(llmLifecycle.fallback_candidate_count) > 1
    ) {
        bits.push(`Fallback ${Number(llmLifecycle.fallback_attempt_no)} of ${Number(llmLifecycle.fallback_candidate_count)}`);
    }
    return bits.join(' · ');
}

function getExplicitThinkingCardProgressViewModel(request) {
    const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const candidates = [
        request?.thinkingCardProgressViewModel,
        request?.thinking_card_progress_view_model,
        latestProgress?.thinking_card_progress_view_model,
        latestProgress?.thinking_card_view_model,
        latestProgress?.progress_view_model
    ];

    for (const candidate of candidates) {
        if (candidate && typeof candidate === 'object') {
            return candidate;
        }
    }
    return null;
}

function toThinkingCardNonNegativeInteger(value) {
    const parsed = Number(value);
    if (!Number.isFinite(parsed)) {
        return 0;
    }
    return Math.max(0, Math.trunc(parsed));
}

function toThinkingCardOptionalNonNegativeInteger(value) {
    const parsed = Number(value);
    if (!Number.isFinite(parsed)) {
        return null;
    }
    return Math.max(0, Math.trunc(parsed));
}

function deriveThinkingCardWorkflowExecutionSummary(request) {
    const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const routingDiagnostics = getWorkflowRoutingDiagnostics(
        (request?.workflowRoutingDiagnostics && typeof request.workflowRoutingDiagnostics === 'object')
            ? request.workflowRoutingDiagnostics
            : latestProgress
    );
    const dispatch = (routingDiagnostics?.dispatch && typeof routingDiagnostics.dispatch === 'object')
        ? routingDiagnostics.dispatch
        : null;
    const customExecution = (
        dispatch?.custom_workflow_execution
        && typeof dispatch.custom_workflow_execution === 'object'
    )
        ? dispatch.custom_workflow_execution
        : null;
    if (!customExecution) {
        return null;
    }
    return {
        ...customExecution,
        selected_workflow_id: normaliseThinkingActivityString(routingDiagnostics?.selected_workflow_id)
            || normaliseThinkingActivityString(dispatch?.dispatch_workflow_id)
            || normaliseThinkingActivityString(customExecution.workflow_id)
            || null,
        dispatch_terminal_status: normaliseThinkingActivityString(dispatch?.dispatch_terminal_status) || null
    };
}

function normaliseThinkingCardWorkflowExecutionSummary(rawSummary) {
    if (!rawSummary || typeof rawSummary !== 'object') {
        return null;
    }
    const workflowId = normaliseThinkingActivityString(
        rawSummary.workflow_id || rawSummary.selected_workflow_id
    );
    const workflowInstanceId = normaliseThinkingActivityString(rawSummary.workflow_instance_id);
    const terminalStatus = normaliseThinkingActivityString(
        rawSummary.terminal_status || rawSummary.dispatch_terminal_status
    );
    const finalState = normaliseThinkingActivityString(rawSummary.final_state);
    const actionCompletedCount = toThinkingCardNonNegativeInteger(rawSummary.action_completed_count);
    const actionSuccessCount = toThinkingCardNonNegativeInteger(rawSummary.action_success_count);
    const actionFailureCount = toThinkingCardNonNegativeInteger(rawSummary.action_failure_count);
    const actionUnknownCount = toThinkingCardNonNegativeInteger(rawSummary.action_unknown_count);
    const terminalEffectCount = toThinkingCardNonNegativeInteger(rawSummary.terminal_effect_count);
    const durableSideEffectCount = toThinkingCardNonNegativeInteger(rawSummary.durable_side_effect_count);
    const observed = rawSummary.observed === true || Boolean(
        workflowId
        || workflowInstanceId
        || terminalStatus
        || finalState
        || actionCompletedCount
        || actionSuccessCount
        || actionFailureCount
        || terminalEffectCount
        || durableSideEffectCount
    );
    if (!observed) {
        return null;
    }

    const statusText = terminalStatus
        ? `terminal status ${terminalStatus}`
        : (finalState ? `final state ${finalState}` : 'execution observed');
    const actionParts = [];
    if (actionCompletedCount > 0) {
        actionParts.push(`${formatThinkingCountLabel(actionCompletedCount, 'action')} completed`);
    }
    if (actionSuccessCount > 0) {
        actionParts.push(`${formatThinkingCountLabel(actionSuccessCount, 'action')} succeeded`);
    }
    if (actionFailureCount > 0) {
        actionParts.push(`${formatThinkingCountLabel(actionFailureCount, 'action')} failed`);
    }
    if (actionUnknownCount > 0) {
        actionParts.push(`${formatThinkingCountLabel(actionUnknownCount, 'action')} unknown`);
    }
    const effectText = [
        formatThinkingCountLabel(terminalEffectCount, 'terminal effect'),
        formatThinkingCountLabel(durableSideEffectCount, 'durable side effect')
    ].join('; ');
    const detailBits = [
        statusText,
        actionParts.join(', '),
        effectText
    ].filter(Boolean);
    return {
        workflow_id: workflowId || null,
        workflow_instance_id: workflowInstanceId || null,
        terminal_status: terminalStatus || null,
        final_state: finalState || null,
        action_completed_count: actionCompletedCount,
        action_success_count: actionSuccessCount,
        action_failure_count: actionFailureCount,
        action_unknown_count: actionUnknownCount,
        terminal_effect_count: terminalEffectCount,
        durable_side_effect_count: durableSideEffectCount,
        summary_text: detailBits.join(' · ')
    };
}

function deriveThinkingCardWorkflowVerificationSummary(request) {
    const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const routingDiagnostics = getWorkflowRoutingDiagnostics(
        (request?.workflowRoutingDiagnostics && typeof request.workflowRoutingDiagnostics === 'object')
            ? request.workflowRoutingDiagnostics
            : latestProgress
    );
    const dispatch = (routingDiagnostics?.dispatch && typeof routingDiagnostics.dispatch === 'object')
        ? routingDiagnostics.dispatch
        : null;
    const ledger = (dispatch?.required_tool_obligations && typeof dispatch.required_tool_obligations === 'object')
        ? dispatch.required_tool_obligations
        : (dispatch?.tool_execution?.required_tool_obligations
            && typeof dispatch.tool_execution.required_tool_obligations === 'object'
                ? dispatch.tool_execution.required_tool_obligations
                : null);
    const unsatisfiedTools = Array.isArray(ledger?.unsatisfied_required_tools)
        ? ledger.unsatisfied_required_tools
            .map((value) => normaliseThinkingActivityString(value))
            .filter(Boolean)
        : [];
    const rawBlockingCodes = dispatch?.required_tool_obligation_blocking_failure_codes
        || ledger?.blocking_failure_codes;
    const blockingCodes = Array.isArray(rawBlockingCodes)
        ? rawBlockingCodes
            .map((value) => normaliseThinkingActivityString(value))
            .filter(Boolean)
        : [];
    const customExecution = (
        dispatch?.custom_workflow_execution
        && typeof dispatch.custom_workflow_execution === 'object'
    )
        ? dispatch.custom_workflow_execution
        : null;
    const durableSideEffectCount = toThinkingCardNonNegativeInteger(
        customExecution?.durable_side_effect_count
    );
    const terminalEffectCount = toThinkingCardNonNegativeInteger(
        customExecution?.terminal_effect_count
    );
    const bits = [];
    if (unsatisfiedTools.length > 0) {
        bits.push(`unsatisfied required tools: ${unsatisfiedTools.slice(0, 5).join(', ')}${unsatisfiedTools.length > 5 ? ` +${unsatisfiedTools.length - 5} more` : ''}`);
    }
    if (blockingCodes.length > 0) {
        bits.push(`blocking codes: ${blockingCodes.slice(0, 4).join(', ')}${blockingCodes.length > 4 ? ` +${blockingCodes.length - 4} more` : ''}`);
    }
    if (customExecution) {
        bits.push(`${formatThinkingCountLabel(terminalEffectCount, 'terminal effect')} and ${formatThinkingCountLabel(durableSideEffectCount, 'durable side effect')} observed`);
    }
    return bits.join(' · ');
}

function isAuxiliaryThinkingCardLlmLifecycle(llmLifecycle) {
    const promptText = normaliseThinkingActivityString(
        llmLifecycle?.prompt_preview?.text || llmLifecycle?.prompt_preview?.preview
    ).toLowerCase();
    return Boolean(promptText && promptText.includes('quick-reply button options for a chat ui'));
}

function normaliseThinkingCardProgressViewModel(rawViewModel, request = null) {
    if (!rawViewModel || typeof rawViewModel !== 'object') {
        return null;
    }
    const workflowDiscovery = (request?.workflowDiscovery && typeof request.workflowDiscovery === 'object')
        ? request.workflowDiscovery
        : null;
    const selectedWorkflow = normaliseThinkingCardSelectedWorkflow(
        rawViewModel.selected_workflow || {
            selected_workflow_id: rawViewModel.selected_workflow_id,
            selected_workflow_name: rawViewModel.selected_workflow_name
        },
        workflowDiscovery
    );
    const llmLifecycle = normaliseThinkingCardLlmLifecycle(
        rawViewModel.llm_input_lifecycle || rawViewModel.llm_lifecycle || rawViewModel.latest_llm_exchange
    );
    const waitState = (rawViewModel.wait_state && typeof rawViewModel.wait_state === 'object')
        ? {
            state: normaliseThinkingActivityString(rawViewModel.wait_state.state) || null,
            label: normaliseThinkingActivityString(rawViewModel.wait_state.label) || null,
            boundary: normaliseThinkingActivityString(rawViewModel.wait_state.boundary) || null,
            next_action: normaliseThinkingActivityString(rawViewModel.wait_state.next_action) || null
        }
        : null;
    const missingTelemetry = normaliseThinkingCardSummaryList(
        rawViewModel.missing_telemetry || rawViewModel.telemetry_gaps
    );
    const workflowExecutionSummary = normaliseThinkingCardWorkflowExecutionSummary(
        rawViewModel.workflow_execution_summary
            || rawViewModel.selected_workflow_execution
            || deriveThinkingCardWorkflowExecutionSummary(request)
    );
    const workflowVerificationSummary = firstThinkingCardText(
        rawViewModel.workflow_verification_summary,
        rawViewModel.verification_summary,
        deriveThinkingCardWorkflowVerificationSummary(request)
    ) || null;
    const executionInterpretation = normaliseThinkingExecutionInterpretation(
        rawViewModel.thinking_interpretability || rawViewModel.execution_interpretation,
        request
    ) || deriveThinkingExecutionInterpretation(request);
    const recoveryProgress = normaliseThinkingRecoveryProgress(
        rawViewModel.recovery_progress
    ) || executionInterpretation?.recovery_progress || deriveThinkingRecoveryProgress(request);
    const rawLargeLlmCallAlerts = [
        ...normaliseThinkingLargeLlmCallAlerts(rawViewModel.large_llm_call_alerts),
        ...normaliseThinkingLargeLlmCallAlerts(recoveryProgress?.large_llm_call_alerts),
        ...collectThinkingLargeLlmCallAlerts(request)
    ];
    const seenLargeLlmCallAlerts = new Set();
    const largeLlmCallAlerts = rawLargeLlmCallAlerts.filter((alert) => {
        const key = buildThinkingLargeLlmCallAlertKey(alert);
        if (seenLargeLlmCallAlerts.has(key)) {
            return false;
        }
        seenLargeLlmCallAlerts.add(key);
        return true;
    });

    const viewModel = {
        schema_version: THINKING_CARD_PROGRESS_VIEW_MODEL_SCHEMA,
        source_authority: normaliseThinkingActivityString(rawViewModel.source_authority)
            || THINKING_CARD_PROGRESS_VIEW_MODEL_SOURCE_EXPLICIT,
        objective_summary: firstThinkingCardText(
            rawViewModel.objective_summary,
            rawViewModel.intent_summary,
            rawViewModel.goal_summary
        ) || null,
        object_or_target_summary: firstThinkingCardText(
            rawViewModel.object_or_target_summary,
            rawViewModel.working_object_summary,
            rawViewModel.target_summary,
            rawViewModel.object_summary
        ) || null,
        route_summary: firstThinkingCardText(
            rawViewModel.route_summary,
            rawViewModel.workflow_summary
        ) || null,
        route_summary_html: normaliseThinkingActivityString(rawViewModel.route_summary_html) || '',
        selected_workflow: selectedWorkflow,
        evidence_context_summary: firstThinkingCardText(
            rawViewModel.evidence_context_summary,
            rawViewModel.evidence_summary,
            rawViewModel.context_summary
        ) || null,
        current_activity: firstThinkingCardText(
            rawViewModel.current_activity,
            rawViewModel.activity_summary,
            rawViewModel.stage_summary
        ) || null,
        workflow_execution_summary: workflowExecutionSummary,
        workflow_verification_summary: workflowVerificationSummary,
        execution_interpretation: executionInterpretation,
        recovery_progress: recoveryProgress,
        large_llm_call_alerts: largeLlmCallAlerts,
        llm_input_lifecycle: llmLifecycle,
        wait_state: waitState,
        confirmation_requirement: firstThinkingCardText(
            rawViewModel.confirmation_requirement,
            rawViewModel.confirmation_summary
        ) || null,
        uncertainty_summary: firstThinkingCardText(
            rawViewModel.uncertainty_summary,
            rawViewModel.missing_information_summary
        ) || null,
        missing_telemetry: missingTelemetry,
        expert_details: normaliseThinkingCardSummaryList(rawViewModel.expert_details),
        debug_details: normaliseThinkingCardSummaryList(rawViewModel.debug_details)
    };

    const hasContent = [
        viewModel.objective_summary,
        viewModel.object_or_target_summary,
        viewModel.route_summary,
        viewModel.evidence_context_summary,
        viewModel.current_activity,
        viewModel.workflow_execution_summary?.summary_text,
        viewModel.workflow_verification_summary,
        viewModel.execution_interpretation?.identity_summary,
        viewModel.execution_interpretation?.step_summary,
        buildThinkingRecoveryProgressSummary(viewModel.recovery_progress),
        viewModel.confirmation_requirement,
        viewModel.uncertainty_summary
    ].some(Boolean) || Boolean(viewModel.selected_workflow) || Boolean(viewModel.llm_input_lifecycle)
        || Boolean(viewModel.wait_state) || viewModel.missing_telemetry.length > 0
        || viewModel.large_llm_call_alerts.length > 0
        || viewModel.expert_details.length > 0 || viewModel.debug_details.length > 0;

    return hasContent ? viewModel : null;
}

function findLatestThinkingCardLlmDiagnosticData(request) {
    const rows = buildThinkingWorkflowStageRows(request);
    if (rows.length === 0) {
        return null;
    }
    const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const latestStageId = canonicaliseThinkingDiagnosticStageId(
        latestProgress?.phase || latestProgress?.stage
    );
    const llmRows = rows
        .map((row) => row?.diagnosticData)
        .filter((data) => data && typeof data === 'object' && (
            data.latest_llm_exchange
            || data.llm_prompt_preview
            || data.llm_request_state
        ));
    if (llmRows.length === 0) {
        return null;
    }
    const currentStageMatch = latestStageId
        ? llmRows.find((data) => canonicaliseThinkingDiagnosticStageId(data.stage_id) === latestStageId)
        : null;
    return currentStageMatch || llmRows[llmRows.length - 1] || null;
}

function isThinkingCardLlmOrModelStage(stageId) {
    const cleanStageId = canonicaliseThinkingDiagnosticStageId(stageId);
    return new Set([
        'expected_outcome_inference',
        'selector_preparation',
        'selector_decision',
        'workflow_dispatch_prepare',
        'workflow_dispatch',
        'plain_response',
        'tool_plan',
        'screen_backfill',
        'narration'
    ]).has(cleanStageId);
}

function buildDerivedThinkingCardEvidenceSummary({
    request,
    workflowDiscovery,
    llmLifecycle
}) {
    const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const explicitEvidence = firstThinkingCardText(
        latestProgress?.evidence_context_summary,
        latestProgress?.evidence_summary,
        latestProgress?.context_source_summary,
        latestProgress?.source_summary
    );
    if (explicitEvidence) {
        return explicitEvidence;
    }

    const bits = [];
    const matchCount = getWorkflowDiscoveryMatchCount(workflowDiscovery);
    const candidateCount = getWorkflowDiscoveryCandidateCount(workflowDiscovery);
    const searchSources = Array.isArray(workflowDiscovery?.search_sources)
        ? workflowDiscovery.search_sources
            .map((value) => normaliseThinkingActivityString(value))
            .filter(Boolean)
        : [];
    if (Number.isFinite(matchCount) || Number.isFinite(candidateCount)) {
        const discoveryBits = [];
        if (Number.isFinite(matchCount)) {
            discoveryBits.push(formatThinkingCountLabel(matchCount, 'workflow match', 'workflow matches'));
        }
        if (Number.isFinite(candidateCount)) {
            discoveryBits.push(formatThinkingCountLabel(candidateCount, 'candidate route'));
        }
        if (searchSources.length > 0) {
            discoveryBits.push(`sources: ${searchSources.join(', ')}`);
        }
        bits.push(`Workflow discovery: ${discoveryBits.join('; ')}`);
    }

    const contextSummary = buildThinkingCardContextSummaryText(llmLifecycle);
    if (contextSummary) {
        bits.push(`LLM context: ${contextSummary}`);
    }

    const toolHistory = getCanonicalThinkingToolHistory(request);
    const observedCapabilities = toolHistory
        .map((entry) => {
            const descriptor = getThinkingCapabilityDescriptor(entry);
            return {
                label: normaliseThinkingActivityString(descriptor?.label),
                kind: normaliseThinkingActivityString(descriptor?.capabilityKind)
            };
        })
        .filter((entry) => entry.label);
    const toolNames = [...new Set(observedCapabilities.map((entry) => entry.label))];
    if (toolNames.length > 0) {
        const preview = toolNames.slice(0, 3).join(', ');
        const onlyRepresentedWorkflows = observedCapabilities.every(
            (entry) => entry.kind === 'represented_workflow'
        );
        const observationLabel = onlyRepresentedWorkflows
            ? 'Workflow observed'
            : 'Tools observed';
        bits.push(toolNames.length > 3
            ? `${observationLabel}: ${preview} +${toolNames.length - 3} more`
            : `${observationLabel}: ${preview}`);
    }

    return bits.join(' · ');
}

function buildDerivedThinkingCardWaitState({
    latestProgress,
    presentation,
    llmLifecycle
}) {
    const livenessState = presentation?.livenessState || normaliseThinkingLivenessState(latestProgress);
    const state = normaliseThinkingActivityString(livenessState) || THINKING_STATUS_ACTIVE;
    const stageLabel = firstThinkingCardText(
        latestProgress?.phase_label,
        latestProgress?.stage_label,
        formatThinkingActivityFallbackLabel(latestProgress?.phase || latestProgress?.stage)
    );
    const llmState = normaliseThinkingActivityString(llmLifecycle?.state).toLowerCase();
    const label = (() => {
        if (llmState === 'sent' && !llmLifecycle?.first_output_at_utc) {
            return 'Waiting for model output';
        }
        if (llmState === 'prepared') {
            return 'LLM input is prepared and waiting to be sent';
        }
        if (state === THINKING_STATUS_STALLED) {
            return stageLabel ? `Stalled at ${stageLabel}` : 'Stalled while waiting for progress';
        }
        if (state === THINKING_STATUS_WAITING) {
            return stageLabel ? `Waiting at ${stageLabel}` : 'Waiting for live progress';
        }
        const terminalStatus = resolveThinkingTerminalStatus(latestProgress);
        if (terminalStatus) {
            if (terminalStatus === THINKING_STATUS_COMPLETED) {
                return 'Turn completed';
            }
            if (terminalStatus === THINKING_STATUS_FAILED) {
                return 'Turn failed';
            }
            if (terminalStatus === THINKING_STATUS_CANCELLED) {
                return 'Turn cancelled';
            }
            if (terminalStatus === THINKING_STATUS_TERMINATED) {
                return 'Turn terminated';
            }
            return thinkingTerminalLabel(terminalStatus);
        }
        if (isClientInitialThinkingProgress(latestProgress)) {
            return 'Submitting the turn and waiting for live progress';
        }
        return stageLabel ? `Working on ${stageLabel}` : 'Working on the turn';
    })();

    return {
        state,
        label,
        boundary: stageLabel || null,
        next_action: firstThinkingCardText(
            latestProgress?.next_action,
            latestProgress?.recovery_next_action,
            latestProgress?.fallback_next_action
        ) || null
    };
}

function buildDerivedThinkingCardMissingTelemetry({
    latestProgress,
    llmDiagnosticData,
    llmLifecycle
}) {
    const notes = [];
    if (!latestProgress || typeof latestProgress !== 'object') {
        notes.push('No live progress has been received yet.');
        return notes;
    }

    const pendingReason = normaliseThinkingActivityString(latestProgress.pending_reason);
    if (pendingReason === 'request_progress_not_found' || pendingReason === 'no_visible_progress_state') {
        notes.push('The turn is running, but live progress has not become visible yet.');
    }

    const stageId = canonicaliseThinkingDiagnosticStageId(latestProgress.phase || latestProgress.stage);
    const hasLlmInput = Boolean(llmLifecycle?.prompt_preview) || Boolean(llmLifecycle?.state);
    if (
        isThinkingCardLlmOrModelStage(stageId)
        && !hasLlmInput
        && !resolveThinkingTerminalStatus(latestProgress)
    ) {
        notes.push('Prepared LLM input has not been reported for the current stage yet.');
    }
    if (llmDiagnosticData?.missing_recorded_llm_output === true && llmLifecycle?.state === 'sent') {
        notes.push('No model output has been reported yet.');
    }
    return [...new Set(notes)];
}

function buildThinkingCardProgressViewModel(request) {
    const explicitViewModel = normaliseThinkingCardProgressViewModel(
        getExplicitThinkingCardProgressViewModel(request),
        request
    );
    if (explicitViewModel) {
        return explicitViewModel;
    }

    if (!request || typeof request !== 'object') {
        return null;
    }

    const latestProgress = (request.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const workflowDiscovery = (request.workflowDiscovery && typeof request.workflowDiscovery === 'object')
        ? request.workflowDiscovery
        : (latestProgress?.workflow_discovery && typeof latestProgress.workflow_discovery === 'object'
            ? latestProgress.workflow_discovery
            : null);
    if (!latestProgress && !workflowDiscovery && !normaliseThinkingActivityString(request.promptRaw)) {
        return null;
    }
    const canonicalRoutingProgress = buildCanonicalWorkflowRoutingProgress(request);
    const routingNarrative = buildWorkflowRoutingNarrative(canonicalRoutingProgress, workflowDiscovery, {
        includeNoMatchTransition: true,
    });
    const llmDiagnosticData = findLatestThinkingCardLlmDiagnosticData(request);
    const llmLifecycle = normaliseThinkingCardLlmLifecycle(
        llmDiagnosticData || latestProgress
    );
    const presentation = buildThinkingProgressPresentation(latestProgress, request);
    const selectedWorkflow = normaliseThinkingCardSelectedWorkflow({
        selected_workflow_id: routingNarrative.context.selectedWorkflowId,
        selected_workflow_name: routingNarrative.context.selectedWorkflowName
    }, workflowDiscovery);
    const routeSummary = routingNarrative.text
        || (selectedWorkflow?.label ? `Selected route: ${selectedWorkflow.label}` : '')
        || firstThinkingCardText(latestProgress?.route_summary, latestProgress?.workflow_summary);
    const latestSemanticOperation = getThinkingSemanticOperation(latestProgress);
    const currentActivity = firstThinkingCardText(
        latestProgress?.current_activity,
        latestProgress?.activity_summary,
        latestProgress?.result_summary,
        latestSemanticOperation?.summary,
        latestProgress?.subtask,
        latestProgress?.workflow_task,
        presentation?.stageText ? presentation.stageText.replace(/\.{3}$/, '') : ''
    );
    const objectiveSummary = firstThinkingCardText(
        latestProgress?.objective_summary,
        latestProgress?.intent_summary,
        latestProgress?.goal_summary,
        summarisePromptForThinkingCard(request.promptRaw, 'User request'),
        latestProgress?.goal_label
    );
    const objectOrTargetSummary = firstThinkingCardText(
        latestProgress?.object_or_target_summary,
        latestProgress?.working_object_summary,
        latestProgress?.target_summary,
        latestProgress?.object_summary,
        latestProgress?.goal_label,
        latestProgress?.target,
        workflowDiscovery?.requested_query,
        workflowDiscovery?.query,
        summarisePromptForThinkingCard(request.promptRaw)
    );
    const evidenceSummary = buildDerivedThinkingCardEvidenceSummary({
        request,
        workflowDiscovery,
        llmLifecycle
    });
    const waitState = buildDerivedThinkingCardWaitState({
        latestProgress,
        presentation,
        llmLifecycle
    });
    const confirmationRequirement = firstThinkingCardText(
        latestProgress?.confirmation_requirement,
        latestProgress?.confirmation_summary,
        latestProgress?.pending_confirmation_summary,
        latestProgress?.requires_confirmation === true
            ? 'Confirmation will be required before any external action is taken.'
            : ''
    );
    const uncertaintySummary = firstThinkingCardText(
        latestProgress?.uncertainty_summary,
        latestProgress?.missing_information_summary,
        routingNarrative.context.noDirectMatch && !routingNarrative.context.hasSelection
            ? 'No matching workflow route has been selected yet.'
            : ''
    );
    const missingTelemetry = buildDerivedThinkingCardMissingTelemetry({
        latestProgress,
        llmDiagnosticData,
        llmLifecycle
    });
    const executionInterpretation = deriveThinkingExecutionInterpretation(request);
    const recoveryProgress = deriveThinkingRecoveryProgress(request);
    const largeLlmCallAlerts = collectThinkingLargeLlmCallAlerts(request);

    const viewModel = {
        schema_version: THINKING_CARD_PROGRESS_VIEW_MODEL_SCHEMA,
        source_authority: THINKING_CARD_PROGRESS_VIEW_MODEL_SOURCE_DERIVED,
        objective_summary: objectiveSummary || null,
        object_or_target_summary: objectOrTargetSummary || null,
        route_summary: routeSummary || null,
        route_summary_html: routingNarrative.html || '',
        selected_workflow: selectedWorkflow,
        evidence_context_summary: evidenceSummary || null,
        current_activity: currentActivity || null,
        execution_interpretation: executionInterpretation,
        recovery_progress: recoveryProgress,
        large_llm_call_alerts: largeLlmCallAlerts,
        llm_input_lifecycle: llmLifecycle,
        wait_state: waitState,
        confirmation_requirement: confirmationRequirement || null,
        uncertainty_summary: uncertaintySummary || null,
        missing_telemetry: missingTelemetry,
        expert_details: [],
        debug_details: []
    };

    return normaliseThinkingCardProgressViewModel(viewModel, request);
}

function renderThinkingCardSynopsisItemHTML({ label, value, html = '', tone = '' }) {
    const cleanLabel = normaliseThinkingActivityString(label);
    const cleanValue = normaliseThinkingActivityString(value);
    const cleanHtml = normaliseThinkingActivityString(html);
    if (!cleanLabel || (!cleanValue && !cleanHtml)) {
        return '';
    }
    const toneClass = tone ? ` is-${escapeHtml(tone)}` : '';
    return `<div class="thinking-card-synopsis-item${toneClass}">
        <div class="thinking-card-synopsis-label">${escapeHtml(cleanLabel)}</div>
        <div class="thinking-card-synopsis-value">${cleanHtml || escapeHtml(cleanValue)}</div>
    </div>`;
}

const THINKING_PRECEDENCE_TELEMETRY = {
    selected_workflow_execution_missing: 0,
    last_violation: null
};

function recordThinkingPrecedenceViolation(detail = {}) {
    THINKING_PRECEDENCE_TELEMETRY.selected_workflow_execution_missing += 1;
    THINKING_PRECEDENCE_TELEMETRY.last_violation = {
        at: Date.now(),
        evidence_sources: Array.isArray(detail.evidence_sources) ? detail.evidence_sources : [],
        finalisation_row_emitted: detail.finalisation_row_emitted === true
    };
    if (typeof console !== 'undefined' && typeof console.warn === 'function') {
        console.warn(
            'Thinking-card precedence violation: selected-workflow evidence present but no selected-workflow execution row was rendered in the default synopsis.',
            THINKING_PRECEDENCE_TELEMETRY.last_violation
        );
    }
}

function renderThinkingCardProgressSynopsisHTML(viewModel, mode = THINKING_CARD_MODE_DEFAULT, request = null) {
    if (!viewModel || typeof viewModel !== 'object') {
        return '';
    }
    const renderMode = normaliseThinkingCardMode(mode);
    const items = [];
    let selectedWorkflowRowEmitted = false;
    let finalisationRowEmitted = false;
    const addItem = (label, value, html = '', tone = '') => {
        const itemHtml = renderThinkingCardSynopsisItemHTML({ label, value, html, tone });
        if (itemHtml) {
            items.push(itemHtml);
        }
    };

    const progressContract = viewModel.execution_interpretation?.progress_contract || null;
    const interpretationFamily = normaliseThinkingActivityString(
        viewModel.execution_interpretation?.execution_family
    );

    const objectiveSummary = normaliseThinkingSynopsisIdentity(viewModel.objective_summary);
    const workingOnSummary = normaliseThinkingSynopsisIdentity(viewModel.object_or_target_summary);
    addItem('Objective', viewModel.objective_summary);
    if (!objectiveSummary || workingOnSummary !== objectiveSummary) {
        addItem('Working on', viewModel.object_or_target_summary);
    }
    addItem('Route', viewModel.route_summary, viewModel.route_summary_html);
    addItem('Evidence and context', viewModel.evidence_context_summary);
    addItem('Current activity', viewModel.current_activity);
    if (renderThinkingCardSynopsisItemHTML({ label: 'Workflow execution', value: viewModel.workflow_execution_summary?.summary_text })) {
        selectedWorkflowRowEmitted = true;
    }
    addItem('Workflow execution', viewModel.workflow_execution_summary?.summary_text);
    if (renderThinkingCardSynopsisItemHTML({ label: 'Verification', value: viewModel.workflow_verification_summary })) {
        selectedWorkflowRowEmitted = true;
    }
    addItem('Verification', viewModel.workflow_verification_summary);
    const recoveryProgress = viewModel.recovery_progress || viewModel.execution_interpretation?.recovery_progress;
    addItem('Recovery status', buildThinkingRecoveryProgressSummary(recoveryProgress));
    addItem('Recovery trigger', buildThinkingRecoveryFailureSummary(recoveryProgress), '', 'warning');
    if (interpretationFamily === 'selected_workflow'
        && renderThinkingCardSynopsisItemHTML({ label: 'Execution path', value: viewModel.execution_interpretation?.identity_summary })) {
        selectedWorkflowRowEmitted = true;
    }
    addItem('Execution path', viewModel.execution_interpretation?.identity_summary);
    if (viewModel.execution_interpretation?.post_processing_only === true
        && renderThinkingCardSynopsisItemHTML({ label: 'Progress meaning', value: viewModel.execution_interpretation?.step_summary })) {
        finalisationRowEmitted = true;
    }
    addItem('Progress meaning', viewModel.execution_interpretation?.step_summary);
    addItem('Blocker', viewModel.execution_interpretation?.blocker_summary, '', 'warning');

    const llmLifecycleText = buildThinkingCardLlmLifecycleText(
        viewModel.llm_input_lifecycle,
        { includeProvider: renderMode === THINKING_CARD_MODE_DEBUG }
    );
    const auxiliaryLlmLifecycle = isAuxiliaryThinkingCardLlmLifecycle(viewModel.llm_input_lifecycle);
    const showLlmLifecycle = !auxiliaryLlmLifecycle || renderMode === THINKING_CARD_MODE_DEBUG;
    if (showLlmLifecycle) {
        addItem(auxiliaryLlmLifecycle ? 'Auxiliary LLM input' : 'LLM input', llmLifecycleText);
        const promptPreview = buildThinkingCaptureSummaryText(viewModel.llm_input_lifecycle?.prompt_preview);
        addItem(auxiliaryLlmLifecycle ? 'Auxiliary prepared input' : 'Prepared input', promptPreview);
        const contextSummary = buildThinkingCardContextSummaryText(viewModel.llm_input_lifecycle);
        addItem(auxiliaryLlmLifecycle ? 'Auxiliary context' : 'Context', contextSummary);
    }
    addItem('Wait state', viewModel.wait_state?.label);
    addItem('Next action', viewModel.wait_state?.next_action);
    addItem('Confirmation', viewModel.confirmation_requirement);
    addItem('Uncertainty', viewModel.uncertainty_summary);
    for (const note of viewModel.missing_telemetry || []) {
        addItem('Telemetry gap', note, '', 'warning');
    }

    if (renderMode === THINKING_CARD_MODE_EXPERT || renderMode === THINKING_CARD_MODE_DEBUG) {
        if (viewModel.selected_workflow?.label) {
            addItem('Selected workflow', viewModel.selected_workflow.label);
        }
        const largeLlmCallAlerts = collectThinkingLargeLlmCallAlerts(request, viewModel);
        for (const alert of largeLlmCallAlerts) {
            addItem('Large LLM input', formatThinkingLargeLlmCallAlert(alert), '', 'warning');
        }
        for (const detail of viewModel.expert_details || []) {
            addItem('Expert detail', detail);
        }
    }

    if (renderMode === THINKING_CARD_MODE_DEBUG) {
        addItem('View-model source', formatThinkingActivityFallbackLabel(viewModel.source_authority));
        for (const detail of viewModel.debug_details || []) {
            addItem('Debug detail', detail);
        }
    }

    if (items.length === 0) {
        return '';
    }

    const evidencePresent = progressContract?.selected_workflow_evidence_present === true
        || interpretationFamily === 'selected_workflow';
    const precedenceViolation = renderMode === THINKING_CARD_MODE_DEFAULT
        && evidencePresent
        && !selectedWorkflowRowEmitted;
    if (precedenceViolation) {
        recordThinkingPrecedenceViolation({
            evidence_sources: progressContract?.selected_workflow_evidence_sources || [],
            finalisation_row_emitted: finalisationRowEmitted
        });
    }
    const violationAttr = precedenceViolation
        ? ' data-thinking-precedence-violation="selected_workflow_execution_missing"'
        : '';

    return `<section class="thinking-card-synopsis" data-thinking-progress-view-model="${escapeHtml(viewModel.schema_version || THINKING_CARD_PROGRESS_VIEW_MODEL_SCHEMA)}"${violationAttr}>
        ${items.join('')}
    </section>`;
}

/**
 * Update the thinking card meta element (elapsed time + liveness metadata).
 */
function cloneThinkingTimingEntryArray(value) {
    return Array.isArray(value)
        ? value
            .filter((entry) => entry && typeof entry === 'object')
            .map((entry) => ({ ...entry }))
        : [];
}

function cloneThinkingSlowestSpanRows(value) {
    return Array.isArray(value)
        ? value
            .filter((entry) => entry && typeof entry === 'object')
            .map((entry) => ({
                span_id: normaliseThinkingActivityString(entry.span_id),
                stage_id: normaliseThinkingActivityString(entry.stage_id || entry.stage),
                operation_kind: normaliseThinkingActivityString(entry.operation_kind),
                operation_name: normaliseThinkingActivityString(entry.operation_name),
                duration_ms: Number.isFinite(entry.duration_ms) ? Number(entry.duration_ms) : null,
                status: normaliseThinkingActivityString(entry.status),
                source: normaliseThinkingActivityString(entry.source),
                model: normaliseThinkingActivityString(entry.model),
                provider: normaliseThinkingActivityString(entry.provider),
                prompt_id: normaliseThinkingActivityString(entry.prompt_id)
            }))
        : [];
}

function cloneThinkingOperationTotalRows(value) {
    return Array.isArray(value)
        ? value
            .filter((entry) => entry && typeof entry === 'object')
            .map((entry) => ({
                operation_kind: normaliseThinkingActivityString(entry.operation_kind),
                operation_name: normaliseThinkingActivityString(entry.operation_name),
                span_count: Number.isFinite(entry.span_count) ? Number(entry.span_count) : null,
                duration_ms: Number.isFinite(entry.duration_ms) ? Number(entry.duration_ms) : null
            }))
        : [];
}

function cloneThinkingLatencySummary(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }
    return {
        min_ms: Number.isFinite(value.min_ms) ? Number(value.min_ms) : null,
        max_ms: Number.isFinite(value.max_ms) ? Number(value.max_ms) : null,
        mean_ms: Number.isFinite(value.mean_ms) ? Number(value.mean_ms) : null
    };
}

function cloneThinkingTimingSummaryTotals(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }
    return {
        elapsed_ms: Number.isFinite(value.elapsed_ms) ? Number(value.elapsed_ms) : null,
        phase_elapsed_ms: Number.isFinite(value.phase_elapsed_ms) ? Number(value.phase_elapsed_ms) : null,
        operation_elapsed_ms: Number.isFinite(value.operation_elapsed_ms) ? Number(value.operation_elapsed_ms) : null,
        llm_elapsed_ms: Number.isFinite(value.llm_elapsed_ms) ? Number(value.llm_elapsed_ms) : null,
        tool_elapsed_ms: Number.isFinite(value.tool_elapsed_ms) ? Number(value.tool_elapsed_ms) : null
    };
}

function cloneThinkingModelPromptTimingRows(value) {
    return Array.isArray(value)
        ? value
            .filter((entry) => entry && typeof entry === 'object')
            .map((entry) => ({
                stage_id: normaliseThinkingActivityString(entry.stage_id || entry.stage),
                provider: normaliseThinkingActivityString(entry.provider),
                model: normaliseThinkingActivityString(entry.model),
                prompt_id: normaliseThinkingActivityString(entry.prompt_id),
                prompt_sha256: normaliseThinkingActivityString(entry.prompt_sha256),
                call_count: Number.isFinite(entry.call_count) ? Number(entry.call_count) : null,
                success_count: Number.isFinite(entry.success_count) ? Number(entry.success_count) : null,
                failure_count: Number.isFinite(entry.failure_count) ? Number(entry.failure_count) : null,
                duration_ms: Number.isFinite(entry.duration_ms) ? Number(entry.duration_ms) : null,
                prompt_char_count: Number.isFinite(entry.prompt_char_count) ? Number(entry.prompt_char_count) : null,
                max_prompt_char_count: Number.isFinite(entry.max_prompt_char_count) ? Number(entry.max_prompt_char_count) : null,
                first_output_latency_ms: cloneThinkingLatencySummary(entry.first_output_latency_ms)
            }))
        : [];
}

function cloneThinkingTimingSummary(summary) {
    if (!summary || typeof summary !== 'object') {
        return null;
    }
    return {
        schema_version: normaliseThinkingActivityString(summary.schema_version),
        generated_at_utc: normaliseThinkingActivityString(summary.generated_at_utc),
        span_count: Number.isFinite(summary.span_count) ? Number(summary.span_count) : null,
        stored_span_count: Number.isFinite(summary.stored_span_count) ? Number(summary.stored_span_count) : null,
        dropped_span_count: Number.isFinite(summary.dropped_span_count) ? Number(summary.dropped_span_count) : null,
        summary: cloneThinkingTimingSummaryTotals(summary.summary),
        slowest_spans: cloneThinkingSlowestSpanRows(summary.slowest_spans),
        model_prompt_summary: cloneThinkingModelPromptTimingRows(summary.model_prompt_summary)
    };
}

function cloneThinkingLatestProgress(progress) {
    if (!progress || typeof progress !== 'object') {
        return null;
    }
    const copy = { ...progress };
    const semanticOperation = getThinkingSemanticOperation(progress);
    delete copy.semantic_operation;
    delete copy.semanticOperation;
    if (semanticOperation) {
        copy.semanticOperation = semanticOperation;
    }
    if (Array.isArray(progress.tool_history)) {
        copy.tool_history = cloneThinkingToolHistory(progress.tool_history);
    }
    const timingSummary = cloneThinkingTimingSummary(progress.timing_summary);
    if (timingSummary) {
        copy.timing_summary = timingSummary;
    }
    return copy;
}

function cloneThinkingTimingBreakdown(timing) {
    if (!timing || typeof timing !== 'object') {
        return null;
    }
    return {
        schema_version: normaliseThinkingActivityString(timing.schema_version),
        stages: cloneThinkingTimingEntryArray(timing.stages),
        llm_calls_by_stage_model: cloneThinkingTimingEntryArray(timing.llm_calls_by_stage_model),
        totals: timing.totals && typeof timing.totals === 'object'
            ? { ...timing.totals }
            : null,
        slowest_spans: cloneThinkingSlowestSpanRows(timing.slowest_spans),
        operation_totals: cloneThinkingOperationTotalRows(timing.operation_totals),
        model_prompt_summary: cloneThinkingModelPromptTimingRows(timing.model_prompt_summary)
    };
}

function getThinkingTimingBreakdown(request) {
    return (request?.timingBreakdown && typeof request.timingBreakdown === 'object')
        ? request.timingBreakdown
        : null;
}

function getThinkingTimingSummary(request) {
    const candidates = [
        request?.timingSummary,
        request?.latestProgress?.timing_summary
    ];
    for (const candidate of candidates) {
        if (candidate && typeof candidate === 'object') {
            return candidate;
        }
    }
    return null;
}

function getThinkingTimingRows(request) {
    const timing = getThinkingTimingBreakdown(request);
    return Array.isArray(timing?.llm_calls_by_stage_model)
        ? timing.llm_calls_by_stage_model.filter((entry) => entry && typeof entry === 'object')
        : [];
}

function getThinkingSlowestTimingSpans(request) {
    const timing = getThinkingTimingBreakdown(request);
    const summary = getThinkingTimingSummary(request);
    const candidates = [
        timing?.slowest_spans,
        summary?.slowest_spans
    ];
    for (const candidate of candidates) {
        const rows = Array.isArray(candidate)
            ? candidate.filter((entry) => entry && typeof entry === 'object')
            : [];
        if (rows.length > 0) {
            return rows
                .slice()
                .sort((left, right) => Number(right.duration_ms || 0) - Number(left.duration_ms || 0));
        }
    }
    return [];
}

function getThinkingOperationTotalRows(request) {
    const timing = getThinkingTimingBreakdown(request);
    return Array.isArray(timing?.operation_totals)
        ? timing.operation_totals.filter((entry) => entry && typeof entry === 'object')
        : [];
}

function getThinkingModelPromptTimingRows(request) {
    const timing = getThinkingTimingBreakdown(request);
    const summary = getThinkingTimingSummary(request);
    const candidates = [
        timing?.model_prompt_summary,
        summary?.model_prompt_summary
    ];
    for (const candidate of candidates) {
        const rows = Array.isArray(candidate)
            ? candidate.filter((entry) => entry && typeof entry === 'object')
            : [];
        if (rows.length > 0) {
            return rows;
        }
    }
    return [];
}

function hasSufficientThinkingTimingBaseline(row) {
    return Number.isFinite(row?.historical_observation_count)
        && Number(row.historical_observation_count) >= 3
        && Number.isFinite(row?.historical_mean_duration_ms);
}

function formatThinkingTimingBaselineMeta(request) {
    const rows = getThinkingTimingRows(request)
        .filter(hasSufficientThinkingTimingBaseline)
        .sort((a, b) => Number(b.duration_ms || 0) - Number(a.duration_ms || 0));
    if (rows.length === 0) {
        return '';
    }
    const row = rows[0];
    const model = normaliseThinkingActivityString(row.model) || 'model';
    const duration = formatThinkingDiagnosticDuration(row.duration_ms);
    const mean = formatThinkingDiagnosticDuration(row.historical_mean_duration_ms);
    if (!duration || !mean) {
        return '';
    }
    const classification = normaliseThinkingActivityString(row.duration_deviation_classification);
    const label = classification && classification !== 'within_usual_range'
        ? `${formatThinkingActivityFallbackLabel(classification).toLowerCase()}: `
        : '';
    return `${label}${model} ${duration} avg ${mean}`;
}

function updateThinkingCardMeta(request, progress, cardRoot = null) {
    const metaEl = getThinkingCardMetaEl(cardRoot);
    if (!metaEl) return;

    const effectiveProgress = (progress && typeof progress === 'object')
        ? progress
        : ((request && request.latestProgress && typeof request.latestProgress === 'object')
            ? request.latestProgress
            : null);
    updateThinkingCardStatusBadge(effectiveProgress, cardRoot);

    const bits = [];

    // Elapsed time
    const thinkingStartedAtMs = request && Number.isFinite(request.thinkingStartedAtMs)
        ? Number(request.thinkingStartedAtMs)
        : null;
    if (thinkingStartedAtMs !== null) {
        const elapsedReferenceMs = request && Number.isFinite(request.thinkingFinishedAtMs)
            ? Number(request.thinkingFinishedAtMs)
            : Date.now();
        const elapsedMs = elapsedReferenceMs - thinkingStartedAtMs;
        bits.push(formatThinkingDuration(elapsedMs));
    }

    // Tool count
    const done = effectiveProgress && Number.isFinite(effectiveProgress.tool_calls_done)
        ? Number(effectiveProgress.tool_calls_done)
        : null;
    const cap = effectiveProgress && Number.isFinite(effectiveProgress.tool_calls_cap)
        ? Number(effectiveProgress.tool_calls_cap)
        : null;
    const stage = effectiveProgress && typeof effectiveProgress.stage === 'string'
        ? effectiveProgress.stage.trim().toLowerCase()
        : '';
    const activeToolName = effectiveProgress && typeof effectiveProgress.tool === 'string'
        ? effectiveProgress.tool.trim()
        : '';
    const shouldShowToolCount = done !== null
        && cap !== null
        && cap > 0
        && (done > 0 || Boolean(activeToolName) || stage.includes('tool'));
    if (shouldShowToolCount) {
        bits.push(`${done}/${cap} tools`);
    }

    const etaText = formatThinkingEtaText(effectiveProgress);
    if (etaText) {
        bits.push(etaText);
    }

    const timingBaselineText = formatThinkingTimingBaselineMeta(request);
    if (timingBaselineText) {
        bits.push(timingBaselineText);
    }

    const lastActivityText = formatLastActivityText(effectiveProgress);
    if (lastActivityText) {
        bits.push(lastActivityText);
    }

    metaEl.textContent = bits.length > 0 ? bits.join(' \u00b7 ') : '';
    const lastActivityMs = resolveLastActivityTimestampMs(effectiveProgress);
    if (Number.isFinite(lastActivityMs)) {
        setUnambiguousTimestampTooltip(metaEl, new Date(lastActivityMs).toISOString(), 'Last activity: ');
    } else {
        metaEl.removeAttribute('title');
        metaEl.removeAttribute('aria-label');
        metaEl.removeAttribute('data-original-title');
    }
}

function recordToolUseHistory(request, progress) {
    if (!request || !progress || typeof progress !== 'object') {
        return;
    }

    const tool = typeof progress.tool === 'string' ? progress.tool.trim() : '';
    const workflowTask = typeof progress.workflow_task === 'string' ? progress.workflow_task.trim() : '';
    const phase = typeof progress.phase === 'string' ? progress.phase.trim() : '';
    const phaseLabel = typeof progress.phase_label === 'string' ? progress.phase_label.trim() : '';
    const status = typeof progress.status === 'string' ? progress.status.trim() : '';
    const resultSummary = typeof progress.result_summary === 'string' ? progress.result_summary.trim() : '';
    const semanticOperation = getThinkingSemanticOperation(progress);

    // Track phase transitions in addition to tool use.
    if (!Array.isArray(request.toolUseProgressHistory)) {
        request.toolUseProgressHistory = [];
    }

    if (!Array.isArray(request.phaseHistory)) {
        request.phaseHistory = [];
    }

    const hasCanonicalPhaseHistory = Array.isArray(progress.phase_history);

    // Record phase transitions (JVNAUTOSCI-984).
    if (!hasCanonicalPhaseHistory && phase && status === 'phase_transition') {
        const lastPhase = request.phaseHistory.length
            ? request.phaseHistory[request.phaseHistory.length - 1]
            : null;
        if (!lastPhase || lastPhase.phase !== phase) {
            request.phaseHistory.push({
                phase,
                phaseLabel,
                timestamp: Date.now(),
            });
        }
    }

    const syncedCanonicalHistory = syncThinkingToolHistoryFromProgress(request, progress);
    if (syncedCanonicalHistory) {
        return;
    }

    // Original tool/task tracking.
    if (!tool && !workflowTask) {
        return;
    }

    const batchSize = Number.isFinite(progress.batch_size) ? Number(progress.batch_size) : null;

    const history = request.toolUseProgressHistory;
    const last = history.length ? history[history.length - 1] : null;
    const lastTool = last && typeof last.tool === 'string' ? last.tool : null;
    const lastTask = last && typeof last.workflowTask === 'string' ? last.workflowTask : null;
    const lastBatch = last && Number.isFinite(last.batchSize) ? Number(last.batchSize) : null;

    // Determine success/fail status
    const isSuccess = status === 'tool_invoked';
    const isFail = status === 'tool_failed' || status === 'tool_blocked' || status === 'error';

    if (lastTool === tool && lastTask === workflowTask && lastBatch === batchSize) {
        // Update result summary and status for existing entry if new info is provided
        if (last) {
            if (resultSummary) {
                last.resultSummary = resultSummary;
            }
            if (isSuccess || isFail) {
                last.success = isSuccess;
            }
            if (semanticOperation) {
                last.semanticOperation = semanticOperation;
            }
        }
        return;
    }

    history.push({
        tool,
        workflowTask,
        batchSize,
        phase,
        resultSummary,
        success: isSuccess ? true : (isFail ? false : null),
        ...(semanticOperation ? { semanticOperation } : {})
    });
}

function normaliseThinkingActivityString(value) {
    return (typeof value === 'string') ? value.trim() : '';
}

function renderConceptSelectionButtonHTML(conceptId, label, options = {}) {
    const cleanConceptId = _normalisePotentialConceptId(conceptId);
    const cleanLabel = normaliseThinkingActivityString(label);
    if (!cleanLabel) {
        return '';
    }
    if (!cleanConceptId) {
        return escapeHtml(cleanLabel);
    }

    const classNames = Array.isArray(options.classNames)
        ? options.classNames.filter((value) => typeof value === 'string' && value.trim())
        : [];
    const buttonClass = ['concept-selection-link', ...classNames].join(' ');
    const title = normaliseThinkingActivityString(options.title) || 'Open concept tab';
    return `<button type="button" class="${escapeHtml(buttonClass)}" data-concept-id="${escapeHtml(cleanConceptId)}" title="${escapeHtml(title)}">${escapeHtml(cleanLabel)}</button>`;
}

function bindConceptSelectionClicks(container, options = {}) {
    if (!(container instanceof HTMLElement)) {
        return;
    }

    const selector = normaliseThinkingActivityString(options.selector) || '.concept-selection-link';
    const datasetKey = normaliseThinkingActivityString(options.datasetKey) || 'conceptSelectionBound';
    if (container.dataset?.[datasetKey] === 'true') {
        return;
    }

    container.addEventListener('click', (event) => {
        const target = event.target;
        if (!target || !(target instanceof HTMLElement)) {
            return;
        }
        const button = target.closest(selector);
        if (!button) {
            return;
        }
        // JVNAUTOSCI-1441: Do not call preventDefault when the concept link
        // is inside a <summary> of a <details> element, because that would
        // block the native toggle behaviour.
        const insideDetailsSummary = !!button.closest('summary')?.closest('details');
        if (!insideDetailsSummary) {
            event.preventDefault();
        }
        const conceptId = button.dataset.conceptId;
        if (!conceptId) {
            return;
        }
        dispatchSelectConceptByIdEvent(conceptId, event);
    });

    container.dataset[datasetKey] = 'true';
}

function formatThinkingActivityFallbackLabel(value) {
    const raw = normaliseThinkingActivityString(value);
    if (!raw) {
        return '';
    }
    return raw
        .replace(/_/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .replace(/^\w/, (c) => c.toUpperCase());
}

function deriveThinkingActivityState(status, eventKind) {
    const statusLower = normaliseThinkingActivityString(status).toLowerCase();
    const kindLower = normaliseThinkingActivityString(eventKind).toLowerCase();

    if (statusLower === 'error' || statusLower === 'failed' || statusLower === 'tool_failed' || statusLower === 'tool_blocked' || kindLower === 'error') {
        return 'failure';
    }

    if (
        statusLower === 'completed'
        || statusLower === 'done'
        || statusLower === 'tool_invoked'
        || statusLower === 'workflow_discovery_complete'
        || statusLower === 'llm_call_end'
        || statusLower === 'retry_end'
        || statusLower === 'orchestrator_end'
    ) {
        return 'success';
    }

    return 'pending';
}

function buildThinkingActivityLabelAndDetail(entry) {
    const status = normaliseThinkingActivityString(entry.status).toLowerCase();
    const stageLabel = normaliseThinkingActivityString(entry.stage_label) || normaliseThinkingActivityString(entry.phase_label);
    const stage = normaliseThinkingActivityString(entry.stage) || normaliseThinkingActivityString(entry.phase);
    const tool = normaliseThinkingActivityString(entry.tool);
    const workflowTask = normaliseThinkingActivityString(entry.workflow_task);
    const subtask = normaliseThinkingActivityString(entry.subtask);
    const model = normaliseThinkingActivityString(entry.model);
    const provider = normaliseThinkingActivityString(entry.provider);
    const resultSummary = normaliseThinkingActivityString(entry.result_summary);
    const error = normaliseThinkingActivityString(entry.error);
    const workflowMatchCount = Number.isFinite(entry.workflow_match_count)
        ? Math.max(0, Number(entry.workflow_match_count))
        : null;
    const workflowCandidateCount = Number.isFinite(entry.workflow_candidate_count)
        ? Math.max(0, Number(entry.workflow_candidate_count))
        : null;
    const batchSize = Number.isFinite(entry.batch_size) ? Number(entry.batch_size) : null;
    const routingNarrative = buildWorkflowRoutingNarrative(entry, null, {
        includeNoMatchTransition: true,
    });

    const stageText = stageLabel || formatThinkingActivityFallbackLabel(stage);
    const toolName = tool || workflowTask || subtask;
    const modelText = [model, provider].filter(Boolean).join(' · ');
    const detailParts = [];
    const detailHtmlParts = [];
    let label;
    const pushDetail = (text, html = null) => {
        const cleanText = normaliseThinkingActivityString(text);
        const cleanHtml = normaliseThinkingActivityString(html);
        if (!cleanText) {
            return;
        }
        detailParts.push(cleanText);
        detailHtmlParts.push(cleanHtml || escapeHtml(cleanText));
    };

    if (status === 'phase_transition') {
        label = stageText || 'Phase transition';
        if (stage && stageText.toLowerCase() !== stage.toLowerCase()) {
            pushDetail(formatThinkingActivityFallbackLabel(stage));
        }
    } else if (status === 'workflow_discovery') {
        label = 'Workflow discovery';
        pushDetail('Searching applicable workflows');
    } else if (status === 'workflow_discovery_complete') {
        label = 'Workflow discovery';
        if (workflowMatchCount === 0 && routingNarrative.context.hasSelection) {
            pushDetail(routingNarrative.text, routingNarrative.html);
        } else if (workflowMatchCount === 0 && workflowCandidateCount && workflowCandidateCount > 0) {
            pushDetail(
                workflowCandidateCount > 1
                    ? `${workflowCandidateCount} workflow candidates found`
                    : 'Relevant workflow candidate found'
            );
        } else if (workflowMatchCount === 0) {
            pushDetail('No direct workflow match found');
        } else if (workflowMatchCount && workflowMatchCount > 0) {
            pushDetail(
                workflowMatchCount > 1
                    ? `${workflowMatchCount} workflows found`
                    : '1 workflow found'
            );
        }
    } else if (status === 'orchestrator_start') {
        label = 'Workflow dispatch';
        pushDetail(routingNarrative.text, routingNarrative.html);
    } else if (status === 'orchestrator_end') {
        label = 'Finished orchestrator';
    } else if (status === 'llm_request_prepared') {
        label = 'Prepared LLM request';
        if (stageText) {
            pushDetail(stageText);
        }
    } else if (status === 'llm_call_start') {
        label = stage === 'workflow_dispatch' && stageText
            ? stageText
            : 'Starting LLM call';
        if (modelText) {
            pushDetail(modelText);
        }
    } else if (status === 'llm_call_chunk') {
        label = 'Streaming LLM output';
        if (modelText) {
            pushDetail(modelText);
        }
    } else if (status === 'llm_call_end') {
        label = stage === 'workflow_dispatch' && stageText
            ? stageText
            : 'Completed LLM call';
        if (modelText) {
            pushDetail(modelText);
        }
    } else if (status === 'tool_call_start') {
        label = toolName ? `Tool call: ${toolName}` : 'Starting tool call';
    } else if (status === 'tool_invoked') {
        label = toolName ? `Tool call completed: ${toolName}` : 'Tool call completed';
    } else if (status === 'tool_failed') {
        label = toolName ? `Tool call failed: ${toolName}` : 'Tool call failed';
    } else if (status === 'tool_blocked') {
        label = toolName ? `Tool call blocked: ${toolName}` : 'Tool call blocked';
    } else if (status === 'retry_start') {
        label = 'Retrying step';
        if (subtask) {
            pushDetail(subtask);
        }
    } else if (status === 'retry_end') {
        label = 'Retry completed';
        if (subtask) {
            pushDetail(subtask);
        }
    } else if (status === 'heartbeat') {
        label = 'Waiting for updates';
        if (stageText) {
            pushDetail(stageText);
        }
    } else if (status === 'completed' || status === 'done') {
        label = 'Turn completed';
    } else if (status === 'error' || status === 'failed') {
        label = 'Turn failed';
    } else if (toolName) {
        label = toolName;
    } else if (stageText) {
        label = stageText;
    } else if (stage) {
        label = formatThinkingActivityFallbackLabel(stage);
    } else if (entry.status) {
        label = formatThinkingActivityFallbackLabel(entry.status);
    } else if (entry.event_kind) {
        label = formatThinkingActivityFallbackLabel(entry.event_kind);
    } else {
        label = 'Activity update';
    }

    if (batchSize !== null) {
        pushDetail(`batch ${batchSize}`);
    }
    if (resultSummary) {
        pushDetail(resultSummary);
    } else if (error) {
        pushDetail(error);
    }

    return {
        label,
        detail: detailParts.join(' · '),
        detailHtml: detailHtmlParts.join(' · ')
    };
}

function buildThinkingActivityGroupingKey(entry) {
    const status = normaliseThinkingActivityString(entry.status).toLowerCase();
    const eventKind = normaliseThinkingActivityString(entry.eventKind).toLowerCase();
    const stage = normaliseThinkingActivityString(entry.stage).toLowerCase();
    const subtask = normaliseThinkingActivityString(entry.subtask).toLowerCase();
    const model = normaliseThinkingActivityString(entry.model).toLowerCase();
    return `${status}::${eventKind}::${stage}::${subtask}::${model}`;
}

function normaliseThinkingActivityHistory(diagnosticEvents) {
    if (!Array.isArray(diagnosticEvents) || diagnosticEvents.length === 0) {
        return [];
    }

    const normalised = [];

    for (const rawEntry of diagnosticEvents) {
        if (!rawEntry || typeof rawEntry !== 'object') {
            continue;
        }

        const status = normaliseThinkingActivityString(rawEntry.status);
        const eventKind = normaliseThinkingActivityString(rawEntry.event_kind);
        const stage = normaliseThinkingActivityString(rawEntry.stage) || normaliseThinkingActivityString(rawEntry.phase);
        const subtask = normaliseThinkingActivityString(rawEntry.subtask)
            || normaliseThinkingActivityString(rawEntry.tool)
            || normaliseThinkingActivityString(rawEntry.workflow_task);
        const model = normaliseThinkingActivityString(rawEntry.model);
        const sequenceNo = Number.isFinite(rawEntry.sequence_no) ? Number(rawEntry.sequence_no) : null;
        const atUtc = normaliseThinkingActivityString(rawEntry.at_utc);
        const state = deriveThinkingActivityState(status, eventKind);
        const isLowLevel = THINKING_ACTIVITY_LOW_LEVEL_EVENT_KINDS.has(eventKind.toLowerCase()) || status.toLowerCase() === 'heartbeat';
        const labelAndDetail = buildThinkingActivityLabelAndDetail(rawEntry);

        const entry = {
            sequenceNo,
            atUtc,
            stage,
            status,
            eventKind,
            label: labelAndDetail.label,
            detail: labelAndDetail.detail,
            detailHtml: labelAndDetail.detailHtml,
            state,
            isLowLevel,
            groupCount: 1,
            subtask,
            model
        };

        if (isLowLevel && normalised.length > 0) {
            const previous = normalised[normalised.length - 1];
            const groupingKey = buildThinkingActivityGroupingKey(entry);
            if (previous.isLowLevel && previous.groupingKey === groupingKey) {
                previous.groupCount = Number(previous.groupCount || 1) + 1;
                if (sequenceNo !== null) {
                    previous.sequenceNo = sequenceNo;
                }
                if (atUtc) {
                    previous.atUtc = atUtc;
                }
                if (entry.detail) {
                    previous.detail = entry.detail;
                }
                if (entry.detailHtml) {
                    previous.detailHtml = entry.detailHtml;
                }
                continue;
            }
            entry.groupingKey = groupingKey;
        } else if (isLowLevel) {
            entry.groupingKey = buildThinkingActivityGroupingKey(entry);
        }

        normalised.push(entry);
    }

    return normalised.map(({ groupingKey: _groupingKey, ...entry }) => entry);
}

function renderThinkingActivityHistoryHTML(request, mode = THINKING_CARD_MODE_DEFAULT) {
    if (!request || typeof request !== 'object') {
        return '';
    }

    const activityHistory = Array.isArray(request.activityHistory) ? request.activityHistory : [];
    if (activityHistory.length === 0) {
        return '';
    }

    const renderMode = normaliseThinkingCardMode(mode);
    const items = [];
    for (const entry of activityHistory) {
        if (!entry || typeof entry !== 'object') {
            continue;
        }

        const label = normaliseThinkingActivityString(entry.label);
        if (!label) {
            continue;
        }

        const rowClass = entry.isLowLevel ? 'thinking-card-tool thinking-card-activity is-low-level' : 'thinking-card-tool thinking-card-activity';
        items.push(renderThinkingDiagnosticRowHTML({
            ...entry,
            diagnosticKey: buildThinkingDiagnosticKey(
                'activity',
                entry.sequenceNo || '',
                entry.status || label,
                entry.stage || entry.subtask || ''
            ),
            diagnosticHtml: renderMode === THINKING_CARD_MODE_DEBUG
                ? buildThinkingActivityDiagnosticsHTML(entry)
                : ''
        }, rowClass));
    }

    return items.join('');
}

function formatThinkingDuration(elapsedMs) {
    const ms = Number.isFinite(elapsedMs) ? Math.max(0, Number(elapsedMs)) : 0;
    const totalSeconds = Math.floor(ms / 1000);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;

    if (minutes > 0) {
        return `${minutes}m ${String(seconds).padStart(2, '0')}s`;
    }
    return `${totalSeconds}s`;
}

function describeThinkingSemanticVerification(operation) {
    if (!operation || typeof operation !== 'object') {
        return '';
    }
    const verification = operation.verification && typeof operation.verification === 'object'
        ? operation.verification
        : null;
    const status = normaliseThinkingActivityString(verification?.status).toLowerCase();
    if (
        status === 'verified'
        && verification?.canonicalReadBackPresent === true
        && verification?.source === 'canonical_read_back'
    ) {
        return 'Canonical read-back verified';
    }
    if (verification?.canonicalReadBackPresent === true) {
        return 'Canonical read-back recorded; verification not confirmed';
    }
    if (status === 'receipt_only' && verification?.canonicalReadBackPresent === false) {
        return 'Tool receipt only; canonical read-back not recorded';
    }
    if (status === 'receipt_only') {
        return 'Tool receipt only; canonical read-back did not verify the outcome';
    }
    const lifecycleStatus = normaliseThinkingActivityString(operation.lifecycleStatus).toLowerCase();
    if (lifecycleStatus === 'running' || lifecycleStatus === 'pending') {
        return 'Canonical read-back pending';
    }
    if (operation.outcome) {
        return 'Tool receipt only; canonical read-back not recorded';
    }
    return 'Canonical read-back status unavailable';
}

function getThinkingSemanticArgumentCanonicalId(argument) {
    if (!argument || typeof argument !== 'object') {
        return '';
    }
    const explicitId = normaliseThinkingActivityString(argument.conceptId);
    if (explicitId) {
        return explicitId;
    }
    if (normaliseThinkingActivityString(argument.valueKind).toLowerCase() === 'text') {
        return '';
    }
    return typeof argument.value === 'string'
        ? normaliseThinkingActivityString(argument.value)
        : '';
}

/**
 * Render the tool history as structured HTML for the thinking card body.
 * No longer shows phase history (phases are in the header).
 */
function renderToolHistoryHTML(request, mode = THINKING_CARD_MODE_DEFAULT) {
    if (!request) {
        return '';
    }

    const toolHistory = getCanonicalThinkingToolHistory(request);

    if (toolHistory.length === 0) {
        return '';
    }

    const renderMode = normaliseThinkingCardMode(mode);
    const items = [];
    for (const [entryIndex, entry] of toolHistory.entries()) {
        const tool = entry && typeof entry.tool === 'string' ? entry.tool : '';
        const workflowTask = entry && typeof entry.workflowTask === 'string' ? entry.workflowTask : '';
        if (!tool && !workflowTask) {
            continue;
        }
        const batchSize = entry && Number.isFinite(entry.batchSize) ? Number(entry.batchSize) : null;
        const capabilityDescriptor = getThinkingCapabilityDescriptor(entry);
        const semanticOperation = capabilityDescriptor?.semanticOperation || null;
        const invocationIdentity = normaliseThinkingActivityString(
            entry?.callId
            || entry?.call_id
            || semanticOperation?.operationId
            || semanticOperation?.operation_id
        );
        const resultSummary = replaceOpaqueThinkingCapabilityLabel(
            entry && typeof entry.resultSummary === 'string' ? entry.resultSummary : '',
            capabilityDescriptor
        );
        const semanticSummary = replaceOpaqueThinkingCapabilityLabel(
            semanticOperation?.summary,
            capabilityDescriptor
        );
        const semanticCapabilityLabel = normaliseThinkingActivityString(
            capabilityDescriptor?.label
        );
        const isRepresentedWorkflow = (
            capabilityDescriptor?.capabilityKind === 'represented_workflow'
        );
        const success = entry.success;

        // Status icon and class
        let statusClass = 'pending';
        if (success === true) {
            statusClass = 'success';
        } else if (success === false) {
            statusClass = 'failure';
        }

        const technicalToolLabel = (
            renderMode !== THINKING_CARD_MODE_DEBUG
            && isRepresentedWorkflow
            && semanticCapabilityLabel
        )
            ? `Workflow: ${semanticCapabilityLabel}`
            : (tool
                ? `Tool call: ${tool}`
                : (workflowTask ? `Workflow task: ${workflowTask}` : ''));
        const toolLabel = renderMode === THINKING_CARD_MODE_DEFAULT && semanticSummary
            ? semanticSummary
            : technicalToolLabel;
        const toolDetail = renderMode === THINKING_CARD_MODE_DEFAULT && semanticSummary
            ? ''
            : (semanticSummary || resultSummary);
        items.push(renderThinkingDiagnosticRowHTML({
            label: toolLabel,
            detail: toolDetail,
            detailHtml: '',
            state: statusClass,
            diagnosticKey: buildThinkingDiagnosticKey(
                'tool',
                tool || workflowTask,
                invocationIdentity || `legacy-${entryIndex}`,
                batchSize ?? ''
            ),
            diagnosticHtml: renderMode === THINKING_CARD_MODE_DEFAULT
                ? ''
                : buildToolHistoryDiagnosticsHTML(entry, renderMode)
        }, 'thinking-card-tool'));
    }

    return items.join('');
}

function normaliseWorkflowDiscoveryMatches(workflowDiscovery) {
    if (!workflowDiscovery || typeof workflowDiscovery !== 'object') {
        return [];
    }

    const matches = Array.isArray(workflowDiscovery.matches) ? workflowDiscovery.matches : [];
    return matches.filter((match) => match && typeof match === 'object');
}

function normaliseWorkflowDiscoveryCandidates(workflowDiscovery) {
    if (!workflowDiscovery || typeof workflowDiscovery !== 'object') {
        return [];
    }

    const candidates = Array.isArray(workflowDiscovery.candidates) ? workflowDiscovery.candidates : [];
    return candidates.filter((match) => match && typeof match === 'object');
}

function getWorkflowDiscoveryMatchCount(workflowDiscovery) {
    if (!workflowDiscovery || typeof workflowDiscovery !== 'object') {
        return null;
    }

    if (Number.isFinite(workflowDiscovery.match_count)) {
        return Math.max(0, Number(workflowDiscovery.match_count));
    }

    return normaliseWorkflowDiscoveryMatches(workflowDiscovery).length;
}

function getWorkflowDiscoveryCandidateCount(workflowDiscovery) {
    if (!workflowDiscovery || typeof workflowDiscovery !== 'object') {
        return null;
    }

    if (Number.isFinite(workflowDiscovery.candidate_count)) {
        return Math.max(0, Number(workflowDiscovery.candidate_count));
    }

    return normaliseWorkflowDiscoveryCandidates(workflowDiscovery).length;
}

function findWorkflowDiscoveryMatchById(workflowDiscovery, workflowId) {
    const cleanWorkflowId = normaliseThinkingActivityString(workflowId);
    if (!cleanWorkflowId) {
        return null;
    }

    return normaliseWorkflowDiscoveryMatches(workflowDiscovery).find((match) => (
        normaliseThinkingActivityString(match.concept_id) === cleanWorkflowId
    )) || null;
}

function resolveWorkflowDisplayDescriptor(workflowId, workflowName, workflowDiscovery = null) {
    const cleanWorkflowId = normaliseThinkingActivityString(workflowId);
    let cleanWorkflowName = normaliseThinkingActivityString(workflowName);

    if (!cleanWorkflowName && cleanWorkflowId) {
        const match = findWorkflowDiscoveryMatchById(workflowDiscovery, cleanWorkflowId);
        cleanWorkflowName = normaliseThinkingActivityString(match?.name);
    }

    return {
        conceptId: _normalisePotentialConceptId(cleanWorkflowId),
        workflowId: cleanWorkflowId,
        workflowName: cleanWorkflowName,
        label: cleanWorkflowName && cleanWorkflowId && cleanWorkflowName !== cleanWorkflowId
            ? `${cleanWorkflowName} (${cleanWorkflowId})`
            : (cleanWorkflowName || cleanWorkflowId || '')
    };
}

function renderWorkflowDisplayHtml(workflowId, workflowName, workflowDiscovery = null, options = {}) {
    const descriptor = resolveWorkflowDisplayDescriptor(workflowId, workflowName, workflowDiscovery);
    return renderConceptSelectionButtonHTML(descriptor.conceptId, descriptor.label, {
        classNames: ['thinking-card-concept-link', ...(Array.isArray(options.classNames) ? options.classNames : [])],
        title: options.title || 'Open concept tab'
    });
}

function formatWorkflowDisplayText(workflowId, workflowName, workflowDiscovery = null) {
    return resolveWorkflowDisplayDescriptor(workflowId, workflowName, workflowDiscovery).label;
}

function buildWorkflowRoutingContext(progressLike, workflowDiscovery = null) {
    if (!progressLike || typeof progressLike !== 'object') {
        const workflowMatchCount = getWorkflowDiscoveryMatchCount(workflowDiscovery);
        return {
            selectedWorkflowId: null,
            selectedWorkflowName: null,
            selectedWorkflowText: null,
            selectedWorkflowHtml: '',
            selectorVerdict: null,
            selectorVerdictLabel: null,
            selectorSource: null,
            selectorSourceLabel: null,
            workflowMatchCount,
            workflowCandidateCount: getWorkflowDiscoveryCandidateCount(workflowDiscovery),
            hasSelection: false,
            hasDirectMatch: Number.isFinite(workflowMatchCount) && Number(workflowMatchCount) > 0,
            noDirectMatch: workflowMatchCount !== null && Number(workflowMatchCount) <= 0,
        };
    }

    const workflowSelection = getWorkflowSelectionSnapshot(progressLike);
    const workflowRoutingDiagnostics = getWorkflowRoutingDiagnostics(progressLike);
    const selectedWorkflowId = normaliseThinkingActivityString(progressLike.selected_workflow_id)
        || normaliseThinkingActivityString(workflowSelection?.selected_workflow_id)
        || deriveSelectedWorkflowIdFromRoutingDiagnostics(workflowRoutingDiagnostics)
        || null;
    const selectedWorkflowName = normaliseThinkingActivityString(progressLike.selected_workflow_name)
        || normaliseThinkingActivityString(workflowSelection?.selected_workflow_name)
        || null;
    const selectedWorkflowText = formatWorkflowDisplayText(
        selectedWorkflowId,
        selectedWorkflowName,
        workflowDiscovery
    ) || null;
    const selectedWorkflowHtml = renderWorkflowDisplayHtml(
        selectedWorkflowId,
        selectedWorkflowName,
        workflowDiscovery
    ) || (selectedWorkflowText ? escapeHtml(selectedWorkflowText) : '');
    const selectorVerdict = normaliseThinkingActivityString(progressLike.workflow_selector_verdict)
        || normaliseThinkingActivityString(
            workflowSelection?.selector_verdict ?? workflowSelection?.workflow_selector_verdict
        )
        || deriveWorkflowSelectorVerdictFromRoutingDiagnostics(workflowRoutingDiagnostics)
        || null;
    const selectorSource = normaliseThinkingActivityString(progressLike.workflow_selector_source)
        || normaliseThinkingActivityString(
            workflowSelection?.selector_source ?? workflowSelection?.workflow_selector_source
        )
        || deriveWorkflowSelectorSourceFromRoutingDiagnostics(workflowRoutingDiagnostics)
        || null;
    const workflowMatchCount = Number.isFinite(progressLike.workflow_match_count)
        ? Math.max(0, Number(progressLike.workflow_match_count))
        : (
            Number.isFinite(workflowSelection?.workflow_match_count)
                ? Math.max(0, Number(workflowSelection.workflow_match_count))
                : getWorkflowDiscoveryMatchCount(workflowDiscovery)
        );
    const dispatchDiagnostics = getWorkflowRoutingDispatchDiagnostics(progressLike);

    return {
        selectedWorkflowId,
        selectedWorkflowName,
        selectedWorkflowText,
        selectedWorkflowHtml,
        selectorVerdict,
        selectorVerdictLabel: selectorVerdict
            ? formatThinkingActivityFallbackLabel(selectorVerdict)
            : null,
        selectorSource,
        selectorSourceLabel: selectorSource
            ? formatThinkingActivityFallbackLabel(selectorSource)
            : null,
        workflowMatchCount,
        workflowCandidateCount: Number.isFinite(progressLike.workflow_candidate_count)
            ? Math.max(0, Number(progressLike.workflow_candidate_count))
            : (
                Number.isFinite(workflowSelection?.workflow_candidate_count)
                    ? Math.max(0, Number(workflowSelection.workflow_candidate_count))
                    : getWorkflowDiscoveryCandidateCount(workflowDiscovery)
            ),
        dispatchTerminalStatus: normaliseThinkingActivityString(dispatchDiagnostics?.dispatch_terminal_status) || null,
        dispatchTerminalFailureReason: normaliseThinkingActivityString(dispatchDiagnostics?.dispatch_terminal_failure_reason) || null,
        dispatchTerminalFailureDetail: normaliseThinkingActivityString(dispatchDiagnostics?.dispatch_terminal_failure_detail) || null,
        dispatchTerminalUnresolvedRequiredInputs: Array.isArray(dispatchDiagnostics?.dispatch_terminal_unresolved_required_inputs)
            ? dispatchDiagnostics.dispatch_terminal_unresolved_required_inputs
                .map((value) => normaliseThinkingActivityString(value))
                .filter(Boolean)
            : [],
        hasSelection: Boolean(selectedWorkflowText),
        hasDirectMatch: Number.isFinite(workflowMatchCount) && Number(workflowMatchCount) > 0,
        noDirectMatch: workflowMatchCount !== null && Number(workflowMatchCount) <= 0,
    };
}

function buildWorkflowRoutingNarrative(
    progressLike,
    workflowDiscovery = null,
    {
        includeNoMatchTransition = false,
        includeSource = true,
        includeVerdict = true,
        preferRouteVerb = false,
    } = {}
) {
    const context = buildWorkflowRoutingContext(progressLike, workflowDiscovery);
    const textParts = [];
    const htmlParts = [];
    const useNoMatchTransition = includeNoMatchTransition && context.noDirectMatch && context.hasSelection;

    if (context.hasSelection) {
        if (useNoMatchTransition) {
            const prefix = context.selectorSourceLabel
                ? `No direct workflow match found; routed via ${context.selectorSourceLabel.toLowerCase()} to `
                : 'No direct workflow match found; routed to ';
            textParts.push(`${prefix}${context.selectedWorkflowText}`);
            htmlParts.push(`${escapeHtml(prefix)}${context.selectedWorkflowHtml}`);
        } else if (preferRouteVerb && context.selectorSourceLabel) {
            const prefix = `Routed via ${context.selectorSourceLabel.toLowerCase()} to `;
            textParts.push(`${prefix}${context.selectedWorkflowText}`);
            htmlParts.push(`${escapeHtml(prefix)}${context.selectedWorkflowHtml}`);
        } else {
            textParts.push(`Selected ${context.selectedWorkflowText}`);
            htmlParts.push(`Selected ${context.selectedWorkflowHtml}`);
        }
    }

    if (includeSource && context.selectorSourceLabel && !useNoMatchTransition && !preferRouteVerb) {
        textParts.push(`Source: ${context.selectorSourceLabel}`);
        htmlParts.push(`Source: ${escapeHtml(context.selectorSourceLabel)}`);
    }

    if (includeVerdict && context.selectorVerdictLabel) {
        textParts.push(context.selectorVerdictLabel);
        htmlParts.push(escapeHtml(context.selectorVerdictLabel));
    }

    return {
        text: textParts.join(' · '),
        html: htmlParts.join(' · '),
        context,
    };
}

function buildThinkingDiagnosticKey(...parts) {
    return parts
        .map((value) => {
            if (Number.isFinite(value)) {
                return String(value);
            }
            if (typeof value === 'boolean') {
                return value ? 'true' : 'false';
            }
            return normaliseThinkingActivityString(value);
        })
        .map((value) => value.toLowerCase())
        .map((value) => value.replace(/[^a-z0-9#:_-]+/g, '-').replace(/^-+|-+$/g, ''))
        .filter(Boolean)
        .join('::');
}

function ensureThinkingDiagnosticExpansionState(request) {
    if (!request || typeof request !== 'object') {
        return new Set();
    }

    if (request.expandedThinkingDiagnosticKeys instanceof Set) {
        return request.expandedThinkingDiagnosticKeys;
    }

    const next = new Set(
        Array.isArray(request.expandedThinkingDiagnosticKeys)
            ? request.expandedThinkingDiagnosticKeys
                .map((value) => normaliseThinkingActivityString(value))
                .filter(Boolean)
            : []
    );
    request.expandedThinkingDiagnosticKeys = next;
    return next;
}

function snapshotThinkingDiagnosticExpansionState(container, request = getThinkingCardDisplayRequest()) {
    if (!(container instanceof HTMLElement) || !request || typeof request !== 'object') {
        return;
    }

    const expandedKeys = new Set();
    const openRows = container.querySelectorAll(`${THINKING_DIAGNOSTIC_DETAILS_SELECTOR}[open]`);
    openRows.forEach((detailsEl) => {
        const key = normaliseThinkingActivityString(detailsEl.dataset.thinkingDiagnosticKey);
        if (key) {
            expandedKeys.add(key);
        }
    });
    request.expandedThinkingDiagnosticKeys = expandedKeys;
}

function bindThinkingDiagnosticToggles(container, request = getThinkingCardDisplayRequest()) {
    if (!(container instanceof HTMLElement)) {
        return;
    }

    const expandedKeys = ensureThinkingDiagnosticExpansionState(request);
    const rows = container.querySelectorAll(THINKING_DIAGNOSTIC_DETAILS_SELECTOR);
    rows.forEach((detailsEl) => {
        const key = normaliseThinkingActivityString(detailsEl.dataset.thinkingDiagnosticKey);
        if (!key) {
            return;
        }

        detailsEl.open = expandedKeys.has(key);
        if (detailsEl.dataset.thinkingDiagnosticToggleBound === 'true') {
            return;
        }

        detailsEl.addEventListener('toggle', () => {
            const currentRequest = request || getThinkingCardDisplayRequest();
            const currentExpandedKeys = ensureThinkingDiagnosticExpansionState(currentRequest);
            if (detailsEl.open) {
                currentExpandedKeys.add(key);
            } else {
                currentExpandedKeys.delete(key);
            }
        });
        detailsEl.dataset.thinkingDiagnosticToggleBound = 'true';
    });
}

function bindThinkingLlmCallLogExpansionCache(container, request = getThinkingCardDisplayRequest()) {
    if (!(container instanceof HTMLElement) || !request || typeof request !== 'object') {
        return;
    }

    const rows = container.querySelectorAll(THINKING_LLM_CALL_LOG_DETAILS_SELECTOR);
    rows.forEach((detailsEl) => {
        const key = normaliseThinkingActivityString(detailsEl.dataset.thinkingLlmCallLogKey);
        if (!key || detailsEl.dataset.thinkingLlmCallLogCacheBound === 'true') {
            return;
        }

        detailsEl.addEventListener('toggle', () => {
            const currentRequest = request || getThinkingCardDisplayRequest();
            const state = ensureThinkingLlmCallLogState(currentRequest);
            const cache = ensureThinkingLlmCallLogEntryCache(state);
            if (detailsEl.open || !cache) {
                return;
            }
            cache.delete(key);
        });
        detailsEl.dataset.thinkingLlmCallLogCacheBound = 'true';
    });
}

function formatThinkingDiagnosticFactValue(value) {
    if (typeof value === 'boolean') {
        return value ? 'Yes' : 'No';
    }
    if (Number.isFinite(value)) {
        return String(value);
    }
    if (Array.isArray(value)) {
        return value
            .map((entry) => formatThinkingDiagnosticFactValue(entry))
            .filter(Boolean)
            .join(', ');
    }
    return normaliseThinkingActivityString(value);
}

function buildThinkingDiagnosticFactsHTML(facts) {
    if (!Array.isArray(facts) || facts.length === 0) {
        return '';
    }

    const items = facts
        .map((fact) => {
            if (!fact || typeof fact !== 'object') {
                return '';
            }
            const label = normaliseThinkingActivityString(fact.label);
            const htmlValue = normaliseThinkingActivityString(fact.html);
            const textValue = formatThinkingDiagnosticFactValue(fact.value);
            if (!label || (!htmlValue && !textValue)) {
                return '';
            }
            return `<div class="thinking-card-diagnostic-fact">
                <dt>${escapeHtml(label)}</dt>
                <dd>${htmlValue || escapeHtml(textValue)}</dd>
            </div>`;
        })
        .filter(Boolean);

    if (items.length === 0) {
        return '';
    }

    return `<dl class="thinking-card-diagnostic-facts">${items.join('')}</dl>`;
}

function normaliseThinkingProgressFactValue(value) {
    if (typeof value === 'boolean') {
        return value;
    }
    if (Number.isFinite(value)) {
        return Number(value);
    }
    if (typeof value === 'string') {
        return normaliseThinkingActivityString(value);
    }
    if (Array.isArray(value)) {
        const values = value
            .map((item) => normaliseThinkingProgressFactValue(item))
            .filter((item) => item !== null && item !== undefined && item !== '');
        return values.length > 0 ? values : null;
    }
    return null;
}

function normaliseThinkingProgressFacts(value) {
    const rawFacts = Array.isArray(value)
        ? value
        : (Array.isArray(value?.facts) ? value.facts : []);
    const facts = [];
    for (const rawFact of rawFacts) {
        if (!rawFact || typeof rawFact !== 'object') {
            continue;
        }
        const factId = normaliseThinkingActivityString(rawFact.fact_id || rawFact.id);
        const label = normaliseThinkingActivityString(rawFact.label);
        if (!factId || !label) {
            continue;
        }
        const fact = {
            schema_version: normaliseThinkingActivityString(rawFact.schema_version) || 'workflow_progress_projection.v1',
            fact_id: factId,
            label,
            status: normaliseThinkingActivityString(rawFact.status)
                || (Object.prototype.hasOwnProperty.call(rawFact, 'value') ? 'available' : 'missing'),
            present: rawFact.present === true,
            redacted: rawFact.redacted === true,
            truncated: rawFact.truncated === true,
            value_kind: normaliseThinkingActivityString(rawFact.value_kind),
            visibility: normaliseThinkingActivityString(rawFact.visibility),
            source_path: normaliseThinkingActivityString(rawFact.source_path),
            resolved_path: normaliseThinkingActivityString(rawFact.resolved_path),
            contract_id: normaliseThinkingActivityString(rawFact.contract_id),
            redaction_policy: normaliseThinkingActivityString(rawFact.redaction_policy),
            reason_code: normaliseThinkingActivityString(rawFact.reason_code),
            workflow_id: normaliseThinkingActivityString(rawFact.workflow_id),
            state_id: normaliseThinkingActivityString(rawFact.state_id),
            action_id: normaliseThinkingActivityString(rawFact.action_id)
        };
        if (Object.prototype.hasOwnProperty.call(rawFact, 'value') && !fact.redacted) {
            fact.value = normaliseThinkingProgressFactValue(rawFact.value);
        }
        facts.push(fact);
        if (facts.length >= 12) {
            break;
        }
    }
    return facts;
}

function isThinkingProgressFactVisibleForMode(fact, mode = THINKING_CARD_MODE_DEFAULT) {
    if (!fact || typeof fact !== 'object') {
        return false;
    }
    const renderMode = normaliseThinkingCardMode(mode);
    const visibility = String(fact.visibility || '').trim().toLowerCase();
    if (visibility === 'hidden' || visibility === 'none' || visibility === 'telemetry_only') {
        return false;
    }
    if (renderMode === THINKING_CARD_MODE_DEBUG) {
        return true;
    }
    if (renderMode === THINKING_CARD_MODE_EXPERT) {
        return true;
    }
    if (visibility === 'expert' || visibility === 'debug' || visibility === 'diagnostic') {
        return false;
    }
    return fact.redacted !== true && fact.status === 'available' && fact.value !== null && fact.value !== undefined && fact.value !== '';
}

function formatThinkingProgressFactValueText(value) {
    if (Array.isArray(value)) {
        return value
            .map((item) => formatThinkingProgressFactValueText(item))
            .filter(Boolean)
            .join(', ');
    }
    if (typeof value === 'boolean') {
        return value ? 'Yes' : 'No';
    }
    if (Number.isFinite(value)) {
        return String(value);
    }
    return normaliseThinkingActivityString(value);
}

function formatThinkingProgressFactInline(fact, mode = THINKING_CARD_MODE_DEFAULT) {
    if (!isThinkingProgressFactVisibleForMode(fact, mode)) {
        return '';
    }
    const label = normaliseThinkingActivityString(fact.label);
    if (!label) {
        return '';
    }
    const renderMode = normaliseThinkingCardMode(mode);
    const valueText = formatThinkingProgressFactValueText(fact.value);
    let body = valueText;
    if (fact.redacted === true) {
        body = 'redacted';
    } else if (!body && renderMode !== THINKING_CARD_MODE_DEFAULT) {
        body = formatThinkingActivityFallbackLabel(fact.status || fact.reason_code || 'missing');
    }
    if (!body) {
        return '';
    }
    const suffixes = [];
    if (fact.truncated === true) {
        suffixes.push('truncated');
    }
    if (renderMode === THINKING_CARD_MODE_DEBUG) {
        if (fact.source_path) {
            suffixes.push(`source: ${fact.source_path}`);
        }
        if (fact.resolved_path && fact.resolved_path !== fact.source_path) {
            suffixes.push(`resolved: ${fact.resolved_path}`);
        }
        if (fact.contract_id) {
            suffixes.push(`contract: ${fact.contract_id}`);
        }
        if (fact.reason_code) {
            suffixes.push(`reason: ${fact.reason_code}`);
        }
    } else if (renderMode === THINKING_CARD_MODE_EXPERT && (fact.redacted || fact.reason_code)) {
        suffixes.push(formatThinkingActivityFallbackLabel(fact.reason_code || fact.redaction_policy || 'redacted'));
    }
    return `${label}: ${body}${suffixes.length > 0 ? ` (${suffixes.join('; ')})` : ''}`;
}

function formatThinkingProgressFactsInline(value, mode = THINKING_CARD_MODE_DEFAULT, options = {}) {
    const facts = normaliseThinkingProgressFacts(value)
        .map((fact) => formatThinkingProgressFactInline(fact, mode))
        .filter(Boolean);
    const limit = Number.isFinite(options.limit) ? Math.max(1, Number(options.limit)) : 3;
    return facts.slice(0, limit).join(' · ');
}

function buildThinkingProgressFactsSectionHTML(value, mode = THINKING_CARD_MODE_EXPERT) {
    const lines = normaliseThinkingProgressFacts(value)
        .map((fact) => formatThinkingProgressFactInline(fact, mode))
        .filter(Boolean);
    if (lines.length === 0) {
        return '';
    }
    return buildThinkingDiagnosticListHTML('Projected progress facts', lines);
}

function buildThinkingDiagnosticListHTML(title, values, options = {}) {
    const items = Array.isArray(values)
        ? values
            .map((value) => normaliseThinkingActivityString(value))
            .filter(Boolean)
        : [];
    if (items.length === 0) {
        return '';
    }

    const cleanTitle = normaliseThinkingActivityString(title) || 'Details';
    const codeValues = options.code === true;
    const renderedItems = items.map((value) => {
        const content = codeValues
            ? `<code class="thinking-card-diagnostic-inline-code">${escapeHtml(value)}</code>`
            : escapeHtml(value);
        return `<li>${content}</li>`;
    });
    return `<div class="thinking-card-diagnostic-section">
        <div class="thinking-card-diagnostic-section-title">${escapeHtml(cleanTitle)}</div>
        <ul class="thinking-card-diagnostic-list">${renderedItems.join('')}</ul>
    </div>`;
}

function buildThinkingDiagnosticTextSectionHTML(title, value, options = {}) {
    const cleanTitle = normaliseThinkingActivityString(title) || 'Details';
    const cleanValue = normaliseThinkingActivityString(value);
    if (!cleanValue) {
        return '';
    }

    const codeBlock = options.codeBlock === true;
    const renderedValue = codeBlock
        ? `<pre class="thinking-card-diagnostic-pre"><code>${escapeHtml(cleanValue)}</code></pre>`
        : `<div class="thinking-card-diagnostic-text">${escapeHtml(cleanValue)}</div>`;

    return `<div class="thinking-card-diagnostic-section">
        <div class="thinking-card-diagnostic-section-title">${escapeHtml(cleanTitle)}</div>
        ${renderedValue}
    </div>`;
}

function renderThinkingDiagnosticWorkflowCandidatesHTML(candidates, workflowDiscovery = null) {
    const candidateList = Array.isArray(candidates)
        ? candidates.filter((candidate) => candidate && typeof candidate === 'object')
        : [];
    if (candidateList.length === 0) {
        return '';
    }

    const items = candidateList.map((candidate) => {
        const nameHtml = renderWorkflowDisplayHtml(
            candidate.concept_id,
            candidate.name,
            workflowDiscovery,
            { classNames: ['thinking-card-diagnostic-workflow-link'] }
        ) || escapeHtml(formatWorkflowDisplayText(candidate.concept_id, candidate.name, workflowDiscovery) || candidate.concept_id || 'Workflow candidate');
        const summaryBits = [];

        const matchSource = normaliseThinkingActivityString(candidate.match_source);
        if (matchSource) {
            summaryBits.push(`Source: ${formatThinkingActivityFallbackLabel(matchSource)}`);
        }
        if (Number.isFinite(candidate.relevance_score)) {
            summaryBits.push(`Relevance ${Math.round(Number(candidate.relevance_score) * 100)}%`);
        }
        if (Number.isFinite(candidate.confidence_score) && Number(candidate.confidence_score) > 0) {
            summaryBits.push(`Confidence ${Math.round(Number(candidate.confidence_score) * 100)}%`);
        }
        if (candidate.routing_eligible === true) {
            summaryBits.push('Routing eligible');
        } else if (candidate.routing_eligible === false) {
            const reason = formatThinkingActivityFallbackLabel(candidate.routing_exclusion_reason);
            summaryBits.push(reason ? `Routing excluded: ${reason}` : 'Routing excluded');
        }
        if (candidate.is_executable === true) {
            summaryBits.push('Executable');
        } else if (candidate.is_executable === false) {
            const reason = formatThinkingActivityFallbackLabel(candidate.executability_reason);
            summaryBits.push(reason ? `Non-executable: ${reason}` : 'Non-executable');
        }
        if (candidate.is_policy_safe === false) {
            summaryBits.push('Policy blocked');
        }

        const description = normaliseThinkingActivityString(candidate.description);
        const executabilityDetail = normaliseThinkingActivityString(candidate.executability_detail);
        return `<li class="thinking-card-diagnostic-candidate">
            <div class="thinking-card-diagnostic-candidate-name">${nameHtml}</div>
            ${summaryBits.length > 0 ? `<div class="thinking-card-diagnostic-candidate-meta">${escapeHtml(summaryBits.join(' · '))}</div>` : ''}
            ${description ? `<div class="thinking-card-diagnostic-candidate-text">${escapeHtml(description)}</div>` : ''}
            ${executabilityDetail ? `<div class="thinking-card-diagnostic-candidate-text">${escapeHtml(executabilityDetail)}</div>` : ''}
        </li>`;
    });

    return `<div class="thinking-card-diagnostic-section">
        <div class="thinking-card-diagnostic-section-title">Workflow candidates</div>
        <ul class="thinking-card-diagnostic-candidates">${items.join('')}</ul>
    </div>`;
}

function renderThinkingDiagnosticPanelHTML({ facts = [], sections = [] } = {}) {
    const factsHtml = buildThinkingDiagnosticFactsHTML(facts);
    const extraSections = Array.isArray(sections)
        ? sections.filter((section) => normaliseThinkingActivityString(section))
        : [];
    if (!factsHtml && extraSections.length === 0) {
        return '';
    }

    return `<div class="thinking-card-diagnostic-panel">${factsHtml}${extraSections.join('')}</div>`;
}

function renderThinkingDiagnosticRowHTML(entry, rowClass = 'thinking-card-tool') {
    if (!entry || typeof entry !== 'object') {
        return '';
    }

    const label = normaliseThinkingActivityString(entry.label);
    if (!label) {
        return '';
    }

    const statusClass = (entry.state === 'success' || entry.state === 'failure') ? entry.state : 'pending';
    const statusIcon = statusClass === 'success' ? '✓' : (statusClass === 'failure' ? '✗' : '');
    const diagnosticHtml = normaliseThinkingActivityString(entry.diagnosticHtml);
    const detailHtmlParts = [];
    if (Number.isFinite(entry.groupCount) && Number(entry.groupCount) > 1) {
        detailHtmlParts.push(escapeHtml(`${Number(entry.groupCount)} updates`));
    }
    // JVNAUTOSCI-1441: For collapsible rows (<details>), use plain text in
    // <summary> to avoid interactive <button> elements that prevent the
    // native <details> toggle.
    if (diagnosticHtml && normaliseThinkingActivityString(entry.detail)) {
        detailHtmlParts.push(escapeHtml(normaliseThinkingActivityString(entry.detail)));
    } else if (normaliseThinkingActivityString(entry.detailHtml)) {
        detailHtmlParts.push(entry.detailHtml);
    } else if (normaliseThinkingActivityString(entry.detail)) {
        detailHtmlParts.push(escapeHtml(normaliseThinkingActivityString(entry.detail)));
    }
    const detailLabel = detailHtmlParts.length > 0
        ? `<span class="thinking-card-tool-result">${detailHtmlParts.join(' · ')}</span>`
        : '';

    const summaryHtml = `<span class="thinking-card-tool-status ${statusClass}">${statusIcon}</span>
        <span class="thinking-card-tool-name">${escapeHtml(label)}</span>${detailLabel}`;
    if (!diagnosticHtml) {
        return `<div class="${rowClass}">${summaryHtml}</div>`;
    }

    const diagnosticKey = normaliseThinkingActivityString(entry.diagnosticKey)
        || buildThinkingDiagnosticKey(label, entry.detail, statusClass);
    return `<details class="thinking-card-diagnostic-row${entry.isLowLevel ? ' is-low-level' : ''}" data-thinking-diagnostic-key="${escapeHtml(diagnosticKey)}">
        <summary class="${rowClass}">${summaryHtml}<span class="thinking-card-diagnostic-toggle-indicator" aria-hidden="true">▸</span></summary>
        ${diagnosticHtml}
    </details>`;
}

function canonicaliseThinkingDiagnosticStageId(stageId) {
    const cleanStageId = normaliseThinkingActivityString(stageId);
    if (cleanStageId === 'workflow_discovery_complete') {
        return 'workflow_discovery';
    }
    return cleanStageId;
}

function getThinkingDiagnosticEvents(request) {
    const diagnosticEvents = request?.latestProgress?.diagnostic_events;
    return Array.isArray(diagnosticEvents)
        ? diagnosticEvents.filter((entry) => entry && typeof entry === 'object')
        : [];
}

function getThinkingDiagnosticEventsForStage(request, stageId) {
    const cleanStageId = canonicaliseThinkingDiagnosticStageId(stageId);
    if (!cleanStageId) {
        return [];
    }

    return getThinkingDiagnosticEvents(request).filter((entry) => (
        canonicaliseThinkingDiagnosticStageId(entry.phase || entry.stage) === cleanStageId
    ));
}

function getThinkingStageDiagnosticEntry(request, stageId) {
    const cleanStageId = canonicaliseThinkingDiagnosticStageId(stageId);
    if (!cleanStageId) {
        return null;
    }

    const stageDiagnostics = Array.isArray(request?.stageDiagnostics)
        ? request.stageDiagnostics
        : [];
    for (const entry of stageDiagnostics) {
        if (!entry || typeof entry !== 'object') {
            continue;
        }
        const directStageId = canonicaliseThinkingDiagnosticStageId(entry.stage_id || entry.stageId);
        if (directStageId === cleanStageId) {
            return entry;
        }
        const nestedDiagnostics = entry.diagnostics;
        if (nestedDiagnostics && typeof nestedDiagnostics === 'object') {
            const nestedStageId = canonicaliseThinkingDiagnosticStageId(
                nestedDiagnostics.stage_id || nestedDiagnostics.stageId
            );
            if (nestedStageId === cleanStageId) {
                return nestedDiagnostics;
            }
        }
    }

    return null;
}

function normaliseThinkingDiagnosticCapture(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }
    const text = normaliseThinkingActivityString(value.text);
    const preview = normaliseThinkingActivityString(value.preview);
    const charCount = Number.isFinite(value.char_count)
        ? Number(value.char_count)
        : null;
    if (!text && !preview && !Number.isFinite(charCount)) {
        return null;
    }
    return {
        text: text || null,
        preview: preview || null,
        char_count: charCount,
        preview_truncated: value.preview_truncated === true
    };
}

function buildThinkingLiveLlmExchange(stageId, stageDiagnostic, latestStageEvent, latestProgress) {
    const cleanStageId = canonicaliseThinkingDiagnosticStageId(stageId);
    const currentStageId = canonicaliseThinkingDiagnosticStageId(
        latestProgress?.phase || latestProgress?.stage
    );
    const candidates = [];
    if (stageDiagnostic?.latest_llm_exchange && typeof stageDiagnostic.latest_llm_exchange === 'object') {
        candidates.push(stageDiagnostic.latest_llm_exchange);
    }
    if (latestStageEvent && typeof latestStageEvent === 'object') {
        candidates.push(latestStageEvent);
    }
    if (cleanStageId && currentStageId === cleanStageId && latestProgress && typeof latestProgress === 'object') {
        candidates.push(latestProgress);
    }

    for (const candidate of candidates) {
        if (!candidate || typeof candidate !== 'object') {
            continue;
        }
        if (candidate.prompt_preview && typeof candidate.prompt_preview === 'object') {
            return {
                entry_type: normaliseThinkingActivityString(candidate.entry_type) || 'live_llm_request',
                stage: normaliseThinkingActivityString(candidate.stage) || cleanStageId || null,
                llm_request_state: normaliseThinkingActivityString(candidate.llm_request_state) || null,
                prompt_preview: normaliseThinkingDiagnosticCapture(candidate.prompt_preview),
                context_summary: (candidate.context_summary && typeof candidate.context_summary === 'object')
                    ? { ...candidate.context_summary }
                    : null,
                context_message_count: Number.isFinite(candidate.context_message_count)
                    ? Number(candidate.context_message_count)
                    : null,
                tool_definition_count: Number.isFinite(candidate.tool_definition_count)
                    ? Number(candidate.tool_definition_count)
                    : null,
                selected_model: normaliseThinkingActivityString(candidate.selected_model || candidate.model) || null,
                selected_provider: normaliseThinkingActivityString(candidate.selected_provider || candidate.provider) || null,
                fallback_attempt_no: Number.isFinite(candidate.fallback_attempt_no)
                    ? Number(candidate.fallback_attempt_no)
                    : null,
                fallback_candidate_count: Number.isFinite(candidate.fallback_candidate_count)
                    ? Number(candidate.fallback_candidate_count)
                    : null,
                llm_request_prepared_at_utc: normaliseThinkingActivityString(candidate.llm_request_prepared_at_utc) || null,
                llm_request_sent_at_utc: normaliseThinkingActivityString(candidate.llm_request_sent_at_utc) || null,
                llm_first_output_at_utc: normaliseThinkingActivityString(candidate.llm_first_output_at_utc) || null,
                context_lineage: (candidate.context_lineage && typeof candidate.context_lineage === 'object')
                    ? { ...candidate.context_lineage }
                    : null,
                response_preview: normaliseThinkingDiagnosticCapture(candidate.response_preview || candidate.llm_response_preview)
            };
        }

        const llmRequest = (candidate.llm_request && typeof candidate.llm_request === 'object')
            ? candidate.llm_request
            : null;
        if (!llmRequest && !candidate.llm_request_state && !(candidate.llm_response_preview && typeof candidate.llm_response_preview === 'object')) {
            continue;
        }
        return {
            entry_type: 'live_llm_request',
            stage: cleanStageId || null,
            llm_request_state: normaliseThinkingActivityString(candidate.llm_request_state) || null,
            prompt_preview: normaliseThinkingDiagnosticCapture(llmRequest?.prompt),
            context_summary: (llmRequest?.context_summary && typeof llmRequest.context_summary === 'object')
                ? { ...llmRequest.context_summary }
                : null,
            context_lineage: (llmRequest?.context_lineage && typeof llmRequest.context_lineage === 'object')
                ? { ...llmRequest.context_lineage }
                : null,
            context_message_count: Number.isFinite(llmRequest?.context_message_count)
                ? Number(llmRequest.context_message_count)
                : null,
            tool_definition_count: Number.isFinite(llmRequest?.tool_count)
                ? Number(llmRequest.tool_count)
                : null,
            selected_model: normaliseThinkingActivityString(candidate.model) || null,
            selected_provider: normaliseThinkingActivityString(candidate.provider) || null,
            fallback_attempt_no: Number.isFinite(candidate.fallback_attempt_no)
                ? Number(candidate.fallback_attempt_no)
                : null,
            fallback_candidate_count: Number.isFinite(candidate.fallback_candidate_count)
                ? Number(candidate.fallback_candidate_count)
                : null,
            llm_request_prepared_at_utc: normaliseThinkingActivityString(candidate.llm_request_prepared_at_utc) || null,
            llm_request_sent_at_utc: normaliseThinkingActivityString(candidate.llm_request_sent_at_utc) || null,
            llm_first_output_at_utc: normaliseThinkingActivityString(candidate.llm_first_output_at_utc) || null,
            response_preview: normaliseThinkingDiagnosticCapture(candidate.llm_response_preview)
        };
    }

    return null;
}

function formatThinkingLlmRequestState(state) {
    const cleanState = normaliseThinkingActivityString(state).toLowerCase();
    switch (cleanState) {
    case 'prepared':
        return 'Prepared';
    case 'sent':
        return 'Sent';
    case 'received_output':
        return 'Received output';
    case 'completed':
        return 'Completed';
    case 'failed':
        return 'Failed';
    default:
        return cleanState ? formatThinkingActivityFallbackLabel(cleanState) : '';
    }
}

function buildThinkingLlmContextSummaryLines(summary) {
    if (!summary || typeof summary !== 'object') {
        return [];
    }
    const lines = [];
    if (Number.isFinite(summary.message_count)) {
        lines.push(`${Number(summary.message_count)} context messages`);
    }
    if (Number.isFinite(summary.leading_system_message_count) && Number(summary.leading_system_message_count) > 0) {
        lines.push(`${Number(summary.leading_system_message_count)} leading system messages`);
    }
    if (summary.role_counts && typeof summary.role_counts === 'object') {
        const roleCounts = Object.entries(summary.role_counts)
            .filter(([, value]) => Number.isFinite(Number(value)))
            .map(([role, value]) => `${role}: ${Number(value)}`);
        if (roleCounts.length > 0) {
            lines.push(`Roles: ${roleCounts.join(', ')}`);
        }
    }
    if (Number.isFinite(summary.total_content_chars)) {
        lines.push(`${Number(summary.total_content_chars)} content chars`);
    }
    return lines;
}

function buildThinkingLlmContextLineageLines(lineage) {
    if (!lineage || typeof lineage !== 'object') {
        return [];
    }
    const lines = [];
    const baseContextSource = normaliseThinkingActivityString(lineage.base_context_source);
    if (baseContextSource) {
        lines.push(`Base context source: ${formatThinkingActivityFallbackLabel(baseContextSource)}`);
    }
    const insertionStrategy = normaliseThinkingActivityString(lineage.insertion_strategy);
    if (insertionStrategy) {
        lines.push(`Insertion strategy: ${formatThinkingActivityFallbackLabel(insertionStrategy)}`);
    }
    if (Number.isFinite(lineage.stage_added_message_count)) {
        lines.push(
            formatThinkingCountLabel(
                Number(lineage.stage_added_message_count),
                'stage-added message'
            )
        );
    }
    const baseContextSummaryLines = buildThinkingLlmContextSummaryLines(lineage.base_context_summary);
    if (baseContextSummaryLines.length > 0) {
        lines.push(`Base context: ${baseContextSummaryLines.join(', ')}`);
    }
    const stageContextSummaryLines = buildThinkingLlmContextSummaryLines(lineage.stage_context_summary);
    if (stageContextSummaryLines.length > 0) {
        lines.push(`Stage context: ${stageContextSummaryLines.join(', ')}`);
    }
    if (lineage.trimmed === true) {
        lines.push('Stage context was trimmed before sending');
    }
    const stageAddedMessages = Array.isArray(lineage.stage_added_messages)
        ? lineage.stage_added_messages.filter((entry) => entry && typeof entry === 'object')
        : [];
    for (const entry of stageAddedMessages.slice(0, 3)) {
        const role = normaliseThinkingActivityString(entry.role) || 'message';
        const preview = normaliseThinkingActivityString(entry.preview);
        const content = normaliseThinkingActivityString(entry.content);
        const snippet = preview || content;
        if (snippet) {
            lines.push(`${formatThinkingActivityFallbackLabel(role)} added: ${snippet}`);
        }
    }
    return lines;
}

function buildThinkingCaptureSummaryText(capture, fallback = '') {
    if (!capture || typeof capture !== 'object') {
        return fallback;
    }
    const preview = normaliseThinkingActivityString(capture.preview);
    if (preview) {
        return preview;
    }
    const text = normaliseThinkingActivityString(capture.text);
    if (!text) {
        return fallback;
    }
    const collapsed = text.replace(/\s+/g, ' ').trim();
    if (collapsed.length <= 120) {
        return collapsed;
    }
    return `${collapsed.slice(0, 117).trimEnd()}...`;
}

function buildThinkingWorkflowStageDiagnosticData(stageId, stageLabel, request) {
    const cleanStageId = canonicaliseThinkingDiagnosticStageId(stageId);
    if (!cleanStageId) {
        return null;
    }

    const stageDiagnostic = getThinkingStageDiagnosticEntry(request, cleanStageId);
    const stageEvents = getThinkingDiagnosticEventsForStage(request, cleanStageId);
    const latestStageEvent = stageEvents.length > 0 ? stageEvents[stageEvents.length - 1] : null;
    const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const workflowDiscovery = (request?.workflowDiscovery && typeof request.workflowDiscovery === 'object')
        ? request.workflowDiscovery
        : null;
    const toolHistory = getCanonicalThinkingToolHistory(request);
    const canonicalRoutingProgress = buildCanonicalWorkflowRoutingProgress(request);
    const stageRoutingProgress = buildCanonicalWorkflowRoutingProgress(request, stageDiagnostic);
    const routingNarrative = buildWorkflowRoutingNarrative(canonicalRoutingProgress, workflowDiscovery, {
        includeNoMatchTransition: true,
    });
    const stageRoutingNarrative = buildWorkflowRoutingNarrative(stageRoutingProgress, workflowDiscovery, {
        includeNoMatchTransition: true,
    });
    const selectorDiagnostics = buildThinkingSelectorDiagnosticsSnapshot(
        stageRoutingProgress.workflow_routing_diagnostics
    );
    const latestLlmExchange = buildThinkingLiveLlmExchange(
        cleanStageId,
        stageDiagnostic,
        latestStageEvent,
        latestProgress
    );
    const llmPromptPreview = normaliseThinkingDiagnosticCapture(latestLlmExchange?.prompt_preview);
    const llmResponsePreview = normaliseThinkingDiagnosticCapture(latestLlmExchange?.response_preview);
    const llmInputRecorded = stageDiagnostic?.llm_input_recorded === true || Boolean(llmPromptPreview);
    const llmOutputRecorded = stageDiagnostic?.llm_output_recorded === true || Boolean(llmResponsePreview);
    const hasRecordedLlmExchange = stageDiagnostic?.has_recorded_llm_exchange === true
        || (Boolean(llmPromptPreview) && Boolean(llmResponsePreview));
    const llmExchangeRecordCount = Number.isFinite(stageDiagnostic?.llm_exchange_record_count)
        ? Math.max(Number(stageDiagnostic.llm_exchange_record_count), latestLlmExchange ? 1 : 0)
        : (latestLlmExchange ? 1 : 0);
    const missingRecordedLlmInput = stageDiagnostic?.missing_recorded_llm_input === true
        || (!llmInputRecorded);
    const missingRecordedLlmOutput = stageDiagnostic?.missing_recorded_llm_output === true
        || (!llmOutputRecorded);
    const latestProgressFacts = normaliseThinkingProgressFacts(
        stageDiagnostic?.progress_facts
        || latestStageEvent?.progress_facts
        || latestProgress?.progress_facts
    );

    const data = {
        stage_id: cleanStageId,
        stage_label: normaliseThinkingActivityString(stageLabel) || formatThinkingActivityFallbackLabel(cleanStageId) || 'Workflow step',
        stage_event_count: Number.isFinite(stageDiagnostic?.event_count)
            ? Number(stageDiagnostic.event_count)
            : stageEvents.length,
        latest_status: normaliseThinkingActivityString(stageDiagnostic?.latest_status)
            || normaliseThinkingActivityString(latestStageEvent?.status)
            || null,
        latest_at_utc: normaliseThinkingActivityString(stageDiagnostic?.latest_at_utc)
            || normaliseThinkingActivityString(latestStageEvent?.at_utc)
            || null,
        latest_result_summary: normaliseThinkingActivityString(stageDiagnostic?.latest_result_summary)
            || normaliseThinkingActivityString(latestStageEvent?.result_summary)
            || null,
        latest_error: normaliseThinkingActivityString(stageDiagnostic?.latest_error)
            || normaliseThinkingActivityString(latestStageEvent?.error)
            || null,
        llm_input_recorded: llmInputRecorded,
        llm_output_recorded: llmOutputRecorded,
        has_recorded_llm_exchange: hasRecordedLlmExchange,
        llm_exchange_record_count: llmExchangeRecordCount,
        missing_recorded_llm_input: missingRecordedLlmInput,
        missing_recorded_llm_output: missingRecordedLlmOutput,
        python_decision_count: Number.isFinite(stageDiagnostic?.python_decision_count)
            ? Number(stageDiagnostic.python_decision_count)
            : 0,
        possibly_inappropriate_python_code_use_count: Number.isFinite(stageDiagnostic?.possibly_inappropriate_python_code_use_count)
            ? Number(stageDiagnostic.possibly_inappropriate_python_code_use_count)
            : 0,
        python_decision_classes: Array.isArray(stageDiagnostic?.python_decision_classes)
            ? stageDiagnostic.python_decision_classes
                .map((value) => normaliseThinkingActivityString(value))
                .filter(Boolean)
            : [],
        python_decision_sources: Array.isArray(stageDiagnostic?.python_decision_sources)
            ? stageDiagnostic.python_decision_sources
                .map((value) => normaliseThinkingActivityString(value))
                .filter(Boolean)
            : [],
        latest_llm_exchange: latestLlmExchange,
        llm_request_state: normaliseThinkingActivityString(latestLlmExchange?.llm_request_state) || null,
        llm_request_prepared_at_utc: normaliseThinkingActivityString(latestLlmExchange?.llm_request_prepared_at_utc) || null,
        llm_request_sent_at_utc: normaliseThinkingActivityString(latestLlmExchange?.llm_request_sent_at_utc) || null,
        llm_first_output_at_utc: normaliseThinkingActivityString(latestLlmExchange?.llm_first_output_at_utc) || null,
        llm_prompt_preview: llmPromptPreview,
        llm_response_preview: llmResponsePreview,
        llm_context_summary: (latestLlmExchange?.context_summary && typeof latestLlmExchange.context_summary === 'object')
            ? { ...latestLlmExchange.context_summary }
            : null,
        llm_context_lineage: (latestLlmExchange?.context_lineage && typeof latestLlmExchange.context_lineage === 'object')
            ? { ...latestLlmExchange.context_lineage }
            : null,
        llm_context_message_count: Number.isFinite(latestLlmExchange?.context_message_count)
            ? Number(latestLlmExchange.context_message_count)
            : null,
        llm_tool_definition_count: Number.isFinite(latestLlmExchange?.tool_definition_count)
            ? Number(latestLlmExchange.tool_definition_count)
            : null,
        llm_selected_model: normaliseThinkingActivityString(latestLlmExchange?.selected_model) || null,
        llm_selected_provider: normaliseThinkingActivityString(latestLlmExchange?.selected_provider) || null,
        llm_fallback_attempt_no: Number.isFinite(latestLlmExchange?.fallback_attempt_no)
            ? Number(latestLlmExchange.fallback_attempt_no)
            : null,
        llm_fallback_candidate_count: Number.isFinite(latestLlmExchange?.fallback_candidate_count)
            ? Number(latestLlmExchange.fallback_candidate_count)
            : null,
        progress_facts: latestProgressFacts
    };

    if (
        stageRoutingNarrative.context.hasSelection
        || stageRoutingNarrative.context.selectorVerdict
        || stageRoutingNarrative.context.selectorSource
    ) {
        data.selected_workflow_id = stageRoutingNarrative.context.selectedWorkflowId;
        data.selected_workflow_name = stageRoutingNarrative.context.selectedWorkflowName;
        data.workflow_selector_verdict = stageRoutingNarrative.context.selectorVerdict;
        data.workflow_selector_source = stageRoutingNarrative.context.selectorSource;
        data.workflow_selection_narrative = stageRoutingNarrative.text || null;
        data.workflow_selection_narrative_html = stageRoutingNarrative.html || null;
    }

    if (cleanStageId === 'selected_workflow_execution') {
        const selectedWorkflowExecution = getThinkingSelectedWorkflowExecution(request);
        data.selected_workflow_execution = selectedWorkflowExecution;
        data.selected_workflow_id = selectedWorkflowExecution?.selected_workflow_id || null;
        data.selected_workflow_name = selectedWorkflowExecution?.selected_workflow_name || null;
        data.selected_workflow_event_count = Number.isFinite(selectedWorkflowExecution?.event_count)
            ? Number(selectedWorkflowExecution.event_count)
            : 0;
        data.latest_selected_workflow_event = selectedWorkflowExecution?.latest_event || null;
        const selectedProgressFacts = normaliseThinkingProgressFacts(
            data.latest_selected_workflow_event?.progress_facts
            || selectedWorkflowExecution?.progress_facts
        );
        if (selectedProgressFacts.length > 0) {
            data.progress_facts = selectedProgressFacts;
        }
    }

    data.latest_subtask = normaliseThinkingActivityString(stageDiagnostic?.latest_subtask)
        || normaliseThinkingActivityString(latestStageEvent?.subtask)
        || null;
    data.latest_workflow_task = normaliseThinkingActivityString(stageDiagnostic?.latest_workflow_task)
        || normaliseThinkingActivityString(latestStageEvent?.workflow_task)
        || null;
    data.latest_tool = normaliseThinkingActivityString(stageDiagnostic?.latest_tool)
        || normaliseThinkingActivityString(latestStageEvent?.tool)
        || null;
    data.workflow_selection_rationale = normaliseThinkingActivityString(stageDiagnostic?.workflow_selection_rationale) || null;
    data.pre_dispatch = (stageDiagnostic?.pre_dispatch && typeof stageDiagnostic.pre_dispatch === 'object')
        ? { ...stageDiagnostic.pre_dispatch }
        : null;
    data.tool_execution = (stageDiagnostic?.tool_execution && typeof stageDiagnostic.tool_execution === 'object')
        ? { ...stageDiagnostic.tool_execution }
        : null;
    data.critic_verdict = (stageDiagnostic?.critic_verdict && typeof stageDiagnostic.critic_verdict === 'object')
        ? { ...stageDiagnostic.critic_verdict }
        : null;
    data.completion_gate = (stageDiagnostic?.completion_gate && typeof stageDiagnostic.completion_gate === 'object')
        ? { ...stageDiagnostic.completion_gate }
        : null;
    data.response_transformation = (
        stageDiagnostic?.response_transformation
        && typeof stageDiagnostic.response_transformation === 'object'
    )
        ? {
            ...stageDiagnostic.response_transformation,
            input_summary: (
                stageDiagnostic.response_transformation.input_summary
                && typeof stageDiagnostic.response_transformation.input_summary === 'object'
            )
                ? { ...stageDiagnostic.response_transformation.input_summary }
                : {},
            output_summary: (
                stageDiagnostic.response_transformation.output_summary
                && typeof stageDiagnostic.response_transformation.output_summary === 'object'
            )
                ? { ...stageDiagnostic.response_transformation.output_summary }
                : {}
        }
        : null;

    if (cleanStageId === 'workflow_discovery' && workflowDiscovery) {
        data.requested_query = normaliseThinkingActivityString(workflowDiscovery.requested_query) || null;
        data.query = normaliseThinkingActivityString(workflowDiscovery.query) || null;
        data.search_sources = Array.isArray(workflowDiscovery.search_sources)
            ? workflowDiscovery.search_sources
                .map((value) => normaliseThinkingActivityString(value))
                .filter(Boolean)
            : [];
        data.threshold = Number.isFinite(workflowDiscovery.threshold) ? Number(workflowDiscovery.threshold) : null;
        data.search_time_ms = Number.isFinite(workflowDiscovery.search_time_ms) ? Math.round(Number(workflowDiscovery.search_time_ms)) : null;
        data.timeout_budget_seconds = Number.isFinite(workflowDiscovery.timeout_budget_seconds)
            ? Number(workflowDiscovery.timeout_budget_seconds)
            : null;
        data.budget_exhausted = workflowDiscovery.budget_exhausted === true;
        data.budget_exhaustion_stage = normaliseThinkingActivityString(workflowDiscovery.budget_exhaustion_stage) || null;
        data.budget_exhaustion_detail = normaliseThinkingActivityString(workflowDiscovery.budget_exhaustion_detail) || null;
        data.namespace = normaliseThinkingActivityString(workflowDiscovery.namespace) || null;
        data.allow_non_executable = workflowDiscovery.allow_non_executable === true;
        data.match_count = getWorkflowDiscoveryMatchCount(workflowDiscovery);
        data.candidate_count = getWorkflowDiscoveryCandidateCount(workflowDiscovery);
        data.errors = Array.isArray(workflowDiscovery.errors)
            ? workflowDiscovery.errors
                .map((value) => normaliseThinkingActivityString(value))
                .filter(Boolean)
            : [];
        data.candidates = normaliseWorkflowDiscoveryCandidates(workflowDiscovery).map((candidate) => ({ ...candidate }));
        data.selected_workflow_id = routingNarrative.context.selectedWorkflowId;
        data.selected_workflow_name = routingNarrative.context.selectedWorkflowName;
        data.workflow_selector_verdict = routingNarrative.context.selectorVerdict;
        data.workflow_selector_source = routingNarrative.context.selectorSource;
        data.workflow_selection_narrative = routingNarrative.text || null;
        data.workflow_selection_narrative_html = routingNarrative.html || null;
    }

    if (
        cleanStageId === 'selector_preparation'
        || cleanStageId === 'selector_decision'
        || cleanStageId === 'workflow_dispatch_prepare'
        || cleanStageId === 'workflow_dispatch'
        || cleanStageId === 'plain_response'
        || cleanStageId === 'tool_plan'
    ) {
        data.selected_workflow_id = stageRoutingNarrative.context.selectedWorkflowId;
        data.selected_workflow_name = stageRoutingNarrative.context.selectedWorkflowName;
        data.workflow_selector_verdict = stageRoutingNarrative.context.selectorVerdict;
        data.workflow_selector_source = stageRoutingNarrative.context.selectorSource;
        data.workflow_match_count = stageRoutingNarrative.context.workflowMatchCount;
        data.workflow_candidate_count = stageRoutingNarrative.context.workflowCandidateCount;
        data.workflow_selection_narrative = stageRoutingNarrative.text || null;
        data.workflow_selection_narrative_html = stageRoutingNarrative.html || null;
        data.dispatch_terminal_status = normaliseThinkingActivityString(stageDiagnostic?.dispatch_terminal_status)
            || stageRoutingNarrative.context.dispatchTerminalStatus;
        data.dispatch_terminal_failure_reason = normaliseThinkingActivityString(stageDiagnostic?.dispatch_terminal_failure_reason)
            || stageRoutingNarrative.context.dispatchTerminalFailureReason;
        data.dispatch_terminal_failure_detail = normaliseThinkingActivityString(stageDiagnostic?.dispatch_terminal_failure_detail)
            || stageRoutingNarrative.context.dispatchTerminalFailureDetail;
        data.dispatch_terminal_unresolved_required_inputs = Array.isArray(stageDiagnostic?.dispatch_terminal_unresolved_required_inputs)
            ? stageDiagnostic.dispatch_terminal_unresolved_required_inputs
                .map((value) => normaliseThinkingActivityString(value))
                .filter(Boolean)
            : stageRoutingNarrative.context.dispatchTerminalUnresolvedRequiredInputs;
        data.selector_prompt_id = selectorDiagnostics?.prompt_id || null;
        data.selector_requested_prompt_ids = Array.isArray(selectorDiagnostics?.requested_prompt_ids)
            ? selectorDiagnostics.requested_prompt_ids.slice()
            : [];
        data.selector_prompt = selectorDiagnostics?.prompt || null;
        data.selector_candidate_list = selectorDiagnostics?.candidate_list || null;
        data.selector_response = selectorDiagnostics?.response || null;
    }

    if (cleanStageId === 'tool_execute') {
        const successCount = toolHistory.filter((entry) => entry.success === true).length;
        const failureCount = toolHistory.filter((entry) => entry.success === false).length;
        data.tool_history = toolHistory;
        data.tool_call_count = toolHistory.length;
        data.tool_success_count = successCount;
        data.tool_failure_count = failureCount;
        data.tool_pending_count = Math.max(0, toolHistory.length - successCount - failureCount);
    }

    return data;
}

function formatThinkingDiagnosticDuration(value) {
    return Number.isFinite(value) ? `${Math.max(0, Math.round(Number(value)))} ms` : '';
}

function formatThinkingCountLabel(value, singular, plural = `${singular}s`) {
    if (!Number.isFinite(value)) {
        return '';
    }
    const count = Math.max(0, Number(value));
    return `${count} ${count === 1 ? singular : plural}`;
}

function describeThinkingTransformationSource(sourcePath, stageId) {
    const cleanSourcePath = normaliseThinkingActivityString(sourcePath).toLowerCase();
    if (!cleanSourcePath) {
        return stageId === 'narration'
            ? 'the prepared screen response'
            : 'the draft response';
    }
    switch (cleanSourcePath) {
    case 'response_text':
        return 'the drafted reply';
    case 'response_text_plus_follow_up_summary':
        return 'the drafted reply and follow-up summary';
    case 'follow_up_summary':
        return 'the follow-up summary';
    case 'llm_synthesis':
        return stageId === 'narration'
            ? 'a synthesised narration draft'
            : 'a synthesised screen draft';
    case 'workflow':
        return 'the workflow response';
    case 'screen_text_fallback':
        return 'the prepared screen response';
    default:
        return formatThinkingActivityFallbackLabel(cleanSourcePath).toLowerCase();
    }
}

function buildThinkingPreDispatchStepLines(preDispatch) {
    const steps = Array.isArray(preDispatch?.steps)
        ? preDispatch.steps.filter((entry) => entry && typeof entry === 'object')
        : [];
    return steps.map((step) => {
        const bits = [
            normaliseThinkingActivityString(step.step_label)
                || formatThinkingActivityFallbackLabel(step.step_id)
                || 'Unnamed step'
        ];
        const resultSummary = normaliseThinkingActivityString(step.result_summary);
        if (resultSummary && resultSummary !== bits[0]) {
            bits.push(resultSummary);
        }
        const status = normaliseThinkingActivityString(step.status);
        if (status) {
            bits.push(formatThinkingActivityFallbackLabel(status));
        }
        if (Number.isFinite(step.duration_ms)) {
            bits.push(formatThinkingDiagnosticDuration(step.duration_ms));
        }
        const errorClass = normaliseThinkingActivityString(step.error_class);
        const errorText = normaliseThinkingActivityString(step.error);
        if (errorClass) {
            bits.push(errorClass);
        } else if (errorText) {
            bits.push(errorText);
        }
        return bits.join(' · ');
    }).filter(Boolean);
}

function buildThinkingCriticSummarySnapshot(criticVerdict) {
    const summary = (criticVerdict?.summary && typeof criticVerdict.summary === 'object')
        ? criticVerdict.summary
        : {};
    const verifiedCount = Number.isFinite(summary.verified_count)
        ? Number(summary.verified_count)
        : null;
    const notVerifiedCount = Number.isFinite(summary.not_verified_count)
        ? Number(summary.not_verified_count)
        : null;
    const inconclusiveCount = Number.isFinite(summary.inconclusive_count)
        ? Number(summary.inconclusive_count)
        : null;
    const errorCount = Number.isFinite(summary.error_count)
        ? Number(summary.error_count)
        : null;
    const unresolvedCheckCount = Number.isFinite(criticVerdict?.unresolved_check_count)
        ? Number(criticVerdict.unresolved_check_count)
        : [notVerifiedCount, inconclusiveCount, errorCount]
            .filter((value) => Number.isFinite(value))
            .reduce((total, value) => total + Number(value), 0);

    return {
        summary,
        verifiedCount,
        notVerifiedCount,
        inconclusiveCount,
        errorCount,
        unresolvedCheckCount
    };
}

function buildThinkingTransformationSummaryText(stageId, transformation) {
    if (!transformation || typeof transformation !== 'object') {
        return '';
    }

    const stageLabel = stageId === 'narration'
        ? 'spoken narration'
        : 'on-screen response';
    const status = normaliseThinkingActivityString(transformation.status).toLowerCase();
    const sourceLabel = describeThinkingTransformationSource(transformation.source_path, stageId);
    const suppressionReason = normaliseThinkingActivityString(
        transformation.suppression_reason || transformation.output_summary?.reason
    );
    const errorClass = normaliseThinkingActivityString(transformation.error_class);

    if (status === 'failure') {
        return errorClass
            ? `${formatThinkingActivityFallbackLabel(stageLabel)} backfill failed · ${errorClass}`
            : `${formatThinkingActivityFallbackLabel(stageLabel)} backfill failed`;
    }
    if (status === 'skipped' || status === 'no_op') {
        return suppressionReason
            ? `${formatThinkingActivityFallbackLabel(stageLabel)} backfill skipped · ${formatThinkingActivityFallbackLabel(suppressionReason)}`
            : `${formatThinkingActivityFallbackLabel(stageLabel)} backfill skipped`;
    }
    if (status === 'success' || status === 'fallback_success') {
        return stageId === 'narration'
            ? `Preparing spoken narration from ${sourceLabel}`
            : `Preparing the on-screen response from ${sourceLabel}`;
    }
    return stageId === 'narration'
        ? 'Preparing spoken narration'
        : 'Preparing the on-screen response';
}

function buildThinkingCompletionGateSummaryText(completionGate) {
    if (!completionGate || typeof completionGate !== 'object') {
        return 'Verifying that the turn is safe to mark complete';
    }

    const decision = normaliseThinkingActivityString(completionGate.decision).toLowerCase();
    const decisionReason = normaliseThinkingActivityString(completionGate.decision_reason);
    const blockingEffectIds = Array.isArray(completionGate.blocking_effect_ids)
        ? completionGate.blocking_effect_ids
            .map((value) => normaliseThinkingActivityString(value))
            .filter(Boolean)
        : [];

    if (
        decision === 'follow_up_required'
        || decision === 'escalation_required'
    ) {
        const summaryBits = ['Follow-up is still required'];
        if (blockingEffectIds.length > 0) {
            summaryBits.push(formatThinkingCountLabel(blockingEffectIds.length, 'blocking effect'));
        } else if (decisionReason) {
            summaryBits.push(formatThinkingActivityFallbackLabel(decisionReason));
        }
        return summaryBits.join(' · ');
    }
    if (decision === 'completed' || decision === 'complete') {
        return completionGate.safe_to_claim_completion === false
            ? 'Completion checks are still being resolved'
            : 'Ready to mark the turn complete';
    }
    if (decision === 'failed' || decision === 'error') {
        return decisionReason
            ? `Turn cannot be marked complete · ${formatThinkingActivityFallbackLabel(decisionReason)}`
            : 'Turn cannot be marked complete';
    }

    return decisionReason
        ? `Verifying completion safety · ${formatThinkingActivityFallbackLabel(decisionReason)}`
        : 'Verifying that the turn is safe to mark complete';
}

function renderThinkingWorkflowStageDiagnosticDataHTML(data, workflowDiscovery = null) {
    if (!data || typeof data !== 'object') {
        return '';
    }

    const facts = [
        { label: 'Stage id', value: data.stage_id },
        { label: 'Observed updates', value: data.stage_event_count },
        { label: 'Latest status', value: data.latest_status ? formatThinkingActivityFallbackLabel(data.latest_status) : '' },
        { label: 'Latest update', value: data.latest_at_utc },
        { label: 'Latest result', value: data.latest_result_summary },
        { label: 'Recorded LLM input', value: data.llm_input_recorded ? 'Yes' : 'No' },
        { label: 'Recorded LLM output', value: data.llm_output_recorded ? 'Yes' : 'No' },
        {
            label: 'LLM request state',
            value: data.llm_request_state
                ? formatThinkingLlmRequestState(data.llm_request_state)
                : ''
        },
        { label: 'LLM model', value: data.llm_selected_model },
        { label: 'LLM provider', value: data.llm_selected_provider },
        { label: 'Request prepared', value: data.llm_request_prepared_at_utc },
        { label: 'Request sent', value: data.llm_request_sent_at_utc },
        { label: 'First output', value: data.llm_first_output_at_utc },
        {
            label: 'Fallback attempt',
            value: (
                Number.isFinite(data.llm_fallback_attempt_no)
                && Number.isFinite(data.llm_fallback_candidate_count)
            )
                ? `${Number(data.llm_fallback_attempt_no)} of ${Number(data.llm_fallback_candidate_count)}`
                : ''
        },
        { label: 'Latest subtask', value: data.latest_subtask },
        { label: 'Latest workflow task', value: data.latest_workflow_task },
        { label: 'Latest tool', value: data.latest_tool },
        { label: 'Python decisions', value: data.python_decision_count },
        { label: 'Possibly inappropriate Python decisions', value: data.possibly_inappropriate_python_code_use_count }
    ];
    const sections = [];

    if (data.stage_id === 'selected_workflow_execution') {
        const selectedWorkflowHtml = renderWorkflowDisplayHtml(
            data.selected_workflow_id,
            data.selected_workflow_name,
            workflowDiscovery
        );
        facts.push(
            {
                label: 'Selected workflow',
                value: formatWorkflowDisplayText(
                    data.selected_workflow_id,
                    data.selected_workflow_name,
                    workflowDiscovery
                ),
                html: selectedWorkflowHtml
            },
            { label: 'Workflow execution updates', value: data.selected_workflow_event_count },
            {
                label: 'Latest workflow event',
                value: formatThinkingSelectedWorkflowExecutionEvent(
                    data.latest_selected_workflow_event,
                    workflowDiscovery
                )
            },
            { label: 'Latest state id', value: data.latest_selected_workflow_event?.state_id },
            { label: 'Latest action id', value: data.latest_selected_workflow_event?.action_id },
            { label: 'Action status', value: data.latest_selected_workflow_event?.action_status },
            { label: 'Action outcome', value: data.latest_selected_workflow_event?.action_outcome },
            { label: 'Effect status', value: data.latest_selected_workflow_event?.effect_status },
            { label: 'Mutation outcome', value: data.latest_selected_workflow_event?.mutation_outcome },
            { label: 'Outcome finality', value: data.latest_selected_workflow_event?.outcome_finality },
            { label: 'Next action', value: data.latest_selected_workflow_event?.next_action }
        );
        sections.push(buildThinkingDiagnosticListHTML(
            'Workflow execution events',
            buildThinkingSelectedWorkflowExecutionEventLines(
                data.selected_workflow_execution,
                workflowDiscovery
            )
        ));
        sections.push(buildThinkingProgressFactsSectionHTML(
            data.progress_facts,
            THINKING_CARD_MODE_DEBUG
        ));
    } else if (data.stage_id === 'workflow_discovery') {
        facts.push(
            {
                label: 'Requested search',
                value: data.requested_query,
                html: data.requested_query
                    ? `<code class="thinking-card-diagnostic-inline-code">${escapeHtml(data.requested_query)}</code>`
                    : ''
            },
            {
                label: 'Executed search',
                value: data.query,
                html: data.query
                    ? `<code class="thinking-card-diagnostic-inline-code">${escapeHtml(data.query)}</code>`
                    : ''
            },
            { label: 'Search sources', value: data.search_sources },
            { label: 'Namespace', value: data.namespace },
            { label: 'Threshold', value: data.threshold },
            { label: 'Search time', value: Number.isFinite(data.search_time_ms) ? `${data.search_time_ms} ms` : '' },
            {
                label: 'Budget',
                value: Number.isFinite(data.timeout_budget_seconds)
                    ? `${data.timeout_budget_seconds.toFixed(3)} s`
                    : ''
            },
            {
                label: 'Budget exhausted',
                value: data.budget_exhausted ? 'Yes' : 'No'
            },
            { label: 'Budget exhaustion stage', value: data.budget_exhaustion_stage },
            { label: 'Routing matches', value: data.match_count },
            { label: 'Candidates considered', value: data.candidate_count },
            { label: 'Allow non-executable', value: data.allow_non_executable },
            {
                label: 'Dispatch outcome',
                value: data.workflow_selection_narrative,
                html: data.workflow_selection_narrative_html
            }
        );
        sections.push(buildThinkingDiagnosticListHTML('Errors', data.errors));
        if (data.budget_exhaustion_detail) {
            sections.push(buildThinkingDiagnosticTextSectionHTML(
                'Budget exhaustion detail',
                data.budget_exhaustion_detail,
                { preserveWhitespace: false }
            ));
        }
        sections.push(renderThinkingDiagnosticWorkflowCandidatesHTML(data.candidates, workflowDiscovery));
    } else if (data.stage_id === 'expected_outcome_inference') {
        const inferredContractSummary = buildThinkingCaptureSummaryText(
            data.llm_response_preview,
            data.latest_result_summary || ''
        );
        facts.push(
            { label: 'Inference target', value: 'What would count as a grounded successful answer for this turn' },
            {
                label: 'Inferred contract summary',
                value: inferredContractSummary
            }
        );
    } else if (data.stage_id === 'selector_preparation') {
        facts.push(
            { label: 'Selector prompt id', value: data.selector_prompt_id },
            {
                label: 'Requested selector prompt ids',
                value: Array.isArray(data.selector_requested_prompt_ids)
                    ? data.selector_requested_prompt_ids.length
                    : ''
            },
            {
                label: 'Selector prompt readiness',
                value: data.selector_prompt?.text || data.selector_prompt?.preview
                    ? 'Prepared'
                    : 'Unavailable'
            }
        );
        sections.push(buildThinkingDiagnosticListHTML(
            'Requested selector prompt ids',
            data.selector_requested_prompt_ids,
            { code: true }
        ));
        sections.push(buildThinkingDiagnosticTextSectionHTML(
            'Selector prompt',
            data.selector_prompt?.text || data.selector_prompt?.preview,
            { codeBlock: true }
        ));
        sections.push(buildThinkingDiagnosticTextSectionHTML(
            'Selector candidate list',
            data.selector_candidate_list?.text || data.selector_candidate_list?.preview,
            { codeBlock: true }
        ));
    } else if (data.stage_id === 'selector_decision' || data.stage_id === 'workflow_dispatch' || data.stage_id === 'plain_response') {
        const selectedWorkflowHtml = renderWorkflowDisplayHtml(
            data.selected_workflow_id,
            data.selected_workflow_name,
            workflowDiscovery
        );
        facts.push(
            {
                label: 'Selected workflow',
                value: formatWorkflowDisplayText(
                    data.selected_workflow_id,
                    data.selected_workflow_name,
                    workflowDiscovery
                ),
                html: selectedWorkflowHtml
            },
            {
                label: 'Selector verdict',
                value: data.workflow_selector_verdict
                    ? formatThinkingActivityFallbackLabel(data.workflow_selector_verdict)
                    : ''
            },
            {
                label: 'Selector source',
                value: data.workflow_selector_source
                    ? formatThinkingActivityFallbackLabel(data.workflow_selector_source)
                    : ''
            },
            {
                label: 'Routing rationale',
                value: data.workflow_selection_narrative,
                html: data.workflow_selection_narrative_html
            },
            {
                label: 'Dispatch terminal status',
                value: data.dispatch_terminal_status
                    ? formatThinkingActivityFallbackLabel(data.dispatch_terminal_status)
                    : ''
            },
            {
                label: 'Dispatch failure reason',
                value: data.dispatch_terminal_failure_reason
                    ? formatThinkingActivityFallbackLabel(data.dispatch_terminal_failure_reason)
                    : ''
            },
            { label: 'Routing matches', value: data.workflow_match_count },
            { label: 'Candidates considered', value: data.workflow_candidate_count }
        );
        sections.push(buildThinkingDiagnosticListHTML(
            'Dispatch failure detail',
            data.dispatch_terminal_failure_detail ? [data.dispatch_terminal_failure_detail] : []
        ));
        sections.push(buildThinkingDiagnosticListHTML(
            'Unresolved required inputs',
            data.dispatch_terminal_unresolved_required_inputs
        ));
        sections.push(buildThinkingDiagnosticListHTML(
            'Requested selector prompt ids',
            data.selector_requested_prompt_ids,
            { code: true }
        ));
        sections.push(buildThinkingDiagnosticTextSectionHTML(
            'Selector prompt',
            data.selector_prompt?.text || data.selector_prompt?.preview,
            { codeBlock: true }
        ));
        sections.push(buildThinkingDiagnosticTextSectionHTML(
            'Selector candidate list',
            data.selector_candidate_list?.text || data.selector_candidate_list?.preview,
            { codeBlock: true }
        ));
        sections.push(buildThinkingDiagnosticTextSectionHTML(
            'Selector response',
            data.selector_response?.text || data.selector_response?.preview,
            { codeBlock: true }
        ));
    } else if (data.stage_id === 'workflow_dispatch_prepare') {
        const selectedWorkflowHtml = renderWorkflowDisplayHtml(
            data.selected_workflow_id,
            data.selected_workflow_name,
            workflowDiscovery
        );
        facts.push(
            {
                label: 'Selected workflow',
                value: formatWorkflowDisplayText(
                    data.selected_workflow_id,
                    data.selected_workflow_name,
                    workflowDiscovery
                ),
                html: selectedWorkflowHtml
            },
            {
                label: 'Routing rationale',
                value: data.workflow_selection_narrative,
                html: data.workflow_selection_narrative_html
            },
            { label: 'Pre-dispatch steps', value: data.pre_dispatch?.step_count },
            { label: 'Completed checks', value: data.pre_dispatch?.completed_step_count },
            { label: 'Failed checks', value: data.pre_dispatch?.failed_step_count },
            {
                label: 'Total pre-dispatch time',
                value: formatThinkingDiagnosticDuration(data.pre_dispatch?.total_duration_ms)
            },
            {
                label: 'Slowest step',
                value: normaliseThinkingActivityString(data.pre_dispatch?.slowest_step_label)
                    || formatThinkingActivityFallbackLabel(data.pre_dispatch?.slowest_step_id)
            },
            {
                label: 'Slowest step time',
                value: formatThinkingDiagnosticDuration(data.pre_dispatch?.slowest_step_duration_ms)
            }
        );
        sections.push(buildThinkingDiagnosticListHTML(
            'Pre-dispatch checks',
            buildThinkingPreDispatchStepLines(data.pre_dispatch)
        ));
        sections.push(buildThinkingDiagnosticListHTML(
            'Requested selector prompt ids',
            data.selector_requested_prompt_ids,
            { code: true }
        ));
        sections.push(buildThinkingDiagnosticTextSectionHTML(
            'Selector prompt',
            data.selector_prompt?.text || data.selector_prompt?.preview,
            { codeBlock: true }
        ));
        sections.push(buildThinkingDiagnosticTextSectionHTML(
            'Selector candidate list',
            data.selector_candidate_list?.text || data.selector_candidate_list?.preview,
            { codeBlock: true }
        ));
    } else if (data.stage_id === 'tool_plan') {
        const selectedWorkflowHtml = renderWorkflowDisplayHtml(
            data.selected_workflow_id,
            data.selected_workflow_name,
            workflowDiscovery
        );
        facts.push(
            {
                label: 'Selected workflow',
                value: formatWorkflowDisplayText(
                    data.selected_workflow_id,
                    data.selected_workflow_name,
                    workflowDiscovery
                ),
                html: selectedWorkflowHtml
            },
            { label: 'Planned tool calls', value: data.tool_execution?.planned_count },
            { label: 'Started tool calls', value: data.tool_execution?.started_count },
            { label: 'Executed tool calls', value: data.tool_execution?.executed_count },
            { label: 'Tool invocations', value: data.tool_execution?.invocation_count },
            { label: 'Successful invocations', value: data.tool_execution?.successful_invocation_count },
            { label: 'Failed invocations', value: data.tool_execution?.failed_invocation_count },
            { label: 'Blocked invocations', value: data.tool_execution?.blocked_invocation_count },
            { label: 'Zero tools executed', value: data.tool_execution?.zero_tools_executed }
        );
        sections.push(buildThinkingDiagnosticListHTML(
            'Tool planning failure codes',
            data.tool_execution?.failure_codes
        ));
        sections.push(buildThinkingDiagnosticListHTML(
            'Requested selector prompt ids',
            data.selector_requested_prompt_ids,
            { code: true }
        ));
        sections.push(buildThinkingDiagnosticTextSectionHTML(
            'Selector prompt',
            data.selector_prompt?.text || data.selector_prompt?.preview,
            { codeBlock: true }
        ));
        sections.push(buildThinkingDiagnosticTextSectionHTML(
            'Selector candidate list',
            data.selector_candidate_list?.text || data.selector_candidate_list?.preview,
            { codeBlock: true }
        ));
    } else if (data.stage_id === 'tool_execute') {
        facts.push(
            { label: 'Tool calls observed', value: data.tool_call_count },
            { label: 'Successful', value: data.tool_success_count },
            { label: 'Failed', value: data.tool_failure_count },
            { label: 'Pending', value: data.tool_pending_count }
        );
        const toolLines = Array.isArray(data.tool_history)
            ? data.tool_history.map((entry) => {
                const target = normaliseThinkingActivityString(entry.tool || entry.workflowTask);
                if (!target) {
                    return '';
                }
                const bits = [target];
                if (Number.isFinite(entry.batchSize)) {
                    bits.push(`batch ${Number(entry.batchSize)}`);
                }
                if (typeof entry.success === 'boolean') {
                    bits.push(entry.success ? 'success' : 'failed');
                }
                const resultSummary = normaliseThinkingActivityString(entry.resultSummary);
                if (resultSummary) {
                    bits.push(resultSummary);
                }
                return bits.join(' · ');
            }).filter(Boolean)
            : [];
        sections.push(buildThinkingDiagnosticListHTML('Observed tool calls', toolLines));
    } else if (data.stage_id === 'screen_backfill' || data.stage_id === 'narration') {
        const transformation = data.response_transformation;
        const selectedWorkflowHtml = renderWorkflowDisplayHtml(
            data.selected_workflow_id,
            data.selected_workflow_name,
            workflowDiscovery
        );
        facts.push(
            {
                label: 'Selected workflow',
                value: formatWorkflowDisplayText(
                    data.selected_workflow_id,
                    data.selected_workflow_name,
                    workflowDiscovery
                ),
                html: selectedWorkflowHtml
            },
            {
                label: 'Routing rationale',
                value: data.workflow_selection_narrative,
                html: data.workflow_selection_narrative_html
            },
            {
                label: 'Transformation status',
                value: transformation?.status
                    ? formatThinkingActivityFallbackLabel(transformation.status)
                    : ''
            },
            {
                label: 'Source material',
                value: describeThinkingTransformationSource(transformation?.source_path, data.stage_id)
            },
            {
                label: 'Presenter format',
                value: normaliseThinkingActivityString(transformation?.output_summary?.presenter_format)
            },
            { label: 'Backfill applied', value: transformation?.output_summary?.applied },
            { label: 'Needs backfill', value: transformation?.input_summary?.needs_backfill },
            { label: 'Tool messages available', value: transformation?.input_summary?.tool_message_count },
            {
                label: 'Latency',
                value: formatThinkingDiagnosticDuration(transformation?.latency_ms)
            },
            { label: 'Model', value: transformation?.model_id },
            {
                label: 'Suppression reason',
                value: transformation?.suppression_reason
                    ? formatThinkingActivityFallbackLabel(transformation.suppression_reason)
                    : ''
            },
            { label: 'Error class', value: transformation?.error_class }
        );
    } else if (data.stage_id === 'postcondition_critic') {
        const criticSnapshot = buildThinkingCriticSummarySnapshot(data.critic_verdict);
        facts.push(
            { label: 'Critic workflow', value: data.critic_verdict?.workflow_id },
            { label: 'Verified checks', value: criticSnapshot.verifiedCount },
            { label: 'Not verified', value: criticSnapshot.notVerifiedCount },
            { label: 'Inconclusive', value: criticSnapshot.inconclusiveCount },
            { label: 'Errors', value: criticSnapshot.errorCount },
            { label: 'Unresolved checks', value: criticSnapshot.unresolvedCheckCount },
            { label: 'Has unresolved checks', value: data.critic_verdict?.has_unresolved_checks }
        );
    } else if (data.stage_id === 'completion_gate') {
        facts.push(
            {
                label: 'Decision',
                value: data.completion_gate?.decision
                    ? formatThinkingActivityFallbackLabel(data.completion_gate.decision)
                    : ''
            },
            { label: 'Decision reason', value: data.completion_gate?.decision_reason },
            { label: 'Requires follow-up', value: data.completion_gate?.requires_follow_up },
            { label: 'Safe to claim completion', value: data.completion_gate?.safe_to_claim_completion }
        );
        sections.push(buildThinkingDiagnosticListHTML(
            'Blocking effects',
            data.completion_gate?.blocking_effect_ids
        ));
        sections.push(buildThinkingDiagnosticListHTML(
            'Blocking failure codes',
            data.completion_gate?.blocking_failure_codes
        ));
    }

    if (data.latest_error) {
        sections.push(buildThinkingDiagnosticListHTML('Latest error', [data.latest_error]));
    }
    sections.push(buildThinkingDiagnosticTextSectionHTML(
        'Prepared prompt preview',
        data.llm_prompt_preview?.text || data.llm_prompt_preview?.preview,
        { codeBlock: true }
    ));
    sections.push(buildThinkingDiagnosticListHTML(
        'Context summary',
        buildThinkingLlmContextSummaryLines(data.llm_context_summary)
    ));
    sections.push(buildThinkingDiagnosticListHTML(
        'Context lineage',
        buildThinkingLlmContextLineageLines(data.llm_context_lineage)
    ));
    sections.push(buildThinkingDiagnosticTextSectionHTML(
        'Latest output preview',
        data.llm_response_preview?.preview || data.llm_response_preview?.text
    ));

    if (Array.isArray(data.python_decision_classes) && data.python_decision_classes.length > 0) {
        sections.push(buildThinkingDiagnosticListHTML('Python decision classes', data.python_decision_classes));
    }
    if (Array.isArray(data.python_decision_sources) && data.python_decision_sources.length > 0) {
        sections.push(buildThinkingDiagnosticListHTML('Python decision sources', data.python_decision_sources));
    }

    return renderThinkingDiagnosticPanelHTML({ facts, sections });
}

function renderThinkingWorkflowStageExpertDataHTML(data, workflowDiscovery = null) {
    if (!data || typeof data !== 'object') {
        return '';
    }

    const facts = [];
    const sections = [];
    const addSelectedWorkflowFact = () => {
        const selectedWorkflowText = formatWorkflowDisplayText(
            data.selected_workflow_id,
            data.selected_workflow_name,
            workflowDiscovery
        );
        if (!selectedWorkflowText) {
            return;
        }
        facts.push({
            label: 'Selected workflow',
            value: selectedWorkflowText,
            html: renderWorkflowDisplayHtml(
                data.selected_workflow_id,
                data.selected_workflow_name,
                workflowDiscovery
            )
        });
    };
    const addRoutingFacts = () => {
        if (data.workflow_selector_verdict) {
            facts.push({
                label: 'Selector verdict',
                value: formatThinkingActivityFallbackLabel(data.workflow_selector_verdict)
            });
        }
        if (data.workflow_selector_source) {
            facts.push({
                label: 'Selector source',
                value: formatThinkingActivityFallbackLabel(data.workflow_selector_source)
            });
        }
        if (data.workflow_selection_narrative) {
            facts.push({
                label: 'Routing rationale',
                value: data.workflow_selection_narrative,
                html: data.workflow_selection_narrative_html
            });
        }
    };
    const addModelFacts = () => {
        if (data.llm_selected_model) {
            facts.push({ label: 'LLM model', value: data.llm_selected_model });
        }
        if (
            Number.isFinite(data.llm_fallback_attempt_no)
            && Number.isFinite(data.llm_fallback_candidate_count)
        ) {
            facts.push({
                label: 'Fallback attempt',
                value: `${Number(data.llm_fallback_attempt_no)} of ${Number(data.llm_fallback_candidate_count)}`
            });
        }
    };
    const addLatestResultFact = () => {
        if (data.latest_result_summary) {
            facts.push({ label: 'Latest result', value: data.latest_result_summary });
        }
    };

    if (data.stage_id === 'selected_workflow_execution') {
        addSelectedWorkflowFact();
        facts.push(
            { label: 'Workflow execution updates', value: data.selected_workflow_event_count },
            {
                label: 'Latest workflow event',
                value: formatThinkingSelectedWorkflowExecutionEvent(
                    data.latest_selected_workflow_event,
                    workflowDiscovery
                )
            },
            { label: 'Latest state id', value: data.latest_selected_workflow_event?.state_id },
            { label: 'Latest action id', value: data.latest_selected_workflow_event?.action_id },
            { label: 'Action outcome', value: data.latest_selected_workflow_event?.action_outcome },
            { label: 'Effect status', value: data.latest_selected_workflow_event?.effect_status },
            { label: 'Next action', value: data.latest_selected_workflow_event?.next_action }
        );
        sections.push(buildThinkingDiagnosticListHTML(
            'Workflow execution events',
            buildThinkingSelectedWorkflowExecutionEventLines(
                data.selected_workflow_execution,
                workflowDiscovery
            )
        ));
        sections.push(buildThinkingProgressFactsSectionHTML(
            data.progress_facts,
            THINKING_CARD_MODE_EXPERT
        ));
    } else if (data.stage_id === 'workflow_discovery') {
        facts.push(
            { label: 'Search sources', value: data.search_sources },
            { label: 'Routing matches', value: data.match_count },
            { label: 'Candidates considered', value: data.candidate_count },
            { label: 'Budget exhausted', value: data.budget_exhausted }
        );
        addRoutingFacts();
        sections.push(renderThinkingDiagnosticWorkflowCandidatesHTML(data.candidates, workflowDiscovery));
        sections.push(buildThinkingDiagnosticListHTML('Discovery errors', data.errors));
    } else if (data.stage_id === 'expected_outcome_inference') {
        const inferredContractSummary = buildThinkingCaptureSummaryText(
            data.llm_response_preview,
            data.latest_result_summary || ''
        );
        facts.push({
            label: 'Inferred contract summary',
            value: inferredContractSummary
        });
        addLatestResultFact();
    } else if (data.stage_id === 'selector_preparation') {
        facts.push({
            label: 'Selector prompt readiness',
            value: data.selector_prompt?.text || data.selector_prompt?.preview
                ? 'Prepared'
                : 'Unavailable'
        });
        addModelFacts();
    } else if (data.stage_id === 'selector_decision' || data.stage_id === 'workflow_dispatch' || data.stage_id === 'plain_response') {
        addSelectedWorkflowFact();
        addRoutingFacts();
        facts.push(
            { label: 'Routing matches', value: data.workflow_match_count },
            { label: 'Candidates considered', value: data.workflow_candidate_count }
        );
        addModelFacts();
        sections.push(buildThinkingDiagnosticListHTML(
            'Unresolved required inputs',
            data.dispatch_terminal_unresolved_required_inputs
        ));
    } else if (data.stage_id === 'workflow_dispatch_prepare') {
        addSelectedWorkflowFact();
        addRoutingFacts();
        facts.push(
            { label: 'Pre-dispatch steps', value: data.pre_dispatch?.step_count },
            { label: 'Completed checks', value: data.pre_dispatch?.completed_step_count },
            { label: 'Failed checks', value: data.pre_dispatch?.failed_step_count },
            {
                label: 'Total pre-dispatch time',
                value: formatThinkingDiagnosticDuration(data.pre_dispatch?.total_duration_ms)
            }
        );
        sections.push(buildThinkingDiagnosticListHTML(
            'Pre-dispatch checks',
            buildThinkingPreDispatchStepLines(data.pre_dispatch)
        ));
    } else if (data.stage_id === 'tool_plan') {
        addSelectedWorkflowFact();
        facts.push(
            { label: 'Planned tool calls', value: data.tool_execution?.planned_count },
            { label: 'Started tool calls', value: data.tool_execution?.started_count },
            { label: 'Executed tool calls', value: data.tool_execution?.executed_count },
            { label: 'Successful invocations', value: data.tool_execution?.successful_invocation_count },
            { label: 'Failed invocations', value: data.tool_execution?.failed_invocation_count },
            { label: 'Blocked invocations', value: data.tool_execution?.blocked_invocation_count }
        );
        sections.push(buildThinkingDiagnosticListHTML(
            'Tool planning failure codes',
            data.tool_execution?.failure_codes
        ));
    } else if (data.stage_id === 'tool_execute') {
        facts.push(
            { label: 'Tool calls observed', value: data.tool_call_count },
            { label: 'Successful', value: data.tool_success_count },
            { label: 'Failed', value: data.tool_failure_count },
            { label: 'Pending', value: data.tool_pending_count }
        );
        const toolLines = Array.isArray(data.tool_history)
            ? data.tool_history.map((entry) => {
                const target = normaliseThinkingActivityString(entry.tool || entry.workflowTask);
                if (!target) {
                    return '';
                }
                const bits = [target];
                if (Number.isFinite(entry.batchSize)) {
                    bits.push(`batch ${Number(entry.batchSize)}`);
                }
                if (typeof entry.success === 'boolean') {
                    bits.push(entry.success ? 'success' : 'failed');
                }
                const resultSummary = normaliseThinkingActivityString(entry.resultSummary);
                if (resultSummary) {
                    bits.push(resultSummary);
                }
                return bits.join(' · ');
            }).filter(Boolean)
            : [];
        sections.push(buildThinkingDiagnosticListHTML('Observed tool calls', toolLines));
    } else if (data.stage_id === 'screen_backfill' || data.stage_id === 'narration') {
        const transformation = data.response_transformation;
        addSelectedWorkflowFact();
        addRoutingFacts();
        facts.push(
            {
                label: 'Transformation status',
                value: transformation?.status
                    ? formatThinkingActivityFallbackLabel(transformation.status)
                    : ''
            },
            {
                label: 'Source material',
                value: describeThinkingTransformationSource(transformation?.source_path, data.stage_id)
            },
            { label: 'Backfill applied', value: transformation?.output_summary?.applied },
            { label: 'Needs backfill', value: transformation?.input_summary?.needs_backfill },
            {
                label: 'Latency',
                value: formatThinkingDiagnosticDuration(transformation?.latency_ms)
            },
            { label: 'Model', value: transformation?.model_id }
        );
    } else if (data.stage_id === 'postcondition_critic') {
        const criticSnapshot = buildThinkingCriticSummarySnapshot(data.critic_verdict);
        facts.push(
            { label: 'Critic workflow', value: data.critic_verdict?.workflow_id },
            { label: 'Verified checks', value: criticSnapshot.verifiedCount },
            { label: 'Not verified', value: criticSnapshot.notVerifiedCount },
            { label: 'Inconclusive', value: criticSnapshot.inconclusiveCount },
            { label: 'Errors', value: criticSnapshot.errorCount },
            { label: 'Unresolved checks', value: criticSnapshot.unresolvedCheckCount }
        );
    } else if (data.stage_id === 'completion_gate') {
        facts.push(
            {
                label: 'Decision',
                value: data.completion_gate?.decision
                    ? formatThinkingActivityFallbackLabel(data.completion_gate.decision)
                    : ''
            },
            { label: 'Decision reason', value: data.completion_gate?.decision_reason },
            { label: 'Requires follow-up', value: data.completion_gate?.requires_follow_up },
            { label: 'Safe to claim completion', value: data.completion_gate?.safe_to_claim_completion }
        );
        sections.push(buildThinkingDiagnosticListHTML(
            'Blocking effects',
            data.completion_gate?.blocking_effect_ids
        ));
    } else {
        addLatestResultFact();
        addSelectedWorkflowFact();
        addRoutingFacts();
        addModelFacts();
    }

    if (data.latest_error) {
        sections.push(buildThinkingDiagnosticListHTML('Latest error', [data.latest_error]));
    }

    return renderThinkingDiagnosticPanelHTML({ facts, sections });
}

function buildThinkingStageAuthoritySummaryText(stageDiagnostic) {
    if (!stageDiagnostic || typeof stageDiagnostic !== 'object') {
        return '';
    }

    const parts = [];
    if (Number.isFinite(stageDiagnostic.python_decision_count) && Number(stageDiagnostic.python_decision_count) > 0) {
        const count = Number(stageDiagnostic.python_decision_count);
        parts.push(count === 1 ? '1 Python decision' : `${count} Python decisions`);
    }
    if (
        Number.isFinite(stageDiagnostic.possibly_inappropriate_python_code_use_count)
        && Number(stageDiagnostic.possibly_inappropriate_python_code_use_count) > 0
    ) {
        const count = Number(stageDiagnostic.possibly_inappropriate_python_code_use_count);
        parts.push(
            count === 1
                ? '1 possibly inappropriate Python decision'
                : `${count} possibly inappropriate Python decisions`
        );
    }
    return parts.join(' · ');
}

function buildThinkingActivityDiagnosticsHTML(entry) {
    if (!entry || typeof entry !== 'object') {
        return '';
    }

    const facts = [
        { label: 'Sequence', value: entry.sequenceNo },
        { label: 'Stage', value: entry.stage ? formatThinkingActivityFallbackLabel(entry.stage) : '' },
        { label: 'Status', value: entry.status ? formatThinkingActivityFallbackLabel(entry.status) : '' },
        { label: 'Event kind', value: entry.eventKind ? formatThinkingActivityFallbackLabel(entry.eventKind) : '' },
        { label: 'Merged updates', value: entry.groupCount && Number(entry.groupCount) > 1 ? Number(entry.groupCount) : '' },
        { label: 'Model', value: entry.model },
        { label: 'Subtask', value: entry.subtask },
        { label: 'Timestamp', value: entry.atUtc },
        {
            label: 'Detail',
            value: entry.detail,
            html: normaliseThinkingActivityString(entry.detailHtml)
                ? entry.detailHtml
                : ''
        }
    ];

    return renderThinkingDiagnosticPanelHTML({ facts });
}

function buildToolHistoryDiagnosticsHTML(entry, mode = THINKING_CARD_MODE_EXPERT) {
    if (!entry || typeof entry !== 'object') {
        return '';
    }

    const renderMode = normaliseThinkingCardMode(mode);
    const tool = normaliseThinkingActivityString(entry.tool);
    const workflowTask = normaliseThinkingActivityString(entry.workflowTask);
    const capabilityDescriptor = getThinkingCapabilityDescriptor(entry);
    const semanticOperation = capabilityDescriptor?.semanticOperation || null;
    const isRepresentedWorkflow = (
        capabilityDescriptor?.capabilityKind === 'represented_workflow'
    );
    const capabilityLabel = normaliseThinkingActivityString(
        capabilityDescriptor?.label
    );
    const facts = [
        {
            label: isRepresentedWorkflow && renderMode !== THINKING_CARD_MODE_DEBUG
                ? 'Workflow capability'
                : 'Tool',
            value: isRepresentedWorkflow && renderMode !== THINKING_CARD_MODE_DEBUG
                ? capabilityLabel
                : tool
        },
        { label: 'Workflow task', value: workflowTask },
        { label: 'Phase', value: entry.phase ? formatThinkingActivityFallbackLabel(entry.phase) : '' },
        { label: 'Batch size', value: entry.batchSize },
        {
            label: 'Result',
            value: replaceOpaqueThinkingCapabilityLabel(
                semanticOperation?.summary || entry.resultSummary,
                capabilityDescriptor
            )
        },
        {
            label: 'Outcome',
            value: typeof entry.success === 'boolean'
                ? (entry.success ? 'Success' : 'Failed')
                : 'Pending'
        }
    ];
    const hasWorkflowArgument = semanticOperation?.arguments?.some(
        (argument) => argument?.role === 'workflow'
    );
    if (
        isRepresentedWorkflow
        && renderMode !== THINKING_CARD_MODE_DEFAULT
        && capabilityDescriptor?.workflowId
        && !hasWorkflowArgument
    ) {
        facts.push({ label: 'Workflow ID', value: capabilityDescriptor.workflowId });
    }

    if (semanticOperation) {
        const focusSourceArgument = normaliseThinkingActivityString(
            semanticOperation.focus?.sourceArgument
        );
        if (semanticOperation.focus) {
            const focusDisplay = normaliseThinkingActivityString(semanticOperation.focus.display)
                || formatThinkingDiagnosticFactValue(semanticOperation.focus.value);
            facts.push({ label: semanticOperation.focus.label, value: focusDisplay });
            const focusId = getThinkingSemanticArgumentCanonicalId(semanticOperation.focus);
            if (focusId) {
                facts.push({ label: `${semanticOperation.focus.label} ID`, value: focusId });
            }
            if (renderMode === THINKING_CARD_MODE_DEBUG && focusSourceArgument) {
                facts.push({
                    label: `${semanticOperation.focus.label} source argument`,
                    value: focusSourceArgument
                });
            }
        }
        for (const argument of semanticOperation.arguments) {
            if (
                focusSourceArgument
                && normaliseThinkingActivityString(argument.sourceArgument) === focusSourceArgument
            ) {
                continue;
            }
            const label = normaliseThinkingActivityString(argument.label);
            const display = normaliseThinkingActivityString(argument.display)
                || formatThinkingDiagnosticFactValue(argument.value);
            if (!label || !display) {
                continue;
            }
            facts.push({ label, value: display });
            const canonicalId = getThinkingSemanticArgumentCanonicalId(argument);
            if (canonicalId) {
                facts.push({ label: `${label} ID`, value: canonicalId });
            }
            if (renderMode === THINKING_CARD_MODE_DEBUG && argument.sourceArgument) {
                facts.push({ label: `${label} source argument`, value: argument.sourceArgument });
            }
        }
        if (semanticOperation.observation) {
            if (
                Number.isFinite(semanticOperation.observation.count)
                && semanticOperation.observation.countLabel
            ) {
                const qualifier = semanticOperation.observation.countIsLowerBound
                    ? 'At least '
                    : '';
                facts.push({
                    label: 'Returned count',
                    value: `${qualifier}${semanticOperation.observation.count} ${semanticOperation.observation.countLabel}`
                });
            }
            const returnedNames = semanticOperation.observation.items
                .map((item) => normaliseThinkingActivityString(item.name))
                .filter(Boolean);
            if (returnedNames.length > 0) {
                facts.push({ label: 'Returned items', value: returnedNames.join(', ') });
            }
            const returnedIds = semanticOperation.observation.items
                .map((item) => normaliseThinkingActivityString(item.identifier))
                .filter(Boolean);
            if (returnedIds.length > 0) {
                facts.push({ label: 'Returned IDs', value: returnedIds.join(', ') });
            }
            for (const detail of semanticOperation.observation.details || []) {
                const label = normaliseThinkingActivityString(detail.label);
                const value = normaliseThinkingActivityString(detail.value);
                if (label && value) {
                    facts.push({ label, value });
                }
            }
        }
        if (semanticOperation.observation) {
            facts.push({
                label: 'Observation source',
                value: 'Returned capability result'
            });
        } else {
            facts.push({
                label: 'Verification',
                value: describeThinkingSemanticVerification(semanticOperation)
            });
        }
        if (semanticOperation.outcome && typeof semanticOperation.outcome.changed === 'boolean') {
            facts.push({
                label: 'Reported change',
                value: semanticOperation.outcome.changed ? 'Yes' : 'No'
            });
        }
    }

    if (renderMode === THINKING_CARD_MODE_DEBUG) {
        const outcome = semanticOperation?.outcome || null;
        facts.push(
            { label: 'Tool call ID', value: entry.callId || entry.call_id },
            { label: 'Semantic operation ID', value: semanticOperation?.operationId },
            { label: 'Semantic schema', value: semanticOperation?.schemaVersion },
            { label: 'Lifecycle', value: semanticOperation?.lifecycleStatus },
            { label: 'Capability ID', value: semanticOperation?.capability?.id },
            { label: 'Capability kind', value: semanticOperation?.capability?.kind },
            { label: 'Execution method', value: semanticOperation?.capability?.executionMethod },
            { label: 'Effect status', value: outcome?.effectStatus },
            { label: 'Outcome finality', value: outcome?.outcomeFinality },
            {
                label: semanticOperation?.observation
                    ? 'Receipt source'
                    : 'Verification source',
                value: semanticOperation?.verification?.source
            },
            { label: 'Visibility', value: semanticOperation?.visibility }
        );
    }

    return renderThinkingDiagnosticPanelHTML({ facts });
}

function buildThinkingStageDiagnosticsSnapshot(request) {
    const workflowRows = buildThinkingWorkflowStageRows(request)
        .map((entry) => ({
            stage_id: entry.stageId || null,
            label: entry.label || null,
            detail: entry.detail || null,
            state: entry.state || null,
            diagnostics: entry.diagnosticData || null
        }))
        .filter((entry) => entry.stage_id || entry.label);

    const preservedEntries = Array.isArray(request?.stageDiagnostics)
        ? request.stageDiagnostics
            .map((entry) => normaliseThinkingStageDiagnosticSnapshotEntry(entry))
            .filter((entry) => entry && (entry.stage_id || entry.label))
        : [];

    if (workflowRows.length === 0) {
        return preservedEntries;
    }
    if (preservedEntries.length === 0) {
        return workflowRows;
    }

    const mergedRows = workflowRows.map((entry) => ({ ...entry }));
    const seenStageKeys = new Set(
        mergedRows
            .map((entry) => normaliseThinkingActivityString(entry.stage_id || entry.label))
            .filter(Boolean)
    );

    for (const entry of preservedEntries) {
        const stageKey = normaliseThinkingActivityString(entry.stage_id || entry.label);
        if (!stageKey || seenStageKeys.has(stageKey)) {
            continue;
        }
        mergedRows.push({ ...entry });
        seenStageKeys.add(stageKey);
    }

    return mergedRows;
}

function normaliseThinkingStageDiagnosticSnapshotEntry(entry) {
    if (!entry || typeof entry !== 'object') {
        return null;
    }

    const stageId = normaliseThinkingActivityString(entry.stage_id || entry.stageId);
    const label = normaliseThinkingActivityString(entry.label || entry.stage_label || entry.stageLabel)
        || formatThinkingActivityFallbackLabel(stageId)
        || null;
    const detail = normaliseThinkingActivityString(entry.detail) || null;
    const state = normaliseThinkingActivityString(entry.state) || null;
    const diagnostics = (entry.diagnostics && typeof entry.diagnostics === 'object')
        ? { ...entry.diagnostics }
        : null;

    if (!stageId && !label) {
        return null;
    }

    return {
        stage_id: stageId,
        label,
        detail,
        state,
        diagnostics
    };
}

function getThinkingSelectedWorkflowExecution(request) {
    const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const candidates = [
        request?.selectedWorkflowExecution,
        request?.selected_workflow_execution,
        latestProgress?.selected_workflow_execution,
        latestProgress?.progress_view_model?.selected_workflow_execution,
        latestProgress?.progress_view_model?.workflow_execution_summary,
    ];
    for (const candidate of candidates) {
        if (candidate && typeof candidate === 'object') {
            return normaliseThinkingSelectedWorkflowExecution(candidate, request?.workflowDiscovery || null);
        }
    }
    return null;
}

function normaliseThinkingSelectedWorkflowExecution(rawExecution, workflowDiscovery = null) {
    if (!rawExecution || typeof rawExecution !== 'object') {
        return null;
    }
    const rawEvents = Array.isArray(rawExecution.events)
        ? rawExecution.events
        : [];
    const events = rawEvents
        .filter((entry) => entry && typeof entry === 'object')
        .map((entry) => ({
            status: normaliseThinkingActivityString(entry.status) || null,
            event_kind: normaliseThinkingActivityString(entry.event_kind) || null,
            workflow_id: normaliseThinkingActivityString(entry.workflow_id) || null,
            selected_workflow_id: normaliseThinkingActivityString(entry.selected_workflow_id) || null,
            selected_workflow_name: normaliseThinkingActivityString(entry.selected_workflow_name) || null,
            selected_execution_mode: normaliseThinkingActivityString(entry.selected_execution_mode) || null,
            state_id: normaliseThinkingActivityString(entry.state_id) || null,
            action_id: normaliseThinkingActivityString(entry.action_id) || null,
            action_status: normaliseThinkingActivityString(entry.action_status) || null,
            action_outcome: normaliseThinkingActivityString(entry.action_outcome || entry.outcome) || null,
            final_state: normaliseThinkingActivityString(entry.final_state) || null,
            error: normaliseThinkingActivityString(entry.error) || null,
            execution_mode: normaliseThinkingActivityString(entry.execution_mode) || null,
            effect_status: normaliseThinkingActivityString(entry.effect_status) || null,
            mutation_outcome: normaliseThinkingActivityString(entry.mutation_outcome) || null,
            outcome_finality: normaliseThinkingActivityString(entry.outcome_finality) || null,
            failure_reason: normaliseThinkingActivityString(entry.failure_reason) || null,
            next_action: normaliseThinkingActivityString(entry.next_action) || null,
            changed: typeof entry.changed === 'boolean' ? entry.changed : null,
            semantic_effect: typeof entry.semantic_effect === 'boolean' ? entry.semantic_effect : null,
            duration_ms: Number.isFinite(entry.duration_ms) ? Number(entry.duration_ms) : null,
            sequence_no: Number.isFinite(entry.sequence_no) ? Number(entry.sequence_no) : null,
            at_utc: normaliseThinkingActivityString(entry.at_utc) || null,
            progress_facts: normaliseThinkingProgressFacts(entry.progress_facts),
        }));
    const normalisedExplicitLatestEvent = (
        rawExecution.latest_event && typeof rawExecution.latest_event === 'object'
            ? normaliseThinkingSelectedWorkflowExecution(
                { events: [rawExecution.latest_event] },
                workflowDiscovery
            )?.latest_event
            : null
    );
    const latestEvent = normalisedExplicitLatestEvent
        || (events.length > 0 ? events[events.length - 1] : null);
    const workflowId = normaliseThinkingActivityString(rawExecution.selected_workflow_id)
        || normaliseThinkingActivityString(rawExecution.workflow_id)
        || normaliseThinkingActivityString(latestEvent?.selected_workflow_id)
        || normaliseThinkingActivityString(latestEvent?.workflow_id)
        || null;
    if (!workflowId && events.length === 0) {
        return null;
    }
    const workflowName = normaliseThinkingActivityString(rawExecution.selected_workflow_name)
        || normaliseThinkingActivityString(latestEvent?.selected_workflow_name)
        || normaliseThinkingActivityString(
            resolveWorkflowDisplayDescriptor(workflowId, null, workflowDiscovery).workflowName
        )
        || null;
    return {
        schema_version: 'selected_workflow_execution.v1',
        workflow_id: workflowId,
        selected_workflow_id: workflowId,
        selected_workflow_name: workflowName,
        selected_execution_mode: normaliseThinkingActivityString(rawExecution.selected_execution_mode)
            || normaliseThinkingActivityString(latestEvent?.selected_execution_mode)
            || null,
        event_count: Number.isFinite(rawExecution.event_count)
            ? Number(rawExecution.event_count)
            : events.length,
        latest_event: latestEvent,
        events,
        progress_facts: normaliseThinkingProgressFacts(
            rawExecution.progress_facts || latestEvent?.progress_facts
        ),
        summary_text: normaliseThinkingActivityString(rawExecution.summary_text)
            || formatThinkingSelectedWorkflowExecutionEvent(latestEvent, workflowDiscovery)
            || null,
    };
}

function formatThinkingWorkflowStateLabel(stateId, workflowId = null) {
    const cleanStateId = normaliseThinkingActivityString(stateId);
    if (!cleanStateId) {
        return '';
    }

    const representedStepPrefix = '#V#workflow_step_';
    if (!cleanStateId.startsWith(representedStepPrefix)) {
        return formatThinkingActivityFallbackLabel(cleanStateId);
    }

    let stateSlug = cleanStateId.slice(representedStepPrefix.length);
    const workflowSlug = normaliseThinkingActivityString(workflowId)
        .replace(/^#V#/, '');
    if (workflowSlug && stateSlug.startsWith(`${workflowSlug}_`)) {
        stateSlug = stateSlug.slice(workflowSlug.length + 1);
    }
    return formatThinkingActivityFallbackLabel(stateSlug);
}

function formatThinkingSelectedWorkflowExecutionEvent(event, workflowDiscovery = null) {
    if (!event || typeof event !== 'object') {
        return '';
    }
    const workflowText = formatWorkflowDisplayText(
        event.selected_workflow_id || event.workflow_id,
        event.selected_workflow_name,
        workflowDiscovery
    );
    const stateText = formatThinkingWorkflowStateLabel(
        event.state_id,
        event.selected_workflow_id || event.workflow_id
    );
    const actionText = event.action_id ? formatThinkingActivityFallbackLabel(event.action_id) : '';
    const outcome = event.action_outcome || event.action_status || event.outcome || '';
    const outcomeText = outcome ? formatThinkingActivityFallbackLabel(outcome) : '';
    const durationText = formatThinkingDiagnosticDuration(event.duration_ms);
    const effectText = (() => {
        if (event.semantic_effect === false) {
            return 'Read-only workflow';
        }
        if (event.semantic_effect !== true) {
            return '';
        }
        switch (normaliseThinkingActivityString(event.effect_status).toLowerCase()) {
        case 'succeeded':
            return 'Requested effect completed';
        case 'not_started':
            return 'Effect not started';
        case 'failed':
            return 'Effect failed';
        case 'partial':
            return 'Effect still pending';
        case 'indeterminate':
            return 'Effect outcome unknown';
        default:
            return '';
        }
    })();
    const nextActionText = event.next_action ? `Next: ${event.next_action}` : '';
    switch (event.status) {
    case 'workflow_execution_selected':
        return workflowText ? `Selected ${workflowText}` : 'Selected workflow';
    case 'workflow_execution_start':
        return workflowText ? `Started ${workflowText}` : 'Started selected workflow';
    case 'workflow_execution_complete':
        return [
            workflowText ? `Completed ${workflowText}` : 'Completed selected workflow',
            stateText
                ? `Last step: ${stateText}`
                : (actionText ? `Last step: ${actionText}` : event.final_state),
            effectText,
            nextActionText
        ].filter(Boolean).join(' · ');
    case 'workflow_execution_failed':
        return [
            workflowText ? `Failed ${workflowText}` : 'Selected workflow failed',
            stateText || actionText || event.final_state,
            event.failure_reason || event.error,
            effectText,
            nextActionText
        ].filter(Boolean).join(' · ');
    case 'workflow_execution_waiting':
        return [
            workflowText ? `Waiting for ${workflowText}` : 'Waiting for selected workflow',
            stateText || actionText,
            effectText,
            nextActionText
        ].filter(Boolean).join(' · ');
    case 'workflow_execution_indeterminate':
        return [
            workflowText ? `Outcome unknown for ${workflowText}` : 'Selected workflow outcome unknown',
            stateText || actionText,
            event.failure_reason || event.error,
            effectText,
            nextActionText
        ].filter(Boolean).join(' · ');
    case 'workflow_step_start':
        return [actionText ? `Running ${actionText}` : 'Running workflow step', stateText].filter(Boolean).join(' · ');
    case 'workflow_step_complete':
        return [
            actionText ? `Finished ${actionText}` : 'Finished workflow step',
            stateText,
            outcomeText,
            durationText,
            effectText,
            nextActionText
        ].filter(Boolean).join(' · ');
    default:
        return [formatThinkingActivityFallbackLabel(event.status), actionText || stateText || workflowText, outcomeText].filter(Boolean).join(' · ');
    }
}

function buildThinkingSelectedWorkflowExecutionEventLines(execution, workflowDiscovery = null) {
    const events = Array.isArray(execution?.events) ? execution.events : [];
    return events
        .map((event) => formatThinkingSelectedWorkflowExecutionEvent(event, workflowDiscovery))
        .filter(Boolean);
}

function buildWorkflowStageDetailPresentation(stageId, request) {
    const workflowDiscovery = (request?.workflowDiscovery && typeof request.workflowDiscovery === 'object')
        ? request.workflowDiscovery
        : null;
    const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const canonicalRoutingProgress = buildCanonicalWorkflowRoutingProgress(request);
    const cleanStageId = normaliseThinkingActivityString(stageId);
    const stageDiagnostic = getThinkingStageDiagnosticEntry(request, cleanStageId);
    const stageData = buildThinkingWorkflowStageDiagnosticData(
        cleanStageId,
        normaliseThinkingActivityString(stageDiagnostic?.stage_label)
            || formatThinkingActivityFallbackLabel(cleanStageId)
            || 'Workflow step',
        request
    );
    const routingNarrative = buildWorkflowRoutingNarrative(canonicalRoutingProgress, workflowDiscovery, {
        includeNoMatchTransition: true,
    });

    if (cleanStageId === 'selected_workflow_execution') {
        const execution = getThinkingSelectedWorkflowExecution(request);
        const latestLine = formatThinkingSelectedWorkflowExecutionEvent(
            execution?.latest_event,
            workflowDiscovery
        );
        if (latestLine) {
            const projectedFactsLine = formatThinkingProgressFactsInline(
                execution?.latest_event?.progress_facts || execution?.progress_facts,
                THINKING_CARD_MODE_DEFAULT
            );
            const detailLine = [latestLine, projectedFactsLine].filter(Boolean).join(' · ');
            return {
                text: detailLine,
                html: escapeHtml(detailLine)
            };
        }
        if (execution?.summary_text) {
            return {
                text: execution.summary_text,
                html: escapeHtml(execution.summary_text)
            };
        }
    }

    if (cleanStageId === 'workflow_discovery') {
        const errors = Array.isArray(workflowDiscovery?.errors)
            ? workflowDiscovery.errors.filter((item) => typeof item === 'string' && item.trim())
            : [];
        if (errors.length > 0) {
            return {
                text: errors[0].trim(),
                html: escapeHtml(errors[0].trim())
            };
        }

        const matchCount = getWorkflowDiscoveryMatchCount(workflowDiscovery);
        const candidateCount = getWorkflowDiscoveryCandidateCount(workflowDiscovery);
        if (matchCount === null) {
            return {
                text: 'Searching applicable workflows',
                html: 'Searching applicable workflows'
            };
        }
        if (matchCount <= 0 && routingNarrative.context.hasSelection) {
            return {
                text: routingNarrative.text,
                html: routingNarrative.html
            };
        }
        if (matchCount <= 0 && candidateCount > 0) {
            const primaryCandidate = normaliseWorkflowDiscoveryCandidates(workflowDiscovery)[0] || null;
            const primaryLabel = formatWorkflowDisplayText(
                primaryCandidate?.concept_id,
                primaryCandidate?.name,
                workflowDiscovery
            );
            const primaryLabelHtml = renderWorkflowDisplayHtml(
                primaryCandidate?.concept_id,
                primaryCandidate?.name,
                workflowDiscovery
            );
            if (primaryLabel) {
                return {
                    text: candidateCount > 1
                        ? `Found candidate ${primaryLabel} · ${candidateCount} candidates`
                        : `Found candidate ${primaryLabel}`,
                    html: candidateCount > 1
                        ? `Found candidate ${primaryLabelHtml || escapeHtml(primaryLabel)} · ${candidateCount} candidates`
                        : `Found candidate ${primaryLabelHtml || escapeHtml(primaryLabel)}`
                };
            }
            return {
                text: candidateCount > 1
                    ? `Found ${candidateCount} workflow candidates`
                    : 'Found 1 workflow candidate',
                html: candidateCount > 1
                    ? `Found ${candidateCount} workflow candidates`
                    : 'Found 1 workflow candidate'
            };
        }
        if (matchCount <= 0) {
            return {
                text: 'No direct workflow match found',
                html: 'No direct workflow match found'
            };
        }

        const primaryMatch = normaliseWorkflowDiscoveryMatches(workflowDiscovery)[0] || null;
        const primaryLabel = formatWorkflowDisplayText(
            primaryMatch?.concept_id,
            primaryMatch?.name,
            workflowDiscovery
        );
        const primaryLabelHtml = renderWorkflowDisplayHtml(
            primaryMatch?.concept_id,
            primaryMatch?.name,
            workflowDiscovery
        );
        if (primaryLabel) {
            return {
                text: matchCount > 1
                    ? `Found ${primaryLabel} · ${matchCount} matches`
                    : `Found ${primaryLabel}`,
                html: matchCount > 1
                    ? `Found ${primaryLabelHtml || escapeHtml(primaryLabel)} · ${matchCount} matches`
                    : `Found ${primaryLabelHtml || escapeHtml(primaryLabel)}`
            };
        }
        return {
            text: matchCount > 1
                ? `Found ${matchCount} applicable workflows`
                : 'Found 1 applicable workflow',
            html: matchCount > 1
                ? `Found ${matchCount} applicable workflows`
                : 'Found 1 applicable workflow'
        };
    }

    if (cleanStageId === 'workflow_dispatch' || cleanStageId === 'plain_response') {
        return {
            text: routingNarrative.text,
            html: routingNarrative.html
        };
    }

    if (cleanStageId === 'expected_outcome_inference') {
        const inferredContractSummary = buildThinkingCaptureSummaryText(
            stageData?.llm_response_preview,
            normaliseThinkingActivityString(stageData?.latest_result_summary)
        );
        if (inferredContractSummary) {
            return {
                text: `Inferring success criteria · ${inferredContractSummary}`,
                html: `Inferring success criteria · ${escapeHtml(inferredContractSummary)}`
            };
        }
        return {
            text: 'Inferring what a grounded successful answer should satisfy',
            html: 'Inferring what a grounded successful answer should satisfy'
        };
    }

    if (cleanStageId === 'selector_preparation') {
        const requestState = formatThinkingLlmRequestState(stageData?.llm_request_state);
        const textBits = ['Preparing selector context'];
        const htmlBits = ['Preparing selector context'];
        if (requestState) {
            textBits.push(requestState);
            htmlBits.push(escapeHtml(requestState));
        }
        if (buildThinkingCaptureSummaryText(stageData?.selector_prompt)) {
            textBits.push('prompt ready');
            htmlBits.push('prompt ready');
        }
        return {
            text: textBits.join(' · '),
            html: htmlBits.join(' · ')
        };
    }

    if (cleanStageId === 'selector_decision') {
        const workflowText = formatWorkflowDisplayText(
            stageData?.selected_workflow_id,
            stageData?.selected_workflow_name,
            workflowDiscovery
        );
        const workflowHtml = renderWorkflowDisplayHtml(
            stageData?.selected_workflow_id,
            stageData?.selected_workflow_name,
            workflowDiscovery
        ) || escapeHtml(workflowText || '');
        const selectorVerdict = normaliseThinkingActivityString(stageData?.workflow_selector_verdict);
        if (workflowText) {
            const textBits = [`Selected ${workflowText}`];
            const htmlBits = [`Selected ${workflowHtml}`];
            if (selectorVerdict) {
                const formattedVerdict = formatThinkingActivityFallbackLabel(selectorVerdict);
                textBits.push(formattedVerdict);
                htmlBits.push(escapeHtml(formattedVerdict));
            }
            return {
                text: textBits.join(' · '),
                html: htmlBits.join(' · ')
            };
        }
        const requestState = formatThinkingLlmRequestState(stageData?.llm_request_state);
        if (requestState) {
            return {
                text: `Evaluating workflow candidates · ${requestState}`,
                html: `Evaluating workflow candidates · ${escapeHtml(requestState)}`
            };
        }
        return {
            text: 'Evaluating workflow candidates',
            html: 'Evaluating workflow candidates'
        };
    }

    if (cleanStageId === 'workflow_dispatch_prepare') {
        const latestPreDispatchStep = Array.isArray(stageData?.pre_dispatch?.steps)
            && stageData.pre_dispatch.steps.length > 0
            ? stageData.pre_dispatch.steps[stageData.pre_dispatch.steps.length - 1]
            : null;
        const workflowText = formatWorkflowDisplayText(
            stageData?.selected_workflow_id,
            stageData?.selected_workflow_name,
            workflowDiscovery
        );
        const workflowHtml = renderWorkflowDisplayHtml(
            stageData?.selected_workflow_id,
            stageData?.selected_workflow_name,
            workflowDiscovery
        ) || escapeHtml(workflowText || '');
        const latestCheckLabel = normaliseThinkingActivityString(latestPreDispatchStep?.result_summary)
            || normaliseThinkingActivityString(latestPreDispatchStep?.step_label)
            || normaliseThinkingActivityString(stageData?.latest_subtask)
            || normaliseThinkingActivityString(stageData?.latest_workflow_task);
        const completedChecks = Number.isFinite(stageData?.pre_dispatch?.completed_step_count)
            ? Number(stageData.pre_dispatch.completed_step_count)
            : null;

        if (workflowText) {
            const textBits = [`Preparing ${workflowText} for dispatch`];
            const htmlBits = [`Preparing ${workflowHtml} for dispatch`];
            if (latestCheckLabel) {
                textBits.push(latestCheckLabel);
                htmlBits.push(escapeHtml(latestCheckLabel));
            } else if (completedChecks !== null && completedChecks > 0) {
                const checkSummary = formatThinkingCountLabel(completedChecks, 'pre-dispatch check');
                textBits.push(checkSummary);
                htmlBits.push(escapeHtml(checkSummary));
            }
            return {
                text: textBits.join(' · '),
                html: htmlBits.join(' · ')
            };
        }
        if (latestCheckLabel) {
            return {
                text: `Preparing dispatch inputs · ${latestCheckLabel}`,
                html: `Preparing dispatch inputs · ${escapeHtml(latestCheckLabel)}`
            };
        }
        return {
            text: 'Preparing workflow dispatch',
            html: 'Preparing workflow dispatch'
        };
    }

    if (cleanStageId === 'tool_plan') {
        const workflowText = formatWorkflowDisplayText(
            stageData?.selected_workflow_id,
            stageData?.selected_workflow_name,
            workflowDiscovery
        );
        const workflowHtml = renderWorkflowDisplayHtml(
            stageData?.selected_workflow_id,
            stageData?.selected_workflow_name,
            workflowDiscovery
        ) || escapeHtml(workflowText || '');
        const plannedCount = Number.isFinite(stageData?.tool_execution?.planned_count)
            ? Number(stageData.tool_execution.planned_count)
            : null;
        const planningFocus = normaliseThinkingActivityString(stageData?.latest_workflow_task)
            || normaliseThinkingActivityString(stageData?.latest_tool)
            || normaliseThinkingActivityString(stageData?.latest_subtask);

        let text = plannedCount !== null
            ? `Planning ${formatThinkingCountLabel(plannedCount, 'tool call')}`
            : 'Planning tool calls';
        let html = escapeHtml(text);
        if (workflowText) {
            text += ` for ${workflowText}`;
            html += ` for ${workflowHtml}`;
        }
        if (planningFocus) {
            text += ` · ${planningFocus}`;
            html += ` · ${escapeHtml(planningFocus)}`;
        }
        return { text, html };
    }

    if (cleanStageId === 'tool_execute') {
        const toolNames = getCanonicalThinkingToolHistory(request)
            .map((entry) => normaliseThinkingActivityString(entry?.tool || entry?.workflowTask))
            .filter(Boolean);
        const uniqueToolNames = [...new Set(toolNames)];
        if (uniqueToolNames.length > 0) {
            const preview = uniqueToolNames.slice(0, 3).join(', ');
            const text = uniqueToolNames.length > 3
                ? `Tools: ${preview} +${uniqueToolNames.length - 3} more`
                : `Tools: ${preview}`;
            return {
                text,
                html: escapeHtml(text)
            };
        }
    }

    if (cleanStageId === 'screen_backfill' || cleanStageId === 'narration') {
        const transformationText = buildThinkingTransformationSummaryText(
            cleanStageId,
            stageData?.response_transformation
        );
        const workflowText = formatWorkflowDisplayText(
            stageData?.selected_workflow_id,
            stageData?.selected_workflow_name,
            workflowDiscovery
        );
        const workflowHtml = renderWorkflowDisplayHtml(
            stageData?.selected_workflow_id,
            stageData?.selected_workflow_name,
            workflowDiscovery
        ) || escapeHtml(workflowText || '');
        if (transformationText) {
            return {
                text: workflowText
                    ? `${transformationText} · Workflow: ${workflowText}`
                    : transformationText,
                html: workflowText
                    ? `${escapeHtml(transformationText)} · Workflow: ${workflowHtml}`
                    : escapeHtml(transformationText)
            };
        }
        if (workflowText) {
            const prefix = cleanStageId === 'narration'
                ? 'Preparing spoken narration'
                : 'Preparing the on-screen response';
            return {
                text: `${prefix} · Workflow: ${workflowText}`,
                html: `${escapeHtml(prefix)} · Workflow: ${workflowHtml}`
            };
        }
    }

    if (cleanStageId === 'postcondition_critic') {
        const criticSnapshot = buildThinkingCriticSummarySnapshot(stageData?.critic_verdict);
        if (criticSnapshot.unresolvedCheckCount > 0) {
            const text = `Found ${formatThinkingCountLabel(criticSnapshot.unresolvedCheckCount, 'unresolved postcondition check')}`;
            return {
                text,
                html: escapeHtml(text)
            };
        }
        if (criticSnapshot.verifiedCount > 0) {
            const text = `Validated ${formatThinkingCountLabel(criticSnapshot.verifiedCount, 'required check')}`;
            return {
                text,
                html: escapeHtml(text)
            };
        }
        return {
            text: 'Checking required effects and evidence before completion',
            html: 'Checking required effects and evidence before completion'
        };
    }

    if (cleanStageId === 'completion_gate') {
        const text = buildThinkingCompletionGateSummaryText(stageData?.completion_gate);
        return {
            text,
            html: escapeHtml(text)
        };
    }

    const latestStageId = normaliseThinkingActivityString(latestProgress?.stage || latestProgress?.phase);
    if (cleanStageId && latestStageId === cleanStageId) {
        const resultSummary = normaliseThinkingActivityString(latestProgress?.result_summary);
        if (resultSummary) {
            return {
                text: resultSummary,
                html: escapeHtml(resultSummary)
            };
        }
    }

    const stageResultSummary = normaliseThinkingActivityString(stageDiagnostic?.latest_result_summary);
    if (stageResultSummary) {
        return {
            text: stageResultSummary,
            html: escapeHtml(stageResultSummary)
        };
    }

    return {
        text: '',
        html: ''
    };
}

function buildThinkingWorkflowStageRows(request) {
    if (!request || typeof request !== 'object') {
        return [];
    }
    const selectedWorkflowExecutionSummary = normaliseThinkingCardWorkflowExecutionSummary(
        deriveThinkingCardWorkflowExecutionSummary(request)
    );
    const liveSelectedWorkflowExecution = getThinkingSelectedWorkflowExecution(request);
    const selectedWorkflowExecution = liveSelectedWorkflowExecution || selectedWorkflowExecutionSummary;

    const workflowStagePath = (request.workflowStagePath && typeof request.workflowStagePath === 'object')
        ? request.workflowStagePath
        : null;
    const path = Array.isArray(workflowStagePath?.path)
        ? workflowStagePath.path.filter((entry) => entry && typeof entry === 'object')
        : [];
    const preservedRows = Array.isArray(request?.stageDiagnostics)
        ? request.stageDiagnostics
            .map((entry) => normaliseThinkingStageDiagnosticSnapshotEntry(entry))
            .filter((entry) => entry && (entry.stage_id || entry.label))
            .map((entry) => ({
                stageId: entry.stage_id,
                label: entry.label || formatThinkingActivityFallbackLabel(entry.stage_id) || 'Workflow step',
                detail: entry.detail || '',
                detailHtml: '',
                state: entry.state || null,
                diagnosticKey: buildThinkingDiagnosticKey('stage', entry.stage_id || entry.label),
                diagnosticData: entry.diagnostics || null
            }))
        : [];

    const workflowDiscovery = (request.workflowDiscovery && typeof request.workflowDiscovery === 'object')
        ? request.workflowDiscovery
        : null;
    const fallbackProgressStageRow = (() => {
        const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
            ? request.latestProgress
            : null;
        if (!latestProgress) {
            return null;
        }
        const stageId = normaliseThinkingActivityString(latestProgress.stage || latestProgress.phase) || 'context_build';
        const stageLabel = normaliseThinkingActivityString(latestProgress.stage_label || latestProgress.phase_label)
            || formatThinkingActivityFallbackLabel(stageId)
            || 'Current progress';
        const interpretation = deriveThinkingExecutionInterpretation(request);
        const detail = firstThinkingCardText(
            interpretation?.step_summary,
            latestProgress.result_summary,
            latestProgress.subtask,
            latestProgress.workflow_task,
            latestProgress.pending_reason
        );
        return {
            stageId,
            label: stageLabel,
            detail,
            detailHtml: detail ? escapeHtml(detail) : '',
            state: resolveThinkingLatestStageRowState(latestProgress, stageId)
                || (isTerminalThinkingProgress(latestProgress) ? 'success' : 'pending'),
            diagnosticKey: buildThinkingDiagnosticKey('stage', stageId),
            diagnosticData: buildThinkingWorkflowStageDiagnosticData(stageId, stageLabel, request)
        };
    })();
    if (path.length === 0) {
        if (preservedRows.length > 0) {
            const preservedHasSelectedWorkflowExecution = preservedRows.some((entry) => (
                canonicaliseThinkingDiagnosticStageId(entry.stageId || entry.stage_id || entry.label)
                === 'selected_workflow_execution'
            ));
            if (selectedWorkflowExecution && !preservedHasSelectedWorkflowExecution) {
                return [
                    buildSelectedWorkflowExecutionStageRow(
                        selectedWorkflowExecution,
                        workflowDiscovery
                    ),
                    ...preservedRows,
                ];
            }
            return preservedRows;
        }
        if (workflowDiscovery) {
            const diagnosticData = buildThinkingWorkflowStageDiagnosticData(
                'workflow_discovery',
                'Workflow discovery',
                request
            );
            const detailPresentation = buildWorkflowStageDetailPresentation('workflow_discovery', request);
            const routingContext = buildWorkflowRoutingContext(
                buildCanonicalWorkflowRoutingProgress(request),
                workflowDiscovery
            );
            const discoveryRows = [{
                stageId: 'workflow_discovery',
                label: 'Workflow discovery',
                detail: detailPresentation.text,
                detailHtml: detailPresentation.html,
                state: routingContext.noDirectMatch && routingContext.hasSelection
                    ? 'success'
                    : (getWorkflowDiscoveryMatchCount(workflowDiscovery) > 0 ? 'success' : 'failure'),
                diagnosticKey: buildThinkingDiagnosticKey('stage', 'workflow_discovery'),
                diagnosticData
            }];
            if (selectedWorkflowExecution) {
                discoveryRows.unshift(buildSelectedWorkflowExecutionStageRow(
                    selectedWorkflowExecution,
                    workflowDiscovery
                ));
            }
            if (
                fallbackProgressStageRow
                && !discoveryRows.some((entry) => entry.stageId === fallbackProgressStageRow.stageId)
            ) {
                discoveryRows.push(fallbackProgressStageRow);
            }
            return discoveryRows;
        }
        if (selectedWorkflowExecution) {
            const selectedRow = buildSelectedWorkflowExecutionStageRow(
                selectedWorkflowExecution,
                workflowDiscovery
            );
            if (
                fallbackProgressStageRow
                && fallbackProgressStageRow.stageId !== selectedRow.stageId
            ) {
                return [selectedRow, fallbackProgressStageRow];
            }
            return [selectedRow];
        }
        return fallbackProgressStageRow ? [fallbackProgressStageRow] : [];
    }

    const latestProgress = (request.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const routingContext = buildWorkflowRoutingContext(
        buildCanonicalWorkflowRoutingProgress(request),
        workflowDiscovery
    );
    const latestStageId = (() => {
        const lastStage = path[path.length - 1];
        return normaliseThinkingActivityString(lastStage?.stage_id || lastStage?.runtime_stage_normalised);
    })();
    const latestIsTerminal = isTerminalThinkingProgress(latestProgress);
    const latestStageRowState = resolveThinkingLatestStageRowState(latestProgress, latestStageId);

    const stageRows = path.map((entry, index) => {
        const stageId = normaliseThinkingActivityString(entry.stage_id || entry.runtime_stage_normalised);
        const stageLabel = normaliseThinkingActivityString(entry.stage_label)
            || formatThinkingActivityFallbackLabel(stageId)
            || 'Workflow step';
        const diagnosticData = buildThinkingWorkflowStageDiagnosticData(stageId, stageLabel, request);
        const detailPresentation = buildWorkflowStageDetailPresentation(stageId, request);
        const authorityDetail = buildThinkingStageAuthoritySummaryText(diagnosticData);
        const detail = authorityDetail
            ? [detailPresentation.text, authorityDetail].filter(Boolean).join(' · ')
            : detailPresentation.text;
        const detailHtml = authorityDetail
            ? [detailPresentation.html, escapeHtml(authorityDetail)].filter(Boolean).join(' · ')
            : detailPresentation.html;
        let state = 'success';

        if (stageId === 'workflow_discovery') {
            const matchCount = getWorkflowDiscoveryMatchCount(workflowDiscovery);
            const candidateCount = getWorkflowDiscoveryCandidateCount(workflowDiscovery);
            const discoveryErrors = Array.isArray(workflowDiscovery?.errors)
                ? workflowDiscovery.errors.filter((item) => typeof item === 'string' && item.trim())
                : [];
            if (routingContext.noDirectMatch && routingContext.hasSelection) {
                state = 'success';
            } else if (discoveryErrors.length > 0 || matchCount === 0) {
                state = candidateCount > 0 ? 'success' : 'failure';
            } else if (matchCount === null) {
                state = 'pending';
            }
        } else if (index === path.length - 1 && !latestIsTerminal) {
            state = 'pending';
        } else if (stageId === latestStageId && latestStageRowState === 'failure') {
            state = 'failure';
        }

        return {
            stageId,
            label: stageLabel,
            detail,
            detailHtml,
            state,
            diagnosticKey: buildThinkingDiagnosticKey('stage', stageId),
            diagnosticData
        };
    });

    const pathHasSelectedWorkflowExecution = path.some((entry) => (
        canonicaliseThinkingDiagnosticStageId(entry.stage_id || entry.runtime_stage_normalised)
        === 'selected_workflow_execution'
    ));
    if (selectedWorkflowExecution && !pathHasSelectedWorkflowExecution) {
        stageRows.unshift(buildSelectedWorkflowExecutionStageRow(
            selectedWorkflowExecution,
            workflowDiscovery
        ));
    }

    if (preservedRows.length === 0) {
        return stageRows;
    }

    const mergedRows = stageRows.map((entry) => ({ ...entry }));
    const seenStageKeys = new Set(
        mergedRows
            .map((entry) => normaliseThinkingActivityString(entry.stageId || entry.label))
            .filter(Boolean)
    );

    for (const entry of preservedRows) {
        const stageKey = normaliseThinkingActivityString(entry.stageId || entry.label);
        if (!stageKey || seenStageKeys.has(stageKey)) {
            continue;
        }
        mergedRows.push({ ...entry });
        seenStageKeys.add(stageKey);
    }

    return mergedRows;
}

function buildSelectedWorkflowExecutionStageRow(summary, workflowDiscovery = null) {
    const workflowId = normaliseThinkingActivityString(summary?.workflow_id || summary?.selected_workflow_id);
    const instanceId = normaliseThinkingActivityString(summary?.workflow_instance_id);
    const eventLine = formatThinkingSelectedWorkflowExecutionEvent(
        summary?.latest_event,
        workflowDiscovery
    );
    const workflowText = formatWorkflowDisplayText(
        workflowId,
        summary?.selected_workflow_name,
        workflowDiscovery
    );
    const detailBits = [
        workflowText ? `Workflow: ${workflowText}` : '',
        instanceId ? `Instance: ${instanceId}` : '',
        eventLine || summary?.summary_text || '',
        formatThinkingProgressFactsInline(
            summary?.latest_event?.progress_facts || summary?.progress_facts,
            THINKING_CARD_MODE_DEFAULT
        )
    ].filter(Boolean);
    const latestStatus = normaliseThinkingActivityString(summary?.latest_event?.status);
    const state = summary?.action_failure_count > 0 || latestStatus === 'workflow_execution_failed'
        ? 'failure'
        : (
            summary?.terminal_status === 'completed'
            || latestStatus === 'workflow_execution_complete'
                ? 'success'
                : 'pending'
        );
    return {
        stageId: 'selected_workflow_execution',
        label: 'Selected workflow execution',
        detail: detailBits.join(' · '),
        detailHtml: detailBits.map((value) => escapeHtml(value)).join(' · '),
        state,
        diagnosticKey: buildThinkingDiagnosticKey('stage', 'selected_workflow_execution'),
        diagnosticData: {
            stage_id: 'selected_workflow_execution',
            stage_label: 'Selected workflow execution',
            selected_workflow_id: workflowId || null,
            selected_workflow_name: normaliseThinkingActivityString(summary?.selected_workflow_name) || null,
            workflow_instance_id: instanceId || null,
            selected_workflow_event_count: Number.isFinite(summary?.event_count)
                ? Number(summary.event_count)
                : (Array.isArray(summary?.events) ? summary.events.length : 0),
            latest_selected_workflow_event: summary?.latest_event || null,
            selected_workflow_execution: summary?.events ? { ...summary } : null,
            custom_workflow_execution: { ...summary },
            progress_facts: normaliseThinkingProgressFacts(
                summary?.latest_event?.progress_facts || summary?.progress_facts
            )
        }
    };
}

function renderThinkingWorkflowStageHistoryHTML(request, mode = THINKING_CARD_MODE_DEFAULT) {
    const rows = buildThinkingWorkflowStageRows(request);
    if (rows.length === 0) {
        return '';
    }

    const renderMode = normaliseThinkingCardMode(mode);
    return rows.map((entry) => renderThinkingDiagnosticRowHTML({
        ...entry,
        diagnosticHtml: (() => {
            if (renderMode === THINKING_CARD_MODE_DEBUG) {
                return renderThinkingWorkflowStageDiagnosticDataHTML(
                    entry.diagnosticData,
                    request?.workflowDiscovery || null
                );
            }
            if (renderMode === THINKING_CARD_MODE_EXPERT) {
                return renderThinkingWorkflowStageExpertDataHTML(
                    entry.diagnosticData,
                    request?.workflowDiscovery || null
                );
            }
            return '';
        })()
    }, 'thinking-card-tool thinking-card-activity')).join('');
}

function formatThinkingTimingOperationLabel(operationKind, operationName) {
    const kind = normaliseThinkingActivityString(operationKind);
    const name = normaliseThinkingActivityString(operationName);
    const kindLabel = kind ? formatThinkingActivityFallbackLabel(kind) : '';
    if (!name || name === kind) {
        return kindLabel || name;
    }
    return kindLabel ? `${kindLabel} / ${name}` : name;
}

function formatThinkingTimingModelProviderLabel(row) {
    const model = normaliseThinkingActivityString(row?.model);
    const provider = normaliseThinkingActivityString(row?.provider);
    if (provider && model) {
        return `${provider}/${model}`;
    }
    return model || provider;
}

function formatThinkingTimingSpanLine(row, options = {}) {
    if (!row || typeof row !== 'object') {
        return '';
    }
    const includePrompt = options.includePrompt !== false;
    const stage = normaliseThinkingActivityString(row.stage_id || row.stage)
        || 'unscoped';
    const operation = formatThinkingTimingOperationLabel(row.operation_kind, row.operation_name);
    const duration = formatThinkingDiagnosticDuration(row.duration_ms);
    const status = formatThinkingActivityFallbackLabel(row.status);
    const model = formatThinkingTimingModelProviderLabel(row);
    const promptId = includePrompt ? normaliseThinkingActivityString(row.prompt_id) : '';

    return [
        formatThinkingActivityFallbackLabel(stage),
        operation,
        duration,
        status,
        model,
        promptId ? `prompt ${promptId}` : ''
    ].filter(Boolean).join(' · ');
}

function deriveThinkingTimingSpanState(row) {
    const status = normaliseThinkingActivityString(row?.status).toLowerCase();
    if (['success', 'completed', 'complete', 'done'].includes(status)) {
        return 'success';
    }
    if (['failure', 'failed', 'error', 'errored'].includes(status)) {
        return 'failure';
    }
    return 'pending';
}

function formatThinkingOperationTotalLine(row) {
    if (!row || typeof row !== 'object') {
        return '';
    }
    const operation = formatThinkingTimingOperationLabel(row.operation_kind, row.operation_name);
    const count = Number.isFinite(row.span_count)
        ? formatThinkingCountLabel(Number(row.span_count), 'span')
        : '';
    const duration = formatThinkingDiagnosticDuration(row.duration_ms);
    return [operation, count, duration].filter(Boolean).join(' · ');
}

function formatThinkingModelPromptTimingLine(row) {
    if (!row || typeof row !== 'object') {
        return '';
    }
    const stage = normaliseThinkingActivityString(row.stage_id || row.stage);
    const model = formatThinkingTimingModelProviderLabel(row);
    const promptId = normaliseThinkingActivityString(row.prompt_id);
    const calls = Number.isFinite(row.call_count)
        ? formatThinkingCountLabel(Number(row.call_count), 'call')
        : '';
    const successCount = Number.isFinite(row.success_count)
        ? `${Number(row.success_count)} ok`
        : '';
    const failureCount = Number.isFinite(row.failure_count) && Number(row.failure_count) > 0
        ? `${Number(row.failure_count)} failed`
        : '';
    const duration = formatThinkingDiagnosticDuration(row.duration_ms);
    const promptCharCount = toThinkingCardOptionalNonNegativeInteger(
        row.max_prompt_char_count || row.prompt_char_count
    );
    const promptSize = (
        promptCharCount !== null
        && promptCharCount >= THINKING_LARGE_LLM_PROMPT_CHAR_THRESHOLD
    )
        ? `large input ${promptCharCount.toLocaleString()} chars`
        : '';
    const latencySummary = row.first_output_latency_ms && typeof row.first_output_latency_ms === 'object'
        ? row.first_output_latency_ms
        : null;
    const firstOutput = latencySummary && Number.isFinite(latencySummary.mean_ms)
        ? `first output avg ${formatThinkingDiagnosticDuration(latencySummary.mean_ms)}`
        : '';

    return [
        stage ? formatThinkingActivityFallbackLabel(stage) : '',
        model,
        promptId ? `prompt ${promptId}` : '',
        calls,
        successCount,
        failureCount,
        promptSize,
        duration,
        firstOutput
    ].filter(Boolean).join(' · ');
}

function buildThinkingTimingSummaryFacts(request) {
    const summary = getThinkingTimingSummary(request);
    if (!summary || typeof summary !== 'object') {
        return [];
    }
    const timing = summary.summary && typeof summary.summary === 'object'
        ? summary.summary
        : {};
    const spanBits = [];
    if (Number.isFinite(summary.span_count)) {
        spanBits.push(String(Number(summary.span_count)));
    }
    if (Number.isFinite(summary.stored_span_count) && summary.stored_span_count !== summary.span_count) {
        spanBits.push(`${Number(summary.stored_span_count)} stored`);
    }
    if (Number.isFinite(summary.dropped_span_count) && Number(summary.dropped_span_count) > 0) {
        spanBits.push(`${Number(summary.dropped_span_count)} dropped`);
    }
    return [
        { label: 'Spans', value: spanBits.join(' · ') },
        { label: 'Elapsed', value: formatThinkingDiagnosticDuration(timing.elapsed_ms) },
        { label: 'Phase time', value: formatThinkingDiagnosticDuration(timing.phase_elapsed_ms) },
        { label: 'Operation time', value: formatThinkingDiagnosticDuration(timing.operation_elapsed_ms) },
        { label: 'LLM time', value: formatThinkingDiagnosticDuration(timing.llm_elapsed_ms) },
        { label: 'Tool time', value: formatThinkingDiagnosticDuration(timing.tool_elapsed_ms) }
    ];
}

function buildThinkingTimingDiagnosticPanelHTML(request, mode = THINKING_CARD_MODE_EXPERT) {
    const renderMode = normaliseThinkingCardMode(mode);
    if (renderMode === THINKING_CARD_MODE_DEFAULT) {
        return '';
    }
    const slowestRows = getThinkingSlowestTimingSpans(request);
    const operationRows = getThinkingOperationTotalRows(request);
    const modelPromptRows = getThinkingModelPromptTimingRows(request);
    const slowestLimit = renderMode === THINKING_CARD_MODE_DEBUG
        ? slowestRows.length
        : Math.min(5, slowestRows.length);
    const operationLimit = renderMode === THINKING_CARD_MODE_DEBUG
        ? operationRows.length
        : Math.min(5, operationRows.length);
    const modelPromptLimit = renderMode === THINKING_CARD_MODE_DEBUG
        ? modelPromptRows.length
        : Math.min(5, modelPromptRows.length);
    const sections = [
        buildThinkingDiagnosticListHTML(
            'Slowest spans',
            slowestRows.slice(0, slowestLimit).map((row) => formatThinkingTimingSpanLine(row))
        ),
        buildThinkingDiagnosticListHTML(
            'Operation totals',
            operationRows.slice(0, operationLimit).map(formatThinkingOperationTotalLine)
        ),
        buildThinkingDiagnosticListHTML(
            'Model/prompt timing',
            modelPromptRows.slice(0, modelPromptLimit).map(formatThinkingModelPromptTimingLine)
        )
    ];
    return renderThinkingDiagnosticPanelHTML({
        facts: buildThinkingTimingSummaryFacts(request),
        sections
    });
}

function formatThinkingLlmTimingLine(row) {
    if (!row || typeof row !== 'object') {
        return '';
    }
    const stage = normaliseThinkingActivityString(row.stage);
    const model = normaliseThinkingActivityString(row.model) || 'unknown model';
    const provider = normaliseThinkingActivityString(row.provider);
    const duration = formatThinkingDiagnosticDuration(row.duration_ms);
    const calls = Number.isFinite(row.call_count)
        ? formatThinkingCountLabel(Number(row.call_count), 'call')
        : '';
    const promptCharCount = toThinkingCardOptionalNonNegativeInteger(
        row.max_prompt_char_count || row.prompt_char_count
    );
    const promptSize = (
        promptCharCount !== null
        && promptCharCount >= THINKING_LARGE_LLM_PROMPT_CHAR_THRESHOLD
    )
        ? `large input ${promptCharCount.toLocaleString()} chars`
        : '';
    const bits = [
        stage ? formatThinkingActivityFallbackLabel(stage) : '',
        provider ? `${provider}/${model}` : model,
        calls,
        promptSize,
        duration
    ].filter(Boolean);

    if (hasSufficientThinkingTimingBaseline(row)) {
        const mean = formatThinkingDiagnosticDuration(row.historical_mean_duration_ms);
        const stddev = Number.isFinite(row.historical_stddev_duration_ms)
            ? formatThinkingDiagnosticDuration(row.historical_stddev_duration_ms)
            : '';
        const count = Number(row.historical_observation_count);
        const classification = normaliseThinkingActivityString(row.duration_deviation_classification);
        const baseline = [
            mean ? `usual ${mean}` : '',
            stddev ? `+/- ${stddev}` : '',
            Number.isFinite(count) ? `n=${count}` : '',
            classification && classification !== 'within_usual_range'
                ? formatThinkingActivityFallbackLabel(classification).toLowerCase()
                : ''
        ].filter(Boolean).join(' ');
        if (baseline) {
            bits.push(baseline);
        }
    }

    return bits.join(' · ');
}

function renderThinkingTimingBreakdownHTML(request, mode = THINKING_CARD_MODE_DEFAULT) {
    const renderMode = normaliseThinkingCardMode(mode);
    const sections = [];
    const slowestRows = getThinkingSlowestTimingSpans(request);
    if (slowestRows.length > 0) {
        const topSpan = slowestRows[0];
        sections.push(renderThinkingDiagnosticRowHTML({
            label: slowestRows.length > 1 ? 'Slowest timing spans' : 'Slowest timing span',
            detail: formatThinkingTimingSpanLine(topSpan, {
                includePrompt: renderMode !== THINKING_CARD_MODE_DEFAULT
            }),
            state: deriveThinkingTimingSpanState(topSpan),
            diagnosticKey: buildThinkingDiagnosticKey('timing', 'slowest_spans'),
            diagnosticHtml: buildThinkingTimingDiagnosticPanelHTML(request, renderMode)
        }, 'thinking-card-tool thinking-card-activity'));
    }

    if (renderMode === THINKING_CARD_MODE_DEFAULT) {
        return sections.join('');
    }

    const operationLines = getThinkingOperationTotalRows(request)
        .map(formatThinkingOperationTotalLine)
        .filter(Boolean);
    if (slowestRows.length === 0 && operationLines.length > 0) {
        sections.push(renderThinkingDiagnosticRowHTML({
            label: 'Operation timing',
            detail: operationLines[0],
            diagnosticKey: buildThinkingDiagnosticKey('timing', 'operation_totals'),
            diagnosticHtml: buildThinkingDiagnosticListHTML('Operation totals', operationLines)
        }, 'thinking-card-tool thinking-card-activity'));
    }

    const rows = getThinkingTimingRows(request);
    const timingLines = rows
        .map(formatThinkingLlmTimingLine)
        .filter(Boolean);
    if (timingLines.length > 0) {
        sections.push(renderThinkingDiagnosticRowHTML({
            label: 'LLM timing',
            detail: timingLines[0],
            diagnosticKey: buildThinkingDiagnosticKey('timing', 'llm'),
            diagnosticHtml: renderMode === THINKING_CARD_MODE_DEBUG
                ? buildThinkingDiagnosticListHTML('LLM calls by stage/model', timingLines)
                : ''
        }, 'thinking-card-tool thinking-card-activity'));
    }

    return sections.join('');
}

/**
 * Render workflow discovery results as HTML for the thinking card.
 * JVNAUTOSCI-1076: Shows relevant workflows found during conversation turn.
 */
function renderWorkflowDiscoveryHTML(workflows) {
    if (!workflows || !Array.isArray(workflows) || workflows.length === 0) {
        return '';
    }

    const items = workflows.map(wf => {
        const name = renderWorkflowDisplayHtml(
            wf?.concept_id,
            wf?.name,
            null,
            { classNames: ['thinking-card-workflow-link'] }
        ) || escapeHtml(wf.name || wf.concept_id || 'Unknown workflow');
        const score = typeof wf.relevance_score === 'number'
            ? `<span class="thinking-card-workflow-score">${Math.round(wf.relevance_score * 100)}%</span>`
            : '';
        const desc = wf.description
            ? `<span class="thinking-card-workflow-desc">${escapeHtml(wf.description.slice(0, 80))}${wf.description.length > 80 ? '...' : ''}</span>`
            : '';
        return `<div class="thinking-card-workflow">
            <span class="thinking-card-workflow-icon">⚡</span>
            <span class="thinking-card-workflow-name">${name}</span>${score}${desc}
        </div>`;
    });

    return `<div class="thinking-card-workflows">
        <div class="thinking-card-workflows-header">Possibly relevant workflows:</div>
        ${items.join('')}
    </div>`;
}

/**
 * Render the complete thinking card body HTML including canonical workflow
 * stages and lower-level tool activity.
 */
function renderThinkingCardBodyHTML(request, options = {}) {
    const mode = getThinkingCardMode(request, options);
    const progressViewModel = buildThinkingCardProgressViewModel(request);
    const synopsisHtml = renderThinkingCardProgressSynopsisHTML(progressViewModel, mode, request);
    const llmUsageCostHtml = renderThinkingLlmUsageCostSummaryHTML(request);
    const criticHtml = renderThinkingCriticPanelHTML(request);
    const workflowStageHtml = renderThinkingWorkflowStageHistoryHTML(request, mode);
    const llmCallLogHtml = renderThinkingLlmCallLogSectionHTML(request, mode);
    const timingHtml = renderThinkingTimingBreakdownHTML(request, mode);
    if (mode === THINKING_CARD_MODE_DEFAULT && synopsisHtml) {
        return synopsisHtml + llmUsageCostHtml + criticHtml + workflowStageHtml + timingHtml + renderToolHistoryHTML(request, mode) + llmCallLogHtml;
    }

    if (workflowStageHtml) {
        return synopsisHtml + llmUsageCostHtml + criticHtml + workflowStageHtml + timingHtml + renderToolHistoryHTML(request, mode) + llmCallLogHtml;
    }

    const activityHistoryHtml = renderThinkingActivityHistoryHTML(request, mode);
    if (activityHistoryHtml) {
        return synopsisHtml + llmUsageCostHtml + criticHtml + activityHistoryHtml + timingHtml + llmCallLogHtml;
    }

    const toolHistoryHtml = renderToolHistoryHTML(request, mode);
    const workflowHtml = request?.workflowDiscovery?.matches
        ? renderWorkflowDiscoveryHTML(request.workflowDiscovery.matches)
        : '';
    const fallbackProgressHtml = renderThinkingLatestProgressSummaryHTML(request);

    return synopsisHtml + llmUsageCostHtml + criticHtml + timingHtml + toolHistoryHtml + workflowHtml + fallbackProgressHtml + llmCallLogHtml;
}

function resolveThinkingLlmUsageCostSummary(request) {
    const candidates = [
        request?.llmUsageCostSummary,
        request?.latestProgress?.llm_usage_cost_summary
    ];
    return candidates.find((candidate) => candidate && typeof candidate === 'object') || null;
}

function thinkingUsageNumber(value) {
    return Number.isFinite(value) && Number(value) >= 0 ? Number(value) : null;
}

function formatThinkingTokenCount(value, label) {
    const count = thinkingUsageNumber(value);
    return count === null ? '' : `${count.toLocaleString('en-NZ')} ${label}`;
}

function formatThinkingEstimatedCost(cost) {
    if (!cost || typeof cost !== 'object') {
        return 'cost estimate unavailable';
    }
    const status = normaliseThinkingActivityString(cost.status).toLowerCase();
    const currency = normaliseThinkingActivityString(cost.currency).toUpperCase();
    const amount = status === 'estimated'
        ? thinkingUsageNumber(cost.amount)
        : thinkingUsageNumber(cost.known_amount);
    if (amount !== null && currency) {
        let renderedAmount = `${currency} ${amount.toFixed(6)}`;
        if (amount > 0 && amount < 0.0001) {
            renderedAmount = `${currency === 'USD' ? 'US$' : `${currency} `}${amount.toPrecision(3)}`;
        } else {
            try {
                renderedAmount = new Intl.NumberFormat('en-NZ', {
                    style: 'currency',
                    currency,
                    minimumFractionDigits: amount > 0 && amount < 0.01 ? 4 : 2,
                    maximumFractionDigits: 6
                }).format(amount);
            } catch (_) {
                // Keep the explicit currency fallback for an unrecognised code.
            }
        }
        return status === 'partial'
            ? `known cost subtotal ${renderedAmount} (partial)`
            : `estimated ${renderedAmount}`;
    }
    if (status === 'not_applicable') {
        return 'no billable model request';
    }
    return status === 'partial'
        ? 'cost estimate partial; no priced subtotal available'
        : 'cost estimate unavailable';
}

function effectiveThinkingModelIdentity(call) {
    if (!call || typeof call !== 'object') {
        return '';
    }
    const model = normaliseThinkingActivityString(
        call.effective_model || call.model || call.selected_model || call.requested_model
    );
    const provider = normaliseThinkingActivityString(call.provider);
    return model ? (provider ? `${provider}/${model}` : model) : '';
}

function providerObservedThinkingModelIdentity(call) {
    if (normaliseThinkingActivityString(call?.model_identity_source) !== 'provider_response') {
        return '';
    }
    const model = normaliseThinkingActivityString(call?.effective_model);
    const provider = normaliseThinkingActivityString(call?.provider);
    return model ? (provider ? `${provider}/${model}` : model) : '';
}

function renderThinkingLlmUsageCostSummaryHTML(request) {
    const summary = resolveThinkingLlmUsageCostSummary(request);
    if (!summary) {
        const liveEntries = collectThinkingLiveLlmCallLogEntries(request);
        const liveModels = Array.from(new Set(
            liveEntries.map((entry) => effectiveThinkingModelIdentity(entry)).filter(Boolean)
        ));
        if (liveModels.length === 0) {
            return '';
        }
        return `<section class="thinking-card-diagnostic-section thinking-card-llm-usage-cost">
            <div class="thinking-card-diagnostic-section-title">Model usage</div>
            <div class="thinking-card-diagnostic-text">${escapeHtml(liveModels.join(', '))} · in progress · token usage pending</div>
        </section>`;
    }

    const identitiesSource = Array.isArray(summary.model_identities)
        ? summary.model_identities
        : [];
    const calls = identitiesSource.filter(
        (call) => call && typeof call === 'object'
    );
    const identities = Array.from(new Set(
        calls.map((call) => providerObservedThinkingModelIdentity(call)).filter(Boolean)
    ));
    const usage = summary.usage && typeof summary.usage === 'object' ? summary.usage : {};
    const inputTokens = thinkingUsageNumber(usage.input_tokens) ?? thinkingUsageNumber(usage.known_input_tokens);
    const outputTokens = thinkingUsageNumber(usage.output_tokens) ?? thinkingUsageNumber(usage.known_output_tokens);
    const totalTokens = thinkingUsageNumber(usage.total_tokens) ?? thinkingUsageNumber(usage.known_total_tokens);
    const usageStatus = normaliseThinkingActivityString(usage.status).toLowerCase();
    const callCount = thinkingUsageNumber(summary.unique_call_count) ?? thinkingUsageNumber(summary.call_count);
    const bits = [
        identities.length > 0 ? identities.join(', ') : 'effective model identity unavailable',
        formatThinkingTokenCount(inputTokens, 'input'),
        formatThinkingTokenCount(outputTokens, 'output'),
        (inputTokens === null && outputTokens === null) ? formatThinkingTokenCount(totalTokens, 'tokens') : '',
        formatThinkingEstimatedCost(summary.estimated_cost),
        callCount !== null ? `${callCount.toLocaleString('en-NZ')} model call${callCount === 1 ? '' : 's'}` : '',
        usageStatus === 'partial' ? 'token coverage partial' : '',
        usageStatus === 'unavailable' ? 'token usage unavailable' : ''
    ].filter(Boolean);

    return `<section class="thinking-card-diagnostic-section thinking-card-llm-usage-cost">
        <div class="thinking-card-diagnostic-section-title">Model usage</div>
        <div class="thinking-card-diagnostic-text">${escapeHtml(bits.join(' · '))}</div>
    </section>`;
}

function resolveThinkingRequestIdForLlmCallLog(request) {
    const candidates = [
        request?.clientRequestId,
        request?.latestProgress?.request_id,
        request?.turnExecutionDiagnostics?.request_id,
        request?.turn_execution_diagnostics?.request_id,
        request?.latestProgress?.turn_execution_diagnostics?.request_id
    ];
    for (const candidate of candidates) {
        const clean = normaliseThinkingActivityString(candidate);
        if (clean) {
            return clean;
        }
    }
    return '';
}

function ensureThinkingLlmCallLogState(request) {
    if (!request || typeof request !== 'object') {
        return null;
    }
    const currentRequestId = resolveThinkingRequestIdForLlmCallLog(request);
    const existing = (request.thinkingLlmCallLog && typeof request.thinkingLlmCallLog === 'object')
        ? request.thinkingLlmCallLog
        : null;
    if (existing) {
        const existingRequestId = normaliseThinkingActivityString(existing.requestId);
        if (existingRequestId && currentRequestId && existingRequestId !== currentRequestId) {
            request.thinkingLlmCallLog = createThinkingLlmCallLogState(currentRequestId);
            return request.thinkingLlmCallLog;
        }
        existing.requestId = existingRequestId || currentRequestId;
        if (!Array.isArray(existing.entries)) {
            existing.entries = [];
        }
        ensureThinkingLlmCallLogEntryCache(existing);
        return existing;
    }
    request.thinkingLlmCallLog = createThinkingLlmCallLogState(currentRequestId);
    return request.thinkingLlmCallLog;
}

function createThinkingLlmCallLogState(requestId = '') {
    return {
        loading: false,
        loaded: false,
        error: '',
        entries: [],
        totalCount: null,
        nextOffset: 0,
        hasMore: false,
        requestId: normaliseThinkingActivityString(requestId),
        entryCache: new Map()
    };
}

function ensureThinkingLlmCallLogEntryCache(state) {
    if (!state || typeof state !== 'object') {
        return null;
    }
    if (state.entryCache instanceof Map) {
        return state.entryCache;
    }
    const next = new Map();
    const rawCache = state.entryCache;
    if (Array.isArray(rawCache)) {
        rawCache.forEach((pair) => {
            if (!Array.isArray(pair) || pair.length < 2) {
                return;
            }
            const key = normaliseThinkingActivityString(pair[0]);
            if (key && pair[1] && typeof pair[1] === 'object') {
                next.set(key, cloneThinkingLlmCallLogEntry(pair[1]));
            }
        });
    } else if (rawCache && typeof rawCache === 'object') {
        Object.entries(rawCache).forEach(([keyRaw, entry]) => {
            const key = normaliseThinkingActivityString(keyRaw);
            if (key && entry && typeof entry === 'object') {
                next.set(key, cloneThinkingLlmCallLogEntry(entry));
            }
        });
    }
    state.entryCache = next;
    return next;
}

function cloneThinkingLlmCallLogStateForSnapshot(state) {
    if (!state || typeof state !== 'object') {
        return null;
    }
    const cache = ensureThinkingLlmCallLogEntryCache(state);
    return {
        loading: false,
        loaded: state.loaded === true,
        error: normaliseThinkingActivityString(state.error),
        entries: Array.isArray(state.entries)
            ? state.entries.map((entry) => cloneThinkingLlmCallLogEntry(entry)).filter(Boolean)
            : [],
        totalCount: Number.isFinite(state.totalCount) ? Number(state.totalCount) : null,
        nextOffset: Number.isFinite(state.nextOffset) ? Number(state.nextOffset) : 0,
        hasMore: state.hasMore === true,
        requestId: normaliseThinkingActivityString(state.requestId),
        entryCache: cache instanceof Map
            ? Array.from(cache.entries())
                .map(([key, entry]) => [key, cloneThinkingLlmCallLogEntry(entry)])
                .filter(([, entry]) => !!entry)
            : []
    };
}

function formatThinkingLlmCallTimestamp(isoString) {
    if (!isoString || typeof isoString !== 'string') {
        return '';
    }
    const parsed = new Date(isoString);
    if (Number.isNaN(parsed.getTime())) {
        return '';
    }
    const base = parsed.toLocaleTimeString('en-NZ', {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    });
    const millis = String(parsed.getMilliseconds()).padStart(3, '0');
    return `${base}.${millis}`;
}

function captureTextForThinkingLlmCallLog(capture) {
    if (!capture || typeof capture !== 'object') {
        return '';
    }
    return normaliseThinkingActivityString(capture.text)
        || normaliseThinkingActivityString(capture.preview);
}

function isThinkingLiveLlmDiagnosticEvent(entry) {
    if (!entry || typeof entry !== 'object') {
        return false;
    }
    return Boolean(
        entry.llm_request
        || entry.llm_request_state
        || entry.llm_request_sent_at_utc
        || entry.llm_first_output_at_utc
        || entry.llm_response_preview
    );
}

function buildThinkingLiveLlmCallKey(entry, index) {
    const llmRequest = (entry?.llm_request && typeof entry.llm_request === 'object')
        ? entry.llm_request
        : null;
    const explicitCallId = normaliseThinkingActivityString(
        entry?.call_id || entry?.llm_call_id || llmRequest?.call_id
    );
    if (explicitCallId) {
        return `call:${explicitCallId}`;
    }
    const explicitExchangeId = normaliseThinkingActivityString(
        entry?.llm_exchange_id || llmRequest?.llm_exchange_id
    );
    if (explicitExchangeId) {
        return `exchange:${explicitExchangeId}`;
    }

    const stage = normaliseThinkingActivityString(entry?.workflow_stage_id)
        || normaliseThinkingActivityString(entry?.stage)
        || normaliseThinkingActivityString(entry?.phase)
        || 'unscoped';
    const model = normaliseThinkingActivityString(entry?.model) || 'unknown_model';
    const provider = normaliseThinkingActivityString(entry?.provider) || 'unknown_provider';
    const attemptNo = Number.isFinite(entry?.fallback_attempt_no)
        ? Number(entry.fallback_attempt_no)
        : index;
    const preparedAt = normaliseThinkingActivityString(entry?.llm_request_prepared_at_utc)
        || normaliseThinkingActivityString(entry?.llm_request_sent_at_utc)
        || normaliseThinkingActivityString(entry?.at_utc)
        || String(index);
    return [stage, provider, model, attemptNo, preparedAt].join('::');
}

function mergeThinkingLiveLlmCallEvent(existing, entry, index) {
    const llmRequest = (entry?.llm_request && typeof entry.llm_request === 'object')
        ? entry.llm_request
        : null;
    const explicitCallId = normaliseThinkingActivityString(
        entry?.call_id || entry?.llm_call_id || llmRequest?.call_id
    );
    const explicitExchangeId = normaliseThinkingActivityString(
        entry?.llm_exchange_id || llmRequest?.llm_exchange_id
    );
    const promptCapture = normaliseThinkingDiagnosticCapture(
        entry?.prompt_preview || entry?.llm_prompt_preview || llmRequest?.prompt
    );
    const responseCapture = normaliseThinkingDiagnosticCapture(
        entry?.response_preview || entry?.llm_response_preview
    );
    const state = normaliseThinkingActivityString(entry?.llm_request_state)
        || normaliseThinkingActivityString(entry?.request_state)
        || normaliseThinkingActivityString(entry?.status);
    const sentAt = normaliseThinkingActivityString(entry?.llm_request_sent_at_utc);
    const firstOutputAt = normaliseThinkingActivityString(entry?.llm_first_output_at_utc);
    const completedAt = state.toLowerCase() === 'completed'
        ? normaliseThinkingActivityString(entry?.at_utc)
        : '';
    const atUtc = firstOutputAt
        || completedAt
        || sentAt
        || normaliseThinkingActivityString(entry?.llm_request_prepared_at_utc)
        || normaliseThinkingActivityString(entry?.at_utc);

    const promptText = captureTextForThinkingLlmCallLog(promptCapture);
    const responseText = captureTextForThinkingLlmCallLog(responseCapture);
    const promptCharCount = toThinkingCardOptionalNonNegativeInteger(promptCapture?.char_count)
        || (promptText ? promptText.length : null);
    const sequenceNo = Number.isFinite(entry?.sequence_no)
        ? Number(entry.sequence_no)
        : (Number.isFinite(existing?.sequence_no) ? Number(existing.sequence_no) : index + 1);
    const incomingIdentitySource = normaliseThinkingActivityString(entry?.model_identity_source);
    const existingIdentitySource = normaliseThinkingActivityString(existing?.model_identity_source);
    const effectiveModel = incomingIdentitySource === 'provider_response'
        ? normaliseThinkingActivityString(entry?.effective_model)
        : (existingIdentitySource === 'provider_response'
            ? normaliseThinkingActivityString(existing?.effective_model)
            : '');

    return {
        call_id: explicitCallId || existing?.call_id || '',
        llm_exchange_id: explicitExchangeId || existing?.llm_exchange_id || '',
        sequence_no: sequenceNo,
        stage: normaliseThinkingActivityString(entry?.workflow_stage_id)
            || normaliseThinkingActivityString(entry?.stage)
            || normaliseThinkingActivityString(entry?.phase)
            || existing?.stage
            || 'unscoped',
        call_type: 'live_llm_call',
        model: normaliseThinkingActivityString(entry?.model)
            || normaliseThinkingActivityString(entry?.selected_model)
            || existing?.model
            || 'unknown model',
        requested_model: normaliseThinkingActivityString(entry?.requested_model)
            || existing?.requested_model
            || '',
        selected_model: normaliseThinkingActivityString(entry?.selected_model)
            || existing?.selected_model
            || '',
        effective_model: effectiveModel,
        model_identity_source: incomingIdentitySource || existingIdentitySource || '',
        provider: normaliseThinkingActivityString(entry?.provider)
            || normaliseThinkingActivityString(entry?.selected_provider)
            || existing?.provider
            || '',
        at_utc: atUtc || existing?.at_utc || '',
        started_at_utc: sentAt || existing?.started_at_utc || '',
        completed_at_utc: completedAt || firstOutputAt || existing?.completed_at_utc || '',
        duration_ms: Number.isFinite(entry?.duration_ms)
            ? Math.max(0, Number(entry.duration_ms))
            : (Number.isFinite(existing?.duration_ms) ? Number(existing.duration_ms) : null),
        prompt_char_count: promptCharCount !== null
            ? promptCharCount
            : (Number.isFinite(existing?.prompt_char_count) ? Number(existing.prompt_char_count) : null),
        live_state: state || existing?.live_state || '',
        prompt: promptText
            ? {
                text: promptText,
                is_truncated: promptCapture?.preview_truncated === true,
                char_count: promptCharCount
            }
            : (existing?.prompt || null),
        response: responseText
            ? {
                text: responseText,
                is_truncated: responseCapture?.preview_truncated === true
            }
            : (existing?.response || null),
        usage: entry?.usage && typeof entry.usage === 'object'
            ? { ...entry.usage }
            : (existing?.usage || null),
        unavailable_reason: responseText
            ? ''
            : (state.toLowerCase() === 'sent'
                ? 'response pending'
                : (existing?.unavailable_reason || 'response not recorded yet'))
    };
}

function collectThinkingLiveLlmCallLogEntries(request) {
    const diagnosticEvents = getThinkingDiagnosticEvents(request);
    if (diagnosticEvents.length === 0) {
        return [];
    }

    const byKey = new Map();
    for (const [index, entry] of diagnosticEvents.entries()) {
        if (!isThinkingLiveLlmDiagnosticEvent(entry)) {
            continue;
        }
        const key = buildThinkingLiveLlmCallKey(entry, index);
        byKey.set(key, mergeThinkingLiveLlmCallEvent(byKey.get(key), entry, index));
    }

    return Array.from(byKey.values())
        .filter((entry) => entry.prompt || entry.response || entry.live_state)
        .sort((left, right) => {
            const leftAt = Date.parse(left.at_utc || left.started_at_utc || '');
            const rightAt = Date.parse(right.at_utc || right.started_at_utc || '');
            if (Number.isNaN(leftAt) || Number.isNaN(rightAt) || leftAt === rightAt) {
                return Number(left.sequence_no || 0) - Number(right.sequence_no || 0);
            }
            return leftAt - rightAt;
        });
}

function cloneThinkingLlmCallLogEntry(entry) {
    if (!entry || typeof entry !== 'object') {
        return null;
    }
    return {
        ...entry,
        prompt: entry.prompt && typeof entry.prompt === 'object' ? { ...entry.prompt } : entry.prompt,
        response: entry.response && typeof entry.response === 'object' ? { ...entry.response } : entry.response,
        usage: entry.usage && typeof entry.usage === 'object' ? { ...entry.usage } : entry.usage
    };
}

function buildThinkingLlmCallLogEntryKey(entry, index = null) {
    const explicitCallId = normaliseThinkingActivityString(
        entry?.call_id || entry?.llm_call_id
    );
    if (explicitCallId) {
        return buildThinkingDiagnosticKey('llm_exchange', 'call', explicitCallId);
    }
    const explicitExchangeId = normaliseThinkingActivityString(entry?.llm_exchange_id);
    if (explicitExchangeId) {
        return buildThinkingDiagnosticKey('llm_exchange', 'exchange', explicitExchangeId);
    }

    if (Number.isFinite(entry?.sequence_no)) {
        return buildThinkingDiagnosticKey('llm_exchange', 'seq', Number(entry.sequence_no));
    }

    const stage = normaliseThinkingActivityString(entry?.stage) || 'unscoped';
    const callType = normaliseThinkingActivityString(entry?.call_type) || 'llm_call';
    const model = normaliseThinkingActivityString(entry?.model) || 'unknown_model';
    const provider = normaliseThinkingActivityString(entry?.provider) || 'unknown_provider';
    const timestamp = normaliseThinkingActivityString(entry?.completed_at_utc)
        || normaliseThinkingActivityString(entry?.started_at_utc)
        || normaliseThinkingActivityString(entry?.at_utc);
    return buildThinkingDiagnosticKey(
        'llm_exchange',
        stage,
        callType,
        provider,
        model,
        timestamp || (Number.isFinite(index) ? Number(index) : 'unknown')
    );
}

function rememberThinkingLlmCallLogEntries(state, entries) {
    const cache = ensureThinkingLlmCallLogEntryCache(state);
    if (!cache || !Array.isArray(entries)) {
        return;
    }
    entries.forEach((entry, index) => {
        const key = buildThinkingLlmCallLogEntryKey(entry, index);
        const copy = cloneThinkingLlmCallLogEntry(entry);
        if (key && copy) {
            cache.set(key, copy);
        }
    });
}

function collectCachedExpandedThinkingLlmCallLogEntries(request, state, visibleEntries) {
    const cache = ensureThinkingLlmCallLogEntryCache(state);
    if (!cache || cache.size === 0 || !request || typeof request !== 'object') {
        return [];
    }

    const expandedKeys = ensureThinkingDiagnosticExpansionState(request);
    if (!(expandedKeys instanceof Set) || expandedKeys.size === 0) {
        return [];
    }

    const visibleKeys = new Set(
        (Array.isArray(visibleEntries) ? visibleEntries : [])
            .map((entry, index) => buildThinkingLlmCallLogEntryKey(entry, index))
            .filter(Boolean)
    );
    const cachedEntries = [];
    expandedKeys.forEach((key) => {
        if (!cache.has(key) || visibleKeys.has(key)) {
            return;
        }
        const entry = cloneThinkingLlmCallLogEntry(cache.get(key));
        if (entry) {
            cachedEntries.push(entry);
        }
    });
    return cachedEntries;
}

function combineThinkingLlmCallLogEntries(liveEntries, archivedEntries, archiveLoaded) {
    const live = Array.isArray(liveEntries) ? liveEntries : [];
    const archived = Array.isArray(archivedEntries) ? archivedEntries : [];
    if (!archiveLoaded) {
        return live;
    }
    if (live.length === 0) {
        return archived;
    }

    const archivedKeys = new Set(archived.map((entry) => [
        normaliseThinkingActivityString(entry?.stage),
        normaliseThinkingActivityString(entry?.model),
        normaliseThinkingActivityString(entry?.provider),
        normaliseThinkingActivityString(entry?.started_at_utc)
            || normaliseThinkingActivityString(entry?.at_utc)
    ].join('::')));
    const pendingLive = live.filter((entry) => {
        if (entry?.response) {
            return false;
        }
        const key = [
            normaliseThinkingActivityString(entry?.stage),
            normaliseThinkingActivityString(entry?.model),
            normaliseThinkingActivityString(entry?.provider),
            normaliseThinkingActivityString(entry?.started_at_utc)
                || normaliseThinkingActivityString(entry?.at_utc)
        ].join('::');
        return !archivedKeys.has(key);
    });
    return [...archived, ...pendingLive];
}

function classifyThinkingLlmCallLogEntry(entry) {
    const source = normaliseThinkingActivityString(entry?.source).toLowerCase();
    const stage = normaliseThinkingActivityString(entry?.stage).toLowerCase();
    const workflowStageId = normaliseThinkingActivityString(entry?.workflow_stage_id).toLowerCase();
    const callType = normaliseThinkingActivityString(entry?.call_type).toLowerCase();
    const fields = [source, stage, workflowStageId, callType].filter(Boolean);

    if (fields.some((field) => field.includes('buttonify') || field.includes('quick_reply') || field.includes('quick-reply'))) {
        return 'Auxiliary UI quick replies';
    }
    if (source.includes('aux_llm_calls') || fields.some((field) => field.includes('auxiliary'))) {
        return 'Auxiliary LLM';
    }
    if (fields.some((field) => field.includes('selector'))) {
        return 'Selector LLM';
    }
    if (fields.some((field) => field.includes('final_answer') || field.includes('answer_synthesis') || field.includes('response_final'))) {
        return 'Answer LLM';
    }
    if (fields.some((field) => field.includes('workflow'))) {
        return 'Workflow LLM';
    }
    return '';
}

function thinkingLlmCallUsageCostBits(entry) {
    const usage = entry?.usage && typeof entry.usage === 'object' ? entry.usage : {};
    const inputTokens = thinkingUsageNumber(usage.input_tokens) ?? thinkingUsageNumber(usage.known_input_tokens);
    const outputTokens = thinkingUsageNumber(usage.output_tokens) ?? thinkingUsageNumber(usage.known_output_tokens);
    const totalTokens = thinkingUsageNumber(usage.total_tokens) ?? thinkingUsageNumber(usage.known_total_tokens);
    return [
        formatThinkingTokenCount(inputTokens, 'input'),
        formatThinkingTokenCount(outputTokens, 'output'),
        (inputTokens === null && outputTokens === null) ? formatThinkingTokenCount(totalTokens, 'tokens') : ''
    ].filter(Boolean);
}

function renderThinkingLlmModelLineageHTML(entry) {
    const requested = normaliseThinkingActivityString(entry?.requested_model);
    const selected = normaliseThinkingActivityString(entry?.selected_model);
    const effective = normaliseThinkingActivityString(entry?.model_identity_source) === 'provider_response'
        ? normaliseThinkingActivityString(entry?.effective_model)
        : '';
    const lineageBits = [
        requested ? `requested ${requested}` : '',
        selected && selected !== requested ? `selected ${selected}` : '',
        effective && effective !== selected && effective !== requested ? `effective ${effective}` : ''
    ].filter(Boolean);
    return lineageBits.length > 1
        ? `<div class="thinking-card-diagnostic-text">Model lineage: ${escapeHtml(lineageBits.join(' · '))}</div>`
        : '';
}

function renderThinkingLlmCallLogEntriesHTML(entries, options = {}) {
    if (!Array.isArray(entries) || entries.length === 0) {
        return '<div class="thinking-card-diagnostic-text">No LLM exchanges were recorded for this turn.</div>';
    }

    return entries.map((entry, index) => {
        const diagnosticKey = buildThinkingLlmCallLogEntryKey(entry, index);
        const seq = Number.isFinite(entry?.sequence_no) ? Number(entry.sequence_no) : null;
        const stage = normaliseThinkingActivityString(entry?.stage) || 'unscoped';
        const callType = normaliseThinkingActivityString(entry?.call_type) || 'llm_call';
        const roleLabel = classifyThinkingLlmCallLogEntry(entry);
        const model = normaliseThinkingActivityString(entry?.model) || 'unknown model';
        const provider = normaliseThinkingActivityString(entry?.provider);
        const liveState = formatThinkingLlmRequestState(entry?.live_state);
        const promptText = normaliseThinkingActivityString(entry?.prompt?.text);
        const responseText = normaliseThinkingActivityString(entry?.response?.text);
        const promptTruncated = entry?.prompt?.is_truncated === true;
        const responseTruncated = entry?.response?.is_truncated === true;
        const promptCharCount = getThinkingLlmPromptCharCount(entry);
        const promptSizeCue = (
            options?.showLargeInputCue === true
            && promptCharCount !== null
            && promptCharCount >= THINKING_LARGE_LLM_PROMPT_CHAR_THRESHOLD
        )
            ? `large input ${promptCharCount.toLocaleString()} chars`
            : '';
        const unavailableReason = normaliseThinkingActivityString(entry?.unavailable_reason);
        const durationMs = Number.isFinite(entry?.duration_ms) ? Math.max(0, Number(entry.duration_ms)) : null;
        const atUtc = normaliseThinkingActivityString(entry?.at_utc)
            || normaliseThinkingActivityString(entry?.completed_at_utc)
            || normaliseThinkingActivityString(entry?.started_at_utc);
        const timestampLabel = formatThinkingLlmCallTimestamp(atUtc);
        const usageCostBits = thinkingLlmCallUsageCostBits(entry);

        const headerBits = [
            seq !== null ? `#${seq}` : '',
            timestampLabel,
            roleLabel,
            formatThinkingActivityFallbackLabel(stage),
            formatThinkingActivityFallbackLabel(callType),
            liveState,
            provider ? `${model} (${provider})` : model,
            ...usageCostBits,
            promptSizeCue,
            durationMs !== null ? `${durationMs}ms` : ''
        ].filter(Boolean);

        const promptMetaBits = [
            promptCharCount !== null ? `${promptCharCount.toLocaleString()} chars` : '',
            promptTruncated ? 'truncated' : ''
        ].filter(Boolean);
        const promptMeta = promptMetaBits.length > 0 ? ` (${promptMetaBits.join(', ')})` : '';
        const responseMeta = responseTruncated ? ' (truncated)' : '';
        const archiveLoadButton = (
            options?.canLoadArchive === true
            && options?.archiveLoaded !== true
            && liveState.toLowerCase() !== 'sent'
        )
            ? '<button type="button" class="btn thinking-card-action" data-thinking-action="llm-call-log-toggle">Load archived exchange details</button>'
            : '';
        const availability = (!promptText || !responseText)
            ? `<div class="thinking-card-diagnostic-text">Missing exchange detail: ${escapeHtml(unavailableReason || 'not recorded')}</div>${archiveLoadButton}`
            : '';

        const promptBlock = promptText
            ? `<div class="thinking-card-diagnostic-section-title">Prompt${promptMeta}</div><pre class="thinking-card-diagnostic-pre"><code>${escapeHtml(promptText)}</code></pre>`
            : '';
        const responseBlock = responseText
            ? `<div class="thinking-card-diagnostic-section-title">Response${responseMeta}</div><pre class="thinking-card-diagnostic-pre"><code>${escapeHtml(responseText)}</code></pre>`
            : '';

        return `<details class="thinking-card-diagnostic" data-thinking-diagnostic-key="${escapeHtml(diagnosticKey)}" data-thinking-llm-call-log-key="${escapeHtml(diagnosticKey)}" data-thinking-llm-call-at-utc="${escapeHtml(atUtc || '')}" data-thinking-llm-call-model="${escapeHtml(model)}">
            <summary>${escapeHtml(headerBits.join(' · '))}</summary>
            <div class="thinking-card-diagnostic-content">
                ${renderThinkingLlmModelLineageHTML(entry)}
                ${promptBlock}
                ${responseBlock}
                ${availability}
            </div>
        </details>`;
    }).join('');
}

function renderThinkingLlmCallLogSectionHTML(request, mode = THINKING_CARD_MODE_DEFAULT) {
    const renderMode = normaliseThinkingCardMode(mode);

    const requestId = resolveThinkingRequestIdForLlmCallLog(request);
    if (!requestId) {
        return '';
    }

    const state = ensureThinkingLlmCallLogState(request);
    if (!state) {
        return '';
    }

    const buttonLabel = state.loaded ? 'Refresh full LLM call log' : 'View full LLM call log';
    const loadButton = `<button type="button" class="btn thinking-card-action" data-thinking-action="llm-call-log-toggle">${escapeHtml(buttonLabel)}</button>`;
    const liveEntries = collectThinkingLiveLlmCallLogEntries(request);
    const baseVisibleEntries = combineThinkingLlmCallLogEntries(liveEntries, state.entries, state.loaded);
    rememberThinkingLlmCallLogEntries(state, baseVisibleEntries);
    const cachedExpandedEntries = collectCachedExpandedThinkingLlmCallLogEntries(request, state, baseVisibleEntries);
    const visibleEntries = [...baseVisibleEntries, ...cachedExpandedEntries];
    const hasVisibleEntries = visibleEntries.length > 0;

    const statusLine = state.loading
        ? '<div class="thinking-card-diagnostic-text">Loading full LLM call log...</div>'
        : (normaliseThinkingActivityString(state.error)
            ? `<div class="thinking-card-diagnostic-text">${escapeHtml(state.error)}</div>`
            : '');

    const cachedExpandedLine = (!state.loaded && liveEntries.length === 0 && cachedExpandedEntries.length > 0)
        ? '<div class="thinking-card-diagnostic-text">Keeping previously expanded LLM exchange details visible while live events refresh.</div>'
        : '';

    const liveLine = (!state.loaded && !state.loading && !normaliseThinkingActivityString(state.error) && liveEntries.length > 0)
        ? '<div class="thinking-card-diagnostic-text">Showing live LLM events currently loaded. Lifecycle events with a shared call ID are grouped into one exchange. View the archived call log for completed exchanges to load prompt and response bodies.</div>'
        : '';

    const unloadedLine = (!state.loaded && !state.loading && !normaliseThinkingActivityString(state.error) && !hasVisibleEntries)
        ? '<div class="thinking-card-diagnostic-text">No live LLM events are currently loaded. View the archived call log for completed exchanges; timing and auxiliary summaries shown above may come from other telemetry.</div>'
        : '';

    const countLine = Number.isFinite(state.totalCount)
        ? `<div class="thinking-card-diagnostic-text">Showing ${escapeHtml(String((state.entries || []).length))} of ${escapeHtml(String(state.totalCount))} exchanges.</div>`
        : '';

    const entriesHtml = (state.loaded || liveEntries.length > 0 || cachedExpandedEntries.length > 0)
        ? renderThinkingLlmCallLogEntriesHTML(visibleEntries, {
            archiveLoaded: state.loaded,
            canLoadArchive: true,
            showLargeInputCue: renderMode !== THINKING_CARD_MODE_DEFAULT
        })
        : '';

    const loadMoreButton = state.loaded && state.hasMore
        ? '<button type="button" class="btn thinking-card-action" data-thinking-action="llm-call-log-more">Load more</button>'
        : '';

    return `<section class="thinking-card-diagnostic-section thinking-card-llm-call-log">
        <div class="thinking-card-diagnostic-section-title">Every LLM interaction (timestamped)</div>
        <div class="thinking-card-diagnostic-actions">${loadButton}${loadMoreButton}</div>
        ${countLine}
        ${statusLine}
        ${liveLine}
        ${cachedExpandedLine}
        ${unloadedLine}
        ${entriesHtml}
    </section>`;
}

async function loadThinkingLlmCallLog(request, options = {}) {
    if (!request || typeof request !== 'object') {
        return false;
    }
    const requestId = resolveThinkingRequestIdForLlmCallLog(request);
    if (!requestId) {
        return false;
    }

    const state = ensureThinkingLlmCallLogState(request);
    if (!state || state.loading) {
        return false;
    }

    const append = options.append === true;
    const pageSize = Number.isFinite(options.pageSize)
        ? Math.max(1, Math.min(200, Number(options.pageSize)))
        : THINKING_LLM_CALL_LOG_PAGE_SIZE;
    const nextOffset = append
        ? (Number.isFinite(state.nextOffset) ? Number(state.nextOffset) : (Array.isArray(state.entries) ? state.entries.length : 0))
        : 0;

    state.loading = true;
    state.error = '';
    refreshThinkingCardProgressUi(request);

    try {
        const params = new URLSearchParams();
        params.set('request_id', requestId);
        params.set('offset', String(nextOffset));
        params.set('limit', String(pageSize));

        const response = await fetch(`${THINKING_LLM_CALL_LOG_ENDPOINT}?${params.toString()}`, {
            method: 'GET',
            headers: {
                Accept: 'application/json',
                ...buildChatFetchHeaders()
            },
            cache: 'no-store'
        });
        const body = await response.json().catch(() => ({}));
        if (!response.ok || body?.success !== true) {
            throw new Error(
                normaliseThinkingActivityString(body?.error)
                || normaliseThinkingActivityString(body?.message)
                || `Failed with status ${response.status}`
            );
        }

        const incomingEntries = Array.isArray(body.entries) ? body.entries : [];
        state.entries = append
            ? [...(Array.isArray(state.entries) ? state.entries : []), ...incomingEntries]
            : incomingEntries;
        state.totalCount = Number.isFinite(body.total_count) ? Number(body.total_count) : state.entries.length;
        state.nextOffset = Number.isFinite(body.next_offset) ? Number(body.next_offset) : state.entries.length;
        state.hasMore = body.has_more === true;
        state.loaded = true;
        state.requestId = requestId;
    } catch (error) {
        const message = normaliseThinkingActivityString(error?.message || error);
        state.error = message || 'Failed to load LLM call log.';
    } finally {
        state.loading = false;
        refreshThinkingCardProgressUi(request);
    }
    return state.loaded;
}

function renderThinkingLatestProgressSummaryHTML(request) {
    const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    if (!latestProgress) {
        return '';
    }
    const workflowDiscovery = (request?.workflowDiscovery && typeof request.workflowDiscovery === 'object')
        ? request.workflowDiscovery
        : null;
    const routingNarrative = buildWorkflowRoutingNarrative(latestProgress, workflowDiscovery, {
        includeNoMatchTransition: true,
    });

    const label = normaliseThinkingActivityString(latestProgress.phase_label)
        || normaliseThinkingActivityString(latestProgress.stage_label)
        || formatThinkingActivityFallbackLabel(
            normaliseThinkingActivityString(latestProgress.phase)
                || normaliseThinkingActivityString(latestProgress.stage)
        )
        || 'Current status';
    const detail = normaliseThinkingActivityString(latestProgress.result_summary)
        || normaliseThinkingActivityString(latestProgress.subtask)
        || routingNarrative.text
        || normaliseThinkingActivityString(latestProgress.pending_reason);
    if (!label && !detail) {
        return '';
    }

    return renderThinkingDiagnosticRowHTML({
        label,
        detail,
        detailHtml: routingNarrative.text === detail ? routingNarrative.html : '',
        state: isTerminalThinkingProgress(latestProgress) ? 'success' : 'pending'
    }, 'thinking-card-tool thinking-card-activity');
}

function getThinkingRequestElapsedMs(request) {
    if (!request || !Number.isFinite(request.thinkingStartedAtMs)) {
        return null;
    }
    return Math.max(0, Date.now() - Number(request.thinkingStartedAtMs));
}

function isClientInitialThinkingProgress(progress) {
    return normaliseThinkingActivityString(progress?.pending_reason) === 'client_request_setup';
}

function buildInitialThinkingProgressPlaceholder(requestId) {
    const progress = {
        status: 'pending',
        phase: 'context_build',
        stage: 'context_build',
        phase_label: 'Preparing response',
        stage_label: 'Build context',
        liveness_state: THINKING_STATUS_ACTIVE,
        pending_reason: 'client_request_setup',
        subtask: 'request setup',
        result_summary: 'Submitting your turn and preparing live progress updates.'
    };
    if (typeof requestId === 'string' && requestId.trim()) {
        progress.request_id = requestId.trim();
    }
    return progress;
}

function buildPendingThinkingProgressFallback(statusCode, requestId, payload = null) {
    const fallback = (payload && typeof payload === 'object') ? { ...payload } : {};
    if (!normaliseThinkingActivityString(fallback.status)) {
        fallback.status = 'pending';
    }
    if (!normaliseThinkingActivityString(fallback.phase)) {
        fallback.phase = 'context_build';
    }
    if (!normaliseThinkingActivityString(fallback.stage)) {
        fallback.stage = fallback.phase;
    }
    if (!normaliseThinkingActivityString(fallback.phase_label)) {
        fallback.phase_label = 'Preparing response';
    }
    if (!normaliseThinkingActivityString(fallback.stage_label)) {
        fallback.stage_label = 'Build context';
    }
    if (!normaliseThinkingActivityString(fallback.liveness_state)) {
        fallback.liveness_state = THINKING_STATUS_WAITING;
    }
    if (!normaliseThinkingActivityString(fallback.request_id) && requestId) {
        fallback.request_id = requestId;
    }
    if (!normaliseThinkingActivityString(fallback.pending_reason)) {
        fallback.pending_reason = statusCode === 404
            ? 'request_progress_not_found'
            : 'no_visible_progress_state';
    }
    if (!normaliseThinkingActivityString(fallback.subtask)) {
        fallback.subtask = 'request setup';
    }
    if (!normaliseThinkingActivityString(fallback.result_summary)) {
        fallback.result_summary = statusCode === 404
            ? 'The turn has started, but live progress is not visible yet. Von will keep checking automatically.'
            : 'Von is setting up this turn. Live progress updates will appear automatically when ready.';
    }
    return fallback;
}

function shouldSurfaceThinkingProgressTimeoutFallback(request, poll) {
    const latestProgress = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    if (latestProgress && !isClientInitialThinkingProgress(latestProgress)) {
        return true;
    }

    const consecutiveTimeouts = Number.isFinite(poll?.consecutiveTimeouts)
        ? Math.max(0, Math.round(Number(poll.consecutiveTimeouts)))
        : 0;
    if (consecutiveTimeouts >= THINKING_PROGRESS_TIMEOUTS_BEFORE_VISIBLE) {
        return true;
    }

    const elapsedMs = getThinkingRequestElapsedMs(request);
    return elapsedMs !== null && elapsedMs >= THINKING_PROGRESS_TIMEOUT_VISIBLE_AFTER_MS;
}

function buildProgressPollTimeoutFallback(request, requestId) {
    const current = (request?.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const currentPhase = normaliseThinkingActivityString(current?.phase);
    const currentStage = normaliseThinkingActivityString(current?.stage);
    const currentPhaseLabel = normaliseThinkingActivityString(current?.phase_label);
    const currentStageLabel = normaliseThinkingActivityString(current?.stage_label);
    const currentSubtask = normaliseThinkingActivityString(current?.subtask);
    const currentPendingReason = normaliseThinkingActivityString(current?.pending_reason);
    const elapsedMs = getThinkingRequestElapsedMs(request);
    const usesClientInitialPlaceholder = !current || isClientInitialThinkingProgress(current);

    return buildPendingThinkingProgressFallback(202, requestId, {
        ...(current && typeof current === 'object' ? current : {}),
        status: 'pending',
        phase: currentPhase || 'context_build',
        stage: currentStage || currentPhase || 'context_build',
        phase_label: usesClientInitialPlaceholder
            ? 'Still preparing response'
            : (currentPhaseLabel || 'Live progress delayed'),
        stage_label: currentStageLabel || 'Build context',
        liveness_state: THINKING_STATUS_WAITING,
        pending_reason: currentPendingReason === 'client_request_setup'
            ? 'progress_poll_timeout'
            : (currentPendingReason || 'progress_poll_timeout'),
        subtask: currentSubtask || (usesClientInitialPlaceholder ? 'request setup' : 'live progress'),
        result_summary: elapsedMs !== null && elapsedMs >= (THINKING_PROGRESS_TIMEOUT_VISIBLE_AFTER_MS * 2)
            ? 'Von is still working. Live progress updates remain delayed, and the interface will keep retrying automatically.'
            : 'Von is still working. Live progress updates have not arrived yet, so the interface will keep retrying automatically.'
    });
}

/**
 * Legacy function - redirects to renderToolHistoryHTML.
 * Returns empty string for backwards compatibility with tooltip usage.
 */
function formatToolUseHistoryTooltip(_request) {
    // For backwards compatibility, this can still return plain text for tooltips
    // But the primary display now uses renderToolHistoryHTML
    return '';
}

function stopToolUseProgressPolling(request) {
    if (!request) {
        return;
    }

    const poll = request.toolUseProgressPoll;
    if (!poll) {
        return;
    }

    request.toolUseProgressPoll = null;

    try {
        if (poll.intervalId) {
            clearInterval(poll.intervalId);
        }
    } catch (_) {
        // Ignore.
    }

    try {
        if (poll.timeoutId) {
            clearTimeout(poll.timeoutId);
        }
    } catch (_) {
        // Ignore.
    }

    try {
        poll.abortController?.abort();
    } catch (_) {
        // Ignore.
    }
}

function stopThinkingTooltipTicker(request) {
    if (!request) {
        return;
    }

    try {
        if (request.thinkingTooltipIntervalId) {
            clearInterval(request.thinkingTooltipIntervalId);
        }
    } catch (_) {
        // Ignore.
    }

    request.thinkingTooltipIntervalId = null;
}

function startThinkingTooltipTicker(request) {
    if (!request || request.aborted) {
        return;
    }

    stopThinkingTooltipTicker(request);

    // Update once per second so the elapsed time stays current,
    // even if tool-progress polling backs off (e.g., repeated 404s).
    request.thinkingTooltipIntervalId = setInterval(() => {
        if (request.aborted || !isLiveChatRequest(request)) {
            stopThinkingTooltipTicker(request);
            return;
        }
        if (isRequestInActiveChatSession(request)) {
            setLoadingIndicatorDetailHtml(renderThinkingCardBodyHTML(request));
            updateThinkingCardMeta(request, request.latestProgress || null);
        }
    }, 1000);
}

function startToolUseProgressPolling(request) {
    if (!request || request.aborted) {
        return;
    }

    if (!showToolUseDuringThinkingSetting) {
        return;
    }

    const requestId = request.clientRequestId;
    if (!requestId) {
        return;
    }

    stopToolUseProgressPolling(request);
    const abortController = new AbortController();

    const poll = {
        abortController,
        timeoutId: null,
        intervalId: null,
        nextDelayMs: 350,
        consecutiveNotFound: 0,
        consecutiveTimeouts: 0
    };

    const scheduleNextPoll = (delayMs) => {
        if (request.aborted || !isLiveChatRequest(request)) {
            return;
        }
        poll.timeoutId = setTimeout(() => {
            void pollOnce();
        }, Math.max(0, Number(delayMs) || 0));
    };

    const pollOnce = async () => {
        if (request.aborted || !isLiveChatRequest(request)) {
            return;
        }

        // Keep detail text "alive" even before the server has any tool-progress state.
        if (isRequestInActiveChatSession(request)) {
            setLoadingIndicatorDetailHtml(renderThinkingCardBodyHTML(request));
            updateThinkingCardMeta(request, request.latestProgress || null);
        }

        try {
            const resp = await fetchWithTimeout(`/von/progress/${encodeURIComponent(requestId)}`,
                {
                    method: 'GET',
                    signal: poll.abortController?.signal,
                    // Progress is an authenticated actor/org read. The legacy
                    // identity header is intentionally omitted: it is neither
                    // authentication nor namespace authority.
                    headers: buildChatFetchHeaders({}, { includeLegacyUserHeader: false }),
                    credentials: 'same-origin',
                    timeoutMs: THINKING_PROGRESS_POLL_FETCH_TIMEOUT_MS
                });
            if (!resp) {
                scheduleNextPoll(Math.min(5000, poll.nextDelayMs * 1.7));
                poll.nextDelayMs = Math.min(5000, poll.nextDelayMs * 1.7);
                return;
            }

            if (resp.status === 404) {
                poll.consecutiveNotFound += 1;
                poll.consecutiveTimeouts = 0;
                let progressPayload = null;
                try {
                    progressPayload = await resp.json();
                } catch (_) {
                    progressPayload = null;
                }
                applyThinkingProgressUpdate(request, buildPendingThinkingProgressFallback(
                    404,
                    requestId,
                    progressPayload
                ));
                refreshThinkingCardProgressUi(request);
                if (isTerminalThinkingProgress(request.latestProgress)) {
                    stopToolUseProgressPolling(request);
                    return;
                }
                poll.nextDelayMs = Math.min(10_000, poll.nextDelayMs * 1.7);
                scheduleNextPoll(poll.nextDelayMs);
                return;
            }

            if (resp.status === 202) {
                poll.consecutiveNotFound = 0;
                poll.consecutiveTimeouts = 0;
                let progressPayload = null;
                try {
                    progressPayload = await resp.json();
                } catch (_) {
                    progressPayload = null;
                }
                applyThinkingProgressUpdate(request, buildPendingThinkingProgressFallback(
                    202,
                    requestId,
                    progressPayload
                ));
                refreshThinkingCardProgressUi(request);
                if (isTerminalThinkingProgress(request.latestProgress)) {
                    stopToolUseProgressPolling(request);
                    return;
                }
                poll.nextDelayMs = Math.min(5000, poll.nextDelayMs * 1.4);
                scheduleNextPoll(poll.nextDelayMs);
                return;
            }

            if (!resp.ok) {
                poll.consecutiveTimeouts = 0;
                poll.nextDelayMs = Math.min(5000, poll.nextDelayMs * 1.7);
                scheduleNextPoll(poll.nextDelayMs);
                return;
            }
            const progress = await resp.json();
            const acceptedProgress = applyThinkingProgressUpdate(request, progress);
            if (!acceptedProgress) {
                refreshThinkingCardProgressUi(request);
                if (isTerminalThinkingProgress(request.latestProgress)) {
                    stopToolUseProgressPolling(request);
                    return;
                }
                scheduleNextPoll(poll.nextDelayMs);
                return;
            }
            syncThinkingCanonicalHistoriesFromProgress(request, progress);
            if (!Array.isArray(progress?.progress_events)) {
                if (!Array.isArray(request.progressEvents)) {
                    request.progressEvents = [];
                }
                request.progressEvents.push({
                    at_utc: new Date().toISOString(),
                    status: progress?.status || null,
                    stage: progress?.stage || progress?.phase || null,
                    sequence_no: progress?.sequence_no || null,
                    liveness_state: progress?.liveness_state || null,
                    idle_ms: progress?.activity_idle_ms ?? progress?.idle_ms ?? null,
                    subtask: progress?.subtask || progress?.tool || progress?.workflow_task || null
                });
                if (request.progressEvents.length > 60) {
                    request.progressEvents = request.progressEvents.slice(-60);
                }
            }

            poll.consecutiveNotFound = 0;
            poll.consecutiveTimeouts = 0;
            poll.nextDelayMs = 350;
            recordToolUseHistory(request, progress);
            if (!Array.isArray(progress?.activity_history)) {
                request.activityHistory = normaliseThinkingActivityHistory(progress?.diagnostic_events);
                if (request.activityHistory.length > 80) {
                    request.activityHistory = request.activityHistory.slice(-80);
                }
            }

            if (progress.workflow_stage_path && typeof progress.workflow_stage_path === 'object') {
                request.workflowStagePath = progress.workflow_stage_path;
            }

            // JVNAUTOSCI-1076: Capture workflow discovery from progress,
            // including explicit no-match payloads.
            if (progress.workflow_discovery && typeof progress.workflow_discovery === 'object') {
                request.workflowDiscovery = progress.workflow_discovery;
            }

            refreshThinkingCardProgressUi(request);

            const effectiveProgress = request.latestProgress;
            const status = typeof effectiveProgress?.status === 'string' ? effectiveProgress.status : null;
            if (isTerminalThinkingProgress(effectiveProgress)) {
                stopToolUseProgressPolling(request);
                return;
            }

            if (normaliseThinkingProgressStatusValue(status) === 'disabled') {
                poll.nextDelayMs = 10_000;
                scheduleNextPoll(poll.nextDelayMs);
                return;
            }

            scheduleNextPoll(poll.nextDelayMs);
        } catch (err) {
            if (err && err.name === 'AbortError') {
                if (err.vonTimeout) {
                    poll.consecutiveTimeouts += 1;
                    if (shouldSurfaceThinkingProgressTimeoutFallback(request, poll)) {
                        applyThinkingProgressUpdate(
                            request,
                            buildProgressPollTimeoutFallback(request, requestId)
                        );
                        refreshThinkingCardProgressUi(request);
                        if (isTerminalThinkingProgress(request.latestProgress)) {
                            stopToolUseProgressPolling(request);
                            return;
                        }
                    }
                    poll.nextDelayMs = Math.min(5000, poll.nextDelayMs * 1.7);
                    scheduleNextPoll(poll.nextDelayMs);
                }
                return;
            }

            poll.nextDelayMs = Math.min(5000, poll.nextDelayMs * 1.7);
            scheduleNextPoll(poll.nextDelayMs);
        }
    };

    request.toolUseProgressPoll = poll;

    void pollOnce();
}

function normaliseForegroundTaskResultPayload(payload) {
    if (!payload || typeof payload !== 'object') {
        return null;
    }

    const result = payload.result && typeof payload.result === 'object'
        ? payload.result
        : payload;
    if (!result || typeof result !== 'object') {
        return null;
    }

    if (
        typeof result.response === 'string'
        || typeof result.response_text === 'string'
        || result.presenter_channels
        || result.response_channels
        || result.llm_debug
    ) {
        if (typeof result.response === 'string') {
            return result;
        }
        return {
            ...result,
            response: typeof result.response_text === 'string' ? result.response_text : ''
        };
    }

    return null;
}

function isForegroundTaskStatusTerminal(statusPayload) {
    const status = String(statusPayload?.status || '').trim().toLowerCase();
    return status === 'completed' || status === 'failed' || status === 'cancelled';
}

function stopForegroundTaskResultPolling(request) {
    const poll = request?.foregroundTaskResultPoll;
    if (!poll) {
        return;
    }
    try {
        if (poll.timeoutId) {
            clearTimeout(poll.timeoutId);
        }
    } catch (_) {
        // Ignore.
    }
    try {
        poll.abortController?.abort();
    } catch (_) {
        // Ignore.
    }
    request.foregroundTaskResultPoll = null;
}

function startForegroundTaskResultPolling(request, handlers = {}) {
    if (!request || request.aborted || !request.clientRequestId) {
        return;
    }

    stopForegroundTaskResultPolling(request);

    const requestId = request.clientRequestId;
    const abortController = new AbortController();
    const poll = {
        abortController,
        timeoutId: null,
        // A server-dispatched retry is already running by the time the browser
        // adopts it, so check promptly instead of imposing the foreground
        // generate path's initial grace period.
        nextDelayMs: request.observingServerDispatch === true
            ? 250
            : FOREGROUND_TASK_RESULT_POLL_INITIAL_DELAY_MS,
        delivering: false
    };

    const scheduleNextPoll = (delayMs) => {
        if (
            request.aborted
            || request.foregroundDeliveryCompleted
            || !isLiveChatRequest(request)
        ) {
            return;
        }
        poll.timeoutId = setTimeout(() => {
            void pollOnce();
        }, Math.max(0, Number(delayMs) || 0));
    };

    const fetchJson = async (url) => {
        const resp = await fetchWithTimeout(url, {
            method: 'GET',
            signal: poll.abortController?.signal,
            headers: buildChatFetchHeaders(),
            credentials: 'same-origin',
            timeoutMs: FOREGROUND_TASK_RESULT_POLL_FETCH_TIMEOUT_MS
        });
        if (!resp || typeof resp.json !== 'function') {
            return { resp, payload: null };
        }
        let payload = null;
        try {
            payload = await resp.json();
        } catch (_) {
            // Keep the null payload default.
        }
        return { resp, payload };
    };

    const repairWindowContextIfNeeded = async (resp, payload) => {
        const errorCode = String(payload?.error_code || payload?.error || '').trim();
        if (resp?.status !== 409 || errorCode !== 'window_context_unavailable') {
            return false;
        }
        await repairCurrentWindowOrganisationBinding();
        poll.nextDelayMs = 250;
        scheduleNextPoll(poll.nextDelayMs);
        return true;
    };

    const pollOnce = async () => {
        if (
            poll.delivering
            || request.aborted
            || request.foregroundDeliveryCompleted
            || !isLiveChatRequest(request)
        ) {
            return;
        }

        try {
            const { resp: statusResp, payload: statusPayload } = await fetchJson(
                `/von/api/task/status/${encodeURIComponent(requestId)}`
            );
            if (await repairWindowContextIfNeeded(statusResp, statusPayload)) {
                return;
            }
            if (!statusResp || statusResp.status === 404 || statusResp.status === 409) {
                poll.nextDelayMs = Math.min(
                    FOREGROUND_TASK_RESULT_POLL_MAX_DELAY_MS,
                    poll.nextDelayMs * 1.5
                );
                scheduleNextPoll(poll.nextDelayMs);
                return;
            }
            if (!statusResp.ok || !isForegroundTaskStatusTerminal(statusPayload)) {
                poll.nextDelayMs = Math.min(
                    FOREGROUND_TASK_RESULT_POLL_MAX_DELAY_MS,
                    poll.nextDelayMs * 1.5
                );
                scheduleNextPoll(poll.nextDelayMs);
                return;
            }

            const status = String(statusPayload?.status || '').trim().toLowerCase();
            if (status !== 'completed') {
                poll.delivering = true;
                await handlers.onFailed?.(statusPayload, status);
                return;
            }

            const { resp: resultResp, payload: resultPayload } = await fetchJson(
                `/von/api/task/result/${encodeURIComponent(requestId)}`
            );
            if (await repairWindowContextIfNeeded(resultResp, resultPayload)) {
                return;
            }
            if (!resultResp || resultResp.status === 404 || resultResp.status === 409) {
                poll.nextDelayMs = Math.min(
                    FOREGROUND_TASK_RESULT_POLL_MAX_DELAY_MS,
                    poll.nextDelayMs * 1.5
                );
                scheduleNextPoll(poll.nextDelayMs);
                return;
            }
            if (!resultResp.ok) {
                poll.nextDelayMs = Math.min(
                    FOREGROUND_TASK_RESULT_POLL_MAX_DELAY_MS,
                    poll.nextDelayMs * 1.5
                );
                scheduleNextPoll(poll.nextDelayMs);
                return;
            }

            const generateBody = normaliseForegroundTaskResultPayload(resultPayload);
            if (!generateBody) {
                poll.nextDelayMs = Math.min(
                    FOREGROUND_TASK_RESULT_POLL_MAX_DELAY_MS,
                    poll.nextDelayMs * 1.5
                );
                scheduleNextPoll(poll.nextDelayMs);
                return;
            }

            poll.delivering = true;
            await handlers.onCompleted?.(generateBody, resultPayload, statusPayload);
        } catch (err) {
            if (err && err.name === 'AbortError') {
                return;
            }
            poll.nextDelayMs = Math.min(
                FOREGROUND_TASK_RESULT_POLL_MAX_DELAY_MS,
                poll.nextDelayMs * 1.5
            );
            scheduleNextPoll(poll.nextDelayMs);
        }
    };

    request.foregroundTaskResultPoll = poll;
    if (request.observingServerDispatch === true) {
        void pollOnce();
    } else {
        scheduleNextPoll(poll.nextDelayMs);
    }
}

// Cool-down for failed history talk-track backfills so we do not spam the server.
// Map<turnId, { at: number, error: string }>
const historySpokenBackfillFailures = new Map();
const HISTORY_SPOKEN_BACKFILL_FAILURE_COOLDOWN_MS = 30_000;

function stripMarkdownForSpeech(text) {
    const input = String(text ?? '');
    if (!input.trim()) {
        return '';
    }

    let value = input;

    // Remove fenced code blocks entirely.
    value = value.replace(/```[\s\S]*?```/g, ' ');

    // Replace inline code with its content.
    value = value.replace(/`([^`]+)`/g, '$1');

    // Replace markdown links [text](url) -> text.
    value = value.replace(/\[([^\]]+)\]\([^)]+\)/g, '$1');

    // Remove images ![alt](url) -> alt.
    value = value.replace(/!\[([^\]]*)\]\([^)]+\)/g, '$1');

    // Remove headings/bullets/quotes markers.
    value = value
        .replace(/^\s{0,3}#{1,6}\s+/gm, '')
        .replace(/^\s{0,3}>\s?/gm, '')
        .replace(/^\s*[-*+]\s+/gm, '')
        .replace(/^\s*\d+\.[\s]+/gm, '');

    // Remove emphasis markers.
    value = value.replace(/\*\*([^*]+)\*\*/g, '$1');
    value = value.replace(/\*([^*]+)\*/g, '$1');
    value = value.replace(/__([^_]+)__/g, '$1');
    value = value.replace(/_([^_]+)_/g, '$1');

    // Remove horizontal rules.
    value = value.replace(/^\s*---+\s*$/gm, ' ');

    // Collapse whitespace.
    value = value.replace(/[ \t]+/g, ' ');
    value = value.replace(/\n{3,}/g, '\n\n');
    value = value.trim();

    return value;
}

function deriveNarrationFromScreenText(screenText, options = {}) {
    const cleaned = stripMarkdownForSpeech(screenText);
    if (!cleaned) {
        return '';
    }

    const maxChars = Number.isFinite(options.maxChars) ? options.maxChars : 900;
    if (cleaned.length <= maxChars) {
        return cleaned;
    }

    // Prefer not to cut mid-sentence if possible.
    const slice = cleaned.slice(0, maxChars);
    const lastBreak = Math.max(slice.lastIndexOf('. '), slice.lastIndexOf('? '), slice.lastIndexOf('! '));
    if (lastBreak > 200) {
        return slice.slice(0, lastBreak + 1).trim() + '…';
    }
    return slice.trim() + '…';
}

const LEGACY_CANONICAL_OUTCOME_FORMATS = new Set([
    'effect_outcome_report_v1',
    'effect_finality_fallback_v1'
]);

const LEGACY_CANONICAL_OUTCOME_NARRATIONS = new Map([
    [
        'This turn completed only partially.',
        'I could not complete or confirm every requested change.'
    ],
    [
        'This turn has at least one unresolved effect outcome.',
        'I could not verify every result of the requested work.'
    ],
    [
        'This turn did not complete all requested effects.',
        'I could not complete all of the requested work.'
    ],
    [
        'At least one requested effect was not started.',
        'I could not start all of the requested work.'
    ],
    [
        'The model did not produce a reliable final answer.',
        'I could not produce a fully reliable final answer.'
    ],
    [
        'The model did not produce a usable final answer.',
        'I could not produce a useful final answer.'
    ]
]);

function getLegacyCanonicalOutcomeReportLead(screenText) {
    const screen = typeof screenText === 'string' ? screenText : '';
    const authoritativeScreen = screen.split(
        /\r?\n\r?\n### Model draft \(non-authoritative\)\r?\n\r?\n/,
        1
    )[0];
    const reportLines = authoritativeScreen.replace(/\r\n?/g, '\n').split('\n');
    const firstNonEmptyIndex = reportLines.findIndex((line) => line.trim());
    const headingIsFirst = firstNonEmptyIndex >= 0
        && reportLines[firstNonEmptyIndex].trim() === '## Effect outcome report';
    if (!headingIsFirst) {
        return null;
    }
    const reportLead = (
        reportLines.slice(firstNonEmptyIndex + 1).find((line) => line.trim()) || ''
    ).trim();
    return LEGACY_CANONICAL_OUTCOME_NARRATIONS.has(reportLead)
        ? reportLead
        : null;
}

function deriveLegacyCanonicalOutcomeNarration(screenText) {
    const reportLead = getLegacyCanonicalOutcomeReportLead(screenText);
    const synopsis = reportLead
        ? LEGACY_CANONICAL_OUTCOME_NARRATIONS.get(reportLead)
        : 'This result needs attention.';
    return `${synopsis} See the detailed report on screen.`;
}

function normalisePresenterChannels(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }

    const screen = typeof value.screen === 'string' ? value.screen : null;
    let spoken = typeof value.spoken === 'string' ? value.spoken : null;
    const format = typeof value.format === 'string' ? value.format : null;

    const canonicalReport = Boolean(
        screen
        && (
            LEGACY_CANONICAL_OUTCOME_FORMATS.has(String(format || '').trim())
            || getLegacyCanonicalOutcomeReportLead(screen)
        )
    );
    const spokenLooksLikeCanonicalReport = Boolean(
        spoken && spoken.includes('## Effect outcome report')
    );
    const trustedCurrentCanonicalNarration = (
        String(format || '').trim() === 'effect_outcome_report_v1'
        && spoken
        && !spokenLooksLikeCanonicalReport
        && screen.trim() !== spoken.trim()
    );
    if (
        canonicalReport
        && (
            !trustedCurrentCanonicalNarration
            || String(format || '').trim() === 'effect_finality_fallback_v1'
        )
    ) {
        spoken = deriveLegacyCanonicalOutcomeNarration(screen);
    }

    const hasAny = (screen && screen.trim()) || (spoken && spoken.trim());
    if (!hasAny) {
        return null;
    }

    return {
        screen: screen && screen.trim() ? screen : null,
        spoken: spoken && spoken.trim() ? spoken : null,
        format
    };
}

function normaliseDisplayElementsContract(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }

    if (value.schema_version !== 'turn_display_elements_v1') {
        return null;
    }

    if (!Array.isArray(value.elements)) {
        return null;
    }

    return value;
}

function extractPresenterChannelsFromDisplayElements(value) {
    const contract = normaliseDisplayElementsContract(value);
    if (!contract) {
        return null;
    }

    let screen = null;
    let spoken = null;

    for (const element of contract.elements) {
        if (!element || typeof element !== 'object') {
            continue;
        }

        if (String(element.element_type || '').trim() !== 'text_block') {
            continue;
        }

        const payload = element.payload;
        const text = (payload && typeof payload === 'object' && typeof payload.text === 'string')
            ? payload.text
            : null;
        if (!text || !text.trim()) {
            continue;
        }

        const elementId = String(element.element_id || '').trim();
        const channel = String(element.channel || '').trim().toLowerCase();
        const intent = String(element.intent || '').trim().toLowerCase();

        if (
            !screen
            && (
                channel === 'screen'
                || elementId === 'screen_text'
                || intent === 'primary_response'
            )
        ) {
            screen = text;
            continue;
        }

        if (
            !spoken
            && (
                channel === 'spoken'
                || elementId === 'spoken_text'
                || intent === 'narration'
            )
        ) {
            spoken = text;
        }
    }

    if (!(screen && screen.trim()) && !(spoken && spoken.trim())) {
        return null;
    }

    return normalisePresenterChannels({
        screen,
        spoken,
        format: 'display_elements_v1'
    });
}

function resolveDisplayElementsContract(responseData, debugData = null) {
    const topLevel = normaliseDisplayElementsContract(responseData?.display_elements);
    if (topLevel) {
        return topLevel;
    }

    const metadataContract = normaliseDisplayElementsContract(responseData?.metadata?.display_elements);
    if (metadataContract) {
        return metadataContract;
    }

    const debugContract = normaliseDisplayElementsContract(debugData?.display_elements);
    if (debugContract) {
        return debugContract;
    }

    return null;
}

function resolvePresenterChannels(rawPresenterChannels, displayElements) {
    const directChannels = normalisePresenterChannels(rawPresenterChannels);
    const contractChannels = extractPresenterChannelsFromDisplayElements(displayElements);

    if (!directChannels && !contractChannels) {
        return null;
    }

    return normalisePresenterChannels({
        screen: directChannels?.screen || contractChannels?.screen || null,
        spoken: directChannels?.spoken || contractChannels?.spoken || null,
        format: directChannels?.format || contractChannels?.format || null
    });
}

function dispatchSelectConceptByIdEvent(conceptId, event = null) {
    if (!conceptId || typeof conceptId !== 'string' || !conceptId.trim()) {
        return;
    }
    document.dispatchEvent(new CustomEvent('von:selectConceptById', {
        detail: {
            conceptId: conceptId.trim(),
            createConceptTab: true,
            modifierKeys: {
                shiftKey: !!(event && event.shiftKey)
            }
        }
    }));
}

function resolveResponsePresenterState(responseData) {
    const debugData = (responseData && typeof responseData === 'object' && responseData.llm_debug && typeof responseData.llm_debug === 'object')
        ? responseData.llm_debug
        : null;
    const displayElements = resolveDisplayElementsContract(responseData, debugData);

    const presenterChannelsRaw = responseData?.presenter_channels
        || responseData?.response_channels
        || responseData?.metadata?.presenter_channels;

    const presenterChannels = resolvePresenterChannels(presenterChannelsRaw, displayElements);
    const screenText = presenterChannels?.screen ? presenterChannels.screen : String(responseData?.response ?? '');
    const spokenText = presenterChannels?.spoken ? presenterChannels.spoken : null;

    return {
        presenterChannels,
        displayElements,
        screenText,
        spokenText
    };
}

