async function fetchAndCacheConceptMetaForChat(
    fullId,
    generation = chatConceptMetaHydrationGeneration
) {
    const conceptId = normalisePotentialConceptId(fullId);
    if (!conceptId) {
        return null;
    }

    if (chatConceptMetaCache.has(conceptId)) {
        return chatConceptMetaCache.get(conceptId);
    }

    if (!chatConceptMetaPending.has(conceptId)) {
        const p = fetchConceptMetaForChat(conceptId, generation).then((meta) => {
            if (chatConceptMetaPending.get(conceptId) === p) {
                chatConceptMetaPending.delete(conceptId);
            }
            if (meta && isChatConceptMetaHydrationCurrent(generation)) {
                chatConceptMetaCache.set(conceptId, meta);
            }
            return isChatConceptMetaHydrationCurrent(generation) ? meta : null;
        });
        chatConceptMetaPending.set(conceptId, p);
    }

    try {
        return await chatConceptMetaPending.get(conceptId);
    } catch (_) {
        if (isChatConceptMetaHydrationCurrent(generation)) {
            chatConceptMetaPending.delete(conceptId);
        }
        return null;
    }
}

function normaliseAliasComparisonText(value) {
    let text = String(value ?? '').trim().toLowerCase();
    if (!text) return '';
    if (text.startsWith('#v#')) {
        text = text.slice(3);
    }
    text = text.replace(/[\s-]+/g, '_');
    text = text.replace(/[^a-z0-9_./:–—]/g, '');
    return text;
}

function buildAliasComparisonKeys(value) {
    const base = normaliseAliasComparisonText(value);
    if (!base) {
        return new Set();
    }
    const keys = new Set([base]);
    const compact = base.replace(/[_\s-]+/g, '');
    if (compact) {
        keys.add(compact);
    }
    return keys;
}

function aliasSearchResultConceptId(row) {
    const rawId = row?.id || row?.concept_id || row?.conceptId || '';
    return normalisePotentialConceptId(rawId);
}

function scoreAliasSearchResult(row, alias) {
    const aliasKeys = buildAliasComparisonKeys(alias);
    if (aliasKeys.size === 0) {
        return 0;
    }

    let score = 0;
    const consider = (value, baseScore) => {
        const keys = buildAliasComparisonKeys(value);
        for (const key of keys) {
            if (aliasKeys.has(key)) {
                score = Math.max(score, baseScore);
            }
        }
    };

    const conceptId = aliasSearchResultConceptId(row);
    if (conceptId) {
        consider(conceptId.slice(3), 100);
        consider(conceptId, 95);
    }
    consider(row?.display_name, 80);
    consider(row?.name, 75);
    consider(row?.label, 70);

    if (score > 0 && String(row?.kind || '').toLowerCase() === 'predicate') {
        score += 5;
    }

    return score;
}

async function searchConceptMetaForChatAlias(
    alias,
    generation = chatConceptMetaHydrationGeneration
) {
    const params = new URLSearchParams();
    params.set('q', alias);
    params.set('limit', '8');
    params.set('include_individuals', '1');

    try {
        const res = await fetchOptionalChatConceptResource(
            `/vontology/api/vontology/search?${params.toString()}`,
            { cache: 'no-store' },
            generation
        );
        if (!res.ok) {
            return null;
        }
        const data = await res.json();
        if (!isChatConceptMetaHydrationCurrent(generation)) {
            return null;
        }
        const results = Array.isArray(data?.results) ? data.results : [];
        const scored = results
            .map((row) => ({
                row,
                fullId: aliasSearchResultConceptId(row),
                score: scoreAliasSearchResult(row, alias)
            }))
            .filter((entry) => entry.fullId && entry.score > 0)
            .sort((a, b) => b.score - a.score);

        if (scored.length === 0) {
            return null;
        }

        const selected = scored[0];
        const meta = await fetchAndCacheConceptMetaForChat(selected.fullId, generation);
        if (meta) {
            return {
                fullId: selected.fullId,
                meta
            };
        }

        const fallbackName = selected.row?.display_name || selected.row?.name || selected.fullId;
        const fallbackMeta = {
            name: String(fallbackName),
            bestName: String(fallbackName),
            shortestName: String(fallbackName),
            kind: selected.row?.kind || 'type',
            source: 'alias_search',
            provisional: true
        };
        if (!isChatConceptMetaHydrationCurrent(generation)) {
            return null;
        }
        chatConceptMetaCache.set(selected.fullId, fallbackMeta);
        return {
            fullId: selected.fullId,
            meta: fallbackMeta
        };
    } catch (err) {
        if (err?.name !== 'AbortError') {
            console.debug('[chatTab] alias search failed', err);
        }
        return null;
    }
}

async function resolveChatConceptAlias(alias, options = {}) {
    const cleanAlias = normalisePotentialConceptAlias(alias, { requireDistinctiveSyntax: false });
    if (!cleanAlias) {
        return null;
    }

    const directFullId = normalisePotentialConceptId(`#V#${cleanAlias}`);
    const generation = Number.isInteger(options?.generation)
        ? options.generation
        : chatConceptMetaHydrationGeneration;
    if (directFullId) {
        const directMeta = await fetchAndCacheConceptMetaForChat(directFullId, generation);
        if (directMeta) {
            return {
                alias: cleanAlias,
                fullId: directFullId,
                meta: directMeta,
                source: 'direct_id'
            };
        }
    }

    if (options?.allowSearch === false) {
        return null;
    }

    const searched = await searchConceptMetaForChatAlias(cleanAlias, generation);
    if (!searched) {
        return null;
    }

    return {
        alias: cleanAlias,
        fullId: searched.fullId,
        meta: searched.meta,
        source: 'alias_search'
    };
}

function shouldSkipInlineAliasTextNode(textNode) {
    const parent = textNode?.parentElement;
    if (!parent) {
        return true;
    }

    for (const selector of CHAT_INLINE_ALIAS_TEXT_SKIP_SELECTORS) {
        try {
            if (parent.closest(selector)) {
                return true;
            }
        } catch (_) {
            // Ignore invalid selectors.
        }
    }

    return false;
}

function shouldSkipInlineAliasCodeElement(codeEl) {
    if (!codeEl || codeEl.closest('pre')) {
        return true;
    }
    for (const selector of ['a', 'button', '.vontology-cartouche', '.vontology-inline-assertion']) {
        try {
            if (codeEl.closest(selector)) {
                return true;
            }
        } catch (_) {
            // Ignore invalid selectors.
        }
    }
    return codeEl.childElementCount !== 0;
}

function appendInlineAliasCandidate(aliasCandidates, alias, options = {}) {
    const cleanAlias = normalisePotentialConceptAlias(alias, { requireDistinctiveSyntax: false });
    if (!cleanAlias) {
        return;
    }
    const allowSearch = options?.allowSearch === true;
    if (aliasCandidates.has(cleanAlias)) {
        const existing = aliasCandidates.get(cleanAlias);
        if (existing && typeof existing === 'object') {
            existing.allowSearch = existing.allowSearch || allowSearch;
        }
        return;
    }
    if (aliasCandidates.size >= CHAT_INLINE_ALIAS_MAX_CANDIDATES) {
        return;
    }
    aliasCandidates.set(cleanAlias, { allowSearch, resolved: null });
}

async function resolveInlineVontologyAliasesInElement(root, options = {}) {
    if (!root || typeof root.querySelectorAll !== 'function') {
        return 0;
    }

    const expectedRenderMode = options?.expectedRenderMode ? String(options.expectedRenderMode) : '';
    const generation = chatConceptMetaHydrationGeneration;
    if (expectedRenderMode && String(root?.dataset?.renderMode || '') !== expectedRenderMode) {
        return 0;
    }

    const aliasCandidates = new Map();
    const codeTargets = [];
    const codeElements = Array.from(root.querySelectorAll('code'));
    for (const codeEl of codeElements) {
        if (shouldSkipInlineAliasCodeElement(codeEl)) {
            continue;
        }
        const alias = normalisePotentialConceptAlias(codeEl.textContent, { requireDistinctiveSyntax: false });
        if (!alias) {
            continue;
        }
        codeTargets.push({ codeEl, alias });
        appendInlineAliasCandidate(aliasCandidates, alias, { allowSearch: true });
    }

    const textTargets = [];
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    let node = walker.nextNode();
    while (node) {
        const textNode = node;
        node = walker.nextNode();
        if (shouldSkipInlineAliasTextNode(textNode)) {
            continue;
        }
        const value = textNode.nodeValue || '';
        const matches = findPotentialConceptAliasMatches(value);
        if (matches.length === 0) {
            continue;
        }
        textTargets.push({ textNode, value, matches });
        for (const match of matches) {
            appendInlineAliasCandidate(aliasCandidates, match.alias, { allowSearch: false });
        }
    }

    if (aliasCandidates.size === 0) {
        return 0;
    }

    await Promise.all(Array.from(aliasCandidates.entries()).map(async ([alias, candidate]) => {
        const resolved = await resolveChatConceptAlias(alias, {
            allowSearch: candidate?.allowSearch === true,
            generation
        });
        if (candidate && typeof candidate === 'object') {
            candidate.resolved = resolved;
        } else {
            aliasCandidates.set(alias, { allowSearch: false, resolved });
        }
    }));

    if (!isChatConceptMetaHydrationCurrent(generation)) {
        return 0;
    }
    if (expectedRenderMode && String(root?.dataset?.renderMode || '') !== expectedRenderMode) {
        return 0;
    }

    let replacementCount = 0;
    for (const target of codeTargets) {
        const resolved = aliasCandidates.get(target.alias)?.resolved || null;
        const codeEl = target.codeEl;
        if (!resolved || !codeEl?.parentNode || shouldSkipInlineAliasCodeElement(codeEl)) {
            continue;
        }
        const currentAlias = normalisePotentialConceptAlias(codeEl.textContent, { requireDistinctiveSyntax: false });
        if (currentAlias !== target.alias) {
            continue;
        }
        const cartouche = createVontologyAliasCartouche(resolved.fullId, target.alias, resolved.meta);
        try {
            codeEl.replaceWith(cartouche);
            updateCartoucheElement(cartouche, resolved.meta);
            replacementCount += 1;
        } catch (_) {
            // Ignore detached nodes.
        }
    }

    for (const target of textTargets) {
        const textNode = target.textNode;
        if (!textNode?.parentNode || shouldSkipInlineAliasTextNode(textNode)) {
            continue;
        }
        if (String(textNode.nodeValue || '') !== target.value) {
            continue;
        }
        const resolvedMatches = target.matches
            .map((match) => {
                const resolved = aliasCandidates.get(match.alias)?.resolved || null;
                if (!resolved) {
                    return null;
                }
                return {
                    ...match,
                    fullId: resolved.fullId,
                    meta: resolved.meta
                };
            })
            .filter(Boolean);
        if (resolvedMatches.length === 0) {
            continue;
        }
        const cartouches = replaceTextNodeWithVontologyAliasCartouches(textNode, resolvedMatches);
        for (let index = 0; index < cartouches.length; index += 1) {
            updateCartoucheElement(cartouches[index], resolvedMatches[index]?.meta || null);
        }
        replacementCount += cartouches.length;
    }

    return replacementCount;
}

function shouldRetryChatConceptMeta(fullId, meta) {
    if (!fullId) {
        return false;
    }

    if (!meta) {
        return true;
    }

    if (meta.provisional === true) {
        return true;
    }

    const name = typeof meta.name === 'string' ? meta.name : '';
    if (name === fullId) {
        return true;
    }

    return false;
}

function scheduleChatConceptMetaRetry(
    fullId,
    generation = chatConceptMetaHydrationGeneration
) {
    if (!fullId || !isChatConceptMetaHydrationCurrent(generation)) {
        return;
    }

    if ((chatConceptMetaRetryCounts.get(fullId) || 0) >= CHAT_CONCEPT_META_MAX_RETRIES) {
        return;
    }

    if (chatConceptMetaRetryTimers.has(fullId)) {
        return;
    }

    const runRetry = () => {
        if (!isChatConceptMetaHydrationCurrent(generation)) {
            return;
        }
        const pendingLookup = chatConceptMetaPending.get(fullId);
        if (pendingLookup) {
            pendingLookup.then(runRetry, runRetry);
            return;
        }

        const replacementTimer = chatConceptMetaRetryTimers.get(fullId);
        if (replacementTimer !== undefined) {
            clearTimeout(replacementTimer);
            chatConceptMetaRetryTimers.delete(fullId);
        }
        const currentRetries = chatConceptMetaRetryCounts.get(fullId) || 0;
        if (currentRetries >= CHAT_CONCEPT_META_MAX_RETRIES) {
            return;
        }
        chatConceptMetaRetryCounts.set(fullId, currentRetries + 1);

        const shouldTrackPending = !chatConceptMetaPending.has(fullId);
        const p = fetchConceptMetaForChatNodeOnly(fullId, generation).then((meta) => {
            if (shouldTrackPending && chatConceptMetaPending.get(fullId) === p) {
                chatConceptMetaPending.delete(fullId);
            }

            if (!isChatConceptMetaHydrationCurrent(generation)) {
                return null;
            }

            if (meta) {
                chatConceptMetaCache.set(fullId, meta);
                const els = Array.from(document.querySelectorAll('.vontology-cartouche[data-full-concept-id]'));
                els
                    .filter(el => el.dataset.fullConceptId === fullId)
                    .forEach(el => updateCartoucheElement(el, meta));
            } else {
                scheduleChatConceptMetaRetry(fullId, generation);
            }

            return meta;
        });

        if (shouldTrackPending) {
            chatConceptMetaPending.set(fullId, p);
        }
    };

    const retries = chatConceptMetaRetryCounts.get(fullId) || 0;
    const delayMs = retries === 0 ? 250 : retries === 1 ? 1000 : 2500;
    const timerId = setTimeout(() => {
        if (chatConceptMetaRetryTimers.get(fullId) === timerId) {
            chatConceptMetaRetryTimers.delete(fullId);
        }
        runRetry();
    }, delayMs);

    chatConceptMetaRetryTimers.set(fullId, timerId);
}

function updateCartoucheElement(cartoucheEl, meta) {
    if (!cartoucheEl) return;
    const fullId = cartoucheEl?.dataset?.fullConceptId;
    console.log('[chatTab] updateCartoucheElement', { fullId, hasMeta: !!meta, meta });
    if (!meta) {
        // Concept not found: mark as missing and show only the concept ID.
        console.log('[chatTab] Marking cartouche as missing:', fullId);
        cartoucheEl.classList.add('vontology-cartouche-missing');
        cartoucheEl.classList.remove('unresolved', 'cartouche-hide-id', 'cartouche-hide-name', 'cartouche-hide-kind', 'cartouche-kind-as-bg');
        cartoucheEl.dataset.kind = '';
        cartoucheEl.title = "This concept doesn't exist yet — click to create";
        const nameEl = cartoucheEl.querySelector('.vontology-cartouche-name');
        if (nameEl) nameEl.textContent = '';
        const kindEl = cartoucheEl.querySelector('.vontology-cartouche-kind');
        if (kindEl) {
            kindEl.className = 'vontology-cartouche-kind';
            kindEl.textContent = '';
        }
        return;
    }
    const prefs = getCartoucheAppearanceSettings();

    const nameEl = cartoucheEl.querySelector('.vontology-cartouche-name');
    const kindEl = cartoucheEl.querySelector('.vontology-cartouche-kind');

    if (nameEl) {
        const displayName = prefs?.useShortestName
            ? (meta.shortestName || meta.bestName || meta.name)
            : (meta.bestName || meta.name || meta.shortestName);
        nameEl.textContent = displayName || (cartoucheEl.dataset.fullConceptId || '');
    }
    if (kindEl) {
        const kindClass = normaliseKindClass(meta.kind);
        kindEl.className = `vontology-cartouche-kind ${kindClass}`;
        kindEl.textContent = formatKindLabel(meta.kind);
    }
    try {
        cartoucheEl.dataset.kind = meta.kind || '';
    } catch (_) { }

    applyCartoucheAppearance(cartoucheEl, prefs);
}

function hydrateChatConceptCartouches(root) {
    if (!root || typeof root.querySelectorAll !== 'function') {
        return;
    }

    const cartouches = Array.from(root.querySelectorAll('.vontology-cartouche[data-full-concept-id]'));
    if (cartouches.length === 0) {
        return;
    }
    const generation = chatConceptMetaHydrationGeneration;

    const uniqueIds = new Set();
    for (const el of cartouches) {
        const fullId = el.dataset.fullConceptId;
        if (fullId) {
            uniqueIds.add(fullId);
        }
    }

    for (const fullId of uniqueIds) {
        if (chatConceptMetaCache.has(fullId)) {
            const cached = chatConceptMetaCache.get(fullId);
            cartouches
                .filter(el => el.dataset.fullConceptId === fullId)
                .forEach(el => updateCartoucheElement(el, cached));

            if (shouldRetryChatConceptMeta(fullId, cached)) {
                scheduleChatConceptMetaRetry(fullId, generation);
            }
            continue;
        }

        if (!chatConceptMetaPending.has(fullId)) {
            const p = fetchConceptMetaForChat(fullId, generation).then((meta) => {
                if (chatConceptMetaPending.get(fullId) === p) {
                    chatConceptMetaPending.delete(fullId);
                }

                if (!isChatConceptMetaHydrationCurrent(generation)) {
                    return null;
                }

                // Avoid caching null or provisional results indefinitely; newly-created concepts can
                // race indexing, and we want a short retry window to auto-hydrate.
                if (meta) {
                    chatConceptMetaCache.set(fullId, meta);
                }

                if (shouldRetryChatConceptMeta(fullId, meta)) {
                    scheduleChatConceptMetaRetry(fullId, generation);
                }
                return meta;
            });
            chatConceptMetaPending.set(fullId, p);
            scheduleChatConceptMetaRetry(fullId, generation);
        }

        chatConceptMetaPending.get(fullId)
            .then((meta) => {
                if (!isChatConceptMetaHydrationCurrent(generation)) {
                    return;
                }
                cartouches
                    .filter(el => el.dataset.fullConceptId === fullId)
                    .forEach(el => updateCartoucheElement(el, meta));

                if (shouldRetryChatConceptMeta(fullId, meta)) {
                    scheduleChatConceptMetaRetry(fullId, generation);
                }
            })
            .catch(() => {
                // Ignore lookup failures; leave placeholders.
                scheduleChatConceptMetaRetry(fullId, generation);
            });
    }
}

function refreshChatCartoucheAppearance() {
    const cartouches = Array.from(document.querySelectorAll('.vontology-cartouche[data-full-concept-id]'));
    if (!cartouches.length) return;
    const prefs = getCartoucheAppearanceSettings();
    for (const el of cartouches) {
        const fullId = el.dataset.fullConceptId;
        const meta = fullId ? chatConceptMetaCache.get(fullId) : null;
        if (meta) {
            updateCartoucheElement(el, meta);
        } else {
            applyCartoucheAppearance(el, prefs);
        }
    }
}

try {
    window.addEventListener('von-preferences-changed', (event) => {
        const key = event?.detail?.key;
        if (key === 'von_cartouche_use_shortest_name' || key === 'von_cartouche_show_name' || key === 'von_cartouche_show_id' || key === 'von_cartouche_show_kind' || key === 'von_cartouche_kind_as_background') {
            refreshChatCartoucheAppearance();
        }
    });
} catch (_) {
    // ignore
}

