const CHAT_PROMPT_QUEUE_POLL_INTERVAL_MS = 2000;

const CHAT_TTS_STORAGE_KEY = 'chatTtsEnabled';

const CHAT_TTS_VOICE_URI_STORAGE_KEY = 'chatTtsVoiceUri';
const CHAT_TTS_LANGUAGE_STORAGE_KEY = 'chatTtsLanguage';
const CHAT_TTS_RATE_STORAGE_KEY = 'chatTtsRate';
const CHAT_TTS_PITCH_STORAGE_KEY = 'chatTtsPitch';
const CHAT_TTS_VOLUME_STORAGE_KEY = 'chatTtsVolume';
const CHAT_TTS_LONG_DURATION_THRESHOLD_KEY = 'chatTtsLongDurationThresholdSec';
const DEFAULT_TTS_LONG_DURATION_THRESHOLD_SEC = 30;
const CHAT_TTS_MAX_SPEAKING_SECONDS_KEY = 'chatTtsMaxSpeakingSeconds';
const DEFAULT_TTS_MAX_SPEAKING_SECONDS = 40;

const CHAT_STT_LANGUAGE_STORAGE_KEY = 'chatSttLanguage';
const CHAT_STT_CONTINUOUS_STORAGE_KEY = 'chatSttContinuous';
const CHAT_STT_INTERIM_RESULTS_STORAGE_KEY = 'chatSttInterimResults';

let activeDictation = null;
let dictationState = null;

let activeTtsTurnId = null;
let activeTtsButton = null;
let activeTtsPlaybackState = null;

function safeLocalStorageGet(key) {
    try {
        if (typeof localStorage === 'undefined') {
            return null;
        }
        return localStorage.getItem(key);
    } catch (_) {
        return null;
    }
}

function safeLocalStorageSet(key, value) {
    try {
        if (typeof localStorage === 'undefined') {
            return;
        }
        localStorage.setItem(key, value);
    } catch (_) {
        // Ignore.
    }
}

function getPreferredChatLanguage() {
    const ctx = getUserContext();
    const lang = (ctx && ctx.language) ? String(ctx.language).trim() : '';
    return lang || 'en-NZ';
}

function clampNumber(value, minValue, maxValue, fallbackValue) {
    const num = Number(value);
    if (!Number.isFinite(num)) {
        return fallbackValue;
    }
    return Math.min(Math.max(num, minValue), maxValue);
}

function normaliseLanguageSetting(value) {
    const lang = String(value ?? '').trim();
    return lang;
}

function parseBoolSetting(value, fallbackValue) {
    if (value === null || value === undefined) {
        return fallbackValue;
    }
    return String(value) === 'true';
}

function getTtsLongDurationThresholdSec() {
    const raw = safeLocalStorageGet(CHAT_TTS_LONG_DURATION_THRESHOLD_KEY);
    const parsed = Number(raw);
    if (Number.isFinite(parsed) && parsed > 0) {
        return Math.min(Math.max(parsed, 5), 300);
    }

    // Default to the user-configured maximum speaking duration so UI settings are respected.
    // (The dedicated long-duration threshold key is not exposed in the settings UI.)
    const maxSpeakingSeconds = getTtsMaxSpeakingSeconds();
    if (Number.isFinite(maxSpeakingSeconds) && maxSpeakingSeconds > 0) {
        return Math.min(Math.max(maxSpeakingSeconds, 5), 600);
    }

    return DEFAULT_TTS_LONG_DURATION_THRESHOLD_SEC;
}

function getTtsMaxSpeakingSeconds() {
    const raw = safeLocalStorageGet(CHAT_TTS_MAX_SPEAKING_SECONDS_KEY);
    const parsed = Number(raw);
    if (Number.isFinite(parsed) && parsed > 0) {
        return Math.min(Math.max(parsed, 10), 600);
    }
    return DEFAULT_TTS_MAX_SPEAKING_SECONDS;
}

function estimateSpeechDurationMs(text, rate) {
    const cleaned = String(text ?? '').trim();
    const chars = cleaned.length;
    const words = cleaned ? cleaned.split(/\s+/).filter(Boolean).length : 0;
    if (!chars) {
        return { expectedMs: null, estimateMethod: null, words: 0, chars: 0 };
    }

    const safeRate = Number.isFinite(rate) && rate > 0 ? rate : 1;
    const baseWpm = 180;
    if (words > 0) {
        const wpm = baseWpm * safeRate;
        return {
            expectedMs: Math.round((words / wpm) * 60 * 1000),
            estimateMethod: 'words_per_minute',
            words,
            chars
        };
    }

    const charsPerSec = 12 * safeRate;
    return {
        expectedMs: Math.round((chars / charsPerSec) * 1000),
        estimateMethod: 'chars_per_sec',
        words,
        chars
    };
}

function resolveSpeechVoiceInfo(voiceUri) {
    const uri = String(voiceUri || '').trim();
    if (!uri) {
        return { voice_uri: null, voice_name: null };
    }

    const voices = getSpeechSynthesisVoices();
    const match = voices.find((voice) => voice && String(voice.voiceURI || '') === uri) || null;
    const voiceName = match && match.name ? String(match.name).trim() : null;

    return {
        voice_uri: uri,
        voice_name: voiceName || null
    };
}

function buildSpeechPlaybackTelemetry(state, stopReason) {
    if (!state || typeof state !== 'object') {
        return null;
    }

    const startedAtMs = Number.isFinite(state.startedAtMs) ? state.startedAtMs : null;
    const endedAtMs = Number.isFinite(state.endedAtMs) ? state.endedAtMs : null;
    const actualDurationMs = (startedAtMs !== null && endedAtMs !== null)
        ? Math.max(0, endedAtMs - startedAtMs)
        : null;

    const expectedMs = Number.isFinite(state.expectedDurationMs) ? state.expectedDurationMs : null;
    const thresholdSec = Number.isFinite(state.thresholdSec) ? state.thresholdSec : null;

    const actualSec = actualDurationMs !== null ? actualDurationMs / 1000 : null;
    const expectedSec = expectedMs !== null ? expectedMs / 1000 : null;

    const durationTooLong = (actualSec !== null && thresholdSec !== null)
        ? actualSec > thresholdSec
        : (expectedSec !== null && thresholdSec !== null ? expectedSec > thresholdSec : false);

    return {
        request_id: state.requestId || null,
        turn_id: state.turnId || null,
        started_at: state.startedAt || null,
        ended_at: state.endedAt || null,
        actual_duration_ms: actualDurationMs,
        expected_duration_ms: expectedMs,
        estimate_method: state.estimateMethod || null,
        duration_threshold_sec: thresholdSec,
        duration_suspect_too_long: durationTooLong,
        tts_source: state.ttsSource || null,
        tts_chars: Number.isFinite(state.ttsChars) ? state.ttsChars : null,
        tts_words: Number.isFinite(state.ttsWords) ? state.ttsWords : null,
        stop_reason: stopReason || null,
        tts_settings: {
            language: state.ttsLanguage || null,
            rate: state.ttsRate ?? null,
            pitch: state.ttsPitch ?? null,
            volume: state.ttsVolume ?? null,
            voice_uri: state.voiceUri || null,
            voice_name: state.voiceName || null
        }
    };
}

async function postSpeechPlaybackTelemetry(turnId, telemetry) {
    if (!telemetry || typeof telemetry !== 'object') {
        return;
    }

    const payload = {
        conversation_id: elements.conversationId || 'local',
        turn_id: turnId,
        request_id: telemetry.request_id || null,
        speech_playback: telemetry,
        context: getUserContext()
    };

    try {
        await fetch('/api/speech/telemetry', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
    } catch (err) {
        console.warn('[speech] Telemetry post failed:', err);
    }
}

function recordSpeechPlaybackTelemetry(turnId, telemetry) {
    if (!telemetry || typeof telemetry !== 'object') {
        return;
    }

    const debugData = turnId ? llmDebugData.get(turnId) : null;
    if (debugData && typeof debugData === 'object') {
        const updated = {
            ...debugData,
            speech_playback: telemetry
        };
        setLlmDebugDataEntry(turnId, updated);
    }

    if (telemetry.duration_suspect_too_long) {
        console.warn('[speech] Long narration duration detected:', telemetry);
    } else {
        console.info('[speech] Narration playback telemetry:', telemetry);
    }

    void postSpeechPlaybackTelemetry(turnId, telemetry);
}

function getChatSpeechSettings() {
    const preferredLanguage = getPreferredChatLanguage();

    const ttsVoiceUri = String(safeLocalStorageGet(CHAT_TTS_VOICE_URI_STORAGE_KEY) || '').trim();
    const ttsLanguageRaw = safeLocalStorageGet(CHAT_TTS_LANGUAGE_STORAGE_KEY);
    const ttsLanguage = normaliseLanguageSetting(ttsLanguageRaw) || preferredLanguage;

    const ttsRate = clampNumber(safeLocalStorageGet(CHAT_TTS_RATE_STORAGE_KEY), 0.5, 2, 1);
    const ttsPitch = clampNumber(safeLocalStorageGet(CHAT_TTS_PITCH_STORAGE_KEY), 0, 2, 1);
    const ttsVolume = clampNumber(safeLocalStorageGet(CHAT_TTS_VOLUME_STORAGE_KEY), 0, 1, 1);

    const sttLanguageRaw = safeLocalStorageGet(CHAT_STT_LANGUAGE_STORAGE_KEY);
    const sttLanguage = normaliseLanguageSetting(sttLanguageRaw) || preferredLanguage;

    const sttContinuous = parseBoolSetting(
        safeLocalStorageGet(CHAT_STT_CONTINUOUS_STORAGE_KEY),
        true
    );
    const sttInterimResults = parseBoolSetting(
        safeLocalStorageGet(CHAT_STT_INTERIM_RESULTS_STORAGE_KEY),
        true
    );

    return {
        tts: {
            voiceUri: ttsVoiceUri || null,
            language: ttsLanguage,
            rate: ttsRate,
            pitch: ttsPitch,
            volume: ttsVolume
        },
        stt: {
            language: sttLanguage,
            continuous: sttContinuous,
            interimResults: sttInterimResults
        }
    };
}

function formatVoiceOptionLabel(voice) {
    if (!voice) {
        return 'Unknown voice';
    }
    const name = String(voice.name || 'Unknown');
    const lang = String(voice.lang || '').trim();
    return lang ? `${name} (${lang})` : name;
}

function _populateTtsVoiceSelect(selectEl, selectedVoiceUri) {
    if (!selectEl) {
        return;
    }

    const keepFirst = selectEl.querySelector('option[value=""]');
    selectEl.innerHTML = '';
    if (keepFirst) {
        selectEl.appendChild(keepFirst);
    } else {
        const opt = document.createElement('option');
        opt.value = '';
        opt.textContent = 'Default';
        selectEl.appendChild(opt);
    }

    const voices = getSpeechSynthesisVoices();
    const sorted = voices
        .slice()
        .filter((v) => v && v.voiceURI)
        .sort((a, b) => formatVoiceOptionLabel(a).localeCompare(formatVoiceOptionLabel(b)));

    for (const voice of sorted) {
        const opt = document.createElement('option');
        opt.value = String(voice.voiceURI);
        opt.textContent = formatVoiceOptionLabel(voice);
        selectEl.appendChild(opt);
    }

    if (selectedVoiceUri) {
        selectEl.value = String(selectedVoiceUri);
    }
}

function isChatTtsEnabled() {
    const toggle = document.getElementById('ttsToggle');
    if (toggle && typeof toggle.checked === 'boolean') {
        return !!toggle.checked;
    }
    return safeLocalStorageGet(CHAT_TTS_STORAGE_KEY) === 'true';
}

function clearActiveTtsUi() {
    if (activeTtsButton) {
        activeTtsButton.classList.remove('active');
        activeTtsButton.textContent = 'Speak';
        activeTtsButton.title = 'Speak this response aloud';
    }
    activeTtsTurnId = null;
    activeTtsButton = null;
}

function toggleSpeakTurn(turnId, text, button) {
    if (!turnId || !button) {
        return;
    }

    if (!isTextToSpeechSupported()) {
        return;
    }

    const trimmed = String(text ?? '').trim();
    if (!trimmed) {
        return;
    }

    const isAlreadyActive = activeTtsTurnId === turnId;
    if (isAlreadyActive) {
        if (activeTtsPlaybackState && activeTtsPlaybackState.turnId === turnId) {
            activeTtsPlaybackState.stopRequested = true;
        }
        stopSpeaking();
        clearActiveTtsUi();
        return;
    }

    // Stop any previous speech and update the previous button state.
    stopSpeaking();
    clearActiveTtsUi();

    activeTtsTurnId = turnId;
    activeTtsButton = button;

    button.classList.add('active');
    button.textContent = 'Stop';
    button.title = 'Stop speaking';

    let utterance;
    try {
        const settings = getChatSpeechSettings();
        const debugData = llmDebugData.get(turnId);
        const estimate = estimateSpeechDurationMs(trimmed, settings.tts.rate);
        const voiceInfo = resolveSpeechVoiceInfo(settings.tts.voiceUri);
        const thresholdSec = getTtsLongDurationThresholdSec();
        const maxSpeakingSeconds = getTtsMaxSpeakingSeconds();
        const ttsSource = debugData?.speech_planning?.tts_source || null;

        activeTtsPlaybackState = {
            turnId,
            requestId: debugData?.request_id || null,
            expectedDurationMs: estimate.expectedMs,
            estimateMethod: estimate.estimateMethod,
            ttsChars: estimate.chars,
            ttsWords: estimate.words,
            thresholdSec,
            maxSpeakingSeconds,
            ttsSource,
            ttsLanguage: settings.tts.language,
            ttsRate: settings.tts.rate,
            ttsPitch: settings.tts.pitch,
            ttsVolume: settings.tts.volume,
            voiceUri: voiceInfo.voice_uri,
            voiceName: voiceInfo.voice_name,
            startedAtMs: null,
            endedAtMs: null,
            startedAt: null,
            endedAt: null,
            stopRequested: false
        };

        utterance = speakText(trimmed, {
            language: settings.tts.language,
            rate: settings.tts.rate,
            pitch: settings.tts.pitch,
            volume: settings.tts.volume,
            voiceUri: settings.tts.voiceUri
        });
    } catch (err) {
        console.warn('[chatTab] TTS failed:', err);
        clearActiveTtsUi();
        return;
    }

    const finish = (reason) => {
        if (activeTtsPlaybackState && activeTtsPlaybackState.turnId === turnId) {
            activeTtsPlaybackState.endedAtMs = Date.now();
            activeTtsPlaybackState.endedAt = new Date(activeTtsPlaybackState.endedAtMs).toISOString();
            const stopReason = activeTtsPlaybackState.stopRequested ? 'cancelled' : reason;
            const telemetry = buildSpeechPlaybackTelemetry(activeTtsPlaybackState, stopReason);
            recordSpeechPlaybackTelemetry(turnId, telemetry);
            activeTtsPlaybackState = null;
        }
        if (activeTtsTurnId === turnId) {
            clearActiveTtsUi();
        }
    };

    try {
        utterance.onstart = () => {
            if (activeTtsPlaybackState && activeTtsPlaybackState.turnId === turnId) {
                activeTtsPlaybackState.startedAtMs = Date.now();
                activeTtsPlaybackState.startedAt = new Date(activeTtsPlaybackState.startedAtMs).toISOString();
            }
        };
        utterance.onend = () => finish('ended');
        utterance.onerror = () => finish('error');
    } catch (_) {
        // Ignore.
    }
}

function stopDictation() {
    if (!activeDictation) {
        return;
    }

    try {
        activeDictation.stop?.();
    } catch (_) {
        // Ignore.
    }
}

// Persist sender/message pairs for transcript exports
function recordTranscriptTurn(sender, message, options = {}) {
    if (!sender && !message) {
        return;
    }

    transcriptTurns.push({
        sender,
        message,
        turnId: options.turnId || null,
        isHistory: !!options.isHistory,
        timestamp: options.timestamp || new Date().toISOString()
    });
}

function normaliseConversationTranscriptTurn(turn, index = 0, source = 'transcript') {
    if (!turn || typeof turn !== 'object') {
        return null;
    }

    const sender = typeof turn.sender === 'string' && turn.sender.trim()
        ? turn.sender.trim()
        : (typeof turn.role === 'string' && turn.role.trim() ? turn.role.trim() : 'Message');
    const rawMessage = turn.message ?? turn.content ?? '';
    const message = typeof rawMessage === 'string' ? rawMessage : String(rawMessage ?? '');
    if (!sender && !message.trim()) {
        return null;
    }

    return {
        sender,
        message,
        turnId: turn.turnId || turn.turn_id || `visible-${index + 1}`,
        isHistory: !!turn.isHistory,
        timestamp: turn.timestamp || turn.timestamp_utc || null,
        source
    };
}

function collectVisibleConversationTranscriptTurns() {
    if (typeof document === 'undefined' || !document.querySelectorAll) {
        return [];
    }

    const containers = Array.from(document.querySelectorAll('#scrollableField .message-container'));
    return containers
        .map((container, index) => {
            if (typeof HTMLElement !== 'undefined' && !(container instanceof HTMLElement)) {
                return null;
            }

            let sender = 'Message';
            if (container.classList.contains('assistant-turn')) {
                sender = 'Von';
            } else if (container.classList.contains('user-turn')) {
                sender = 'User';
            } else if (container.classList.contains('error-turn')) {
                sender = 'Error';
            } else {
                const headerText = container.querySelector('.message-header span')?.textContent || '';
                const headerSender = headerText.split('•')[0]?.trim();
                if (headerSender) {
                    sender = headerSender;
                }
            }

            const messageElement = container.querySelector('.chat-message-text');
            const message = messageElement
                ? (messageElement.innerText || messageElement.textContent || '')
                : '';
            return normaliseConversationTranscriptTurn({
                sender,
                message,
                turnId: container.dataset?.turnId || null,
                isHistory: container.textContent?.includes('(history)') || false
            }, index, 'visible_dom');
        })
        .filter(Boolean);
}

function getConversationTranscriptTurnsSnapshot() {
    const storedTurns = Array.isArray(transcriptTurns)
        ? transcriptTurns
            .map((turn, index) => normaliseConversationTranscriptTurn(turn, index, 'transcript'))
            .filter(Boolean)
        : [];
    if (storedTurns.length > 0) {
        return storedTurns;
    }
    return collectVisibleConversationTranscriptTurns();
}

function countAssistantConversationTranscriptTurns(turns = getConversationTranscriptTurnsSnapshot()) {
    if (!Array.isArray(turns) || turns.length === 0) {
        return 0;
    }

    return turns.filter((turn) => {
        if (!turn || typeof turn !== 'object') {
            return false;
        }

        const rawRole = typeof turn.role === 'string'
            ? turn.role
            : (typeof turn.sender === 'string' ? turn.sender : '');
        const normalisedRole = rawRole.trim().toLowerCase();
        return normalisedRole === 'assistant' || normalisedRole === 'von';
    }).length;
}

function updateHistoryBanner() {
    const banner = document.getElementById('historyBanner');
    const bannerText = document.getElementById('historyBannerText');
    const loadButton = document.getElementById('loadOlderHistoryBtn');

    if (!banner || !bannerText || !loadButton) {
        return;
    }

    const activeHistoryIssue = isHistoryLoadStateActiveForSession(activeChatSessionId);
    banner.classList.remove('is-warning', 'is-error');
    if (activeHistoryIssue) {
        bannerText.textContent = historyLoadState.message;
        banner.classList.remove('hidden');
        banner.classList.add(historyLoadState.retryable ? 'is-warning' : 'is-error');
        loadButton.disabled = true;
        return;
    }

    const remainingSegments = Math.max(totalHistorySegments - historySegmentsShown, 0);

    if (remainingSegments > 0) {
        const segmentLabel = remainingSegments === 1 ? 'segment' : 'segments';
        bannerText.textContent = `Earlier conversation ${segmentLabel} available (${remainingSegments})`;
        banner.classList.remove('hidden');
        loadButton.disabled = false;
    } else {
        banner.classList.add('hidden');
        loadButton.disabled = true;
    }
}

function setActiveChatSession(sessionId, sessionName, externalConversation = undefined) {
    const previousSessionId = activeChatSessionId;
    activeChatSessionId = (typeof sessionId === 'string' && sessionId.trim())
        ? sessionId.trim()
        : null;
    activeChatSessionName = (typeof sessionName === 'string' && sessionName.trim())
        ? sessionName.trim()
        : null;
    const cachedExternalConversation = activeChatSessionId
        ? sessionTabsCache.find(
            session => normaliseHistorySessionId(session?.session_id) === activeChatSessionId
        )?.external_conversation
        : null;
    activeExternalConversationMetadata = (
        externalConversation && typeof externalConversation === 'object'
            ? externalConversation
            : cachedExternalConversation
    ) || null;
    activeChatSessionOwnerId = null;
    activeChatSessionFocus = activeChatSessionId
        ? (chatSessionFocusCache.get(activeChatSessionId) || [])
        : [];
    renderActiveChatSessionFocusChips(activeChatSessionFocus);

    if (previousSessionId !== activeChatSessionId) {
        setSelectedChatPromptQueueEntryId(null);
        chatSessionSelectionGeneration += 1;
        synchroniseLlmExecutionContext({ reason: 'conversation_session_changed' });
        if (activeChatSessionId) {
            if (conversationSituationStateBySession.has(activeChatSessionId)) {
                _renderConversationSituationForActiveSession();
            } else {
                _markConversationSituationLoading(
                    activeChatSessionId,
                    'Loading the selected conversation situation…'
                );
            }
        } else {
            _renderConversationSituationForActiveSession();
        }
    }

    if (activeChatSessionId) {
        const cachedSession = sessionTabsCache.find(
            session => String(session?.session_id || '') === activeChatSessionId
        );
        if (cachedSession?.shared_owner_user_id) {
            activeChatSessionOwnerId = String(cachedSession.shared_owner_user_id || '').trim() || null;
        }
        markConversationSessionAccessed(activeChatSessionId);
    }

    // JVNAUTOSCI-1040: Update task panel with new session
    setTaskPanelSession(activeChatSessionId);

    // Keep metadata header title in sync when the active session name changes
    // (for example, after an in-place rename of the active conversation).
    if (activeChatSessionId && activeChatSessionLinks?.sessionId === activeChatSessionId) {
        _renderChatSessionMetadataPanel({
            sessionId: activeChatSessionId,
            links: activeChatSessionLinks?.links,
            statusText: activeChatSessionLinks?.statusText,
            statusTone: activeChatSessionLinks?.statusTone,
            disabled: activeChatSessionLinks?.disabled
        });
    }

    refreshConversationInfoCopyButtonState();
    renderPendingAttachmentState();
    renderActiveUploadUi();
    renderChatTaskQueuePanel();
    updateExternalConversationUi();
    renderConceptQaConversationControls();
}

function getChatSessionTabsContainer() {
    return document.getElementById('chatSessionTabs');
}

function getChatSessionCountEl() {
    return document.getElementById('chatSessionCount');
}

function setChatSessionCount(count) {
    const el = getChatSessionCountEl();
    if (!el) {
        return;
    }

    if (Number.isFinite(count)) {
        const value = Math.max(0, Number(count));
        el.textContent = String(value);
        el.title = `Conversations (${value})`;
        el.setAttribute('aria-label', `Conversation count: ${value}`);
    } else {
        el.textContent = '—';
        el.title = 'Conversations';
        el.setAttribute('aria-label', 'Conversation count');
    }
}

function getChatSessionMetadataEl() {
    return document.getElementById('chatSessionMetadata');
}

function getChatSessionFocusChipsEl() {
    return document.getElementById('chatSessionFocusChips');
}

function normaliseFocusedConcepts(rawFocus) {
    const values = Array.isArray(rawFocus) ? rawFocus : [];
    const seen = new Set();
    return values.flatMap((raw) => {
        const item = typeof raw === 'string' ? { concept_id: raw } : raw;
        const conceptId = String(item?.concept_id || item?.conceptId || item?.id || '').trim();
        if (!conceptId || seen.has(conceptId)) return [];
        seen.add(conceptId);
        const displayName = String(item?.display_name || item?.displayName || item?.name || item?.label || '').trim();
        return [{ conceptId, displayName: displayName || _deriveNameFromConceptId(conceptId) || conceptId }];
    });
}

function getFocusFromPayload(payload) {
    return normaliseFocusedConcepts(
        payload?.focal_concepts
        || payload?.focus?.focal_concepts
        || payload?.chat_session_focus?.focal_concepts
    );
}

function renderActiveChatSessionFocusChips(focalConcepts = activeChatSessionFocus) {
    const element = getChatSessionFocusChipsEl();
    if (!element) return;
    const focus = normaliseFocusedConcepts(focalConcepts);
    element.replaceChildren();
    if (!focus.length) {
        element.classList.add('is-hidden');
        return;
    }
    element.classList.remove('is-hidden');
    const label = document.createElement('span');
    label.className = 'chat-session-focus-label';
    label.textContent = 'Discussing';
    element.appendChild(label);
    focus.forEach((item) => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'chat-session-focus-chip';
        chip.textContent = item.displayName;
        chip.title = `Open ${item.displayName}`;
        chip.setAttribute('aria-label', `Open focal concept ${item.displayName}`);
        chip.addEventListener('click', () => {
            document.dispatchEvent(new CustomEvent('von:selectConceptById', {
                detail: {
                    conceptId: item.conceptId,
                    createConceptTab: true,
                    promoteExistingTab: true,
                    modifierKeys: { shiftKey: true }
                }
            }));
        });
        element.appendChild(chip);
    });
}

function acceptChatSessionFocus(sessionId, focalConcepts) {
    const sid = String(sessionId || '').trim();
    if (!sid) return [];
    const focus = normaliseFocusedConcepts(focalConcepts);
    chatSessionFocusCache.set(sid, focus);
    if (sid === activeChatSessionId) {
        activeChatSessionFocus = focus;
        renderActiveChatSessionFocusChips(focus);
    }
    return focus;
}

function clearChatSessionFocus(sessionId) {
    const sid = String(sessionId || '').trim();
    if (!sid) return;
    chatSessionFocusCache.delete(sid);
    if (sid === activeChatSessionId) {
        activeChatSessionFocus = [];
        renderActiveChatSessionFocusChips([]);
    }
}

async function loadChatSessionFocus(sessionId, { force = false } = {}) {
    const sid = String(sessionId || '').trim();
    if (!sid) {
        activeChatSessionFocus = [];
        renderActiveChatSessionFocusChips([]);
        return [];
    }
    if (pendingChatOrganisationSwitchId !== null) {
        return [];
    }
    const organisationGenerationAtStart = chatOrganisationGeneration;
    const cached = chatSessionFocusCache.get(sid);
    if (!force && cached) {
        if (sid === activeChatSessionId) {
            activeChatSessionFocus = cached;
            renderActiveChatSessionFocusChips(cached);
        }
        return cached;
    }
    try {
        const response = await fetch(`/von/api/session/chat_session_focus?session_id=${encodeURIComponent(sid)}`, {
            method: 'GET',
            headers: buildChatFetchHeaders({ 'Accept': 'application/json' }),
            cache: 'no-store'
        });
        const data = await response.json().catch(() => ({}));
        if (!isChatOrganisationRequestCurrent(organisationGenerationAtStart)) return [];
        if (!response.ok) {
            // Focus is an actor-authorised projection.  A cached label must not
            // remain visible after the server denies this actor access.
            clearChatSessionFocus(sid);
            return [];
        }
        if (activeChatSessionId !== sid) return [];
        return acceptChatSessionFocus(sid, getFocusFromPayload(data));
    } catch (error) {
        if (!isChatOrganisationRequestCurrent(organisationGenerationAtStart)) return [];
        console.warn('[chatTab] Unable to load conversation focus', error);
        // Fail closed: cache is only a rendering optimisation, never evidence
        // that the current actor may still see the source concepts.
        clearChatSessionFocus(sid);
        return [];
    }
}

function _resolveCurrentChatSessionTitle(sessionId) {
    const sid = (typeof sessionId === 'string' && sessionId.trim())
        ? sessionId.trim()
        : (activeChatSessionId || null);

    const activeName = (typeof activeChatSessionName === 'string' && activeChatSessionName.trim())
        ? activeChatSessionName.trim()
        : '';
    if (activeName && sid && sid === activeChatSessionId) {
        return activeName;
    }

    if (sid) {
        const sessionMeta = _getSessionMetaById(sid);
        if (sessionMeta) {
            return getSessionDisplayName(sessionMeta, { fallbackToId: false });
        }
    }

    if (activeName) {
        return activeName;
    }

    return '';
}

function _appendChatSessionCurrentTitle(container, sessionId) {
    if (!container) return;
    const title = _resolveCurrentChatSessionTitle(sessionId);
    if (!title) return;

    const titleEl = document.createElement('h2');
    titleEl.className = 'chat-session-current-title';
    titleEl.textContent = title;
    titleEl.title = title;
    titleEl.setAttribute('aria-label', `Current conversation: ${title}`);
    container.appendChild(titleEl);
}

function _normaliseChatSessionLinks(links) {
    const raw = (links && typeof links === 'object') ? links : {};
    const out = {};
    for (const { key } of CHAT_SESSION_LINK_KEYS) {
        const values = raw[key];
        const arr = Array.isArray(values) ? values : (typeof values === 'string' ? [values] : []);
        const cleaned = [];
        const seen = new Set();
        for (const item of arr) {
            if (typeof item !== 'string') continue;
            const trimmed = item.trim();
            if (!trimmed) continue;
            if (!trimmed.startsWith('#V#')) continue;
            if (seen.has(trimmed)) continue;
            seen.add(trimmed);
            cleaned.push(trimmed);
        }
        out[key] = cleaned;
    }
    return out;
}

function _normalisePotentialConceptId(text) {
    return normalisePotentialConceptId(text);
}

function _deriveNameFromConceptId(conceptId) {
    const slug = String(conceptId || '').replace(/^#V#/, '');
    if (!slug) return '';
    return slug.replace(/_/g, ' ');
}

function _getStoredOrgContext() {
    // JVNAUTOSCI-1011: Delegate to central helper
    return getSessionScopedOrgContext();
}

function _getSessionMetaById(sessionId) {
    if (!sessionId || !Array.isArray(sessionTabsCache)) return null;
    return sessionTabsCache.find((session) => String(session?.session_id || '') === String(sessionId || '')) || null;
}

function _getMostRecentSessionMeta(sessions = sessionTabsCache) {
    if (!Array.isArray(sessions)) return null;
    return sessions.find((session) => {
        const sid = typeof session?.session_id === 'string' ? session.session_id.trim() : '';
        return Boolean(sid);
    }) || null;
}

function _sessionHasNamespace(session) {
    const ns = session?.namespace;
    return typeof ns === 'string' && ns.trim().length > 0;
}

function _getOrgConceptIdFromNamespace(namespace) {
    const raw = typeof namespace === 'string' ? namespace.trim() : '';
    if (!raw || !raw.includes('@')) return null;
    const atIndex = raw.indexOf('@');
    if (atIndex <= 0) return null;
    const orgSlug = raw.slice(atIndex + 1).trim();
    if (!orgSlug) return null;
    return orgSlug.startsWith('#V#') ? orgSlug : `#V#${orgSlug}`;
}

function _getStoredNamespace() {
    // JVNAUTOSCI-1011: Delegate to central helper
    return getSessionScopedNamespace();
}

async function assignChatSessionToCurrentOrg(sessionId) {
    const sid = String(sessionId || '').trim();
    if (!sid) return;

    await _ensureInviteSessionContext();

    const ctx = getUserContext();
    if (!ctx?.org_id) {
        showToast('No organisation selected.', 'error');
        return;
    }

    try {
        const resp = await postJson('/von/api/session/assign_chat_session_org', { session_id: sid });
        const updatedNamespace = resp?.namespace;
        if (updatedNamespace) {
            sessionTabsCache = normaliseConversationSessionViewModels(
                sessionTabsCache.map((session) => {
                    if (String(session?.session_id || '') === sid) {
                        return { ...session, namespace: updatedNamespace };
                    }
                    return session;
                })
            );
        }
        showToast('Conversation updated to current organisation.', 'success');
        _renderChatSessionMetadataPanel({
            sessionId: sid,
            links: activeChatSessionLinks?.links,
            statusText: activeChatSessionLinks?.statusText,
            statusTone: activeChatSessionLinks?.statusTone,
            disabled: activeChatSessionLinks?.disabled
        });
        renderChatSessionTabs(sessionTabsCache, activeChatSessionId || sid);
    } catch (e) {
        console.error('Assign org error', e);
        showToast('Unable to assign conversation to organisation.', 'error');
    }
}

/**
 * JVNAUTOSCI-1039: Move a conversation to a different organisation.
 * Shows a simple selection interface for the user's other organisations.
 */
async function promptMoveToOrganisation(sessionId) {
    const sid = String(sessionId || '').trim();
    if (!sid) return;

    const session = _getSessionMetaById(sid);
    const currentOrgId = _getOrgConceptIdFromNamespace(session?.namespace);

    // Load user's organisations
    let organisations;
    try {
        organisations = await loadMyOrganisations();
    } catch (e) {
        console.error('Error loading organisations:', e);
        showToast('Unable to load organisations.', 'error');
        return;
    }

    if (!organisations || organisations.length === 0) {
        showToast('You are not a member of any organisations.', 'info');
        return;
    }

    // Filter out current org
    const otherOrgs = organisations.filter((org) => {
        const orgId = org.concept_id || org.id;
        const normOrg = orgId?.startsWith('#V#') ? orgId : `#V#${orgId}`;
        return normOrg !== currentOrgId;
    });

    if (otherOrgs.length === 0) {
        showToast('No other organisations available to move to.', 'info');
        return;
    }

    // Build a simple select element for organisation choice
    const selectId = `move-org-select-${Date.now()}`;
    const optionsHtml = otherOrgs.map((org) => {
        const id = org.concept_id || org.id;
        const name = org.name || id;
        const role = org.role || '';
        return `<option value="${id}">${name}${role ? ` (${role})` : ''}</option>`;
    }).join('');

    const confirmed = await new Promise((resolve) => {
        const modal = document.createElement('div');
        modal.className = 'move-org-modal-overlay';
        modal.innerHTML = `
            <div class="move-org-modal">
                <h3>Move Conversation</h3>
                <p>Select the organisation to move this conversation to:</p>
                <select id="${selectId}" class="move-org-select">
                    ${optionsHtml}
                </select>
                <p class="move-org-warning">Note: Shared access may be revoked for users not in the target organisation.</p>
                <div class="move-org-buttons">
                    <button type="button" class="btn-cancel">Cancel</button>
                    <button type="button" class="btn-move">Move</button>
                </div>
            </div>
        `;

        const cleanup = () => {
            modal.remove();
        };

        modal.querySelector('.btn-cancel').addEventListener('click', () => {
            cleanup();
            resolve(null);
        });

        modal.querySelector('.btn-move').addEventListener('click', () => {
            const select = document.getElementById(selectId);
            const targetOrgId = select?.value;
            cleanup();
            resolve(targetOrgId);
        });

        modal.addEventListener('click', (e) => {
            if (e.target === modal) {
                cleanup();
                resolve(null);
            }
        });

        document.body.appendChild(modal);
    });

    if (!confirmed) return;

    // Call the move API
    try {
        const resp = await postJson('/von/api/session/move_chat_session_org', {
            session_id: sid,
            target_organisation_id: confirmed
        });

        if (resp?.status === 'moved') {
            const revokedCount = resp.invites_revoked || 0;

            // Remove conversation from current view since it now belongs to a different namespace
            sessionTabsCache = normaliseConversationSessionViewModels(
                sessionTabsCache.filter((s) => String(s?.session_id || '') !== sid)
            );

            // If moved the active session, switch to first available or null
            if (activeChatSessionId === sid) {
                const nextSession = sessionTabsCache.find(s => s?.session_id);
                if (nextSession) {
                    await switchToChatSession(nextSession.session_id);
                } else {
                    setActiveChatSession(null, null);
                    _clearChatSessionMetadata();
                }
            }

            let msg = 'Conversation moved successfully.';
            if (revokedCount > 0) {
                msg += ` ${revokedCount} shared invite(s) revoked.`;
            }
            showToast(msg, 'success');

            renderChatSessionTabs(sessionTabsCache, activeChatSessionId);
        } else if (resp?.status === 'ok') {
            showToast(resp.message || 'Conversation already in target organisation.', 'info');
        } else {
            throw new Error(resp?.error || 'Unknown error');
        }
    } catch (e) {
        console.error('Move conversation error:', e);
        const errorMsg = e?.message || 'Unable to move conversation.';
        showToast(errorMsg, 'error');
    }
}

async function _getConceptMetaForChatSession(conceptId) {
    const id = String(conceptId || '').trim();
    if (!id || !id.startsWith('#V#')) return null;

    if (chatSessionConceptMetaCache.has(id)) {
        return chatSessionConceptMetaCache.get(id);
    }

    if (chatSessionConceptMetaInFlight.has(id)) {
        return chatSessionConceptMetaInFlight.get(id);
    }

    const request = (async () => {
        try {
            const url = `/vontology/api/vontology/node_content?identifier=${encodeURIComponent(id)}&raw_only=1`;
            const resp = await fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' } });
            if (!resp.ok) {
                return null;
            }
            const json = await resp.json();
            const preferredLanguage = getPreferredLanguage();
            const bestName = selectBestNameForContext(json?.raw_doc?.names, preferredLanguage);
            const meta = {
                displayName: bestName || json?.display_name || null,
                kind: json?.kind || json?.computed_kind || null
            };
            chatSessionConceptMetaCache.set(id, meta);
            return meta;
        } catch (_) {
            return null;
        } finally {
            chatSessionConceptMetaInFlight.delete(id);
        }
    })();

    chatSessionConceptMetaInFlight.set(id, request);
    return request;
}

function _clearChatSessionMetadata() {
    const el = getChatSessionMetadataEl();
    if (!el) return;
    el.innerHTML = '';
    el.classList.add('is-hidden');
}

function _renderChatSessionMetadataMessage(message) {
    const el = getChatSessionMetadataEl();
    if (!el) return;
    el.classList.remove('is-hidden');
    el.innerHTML = '';

    const isCollapsed = _isChatSessionMetadataCollapsed();

    _appendChatSessionCurrentTitle(el, activeChatSessionId);

    const header = document.createElement('div');
    header.className = 'chat-session-metadata-header';

    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'chat-session-metadata-toggle';
    toggle.setAttribute('aria-expanded', String(!isCollapsed));
    toggle.title = isCollapsed ? 'Show conversation context' : 'Hide conversation context';

    const toggleText = document.createElement('span');
    toggleText.className = 'chat-session-metadata-toggle-text';
    toggleText.textContent = 'Conversation context';

    const toggleIcon = document.createElement('span');
    toggleIcon.className = 'chat-session-metadata-toggle-icon';
    toggleIcon.textContent = '▾';

    toggle.appendChild(toggleText);
    toggle.appendChild(toggleIcon);
    toggle.addEventListener('click', () => {
        _setChatSessionMetadataCollapsed(!isCollapsed);
        _renderChatSessionMetadataMessage(message);
    });

    header.appendChild(toggle);
    el.appendChild(header);

    const body = document.createElement('div');
    body.className = 'chat-session-metadata-body';
    if (isCollapsed) {
        body.classList.add('is-collapsed');
    }

    const row = document.createElement('div');
    row.className = 'chat-session-metadata-row';
    const label = document.createElement('div');
    label.className = 'chat-session-metadata-label';
    label.textContent = 'Metadata';
    const values = document.createElement('div');
    values.className = 'chat-session-metadata-values';

    const msg = document.createElement('span');
    msg.style.fontSize = '13px';
    msg.style.color = '#475569';
    msg.textContent = String(message || '').trim() || '—';
    values.appendChild(msg);
    row.appendChild(label);
    row.appendChild(values);
    body.appendChild(row);
    el.appendChild(body);
}

function _buildChatSessionMetadataSuggestions({ inputEl, suggestionsEl, onPick, includeIndividuals = true }) {
    const state = { items: [], activeIndex: -1, abortController: null };
    let pointerDown = false;

    suggestionsEl.addEventListener('pointerdown', () => {
        pointerDown = true;
    });
    suggestionsEl.addEventListener('pointerup', () => {
        setTimeout(() => {
            pointerDown = false;
        }, 0);
    });

    const clearSuggestions = () => {
        state.items = [];
        state.activeIndex = -1;
        suggestionsEl.classList.remove('open');
        suggestionsEl.innerHTML = '';
        clearRetryableLoadState(suggestionsEl);
        suggestionsEl.title = '';
    };

    const setActive = (idx) => {
        state.activeIndex = idx;
        suggestionsEl.querySelectorAll('.chat-session-metadata-suggestion').forEach((el, i) => {
            if (i === idx) {
                el.classList.add('active');
            } else {
                el.classList.remove('active');
            }
        });
    };

    const render = (items) => {
        suggestionsEl.innerHTML = '';
        if (!items.length) {
            clearRetryableLoadState(suggestionsEl);
            suggestionsEl.title = '';
            suggestionsEl.classList.remove('open');
            return;
        }

        items.forEach((it, idx) => {
            const row = document.createElement('div');
            row.className = 'chat-session-metadata-suggestion';
            row.setAttribute('role', 'option');

            const name = document.createElement('span');
            name.textContent = it.name || it.id;
            name.title = `${it.name || it.id} — ${it.id}`;

            const kind = document.createElement('span');
            kind.className = 'chat-session-metadata-suggestion-kind';
            kind.textContent = it.kind === 'predicate' ? 'Predicate' : (it.kind === 'individual' ? 'Individual' : 'Type');

            row.appendChild(name);
            row.appendChild(kind);

            row.addEventListener('mouseenter', () => setActive(idx));
            row.addEventListener('mouseleave', () => setActive(-1));
            row.addEventListener('click', () => {
                onPick(it);
                clearSuggestions();
            });

            suggestionsEl.appendChild(row);
        });

        suggestionsEl.classList.add('open');
        clearRetryableLoadState(suggestionsEl);
        suggestionsEl.title = '';
    };

    const renderFailure = (query, error) => {
        const failure = describeRetryableLoadFailure(
            error,
            'Concept suggestions are temporarily unavailable.'
        );

        state.items = [];
        state.activeIndex = -1;
        suggestionsEl.innerHTML = '';
        suggestionsEl.classList.add('open');
        suggestionsEl.title = failure.message;

        const row = document.createElement('div');
        row.className = 'chat-session-metadata-suggestion chat-session-metadata-suggestion-error';
        row.textContent = failure.retryable
            ? `${failure.message} Click to retry.`
            : failure.message;

        if (failure.retryable) {
            row.tabIndex = 0;
            row.addEventListener('click', () => {
                void performSearch(query);
            });
            row.addEventListener('keydown', (event) => {
                const key = String(event?.key || '');
                if (key === 'Enter' || key === ' ' || key === 'Spacebar') {
                    event.preventDefault();
                    void performSearch(query);
                }
            });

            armRetryableLoadState(suggestionsEl, () => performSearch(query), {
                backgroundDelayMs: Math.max(0, failure.retryAfterSeconds) * 1000
            });
        } else {
            clearRetryableLoadState(suggestionsEl);
        }

        suggestionsEl.appendChild(row);
    };

    const performSearch = async (query) => {
        const q = String(query || '').trim();
        if (!q) {
            clearSuggestions();
            return;
        }

        try {
            state.abortController?.abort?.();
        } catch (_) { /* ignore */ }
        const ac = new AbortController();
        state.abortController = ac;

        const url = `/vontology/api/vontology/search?q=${encodeURIComponent(q)}&limit=12&fallback_substring=true${includeIndividuals ? '&include_individuals=true' : ''}`;
        try {
            const { data } = await getJsonDetailed(url, { signal: ac.signal });
            const items = Array.isArray(data?.results) ? data.results : [];
            state.items = items;
            state.activeIndex = -1;
            render(items);
        } catch (err) {
            if (err?.name === 'AbortError') return;
            renderFailure(q, err);
        }
    };

    const debounce = (fn, wait) => {
        let t;
        return (...args) => {
            clearTimeout(t);
            t = setTimeout(() => fn(...args), wait);
        };
    };

    const debouncedSearch = debounce(() => performSearch(inputEl.value), 200);

    inputEl.addEventListener('input', () => debouncedSearch());
    inputEl.addEventListener('focus', () => {
        if (state.items.length || suggestionsEl.childElementCount) {
            suggestionsEl.classList.add('open');
        }
    });

    inputEl.addEventListener('blur', () => {
        // Allow click selection to run first.
        setTimeout(() => {
            if (!pointerDown) {
                clearSuggestions();
            }
        }, 0);
    });

    inputEl.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            clearSuggestions();
            inputEl.blur();
            return;
        }

        if (!state.items.length) {
            if (e.key === 'Enter') {
                const maybeId = _normalisePotentialConceptId(inputEl.value);
                if (maybeId) {
                    e.preventDefault();
                    onPick({ id: maybeId, name: null, kind: 'individual' });
                    inputEl.value = '';
                    clearSuggestions();
                }
            }
            return;
        }

        if (e.key === 'ArrowDown') {
            e.preventDefault();
            setActive(Math.min(state.activeIndex + 1, state.items.length - 1));
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            setActive(Math.max(state.activeIndex - 1, 0));
        } else if (e.key === 'Enter') {
            e.preventDefault();
            const idx = (state.activeIndex >= 0) ? state.activeIndex : 0;
            const chosen = state.items[idx];
            if (chosen) {
                onPick(chosen);
                inputEl.value = '';
                clearSuggestions();
            }
        }
    });

    return { clearSuggestions };
}

function _escapeCssValue(value) {
    const raw = String(value ?? '');
    if (typeof CSS !== 'undefined' && typeof CSS.escape === 'function') {
        return CSS.escape(raw);
    }
    return raw.replace(/[^a-zA-Z0-9_-]/g, '_');
}

function _isChatSessionMetadataCollapsed() {
    if (typeof chatSessionMetadataCollapsed === 'boolean') {
        return chatSessionMetadataCollapsed;
    }
    try {
        const stored = window.localStorage.getItem(LS_CHAT_SESSION_METADATA_COLLAPSED);
        chatSessionMetadataCollapsed = stored === null ? true : stored === 'true';
    } catch (_) {
        chatSessionMetadataCollapsed = true;
    }
    return chatSessionMetadataCollapsed;
}

function _setChatSessionMetadataCollapsed(value) {
    chatSessionMetadataCollapsed = !!value;
    try {
        window.localStorage.setItem(LS_CHAT_SESSION_METADATA_COLLAPSED, chatSessionMetadataCollapsed ? 'true' : 'false');
    } catch (_) {
        // ignore
    }
}

function _renderChatSessionMetadataPanel({ sessionId, links, statusText, statusTone, disabled }) {
    const el = getChatSessionMetadataEl();
    if (!el) return;

    const sid = String(sessionId || '').trim();
    if (!sid) {
        _clearChatSessionMetadata();
        return;
    }

    el.classList.remove('is-hidden');
    el.innerHTML = '';

    const isCollapsed = _isChatSessionMetadataCollapsed();
    if (isCollapsed && chatSessionMetadataOpenKey) {
        chatSessionMetadataOpenKey = null;
    }

    _appendChatSessionCurrentTitle(el, sid);

    const header = document.createElement('div');
    header.className = 'chat-session-metadata-header';

    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'chat-session-metadata-toggle';
    toggle.setAttribute('aria-expanded', String(!isCollapsed));
    toggle.title = isCollapsed ? 'Show conversation context' : 'Hide conversation context';
    toggle.disabled = false;

    const toggleText = document.createElement('span');
    toggleText.className = 'chat-session-metadata-toggle-text';
    toggleText.textContent = 'Conversation context';

    const toggleIcon = document.createElement('span');
    toggleIcon.className = 'chat-session-metadata-toggle-icon';
    toggleIcon.textContent = '▾';

    toggle.appendChild(toggleText);
    toggle.appendChild(toggleIcon);
    toggle.addEventListener('click', () => {
        _setChatSessionMetadataCollapsed(!isCollapsed);
        _renderChatSessionMetadataPanel({
            sessionId: sid,
            links: activeChatSessionLinks?.links,
            statusText: activeChatSessionLinks?.statusText,
            statusTone: activeChatSessionLinks?.statusTone,
            disabled: activeChatSessionLinks?.disabled
        });
    });

    header.appendChild(toggle);
    el.appendChild(header);

    if (statusText) {
        const statusRow = document.createElement('div');
        statusRow.className = 'chat-session-metadata-row';
        const label = document.createElement('div');
        label.className = 'chat-session-metadata-label';
        label.textContent = 'Status';
        const values = document.createElement('div');
        values.className = 'chat-session-metadata-values';
        const status = document.createElement('span');
        status.style.fontSize = '12px';
        status.style.color = statusTone === 'error' ? '#b91c1c' : '#64748b';
        status.textContent = statusText;
        values.appendChild(status);
        statusRow.appendChild(label);
        statusRow.appendChild(values);
        el.appendChild(statusRow);
    }

    const body = document.createElement('div');
    body.className = 'chat-session-metadata-body';
    if (isCollapsed) {
        body.classList.add('is-collapsed');
    }

    const sessionMeta = _getSessionMetaById(sid);
    const sessionNamespace = typeof sessionMeta?.namespace === 'string' ? sessionMeta.namespace.trim() : '';
    const sessionOrgId = _getOrgConceptIdFromNamespace(sessionNamespace);
    const sessionOrgName = sessionOrgId ? _deriveNameFromConceptId(sessionOrgId) || sessionOrgId : '';
    const orgCtx = _getStoredOrgContext();
    const storedNamespace = _getStoredNamespace();
    const orgFromNamespace = _getOrgConceptIdFromNamespace(storedNamespace);
    const orgId = orgCtx?.concept_id || orgCtx?.id || getUserContext()?.org_id || orgFromNamespace || null;
    const orgName = orgCtx?.name || _deriveNameFromConceptId(orgId) || orgId || '';
    const isSharedSession = !!(sessionMeta?.shared_with_me || sessionMeta?.shared_from_user_id || sessionMeta?.invite_id);
    const showAssignOrg = !disabled && !!orgId && !isSharedSession && (!sessionMeta || !_sessionHasNamespace(sessionMeta));

    if (showAssignOrg) {
        const row = document.createElement('div');
        row.className = 'chat-session-metadata-row';

        const label = document.createElement('div');
        label.className = 'chat-session-metadata-label';
        label.textContent = 'Organisation';

        const values = document.createElement('div');
        values.className = 'chat-session-metadata-values';

        const info = document.createElement('span');
        info.style.fontSize = '12px';
        info.style.color = '#475569';
        info.textContent = orgName ? `Assign to ${orgName}` : 'Assign to current organisation';

        const actions = document.createElement('div');
        actions.className = 'chat-session-metadata-actions';

        const assignBtn = document.createElement('button');
        assignBtn.type = 'button';
        assignBtn.className = 'btn-mini';
        assignBtn.textContent = 'Set to current org';
        assignBtn.addEventListener('click', () => assignChatSessionToCurrentOrg(sid));

        actions.appendChild(assignBtn);
        values.appendChild(info);
        values.appendChild(actions);
        row.appendChild(label);
        row.appendChild(values);
        body.appendChild(row);
    }

    if (sessionOrgId) {
        const row = document.createElement('div');
        row.className = 'chat-session-metadata-row';

        const label = document.createElement('div');
        label.className = 'chat-session-metadata-label';
        label.textContent = 'Organisation';

        const values = document.createElement('div');
        values.className = 'chat-session-metadata-values';

        const nameEl = document.createElement('span');
        nameEl.style.fontSize = '12px';
        nameEl.style.color = '#475569';
        nameEl.textContent = sessionOrgName || sessionOrgId;

        values.appendChild(nameEl);
        row.appendChild(label);
        row.appendChild(values);
        body.appendChild(row);
    } else if (isSharedSession) {
        const row = document.createElement('div');
        row.className = 'chat-session-metadata-row';

        const label = document.createElement('div');
        label.className = 'chat-session-metadata-label';
        label.textContent = 'Organisation';

        const values = document.createElement('div');
        values.className = 'chat-session-metadata-values';

        const nameEl = document.createElement('span');
        nameEl.style.fontSize = '12px';
        nameEl.style.color = '#64748b';
        nameEl.textContent = 'No organisation assigned';

        values.appendChild(nameEl);
        row.appendChild(label);
        row.appendChild(values);
        body.appendChild(row);
    }

    const safeLinks = _normaliseChatSessionLinks(links);

    for (const group of CHAT_SESSION_LINK_KEYS) {
        const row = document.createElement('div');
        row.className = 'chat-session-metadata-row';

        const label = document.createElement(group.typeConceptId ? 'button' : 'div');
        label.className = group.typeConceptId
            ? 'chat-session-metadata-label chat-session-metadata-label-link'
            : 'chat-session-metadata-label';
        label.textContent = group.label;
        if (group.typeConceptId) {
            label.type = 'button';
            label.title = `Open ${group.label} type concept`;
            label.disabled = !!disabled;
            label.addEventListener('click', (e) => {
                e.preventDefault();
                document.dispatchEvent(new CustomEvent('von:selectConceptById', {
                    detail: { conceptId: group.typeConceptId, createConceptTab: true }
                }));
            });
        }

        const values = document.createElement('div');
        values.className = 'chat-session-metadata-values';

        const ids = Array.isArray(safeLinks[group.key]) ? safeLinks[group.key] : [];
        ids.forEach((conceptId) => {
            const chip = document.createElement('span');
            chip.className = 'chat-session-metadata-chip';

            const link = document.createElement('a');
            link.href = '#';
            const cached = chatSessionConceptMetaCache.get(conceptId);
            link.textContent = cached?.displayName || _deriveNameFromConceptId(conceptId) || conceptId;
            link.title = `${cached?.displayName || conceptId} — ${conceptId}`;
            link.addEventListener('click', (e) => {
                e.preventDefault();
                document.dispatchEvent(new CustomEvent('von:selectConceptById', {
                    detail: { conceptId, createConceptTab: true }
                }));
            });
            chip.appendChild(link);

            const removeBtn = document.createElement('button');
            removeBtn.type = 'button';
            removeBtn.className = 'chat-session-metadata-chip-remove';
            removeBtn.textContent = '×';
            removeBtn.title = `Remove ${conceptId}`;
            removeBtn.disabled = !!disabled;
            removeBtn.addEventListener('click', (e) => {
                e.preventDefault();
                e.stopPropagation();
                removeChatSessionLink(group.key, conceptId);
            });
            chip.appendChild(removeBtn);

            values.appendChild(chip);

            if (!cached && !chatSessionConceptMetaInFlight.has(conceptId)) {
                void _getConceptMetaForChatSession(conceptId).then(() => {
                    if (activeChatSessionLinks?.sessionId === sid) {
                        _renderChatSessionMetadataPanel({
                            sessionId: sid,
                            links: activeChatSessionLinks?.links,
                            statusText: activeChatSessionLinks?.statusText,
                            statusTone: activeChatSessionLinks?.statusTone,
                            disabled: activeChatSessionLinks?.disabled
                        });
                    }
                });
            }
        });

        const actions = document.createElement('div');
        actions.className = 'chat-session-metadata-actions';

        const addBtn = document.createElement('button');
        addBtn.type = 'button';
        addBtn.className = 'chat-session-metadata-add';
        addBtn.textContent = '+';
        addBtn.title = `Add ${group.label}`;
        addBtn.disabled = !!disabled;

        const inputWrap = document.createElement('div');
        inputWrap.className = 'chat-session-metadata-inputwrap';
        inputWrap.dataset.linkKey = group.key;
        inputWrap.style.display = (chatSessionMetadataOpenKey === group.key) ? 'block' : 'none';

        const input = document.createElement('input');
        input.className = 'chat-session-metadata-input';
        input.type = 'text';
        input.placeholder = group.placeholder;
        input.disabled = !!disabled;

        const suggestions = document.createElement('div');
        suggestions.className = 'chat-session-metadata-suggestions';
        suggestions.setAttribute('role', 'listbox');

        inputWrap.appendChild(input);
        inputWrap.appendChild(suggestions);

        addBtn.addEventListener('click', () => {
            if (chatSessionMetadataOpenKey === group.key) {
                chatSessionMetadataOpenKey = null;
                _renderChatSessionMetadataPanel({
                    sessionId: sid,
                    links: activeChatSessionLinks?.links,
                    statusText: activeChatSessionLinks?.statusText,
                    statusTone: activeChatSessionLinks?.statusTone,
                    disabled: activeChatSessionLinks?.disabled
                });
                return;
            }
            chatSessionMetadataOpenKey = group.key;
            _renderChatSessionMetadataPanel({
                sessionId: sid,
                links: activeChatSessionLinks?.links,
                statusText: activeChatSessionLinks?.statusText,
                statusTone: activeChatSessionLinks?.statusTone,
                disabled: activeChatSessionLinks?.disabled
            });

            setTimeout(() => {
                const container = getChatSessionMetadataEl();
                if (!container) return;
                const escapedKey = _escapeCssValue(group.key);
                const target = container.querySelector(`.chat-session-metadata-inputwrap[data-link-key="${escapedKey}"] .chat-session-metadata-input`);
                try { target?.focus?.(); } catch (_) { /* ignore */ }
            }, 0);
        });

        actions.appendChild(addBtn);
        actions.appendChild(inputWrap);
        values.appendChild(actions);

        row.appendChild(label);
        row.appendChild(values);
        body.appendChild(row);

        if (chatSessionMetadataOpenKey === group.key && !disabled && !isCollapsed) {
            // Wire autocomplete + focus.
            _buildChatSessionMetadataSuggestions({
                inputEl: input,
                suggestionsEl: suggestions,
                includeIndividuals: true,
                onPick: (it) => {
                    const picked = _normalisePotentialConceptId(it?.id) || (typeof it?.id === 'string' ? it.id.trim() : '');
                    if (!picked) {
                        showToast('Select a valid concept.', 'error');
                        return;
                    }
                    addChatSessionLink(group.key, picked);
                }
            });
            setTimeout(() => {
                try { input.focus(); } catch (_) { /* ignore */ }
            }, 0);
        }
    }

    el.appendChild(body);
}

function _setActiveChatSessionLinksState(state) {
    activeChatSessionLinks = state;
    _renderChatSessionMetadataPanel({
        sessionId: state?.sessionId,
        links: state?.links,
        statusText: state?.statusText,
        statusTone: state?.statusTone,
        disabled: state?.disabled
    });
}

function _scheduleSaveChatSessionLinks(sessionId, links) {
    const sid = String(sessionId || '').trim();
    if (!sid) return;
    chatSessionLinksDirtySessionId = sid;
    chatSessionLinksDirtyPayload = links;

    if (chatSessionLinksSaveDebounceId) {
        clearTimeout(chatSessionLinksSaveDebounceId);
        chatSessionLinksSaveDebounceId = null;
    }

    chatSessionLinksSaveDebounceId = setTimeout(() => {
        chatSessionLinksSaveDebounceId = null;
        void saveChatSessionLinks(sid, chatSessionLinksDirtyPayload);
    }, 650);
}

async function _flushPendingChatSessionLinksSave(sessionId) {
    const sid = String(sessionId || '').trim();
    if (!sid) return;
    if (!chatSessionLinksDirtySessionId || chatSessionLinksDirtySessionId !== sid) return;
    if (chatSessionLinksSaveDebounceId) {
        clearTimeout(chatSessionLinksSaveDebounceId);
        chatSessionLinksSaveDebounceId = null;
    }
    await saveChatSessionLinks(sid, chatSessionLinksDirtyPayload);
}

function addChatSessionLink(key, conceptId) {
    const sid = activeChatSessionLinks?.sessionId;
    if (!sid || sid !== activeChatSessionId) return;
    const safeKey = String(key || '').trim();
    const id = _normalisePotentialConceptId(conceptId);
    if (!safeKey || !id) return;

    const current = _normaliseChatSessionLinks(activeChatSessionLinks?.links);
    const list = Array.isArray(current[safeKey]) ? current[safeKey].slice() : [];
    if (list.includes(id)) {
        showToast('Already added.', 'info');
        return;
    }
    list.push(id);
    current[safeKey] = list;

    chatSessionLinksCache.set(sid, current);
    _setActiveChatSessionLinksState({
        sessionId: sid,
        links: current,
        statusText: 'Saving…',
        statusTone: 'info',
        disabled: false
    });
    _scheduleSaveChatSessionLinks(sid, current);
}

function removeChatSessionLink(key, conceptId) {
    const sid = activeChatSessionLinks?.sessionId;
    if (!sid || sid !== activeChatSessionId) return;
    const safeKey = String(key || '').trim();
    const id = String(conceptId || '').trim();
    if (!safeKey || !id) return;

    const current = _normaliseChatSessionLinks(activeChatSessionLinks?.links);
    const list = Array.isArray(current[safeKey]) ? current[safeKey].slice() : [];
    const next = list.filter(v => v !== id);
    current[safeKey] = next;

    chatSessionLinksCache.set(sid, current);
    _setActiveChatSessionLinksState({
        sessionId: sid,
        links: current,
        statusText: 'Saving…',
        statusTone: 'info',
        disabled: false
    });
    _scheduleSaveChatSessionLinks(sid, current);
}

async function loadChatSessionLinks(sessionId, options = {}) {
    const sid = String(sessionId || '').trim();
    if (!sid) {
        _clearChatSessionMetadata();
        return;
    }
    if (pendingChatOrganisationSwitchId !== null) {
        return;
    }
    const organisationGenerationAtStart = chatOrganisationGeneration;

    const force = options.force === true;
    const cached = chatSessionLinksCache.get(sid);
    if (!force && cached) {
        _setActiveChatSessionLinksState({ sessionId: sid, links: cached, statusText: '', statusTone: 'info', disabled: false });
        return;
    }

    try {
        chatSessionLinksLoadInFlight?.abortController?.abort?.();
    } catch (_) { /* ignore */ }
    const abortController = new AbortController();
    chatSessionLinksLoadInFlight = { sessionId: sid, abortController };

    _setActiveChatSessionLinksState({ sessionId: sid, links: cached || {}, statusText: 'Loading…', statusTone: 'info', disabled: true });

    try {
        const resp = await fetch(`/von/api/session/chat_session_links?session_id=${encodeURIComponent(sid)}`, {
            method: 'GET',
            headers: buildChatFetchHeaders({ 'Accept': 'application/json' }),
            cache: 'no-store',
            signal: abortController.signal
        });
        const data = await resp.json().catch(() => ({}));

        if (abortController.signal.aborted) return;
        if (!isChatOrganisationRequestCurrent(organisationGenerationAtStart)) return;
        if (activeChatSessionId !== sid) return;

        if (resp.status === 401 || data?.error === 'Not authenticated') {
            chatSessionMetadataOpenKey = null;
            _renderChatSessionMetadataMessage('Log in to view/edit conversation metadata.');
            return;
        }

        if (!resp.ok) {
            _setActiveChatSessionLinksState({ sessionId: sid, links: cached || {}, statusText: 'Unable to load metadata.', statusTone: 'error', disabled: false });
            return;
        }

        const links = _normaliseChatSessionLinks(data?.session_links);
        chatSessionLinksCache.set(sid, links);
        _setActiveChatSessionLinksState({ sessionId: sid, links, statusText: '', statusTone: 'info', disabled: false });
    } catch (err) {
        if (err?.name === 'AbortError' || !isChatOrganisationRequestCurrent(organisationGenerationAtStart)) return;
        _setActiveChatSessionLinksState({ sessionId: sid, links: cached || {}, statusText: 'Unable to load metadata.', statusTone: 'error', disabled: false });
    }
}

async function saveChatSessionLinks(sessionId, links) {
    const sid = String(sessionId || '').trim();
    if (!sid) return;
    const payload = _normaliseChatSessionLinks(links);

    // Avoid parallel saves; last write wins.
    try {
        chatSessionLinksSaveInFlight?.abortController?.abort?.();
    } catch (_) { /* ignore */ }
    const abortController = new AbortController();
    chatSessionLinksSaveInFlight = { sessionId: sid, abortController };

    try {
        const resp = await fetch('/von/api/session/chat_session_links', {
            method: 'POST',
            headers: buildChatFetchHeaders({ 'Content-Type': 'application/json', 'Accept': 'application/json' }),
            body: JSON.stringify({ session_id: sid, session_links: payload }),
            signal: abortController.signal
        });
        const data = await resp.json().catch(() => ({}));
        if (abortController.signal.aborted) return;
        if (activeChatSessionId !== sid) return;

        if (resp.status === 401 || data?.error === 'Not authenticated') {
            _renderChatSessionMetadataMessage('Log in to view/edit conversation metadata.');
            return;
        }

        if (!resp.ok) {
            _setActiveChatSessionLinksState({ sessionId: sid, links: payload, statusText: 'Save failed.', statusTone: 'error', disabled: false });
            return;
        }

        const saved = _normaliseChatSessionLinks(data?.session_links || payload);
        chatSessionLinksCache.set(sid, saved);
        chatSessionLinksDirtySessionId = null;
        chatSessionLinksDirtyPayload = null;
        _setActiveChatSessionLinksState({ sessionId: sid, links: saved, statusText: 'Saved', statusTone: 'info', disabled: false });
        setTimeout(() => {
            if (activeChatSessionLinks?.sessionId === sid && activeChatSessionLinks?.statusText === 'Saved') {
                _setActiveChatSessionLinksState({ sessionId: sid, links: saved, statusText: '', statusTone: 'info', disabled: false });
            }
        }, 1200);
    } catch (err) {
        if (err?.name === 'AbortError') return;
        _setActiveChatSessionLinksState({ sessionId: sid, links: payload, statusText: 'Save failed.', statusTone: 'error', disabled: false });
    }
}

function getChatTabButton() {
    return document.querySelector('.tab-button[data-tab="chatTab"]');
}

function getChatSessionTabById(sessionId) {
    const container = getChatSessionTabsContainer();
    const sid = String(sessionId || '').trim();
    if (!container || !sid) {
        return null;
    }
    const escaped = (typeof CSS !== 'undefined' && typeof CSS.escape === 'function')
        ? CSS.escape(sid)
        : sid.replace(/"/g, '\\"');
    return container.querySelector(`.chat-session-tab[data-session-id="${escaped}"]`);
}

function setChatSessionTabLoading(sessionId, isLoading) {
    const sid = String(sessionId || '').trim();
    const container = getChatSessionTabsContainer();
    if (!container) {
        if (!isLoading && loadingChatSessionId === sid) {
            loadingChatSessionId = null;
        } else if (isLoading && sid) {
            loadingChatSessionId = sid;
        }
        return;
    }

    if (loadingChatSessionId && loadingChatSessionId !== sid) {
        const previousTab = getChatSessionTabById(loadingChatSessionId);
        if (previousTab) {
            previousTab.classList.remove('is-loading');
        }
    }

    if (!isLoading) {
        if (loadingChatSessionId === sid) {
            const targetTab = getChatSessionTabById(sid);
            if (targetTab) {
                targetTab.classList.remove('is-loading');
            }
            loadingChatSessionId = null;
        }
        return;
    }

    if (sid) {
        loadingChatSessionId = sid;
        const targetTab = getChatSessionTabById(sid);
        if (targetTab) {
            targetTab.classList.add('is-loading');
        }
    }
}

function getShortSessionId(sessionId) {
    const sid = String(sessionId || '').trim();
    if (!sid) {
        return 'session';
    }
    return sid.length > 10 ? `${sid.slice(0, 8)}.` : sid;
}

function getSessionDisplayName(session, { fallbackToId = true } = {}) {
    const rawName = (typeof session?.session_name === 'string' && session.session_name.trim())
        ? session.session_name.trim()
        : '';
    if (rawName) {
        return rawName;
    }
    return fallbackToId ? getShortSessionId(session?.session_id) : '';
}

function formatCompletedLabel(isoString) {
    if (!isoString) {
        return 'completed';
    }
    const parsed = new Date(isoString);
    if (Number.isNaN(parsed.getTime())) {
        return 'completed';
    }
    const formatted = parsed.toLocaleString('en-NZ', {
        year: 'numeric',
        month: 'short',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit'
    });
    return `completed ${formatted}`;
}

function formatSessionTimestamp(isoString) {
    if (!isoString) {
        return '';
    }
    const parsed = new Date(isoString);
    if (Number.isNaN(parsed.getTime())) {
        return '';
    }

    const now = new Date();
    const isToday = now.getFullYear() === parsed.getFullYear()
        && now.getMonth() === parsed.getMonth()
        && now.getDate() === parsed.getDate();

    if (isToday) {
        return parsed.toLocaleTimeString('en-NZ', {
            hour: '2-digit',
            minute: '2-digit'
        });
    }

    return parsed.toLocaleDateString('en-NZ', {
        day: '2-digit',
        month: 'short'
    });
}

function scheduleChatSessionTabsRefresh(force = false) {
    if (force) {
        void refreshChatSessionTabs();
        return;
    }

    const now = Date.now();
    const elapsed = now - lastSessionTabsRefreshMs;
    if (elapsed >= SESSION_TABS_REFRESH_COOLDOWN_MS) {
        void refreshChatSessionTabs();
        return;
    }

    if (pendingSessionTabsRefresh) {
        return;
    }

    pendingSessionTabsRefresh = setTimeout(() => {
        pendingSessionTabsRefresh = null;
        void refreshChatSessionTabs();
    }, Math.max(500, SESSION_TABS_REFRESH_COOLDOWN_MS - elapsed));
}

function _chatTabsNowPerfMs() {
    try {
        if (typeof performance !== 'undefined' && typeof performance.now === 'function') {
            return performance.now();
        }
    } catch (_) {
        // ignore
    }
    return Date.now();
}

function _getChatTabsLoadStats() {
    try {
        const raw = localStorage.getItem(LS_CHAT_TABS_LOAD_STATS);
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') return null;
        const emaMs = Number(parsed.ema_ms);
        const samples = Number(parsed.samples);
        const lastMs = Number(parsed.last_ms);
        return {
            ema_ms: Number.isFinite(emaMs) ? emaMs : null,
            samples: Number.isFinite(samples) ? samples : 0,
            last_ms: Number.isFinite(lastMs) ? lastMs : null,
            last_at: typeof parsed.last_at === 'string' ? parsed.last_at : null
        };
    } catch (_) {
        return null;
    }
}

function _storeChatTabsLoadStats(durationMs) {
    const ms = Number(durationMs);
    if (!Number.isFinite(ms) || ms <= 0) return;

    const existing = _getChatTabsLoadStats() || { ema_ms: null, samples: 0, last_ms: null, last_at: null };
    const prev = Number(existing.ema_ms);
    const hasPrev = Number.isFinite(prev) && prev > 0;
    const alpha = 0.30;
    const ema = hasPrev ? (prev * (1 - alpha) + ms * alpha) : ms;
    const samples = (Number.isFinite(existing.samples) ? existing.samples : 0) + 1;

    try {
        localStorage.setItem(LS_CHAT_TABS_LOAD_STATS, JSON.stringify({
            ema_ms: Math.round(ema),
            samples,
            last_ms: Math.round(ms),
            last_at: new Date().toISOString()
        }));
    } catch (_) {
        // ignore localStorage failures
    }
}

function _stopChatTabsLoadingTicker() {
    if (chatTabsLoadingTickerId) {
        clearInterval(chatTabsLoadingTickerId);
        chatTabsLoadingTickerId = null;
    }
    chatTabsLoadingTickerLastRenderedSec = -1;
}

function _startChatTabsLoadingTicker() {
    _stopChatTabsLoadingTicker();

    chatTabsLoadingTickerId = setInterval(() => {
        try {
            const container = getChatSessionTabsContainer();
            if (!container || container.hidden) {
                _stopChatTabsLoadingTicker();
                return;
            }

            const placeholder = container.querySelector('.chat-session-tabs-placeholder.is-loading');
            if (!placeholder) {
                _stopChatTabsLoadingTicker();
                return;
            }

            const telemetryEl = placeholder.querySelector('.chat-session-tabs-placeholder-telemetry');
            if (!telemetryEl) {
                return;
            }

            if (!Number.isFinite(chatTabsFirstLoadStartPerfMs)) {
                telemetryEl.textContent = '';
                return;
            }

            const elapsedMs = Math.max(0, _chatTabsNowPerfMs() - chatTabsFirstLoadStartPerfMs);
            const elapsedSec = Math.floor(elapsedMs / 1000);
            if (elapsedSec === chatTabsLoadingTickerLastRenderedSec) {
                return;
            }
            chatTabsLoadingTickerLastRenderedSec = elapsedSec;

            const stats = _getChatTabsLoadStats();
            const expectedMs = Number(stats?.ema_ms);
            const hasExpected = Number.isFinite(expectedMs) && expectedMs > 250;
            const etaSec = hasExpected ? Math.max(0, Math.round((expectedMs - elapsedMs) / 1000)) : null;

            const parts = [];
            parts.push(`elapsed ${elapsedSec}s`);
            if (etaSec !== null) {
                parts.push(`ETA ~${etaSec}s`);
            }

            telemetryEl.textContent = parts.length ? `• ${parts.join(' • ')}` : '';
        } catch (_) {
            // Best-effort ticker.
        }
    }, 500);
}

function openSettingsToLogin() {
    const opened = openSettingsTabAndFocus('von:focus-current-user-settings');
    if (!opened) {
        const err = new Error('Failed to open settings tab');
        console.warn('[chatTab] Failed to open Settings for login:', err);
        try { showToast('Unable to open Settings for login.', true); } catch (_) { }
    }
}

function getNewChatMenuAnchor(button, event = null) {
    const clientX = Number(event?.clientX);
    const clientY = Number(event?.clientY);
    if (Number.isFinite(clientX) && Number.isFinite(clientY) && (clientX !== 0 || clientY !== 0)) {
        return { x: clientX, y: clientY };
    }
    const rect = button?.getBoundingClientRect?.();
    return {
        x: Number(rect?.left || 0) + 8,
        y: Number(rect?.bottom || 0) + 4
    };
}

function openNewChatOptions(button, event = null) {
    const { x, y } = getNewChatMenuAnchor(button, event);
    openChatSessionMenu(x, y, buildNewChatContextMenuItems(), {
        focusFirst: true,
        returnFocus: button
    });
}

function createNewChatTabButton() {
    const newTab = document.createElement('button');
    newTab.type = 'button';
    newTab.className = 'chat-session-tab chat-session-tab-new';
    newTab.title = 'New conversation. Modifier-click, right-click, or press Shift+F10 for conversation-list options.';
    newTab.setAttribute('aria-label', 'New conversation');
    newTab.setAttribute('aria-haspopup', 'menu');
    newTab.setAttribute('aria-keyshortcuts', 'Shift+F10');
    newTab.textContent = '+';

    newTab.addEventListener('click', (event) => {
        if (event?.ctrlKey || event?.metaKey) {
            event.preventDefault();
            event.stopPropagation();
            openNewChatOptions(newTab, event);
            return;
        }
        void createNewChatSession();
    });
    newTab.addEventListener('contextmenu', (event) => {
        event.preventDefault();
        event.stopPropagation();
        openNewChatOptions(newTab, event);
    });
    newTab.addEventListener('keydown', (event) => {
        const opensContextMenu = event.key === 'ContextMenu' || (event.shiftKey && event.key === 'F10');
        if (!opensContextMenu) {
            return;
        }
        event.preventDefault();
        event.stopPropagation();
        openNewChatOptions(newTab, event);
    });

    return newTab;
}

function renderChatSessionTabsPlaceholder(mode = 'loading') {
    const container = getChatSessionTabsContainer();
    if (!container) {
        return;
    }
    const historyControls = document.getElementById('chatSessionHistoryControls');

    container.hidden = false;
    container.innerHTML = '';
    if (historyControls) historyControls.innerHTML = '';

    setChatSessionCount(null);

    const fragment = document.createDocumentFragment();

    const allowNewChat = mode !== 'unauthenticated';
    if (allowNewChat) {
        fragment.appendChild(createNewChatTabButton());
    }

    const placeholder = document.createElement('div');
    placeholder.className = 'chat-session-tabs-placeholder';

    const primary = document.createElement('span');
    primary.className = 'chat-session-tabs-placeholder-primary';

    const telemetry = document.createElement('span');
    telemetry.className = 'chat-session-tabs-placeholder-telemetry';

    if (mode === 'unauthenticated') {
        primary.textContent = 'Log in to load your saved conversations.';
    } else if (mode === 'error') {
        primary.textContent = 'Unable to load conversations right now (will retry).';
    } else if (mode === 'empty') {
        primary.textContent = 'No saved conversations yet.';
    } else {
        primary.textContent = 'Loading conversations…';
        placeholder.classList.add('is-loading');
    }

    placeholder.appendChild(primary);
    placeholder.appendChild(telemetry);

    fragment.appendChild(placeholder);

    if (mode === 'unauthenticated') {
        const loginTab = document.createElement('button');
        loginTab.type = 'button';
        loginTab.className = 'chat-session-tab';
        loginTab.title = 'Open Settings to log in';
        loginTab.setAttribute('aria-label', 'Open Settings to log in');
        loginTab.textContent = 'Log in';
        loginTab.addEventListener('click', () => {
            openSettingsToLogin();
        });
        fragment.appendChild(loginTab);
    }

    if (mode === 'error') {
        const retryTab = document.createElement('button');
        retryTab.type = 'button';
        retryTab.className = 'chat-session-tab';
        retryTab.title = 'Retry loading conversations';
        retryTab.setAttribute('aria-label', 'Retry loading conversations');
        retryTab.textContent = 'Retry';
        retryTab.addEventListener('click', () => {
            scheduleChatSessionTabsRefresh(true);
        });
        fragment.appendChild(retryTab);
    }

    container.appendChild(fragment);
}

async function refreshChatSessionTabs() {
    const container = getChatSessionTabsContainer();
    if (!container) {
        return;
    }
    if (pendingChatOrganisationSwitchId !== null) {
        renderChatSessionTabsPlaceholder('loading');
        container.hidden = false;
        return;
    }
    const organisationGenerationAtStart = chatOrganisationGeneration;
    const selectionGenerationAtStart = chatSessionSelectionGeneration;
    await _ensureInviteSessionContext();
    if (!isChatOrganisationRequestCurrent(organisationGenerationAtStart)) {
        return;
    }

    const hasCachedTabs = Array.isArray(sessionTabsCache) && sessionTabsCache.length > 0;
    const containerLooksEmpty = container.hidden || !container.firstElementChild;

    // If we're about to load sessions and there's nothing visible yet, keep a placeholder
    // in the tabs bar so the controls don't disappear.
    if (!hasCachedTabs && containerLooksEmpty) {
        if (!Number.isFinite(chatTabsFirstLoadStartPerfMs)) {
            chatTabsFirstLoadStartPerfMs = _chatTabsNowPerfMs();
            chatTabsFirstLoadStartEpochMs = Date.now();
        }
        renderChatSessionTabsPlaceholder('loading');
        _startChatTabsLoadingTicker();
    }

    // Avoid UI flicker: if we have a last-known-good session list, keep it visible
    // while refresh is in flight (and especially if the container was previously hidden).
    if (container.hidden && hasCachedTabs) {
        renderChatSessionTabs(sessionTabsCache, activeChatSessionId);
    }

    if (pendingSessionTabsRefresh) {
        clearTimeout(pendingSessionTabsRefresh);
        pendingSessionTabsRefresh = null;
    }

    lastSessionTabsRefreshMs = Date.now();
    const abortController = new AbortController();
    chatSessionTabsFetchAbortControllers.add(abortController);

    try {
        const response = await fetch(buildChatSessionTabsFetchUrl(), {
            cache: 'no-store',
            headers: buildChatFetchHeaders(),
            signal: abortController.signal
        });
        const data = await response.json();

        // Every organisation-scoped response is bound to the generation in
        // which it started. Aborting is best effort; this fence also rejects
        // mocks, caches, and transports that complete after abort.
        if (!isChatOrganisationRequestCurrent(organisationGenerationAtStart)) {
            return;
        }

        if (data?.authenticated === false) {
            _stopChatTabsLoadingTicker();
            renderChatSessionTabsPlaceholder('unauthenticated');
            lastRenderedSessionCount = 0;
            sessionTabsCache = [];
            chatSessionMetadataOpenKey = null;
            _clearChatSessionMetadata();
            return;
        }

        if (data?.degraded === true) {
            console.warn('[chatTab] Chat session refresh degraded; keeping existing tabs where possible', {
                status: response.status,
                data
            });
            if (hasCachedTabs) {
                renderChatSessionTabs(sessionTabsCache, activeChatSessionId);
                container.hidden = false;
            } else {
                _stopChatTabsLoadingTicker();
                renderChatSessionTabsPlaceholder('error');
            }
            setTimeout(() => scheduleChatSessionTabsRefresh(true), 2000);
            return;
        }

        if (!response.ok) {
            console.warn('[chatTab] Failed to refresh chat sessions (keeping existing tabs)', {
                status: response.status,
                data
            });
            if (hasCachedTabs) {
                container.hidden = false;
            } else {
                _stopChatTabsLoadingTicker();
                renderChatSessionTabsPlaceholder('error');
                setTimeout(() => scheduleChatSessionTabsRefresh(true), 2000);
            }
            return;
        }

        // A refresh can begin before an explicit session change and return after it.
        // Never let that stale response erase a chat that was just selected or created.
        if (chatSessionSelectionGeneration !== selectionGenerationAtStart) {
            if (Array.isArray(sessionTabsCache) && sessionTabsCache.length > 0) {
                renderChatSessionTabs(sessionTabsCache, activeChatSessionId);
                container.hidden = false;
            }
            setTimeout(() => scheduleChatSessionTabsRefresh(true), 0);
            return;
        }

        const sessions = Array.isArray(data?.sessions) ? data.sessions : [];
        serverAgentCreatedSessionVisibilityState = normaliseServerAgentCreatedVisibilityState(data);
        serverConversationHistoryRecencyState = normaliseServerConversationHistoryRecencyState(data);
        const acceptedInvites = Array.isArray(incomingInviteState?.acceptedInvites)
            ? incomingInviteState.acceptedInvites
            : [];
        if (acceptedInvites.length > 0) {
            const sessionMap = new Map(
                sessions
                    .filter(s => s && typeof s.session_id === 'string')
                    .map(s => [s.session_id, s])
            );
            acceptedInvites.forEach((invite) => {
                const sid = (typeof invite?.session_id === 'string') ? invite.session_id.trim() : '';
                if (!sid) return;
                const existing = sessionMap.get(sid);
                if (existing) {
                    existing.shared_with_me = true;
                    if (!existing.shared_from_user_id && invite?.inviter_user_id) {
                        existing.shared_from_user_id = invite.inviter_user_id;
                    }
                    if (!existing.shared_owner_user_id && invite?.conversation_owner_user_id) {
                        existing.shared_owner_user_id = invite.conversation_owner_user_id;
                    }
                    if (!existing.invite_id && invite?.invite_id) {
                        existing.invite_id = invite.invite_id;
                    }
                    return;
                }
                sessions.push({
                    session_id: sid,
                    session_name: null,
                    shared_with_me: true,
                    shared_from_user_id: invite?.inviter_user_id || null,
                    shared_owner_user_id: invite?.conversation_owner_user_id || null,
                    invite_id: invite?.invite_id || null,
                    last_message_at: invite?.accepted_at || invite?.updated_at || invite?.created_at || null
                });
            });
        }

        const normalisedSessions = normaliseConversationSessionViewModels(sessions);
        reconcileServerConversationPreferences(normalisedSessions);

        // If the server temporarily reports no sessions (e.g. after creating a new chat
        // while history is still updating), keep the existing UI rather than hiding it.
        if (normalisedSessions.length === 0) {
            if (hasCachedTabs) {
                console.warn('[chatTab] Session list empty during refresh; keeping existing tabs');
                setTimeout(() => scheduleChatSessionTabsRefresh(true), 2000);
                return;
            }

            // Keep a placeholder visible; this is common right after reload if history
            // is still warming up.
            if (!Number.isFinite(chatTabsFirstLoadStartPerfMs)) {
                chatTabsFirstLoadStartPerfMs = _chatTabsNowPerfMs();
                chatTabsFirstLoadStartEpochMs = Date.now();
            }
            renderChatSessionTabsPlaceholder('loading');
            _startChatTabsLoadingTicker();
            setTimeout(() => scheduleChatSessionTabsRefresh(true), 2000);
            return;
        }

        if (Number.isFinite(chatTabsFirstLoadStartPerfMs)) {
            const durationMs = Math.max(0, _chatTabsNowPerfMs() - chatTabsFirstLoadStartPerfMs);
            _storeChatTabsLoadStats(durationMs);
            const stats = _getChatTabsLoadStats();
            console.info('[chatTab] Chat sessions loaded', {
                duration_ms: Math.round(durationMs),
                ema_ms: stats?.ema_ms ?? null,
                samples: stats?.samples ?? 0,
                start_epoch_ms: chatTabsFirstLoadStartEpochMs
            });
            chatTabsFirstLoadStartPerfMs = null;
            chatTabsFirstLoadStartEpochMs = null;
            _stopChatTabsLoadingTicker();
        }

        sessionTabsCache = normalisedSessions;
        const activeSessionId = (typeof data?.active_session_id === 'string' && data.active_session_id.trim())
            ? data.active_session_id.trim()
            : null;
        let localActiveSessionId = normaliseHistorySessionId(activeChatSessionId);
        const localActiveSession = localActiveSessionId
            ? normalisedSessions.find(
                s => (typeof s?.session_id === 'string') && s.session_id === localActiveSessionId
            )
            : null;
        if (localActiveSessionId && !localActiveSession) {
            setActiveChatSession(null, null);
            localActiveSessionId = null;
        }

        const serverActiveSession = activeSessionId
            ? normalisedSessions.find(
                s => (typeof s?.session_id === 'string') && s.session_id === activeSessionId
            )
            : null;
        const fallbackSession = (!localActiveSessionId && !activeSessionId)
            ? _getMostRecentSessionMeta(normalisedSessions)
            : null;
        const adoptedSession = serverActiveSession || fallbackSession;
        const adoptedSessionId = (typeof adoptedSession?.session_id === 'string' && adoptedSession.session_id.trim())
            ? adoptedSession.session_id.trim()
            : null;

        if (serverActiveSession) {
            activeChatSessionOwnerId = serverActiveSession.shared_owner_user_id || null;
        }

        // Only repair empty local selection from the server or most-recent list.
        // This preserves explicit user selection while still recovering startup/no-active state.
        if (!localActiveSessionId && adoptedSessionId) {
            // A restored selection may be shared.  Do not revive cached focal
            // context until the server has reauthorised it for this actor.
            clearChatSessionFocus(adoptedSessionId);
            setActiveChatSession(adoptedSessionId, adoptedSession?.session_name);
            localActiveSessionId = adoptedSessionId;
            activeChatSessionOwnerId = adoptedSession?.shared_owner_user_id || null;
            void loadChatSessionFocus(adoptedSessionId, { force: true });
        }

        renderChatSessionTabs(normalisedSessions, localActiveSessionId || activeSessionId);
        syncSharedConversationStreams();

        const sidForMeta = localActiveSessionId || activeSessionId;
        if (sidForMeta) {
            void loadChatSessionLinks(sidForMeta, { force: false });
        }
    } catch (err) {
        if (err?.name === 'AbortError' || !isChatOrganisationRequestCurrent(organisationGenerationAtStart)) {
            return;
        }
        console.error('Failed to load chat sessions:', err);

        // If the refresh failed but we have cached tabs, ensure they remain visible.
        if (Array.isArray(sessionTabsCache) && sessionTabsCache.length > 0) {
            try {
                renderChatSessionTabs(sessionTabsCache, activeChatSessionId);
            } catch (renderErr) {
                console.error('Failed to re-render cached chat tabs:', renderErr);
            }
        } else {
            _stopChatTabsLoadingTicker();
            renderChatSessionTabsPlaceholder('error');
        }
    } finally {
        chatSessionTabsFetchAbortControllers.delete(abortController);
    }
}

function renderChatSessionTabs(sessions, activeSessionId) {
    _stopChatTabsLoadingTicker();
    const container = getChatSessionTabsContainer();
    if (!container) {
        return;
    }
    const historyControls = document.getElementById('chatSessionHistoryControls');
    if (historyControls) historyControls.innerHTML = '';

    const canonicalSessions = normaliseConversationSessionViewModels(sessions);
    if (canonicalSessions.length === 0) {
        renderChatSessionTabsPlaceholder('empty');
        lastRenderedSessionCount = 0;
        setChatSessionCount(0);
        sessionTabsCache = [];
        chatSessionMetadataOpenKey = null;
        _clearChatSessionMetadata();
        return;
    }
    sessionTabsCache = canonicalSessions;
    if (activeChatSessionId) {
        activeExternalConversationMetadata = canonicalSessions.find(
            session => normaliseHistorySessionId(session?.session_id) === activeChatSessionId
        )?.external_conversation || null;
        updateExternalConversationUi();
    }

    // JVNAUTOSCI-1014: Filter hidden sessions unless showHiddenSessions is enabled.
    const sessionsAfterHiddenFilter = showHiddenSessions
        ? canonicalSessions
        : canonicalSessions.filter(s => !isConversationHidden(s?.session_id));
    const agentFilterResult = filterAgentCreatedSessionsForDefaultView(sessionsAfterHiddenFilter);
    const serverAgentState = serverAgentCreatedSessionVisibilityState?.applied === true
        ? serverAgentCreatedSessionVisibilityState
        : null;
    const sessionsAfterAgentFilter = serverAgentState
        ? sessionsAfterHiddenFilter
        : agentFilterResult.sessions;
    agentCreatedSessionVisibilityState = serverAgentState
        ? {
            totalCount: serverAgentState.totalCount,
            hiddenCount: serverAgentState.hiddenCount,
            newestVisibleSessionId: serverAgentState.newestVisibleSessionId
        }
        : {
            totalCount: agentFilterResult.totalCount,
            hiddenCount: agentFilterResult.hiddenCount,
            newestVisibleSessionId: (
                typeof agentFilterResult.newestVisibleSession?.session_id === 'string'
                ? agentFilterResult.newestVisibleSession.session_id.trim()
                : null
            )
        };

    const conversationHistorySettings = loadConversationHistorySettings((key) => safeLocalStorageGet(key));
    if (expandedConversationHistoryBaseLimit !== conversationHistorySettings.recentLimit) {
        expandedConversationHistoryLimit = null;
        expandedConversationHistoryBaseLimit = conversationHistorySettings.recentLimit;
    }
    const effectiveRecentLimit = Number.isFinite(expandedConversationHistoryLimit)
        ? Math.max(conversationHistorySettings.recentLimit, Math.trunc(expandedConversationHistoryLimit))
        : conversationHistorySettings.recentLimit;
    const filteredResult = selectConversationHistorySessions({
        sessions: sessionsAfterAgentFilter,
        accessTimestampBySessionId: getConversationHistoryAccessLookup(sessionsAfterAgentFilter),
        recentLimit: effectiveRecentLimit,
        recentWindowDays: conversationHistorySettings.recentWindowDays,
        showAll: false
    });
    let visibleSessions = Array.isArray(filteredResult.sessionsToRender)
        ? filteredResult.sessionsToRender
        : [];
    const newestAgentSessionId = agentCreatedSessionVisibilityState.newestVisibleSessionId;
    const visibleSessionIds = new Set(
        visibleSessions
            .map((session) => (typeof session?.session_id === 'string' ? session.session_id.trim() : ''))
            .filter(Boolean)
    );
    const protectedActiveSessions = [];
    sessionsAfterHiddenFilter.forEach((session) => {
        const sid = (typeof session?.session_id === 'string') ? session.session_id.trim() : '';
        if (!sid || visibleSessionIds.has(sid)) {
            return;
        }
        const shouldRemainVisible = sid === activeSessionId
            || !!getLiveChatRequestForSession(sid)
            || getQueuedChatPromptCountForSession(sid) > 0;
        if (!shouldRemainVisible) {
            return;
        }
        protectedActiveSessions.push(session);
        visibleSessionIds.add(sid);
    });
    if (protectedActiveSessions.length > 0) {
        visibleSessions = [...visibleSessions, ...protectedActiveSessions];
    }
    if (showAgentCreatedSessions) {
        const extraAgentSessions = sessionsAfterAgentFilter.filter((session) => {
            if (!isAgentCreatedConversation(session)) {
                return false;
            }
            const sid = (typeof session?.session_id === 'string') ? session.session_id.trim() : '';
            return sid && !visibleSessionIds.has(sid);
        });
        if (extraAgentSessions.length > 0) {
            visibleSessions = [...visibleSessions, ...extraAgentSessions];
        }
    } else if (newestAgentSessionId) {
        if (!visibleSessionIds.has(newestAgentSessionId) && agentFilterResult.newestVisibleSession) {
            visibleSessions = [...visibleSessions, agentFilterResult.newestVisibleSession];
        }
    }

    // Pinned sessions are user-prioritised and remain visible at the top even when
    // they would otherwise be hidden by recency window/limit filtering.
    const pinnedSessionMap = new Map();
    const pinnedSessionsInFilteredOrder = [];
    const unpinnedSessions = [];
    visibleSessions.forEach((session) => {
        const sid = (typeof session?.session_id === 'string') ? session.session_id.trim() : '';
        if (!sid) {
            return;
        }
        if (isConversationPinned(sid)) {
            pinnedSessionMap.set(sid, session);
            pinnedSessionsInFilteredOrder.push(session);
            return;
        }
        unpinnedSessions.push(session);
    });

    sessionsAfterAgentFilter.forEach((session) => {
        const sid = (typeof session?.session_id === 'string') ? session.session_id.trim() : '';
        if (!sid || !isConversationPinned(sid) || pinnedSessionMap.has(sid)) {
            return;
        }
        pinnedSessionMap.set(sid, session);
    });

    const pinnedSessionIdsInFilteredOrder = new Set(
        pinnedSessionsInFilteredOrder
            .map((session) => (typeof session?.session_id === 'string' ? session.session_id.trim() : ''))
            .filter(Boolean)
    );
    const pinnedSessions = [
        ...pinnedSessionsInFilteredOrder,
        ...Array.from(pinnedSessionMap.values()).filter((session) => {
            const sid = (typeof session?.session_id === 'string') ? session.session_id.trim() : '';
            if (!sid) {
                return false;
            }
            return !pinnedSessionIdsInFilteredOrder.has(sid);
        })
    ];
    const orderedVisibleSessions = [...pinnedSessions, ...unpinnedSessions];

    container.hidden = false;
    container.innerHTML = '';
    lastRenderedSessionCount = orderedVisibleSessions.length;
    setChatSessionCount(Math.max(filteredResult.totalMatchingCount, orderedVisibleSessions.length));

    const fragment = document.createDocumentFragment();

    // Always show the "+" button to create new chats
    fragment.appendChild(createNewChatTabButton());

    const serverOlderCount = (
        serverConversationHistoryRecencyState?.recentWindowDays === filteredResult.recentWindowDays
    )
        ? serverConversationHistoryRecencyState.olderThanWindowCount
        : null;
    const olderThanWindowCount = Number.isFinite(serverOlderCount)
        ? serverOlderCount
        : filteredResult.olderThanWindowCount;
    if (historyControls && olderThanWindowCount > 0) {
        const olderIndicator = document.createElement('span');
        const formattedOlderCount = olderThanWindowCount.toLocaleString();
        olderIndicator.className = 'chat-session-history-indicator';
        olderIndicator.textContent = `[${formattedOlderCount} > ${filteredResult.recentWindowDays}d]`;
        olderIndicator.title = `${formattedOlderCount} conversations are older than ${filteredResult.recentWindowDays} days and hidden from this recent-conversation strip. Search can still find them.`;
        olderIndicator.setAttribute(
            'aria-label',
            `${formattedOlderCount} conversations older than ${filteredResult.recentWindowDays} days`
        );
        olderIndicator.setAttribute('data-keep-title', 'true');
        olderIndicator.tabIndex = 0;
        historyControls.appendChild(olderIndicator);
    }

    if (historyControls && filteredResult.totalMatchingCount > filteredResult.recentLimit) {
        const overflowButton = document.createElement('button');
        const hiddenCount = filteredResult.hiddenByLimitCount;
        const nextTrancheSize = Math.min(hiddenCount, filteredResult.recentLimit);
        const ordinaryClickShowsAll = nextTrancheSize >= hiddenCount;
        overflowButton.type = 'button';
        overflowButton.className = 'chat-session-history-toggle';
        overflowButton.textContent = `+${hiddenCount}`;
        overflowButton.title = ordinaryClickShowsAll
            ? `${hiddenCount} more conversations fall within the ${filteredResult.recentWindowDays}-day window. Click to show all of them.`
            : `${hiddenCount} more conversations fall within the ${filteredResult.recentWindowDays}-day window. Click to show the next ${nextTrancheSize}; Shift-click to show all.`;
        overflowButton.setAttribute(
            'aria-label',
            ordinaryClickShowsAll
                ? `Show all ${hiddenCount} more recent conversations`
                : `Show the next ${nextTrancheSize} of ${hiddenCount} more recent conversations; Shift-click to show all`
        );
        overflowButton.setAttribute('data-keep-title', 'true');
        overflowButton.addEventListener('click', (event) => {
            expandedConversationHistoryLimit = event.shiftKey
                ? filteredResult.totalMatchingCount
                : filteredResult.recentLimit + nextTrancheSize;
            renderChatSessionTabs(sessionTabsCache, activeChatSessionId);
        });
        historyControls.appendChild(overflowButton);
    }

    if (orderedVisibleSessions.length === 0) {
        const placeholder = document.createElement('div');
        placeholder.className = 'chat-session-tabs-placeholder chat-session-tabs-placeholder-filtered';
        placeholder.textContent = `No conversations match the current ${filteredResult.recentWindowDays}-day window. Adjust in Settings > Conversations.`;
        fragment.appendChild(placeholder);
    }

    orderedVisibleSessions.forEach((session, index) => {
        const sid = (typeof session?.session_id === 'string') ? session.session_id.trim() : '';
        if (!sid) {
            return;
        }
        const isPinned = isConversationPinned(sid);
        const isFirstPinnedTab = pinnedSessions.length > 0 && index === 0 && isPinned;
        const isFirstRecentTab = pinnedSessions.length > 0 && unpinnedSessions.length > 0 && index === pinnedSessions.length;
        const groupLabelText = isFirstPinnedTab
            ? `Pinned (${pinnedSessions.length})`
            : (isFirstRecentTab ? 'Recent' : '');

        const displayName = getSessionDisplayName(session, { fallbackToId: false });
        const timestampSource = (typeof session?.last_message_at === 'string' && session.last_message_at.trim())
            ? session.last_message_at.trim()
            : (typeof session?.created_at === 'string' && session.created_at.trim())
                ? session.created_at.trim()
                : '';
        const timestampLabel = formatSessionTimestamp(timestampSource) || '-';
        const absoluteTimestampLabel = formatAbsoluteTimestamp(timestampSource);
        const tab = document.createElement('button');
        tab.type = 'button';
        tab.className = 'chat-session-tab';
        tab.setAttribute('role', 'tab');
        tab.setAttribute('aria-selected', sid === activeSessionId ? 'true' : 'false');
        if (!displayName) {
            tab.setAttribute(
                'aria-label',
                `Unnamed conversation${absoluteTimestampLabel ? `, ${absoluteTimestampLabel}` : ''}`
            );
        }
        tab.dataset.sessionId = sid;
        if (typeof session?.session_name === 'string') {
            tab.dataset.sessionName = session.session_name;
        }

        if (sid === activeSessionId) {
            tab.classList.add('is-active');
        }

        const hasLiveRequest = !!getLiveChatRequestForSession(sid);
        const queueCounts = getChatPromptQueueCountsForSession(sid);
        const queuedPromptCount = queueCounts.total;

        if (groupLabelText) {
            tab.classList.add('chat-session-tab-group-start');
            const groupBadge = document.createElement('span');
            groupBadge.className = 'chat-session-tab-group-badge';
            if (isFirstRecentTab) {
                tab.classList.add('chat-session-tab-group-start-recent');
                groupBadge.classList.add('chat-session-tab-group-badge-recent');
            } else {
                groupBadge.classList.add('chat-session-tab-group-badge-pinned');
            }
            groupBadge.textContent = groupLabelText;
            groupBadge.setAttribute('aria-hidden', 'true');
            tab.appendChild(groupBadge);
        }

        if (sid === loadingChatSessionId) {
            tab.classList.add('is-loading');
        }

        if (hasLiveRequest) {
            tab.classList.add('has-background-request');
        }

        if (queuedPromptCount > 0) {
            tab.classList.add('has-queued-prompts');
        }

        if (isPinned) {
            tab.classList.add('is-pinned');
        }

        const isAgentCreated = isAgentCreatedConversation(session);
        if (isAgentCreated) {
            tab.classList.add('is-agent-created');
        }

        if (session?.shared_with_me || session?.shared_from_user_id || session?.invite_id) {
            tab.classList.add('is-shared');
        }

        // JVNAUTOSCI-1014: Mark hidden conversations with visual styling
        const isHidden = isConversationHidden(sid);
        if (isHidden) {
            tab.classList.add('is-hidden');
        }

        if (session?.is_completed === true) {
            tab.classList.add('is-completed');
            const completedLabel = formatCompletedLabel(session?.completed_at);
            tab.title = displayName
                ? `${displayName} • ${timestampLabel} (${completedLabel})`
                : `Unnamed conversation • ${timestampLabel} (${completedLabel})`;
        } else {
            tab.classList.add('is-open');
            tab.title = displayName
                ? `${displayName} • ${timestampLabel}`
                : `Unnamed conversation • ${timestampLabel}`;
        }

        if (isPinned) {
            tab.title = `${tab.title} • Pinned`;
        }

        if (isAgentCreated) {
            tab.title = `${tab.title} • Test conversation`;
        }

        if (session?.shared_with_me || session?.shared_from_user_id || session?.invite_id) {
            tab.title = `${tab.title} • Shared`;
        }

        if (session?.shared_owner_user_id) {
            const ownerName = _deriveNameFromConceptId(session.shared_owner_user_id) || session.shared_owner_user_id;
            tab.title = `${tab.title} • Owner: ${ownerName}`;
            tab.setAttribute('data-keep-title', 'true');
            tab.dataset.sharedOwnerId = session.shared_owner_user_id;
        }

        const header = document.createElement('span');
        header.className = 'chat-session-tab-header';

        const pinToggle = document.createElement('button');
        pinToggle.type = 'button';
        pinToggle.className = 'chat-session-tab-pin-toggle';
        pinToggle.setAttribute('aria-label', isPinned ? 'Unpin conversation' : 'Pin conversation');
        pinToggle.setAttribute('aria-pressed', isPinned ? 'true' : 'false');
        pinToggle.title = isPinned ? 'Unpin conversation' : 'Pin conversation';
        pinToggle.textContent = isPinned ? '★' : '☆';
        pinToggle.addEventListener('click', (event) => {
            event.preventDefault();
            event.stopPropagation();
            toggleConversationPinned(sid);
        });
        header.appendChild(pinToggle);

        const label = document.createElement('span');
        label.className = 'chat-session-tab-label';
        label.textContent = displayName;
        header.appendChild(label);

        if (session?.external_conversation?.read_only === true) {
            const importedBadge = document.createElement('span');
            importedBadge.className = 'chat-session-imported-marker';
            importedBadge.textContent = 'Imported';
            const provider = String(session.external_conversation.provider || '').trim();
            importedBadge.title = provider
                ? `Read-only import from ${provider.replaceAll('_', ' ')}`
                : 'Read-only imported conversation';
            importedBadge.setAttribute('aria-label', importedBadge.title);
            importedBadge.setAttribute('data-keep-title', 'true');
            header.appendChild(importedBadge);
        }

        if (hasLiveRequest || queuedPromptCount > 0) {
            const activityBadge = document.createElement('span');
            activityBadge.className = 'chat-session-tab-activity';
            if (hasLiveRequest) {
                activityBadge.textContent = sid === activeSessionId ? 'Thinking' : 'Background';
                tab.title = `${tab.title} • ${sid === activeSessionId ? 'Thinking' : 'Background request active'}`;
            } else if (queueCounts.running > 0) {
                activityBadge.textContent = queueCounts.running === 1 ? 'Running' : `Running ${queueCounts.running}`;
                tab.title = `${tab.title} • ${queueCounts.running} prompt${queueCounts.running === 1 ? '' : 's'} running in another tab`;
            } else if (queueCounts.failed > 0 && (queueCounts.queued + queueCounts.restartable) === 0) {
                activityBadge.textContent = queueCounts.failed === 1 ? 'Failed' : `Failed ${queueCounts.failed}`;
                tab.title = `${tab.title} • ${queueCounts.failed} failed queued prompt${queueCounts.failed === 1 ? '' : 's'}`;
            } else {
                const pendingCount = queueCounts.queued + queueCounts.restartable;
                activityBadge.textContent = pendingCount === 1 ? 'Queued' : `Queued ${pendingCount}`;
                const failedSuffix = queueCounts.failed > 0
                    ? `, ${queueCounts.failed} failed`
                    : '';
                tab.title = `${tab.title} • ${pendingCount} queued prompt${pendingCount === 1 ? '' : 's'}${failedSuffix}`;
            }
            header.appendChild(activityBadge);
        }

        const unreadCount = Number.isFinite(session?.shared_unread_count)
            ? Number(session.shared_unread_count)
            : 0;
        if (unreadCount > 0) {
            tab.classList.add('has-unread');
            const unreadBadge = document.createElement('span');
            unreadBadge.className = 'chat-session-tab-unread';
            unreadBadge.textContent = String(unreadCount);
            header.appendChild(unreadBadge);
        }
        if (session?.shared_owner_user_id) {
            const ownerName = _deriveNameFromConceptId(session.shared_owner_user_id) || session.shared_owner_user_id;
            const ownerBadge = document.createElement('span');
            ownerBadge.className = 'chat-session-tab-owner-indicator';
            ownerBadge.textContent = '👑';
            ownerBadge.title = `Owner: ${ownerName}`;
            ownerBadge.setAttribute('aria-label', `Owner: ${ownerName}`);
            ownerBadge.setAttribute('data-keep-title', 'true');
            header.appendChild(ownerBadge);
        }

        const messageCount = Number.isFinite(session?.message_count) ? Number(session.message_count) : null;
        const turnCount = messageCount === null ? null : Math.max(0, Math.ceil(messageCount / 2));
        if (turnCount !== null && turnCount > 0) {
            const suffix = turnCount === 1 ? 'turn' : 'turns';
            tab.title = `${tab.title} • ${turnCount} ${suffix}`;

            const count = document.createElement('span');
            count.className = 'chat-session-tab-count';
            count.textContent = String(turnCount);
            header.appendChild(count);
        }

        const meta = document.createElement('span');
        meta.className = 'chat-session-tab-meta';
        if (isAgentCreated) {
            const agentMarker = document.createElement('span');
            agentMarker.className = 'chat-session-agent-marker';
            agentMarker.textContent = 'von';
            agentMarker.title = 'Test conversation';
            agentMarker.setAttribute('aria-label', 'Test conversation');
            agentMarker.setAttribute('data-keep-title', 'true');
            meta.appendChild(agentMarker);
            meta.appendChild(document.createTextNode(' '));
        }
        meta.appendChild(document.createTextNode(timestampLabel));
        setUnambiguousTimestampTooltip(meta, timestampSource);

        const previewText = formatChatSessionPreview(session?.preview);
        const preview = document.createElement('span');
        preview.className = 'chat-session-tab-preview';
        if (previewText) {
            preview.textContent = previewText;
            preview.title = previewText;
        }

        tab.appendChild(header);
        tab.appendChild(meta);
        if (previewText) {
            tab.appendChild(preview);
        }
        tab.addEventListener('click', () => {
            if (sid === activeChatSessionId) {
                return;
            }
            void switchToChatSession(sid);
        });
        tab.addEventListener('dblclick', () => {
            void promptRenameChatSession(sid, session?.session_name || displayName);
        });
        tab.addEventListener('contextmenu', (event) => {
            event.preventDefault();
            // JVNAUTOSCI-1014: Build context menu with hide/unhide and optional delete
            const menuItems = [
                {
                    label: 'Rename',
                    onClick: () => {
                        void promptRenameChatSession(sid, session?.session_name || displayName);
                    }
                },
                {
                    label: isPinned ? 'Unpin conversation' : 'Pin conversation',
                    onClick: () => {
                        toggleConversationPinned(sid);
                    }
                },
                {
                    label: 'Copy conversation reference',
                    onClick: () => {
                        void copyConversationReferenceToClipboard(session);
                    }
                }
            ];

            // Hide/Unhide option
            if (isHidden) {
                menuItems.push({
                    label: 'Unhide conversation',
                    onClick: () => {
                        unhideConversation(sid);
                    }
                });
            } else {
                menuItems.push({
                    label: 'Hide conversation',
                    onClick: () => {
                        hideConversation(sid);
                    }
                });
            }

            const isSharedConversation = !!(session?.shared_with_me || session?.shared_from_user_id || session?.invite_id);
            if (!isSharedConversation) {
                menuItems.push({
                    label: 'Move to Trash',
                    onClick: () => {
                        if (window.confirm('Move this conversation to Trash? You can restore it later.')) {
                            void deleteConversation(sid);
                        }
                    }
                });
            }

            // JVNAUTOSCI-1039: Move to Organisation option for owned conversations
            // Only show for non-shared conversations (user owns this conversation)
            if (!isSharedConversation) {
                menuItems.push({
                    label: 'Move to Organisation…',
                    onClick: () => {
                        void promptMoveToOrganisation(sid);
                    }
                });
            }

            openChatSessionMenu(event.clientX, event.clientY, menuItems);
        });

        fragment.appendChild(tab);
    });

    container.appendChild(fragment);

    // JVNAUTOSCI-1014: Context menu on container for showing/hiding hidden sessions
    // Remove any existing listener to avoid duplicates
    container.removeEventListener('contextmenu', handleContainerContextMenu);
    container.addEventListener('contextmenu', handleContainerContextMenu);
}

function buildNewChatContextMenuItems() {
    const items = [
        {
            label: 'New conversation',
            onClick: () => {
                void createNewChatSession();
            }
        },
        {
            label: 'Import conversation…',
            onClick: () => {
                document.getElementById('importExternalConversationInput')?.click();
            }
        },
        {
            label: 'Import conversations from this machine…',
            onClick: () => {
                void startExternalConversationBulkImport().catch((error) => {
                    console.error('[chatTab] Machine conversation import failed:', error);
                    showToast(error?.message || 'Unable to start the machine conversation import.', 'error');
                });
            }
        },
        {
            label: getChatSessionTabsLayoutMenuLabel(),
            onClick: () => {
                toggleChatSessionTabsLayout({ announce: true });
            }
        }
    ];

    const agentTotalCount = agentCreatedSessionVisibilityState.totalCount || 0;
    const hiddenAgentCount = agentCreatedSessionVisibilityState.hiddenCount || 0;
    if (hiddenAgentCount > 0 || showAgentCreatedSessions) {
        items.push({
            label: showAgentCreatedSessions
                ? `Hide test conversations (${agentTotalCount})`
                : `Show test conversations (${hiddenAgentCount} hidden)`,
            onClick: () => {
                toggleShowAgentCreatedSessions();
            }
        });
    }

    const hiddenCount = hiddenChatSessionIds.size;
    if (hiddenCount > 0) {
        items.push({
            label: showHiddenSessions ? `Hide hidden (${hiddenCount})` : `Show hidden (${hiddenCount})`,
            onClick: () => {
                toggleShowHiddenSessions();
            }
        });
    }

    return items;
}

function buildExternalConversationImportForm(file, { dryRun }) {
    const form = new FormData();
    form.append('file', file, file?.name || 'conversation.jsonl');
    form.append('dry_run', dryRun ? 'true' : 'false');
    return form;
}

async function requestExternalConversationImport(file, { dryRun }) {
    const response = await fetch('/von/api/session/import_external_conversation', {
        method: 'POST',
        headers: buildChatFetchHeaders(),
        body: buildExternalConversationImportForm(file, { dryRun })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || data?.success !== true) {
        const error = new Error(data?.error || 'Unable to import this conversation.');
        error.code = data?.error_code || null;
        throw error;
    }
    return data;
}

async function handleExternalConversationFile(file) {
    if (!file || typeof file !== 'object') {
        return;
    }
    const previewResult = await requestExternalConversationImport(file, { dryRun: true });
    const preview = previewResult?.preview || {};
    const loss = preview?.loss_report || {};
    const projectedCount = Number(loss?.projected_message_count || 0);
    const provider = String(preview?.provider || 'external').replaceAll('_', ' ');
    const sourceTitle = String(preview?.source_title || file.name || 'Untitled conversation');
    const action = preview?.action === 'unchanged'
        ? 'verify the existing import of'
        : (preview?.action === 'updated' ? 'refresh' : 'import');
    const confirmed = window.confirm(
        `${action[0].toUpperCase()}${action.slice(1)} “${sourceTitle}” from ${provider}?\n\n`
        + `${projectedCount} visible messages will be available as a read-only snapshot. `
        + 'System instructions, reasoning, and tool events remain historical data and are not executed.'
    );
    if (!confirmed) {
        return;
    }
    const result = await requestExternalConversationImport(file, { dryRun: false });
    const sessionId = normaliseHistorySessionId(
        result?.projection?.session_id || result?.preview?.session_id
    );
    showToast(
        result?.status === 'unchanged'
            ? 'That conversation is already imported and current.'
            : `Imported ${projectedCount} visible messages as a read-only conversation.`,
        'success'
    );
    await refreshChatSessionTabs();
    if (sessionId) {
        await switchToChatSession(sessionId);
    }
}

let externalConversationBulkImportBatchId = null;
let externalConversationBulkImportPollTimer = null;
let externalConversationBulkImportLastStatus = null;
let externalConversationBulkImportPanelHidden = false;

async function requestExternalConversationBulkImport(path, { method = 'GET', body = undefined } = {}) {
    const headers = buildChatFetchHeaders(body === undefined ? undefined : { 'Content-Type': 'application/json' });
    const response = await fetch(`/von/api/session/external_conversation_import${path}`, {
        method,
        headers,
        body: body === undefined ? undefined : JSON.stringify(body)
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
        const error = new Error(data?.error || 'Unable to manage the machine conversation import.');
        error.code = data?.error_code || null;
        throw error;
    }
    return data;
}

function renderExternalConversationBulkImport(batch, { reconnecting = false } = {}) {
    const panel = document.getElementById('externalConversationBulkImportPanel');
    const title = document.getElementById('externalConversationBulkImportTitle');
    const summary = document.getElementById('externalConversationBulkImportSummary');
    const pauseButton = document.getElementById('pauseExternalConversationBulkImportBtn');
    const resumeButton = document.getElementById('resumeExternalConversationBulkImportBtn');
    const cancelButton = document.getElementById('cancelExternalConversationBulkImportBtn');
    if (!panel || !title || !summary || !batch) {
        return;
    }
    panel.classList.toggle('hidden', externalConversationBulkImportPanelHidden);
    const counts = batch.counts || {};
    const completed = Number(counts.completed || 0);
    const failed = Number(counts.failed || 0) + Number(counts.unsupported || 0);
    const diverged = Number(counts.diverged || 0);
    const total = Number(batch.source_count || 0);
    const sourceGiB = Number(batch.source_bytes || 0) / (1024 ** 3);
    const sourceSizeLabel = sourceGiB >= 0.1 ? `, ${sourceGiB.toFixed(1)} GiB source data` : '';
    const status = String(batch.status || 'unknown').replaceAll('_', ' ');
    title.textContent = `Machine conversation import: ${status}`;
    summary.textContent = reconnecting
        ? `Connection lost; the durable import continues on the server. Reconnecting… ${completed + failed} of ${total} settled.`
        : `${completed + failed} of ${total} sources settled${sourceSizeLabel}; ${completed} imported, ${failed} failed, ${diverged} have source divergence. Re-running later appends only unseen interactions.`;
    const canPause = ['planning', 'ready', 'running'].includes(batch.status);
    const canResume = ['paused', 'pause_requested'].includes(batch.status);
    const terminal = ['completed', 'partial', 'failed', 'cancelled'].includes(batch.status);
    pauseButton?.classList.toggle('hidden', !canPause);
    resumeButton?.classList.toggle('hidden', !canResume);
    cancelButton?.classList.toggle('hidden', terminal);
}

function scheduleExternalConversationBulkImportPoll(delay = 2000) {
    window.clearTimeout(externalConversationBulkImportPollTimer);
    externalConversationBulkImportPollTimer = window.setTimeout(
        () => void pollExternalConversationBulkImport(),
        delay
    );
}

async function pollExternalConversationBulkImport() {
    if (!externalConversationBulkImportBatchId) {
        return;
    }
    try {
        const batch = await requestExternalConversationBulkImport(`/batches/${encodeURIComponent(externalConversationBulkImportBatchId)}`);
        renderExternalConversationBulkImport(batch);
        const terminal = ['completed', 'partial', 'failed', 'cancelled'].includes(batch.status);
        if (terminal) {
            if (externalConversationBulkImportLastStatus !== batch.status) {
                await refreshChatSessionTabs();
                showToast(
                    batch.status === 'completed'
                        ? 'Machine conversation import completed.'
                        : `Machine conversation import ended with status: ${String(batch.status).replaceAll('_', ' ')}.`,
                    batch.status === 'completed' ? 'success' : 'info'
                );
            }
        } else {
            scheduleExternalConversationBulkImportPoll();
        }
        externalConversationBulkImportLastStatus = batch.status;
    } catch (_error) {
        renderExternalConversationBulkImport(
            { batch_id: externalConversationBulkImportBatchId, status: externalConversationBulkImportLastStatus || 'running', source_count: 0, counts: {} },
            { reconnecting: true }
        );
        scheduleExternalConversationBulkImportPoll(5000);
    }
}

async function loadLatestExternalConversationBulkImport() {
    try {
        const data = await requestExternalConversationBulkImport('/batches?limit=20');
        const batches = Array.isArray(data?.batches) ? data.batches : [];
        const batch = batches.find((candidate) => !['completed', 'partial', 'failed', 'cancelled'].includes(candidate?.status))
            || batches[0]
            || null;
        if (!batch) {
            return;
        }
        externalConversationBulkImportBatchId = batch.batch_id;
        externalConversationBulkImportLastStatus = batch.status;
        renderExternalConversationBulkImport(batch);
        if (!['completed', 'partial', 'failed', 'cancelled'].includes(batch.status)) {
            scheduleExternalConversationBulkImportPoll(500);
        }
    } catch (_) {
        // Authentication may not be ready yet; a started batch is rediscovered on the next tab initialisation.
    }
}

async function startExternalConversationBulkImport() {
    const preview = await requestExternalConversationBulkImport('/preview', {
        method: 'POST',
        body: { providers: ['codex', 'claude_code', 'copilot', 'gemini'] }
    });
    const providerSummary = Object.entries(preview?.providers || {})
        .filter(([, value]) => Number(value?.source_count || 0) > 0)
        .map(([provider, value]) => `${provider.replaceAll('_', ' ')}: ${Number(value.source_count)}`)
        .join(', ');
    const sourceGiB = Number(preview?.source_bytes || 0) / (1024 ** 3);
    const sourceSizeLabel = sourceGiB >= 0.1 ? ` (${sourceGiB.toFixed(1)} GiB of source data)` : '';
    const confirmed = window.confirm(
        `Import ${Number(preview?.source_count || 0).toLocaleString()} local conversation sources${sourceSizeLabel} into Von?\n\n`
        + `${providerSummary || 'No supported sources found.'}\n\n`
        + 'The job is restartable and continues if this browser disconnects. Existing imported events are preserved; only unseen interactions are appended.'
    );
    if (!confirmed || Number(preview?.source_count || 0) === 0) {
        return;
    }
    const batch = await requestExternalConversationBulkImport('/batches', {
        method: 'POST',
        body: { providers: ['codex', 'claude_code', 'copilot', 'gemini'] }
    });
    externalConversationBulkImportBatchId = batch.batch_id;
    externalConversationBulkImportLastStatus = batch.status;
    externalConversationBulkImportPanelHidden = false;
    renderExternalConversationBulkImport(batch);
    scheduleExternalConversationBulkImportPoll(500);
}

async function controlExternalConversationBulkImport(action) {
    if (!externalConversationBulkImportBatchId) {
        return;
    }
    const batch = await requestExternalConversationBulkImport(
        `/batches/${encodeURIComponent(externalConversationBulkImportBatchId)}/${action}`,
        { method: 'POST', body: {} }
    );
    externalConversationBulkImportLastStatus = batch.status;
    renderExternalConversationBulkImport(batch);
    if (!['completed', 'partial', 'failed', 'cancelled', 'paused'].includes(batch.status)) {
        scheduleExternalConversationBulkImportPoll(500);
    }
}

async function continueActiveExternalConversation() {
    if (!activeChatSessionId || !isExternalConversationReadOnly()) {
        return;
    }
    const response = await fetch('/von/api/session/continue_external_conversation', {
        method: 'POST',
        headers: buildChatFetchHeaders({ 'Content-Type': 'application/json' }),
        body: JSON.stringify({ session_id: activeChatSessionId })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || data?.success !== true) {
        throw new Error(data?.error || 'Unable to continue this imported conversation.');
    }
    await refreshChatSessionTabs();
    await switchToChatSession(data.session_id);
    showToast('Created a native Von continuation. New turns will be added there.', 'success');
}

function handleContainerContextMenu(event) {
    // Only show menu if clicking on the container itself or whitespace (not on a tab)
    if (event.target.closest('.chat-session-tab')) {
        return;
    }
    event.preventDefault();
    openChatSessionMenu(event.clientX, event.clientY, buildNewChatContextMenuItems());
}

function shouldShowChatTabMenu() {
    const container = getChatSessionTabsContainer();
    if (!container || container.hidden) {
        return false;
    }
    return lastRenderedSessionCount <= 1;
}

function ensureChatSessionMenu() {
    if (chatSessionMenuEl) {
        return chatSessionMenuEl;
    }

    const menu = document.createElement('div');
    menu.className = 'chat-session-menu';
    menu.setAttribute('role', 'menu');
    menu.setAttribute('aria-hidden', 'true');
    document.body.appendChild(menu);

    document.addEventListener('click', (event) => {
        if (menu.classList.contains('open') && !menu.contains(event.target)) {
            closeChatSessionMenu();
        }
    });

    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') {
            closeChatSessionMenu();
        }
    });

    chatSessionMenuEl = menu;
    return menu;
}

function populateChatSessionMenu(items) {
    const menu = ensureChatSessionMenu();
    menu.innerHTML = '';
    items.forEach((item) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = item.label;
        button.setAttribute('role', 'menuitem');
        button.addEventListener('click', () => {
            closeChatSessionMenu();
            item.onClick();
        });
        menu.appendChild(button);
    });
    return menu;
}

function openChatSessionMenu(x, y, items, options = {}) {
    if (!Array.isArray(items) || items.length === 0) {
        return;
    }

    const menu = populateChatSessionMenu(items);
    chatSessionMenuReturnFocusEl = options.returnFocus instanceof HTMLElement
        ? options.returnFocus
        : null;
    const padding = 8;
    menu.classList.add('open');
    menu.setAttribute('aria-hidden', 'false');
    const maxX = window.innerWidth - menu.offsetWidth - padding;
    const maxY = window.innerHeight - menu.offsetHeight - padding;
    const left = Math.max(padding, Math.min(x, maxX));
    const top = Math.max(padding, Math.min(y, maxY));
    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
    if (options.focusFirst === true) {
        const firstItem = menu.querySelector('button');
        try { firstItem?.focus?.(); } catch (_) { /* ignore */ }
    }
}

function closeChatSessionMenu() {
    if (!chatSessionMenuEl) {
        return;
    }
    const shouldRestoreFocus = chatSessionMenuEl.contains(document.activeElement)
        && chatSessionMenuReturnFocusEl?.isConnected;
    const returnFocusEl = chatSessionMenuReturnFocusEl;
    chatSessionMenuEl.classList.remove('open');
    chatSessionMenuEl.setAttribute('aria-hidden', 'true');
    chatSessionMenuReturnFocusEl = null;
    if (shouldRestoreFocus) {
        try { returnFocusEl.focus(); } catch (_) { /* ignore */ }
    }
}

function setupChatTabContextMenu() {
    const chatTabButton = getChatTabButton();
    if (!chatTabButton) {
        return;
    }
    chatTabButton.addEventListener('contextmenu', (event) => {
        if (!shouldShowChatTabMenu()) {
            return;
        }
        event.preventDefault();
        openChatSessionMenu(event.clientX, event.clientY, buildNewChatContextMenuItems());
    });
}

function createNewChatSession() {
    if (newChatCreationInFlight) {
        return newChatCreationInFlight;
    }

    const creation = (async () => {
        try {
            return await createChatSession('', { preserveComposerDraft: true });
        } catch (err) {
            if (err?.organisationSwitchSuperseded === true) {
                return null;
            }
            console.error('[chatTab] Unable to create chat:', err);
            const msg = err?.message ? String(err.message) : 'Unable to create chat.';
            showToast(msg, 'error');
            return null;
        } finally {
            if (newChatCreationInFlight === creation) {
                newChatCreationInFlight = null;
                updateSendButtonForCurrentChatState();
            }
        }
    })();
    newChatCreationInFlight = creation;
    updateSendButtonForCurrentChatState();
    return creation;
}

function normaliseFocusedConceptIds(rawIds) {
    return normaliseFocusedConcepts(Array.isArray(rawIds) ? rawIds : [])
        .map((item) => item.conceptId);
}

function getFocusedConversationLauncherElement() {
    return document.getElementById('focusedConversationLauncher');
}

function closeFocusedConversationLauncher() {
    getFocusedConversationLauncherElement()?.remove();
}

function focusComposerForConversation() {
    const promptInput = getPromptInputElement();
    if (promptInput) {
        setPromptComposerValue(String(promptInput.value || ''), { promptInput, focus: true });
    }
}

async function loadRecentFocusedConversationSessions(focalConceptId) {
    const conceptId = String(focalConceptId || '').trim();
    if (!conceptId) return [];
    try {
        const response = await fetch(
            `/von/api/session/chat_session_focus?focal_concept_id=${encodeURIComponent(conceptId)}`,
            {
                method: 'GET',
                headers: buildChatFetchHeaders({ 'Accept': 'application/json' }),
                cache: 'no-store'
            }
        );
        const data = await response.json().catch(() => ({}));
        if (!response.ok) return [];
        const sessions = Array.isArray(data?.sessions)
            ? data.sessions
            : (Array.isArray(data?.recent_sessions) ? data.recent_sessions : []);
        return sessions.filter((session) => String(session?.session_id || '').trim());
    } catch (error) {
        console.warn('[chatTab] Unable to load focused conversations', error);
        return [];
    }
}

async function beginFocusedConversation({ focalConceptIds, mode, sessionId = null, sessionName = null }) {
    const focus = normaliseFocusedConceptIds(focalConceptIds);
    if (!focus.length) {
        throw new Error('A focal concept is required to start a discussion.');
    }
    if (
        mode === 'assistant_opening'
        && sessionId
        && isChatPromptSessionBusy(sessionId, { includeQueued: true })
    ) {
        throw new Error('Wait for the current response before asking Von to open another discussion.');
    }

    activateTab('chatTab');
    let targetSessionId = String(sessionId || '').trim();
    let targetSessionName = String(sessionName || '').trim() || null;
    if (targetSessionId) {
        const switched = await switchToChatSession(targetSessionId);
        if (!switched?.ok) {
            throw new Error(switched?.error || 'Unable to open the selected conversation.');
        }
    } else {
        const created = await createChatSession('', { focalConceptIds: focus });
        targetSessionId = String(created?.session_id || activeChatSessionId || '').trim();
        targetSessionName = String(created?.session_name || activeChatSessionName || '').trim() || null;
        if (!targetSessionId) {
            throw new Error('Von did not create a conversation.');
        }
    }

    if (mode === 'assistant_opening') {
        if (isChatPromptSessionBusy(targetSessionId, { includeQueued: true })) {
            throw new Error('Wait for the current response before asking Von to open another discussion.');
        }
        // The request owns its visible thinking/error state.  Do not leave the
        // launch choice open for the duration of a potentially long response.
        void handleSendPrompt({
            sessionId: targetSessionId,
            sessionName: targetSessionName,
            promptOverride: '',
            turnKind: 'assistant_opening',
            initiationId: `assistant-opening:${targetSessionId}:${Date.now()}`,
            allowEmptyPrompt: true,
            skipPromptQueueRecord: true
        });
    } else {
        focusComposerForConversation();
    }
    return { sessionId: targetSessionId, mode };
}

function renderFocusedConversationLauncher({ focalConcepts, recentSessions }) {
    closeFocusedConversationLauncher();
    const focus = normaliseFocusedConcepts(focalConcepts);
    if (!focus.length || !document.body) return null;

    const launcher = document.createElement('section');
    launcher.id = 'focusedConversationLauncher';
    launcher.className = 'focused-conversation-launcher';
    launcher.setAttribute('role', 'dialog');
    launcher.setAttribute('aria-modal', 'true');
    launcher.setAttribute('aria-label', `Discuss ${focus.map((item) => item.displayName).join(', ')}`);

    const title = document.createElement('h3');
    title.textContent = `Discuss ${focus.map((item) => item.displayName).join(', ')}`;
    const description = document.createElement('p');
    description.textContent = recentSessions.length
        ? 'Continue a recent discussion, or start a new one.'
        : 'Start a discussion in your own words, or have Von open it.';
    const actions = document.createElement('div');
    actions.className = 'focused-conversation-launcher-actions';

    const addAction = (label, action, primary = false) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = primary ? 'btn btn-primary' : 'btn btn-secondary';
        button.textContent = label;
        button.addEventListener('click', async () => {
            button.disabled = true;
            try {
                await action();
                closeFocusedConversationLauncher();
            } catch (error) {
                console.error('[chatTab] Unable to begin focused conversation', error);
                showToast(error?.message || 'Could not start that conversation.', 'error');
                button.disabled = false;
            }
        });
        actions.appendChild(button);
        return button;
    };

    if (recentSessions.length) {
        const recent = recentSessions[0];
        addAction(
            `Continue${recent?.session_name ? `: ${recent.session_name}` : ''}`,
            () => beginFocusedConversation({ focalConceptIds: focus.map((item) => item.conceptId), mode: 'user_first', sessionId: recent.session_id, sessionName: recent.session_name }),
            true
        );
    }
    addAction(
        recentSessions.length ? 'New conversation — I’ll start' : 'I’ll start',
        () => beginFocusedConversation({ focalConceptIds: focus.map((item) => item.conceptId), mode: 'user_first' }),
        !recentSessions.length
    );
    addAction(
        recentSessions.length ? 'New conversation — Von starts' : 'Have Von start',
        () => beginFocusedConversation({ focalConceptIds: focus.map((item) => item.conceptId), mode: 'assistant_opening' })
    );
    addAction('Cancel', async () => {});

    launcher.append(title, description, actions);
    document.body.appendChild(launcher);
    actions.querySelector('button')?.focus();
    return launcher;
}

/**
 * Shared entry point for concept, task, and message Discuss controls.
 * The focal reference is stored on the conversation session; it is never
 * smuggled into a synthetic user prompt.
 */
export async function openFocusedConversationLauncher(options = {}) {
    const focalConceptIds = normaliseFocusedConceptIds(
        options.focalConceptIds || [options.conceptId]
    );
    if (!focalConceptIds.length) {
        showToast('This item has no usable concept reference.', 'error');
        return null;
    }
    const suppliedFocus = Array.isArray(options.focalConcepts)
        ? options.focalConcepts
        : focalConceptIds.map((conceptId, index) => ({
            concept_id: conceptId,
            display_name: index === 0 ? options.conceptName : ''
        }));
    const recentSessions = await loadRecentFocusedConversationSessions(focalConceptIds[0]);
    return renderFocusedConversationLauncher({
        focalConcepts: suppliedFocus,
        recentSessions
    });
}

function bindFocusedConversationEvents() {
    if (focusedConversationEventBound) return;
    focusedConversationEventBound = true;
    document.addEventListener('von:discussConcept', (event) => {
        const detail = event?.detail || {};
        void openFocusedConversationLauncher({
            conceptId: detail.conceptId,
            conceptName: detail.conceptName,
            focalConceptIds: detail.focalConceptIds
        });
    });
}

async function promptRenameChatSession(sessionId, currentName) {
    console.log('[chatTab] promptRenameChatSession called', { sessionId, currentName });
    const proposed = window.prompt('Rename chat', currentName || '');
    if (proposed === null) {
        console.log('[chatTab] promptRenameChatSession: user cancelled');
        return;
    }
    const trimmed = String(proposed || '').trim();
    if (!trimmed) {
        alert('Conversation name is required.');
        return;
    }
    try {
        await renameChatSession(sessionId, trimmed);
        console.log('[chatTab] promptRenameChatSession: rename succeeded');
        // Local cache is already updated in renameChatSession - no need for immediate refresh
    } catch (err) {
        console.error('[chatTab] promptRenameChatSession: rename failed', err);
        const msg = err?.message ? String(err.message) : 'Unable to rename chat.';
        alert(msg);
    }
}

async function createChatSession(sessionName, options = {}) {
    if (pendingChatOrganisationSwitchId !== null) {
        const error = new Error('Organisation change in progress.');
        error.organisationSwitchSuperseded = true;
        throw error;
    }
    const organisationGenerationAtStart = chatOrganisationGeneration;
    const payload = {};
    if (typeof sessionName === 'string' && sessionName.trim()) {
        payload.session_name = sessionName.trim();
    }
    const focalConceptIds = normaliseFocusedConceptIds(options.focalConceptIds);
    if (focalConceptIds.length) {
        payload.focal_concept_ids = focalConceptIds;
    }

    const response = await fetch('/von/api/session/create_chat_session', {
        method: 'POST',
        headers: buildChatFetchHeaders({ 'Content-Type': 'application/json' }),
        body: JSON.stringify(payload)
    });
    const data = await response.json();

    if (!isChatOrganisationRequestCurrent(organisationGenerationAtStart)) {
        const error = new Error('Organisation changed before conversation creation completed.');
        error.organisationSwitchSuperseded = true;
        throw error;
    }

    if (!response.ok) {
        const msg = data?.error ? String(data.error) : 'Unable to create chat session.';
        throw new Error(msg);
    }

    setActiveChatSession(data?.session_id, data?.session_name);
    const createdFocus = getFocusFromPayload(data);
    if (data?.session_id) {
        acceptChatSessionFocus(data.session_id, createdFocus);
    }
    _acceptConversationSituationPayload(
        _conversationSituationPayloadHasCarrierState(data)
            ? data
            : {
                conversation_situation: null,
                conversation_observations: [],
                conversation_observation_state: {
                    schema_version: 'conversation_observation_state.v1',
                    retained_count: 0,
                    total_count: 0,
                    omitted_count: 0,
                    retention_limit: 12
                }
            },
        data?.session_id,
        { authoritativeSnapshot: true }
    );
    syncActiveChatSessionThinkingState();

    const nowIso = new Date().toISOString();
    const effectiveSessionId = (typeof data?.session_id === 'string' && data.session_id.trim())
        ? data.session_id.trim()
        : activeChatSessionId;
    const effectiveName = (typeof data?.session_name === 'string' && data.session_name.trim())
        ? data.session_name.trim()
        : (typeof sessionName === 'string' && sessionName.trim())
            ? sessionName.trim()
            : '';

    if (effectiveSessionId) {
        const newSession = normaliseConversationSessionViewModel({
            session_id: effectiveSessionId,
            session_name: effectiveName || null,
            message_count: 0,
            last_message_at: nowIso,
            created_at: nowIso,
            is_completed: false,
            completed_at: null
        });
        sessionTabsCache = normaliseConversationSessionViewModels([
            newSession,
            ...sessionTabsCache.filter(s => String(s?.session_id || '') !== effectiveSessionId)
        ]);
        renderChatSessionTabs(sessionTabsCache, effectiveSessionId);
        if (!createdFocus.length && focalConceptIds.length) {
            void loadChatSessionFocus(effectiveSessionId, { force: true });
        }
    }

    // Metadata editor: start with a fresh load for the new session.
    chatSessionMetadataOpenKey = null;
    if (effectiveSessionId) {
        void loadChatSessionLinks(effectiveSessionId, { force: true });
    }

    const history = Array.isArray(data?.history) ? data.history : [];
    const scrollableField = document.getElementById('scrollableField');
    if (scrollableField) {
        historySegmentsShown = history.length ? 1 : 0;
        totalHistorySegments = history.length ? 1 : 0;
        updateHistoryBanner();
        rehydrateHistory(scrollableField, history, {
            scrollToBottom: true,
            preserveScroll: false,
            showResetNotice: false,
            forceScrollToBottom: true
        });
    }

    const composerValue = options.preserveComposerDraft
        ? String(getPromptInputElement()?.value || '')
        : '';
    setPromptComposerValue(composerValue, { focus: true });

    document.dispatchEvent(new CustomEvent('von:contextReset', {
        detail: { trigger: 'chat_new_session', session_id: effectiveSessionId, session_name: effectiveName || null }
    }));

    scheduleChatSessionTabsRefresh(true);
    return data;
}

async function ensurePromptTargetChatSession(options = {}) {
    let targetSessionId = normaliseHistorySessionId(
        options?.sessionId ?? activeChatSessionId
    );
    let targetSessionName = (typeof options?.sessionName === 'string' && options.sessionName.trim())
        ? options.sessionName.trim()
        : activeChatSessionName;

    if (targetSessionId) {
        return { sessionId: targetSessionId, sessionName: targetSessionName };
    }

    await refreshChatSessionTabs();

    targetSessionId = normaliseHistorySessionId(activeChatSessionId);
    targetSessionName = (typeof activeChatSessionName === 'string' && activeChatSessionName.trim())
        ? activeChatSessionName.trim()
        : targetSessionName;
    if (targetSessionId) {
        if (displayedHistorySessionId !== targetSessionId) {
            const switchResult = await switchToChatSession(targetSessionId);
            if (switchResult?.ok) {
                const switchedSessionId = normaliseHistorySessionId(
                    switchResult?.data?.session_id ?? targetSessionId
                );
                if (switchedSessionId) {
                    targetSessionId = switchedSessionId;
                }
                if (
                    typeof switchResult?.data?.session_name === 'string'
                    && switchResult.data.session_name.trim()
                ) {
                    targetSessionName = switchResult.data.session_name.trim();
                }
            }
        }
        return { sessionId: targetSessionId, sessionName: targetSessionName };
    }

    const recentSession = _getMostRecentSessionMeta();
    const recentSessionId = normaliseHistorySessionId(recentSession?.session_id);
    if (recentSessionId) {
        const switchResult = await switchToChatSession(recentSessionId);
        if (switchResult?.ok) {
            return {
                sessionId: normaliseHistorySessionId(
                    switchResult?.data?.session_id ?? recentSessionId
                ) || recentSessionId,
                sessionName: (
                    typeof switchResult?.data?.session_name === 'string'
                    && switchResult.data.session_name.trim()
                )
                    ? switchResult.data.session_name.trim()
                    : recentSession?.session_name || targetSessionName || null
            };
        }
    }

    const createdSession = await createChatSession(targetSessionName);
    const createdSessionId = normaliseHistorySessionId(
        createdSession?.session_id ?? activeChatSessionId
    );
    const createdSessionName = (
        typeof createdSession?.session_name === 'string'
        && createdSession.session_name.trim()
    )
        ? createdSession.session_name.trim()
        : targetSessionName;
    if (!createdSessionId) {
        throw new Error('Unable to create a chat session for this prompt.');
    }
    return { sessionId: createdSessionId, sessionName: createdSessionName };
}

async function renameChatSession(sessionId, sessionName) {
    const sid = (typeof sessionId === 'string') ? sessionId.trim() : '';
    if (!sid) {
        throw new Error('session_id required');
    }

    const name = (typeof sessionName === 'string') ? sessionName.trim() : '';
    if (!name) {
        throw new Error('session_name required');
    }

    console.log('[chatTab] renameChatSession request', { session_id: sid, session_name: name });
    const response = await fetch('/von/api/session/rename_chat_session', {
        method: 'POST',
        headers: buildChatFetchHeaders({ 'Content-Type': 'application/json' }),
        body: JSON.stringify({ session_id: sid, session_name: name })
    });
    const data = await response.json();
    console.log('[chatTab] renameChatSession response', { ok: response.ok, status: response.status, data });

    if (!response.ok) {
        const msg = data?.error ? String(data.error) : 'Unable to rename chat session.';
        console.error('[chatTab] renameChatSession error', msg);
        throw new Error(msg);
    }

    if (sid === activeChatSessionId) {
        setActiveChatSession(sid, data?.session_name);
    }

    if (sid) {
        const updatedName = (typeof data?.session_name === 'string' && data.session_name.trim())
            ? data.session_name.trim()
            : name;
        sessionTabsCache = normaliseConversationSessionViewModels(
            sessionTabsCache.map((session) => {
                if (String(session?.session_id || '') !== sid) {
                    return session;
                }
                return {
                    ...session,
                    session_name: updatedName
                };
            })
        );
        renderChatSessionTabs(sessionTabsCache, activeChatSessionId || sid);
    }

    // Skip immediate refresh - the local cache update above is sufficient.
    // An immediate refresh can race with MongoDB and overwrite the new name with stale data.
    return data;
}

async function switchToChatSession(sessionId, options = {}) {
    const sid = String(sessionId || '').trim();
    if (!sid) {
        return { ok: false, error: 'session_id required' };
    }
    const requestedTimeoutMs = Number(options?.requestTimeoutMs);
    const requestTimeoutMs = Number.isFinite(requestedTimeoutMs) && requestedTimeoutMs > 0
        ? requestedTimeoutMs
        : CHAT_SESSION_SWITCH_REQUEST_TIMEOUT_MS;

    const previousSessionId = activeChatSessionId;
    const previousSessionName = activeChatSessionName;

    // Session selection is latency-critical. Cancel superseded selection work
    // and optional transcript decoration before it can monopolise the browser's
    // per-origin request slots.
    cancelActiveChatSessionSwitch('superseded');
    cancelChatConceptMetaHydration();

    // JVNAUTOSCI-1002: Sync SSE streams when switching away from session
    if (previousSessionId && previousSessionId !== sid) {
        syncSharedConversationStreams();
    }

    // Best-effort: flush any pending metadata save before switching away.
    if (previousSessionId) {
        void _flushPendingChatSessionLinksSave(previousSessionId);
    }
    const cachedSession = sessionTabsCache.find(
        session => String(session?.session_id || '') === sid
    );
    const targetName = cachedSession?.session_name || null;
    const shouldReuseCachedHistory = canReuseSessionHistory(sid);
    const switchStart = performance.now();
    console.log('[chatTab] switchToChatSession start', {
        from_session_id: previousSessionId || null,
        from_session_name: previousSessionName || null,
        to_session_id: sid,
        to_session_name: targetName,
        cache_reuse: shouldReuseCachedHistory
    });

    // Focus projections are actor-scoped.  Clear any local rendering cache
    // before selecting the session; it will be repopulated only by the
    // server-authorised focus read after the switch succeeds.
    clearChatSessionFocus(sid);
    setActiveChatSession(sid, cachedSession?.session_name);
    const selectionGeneration = chatSessionSelectionGeneration;
    const isCurrentSelection = () => (
        chatSessionSelectionGeneration === selectionGeneration
        && activeChatSessionId === sid
    );
    const finishSupersededSwitch = () => {
        setChatSessionTabLoading(sid, false);
        return { ok: false, superseded: true };
    };
    clearSharedSessionUnread(sid);
    clearLatestUnreadBoundary();
    hideNewSharedMessagesIndicator();
    if (sessionTabsCache.length > 0) {
        renderChatSessionTabs(sessionTabsCache, sid);
    }
    setChatSessionTabLoading(sid, true);

    // Render metadata panel immediately (cached if available).
    chatSessionMetadataOpenKey = null;
    void loadChatSessionLinks(sid, { force: false });

    abortActiveHistoryRequest();
    syncActiveChatSessionThinkingState();

    const scrollableField = document.getElementById('scrollableField');
    if (!scrollableField) {
        setChatSessionTabLoading(sid, false);
        return { ok: false, error: 'Conversation panel unavailable.' };
    }

    const restorePreviousSession = (failureMessage) => {
        setActiveChatSession(previousSessionId, previousSessionName);
        if (sessionTabsCache.length > 0) {
            renderChatSessionTabs(sessionTabsCache, previousSessionId || sid);
        }

        chatSessionMetadataOpenKey = null;
        if (previousSessionId) {
            void loadChatSessionLinks(previousSessionId, { force: false });
        } else {
            _clearChatSessionMetadata();
        }

        setChatSessionTabLoading(sid, false);
        const cached = previousSessionId
            ? getSessionHistoryCache(previousSessionId)
            : null;
        const restoredFromCache = cached
            ? rehydrateFromCache(scrollableField, cached)
            : false;
        if (restoredFromCache) {
            displayedHistorySessionId = previousSessionId;
            clearHistoryLoadState({ sessionId: previousSessionId });
            return true;
        }

        scrollableField.innerHTML = (
            `<div class="chat-session-loading">${escapeHtml(failureMessage)}</div>`
        );
        void loadChatHistory({
            segments: 1,
            scrollToBottom: true,
            showResetNotice: false,
            forceScrollToBottom: true
        });
        return false;
    };

    scrollableField.innerHTML = '<div class="chat-session-loading">Switching chat…</div>';
    transcriptTurns.length = 0;
    clearLlmDebugDataEntries();
    displayedHistorySessionId = null;
    clearHistoryLoadState();
    historySegmentsShown = 0;
    totalHistorySegments = 0;
    updateHistoryBanner();

    const switchRequest = createChatSessionSwitchRequest(sid, requestTimeoutMs);
    try {
        let response = null;
        let data = null;
        let setSessionMs = 0;
        const maxAttempts = 2;
        try {
            for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
                const setSessionStart = performance.now();
                response = await Promise.race([
                    fetch('/von/api/session/set_chat_session', {
                        method: 'POST',
                        headers: buildChatFetchHeaders({ 'Content-Type': 'application/json' }),
                        body: JSON.stringify({ session_id: sid, include_history: false }),
                        signal: switchRequest.abortController.signal
                    }),
                    switchRequest.cancellationPromise
                ]);
                data = await Promise.race([
                    response.json().catch(() => ({})),
                    switchRequest.cancellationPromise
                ]);
                if (!isCurrentSelection()) {
                    return finishSupersededSwitch();
                }
                setSessionMs = Math.round(performance.now() - setSessionStart);
                console.log('[chatTab] switchToChatSession set_chat_session', {
                    ok: response.ok,
                    status: response.status,
                    duration_ms: setSessionMs,
                    session_id: data?.session_id || sid,
                    attempt
                });

                if (response.ok) {
                    break;
                }

                const retryable = Boolean(data?.retryable) || response.status === 503;
                if (!retryable || attempt >= maxAttempts) {
                    break;
                }
                await Promise.race([
                    new Promise((resolve) => setTimeout(resolve, 320)),
                    switchRequest.cancellationPromise
                ]);
                if (!isCurrentSelection()) {
                    return finishSupersededSwitch();
                }
            }
        } finally {
            finishChatSessionSwitchRequest(switchRequest);
        }

        if (!response) {
            throw new Error('No response from set_chat_session');
        }

        if (!response.ok) {
            const msg = data?.error ? String(data.error) : 'Unable to switch session.';
            restorePreviousSession(msg);
            return { ok: false, error: msg };
        }

        const responseSessionId = normaliseHistorySessionId(data?.session_id);
        if (responseSessionId !== sid) {
            throw new Error('Conversation switch response did not match the selected session.');
        }

        if (isConceptQaSession(data) || isConceptQaSession(data?.qa_session)) {
            rememberConceptQaSession(data?.qa_session || data, { sessionId: sid });
        }

        setActiveChatSession(
            data?.session_id,
            data?.session_name,
            data?.external_conversation
        );

        // Refresh metadata (server-side session may have changed).
        const effectiveMetaSessionId = (typeof data?.session_id === 'string' && data.session_id.trim())
            ? data.session_id.trim()
            : sid;
        chatSessionMetadataOpenKey = null;
        void loadChatSessionLinks(effectiveMetaSessionId, { force: true });
        void loadChatSessionFocus(effectiveMetaSessionId, { force: true });

        if (shouldReuseCachedHistory) {
            const cached = getSessionHistoryCache(sid);
            const reused = rehydrateFromCache(scrollableField, cached);
            console.log('[chatTab] switchToChatSession cache reuse', {
                loaded: reused,
                cached_messages: cached?.history?.length ?? 0,
                session_id: sid
            });
            if (!reused) {
                scrollableField.innerHTML = '';
                displayedHistorySessionId = null;
            } else {
                displayedHistorySessionId = sid;
                clearHistoryLoadState({ sessionId: sid });
            }
            setChatSessionTabLoading(sid, false);
        } else {
            const recentStart = performance.now();
            const loaded = await loadRecentChatPair({
                scrollToBottom: true,
                preserveScroll: false,
                showResetNotice: false,
                forceScrollToBottom: true
            });
            if (!isCurrentSelection()) {
                return finishSupersededSwitch();
            }
            const recentMs = Math.round(performance.now() - recentStart);
            console.log('[chatTab] switchToChatSession recent pair', {
                loaded,
                duration_ms: recentMs,
                session_id: sid
            });
            if (!loaded && !isHistoryLoadStateActiveForSession(sid)) {
                scrollableField.innerHTML = '';
            }

            setTimeout(() => {
                if (!isCurrentSelection()) {
                    setChatSessionTabLoading(sid, false);
                    return;
                }
                console.log('[chatTab] switchToChatSession backfill start', { session_id: sid });
                const backfillPromise = loadChatHistory({
                    segments: 1,
                    scrollToBottom: false,
                    preserveScroll: true,
                    showResetNotice: false
                });
                backfillPromise.finally(() => {
                    if (isCurrentSelection()) {
                        setChatSessionTabLoading(sid, false);
                    }
                });
            }, 250);
        }

        document.dispatchEvent(new CustomEvent('von:contextReset', {
            detail: { trigger: 'history_session_switch', session_id: sid, session_name: data?.session_name || targetName }
        }));

        // JVNAUTOSCI-1002: Ensure shared conversation streams are in sync
        syncSharedConversationStreams();

        const promptInput = getPromptInputElement();
        if (promptInput) {
            promptInput.focus();
        }

        scheduleChatSessionTabsRefresh(true);
        console.log('[chatTab] switchToChatSession done', {
            session_id: sid,
            duration_ms: Math.round(performance.now() - switchStart)
        });
        return { ok: true, data };
    } catch (err) {
        if (!isCurrentSelection()) {
            return finishSupersededSwitch();
        }
        const timedOut = err?.name === 'TimeoutError' || switchRequest.cancelReason === 'timeout';
        if (timedOut) {
            console.warn('[chatTab] Conversation switch timed out', {
                session_id: sid,
                timeout_ms: requestTimeoutMs
            });
        } else {
            console.error('Error switching chat session:', err);
        }
        const failureMessage = timedOut
            ? 'Conversation switch timed out. Restoring the previous conversation…'
            : 'Unable to switch session.';
        restorePreviousSession(failureMessage);
        console.log('[chatTab] switchToChatSession failed', {
            session_id: sid,
            reason: timedOut ? 'timeout' : 'error',
            duration_ms: Math.round(performance.now() - switchStart)
        });
        return {
            ok: false,
            error: timedOut ? 'Conversation switch timed out.' : 'Unable to switch session.',
            retryable: timedOut
        };
    }
}

function indicateClipboardResult(button, originalContent, isSuccess) {
    if (!button) {
        return;
    }

    const successClass = 'success-feedback';
    const errorClass = 'error-feedback';
    button.classList.remove(successClass, errorClass);
    button.innerHTML = isSuccess ? '<span class="btn-icon">✓</span>' : '<span class="btn-icon">!</span>';
    button.classList.add(isSuccess ? successClass : errorClass);
    setTimeout(() => {
        button.innerHTML = originalContent;
        button.classList.remove(successClass, errorClass);
    }, 1500);
}

function copyTextFallback(text) {
    if (typeof document === 'undefined') {
        return false;
    }

    const textarea = document.createElement('textarea');
    textarea.value = text;
    textarea.style.position = 'fixed';
    textarea.style.opacity = '0';
    textarea.setAttribute('readonly', '');
    document.body.appendChild(textarea);
    textarea.focus();
    textarea.select();

    let successful = false;
    try {
        if (typeof document.execCommand === 'function') {
            successful = document.execCommand('copy');
        }
    } catch (err) {
        console.error('[chatTab] Failed to copy text via fallback:', err);
        successful = false;
    } finally {
        document.body.removeChild(textarea);
    }

    return successful;
}

async function copyTextToClipboard(text) {
    return copyTextWithClipboardFallback(text);
}

async function copyJsonPayloadToClipboard(payload, button = null, fallbackLabel = 'Copy JSON') {
    if (!payload || typeof payload !== 'object') {
        return false;
    }
    let jsonString;
    try {
        jsonString = JSON.stringify(payload, null, 2);
    } catch (_) {
        return false;
    }

    if (button instanceof HTMLButtonElement) {
        return copyJsonTextWithButtonFeedback(button, jsonString, { fallbackLabel });
    }
    return copyTextToClipboard(jsonString);
}

// Delete exchange (top-level so event handlers can access it)
function deleteExchange(turnId, isUserMessage) {
    const scrollableField = document.getElementById('scrollableField');
    if (!scrollableField) return;

    // Find message containers (may be paired user + assistant)
    const messageContainers = scrollableField.querySelectorAll(`[data-turn-id="${turnId}"]`);
    if (messageContainers.length === 0) return;

    // Get message text for warning check
    let totalLength = 0;
    messageContainers.forEach(container => {
        const text = container.textContent || '';
        totalLength += text.length;
    });

    const isSignificant = totalLength > 200;
    const exchangeType = isUserMessage ? 'user message' : 'Von response';
    let confirmMessage = `Delete this ${exchangeType}?`;

    if (isSignificant) {
        confirmMessage += `\n\nWARNING: This exchange contains significant content (${totalLength} characters).`;
    }

    if (!confirm(confirmMessage)) {
        return;
    }

    messageContainers.forEach(container => {
        container.remove();
    });

    // Remove from transcript
    const index = transcriptTurns.findIndex(t => t.turnId === turnId);
    if (index !== -1) {
        transcriptTurns.splice(index, 1);
    }

    // If it was the only exchange, reload previous context
    const remainingMessages = scrollableField.querySelectorAll('.message-container').length;
    if (remainingMessages === 0) {
        console.log('[chatTab] Last exchange deleted, reloading previous context...');
        loadChatHistory({ segments: historySegmentsShown });
    }

    // Update history counts
    updateHistoryBanner();
    updateHistoryLength();
}

async function updateHistoryLength() {
    try {
        const response = await fetch('/von/history/length', {
            headers: buildChatFetchHeaders()
        });
        const data = await response.json().catch(() => ({}));

        if (response.ok) {
            const historyLength = Number.isFinite(Number(data?.history_length))
                ? Number(data.history_length)
                : 0;
            const sessionCount = (typeof data.session_count === 'number') ? data.session_count : null;
            const authenticated = data.authenticated !== undefined ? data.authenticated : true;
            const historyLengthElement = document.getElementById('chat-history-length');
            if (historyLengthElement) {
                if (!authenticated) {
                    historyMetricsState.degraded = false;
                    historyMetricsState.lastHealthy = null;
                    historyLengthElement.textContent = 'History: unauthenticated';
                    historyLengthElement.title = 'Conversation history unavailable until you log in.';
                } else if (data?.degraded === true) {
                    historyMetricsState.degraded = true;
                    historyMetricsState.message = (typeof data?.error === 'string' && data.error.trim())
                        ? data.error.trim()
                        : 'Conversation history metrics temporarily unavailable.';
                    historyMetricsState.retryable = Boolean(data?.retryable);
                    historyMetricsState.detail = (typeof data?.detail === 'string' && data.detail.trim())
                        ? data.detail.trim()
                        : '';
                    const contextCount = transcriptTurns.length;
                    const cached = (
                        historyMetricsState.lastHealthy
                        && typeof historyMetricsState.lastHealthy === 'object'
                    ) ? historyMetricsState.lastHealthy : null;
                    if (cached) {
                        const conversationsText = cached.sessionCount === null
                            ? '- conversations'
                            : `${cached.sessionCount} conversations`;
                        historyLengthElement.textContent = `History: ${conversationsText} | this ${contextCount} (stale)`;
                        historyLengthElement.title = `${historyMetricsState.message} Showing last loaded totals: ${cached.sessionCount ?? '—'} conversations • ${cached.historyLength ?? '—'} messages.`;
                    } else {
                        historyLengthElement.textContent = `History: temporarily unavailable | this ${contextCount}`;
                        historyLengthElement.title = historyMetricsState.message;
                    }
                } else {
                    historyMetricsState.degraded = false;
                    historyMetricsState.message = '';
                    historyMetricsState.retryable = false;
                    historyMetricsState.detail = '';
                    historyMetricsState.lastHealthy = {
                        historyLength,
                        sessionCount,
                        authenticated: true
                    };
                    const contextCount = transcriptTurns.length;
                    const conversationsText = (sessionCount === null) ? '- conversations' : `${sessionCount} conversations`;
                    historyLengthElement.textContent = `History: ${conversationsText} | this ${contextCount}`;
                    historyLengthElement.title = `Conversation history: ${sessionCount ?? '—'} conversations • total ${historyLength} messages • this session ${contextCount} messages`;
                }

                // Wire a lightweight history popup (scrollable list of sessions).
                if (!historyLengthElement._wired) {
                    historyLengthElement._wired = true;
                    historyLengthElement.style.cursor = 'pointer';
                    historyLengthElement.addEventListener('click', async () => {
                        const modal = document.getElementById('historyStatusModal');
                        const body = document.getElementById('historyStatusBody');
                        const closeBtn = document.getElementById('historyStatusClose');
                        const titleEl = document.getElementById('historyStatusTitle');
                        if (!modal || !body) {
                            return;
                        }

                        try {
                            modal.classList.add('open');
                            modal.setAttribute('aria-hidden', 'false');
                            body.innerHTML = '<p>Loading…</p>';

                            if (titleEl) {
                                titleEl.textContent = 'Conversation history';
                            }

                            if (closeBtn && !closeBtn._wired) {
                                closeBtn._wired = true;
                                closeBtn.addEventListener('click', () => {
                                    modal.classList.remove('open');
                                    modal.setAttribute('aria-hidden', 'true');
                                });
                            }

                            // Fetch a fresh summary for the header.
                            let totalMessages = null;
                            let conversations = null;
                            try {
                                const lenRes = await fetch('/von/history/length', {
                                    cache: 'no-store',
                                    headers: buildChatFetchHeaders()
                                });
                                if (lenRes.ok) {
                                    const lenJs = await lenRes.json();
                                    totalMessages = (typeof lenJs?.history_length === 'number') ? lenJs.history_length : null;
                                    conversations = (typeof lenJs?.session_count === 'number') ? lenJs.session_count : null;
                                }
                            } catch (_) { /* ignore */ }

                            const res = await fetch(buildChatSessionTabsFetchUrl(), {
                                cache: 'no-store',
                                headers: buildChatFetchHeaders()
                            });
                            const js = await res.json();
                            if (!res.ok || js?.authenticated === false) {
                                body.innerHTML = '<p>History unavailable (not logged in).</p>';
                                return;
                            }

                            const sessions = Array.isArray(js?.sessions) ? js.sessions : [];
                            const activeSessionId = (typeof js?.active_session_id === 'string')
                                ? js.active_session_id
                                : null;
                            if (activeSessionId) {
                                const activeSession = sessions.find(
                                    s => (typeof s?.session_id === 'string') && s.session_id === activeSessionId
                                );
                                setActiveChatSession(activeSessionId, activeSession?.session_name);
                            }
                            if (sessions.length === 0) {
                                body.innerHTML = '<p>No saved sessions.</p>';
                                return;
                            }

                            const currentCount = transcriptTurns.length;
                            if (titleEl) {
                                const conversationsText2 = (conversations === null) ? '— conversations' : `${conversations} conversations`;
                                const totalText2 = (totalMessages === null) ? '— total' : `${totalMessages} total`;
                                titleEl.textContent = `Conversation history — ${conversationsText2} • ${totalText2} • this ${currentCount}`;
                            }

                            const rows = sessions.map((s) => {
                                const sidRaw = s?.session_id ? String(s.session_id) : '(unknown session)';
                                const sidShort = (sidRaw.length > 10) ? `${sidRaw.slice(0, 8)}.` : sidRaw;
                                const count = (typeof s?.message_count === 'number') ? s.message_count : 0;

                                const lastAt = (typeof s?.last_message_at === 'string') ? s.last_message_at : null;
                                const lastAtShort = lastAt ? lastAt.replace('T', ' ').replace('Z', '') : '-';
                                const preview = (typeof s?.preview === 'string' && s.preview.trim()) ? s.preview.trim() : '-';

                                const nameRaw = (typeof s?.session_name === 'string' && s.session_name.trim())
                                    ? s.session_name.trim()
                                    : null;
                                const displayName = nameRaw || sidShort;
                                const nameTitle = nameRaw || sidRaw;

                                const ns = (typeof s?.namespace === 'string' && s.namespace.trim()) ? s.namespace.trim() : null;
                                const nsShort = ns ? (ns.length > 48 ? `${ns.slice(0, 46)}.` : ns) : null;

                                const sessionAttr = escapeHtml(sidRaw);
                                const nameAttr = nameRaw ? escapeHtml(nameRaw) : '';
                                const isActive = activeSessionId && sidRaw === activeSessionId;
                                const isCompleted = s?.is_completed === true;
                                const isShared = Boolean(s?.shared_with_me || s?.shared_from_user_id || s?.invite_id);
                                const rowClass = `history-session-row${isActive ? ' is-active' : ''}${isCompleted ? ' is-completed' : ''}${isShared ? ' is-shared' : ''}`;
                                const idSnippet = nameRaw ? ` · id ${escapeHtml(sidShort)}` : '';
                                const completionSnippet = isCompleted
                                    ? ` · ${escapeHtml(formatCompletedLabel(s?.completed_at))}`
                                    : '';

                                return [
                                    `<li class="${rowClass}" role="button" tabindex="0" data-session-id="${sessionAttr}" data-session-name="${nameAttr}">`,
                                    '<div class="history-session-content">',
                                    `<strong class="history-session-id" title="${escapeHtml(nameTitle)}">${escapeHtml(displayName)}</strong>`,
                                    `<span class="history-session-meta">${count} msgs · last ${escapeHtml(lastAtShort)}${completionSnippet}${idSnippet}${nsShort ? ` · ns ${escapeHtml(nsShort)}` : ''}</span>`,
                                    `<span class="history-session-preview" title="${escapeHtml(preview)}">${escapeHtml(preview)}</span>`,
                                    '</div>',
                                    '</li>'
                                ].join('');
                            });

                            const summaryLine = `Showing ${sessions.length} most recent sessions (sorted by last message time)`;

                            body.innerHTML = [
                                `<p class="history-session-summary">${escapeHtml(summaryLine)}</p>`,
                                '<div class="history-session-scroll">',
                                '<ul class="history-session-list">',
                                ...rows,
                                '</ul>',
                                '</div>'
                            ].join('');

                            const switchToSession = async (sessionId) => {
                                const sid = String(sessionId || '').trim();
                                if (!sid) {
                                    return;
                                }

                                body.innerHTML = '<p>Switching session.</p>';
                                const result = await switchToChatSession(sid);
                                if (!result.ok) {
                                    body.innerHTML = `<p>${escapeHtml(result.error || 'Unable to switch session.')}</p>`;
                                    return;
                                }

                                modal.classList.remove('open');
                                modal.setAttribute('aria-hidden', 'true');
                            };

                            const list = body.querySelector('.history-session-list');
                            if (list && !list._wiredSessionSwitch) {
                                list._wiredSessionSwitch = true;

                                list.addEventListener('click', (e) => {
                                    const row = e.target?.closest ? e.target.closest('.history-session-row') : null;
                                    const sid = row?.dataset?.sessionId;
                                    if (sid) {
                                        void switchToSession(sid);
                                    }
                                });

                                list.addEventListener('keydown', (e) => {
                                    if (e.key !== 'Enter' && e.key !== ' ') {
                                        return;
                                    }
                                    const row = e.target?.closest ? e.target.closest('.history-session-row') : null;
                                    const sid = row?.dataset?.sessionId;
                                    if (sid) {
                                        e.preventDefault();
                                        void switchToSession(sid);
                                    }
                                });
                            }

                        } catch (err) {
                            console.error('Error loading history sessions:', err);
                            body.innerHTML = '<p>Unable to load history sessions.</p>';
                        }
                    });
                }
            }

            scheduleChatSessionTabsRefresh();
        } else {
            console.error('Failed to load Conversation history length:', data.error);
        }
    } catch (error) {
        console.error('Error loading Conversation history length:', error);
    }
}

async function loadChatHistory(options = {}) {
    const {
        segments,
        scrollToBottom = true,
        preserveScroll = false,
        showResetNotice = false,
        forceScrollToBottom = false,
        segmentSizeOverride = null,
        tailLimit = null,
        filterRecentPair = false
    } = options;

    const scrollableField = document.getElementById('scrollableField');
    if (!scrollableField) {
        console.error('scrollableField not found');
        return false;
    }
    if (pendingChatOrganisationSwitchId !== null) {
        return false;
    }
    const organisationGenerationAtStart = chatOrganisationGeneration;

    const requestedSegments = Number.isInteger(segments) && segments > 0 ? segments : historySegmentsShown;
    const segmentCount = Math.max(requestedSegments || 1, 1);

    await _ensureInviteSessionContext();
    if (!isChatOrganisationRequestCurrent(organisationGenerationAtStart)) {
        return false;
    }

    const requestedSessionId = normaliseHistorySessionId(activeChatSessionId);
    clearHistoryLoadState({ sessionId: requestedSessionId });
    updateHistoryBanner();
    abortActiveHistoryRequest();
    const requestId = ++historyRequestCounter;
    const abortController = new AbortController();
    activeHistoryRequest = {
        id: requestId,
        sessionId: requestedSessionId,
        abortController,
        aborted: false
    };

    // Get user context to ensure we can load history even if session is new
    const userContext = getUserContext();
    const params = new URLSearchParams({ segments: segmentCount.toString() });
    if (userContext && userContext.user_id) {
        params.append('user_id', userContext.user_id);
    }
    if (requestedSessionId) {
        params.append('session_id', requestedSessionId);
    }
    const effectiveSegmentSize = Number.isInteger(segmentSizeOverride) && segmentSizeOverride > 0
        ? segmentSizeOverride
        : HISTORY_SEGMENT_SIZE;
    if (effectiveSegmentSize > 0) {
        params.append('segment_size', effectiveSegmentSize.toString());
    }
    if (Number.isInteger(tailLimit) && tailLimit > 0) {
        params.append('tail_limit', tailLimit.toString());
    }
    params.append('include_debug', '0');
    try {
        console.log('[chatTab] loadChatHistory request', {
            session_id: requestedSessionId || null,
            segments: segmentCount,
            segment_size: effectiveSegmentSize,
            tail_limit: Number.isInteger(tailLimit) ? tailLimit : null,
            filter_recent_pair: !!filterRecentPair
        });
        const response = await fetch(`/von/history?${params.toString()}`, {
            signal: abortController.signal,
            headers: buildChatFetchHeaders()
        });
        const data = await response.json().catch(() => ({}));

        if (isConceptQaSession(data) || isConceptQaSession(data?.qa_session)) {
            rememberConceptQaSession(data?.qa_session || data, {
                sessionId: requestedSessionId,
            });
            renderConceptQaConversationControls();
        }

        if (!isChatOrganisationRequestCurrent(organisationGenerationAtStart)) {
            return false;
        }
        if (!activeHistoryRequest || activeHistoryRequest.id !== requestId) {
            return false;
        }
        if (requestedSessionId !== normaliseHistorySessionId(activeChatSessionId)) {
            return false;
        }

        const targetSessionId = normaliseHistorySessionId(requestedSessionId || activeChatSessionId);
        const canPreserveRenderedHistory = shouldPreserveRenderedHistoryForSession(
            scrollableField,
            targetSessionId
        );

        console.log(`[chatTab] loadChatHistory response: ok=${response.ok}, segments=${data.segments_returned}, total=${data.total_segments}, history_len=${data.history ? data.history.length : 'undefined'}`);

        if (data?.degraded === true) {
            const degradedMessage = describeHistoryUnavailable(data);
            _markConversationSituationUnavailable(targetSessionId, degradedMessage);
            setHistoryLoadState({
                sessionId: targetSessionId,
                message: degradedMessage,
                retryable: Boolean(data?.retryable),
                detail: typeof data?.detail === 'string' ? data.detail : ''
            });
            if (!canPreserveRenderedHistory) {
                scrollableField.innerHTML = `<div class="chat-session-loading">${escapeHtml(degradedMessage)}</div>`;
                displayedHistorySessionId = null;
            }
            console.warn('[chatTab] loadChatHistory degraded', {
                session_id: targetSessionId,
                status: response.status,
                retryable: Boolean(data?.retryable),
                detail: data?.detail || null
            });
            updateHistoryBanner();
            if (activeHistoryRequest && activeHistoryRequest.id === requestId) {
                activeHistoryRequest = null;
            }
            return false;
        }

        if (response.ok && _conversationSituationPayloadHasCompleteCarrierState(data)) {
            _acceptConversationSituationPayload(data, targetSessionId, {
                authoritativeSnapshot: true,
                notice: 'Conversation situation loaded.'
            });
        } else if (response.ok) {
            _markConversationSituationUnavailable(
                targetSessionId,
                'The server did not return conversation situation state; try refreshing again.'
            );
        }

        if (response.ok && Array.isArray(data?.history)) {
            const historyMessages = filterRecentPair
                ? selectRecentChatPair(data.history)
                : data.history;
            const hasMoreHistory = data?.has_more_history === true;
            const segmentsReturned = Math.max(data.segments_returned || segmentCount, 0);
            let totalSegments = Math.max(data.total_segments || segmentsReturned, segmentsReturned);
            if (hasMoreHistory && totalSegments <= segmentsReturned) {
                totalSegments = segmentsReturned + 1;
            }
            historySegmentsShown = segmentsReturned;
            totalHistorySegments = totalSegments;

            rehydrateHistory(scrollableField, historyMessages, {
                scrollToBottom,
                preserveScroll,
                showResetNotice,
                forceScrollToBottom
            });

            displayedHistorySessionId = targetSessionId;
            _renderLateWorkflowOutcomesForActiveSession();
            clearHistoryLoadState({ sessionId: targetSessionId });
            updateHistoryBanner();
            const sessionMeta = sessionTabsCache.find(
                session => String(session?.session_id || '') === String(requestedSessionId || '')
            );
            updateSessionHistoryCache(requestedSessionId, historyMessages, {
                message_count: sessionMeta?.message_count ?? null,
                last_message_at: sessionMeta?.last_message_at ?? null,
                segments: historySegmentsShown,
                total_segments: totalHistorySegments
            });
            console.log(`Loaded ${data.history.length} historical messages across ${historySegmentsShown} segment(s)`);
            if (activeHistoryRequest && activeHistoryRequest.id === requestId) {
                activeHistoryRequest = null;
            }
            return true;
        }

        if (!response.ok) {
            const fallbackMessage = (typeof data?.error === 'string' && data.error.trim())
                ? data.error.trim()
                : 'Conversation history request failed; please retry.';
            _markConversationSituationUnavailable(targetSessionId, fallbackMessage);
            setHistoryLoadState({
                sessionId: targetSessionId,
                message: fallbackMessage,
                retryable: Boolean(data?.retryable) || response.status >= 500,
                detail: typeof data?.detail === 'string' ? data.detail : ''
            });
            if (!canPreserveRenderedHistory) {
                scrollableField.innerHTML = `<div class="chat-session-loading">${escapeHtml(fallbackMessage)}</div>`;
                displayedHistorySessionId = null;
            }
            updateHistoryBanner();
            if (activeHistoryRequest && activeHistoryRequest.id === requestId) {
                activeHistoryRequest = null;
            }
            return false;
        }

        const hasMoreHistory = data?.has_more_history === true;
        const segmentsReturned = Math.max(data?.segments_returned || 0, 0);
        let totalSegments = Math.max(data?.total_segments || segmentsReturned, segmentsReturned);
        if (hasMoreHistory && totalSegments <= segmentsReturned) {
            totalSegments = segmentsReturned + 1;
        }
        historySegmentsShown = segmentsReturned;
        totalHistorySegments = totalSegments;
        displayedHistorySessionId = targetSessionId;
        _renderLateWorkflowOutcomesForActiveSession();
        clearHistoryLoadState({ sessionId: targetSessionId });
        updateHistoryBanner();
        console.log('No Conversation history to load or empty history');
        if (activeHistoryRequest && activeHistoryRequest.id === requestId) {
            activeHistoryRequest = null;
        }
        return false;
    } catch (error) {
        if (
            error?.name === 'AbortError'
            || !isChatOrganisationRequestCurrent(organisationGenerationAtStart)
        ) {
            return false;
        }
        const targetSessionId = normaliseHistorySessionId(requestedSessionId || activeChatSessionId);
        const fallbackMessage = 'Conversation history request failed; please retry.';
        _markConversationSituationUnavailable(targetSessionId, fallbackMessage);
        setHistoryLoadState({
            sessionId: targetSessionId,
            message: fallbackMessage,
            retryable: true,
            detail: error instanceof Error ? error.message : String(error || '')
        });
        if (!shouldPreserveRenderedHistoryForSession(scrollableField, targetSessionId)) {
            scrollableField.innerHTML = `<div class="chat-session-loading">${escapeHtml(fallbackMessage)}</div>`;
            displayedHistorySessionId = null;
        }
        console.error('Error loading Conversation history:', error);
        updateHistoryBanner();
        if (activeHistoryRequest && activeHistoryRequest.id === requestId) {
            activeHistoryRequest = null;
        }
        return false;
    }
}

function forceScrollToBottomWithRetries(scrollableField, options = {}) {
    const { attempts = 6 } = options;
    const maxAttempts = Number.isInteger(attempts) && attempts > 0 ? attempts : 1;

    const requestFrame = (typeof window !== 'undefined' && typeof window.requestAnimationFrame === 'function')
        ? window.requestAnimationFrame.bind(window)
        : (cb) => setTimeout(cb, 0);

    let remaining = maxAttempts;
    const tick = () => {
        if (!scrollableField || remaining <= 0) {
            return;
        }

        scrollConversationToEnd(scrollableField, { smooth: false });
        remaining -= 1;
        requestFrame(tick);
    };

    // A few frames is usually enough to catch delayed markdown/layout changes.
    requestFrame(tick);
}

async function loadRecentChatPair(options = {}) {
    return loadChatHistory({
        ...options,
        segments: 1,
        segmentSizeOverride: HISTORY_TAIL_SEGMENT_SIZE,
        tailLimit: HISTORY_TAIL_SEGMENT_SIZE,
        filterRecentPair: true
    });
}

function selectRecentChatPair(historyMessages) {
    if (!Array.isArray(historyMessages) || historyMessages.length === 0) {
        return [];
    }

    const eligible = historyMessages.filter(
        (msg) => msg && (msg.role === 'user' || msg.role === 'assistant')
    );
    if (eligible.length === 0) {
        return [];
    }

    let lastAssistantIndex = -1;
    for (let i = eligible.length - 1; i >= 0; i -= 1) {
        if (eligible[i].role === 'assistant') {
            lastAssistantIndex = i;
            break;
        }
    }

    if (lastAssistantIndex === -1) {
        return eligible.slice(-1);
    }

    let lastUserIndex = -1;
    for (let i = lastAssistantIndex - 1; i >= 0; i -= 1) {
        if (eligible[i].role === 'user') {
            lastUserIndex = i;
            break;
        }
    }

    if (lastUserIndex === -1) {
        return eligible.slice(lastAssistantIndex);
    }

    return eligible.slice(lastUserIndex);
}

function normaliseChatTurnId(value) {
    return (typeof value === 'string' && value.trim()) ? value.trim() : null;
}

function buildChatRequestTurnId(role, requestId) {
    const normalisedRequestId = normaliseChatTurnId(requestId);
    if (!normalisedRequestId) {
        return null;
    }
    return `${role === 'assistant' ? 'a' : 'u'}-${normalisedRequestId}`;
}

function restoreLiveUserTurnAfterHistoryHydration(historyMessages) {
    const request = getLiveChatRequestForSession(activeChatSessionId);
    if (
        !request
        || !isRequestInActiveChatSession(request)
        || request.userTurnShouldRender !== true
    ) {
        return false;
    }

    const userTurnId = normaliseChatTurnId(request.userTurnId)
        || buildChatRequestTurnId('user', request.clientRequestId);
    const promptText = (typeof request.promptText === 'string' && request.promptText)
        ? request.promptText
        : (typeof request.promptRaw === 'string' ? request.promptRaw.trim() : '');
    if (!userTurnId || !promptText) {
        return false;
    }

    const canonicalTurnPresent = historyMessages.some((message) => (
        normaliseChatTurnId(message?.turn_id) === userTurnId
    ));
    if (canonicalTurnPresent) {
        return false;
    }

    appendMessage(
        'User',
        promptText,
        userTurnId,
        false,
        false,
        request.userTurnTimestamp || null
    );
    return true;
}

function rehydrateHistory(scrollableField, historyMessages, options = {}) {
    const {
        scrollToBottom = true,
        preserveScroll = false,
        showResetNotice = false,
        forceScrollToBottom = false
    } = options;

    const previousScrollHeight = getConversationPageScrollHeight();
    const previousScrollTop = getConversationPageScrollTop();

    scrollableField.innerHTML = '';
    transcriptTurns.length = 0;
    clearLlmDebugDataEntries();

    historyMessages.forEach((msg, index) => {
        if (msg.role === 'user' || msg.role === 'assistant') {
            const persistedTurnId = typeof msg.turn_id === 'string' ? msg.turn_id.trim() : '';
            const turnId = persistedTurnId || `history-${msg.role}-${index}`;
            let label = msg.role === 'user' ? 'User' : 'Von';
            const externalActor = (
                msg.external_actor && typeof msg.external_actor === 'object'
            ) ? msg.external_actor : null;
            if (externalActor) {
                const externalDisplayName = String(externalActor.display_name || '').trim();
                label = externalDisplayName || (
                    msg.role === 'assistant' ? 'Imported agent' : 'Source user'
                );
            } else if (msg.role === 'user') {
                const authorId = _normalisePotentialConceptId(msg.author_user_id);
                if (authorId) {
                    label = _deriveNameFromConceptId(authorId) || label;
                    if (activeChatSessionOwnerId && authorId === activeChatSessionOwnerId) {
                        label = `👑 ${label}`;
                    }
                }
            }

            // Restore debug data before rendering so markdown gating can see model info.
            const hasDebugData = msg.role === 'assistant'
                && (!!msg.llm_debug_data || !!msg.history_location);
            if (msg.role === 'assistant') {
                const merged = {
                    ...(msg.llm_debug_data && typeof msg.llm_debug_data === 'object' ? msg.llm_debug_data : {}),
                    history_location: msg.history_location || null,
                    reference_manifest: msg.reference_manifest
                        || msg.llm_debug_data?.reference_manifest
                        || null,
                    receipts: msg.receipts || msg.representation_receipts || null,
                    representation: msg.representation || null,
                    timestamp: (
                        msg.llm_debug_data
                        && typeof msg.llm_debug_data === 'object'
                        && msg.llm_debug_data.timestamp !== undefined
                        && msg.llm_debug_data.timestamp !== null
                    )
                        ? msg.llm_debug_data.timestamp
                        : (msg.timestamp || null)
                };
                setLlmDebugDataEntry(turnId, merged);
            }

            const historyMessageOptions = {
                ...(externalActor ? {
                    assistantMessage: msg.role === 'assistant',
                    externalActor,
                    readOnly: true
                } : {}),
                conceptQaReceipt: {
                    receipts: msg.receipts || msg.representation_receipts || null,
                    representation: msg.representation || null,
                    reference_manifest: msg.reference_manifest
                        || msg.llm_debug_data?.reference_manifest
                        || null,
                },
            };
            appendMessage(
                label,
                msg.content,
                turnId,
                hasDebugData,
                true,
                msg.timestamp,
                null,
                null,
                historyMessageOptions
            );
            if (msg.role === 'assistant') {
                const debugData = llmDebugData.get(turnId);
                if (!renderRetainedThinkingCardForDebugData(turnId, debugData)) {
                    renderLoadableRetainedThinkingPlaceholder(turnId, debugData);
                }
            }
        }
    });

    // Conversation observations are a separate append-only carrier. Rebuild
    // their user-visible late-result cards after transcript rehydration, which
    // clears the scrollable field after accepting the carrier snapshot.
    _renderLateWorkflowOutcomesForActiveSession();

    // A history request may have started before the active prompt was sent and
    // finish afterwards. Keep the optimistic user turn as an explicit
    // session-bound overlay until canonical history contains its stable ID.
    // The active Thinking card is restored in the animation-frame callback
    // below, so this preserves the visible user -> Thinking ordering.
    restoreLiveUserTurnAfterHistoryHydration(historyMessages);

    // JVNAUTOSCI-2128: rehydrate the per-conversation ArrowUp recall buffer
    // from history so the most recent user prompt is recallable after a
    // page reload / Von restart, not only within the current page session.
    rehydrateLastSubmittedUserPromptFromHistory(historyMessages);

    if (showResetNotice) {
        appendResetNotice(scrollableField);
    }

    const requestFrame = (typeof window !== 'undefined' && typeof window.requestAnimationFrame === 'function')
        ? window.requestAnimationFrame.bind(window)
        : (cb) => setTimeout(cb, 0);

    requestFrame(() => {
        if (preserveScroll) {
            const newScrollHeight = getConversationPageScrollHeight();
            const delta = newScrollHeight - previousScrollHeight;
            scrollConversationPageTo(previousScrollTop + Math.max(delta, 0));
        } else if (scrollToBottom) {
            scrollConversationToEnd(scrollableField, { smooth: false });

            if (forceScrollToBottom) {
                forceScrollToBottomWithRetries(scrollableField);
            }
        }
        // Update history display to reflect new context count
        updateHistoryLength();
        updateScrollToEndButtonVisibility(scrollableField);
        syncActiveChatSessionThinkingState();
    });
}

function initializeHistoryControls() {
    const loadButton = document.getElementById('loadOlderHistoryBtn');
    if (!loadButton) {
        return;
    }

    loadButton.addEventListener('click', async () => {
        if (totalHistorySegments === 0 || historySegmentsShown >= totalHistorySegments) {
            return;
        }

        loadButton.disabled = true;
        loadButton.classList.add('loading');

        try {
            const targetSegments = totalHistorySegments > 0
                ? Math.min(historySegmentsShown + 1, totalHistorySegments)
                : historySegmentsShown + 1;
            await loadChatHistory({
                segments: targetSegments,
                scrollToBottom: false,
                preserveScroll: true
            });
        } catch (error) {
            console.error('Error loading older history:', error);
        } finally {
            loadButton.classList.remove('loading');
            updateHistoryBanner();
        }
    });
}

function getInvitePopupElements() {
    return {
        popup: document.getElementById('inviteConversationPopup'),
        closeButton: document.getElementById('closeInviteConversation'),
        inviteButton: document.getElementById('inviteConversationBtn'),
        list: document.getElementById('inviteList'),
        status: document.getElementById('inviteStatus'),
        searchInput: document.getElementById('inviteSearchInput'),
        programmeFilter: document.getElementById('inviteProgrammeFilter'),
        projectFilter: document.getElementById('inviteProjectFilter'),
        filtersNote: document.getElementById('inviteFiltersNote')
    };
}

function setInviteStatus(message) {
    const { status } = getInvitePopupElements();
    if (!status) return;
    status.textContent = message || '';
}

function setInvitePopupVisible(visible) {
    const { popup } = getInvitePopupElements();
    if (!popup) return;
    if (visible) {
        popup.classList.remove('hidden');
        popup.setAttribute('aria-hidden', 'false');
    } else {
        popup.classList.add('hidden');
        popup.setAttribute('aria-hidden', 'true');
    }
}

async function _fetchSessionContext() {
    try {
        const resp = await fetch('/von/api/session/context', {
            cache: 'no-cache',
            headers: buildChatFetchHeaders()
        });
        if (!resp.ok) return null;
        return await resp.json();
    } catch (e) {
        console.warn('[invite] Failed to fetch session context', e);
        return null;
    }
}

async function _ensureInviteSessionContext() {
    const ctx = getUserContext();
    if (!ctx?.user_id) {
        return;
    }

    const sessionCtx = await _fetchSessionContext();

    if (!sessionCtx || sessionCtx.user_id !== ctx.user_id) {
        try {
            await postJson('/von/api/session/set_user_concept', { user_concept_id: ctx.user_id });
        } catch (e) {
            console.warn('[invite] Failed to sync session user concept', e);
        }
    }

    if (ctx.org_id && (!sessionCtx || sessionCtx.organisation_id !== ctx.org_id)) {
        try {
            await synchroniseOrganisationContext(() => getUserContext()?.org_id || null);
        } catch (e) {
            console.warn('[invite] Failed to sync session organisation', e);
        }
    }
}

async function populateInviteFilters(sessionLinks) {
    const { programmeFilter, projectFilter } = getInvitePopupElements();
    if (!programmeFilter || !projectFilter) return;

    const links = _normaliseChatSessionLinks(sessionLinks || {});

    const buildOptions = async (selectEl, ids, placeholder) => {
        selectEl.innerHTML = '';
        const defaultOption = document.createElement('option');
        defaultOption.value = '';
        defaultOption.textContent = placeholder;
        selectEl.appendChild(defaultOption);

        for (const id of ids) {
            const meta = await _getConceptMetaForChatSession(id);
            const option = document.createElement('option');
            option.value = id;
            option.textContent = meta?.displayName || _deriveNameFromConceptId(id) || id;
            selectEl.appendChild(option);
        }
    };

    await buildOptions(programmeFilter, links.programmes || [], 'All programmes');
    await buildOptions(projectFilter, links.projects || [], 'All projects');
}

function getInviteFilterValues() {
    const { programmeFilter, projectFilter, searchInput } = getInvitePopupElements();
    return {
        programmeId: programmeFilter?.value || '',
        projectId: projectFilter?.value || '',
        search: (searchInput?.value || '').trim().toLowerCase()
    };
}

function filterInvitees(invitees) {
    const { programmeId, projectId, search } = getInviteFilterValues();
    return invitees.filter((invitee) => {
        const name = String(invitee?.name || '').toLowerCase();
        if (search && !name.includes(search)) {
            return false;
        }
        const match = invitee?.match || {};
        if (programmeId && !(match.programmes || []).includes(programmeId)) {
            return false;
        }
        if (projectId && !(match.projects || []).includes(projectId)) {
            return false;
        }
        return true;
    });
}

async function sendSharedConversationInvite(invitee) {
    if (!activeChatSessionId || !invitee?.concept_id) {
        return;
    }
    await _ensureInviteSessionContext();
    setInviteStatus('Sending invite…');
    try {
        const response = await fetch('/von/api/shared_conversations/invite', {
            method: 'POST',
            headers: buildChatFetchHeaders({ 'Content-Type': 'application/json' }),
            body: JSON.stringify({
                session_id: activeChatSessionId,
                invitee_concept_id: invitee.concept_id
            })
        });
        const data = await response.json();
        if (!response.ok) {
            setInviteStatus(data?.error || 'Invite failed.');
            return;
        }
        invitee.invite_status = data?.invite?.status || 'pending';
        setInviteStatus('Invite sent.');
        renderInviteesList();
    } catch (e) {
        console.error('Invite error', e);
        setInviteStatus('Invite failed.');
    }
}

function renderInviteesList() {
    const { list, filtersNote } = getInvitePopupElements();
    if (!list) return;

    list.innerHTML = '';
    const filtered = filterInvitees(invitePopupState.invitees || []);

    if (!filtered.length) {
        const empty = document.createElement('div');
        empty.className = 'invite-row';
        empty.textContent = 'No matching people.';
        list.appendChild(empty);
        return;
    }

    for (const invitee of filtered) {
        const row = document.createElement('div');
        row.className = 'invite-row';
        row.setAttribute('role', 'listitem');

        const info = document.createElement('div');
        const name = document.createElement('div');
        name.className = 'invite-row-name';
        name.textContent = invitee.name || 'Unknown';
        const meta = document.createElement('div');
        meta.className = 'invite-row-meta';
        meta.textContent = invitee.role ? `Role: ${invitee.role}` : '';
        info.appendChild(name);
        info.appendChild(meta);

        const actions = document.createElement('div');
        actions.className = 'invite-row-actions';

        const status = invitee.invite_status;
        if (status) {
            const pill = document.createElement('span');
            pill.className = 'invite-pill';
            pill.textContent = status;
            actions.appendChild(pill);
        }

        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'btn-mini';
        button.textContent = status === 'accepted' ? 'Shared' : 'Invite';
        button.disabled = status === 'pending' || status === 'accepted';
        button.addEventListener('click', () => sendSharedConversationInvite(invitee));
        actions.appendChild(button);

        row.appendChild(info);
        row.appendChild(actions);
        list.appendChild(row);
    }

    if (filtersNote) {
        if ((invitePopupState.totalCount || 0) > INVITE_LIST_FILTER_THRESHOLD) {
            filtersNote.textContent = 'Sorted by conversation programmes/projects. Use filters to narrow the list.';
        } else {
            filtersNote.textContent = invitePopupState.orderedBy === 'conversation_links'
                ? 'Sorted by conversation links.'
                : '';
        }
    }
}

async function loadInviteesForSession(sessionId) {
    if (!sessionId) return;
    setInviteStatus('Loading invitees…');

    await _ensureInviteSessionContext();

    try {
        const resp = await fetch(`/von/api/shared_conversations/invitees?session_id=${encodeURIComponent(sessionId)}`, {
            headers: buildChatFetchHeaders()
        });
        if (!resp.ok) {
            const data = await resp.json();
            setInviteStatus(data?.error || 'Unable to load invitees.');
            invitePopupState = { invitees: [], sessionLinks: null, orderedBy: null, totalCount: 0 };
            renderInviteesList();
            return;
        }
        const data = await resp.json();
        invitePopupState = {
            invitees: data?.invitees || [],
            sessionLinks: data?.session_links || {},
            orderedBy: data?.ordered_by || null,
            totalCount: data?.total_count || 0
        };
        await populateInviteFilters(invitePopupState.sessionLinks);
        const { programmeFilter, projectFilter } = getInvitePopupElements();
        if (
            invitePopupState.totalCount > INVITE_LIST_FILTER_THRESHOLD
            && programmeFilter
            && projectFilter
            && !programmeFilter.value
            && !projectFilter.value
        ) {
            const links = _normaliseChatSessionLinks(invitePopupState.sessionLinks || {});
            if (links.programmes?.length) {
                programmeFilter.value = links.programmes[0];
            } else if (links.projects?.length) {
                projectFilter.value = links.projects[0];
            }
        }
        setInviteStatus('');
        renderInviteesList();
    } catch (e) {
        console.error('Invite load error', e);
        setInviteStatus('Unable to load invitees.');
    }
}

async function openInvitePopup() {
    if (!activeChatSessionId) {
        showToast('Select a conversation before inviting.');
        return;
    }
    setInvitePopupVisible(true);
    await loadInviteesForSession(activeChatSessionId);
}

function closeInvitePopup() {
    setInvitePopupVisible(false);
    setInviteStatus('');
}

function getIncomingInviteElements() {
    return {
        popup: document.getElementById('incomingInvitesPopup'),
        openButton: document.getElementById('incomingInvitesBtn'),
        closeButton: document.getElementById('closeIncomingInvites'),
        badge: document.getElementById('incomingInvitesBadge'),
        list: document.getElementById('incomingInvitesList'),
        status: document.getElementById('incomingInvitesStatus')
    };
}

function setIncomingInviteStatus(message) {
    const { status } = getIncomingInviteElements();
    if (!status) return;
    status.textContent = message || '';
}

function setIncomingInvitePopupVisible(visible) {
    const { popup } = getIncomingInviteElements();
    if (!popup) return;
    if (visible) {
        popup.classList.remove('hidden');
        popup.setAttribute('aria-hidden', 'false');
    } else {
        popup.classList.add('hidden');
        popup.setAttribute('aria-hidden', 'true');
    }
}

function setIncomingInviteBadge(count) {
    const { badge, openButton } = getIncomingInviteElements();
    if (!badge) return;
    const numeric = Number.isFinite(Number(count)) ? Number(count) : 0;
    if (numeric > 0) {
        badge.textContent = numeric > 99 ? '99+' : String(numeric);
        badge.classList.remove('hidden');
    } else {
        badge.textContent = '';
        badge.classList.add('hidden');
    }
    if (openButton) {
        const label = numeric > 0
            ? `View ${numeric} conversation invite${numeric === 1 ? '' : 's'}`
            : 'View conversation invites';
        openButton.setAttribute('aria-label', label);
        openButton.setAttribute('title', label);
    }
}

function _formatInviteSessionLabel(sessionId) {
    const raw = String(sessionId || '').trim();
    if (!raw) return 'Session: unknown';
    if (raw.length > 16) {
        return `Session: ${raw.slice(0, 8)}…`;
    }
    return `Session: ${raw}`;
}

function _getChatSessionTabElement(sessionId) {
    if (!sessionId) return null;
    const escaped = String(sessionId).replace(/"/g, '\\"');
    return document.querySelector(`.chat-session-tab[data-session-id="${escaped}"]`);
}

function _scrollToChatSession(sessionId) {
    if (!sessionId) return;
    const tab = _getChatSessionTabElement(sessionId);
    if (!tab) {
        scheduleChatSessionTabsRefresh(true);
        setTimeout(() => _scrollToChatSession(sessionId), 600);
        return;
    }
    try {
        tab.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
        tab.classList.add('is-shared-highlight');
        setTimeout(() => tab.classList.remove('is-shared-highlight'), 2000);
    } catch (_) {
        // Ignore scroll errors.
    }
}

async function _resolveInviterName(invite) {
    const inviterId = _normalisePotentialConceptId(invite?.inviter_user_id || invite?.inviter_user_concept_id);
    if (!inviterId) return '';
    const meta = await _getConceptMetaForChatSession(inviterId);
    return meta?.displayName || _deriveNameFromConceptId(inviterId) || inviterId;
}

async function renderIncomingInvitesList() {
    const { list } = getIncomingInviteElements();
    if (!list) return;

    list.innerHTML = '';
    const invites = Array.isArray(incomingInviteState.invites) ? incomingInviteState.invites : [];
    const acceptedInvites = Array.isArray(incomingInviteState.acceptedInvites)
        ? incomingInviteState.acceptedInvites
        : [];

    if (!invites.length && !acceptedInvites.length) {
        const empty = document.createElement('div');
        empty.className = 'invite-row';
        empty.textContent = 'No pending invites.';
        list.appendChild(empty);
        return;
    }

    if (invites.length) {
        const header = document.createElement('div');
        header.className = 'invite-section-title';
        header.textContent = 'Pending invites';
        list.appendChild(header);
    }

    for (const invite of invites) {
        const row = document.createElement('div');
        row.className = 'invite-row';
        row.setAttribute('role', 'listitem');

        const info = document.createElement('div');
        const name = document.createElement('div');
        name.className = 'invite-row-name';
        const inviterName = await _resolveInviterName(invite);
        name.textContent = inviterName ? `Invite from ${inviterName}` : 'Conversation invite';
        const meta = document.createElement('div');
        meta.className = 'invite-row-meta';
        const sessionLabel = _formatInviteSessionLabel(invite?.session_id);
        meta.textContent = sessionLabel;
        info.appendChild(name);
        info.appendChild(meta);

        const actions = document.createElement('div');
        actions.className = 'invite-row-actions';

        const status = String(invite?.status || 'pending');
        if (status) {
            const pill = document.createElement('span');
            pill.className = 'invite-pill';
            pill.textContent = status;
            actions.appendChild(pill);
        }

        if (status === 'pending') {
            const acceptButton = document.createElement('button');
            acceptButton.type = 'button';
            acceptButton.className = 'btn-mini';
            acceptButton.textContent = 'Accept';
            acceptButton.addEventListener('click', () => respondToSharedConversationInvite(invite, 'accept'));

            const declineButton = document.createElement('button');
            declineButton.type = 'button';
            declineButton.className = 'btn-mini';
            declineButton.textContent = 'Decline';
            declineButton.addEventListener('click', () => respondToSharedConversationInvite(invite, 'decline'));

            actions.appendChild(acceptButton);
            actions.appendChild(declineButton);
        }

        row.appendChild(info);
        row.appendChild(actions);
        list.appendChild(row);
    }

    if (acceptedInvites.length) {
        const header = document.createElement('div');
        header.className = 'invite-section-title';
        header.textContent = 'Accepted invites';
        list.appendChild(header);
    }

    for (const invite of acceptedInvites) {
        const row = document.createElement('div');
        row.className = 'invite-row';
        row.setAttribute('role', 'listitem');

        const info = document.createElement('div');
        const name = document.createElement('div');
        name.className = 'invite-row-name';
        const inviterName = await _resolveInviterName(invite);
        name.textContent = inviterName ? `Shared by ${inviterName}` : 'Shared conversation';
        const meta = document.createElement('div');
        meta.className = 'invite-row-meta';
        const sessionLabel = _formatInviteSessionLabel(invite?.session_id);
        meta.textContent = sessionLabel;
        info.appendChild(name);
        info.appendChild(meta);

        const actions = document.createElement('div');
        actions.className = 'invite-row-actions';

        const pill = document.createElement('span');
        pill.className = 'invite-pill';
        pill.textContent = 'accepted';
        actions.appendChild(pill);

        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'btn-mini';
        button.textContent = 'Show conversation';
        button.addEventListener('click', async () => {
            const sessionId = invite?.session_id;
            if (!sessionId) {
                showToast('Unable to open conversation: missing session id.');
                return;
            }
            closeIncomingInvitesPopup();
            const result = await switchToChatSession(sessionId);
            if (!result?.ok) {
                showToast(result?.error || 'Unable to open conversation.');
                return;
            }
            _scrollToChatSession(sessionId);
        });
        actions.appendChild(button);

        row.appendChild(info);
        row.appendChild(actions);
        list.appendChild(row);
    }
}

async function loadIncomingInvites({ silent = false } = {}) {
    if (pendingChatOrganisationSwitchId !== null) {
        return;
    }
    const organisationGenerationAtStart = chatOrganisationGeneration;
    if (incomingInviteLoadInFlight) {
        if (silent) return;
        try { incomingInviteAbortController?.abort(); } catch (_) { }
    }

    if (!silent) {
        setIncomingInviteStatus('Loading invites…');
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 8000);
    incomingInviteAbortController = controller;
    incomingInviteLoadInFlight = true;

    try {
        const [pendingResp, acceptedResp] = await Promise.all([
            fetch('/von/api/shared_conversations/invites?status=pending', {
                cache: 'no-store',
                headers: buildChatFetchHeaders(),
                signal: controller.signal
            }),
            fetch('/von/api/shared_conversations/invites?status=accepted', {
                cache: 'no-store',
                headers: buildChatFetchHeaders(),
                signal: controller.signal
            })
        ]);

        const pendingData = await pendingResp.json();
        const acceptedData = await acceptedResp.json();
        if (!isChatOrganisationRequestCurrent(organisationGenerationAtStart)) {
            return;
        }
        if (!pendingResp.ok || !acceptedResp.ok) {
            if (!silent) {
                setIncomingInviteStatus(pendingData?.error || acceptedData?.error || 'Unable to load invites.');
            }
            incomingInviteState = { invites: [], acceptedInvites: [], totalCount: 0 };
            setIncomingInviteBadge(0);
            await renderIncomingInvitesList();
            return;
        }

        const invites = Array.isArray(pendingData?.invites) ? pendingData.invites : [];
        const acceptedInvites = Array.isArray(acceptedData?.invites) ? acceptedData.invites : [];
        incomingInviteState = {
            invites,
            acceptedInvites,
            totalCount: typeof pendingData?.total_count === 'number' ? pendingData.total_count : invites.length
        };
        setIncomingInviteBadge(incomingInviteState.totalCount);
        if (!silent) {
            setIncomingInviteStatus('');
        }
        await renderIncomingInvitesList();
    } catch (e) {
        if (!isChatOrganisationRequestCurrent(organisationGenerationAtStart)) {
            return;
        }
        if (e && e.name === 'AbortError') {
            if (!silent) {
                setIncomingInviteStatus('Invite loading timed out.');
            }
            return;
        }
        console.error('Invite list error', e);
        if (!silent) {
            setIncomingInviteStatus('Unable to load invites.');
        }
    } finally {
        clearTimeout(timeoutId);
        if (incomingInviteAbortController === controller) {
            incomingInviteAbortController = null;
            incomingInviteLoadInFlight = false;
        }
    }
}

async function respondToSharedConversationInvite(invite, action) {
    const inviteId = invite?.invite_id;
    if (!inviteId) return;

    const actionLabel = action === 'accept' ? 'Accepting invite…' : 'Declining invite…';
    setIncomingInviteStatus(actionLabel);
    try {
        const response = await fetch('/von/api/shared_conversations/invites/respond', {
            method: 'POST',
            headers: buildChatFetchHeaders({ 'Content-Type': 'application/json' }),
            body: JSON.stringify({ invite_id: inviteId, action })
        });
        const data = await response.json();
        if (!response.ok) {
            setIncomingInviteStatus(data?.error || 'Invite update failed.');
            return;
        }

        invite.status = data?.invite?.status || invite.status;
        setIncomingInviteStatus('');
        if (action === 'accept') {
            showToast('Invite accepted. The conversation will appear in your list.');
            scheduleChatSessionTabsRefresh(true);
        } else {
            showToast('Invite declined.');
        }
        await loadIncomingInvites({ silent: true });
    } catch (e) {
        console.error('Invite response error', e);
        setIncomingInviteStatus('Invite update failed.');
    }
}

function openIncomingInvitesPopup() {
    setIncomingInvitePopupVisible(true);
    void loadIncomingInvites();
}

function closeIncomingInvitesPopup() {
    setIncomingInvitePopupVisible(false);
    setIncomingInviteStatus('');
}

// JVNAUTOSCI-1002: SSE streaming for shared conversation turn updates
/**
 * Check if the current session is a shared conversation (either owner with accepted invites
 * or invitee with an accepted invite).
 */
function isSharedConversationSession(sessionId) {
    if (!sessionId) return false;

    // Check if we have any accepted invites for this session (as invitee)
    const acceptedInvites = Array.isArray(incomingInviteState?.acceptedInvites)
        ? incomingInviteState.acceptedInvites
        : [];
    const isInvitee = acceptedInvites.some(
        invite => invite?.session_id === sessionId
    );
    if (isInvitee) return true;

    // Check if this session has shared_owner_user_id set (indicates shared as invitee)
    // or has_shared_participants set (indicates shared as owner)
    const cachedSession = sessionTabsCache.find(
        s => String(s?.session_id || '') === sessionId
    );
    if (cachedSession?.shared_owner_user_id) return true;
    if (cachedSession?.has_shared_participants) return true;

    return false;
}

/**
 * Get the per-session dedupe set for shared turn IDs.
 */
function getSeenSharedTurnIds(sessionId) {
    const sid = String(sessionId || '').trim();
    if (!sid) return new Set();
    let seen = seenSharedTurnIds.get(sid);
    if (!seen) {
        seen = new Set();
        seenSharedTurnIds.set(sid, seen);
    }
    return seen;
}

function getChatSessionTabElement(sessionId) {
    const container = getChatSessionTabsContainer();
    if (!container) return null;
    const sid = String(sessionId || '').trim();
    if (!sid) return null;
    const escaped = (typeof CSS !== 'undefined' && CSS.escape) ? CSS.escape(sid) : sid.replace(/"/g, '\\"');
    return container.querySelector(`.chat-session-tab[data-session-id="${escaped}"]`);
}

function updateChatSessionTabTimestamp(sessionId, timestampValue) {
    const tab = getChatSessionTabElement(sessionId);
    if (!tab) return;
    const meta = tab.querySelector('.chat-session-tab-meta');
    if (!meta) return;
    const rawTimestamp = String(timestampValue || '').trim();
    const label = formatSessionTimestamp(rawTimestamp) || '-';
    meta.textContent = label;
    setUnambiguousTimestampTooltip(meta, rawTimestamp);
}

function formatChatSessionPreview(text) {
    if (typeof text !== 'string') return '';
    const normalised = text.replace(/\s+/g, ' ').trim();
    if (!normalised) return '';
    if (normalised.length <= 60) return normalised;
    return `${normalised.slice(0, 57)}…`;
}

function updateChatSessionTabPreview(sessionId, previewText) {
    const tab = getChatSessionTabElement(sessionId);
    if (!tab) return;
    const preview = formatChatSessionPreview(previewText);
    const existing = tab.querySelector('.chat-session-tab-preview');
    if (preview) {
        if (existing) {
            existing.textContent = preview;
            existing.title = preview;
        } else {
            const previewEl = document.createElement('span');
            previewEl.className = 'chat-session-tab-preview';
            previewEl.textContent = preview;
            previewEl.title = preview;
            tab.appendChild(previewEl);
        }
    } else if (existing) {
        existing.remove();
    }
}

function updateChatSessionTabUnreadBadge(sessionId, unreadCount) {
    const tab = getChatSessionTabElement(sessionId);
    if (!tab) return;
    const existing = tab.querySelector('.chat-session-tab-unread');
    const count = Number.isFinite(unreadCount) ? Number(unreadCount) : 0;
    if (count > 0) {
        if (existing) {
            existing.textContent = String(count);
        } else {
            const badge = document.createElement('span');
            badge.className = 'chat-session-tab-unread';
            badge.textContent = String(count);
            const header = tab.querySelector('.chat-session-tab-header');
            if (header) {
                header.appendChild(badge);
            } else {
                tab.appendChild(badge);
            }
        }
        tab.classList.add('has-unread');
    } else {
        if (existing) {
            existing.remove();
        }
        tab.classList.remove('has-unread');
    }
}

function updateSharedSessionCache(sessionId, payload) {
    const sid = String(sessionId || '').trim();
    if (!sid || !Array.isArray(sessionTabsCache)) return null;
    const sessionIndex = sessionTabsCache.findIndex(
        s => String(s?.session_id || '') === sid
    );
    if (sessionIndex < 0) return null;
    const session = sessionTabsCache[sessionIndex];
    const updatedSession = { ...session };
    const createdAt = payload?.created_at;
    const content = payload?.content;
    if (typeof createdAt === 'string' && createdAt.trim()) {
        updatedSession.last_message_at = createdAt;
    }
    if (typeof content === 'string' && content.trim()) {
        updatedSession.preview = content.trim();
    }
    const normalised = normaliseConversationSessionViewModel(updatedSession) || updatedSession;
    sessionTabsCache = [
        ...sessionTabsCache.slice(0, sessionIndex),
        normalised,
        ...sessionTabsCache.slice(sessionIndex + 1)
    ];
    if (typeof content === 'string' && content.trim()) {
        updateChatSessionTabPreview(sid, normalised.preview);
    }
    return normalised;
}

function markSharedSessionUnread(sessionId) {
    const sid = String(sessionId || '').trim();
    if (!sid) return;
    sharedConversationUnreadSessions.add(sid);
    const session = updateSharedSessionCache(sid, {});
    if (session) {
        const current = Number.isFinite(session.shared_unread_count)
            ? Number(session.shared_unread_count)
            : 0;
        session.shared_unread_count = current + 1;
        updateChatSessionTabUnreadBadge(sid, session.shared_unread_count);
        updateChatSessionTabTimestamp(sid, session.last_message_at);
    } else {
        scheduleChatSessionTabsRefresh(true);
    }
}

function clearSharedSessionUnread(sessionId) {
    const sid = String(sessionId || '').trim();
    if (!sid) return;
    sharedConversationUnreadSessions.delete(sid);
    const session = updateSharedSessionCache(sid, {});
    if (session) {
        session.shared_unread_count = 0;
        updateChatSessionTabUnreadBadge(sid, 0);
    }
}

function recordSharedHistoryIndex(sessionId, historyIndex) {
    if (!Number.isInteger(historyIndex)) return false;
    const sid = String(sessionId || '').trim();
    if (!sid) return false;
    const lastIndex = sharedConversationLastHistoryIndex.get(sid);
    const hasGap = Number.isInteger(lastIndex) && historyIndex > lastIndex + 1;
    if (!Number.isInteger(lastIndex) || historyIndex > lastIndex) {
        sharedConversationLastHistoryIndex.set(sid, historyIndex);
    }
    return hasGap;
}

function scheduleSharedHistoryResync(sessionId) {
    const sid = String(sessionId || '').trim();
    if (!sid || sharedConversationResyncInFlight.has(sid)) return;
    sharedConversationResyncInFlight.add(sid);

    if (activeChatSessionId === sid) {
        loadChatHistory({
            segments: 1,
            scrollToBottom: false,
            preserveScroll: true,
            showResetNotice: false
        }).finally(() => {
            sharedConversationResyncInFlight.delete(sid);
        });
        return;
    }

    scheduleChatSessionTabsRefresh(true);
    setTimeout(() => {
        sharedConversationResyncInFlight.delete(sid);
    }, 1500);
}

/**
 * Close any existing SSE connection for shared conversation streaming.
 */
function closeSharedConversationStream(sessionId = null) {
    if (sessionId) {
        const stream = sharedConversationStreams.get(sessionId);
        if (stream) {
            console.log('[chatTab] Closing shared conversation SSE stream', { sessionId });
            stream.close();
        }
        sharedConversationStreams.delete(sessionId);
        sharedConversationReconnectAttempts.delete(sessionId);
        publishRealtimeConnectionTelemetry('shared_stream_closed');
        return;
    }

    sharedConversationStreams.forEach((stream, sid) => {
        try {
            console.log('[chatTab] Closing shared conversation SSE stream', { sessionId: sid });
            stream.close();
        } catch (_) {
            // Ignore.
        }
    });
    sharedConversationStreams.clear();
    sharedConversationReconnectAttempts.clear();
    publishRealtimeConnectionTelemetry('shared_streams_closed_all');
}

function syncSharedConversationStreams() {
    // Keep a single shared-conversation stream per tab to avoid exhausting
    // browser/server connection slots under multi-tab usage.
    const desiredSessions = new Set();
    if (shouldMaintainSharedConversationStream(activeChatSessionId)) {
        desiredSessions.add(activeChatSessionId);
    }

    Array.from(sharedConversationStreams.keys()).forEach((sid) => {
        if (!desiredSessions.has(sid)) {
            closeSharedConversationStream(sid);
        }
    });

    desiredSessions.forEach((sid) => {
        void startSharedConversationStream(sid);
    });
    publishRealtimeConnectionTelemetry('shared_stream_sync');
}

/**
 * Start SSE stream for a shared conversation session.
 * Only connects if the session is a shared conversation.
 */
async function startSharedConversationStream(sessionId) {
    const sid = String(sessionId || '').trim();
    if (!sid) return;

    if (!shouldMaintainSharedConversationStream(sid)) {
        closeSharedConversationStream(sid);
        return;
    }

    if (sharedConversationStreams.has(sid)) {
        return;
    }

    await _ensureInviteSessionContext();

    console.log('[chatTab] Starting shared conversation SSE stream', { sessionId: sid });
    getSeenSharedTurnIds(sid).clear();

    const url = `/von/api/shared_conversations/stream?session_id=${encodeURIComponent(sid)}`;
    const eventSource = new EventSource(url);
    sharedConversationStreams.set(sid, eventSource);
    publishRealtimeConnectionTelemetry('shared_stream_started');

    eventSource.onopen = () => {
        console.log('[chatTab] SSE stream connected', { sessionId: sid });
        sharedConversationReconnectAttempts.set(sid, 0);
        publishRealtimeConnectionTelemetry('shared_stream_open');
    };

    eventSource.onerror = () => {
        if (sharedConversationStreams.get(sid) !== eventSource) {
            return;
        }
        console.warn('[chatTab] SSE stream error', { sessionId: sid, readyState: eventSource.readyState });

        if (eventSource.readyState === EventSource.CLOSED) {
            eventSource.close();
            sharedConversationStreams.delete(sid);
            publishRealtimeConnectionTelemetry('shared_stream_closed_remote');

            if (shouldMaintainSharedConversationStream(sid)) {
                const attempts = (sharedConversationReconnectAttempts.get(sid) || 0) + 1;
                sharedConversationReconnectAttempts.set(sid, attempts);
                const delay = Math.min(
                    SSE_RECONNECT_BASE_DELAY_MS * Math.pow(2, attempts - 1),
                    SSE_RECONNECT_MAX_DELAY_MS
                );
                console.log('[chatTab] SSE reconnecting in', delay, 'ms, attempt', attempts);
                setTimeout(() => {
                    if (shouldMaintainSharedConversationStream(sid) && !sharedConversationStreams.has(sid)) {
                        void startSharedConversationStream(sid);
                    }
                }, delay);
            } else {
                sharedConversationReconnectAttempts.delete(sid);
                publishRealtimeConnectionTelemetry('shared_stream_reconnect_skipped');
            }
        }
    };

    eventSource.addEventListener('user_turn', (event) => {
        handleSharedTurnEvent(sid, event, 'user');
    });

    eventSource.addEventListener('assistant_turn', (event) => {
        handleSharedTurnEvent(sid, event, 'assistant');
    });
}

/**
 * Handle an incoming turn event from the SSE stream.
 */
function handleSharedTurnEvent(expectedSessionId, event, speaker) {
    let data;
    try {
        data = JSON.parse(event.data);
    } catch (e) {
        console.warn('[chatTab] Failed to parse SSE event data', e);
        return;
    }

    const { turn_id, content, author_user_id, created_at, history_index } = data;
    const sessionId = (typeof data?.session_id === 'string' && data.session_id.trim())
        ? data.session_id.trim()
        : String(expectedSessionId || '').trim();
    if (!sessionId) return;

    const isActiveSession = activeChatSessionId === sessionId;

    // Dedupe by turn_id
    const seenIds = getSeenSharedTurnIds(sessionId);
    if (turn_id && seenIds.has(turn_id)) {
        console.log('[chatTab] Duplicate shared turn, skipping', { turn_id });
        return;
    }
    if (turn_id) {
        seenIds.add(turn_id);
    }

    console.log('[chatTab] Received shared turn', {
        session_id: sessionId,
        turn_id,
        speaker,
        content_length: content?.length,
        author_user_id
    });

    updateSharedSessionCache(sessionId, { content, created_at });
    updateChatSessionTabTimestamp(sessionId, created_at);

    if (recordSharedHistoryIndex(sessionId, history_index)) {
        scheduleSharedHistoryResync(sessionId);
    }

    if (!isActiveSession) {
        markSharedSessionUnread(sessionId);
        return;
    }

    clearSharedSessionUnread(sessionId);

    // Append the message to the transcript
    appendSharedTurnToTranscript({
        role: speaker,
        content: content || '',
        author_user_id,
        timestamp: created_at,
        history_index
    });
}

/**
 * Append a remotely-received turn to the chat transcript.
 */
function appendSharedTurnToTranscript(message) {
    const scrollableField = document.getElementById('scrollableField');
    if (!scrollableField) return;

    const { role, content, author_user_id } = message;

    // Create message element similar to existing rendering
    const messageDiv = document.createElement('div');
    messageDiv.className = `chat-message ${role === 'user' ? 'user-message' : 'assistant-message'} shared-remote-message`;

    // Add indicator that this is from another user
    const sourceIndicator = document.createElement('div');
    sourceIndicator.className = 'shared-message-source';
    if (role === 'user' && author_user_id) {
        // Extract user name from concept ID if possible
        const userName = author_user_id.startsWith('#V#')
            ? author_user_id.slice(3).replace(/_/g, ' ')
            : author_user_id;
        sourceIndicator.textContent = `From: ${userName}`;
    } else if (role === 'assistant') {
        sourceIndicator.textContent = 'Response (shared)';
    }

    const contentDiv = document.createElement('div');
    contentDiv.className = 'message-content';

    // Render markdown if available, otherwise plain text
    if (typeof window.renderMarkdown === 'function') {
        contentDiv.innerHTML = window.renderMarkdown(content || '');
    } else {
        contentDiv.textContent = content || '';
    }

    messageDiv.appendChild(sourceIndicator);
    messageDiv.appendChild(contentDiv);

    // Follow incoming content only when the reader was already near the page end.
    const wasAtBottom = isScrollableFieldNearBottom(scrollableField);

    scrollableField.appendChild(messageDiv);

    // Auto-scroll if user was at bottom
    if (wasAtBottom) {
        scrollConversationToEnd(scrollableField, { smooth: false });
        clearLatestUnreadBoundary();
        hideNewSharedMessagesIndicator();
    } else {
        setLatestUnreadBoundary(messageDiv);
        // Show "new messages" indicator
        showNewSharedMessagesIndicator();
    }

    updateScrollToEndButtonVisibility(scrollableField);
}

function ensureScrollToEndButton(scrollableField = null) {
    const targetField = scrollableField || document.getElementById('scrollableField');
    if (!(targetField instanceof HTMLElement)) {
        return null;
    }

    const controlHost = targetField.closest('.content-wrapper') || targetField.parentElement;
    if (!(controlHost instanceof HTMLElement)) {
        return null;
    }

    let button = document.getElementById(CHAT_SCROLL_TO_END_BUTTON_ID);
    if (button instanceof HTMLButtonElement && button.parentElement !== controlHost) {
        button.remove();
        button = null;
    }

    if (!(button instanceof HTMLButtonElement)) {
        button = document.createElement('button');
        button.type = 'button';
        button.id = CHAT_SCROLL_TO_END_BUTTON_ID;
        button.className = 'chat-scroll-to-end-btn';
        button.setAttribute('aria-label', 'Scroll to latest message');
        button.title = 'Scroll to latest message';
        button.innerHTML = '<span aria-hidden="true">↓</span><span class="sr-only">Scroll to latest message</span>';
        button.setAttribute('aria-hidden', 'true');
        button.tabIndex = -1;
        button.addEventListener('click', (event) => {
            if (event?.shiftKey && scrollConversationToSessionList({ smooth: true })) {
                event.preventDefault();
                return;
            }
            void scrollConversationToEnd(targetField, { smooth: true });
        });
        controlHost.appendChild(button);
    }

    return button;
}

function isScrollableFieldNearBottom(scrollableField, thresholdPx = CHAT_SCROLL_BOTTOM_THRESHOLD_PX) {
    if (!(scrollableField instanceof HTMLElement)) {
        return true;
    }
    const clientHeight = getConversationPageViewportHeight();
    const scrollHeight = getConversationPageScrollHeight();
    const scrollTop = getConversationPageScrollTop();
    const distanceToBottom = scrollHeight - (scrollTop + clientHeight);
    return distanceToBottom <= Math.max(0, Number(thresholdPx) || 0);
}

function getConversationPageScrollTop() {
    if (typeof window === 'undefined') return 0;
    return Number(window.scrollY ?? window.pageYOffset ?? document.documentElement?.scrollTop ?? 0) || 0;
}

function getConversationPageViewportHeight() {
    if (typeof window === 'undefined') return 0;
    return Number(window.innerHeight || document.documentElement?.clientHeight || 0) || 0;
}

function getConversationPageScrollHeight() {
    if (typeof document === 'undefined') return 0;
    return Math.max(
        Number(document.documentElement?.scrollHeight) || 0,
        Number(document.body?.scrollHeight) || 0
    );
}

function scrollConversationPageTo(top, options = {}) {
    if (typeof window === 'undefined') return false;
    const smooth = options?.smooth === true;
    const safeTop = Math.max(0, Number(top) || 0);
    try {
        window.scrollTo({ top: safeTop, behavior: smooth ? 'smooth' : 'auto' });
    } catch (_err) {
        window.scrollTo(0, safeTop);
    }
    return true;
}

function scrollConversationToEnd(scrollableField, options = {}) {
    if (!(scrollableField instanceof HTMLElement)) {
        return false;
    }

    const smooth = options?.smooth !== false;
    const top = getConversationPageScrollHeight();
    scrollConversationPageTo(top, { smooth });

    const schedule = (typeof window !== 'undefined' && typeof window.setTimeout === 'function')
        ? window.setTimeout.bind(window)
        : setTimeout;

    schedule(() => {
        if (isScrollableFieldNearBottom(scrollableField)) {
            clearLatestUnreadBoundary();
            hideNewSharedMessagesIndicator();
        }
        updateScrollToEndButtonVisibility(scrollableField);
    }, smooth ? 220 : 0);

    return true;
}

function updateScrollToEndButtonVisibility(scrollableField = null) {
    const targetField = scrollableField || document.getElementById('scrollableField');
    if (!(targetField instanceof HTMLElement)) {
        return;
    }

    const button = ensureScrollToEndButton(targetField);
    if (!(button instanceof HTMLButtonElement)) {
        return;
    }

    const hasOverflow = (getConversationPageScrollHeight() - getConversationPageViewportHeight()) > 1;
    const nearBottom = isScrollableFieldNearBottom(targetField);
    const shouldShow = hasOverflow && !nearBottom;

    button.classList.toggle('visible', shouldShow);
    button.setAttribute('aria-hidden', shouldShow ? 'false' : 'true');
    button.tabIndex = shouldShow ? 0 : -1;
}

function handleConversationScrollPositionChange(scrollableField) {
    if (!(scrollableField instanceof HTMLElement)) {
        return;
    }

    if (isScrollableFieldNearBottom(scrollableField)) {
        clearLatestUnreadBoundary();
        hideNewSharedMessagesIndicator();
    }

    updateScrollToEndButtonVisibility(scrollableField);
}

function resizePromptComposer(promptInput) {
    if (!(promptInput instanceof HTMLTextAreaElement)) return;
    promptInput.style.height = 'auto';
    const minHeight = 44;
    const maxHeight = 144;
    const nextHeight = Math.min(maxHeight, Math.max(minHeight, Number(promptInput.scrollHeight) || minHeight));
    promptInput.style.height = `${nextHeight}px`;
    promptInput.style.overflowY = (Number(promptInput.scrollHeight) || 0) > maxHeight ? 'auto' : 'hidden';
}

function setLatestUnreadBoundary(messageElement) {
    if (!(messageElement instanceof HTMLElement) || !messageElement.parentElement) {
        return null;
    }

    if (latestUnreadBoundaryElement?.isConnected) {
        latestUnreadBoundaryElement.remove();
    }

    const boundary = document.createElement('div');
    boundary.className = 'latest-unread-boundary';
    boundary.setAttribute('role', 'separator');
    boundary.setAttribute('aria-label', 'Latest unread boundary');
    boundary.setAttribute('tabindex', '-1');
    boundary.textContent = 'Latest unread';
    messageElement.parentElement.insertBefore(boundary, messageElement);
    latestUnreadBoundaryElement = boundary;
    return boundary;
}

function hasLatestUnreadBoundary() {
    return Boolean(latestUnreadBoundaryElement?.isConnected);
}

function clearLatestUnreadBoundary() {
    if (latestUnreadBoundaryElement?.isConnected) {
        latestUnreadBoundaryElement.remove();
    }
    latestUnreadBoundaryElement = null;
}

function jumpToLatestUnreadBoundary() {
    if (!hasLatestUnreadBoundary()) {
        return false;
    }

    const boundary = latestUnreadBoundaryElement;
    try {
        boundary.scrollIntoView({ behavior: 'smooth', block: 'start' });
    } catch (_e) {
        boundary.scrollIntoView();
    }
    try {
        boundary.focus({ preventScroll: true });
    } catch (_e) {
        boundary.focus();
    }
    return true;
}

/**
 * Show indicator that new messages arrived while scrolled up.
 */
function showNewSharedMessagesIndicator() {
    let indicator = document.getElementById('newSharedMessagesIndicator');
    if (!indicator) {
        indicator = document.createElement('button');
        indicator.type = 'button';
        indicator.id = 'newSharedMessagesIndicator';
        indicator.className = 'new-shared-messages-indicator';
        indicator.setAttribute('aria-label', 'Jump to latest unread message');
        indicator.textContent = 'Jump to latest unread';
        indicator.addEventListener('click', () => {
            void jumpToLatestUnreadBoundary();
        });

        const scrollableField = document.getElementById('scrollableField');
        if (scrollableField?.parentElement) {
            scrollableField.parentElement.insertBefore(indicator, scrollableField);
        }
    }

    const hasUnread = hasLatestUnreadBoundary();
    indicator.disabled = !hasUnread;
    indicator.style.display = hasUnread ? 'block' : 'none';
}

/**
 * Hide the new messages indicator (e.g., when user scrolls to bottom).
 */
function hideNewSharedMessagesIndicator() {
    const indicator = document.getElementById('newSharedMessagesIndicator');
    if (indicator) {
        indicator.disabled = true;
        indicator.style.display = 'none';
    }
}

function getWorkflowStatusElements() {
    return {
        panel: document.getElementById('workflowStatusPanel'),
        body: document.getElementById('workflowStatusBody'),
        refreshButton: document.getElementById('workflowStatusRefresh'),
        toggleAvailableButton: document.getElementById('workflowStatusToggleAvailable'),
        furlToggleButton: document.getElementById('workflowStatusFurlToggle'),
        showDesignsCheckbox: document.getElementById('workflowStatusShowDesigns'),
        copyJsonButton: document.getElementById('workflowStatusCopyJson')
    };
}

function getWorkflowEpisodesElements() {
    return {
        popup: document.getElementById('workflowEpisodesPopup'),
        title: document.getElementById('workflowEpisodesTitle'),
        status: document.getElementById('workflowEpisodesStatus'),
        list: document.getElementById('workflowEpisodesList'),
        closeButton: document.getElementById('closeWorkflowEpisodes'),
        copyJsonButton: document.getElementById('copyWorkflowEpisodesJson')
    };
}

function setWorkflowEpisodesPopupVisible(visible) {
    const { popup } = getWorkflowEpisodesElements();
    if (!popup) return;
    workflowEpisodesState.open = Boolean(visible);
    popup.classList.toggle('hidden', !workflowEpisodesState.open);
    popup.setAttribute('aria-hidden', workflowEpisodesState.open ? 'false' : 'true');
}

function formatWorkflowEpisodeTimestamp(value) {
    if (!value) return 'Unknown time';
    const explicitLabel = formatAbsoluteTimestamp(value);
    if (explicitLabel) {
        return explicitLabel;
    }
    return String(value);
}

function renderWorkflowEpisodesPopup() {
    const { title, status, list } = getWorkflowEpisodesElements();
    if (!title || !status || !list) return;

    const workflowLabel = workflowEpisodesState.workflowName || workflowEpisodesState.workflowId || 'Workflow';
    title.textContent = `${workflowLabel} episodes`;

    if (workflowEpisodesState.loading) {
        status.textContent = 'Loading episodes...';
        list.innerHTML = '';
        return;
    }

    if (workflowEpisodesState.error) {
        status.textContent = workflowEpisodesState.error;
        list.innerHTML = '';
        return;
    }

    if (!workflowEpisodesState.items.length) {
        status.textContent = 'No episodes found for this workflow.';
        list.innerHTML = '';
        return;
    }

    status.textContent = `${workflowEpisodesState.items.length} episodes`;
    list.innerHTML = workflowEpisodesState.items.map((item) => {
        const statusLabel = item?.completed ? 'completed' : (item?.status || 'terminated');
        const stageLabel = item?.terminal_stage || item?.final_state || 'unknown';
        const reason = item?.termination_reason || {};
        const reasonCode = reason?.code || (item?.completed ? 'completed' : 'terminated');
        const reasonDetail = reason?.detail || '';
        const timestampLabel = formatWorkflowEpisodeTimestamp(item?.attempt_started_at || item?.updated_at);
        const turnLabel = item?.turn_id || '—';
        const episodeId = item?.episode_id || '—';
        return `
            <div class="workflow-episode-item" role="listitem">
              <div class="workflow-episode-header">
                <span class="workflow-status-badge status-${escapeHtml(statusLabel)}">${escapeHtml(formatWorkflowStatusLabel(statusLabel))}</span>
                <span class="workflow-episode-time">${escapeHtml(timestampLabel)}</span>
              </div>
              <div class="workflow-episode-meta">Stage: ${escapeHtml(stageLabel)} · Reason: ${escapeHtml(reasonCode)}</div>
              ${reasonDetail ? `<div class="workflow-episode-detail">${escapeHtml(reasonDetail)}</div>` : ''}
              <div class="workflow-episode-meta">Turn: ${escapeHtml(turnLabel)} · Episode: ${escapeHtml(episodeId)}</div>
            </div>
        `;
    }).join('');
}

async function fetchWorkflowEpisodesSnapshot(workflowId, { limit = 60 } = {}) {
    const cleanWorkflowId = typeof workflowId === 'string' ? workflowId.trim() : '';
    const safeLimit = Math.max(1, Math.min(Number(limit) || 60, 200));
    const params = buildWorkflowStatusQuery({ includeStatusFilter: true });
    params.set('workflow_id', cleanWorkflowId);
    params.set('limit', String(safeLimit));
    const requestQuery = params.toString();

    try {
        const resp = await fetch(
            `/api/workflows/episodes?${requestQuery}`,
            { method: 'GET', headers: buildChatFetchHeaders() }
        );
        if (!resp.ok) {
            let errorPayload = null;
            try {
                errorPayload = await resp.json();
            } catch (_) {
                errorPayload = null;
            }

            const backendReason = String(
                errorPayload?.diagnostics?.backend_reason
                || errorPayload?.detail
                || `HTTP ${resp.status}`
            );
            const namespaceValue = String(
                errorPayload?.diagnostics?.namespace
                || errorPayload?.filters?.namespace
                || ''
            ).trim();

            return {
                ok: false,
                requestQuery,
                fetchedAt: Date.now(),
                payload: {
                    error: String(errorPayload?.error || 'workflow_episodes_fetch_failed'),
                    detail: backendReason,
                    request_query: requestQuery,
                    diagnostics: {
                        backend_reason: backendReason,
                        namespace: namespaceValue || null
                    },
                    backend_payload: errorPayload
                },
                items: [],
                total: 0,
                hasMore: false,
                error: namespaceValue
                    ? `Could not load workflow episodes (${namespaceValue}): ${backendReason}`
                    : `Could not load workflow episodes: ${backendReason}`
            };
        }
        const payload = await resp.json();
        const items = Array.isArray(payload?.items) ? payload.items : [];
        const totalRaw = Number(payload?.total);
        const total = Number.isFinite(totalRaw) ? Math.max(0, Math.trunc(totalRaw)) : items.length;
        return {
            ok: true,
            requestQuery,
            fetchedAt: Date.now(),
            payload,
            items,
            total,
            hasMore: Boolean(total > items.length),
            error: ''
        };
    } catch (err) {
        return {
            ok: false,
            requestQuery,
            fetchedAt: Date.now(),
            payload: {
                error: 'workflow_episodes_fetch_failed',
                detail: err instanceof Error ? err.message : String(err || 'unknown_error'),
                request_query: requestQuery
            },
            items: [],
            total: 0,
            hasMore: false,
            error: 'Could not load workflow episodes'
        };
    }
}

function _buildWorkflowEpisodesExportPayload() {
    const namespace = getSessionScopedNamespace();
    const orgContext = getSessionScopedOrgContext();
    const userId = getCurrentUserConceptId();
    const definitionItem = workflowDefinitionsState.items.find(
        (item) => String(item?.workflow_id || '').trim() === workflowEpisodesState.workflowId
    ) || null;

    return {
        schema_version: 1,
        exported_at: new Date().toISOString(),
        namespace_context: {
            namespace: namespace || null,
            user_id: userId || null,
            org_id: orgContext?.concept_id || orgContext?.id || null
        },
        workflow: {
            workflow_id: workflowEpisodesState.workflowId || null,
            workflow_name: workflowEpisodesState.workflowName || null,
            definition_summary: definitionItem
        },
        episodes_state: {
            loading: Boolean(workflowEpisodesState.loading),
            error: workflowEpisodesState.error || null,
            count: Array.isArray(workflowEpisodesState.items) ? workflowEpisodesState.items.length : 0,
            total: Number.isFinite(Number(workflowEpisodesState.lastPayload?.total))
                ? Math.max(0, Math.trunc(Number(workflowEpisodesState.lastPayload.total)))
                : (Array.isArray(workflowEpisodesState.items) ? workflowEpisodesState.items.length : 0),
            has_more: Boolean(workflowEpisodesState.lastPayload?.has_more),
            last_fetched_at: workflowEpisodesState.lastFetchedAt
                ? new Date(workflowEpisodesState.lastFetchedAt).toISOString()
                : null,
            request_query: workflowEpisodesState.lastRequestQuery || null
        },
        episodes_payload: workflowEpisodesState.lastPayload
    };
}

function _buildWorkflowDefinitionExportPayload({
    workflowId,
    workflowName,
    definitionSummary,
    episodesSnapshot
}) {
    const namespace = getSessionScopedNamespace();
    const orgContext = getSessionScopedOrgContext();
    const userId = getCurrentUserConceptId();
    const monitorPayload = buildWorkflowMonitorExportPayload();

    return {
        schema_version: 1,
        exported_at: new Date().toISOString(),
        namespace_context: {
            namespace: namespace || null,
            user_id: userId || null,
            org_id: orgContext?.concept_id || orgContext?.id || null
        },
        workflow: {
            workflow_id: workflowId || null,
            workflow_name: workflowName || null,
            definition_summary: definitionSummary || null
        },
        telemetry: {
            attempts: Number.isFinite(Number(definitionSummary?.attempts))
                ? Number(definitionSummary.attempts)
                : 0,
            completions: Number.isFinite(Number(definitionSummary?.completions))
                ? Number(definitionSummary.completions)
                : 0,
            failures: Number.isFinite(Number(definitionSummary?.failures))
                ? Number(definitionSummary.failures)
                : 0,
            in_progress: Number.isFinite(Number(definitionSummary?.in_progress))
                ? Number(definitionSummary.in_progress)
                : 0,
            completion_rate: Number.isFinite(Number(definitionSummary?.completion_rate))
                ? Number(definitionSummary.completion_rate)
                : null,
            terminal_success_rate: Number.isFinite(Number(definitionSummary?.terminal_success_rate))
                ? Number(definitionSummary.terminal_success_rate)
                : null,
            last_episode_at: definitionSummary?.last_episode_at || null,
            episodes_count: Number.isFinite(Number(definitionSummary?.episodes_count))
                ? Math.max(0, Math.trunc(Number(definitionSummary.episodes_count)))
                : null,
            is_executable: Boolean(definitionSummary?.is_executable),
            executability_reason: definitionSummary?.executability_reason || null,
            executability_detail: definitionSummary?.executability_detail || null
        },
        episodes_state: {
            loading: false,
            error: episodesSnapshot?.error || null,
            count: Array.isArray(episodesSnapshot?.items) ? episodesSnapshot.items.length : 0,
            total: Number.isFinite(Number(episodesSnapshot?.total))
                ? Math.max(0, Math.trunc(Number(episodesSnapshot.total)))
                : (Array.isArray(episodesSnapshot?.items) ? episodesSnapshot.items.length : 0),
            has_more: Boolean(episodesSnapshot?.hasMore),
            last_fetched_at: Number.isFinite(Number(episodesSnapshot?.fetchedAt))
                ? new Date(Number(episodesSnapshot.fetchedAt)).toISOString()
                : null,
            request_query: episodesSnapshot?.requestQuery || null
        },
        episodes_payload: episodesSnapshot?.payload || null,
        monitor_context: {
            mode: monitorPayload?.monitor_state?.mode || null,
            show_available: Boolean(monitorPayload?.monitor_state?.show_available),
            show_designs: Boolean(monitorPayload?.monitor_state?.show_designs),
            definitions_request_query: monitorPayload?.definitions_snapshot?.request_query || null,
            available_last_fetched_at: monitorPayload?.monitor_state?.available_last_fetched_at || null
        },
        diagnostics: monitorPayload?.diagnostics || null
    };
}

async function handleCopyWorkflowEpisodesJson() {
    const { copyJsonButton } = getWorkflowEpisodesElements();
    if (!copyJsonButton) return;
    const payload = buildWorkflowEpisodesLocatorPayload();
    const jsonString = JSON.stringify(payload, null, 2);

    const copied = await copyJsonTextWithButtonFeedback(copyJsonButton, jsonString);
    if (copied) {
        showToast('Workflow episodes locator JSON copied', 'success');
    } else {
        console.error('[workflowStatus] Failed to copy workflow episodes locator JSON');
        showToast('Failed to copy workflow episodes locator JSON', 'error');
    }
}

async function handleCopyWorkflowDefinitionJson(workflowId, workflowName) {
    const cleanWorkflowId = typeof workflowId === 'string' ? workflowId.trim() : '';
    if (!cleanWorkflowId) return;

    const copyButton = document.querySelector(
        `.workflow-status-copy-card-json-btn[data-workflow-id="${cssEscape(cleanWorkflowId)}"]`
    );
    const originalContent = copyButton?.textContent || 'Copy JSON';
    const resolvedWorkflowName = workflowName || formatWorkflowName(cleanWorkflowId);
    const payload = buildWorkflowDefinitionLocatorPayload({
        workflowId: cleanWorkflowId,
        workflowName: resolvedWorkflowName
    });
    const jsonString = JSON.stringify(payload, null, 2);

    const copied = await copyJsonTextWithButtonFeedback(copyButton, jsonString, { fallbackLabel: originalContent });
    if (copied) {
        showToast(`Workflow locator JSON copied: ${resolvedWorkflowName}`, 'success');
    } else {
        console.error('[workflowStatus] Failed to copy workflow locator JSON');
        showToast('Failed to copy workflow locator JSON', 'error');
    }
}

async function openWorkflowEpisodesPopup(workflowId, workflowName) {
    if (!workflowId) return;
    const { copyJsonButton } = getWorkflowEpisodesElements();
    if (copyJsonButton) {
        resetCopyJsonButtonPreCopyState(copyJsonButton);
    }
    workflowEpisodesState.workflowId = String(workflowId).trim();
    workflowEpisodesState.workflowName = workflowName || formatWorkflowName(workflowId);
    workflowEpisodesState.loading = true;
    workflowEpisodesState.error = '';
    workflowEpisodesState.items = [];
    workflowEpisodesState.lastPayload = null;
    workflowEpisodesState.lastRequestQuery = '';
    workflowEpisodesState.lastFetchedAt = 0;
    setWorkflowEpisodesPopupVisible(true);
    renderWorkflowEpisodesPopup();

    const snapshot = await fetchWorkflowEpisodesSnapshot(workflowEpisodesState.workflowId, { limit: 60 });
    workflowEpisodesState.lastRequestQuery = snapshot.requestQuery;
    workflowEpisodesState.lastPayload = snapshot.payload;
    workflowEpisodesState.items = snapshot.items;
    workflowEpisodesState.lastFetchedAt = snapshot.fetchedAt;
    if (snapshot.ok) {
        workflowEpisodesState.error = '';
    } else {
        workflowEpisodesState.items = [];
        workflowEpisodesState.error = snapshot.error;
        console.warn('[workflowStatus] Episode fetch failed', snapshot.payload?.detail || 'unknown_error');
    }
    workflowEpisodesState.loading = false;
    renderWorkflowEpisodesPopup();
}

function updateWorkflowStatusActionButtons() {
    const showAvailable = Boolean(workflowDefinitionsState.visible);
    const { toggleAvailableButton, furlToggleButton, refreshButton } = getWorkflowStatusElements();
    if (toggleAvailableButton) {
        toggleAvailableButton.setAttribute('aria-pressed', showAvailable ? 'true' : 'false');
        toggleAvailableButton.textContent = showAvailable ? 'Show active' : 'Show available';
        toggleAvailableButton.title = showAvailable
            ? 'Show active workflow instances'
            : 'Show available workflows';
    }
    if (furlToggleButton) {
        const furled = Boolean(workflowStatusGroupUiState.globallyFurled);
        if (!furlToggleButton.querySelector('.workflow-status-furl-icon')) {
            furlToggleButton.textContent = '';
            const icon = document.createElement('span');
            icon.className = 'workflow-status-furl-icon';
            icon.setAttribute('aria-hidden', 'true');
            furlToggleButton.appendChild(icon);
        }
        furlToggleButton.setAttribute('aria-pressed', furled ? 'true' : 'false');
        furlToggleButton.setAttribute('aria-expanded', furled ? 'false' : 'true');
        furlToggleButton.setAttribute(
            'aria-label',
            furled ? 'Unfurl workflow monitor' : 'Furl workflow monitor'
        );
        furlToggleButton.title = furled
            ? 'Unfurl workflow monitor'
            : 'Furl workflow monitor';
    }
    if (refreshButton) {
        const loading = showAvailable
            ? workflowDefinitionsState.loading
            : workflowStatusStreamState.loading;
        refreshButton.disabled = loading;
        refreshButton.textContent = loading ? 'Refreshing...' : 'Refresh';
        refreshButton.title = showAvailable
            ? (loading ? 'Refreshing available workflows' : 'Refresh workflows')
            : (loading ? 'Refreshing active workflows' : 'Refresh workflows');
    }
}

function formatWorkflowName(workflowId) {
    if (!workflowId) return 'Unknown workflow';
    const trimmed = String(workflowId).trim();
    if (trimmed.startsWith('#V#')) {
        return trimmed.slice(3).replace(/_/g, ' ');
    }
    return trimmed;
}

function formatWorkflowStatusLabel(status) {
    if (!status) return 'unknown';
    return String(status).replace(/_/g, ' ');
}

function formatWorkflowStatusInstanceId(instanceId) {
    const trimmed = String(instanceId || '').trim();
    if (!trimmed) return '';
    if (trimmed.length <= WORKFLOW_STATUS_INSTANCE_ID_INLINE_MAX_CHARS) {
        return trimmed;
    }
    return `${trimmed.slice(0, 12)}...${trimmed.slice(-6)}`;
}

function cssEscape(value) {
    const raw = String(value ?? '');
    if (typeof CSS !== 'undefined' && typeof CSS.escape === 'function') {
        return CSS.escape(raw);
    }
    return raw.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

function getWorkflowStatusItemSortRank(status) {
    if (status === 'running') return 0;
    if (status === 'pending') return 1;
    if (status === 'paused') return 2;
    return 3;
}

function getWorkflowStatusItemUpdatedAt(item) {
    const progressUpdatedAt = String(item?.progress?.updated_at || '').trim();
    if (progressUpdatedAt) {
        return progressUpdatedAt;
    }
    const eventUpdatedAt = String(item?.updated_at || '').trim();
    if (eventUpdatedAt) {
        return eventUpdatedAt;
    }
    const startedAt = String(item?.started_at || '').trim();
    if (startedAt) {
        return startedAt;
    }
    const createdAt = String(item?.created_at || '').trim();
    return createdAt;
}

function sortWorkflowStatusItems(items) {
    return (Array.isArray(items) ? items.slice() : []).sort((a, b) => {
        const statusDelta = getWorkflowStatusItemSortRank(a?.status) - getWorkflowStatusItemSortRank(b?.status);
        if (statusDelta !== 0) return statusDelta;
        return getWorkflowStatusItemUpdatedAt(b).localeCompare(getWorkflowStatusItemUpdatedAt(a));
    });
}

function normaliseWorkflowStatusGroupId(workflowId) {
    const cleaned = typeof workflowId === 'string' ? workflowId.trim() : '';
    return cleaned || '__unknown_workflow__';
}

function buildWorkflowStatusGroups(items) {
    const groups = new Map();
    const orderedItems = sortWorkflowStatusItems(items);

    orderedItems.forEach((item) => {
        const workflowId = normaliseWorkflowStatusGroupId(item?.workflow_id);
        if (!groups.has(workflowId)) {
            groups.set(workflowId, {
                workflowId,
                workflowLabel: workflowId === '__unknown_workflow__' ? 'Unknown workflow' : workflowId,
                workflowNameText: formatWorkflowName(item?.workflow_id),
                items: [],
                statusCounts: new Map()
            });
        }
        const group = groups.get(workflowId);
        group.items.push(item);
        const statusKey = String(item?.status || 'unknown').trim() || 'unknown';
        group.statusCounts.set(statusKey, (group.statusCounts.get(statusKey) || 0) + 1);
    });

    return Array.from(groups.values()).sort((left, right) => {
        const leftRepresentative = left.items[0] || {};
        const rightRepresentative = right.items[0] || {};
        const statusDelta = getWorkflowStatusItemSortRank(leftRepresentative.status) - getWorkflowStatusItemSortRank(rightRepresentative.status);
        if (statusDelta !== 0) {
            return statusDelta;
        }
        const updatedDelta = getWorkflowStatusItemUpdatedAt(rightRepresentative).localeCompare(
            getWorkflowStatusItemUpdatedAt(leftRepresentative)
        );
        if (updatedDelta !== 0) {
            return updatedDelta;
        }
        return left.workflowLabel.localeCompare(right.workflowLabel);
    });
}

function buildWorkflowStatusGroupSummary(group) {
    const statusSummary = Array.from(group.statusCounts.entries())
        .sort((left, right) => {
            const rankDelta = getWorkflowStatusItemSortRank(left[0]) - getWorkflowStatusItemSortRank(right[0]);
            if (rankDelta !== 0) {
                return rankDelta;
            }
            return String(left[0]).localeCompare(String(right[0]));
        })
        .map(([status, count]) => `${count} ${formatWorkflowStatusLabel(status)}`)
        .join(' · ');
    const latestItem = Array.isArray(group.items) ? group.items[0] : null;
    const latestState = String(latestItem?.current_state || latestItem?.progress?.message || '').trim();
    const latestUpdatedAt = getWorkflowStatusItemUpdatedAt(latestItem);
    const bits = [];
    if (statusSummary) {
        bits.push(statusSummary);
    }
    if (latestState) {
        bits.push(`Latest: ${latestState}`);
    }
    if (latestUpdatedAt) {
        bits.push(`Updated: ${formatWorkflowEpisodeTimestamp(latestUpdatedAt)}`);
    }
    return bits.join(' · ');
}

function isWorkflowStatusGroupCollapsed(workflowId, options = {}) {
    const itemCount = Number(options.itemCount) || 0;
    const groupCount = Number(options.groupCount) || 0;
    if (workflowStatusGroupUiState.collapsedByWorkflowId.has(workflowId)) {
        return Boolean(workflowStatusGroupUiState.collapsedByWorkflowId.get(workflowId));
    }
    return !(groupCount === 1 && itemCount <= 1);
}

function pruneWorkflowStatusGroupState(groups) {
    const activeIds = new Set(
        (Array.isArray(groups) ? groups : [])
            .map((group) => String(group?.workflowId || '').trim())
            .filter(Boolean)
    );
    Array.from(workflowStatusGroupUiState.collapsedByWorkflowId.keys()).forEach((workflowId) => {
        if (!activeIds.has(workflowId)) {
            workflowStatusGroupUiState.collapsedByWorkflowId.delete(workflowId);
        }
    });
}

function getWorkflowMonitorRestoreDelayMs(payload, fallbackMs) {
    const scheduledMs = Number(payload?.retry_scheduled_in_ms);
    if (Number.isFinite(scheduledMs) && scheduledMs > 0) {
        return scheduledMs;
    }
    return Math.max(50, Math.round(Number(fallbackMs) || 50));
}

function restoreWorkflowMonitorTimersAfterUnfurl() {
    syncWorkflowCapabilityIndexPolling();

    if (workflowDefinitionsState.visible) {
        const definitionsPayload = (
            workflowDefinitionsState.lastPayload && typeof workflowDefinitionsState.lastPayload === 'object'
        ) ? workflowDefinitionsState.lastPayload : null;
        if (definitionsPayload?.retryable === true) {
            scheduleWorkflowDefinitionsRetry({
                delayMs: getWorkflowMonitorRestoreDelayMs(
                    definitionsPayload,
                    WORKFLOW_DEFINITIONS_CONTENTION_RETRY_BASE_MS
                ),
                silent: true
            });
        }
        return;
    }

    if (!shouldAutoRefreshWorkflowStatusSnapshot()) {
        return;
    }

    const activeSnapshotPayload = (
        workflowStatusStreamState.lastSnapshotPayload &&
        typeof workflowStatusStreamState.lastSnapshotPayload === 'object'
    ) ? workflowStatusStreamState.lastSnapshotPayload : null;
    if (activeSnapshotPayload?.retryable === true) {
        scheduleWorkflowStatusSnapshotRetry({
            delayMs: getWorkflowMonitorRestoreDelayMs(
                activeSnapshotPayload,
                WORKFLOW_STATUS_SNAPSHOT_RETRY_BASE_MS
            ),
            silent: true
        });
        return;
    }

    scheduleWorkflowStatusLiveRefresh();
}

function setWorkflowMonitorGloballyFurled(furled) {
    const nextFurled = Boolean(furled);
    workflowStatusGroupUiState.globallyFurled = nextFurled;
    if (nextFurled) {
        clearWorkflowStatusLiveRefreshTimer();
        clearWorkflowStatusSnapshotRetryTimer();
        clearWorkflowDefinitionsRetryTimer();
    }
    if (!nextFurled) {
        restoreWorkflowMonitorTimersAfterUnfurl();
    }
    renderWorkflowStatusBody();
}

function renderWorkflowStatusItemCard(item) {
    const instanceIdRaw = typeof item?.instance_id === 'string' ? item.instance_id.trim() : '';
    const statusLabel = escapeHtml(formatWorkflowStatusLabel(item?.status));
    const statusClass = escapeHtml(item?.status || 'unknown');
    const currentState = escapeHtml(item?.current_state || '');
    const progress = item?.progress || {};
    const progressCurrent = Number.isFinite(progress.current) ? Number(progress.current) : null;
    const progressTotal = Number.isFinite(progress.total) ? Number(progress.total) : null;
    const progressMessage = escapeHtml(progress.message || '');
    const instanceIdText = formatWorkflowStatusInstanceId(instanceIdRaw);
    const cardTitle = instanceIdText || 'Active instance';
    const updatedAt = getWorkflowStatusItemUpdatedAt(item);

    let percent = null;
    if (progressCurrent !== null && progressTotal && progressTotal > 0) {
        percent = Math.min(100, Math.max(0, Math.round((progressCurrent / progressTotal) * 100)));
    }

    const progressLabelBits = [];
    if (progressCurrent !== null && progressTotal) {
        progressLabelBits.push(`Step ${progressCurrent}/${progressTotal}`);
    } else if (Number.isFinite(item?.step_index)) {
        progressLabelBits.push(`Step ${Number(item.step_index)}`);
    }
    if (progressMessage) {
        progressLabelBits.push(progressMessage);
    } else if (currentState) {
        progressLabelBits.push(currentState);
    }

    const progressLabel = progressLabelBits.length
        ? `<div class="workflow-status-progress-text">${escapeHtml(progressLabelBits.join(' · '))}</div>`
        : '';
    const progressBar = percent !== null
        ? `<div class="workflow-status-progress-bar">
                <span style="width: ${percent}%;"></span>
              </div>`
        : '';
    const updatedMeta = updatedAt
        ? `<div class="workflow-status-meta">Updated: ${escapeHtml(formatWorkflowEpisodeTimestamp(updatedAt))}</div>`
        : '';

    return `
        <div class="workflow-status-item status-${statusClass}">
          <div class="workflow-status-item-header">
            <div class="workflow-status-instance-title" title="${escapeHtml(instanceIdRaw || cardTitle)}">${escapeHtml(cardTitle)}</div>
            <span class="workflow-status-badge status-${statusClass}">${statusLabel}</span>
          </div>
          <div class="workflow-status-meta">State: ${currentState || '—'}</div>
          ${updatedMeta}
          <div class="workflow-status-progress">
            ${progressBar}
            ${progressLabel}
          </div>
        </div>
    `;
}

function formatWorkflowDefinitionStatus(item) {
    if (!item || item.is_executable === true) {
        return 'available';
    }

    const reason = String(item.executability_reason || '').trim();
    if (!reason) {
        return 'not executable';
    }
    if (reason === 'workflow_step_partially_vacuous') {
        return 'partially vacuous';
    }
    if (reason === 'workflow_step_completely_vacuous') {
        return 'completely vacuous';
    }
    if (reason === 'workflow_step_integrity_issue') {
        return 'vacuous';
    }
    if (reason === 'graph_incomplete') {
        return 'partially available';
    }
    if (reason === 'non_executable_design_artifact') {
        return 'non-executable design artifact';
    }
    return reason.replace(/_/g, ' ');
}

function formatWorkflowDefinitionStatusClass(item) {
    if (!item || item.is_executable === true) {
        return 'available';
    }
    const reason = String(item.executability_reason || '').trim();
    if (reason === 'workflow_step_partially_vacuous') {
        return 'partially-vacuous';
    }
    if (reason === 'workflow_step_completely_vacuous') {
        return 'completely-vacuous';
    }
    if (reason === 'workflow_step_integrity_issue') {
        return 'vacuous';
    }
    if (reason === 'graph_incomplete') {
        return 'partially-available';
    }
    return 'not-executable';
}

function isWorkflowDesignArtifact(item) {
    return String(item?.executability_reason || '').trim() === 'non_executable_design_artifact';
}

function filterWorkflowDefinitionsForDisplay(items) {
    const list = Array.isArray(items) ? items : [];
    if (workflowDefinitionsState.showDesigns) {
        return list.slice();
    }
    return list.filter((item) => !isWorkflowDesignArtifact(item));
}

function formatWorkflowExecutabilitySummary(item) {
    if (!item || item.is_executable === true) {
        return '';
    }
    const reason = String(item.executability_reason || '').trim();
    const detail = String(item.executability_detail || '').trim();

    if (
        reason === 'workflow_step_partially_vacuous' ||
        reason === 'workflow_step_completely_vacuous' ||
        reason === 'workflow_step_integrity_issue'
    ) {
        const countMatch = /count=(\d+)/.exec(detail);
        const count = countMatch && countMatch[1] ? countMatch[1] : null;
        const totalMatch = /total=(\d+)/.exec(detail);
        const total = totalMatch && totalMatch[1] ? totalMatch[1] : null;
        if (count) {
            if (reason === 'workflow_step_completely_vacuous') {
                return `All ${count} workflow step(s) are vacuous.`;
            }
            if (
                reason === 'workflow_step_partially_vacuous' &&
                total &&
                count
            ) {
                return `${count}/${total} workflow step(s) are vacuous`;
            }
            return `Vacuous workflow steps detected (${count}).`;
        }
        return 'Vacuous workflow step detected.';
    }
    if (reason === 'graph_incomplete') {
        if (detail) {
            return `Graph issue: ${detail.replace(/_/g, ' ')}`;
        }
        return 'Workflow graph incomplete.';
    }

    if (detail) {
        return detail;
    }
    return formatWorkflowDefinitionStatus(item);
}

function buildWorkflowStatusQuery({ includeStatusFilter } = {}) {
    const params = new URLSearchParams();
    const namespace = getSessionScopedNamespace();
    const orgContext = getSessionScopedOrgContext();
    const userId = getCurrentUserConceptId();

    if (namespace) {
        // Namespace is the authoritative partition key for workflow data.
        // Some valid instances were created with placeholder user/org fields
        // (e.g. anonymous/default); filtering by user/org would hide them.
        params.set('namespace', namespace);
    } else {
        if (orgContext?.concept_id || orgContext?.id) {
            params.set('org_id', orgContext.concept_id || orgContext.id);
        }
        if (userId) params.set('user_id', userId);
    }
    if (includeStatusFilter) {
        params.set('status', Array.from(WORKFLOW_STATUS_ACTIVE).join(','));
    }
    return params;
}

function buildWorkflowStatusStreamQuery() {
    const params = buildWorkflowStatusQuery();
    // Subscribe to all status transitions for the scoped namespace/user/org so
    // terminal updates (completed/failed/cancelled) can remove active cards.
    // Filtering to active-only statuses here causes stale "running" rows.
    return params;
}

function applySharedWorkflowCapabilityIndexPayload(payload) {
    if (!payload || typeof payload !== 'object') {
        return;
    }
    workflowCapabilityIndexState.error = '';
    workflowCapabilityIndexState.lastFetchedAt = Date.now();
    syncWorkflowCapabilityIndexPolling();
    renderWorkflowStatusBody();
}

function ensureWorkflowCapabilityIndexStatusSubscription() {
    if (workflowCapabilityIndexStatusUnsubscribe) {
        return;
    }
    workflowCapabilityIndexStatusUnsubscribe = subscribeToWorkflowCapabilityIndexStatus(
        applySharedWorkflowCapabilityIndexPayload
    );
}

function applyWorkflowCapabilityIndexPayload(payload) {
    if (!payload || typeof payload !== 'object') {
        return;
    }
    ensureWorkflowCapabilityIndexStatusSubscription();
    const previousPayload = getLatestWorkflowCapabilityIndexStatus();
    const acceptedPayload = acceptSharedWorkflowCapabilityIndexStatus(payload);
    // Event dispatch is best effort in the shared coordinator. Apply the
    // accepted (possibly newer) snapshot locally as well so this monitor stays
    // correct in browsers where cross-frame event dispatch is unavailable.
    if (acceptedPayload !== previousPayload) {
        applySharedWorkflowCapabilityIndexPayload(acceptedPayload);
    }
}

function getWorkflowCapabilityIndexPayload() {
    return getLatestWorkflowCapabilityIndexStatus();
}

function clearWorkflowCapabilityIndexPollTimer() {
    if (!workflowCapabilityIndexState.pollTimeoutId) {
        return;
    }
    clearTimeout(workflowCapabilityIndexState.pollTimeoutId);
    workflowCapabilityIndexState.pollTimeoutId = null;
}

function shouldPollWorkflowCapabilityIndex() {
    if (workflowStatusGroupUiState.globallyFurled) {
        return false;
    }
    const { panel } = getWorkflowStatusElements();
    if (!panel) {
        return false;
    }
    const payload = getWorkflowCapabilityIndexPayload();
    return Boolean(payload && typeof payload === 'object' && payload.ready !== true);
}

function syncWorkflowCapabilityIndexPolling() {
    if (!shouldPollWorkflowCapabilityIndex()) {
        clearWorkflowCapabilityIndexPollTimer();
        return;
    }
    if (workflowCapabilityIndexState.pollTimeoutId) {
        return;
    }
    workflowCapabilityIndexState.pollTimeoutId = setTimeout(() => {
        workflowCapabilityIndexState.pollTimeoutId = null;
        if (!shouldPollWorkflowCapabilityIndex()) {
            return;
        }
        void refreshWorkflowCapabilityIndexStatus({ silent: true }).finally(() => {
            syncWorkflowCapabilityIndexPolling();
        });
    }, WORKFLOW_CAPABILITY_INDEX_POLL_INTERVAL_MS);
}

function buildWorkflowCapabilityIndexWarningHtml() {
    const payload = getWorkflowCapabilityIndexPayload();
    const loadError = String(workflowCapabilityIndexState.error || '').trim();
    if (loadError) {
        return `
            <div class="workflow-status-warning-cartouche status-error" role="status" aria-live="polite">
              <div class="workflow-status-warning-title">Capability index status unavailable</div>
              <div class="workflow-status-warning-detail">${escapeHtml(loadError)}</div>
            </div>
        `;
    }

    if (!payload || typeof payload !== 'object') {
        if (!workflowCapabilityIndexState.loading) {
            return '';
        }
        return `
            <div class="workflow-status-warning-cartouche status-info" role="status" aria-live="polite">
              <div class="workflow-status-warning-title">Checking workflow capability index</div>
              <div class="workflow-status-warning-detail">Waiting for the authoritative workflow capability index status.</div>
            </div>
        `;
    }

    if (payload.ready === true) {
        return '';
    }

    const status = (typeof payload.status === 'string' && payload.status.trim())
        ? payload.status.trim()
        : 'not_ready';
    const severityClass = status === 'error' ? 'status-error' : 'status-warning';
    const summary = (typeof payload.summary === 'string' && payload.summary.trim())
        ? payload.summary.trim()
        : 'Workflow capability index not ready.';
    const detail = (typeof payload.detail === 'string' && payload.detail.trim())
        ? payload.detail.trim()
        : 'Workflow discovery is waiting on the authoritative capability index.';
    const metaBits = [];
    const startupCheck = payload.startup_check && typeof payload.startup_check === 'object'
        ? payload.startup_check
        : null;
    if (startupCheck?.checked_at_utc) {
        metaBits.push(`Startup check: ${formatWorkflowEpisodeTimestamp(startupCheck.checked_at_utc)}`);
    }
    if (typeof payload.size === 'number') {
        metaBits.push(`Indexed: ${payload.size}`);
    }
    if (typeof payload.last_mode === 'string' && payload.last_mode.trim()) {
        metaBits.push(`Mode: ${payload.last_mode.trim()}`);
    }
    if (typeof payload.checked_at_utc === 'string' && payload.checked_at_utc.trim()) {
        metaBits.push(`Checked: ${formatWorkflowEpisodeTimestamp(payload.checked_at_utc.trim())}`);
    }
    if (workflowCapabilityIndexState.lastFetchedAt) {
        metaBits.push(`Fetched: ${formatWorkflowEpisodeTimestamp(new Date(workflowCapabilityIndexState.lastFetchedAt).toISOString())}`);
    }
    if (typeof payload.last_error === 'string' && payload.last_error.trim()) {
        metaBits.push(`Reason: ${payload.last_error.trim()}`);
    }
    const metaHtml = metaBits.length
        ? `<div class="workflow-status-warning-meta">${escapeHtml(metaBits.join(' · '))}</div>`
        : '';

    return `
        <div class="workflow-status-warning-cartouche ${severityClass}" role="status" aria-live="polite">
          <div class="workflow-status-warning-title">${escapeHtml(summary)}</div>
          <div class="workflow-status-warning-detail">${escapeHtml(detail)}</div>
          ${metaHtml}
        </div>
    `;
}

function describeWorkflowCapabilityIndexStatusFetchError(err) {
    if (err && typeof err === 'object' && err.vonTimeout) {
        const timeoutSeconds = Math.round(WORKFLOW_CAPABILITY_INDEX_FETCH_TIMEOUT_MS / 1000);
        return `request timed out after ${timeoutSeconds}s`;
    }
    if (err && typeof err === 'object' && err.name === 'AbortError') {
        return 'request was cancelled before the status response arrived';
    }
    return err instanceof Error ? err.message : String(err || 'unknown_error');
}

async function refreshWorkflowCapabilityIndexStatus({ silent = false, force = false } = {}) {
    const { panel } = getWorkflowStatusElements();
    if (!panel) return;
    ensureWorkflowCapabilityIndexStatusSubscription();
    const now = Date.now();
    const currentPayload = getWorkflowCapabilityIndexPayload();
    if (
        !force
        && silent
        && currentPayload
        && Number.isFinite(workflowCapabilityIndexState.lastFetchedAt)
        && workflowCapabilityIndexState.lastFetchedAt > 0
        && (now - workflowCapabilityIndexState.lastFetchedAt) < WORKFLOW_CAPABILITY_INDEX_SILENT_REFRESH_COOLDOWN_MS
    ) {
        return currentPayload;
    }

    workflowCapabilityIndexState.loading = true;
    if (!silent) {
        renderWorkflowStatusBody();
    }

    let refreshError = null;
    const fetchImpl = async (url, options = {}) => {
        try {
            const resp = await fetchWithTimeout(url, {
                ...options,
                method: 'GET',
                headers: {
                    ...(options.headers || {}),
                    ...buildChatFetchHeaders()
                },
                timeoutMs: WORKFLOW_CAPABILITY_INDEX_FETCH_TIMEOUT_MS
            });
            if (!resp.ok) {
                const responsePayload = await resp.json().catch(() => null);
                const detail = (typeof responsePayload?.detail === 'string' && responsePayload.detail.trim())
                    ? responsePayload.detail.trim()
                    : '';
                throw new Error(detail || `HTTP ${resp.status}`);
            }
            return resp;
        } catch (err) {
            refreshError = err;
            const message = describeWorkflowCapabilityIndexStatusFetchError(err);
            workflowCapabilityIndexState.error = `Could not load capability index status: ${message}`;
            if (!silent) {
                console.warn('[workflowStatus] Capability index status fetch failed', err);
            }
            throw err;
        }
    };

    try {
        const payload = await refreshSharedWorkflowCapabilityIndexStatus({ force, fetchImpl });
        if (
            payload
            && typeof payload === 'object'
            && !refreshError
            && payload !== currentPayload
        ) {
            applySharedWorkflowCapabilityIndexPayload(payload);
        }
        return payload;
    } finally {
        workflowCapabilityIndexState.loading = false;
        renderWorkflowStatusBody();
    }
}

function buildWorkflowMonitorExportPayload() {
    const namespace = getSessionScopedNamespace();
    const orgContext = getSessionScopedOrgContext();
    const userId = getCurrentUserConceptId();
    const definitionsPayload = (
        workflowDefinitionsState.lastPayload && typeof workflowDefinitionsState.lastPayload === 'object'
    ) ? workflowDefinitionsState.lastPayload : null;
    const parityInventory = (
        definitionsPayload && typeof definitionsPayload.parity_inventory === 'object'
    ) ? definitionsPayload.parity_inventory : null;
    const filteredItems = filterWorkflowDefinitionsForDisplay(workflowDefinitionsState.items);
    const renderedWorkflowIds = filteredItems
        .map((item) => (typeof item?.workflow_id === 'string' ? item.workflow_id.trim() : ''))
        .filter(Boolean);
    const hiddenDesignWorkflowIds = workflowDefinitionsState.items
        .filter((item) => isWorkflowDesignArtifact(item))
        .map((item) => (typeof item?.workflow_id === 'string' ? item.workflow_id.trim() : ''))
        .filter((workflowId) => workflowId && !renderedWorkflowIds.includes(workflowId));
    const activeItems = Array.from(workflowStatusStreamState.items.values());
    const activeGroups = buildWorkflowStatusGroups(activeItems);
    const capabilityIndexPayload = getWorkflowCapabilityIndexPayload();

    return {
        schema_version: 1,
        exported_at: new Date().toISOString(),
        namespace_context: {
            namespace: namespace || null,
            user_id: userId || null,
            org_id: orgContext?.concept_id || orgContext?.id || null
        },
        monitor_state: {
            mode: workflowDefinitionsState.visible ? 'available_workflows' : 'active_instances',
            show_available: Boolean(workflowDefinitionsState.visible),
            show_designs: Boolean(workflowDefinitionsState.showDesigns),
            active_loading: Boolean(workflowStatusStreamState.loading),
            loading_available: Boolean(workflowDefinitionsState.loading),
            active_error: workflowStatusStreamState.snapshotError || null,
            active_notice: workflowStatusStreamState.snapshotNotice || null,
            global_furled: Boolean(workflowStatusGroupUiState.globallyFurled),
            active_live_refresh_timer_active: Boolean(workflowStatusStreamState.liveRefreshTimeoutId),
            active_retry_timer_active: Boolean(workflowStatusStreamState.retryTimeoutId),
            available_retry_timer_active: Boolean(workflowDefinitionsState.retryTimeoutId),
            active_last_snapshot_at: workflowStatusStreamState.lastSnapshotAt
                ? new Date(workflowStatusStreamState.lastSnapshotAt).toISOString()
                : null,
            available_error: workflowDefinitionsState.error || null,
            available_notice: workflowDefinitionsState.notice || null,
            capability_index_loading: Boolean(workflowCapabilityIndexState.loading),
            capability_index_error: workflowCapabilityIndexState.error || null,
            capability_index_poll_active: Boolean(workflowCapabilityIndexState.pollTimeoutId),
            capability_index_poll_interval_ms: WORKFLOW_CAPABILITY_INDEX_POLL_INTERVAL_MS,
            capability_index_last_fetched_at: workflowCapabilityIndexState.lastFetchedAt
                ? new Date(workflowCapabilityIndexState.lastFetchedAt).toISOString()
                : null,
            available_last_fetched_at: workflowDefinitionsState.lastFetchedAt
                ? new Date(workflowDefinitionsState.lastFetchedAt).toISOString()
                : null
        },
        capability_index: capabilityIndexPayload,
        definitions_snapshot: {
            request_query: workflowDefinitionsState.lastRequestQuery || null,
            rendered_count: renderedWorkflowIds.length,
            rendered_workflow_ids: renderedWorkflowIds,
            hidden_design_count: hiddenDesignWorkflowIds.length,
            hidden_design_workflow_ids: hiddenDesignWorkflowIds,
            contains_salient_predicate_governance_workflow: renderedWorkflowIds.includes('#V#salient_predicate_governance_workflow'),
            payload: definitionsPayload
        },
        active_instances_snapshot: {
            count: activeItems.length,
            group_count: activeGroups.length,
            groups: activeGroups.map((group) => ({
                workflow_id: group.workflowId === '__unknown_workflow__' ? null : group.workflowId,
                workflow_name: group.workflowNameText || null,
                count: group.items.length,
                latest_updated_at: getWorkflowStatusItemUpdatedAt(group.items[0] || null) || null,
                status_counts: Object.fromEntries(group.statusCounts)
            })),
            items: activeItems,
            payload: workflowStatusStreamState.lastSnapshotPayload
        },
        diagnostics: {
            parity_counts: parityInventory?.counts || null,
            parity_reason_codes: Array.isArray(parityInventory?.diagnostics?.reason_codes)
                ? parityInventory.diagnostics.reason_codes
                : [],
            vontology_only_workflow_ids: Array.isArray(parityInventory?.vontology_only_workflow_ids)
                ? parityInventory.vontology_only_workflow_ids
                : [],
            graph_warnings_by_workflow_id: (
                parityInventory?.representation &&
                typeof parityInventory.representation === 'object' &&
                typeof parityInventory.representation.graph_warnings_by_workflow_id === 'object'
            )
                ? parityInventory.representation.graph_warnings_by_workflow_id
                : {}
        }
    };
}

async function handleCopyWorkflowMonitorJson() {
    const { copyJsonButton } = getWorkflowStatusElements();
    if (!copyJsonButton) return;

    const payload = buildWorkflowMonitorLocatorPayload();
    const jsonString = JSON.stringify(payload, null, 2);

    const copied = await copyJsonTextWithButtonFeedback(copyJsonButton, jsonString);
    if (copied) {
        showToast('Workflow monitor locator JSON copied', 'success');
    } else {
        console.error('[workflowStatus] Failed to copy monitor locator JSON');
        showToast('Failed to copy workflow monitor locator JSON', 'error');
    }
}

function renderWorkflowStatusList(items) {
    const { body } = getWorkflowStatusElements();
    if (!body) return;

    const bannerParts = [];
    const capabilityIndexWarning = buildWorkflowCapabilityIndexWarningHtml();
    if (capabilityIndexWarning) {
        bannerParts.push(capabilityIndexWarning);
    }
    if (workflowStatusStreamState.snapshotError) {
        bannerParts.push(`<div class="workflow-status-empty workflow-status-error">${escapeHtml(workflowStatusStreamState.snapshotError)}</div>`);
    } else if (workflowStatusStreamState.snapshotNotice) {
        bannerParts.push(`<div class="workflow-status-empty workflow-status-info">${escapeHtml(workflowStatusStreamState.snapshotNotice)}</div>`);
    }
    const bannerHtml = bannerParts.join('');

    if (!items.length) {
        body.innerHTML = `${bannerHtml}<div class="workflow-status-empty">No active workflows</div>`;
        return;
    }

    const groups = buildWorkflowStatusGroups(items);
    pruneWorkflowStatusGroupState(groups);

    const html = groups.map((group, index) => {
        const workflowIdRaw = group.workflowId === '__unknown_workflow__' ? '' : group.workflowId;
        const workflowNameText = group.workflowNameText || formatWorkflowName(workflowIdRaw);
        const workflowConceptId = _normalisePotentialConceptId(workflowIdRaw);
        const workflowName = workflowConceptId
            ? renderConceptSelectionButtonHTML(workflowConceptId, workflowNameText, {
                classNames: ['workflow-status-concept-link'],
                title: 'Open concept tab'
            })
            : escapeHtml(workflowNameText);
        const isCollapsed = isWorkflowStatusGroupCollapsed(group.workflowId, {
            itemCount: group.items.length,
            groupCount: groups.length
        });
        const bodyId = `workflow-status-group-body-${index}`;
        const groupSummary = buildWorkflowStatusGroupSummary(group);
        const instanceCountLabel = `${group.items.length} ${group.items.length === 1 ? 'instance' : 'instances'}`;

        return `
            <section class="workflow-status-group" data-workflow-id="${escapeHtml(group.workflowId)}" data-collapsed="${isCollapsed ? 'true' : 'false'}">
              <div class="workflow-status-group-header">
                <button
                    type="button"
                    class="workflow-status-group-toggle"
                    data-workflow-id="${escapeHtml(group.workflowId)}"
                    aria-expanded="${isCollapsed ? 'false' : 'true'}"
                    aria-controls="${escapeHtml(bodyId)}"
                    title="${isCollapsed ? 'Expand workflow group' : 'Collapse workflow group'}"
                >
                  <span class="workflow-status-group-chevron" aria-hidden="true"></span>
                  <span class="visually-hidden">${isCollapsed ? 'Expand' : 'Collapse'} ${escapeHtml(workflowNameText)}</span>
                </button>
                <div class="workflow-status-group-title">
                  <div class="workflow-status-name">${workflowName}</div>
                  <div class="workflow-status-group-summary">${escapeHtml(groupSummary || instanceCountLabel)}</div>
                </div>
                <span class="workflow-status-badge workflow-status-count-badge">${escapeHtml(instanceCountLabel)}</span>
              </div>
              <div id="${escapeHtml(bodyId)}" class="workflow-status-group-body${isCollapsed ? ' is-collapsed' : ''}">
                ${group.items.map((item) => renderWorkflowStatusItemCard(item)).join('')}
              </div>
            </section>
        `;
    }).join('');

    body.innerHTML = `${bannerHtml}${html}`;
}

function renderWorkflowDefinitionsList(items) {
    const { body } = getWorkflowStatusElements();
    if (!body) return;

    if (workflowDefinitionsState.loading && !items.length) {
        const capabilityIndexWarning = buildWorkflowCapabilityIndexWarningHtml();
        body.innerHTML = `${capabilityIndexWarning}<div class="workflow-status-empty">Loading available workflows…</div>`;
        return;
    }

    const bannerParts = [];
    const capabilityIndexWarning = buildWorkflowCapabilityIndexWarningHtml();
    if (capabilityIndexWarning) {
        bannerParts.push(capabilityIndexWarning);
    }
    if (workflowDefinitionsState.loading && items.length) {
        bannerParts.push('<div class="workflow-status-empty">Refreshing available workflows…</div>');
    }
    if (workflowDefinitionsState.error) {
        bannerParts.push(`<div class="workflow-status-empty workflow-status-error">${escapeHtml(workflowDefinitionsState.error)}</div>`);
    } else if (workflowDefinitionsState.notice) {
        bannerParts.push(`<div class="workflow-status-empty workflow-status-info">${escapeHtml(workflowDefinitionsState.notice)}</div>`);
    }
    const bannerHtml = bannerParts.join('');

    if (!items.length) {
        body.innerHTML = `${bannerHtml}<div class="workflow-status-empty">No available workflows</div>`;
        return;
    }

    const filteredItems = filterWorkflowDefinitionsForDisplay(items);
    if (!filteredItems.length) {
        body.innerHTML = `${bannerHtml}<div class="workflow-status-empty">No available workflows (design artefacts hidden)</div>`;
        return;
    }

    const ordered = filteredItems.slice().sort((a, b) => {
        const left = String(a?.workflow_id || '');
        const right = String(b?.workflow_id || '');
        return left.localeCompare(right);
    });

    const html = ordered.map((item) => {
        const workflowIdRaw = typeof item?.workflow_id === 'string' ? item.workflow_id.trim() : '';
        const workflowNameText = formatWorkflowName(workflowIdRaw);
        const workflowConceptId = _normalisePotentialConceptId(workflowIdRaw);
        const workflowName = renderConceptSelectionButtonHTML(workflowConceptId, workflowNameText, {
            classNames: ['workflow-status-concept-link'],
            title: 'Open concept tab'
        });
        const workflowId = renderConceptSelectionButtonHTML(workflowConceptId, workflowIdRaw, {
            classNames: ['workflow-status-concept-link', 'workflow-status-id-link'],
            title: 'Open concept tab'
        });
        const description = escapeHtml(item.description || 'No description available.');
        const initialState = escapeHtml(item.initial_state || '—');
        const source = escapeHtml(formatWorkflowStatusLabel(item.source || 'unknown'));
        const statusClass = escapeHtml(formatWorkflowDefinitionStatusClass(item));
        const statusLabel = escapeHtml(formatWorkflowDefinitionStatus(item));
        const executableSummary = formatWorkflowExecutabilitySummary(item);
        const attempts = Number.isFinite(Number(item?.attempts)) ? Number(item.attempts) : 0;
        const completions = Number.isFinite(Number(item?.completions)) ? Number(item.completions) : 0;
        const failures = Number.isFinite(Number(item?.failures)) ? Number(item.failures) : 0;
        const inProgress = Number.isFinite(Number(item?.in_progress)) ? Number(item.in_progress) : 0;
        const terminalSuccessRateRaw = Number(item?.terminal_success_rate);
        const terminalSuccessRate = Number.isFinite(terminalSuccessRateRaw)
            ? `${Math.round(Math.max(0, Math.min(1, terminalSuccessRateRaw)) * 100)}%`
            : '—';
        const episodesCountRaw = Number(item?.episodes_count);
        const episodesCount = Number.isFinite(episodesCountRaw) && episodesCountRaw >= 0
            ? Math.max(0, Math.trunc(episodesCountRaw))
            : null;
        let episodesSummary = 'Episodes: —';
        if (episodesCount !== null) {
            if (attempts > episodesCount) {
                episodesSummary = `Episodes: ${episodesCount} scoped (${attempts} total)`;
            } else {
                episodesSummary = `Episodes: ${episodesCount}`;
            }
        }
        const usageMeta = `Uses: ${attempts} · Succeeded: ${completions} · Failed: ${failures} · Open: ${inProgress} · ${episodesSummary} · Terminal success: ${terminalSuccessRate}`;
        const executionMeta = executableSummary
            ? `<div class="workflow-status-definition-meta">Status detail: ${escapeHtml(executableSummary)}</div>`
            : '';
        const episodesDisabled = episodesCount === 0;
        const episodesButton = `<button type="button" class="btn-mini workflow-status-episodes-btn" data-workflow-id="${escapeHtml(workflowIdRaw)}" data-workflow-name="${escapeHtml(workflowNameText)}"${episodesDisabled ? ' disabled' : ''} title="${escapeHtml(episodesDisabled ? 'No episodes in current scope' : 'Open workflow episodes')}">Episodes</button>`;
        const copyCardJsonButton = `<button type="button" class="btn-mini workflow-status-copy-card-json-btn" data-workflow-id="${escapeHtml(workflowIdRaw)}" data-workflow-name="${escapeHtml(workflowNameText)}" title="Copy workflow summary and episodes JSON">Copy JSON</button>`;
        return `
            <div class="workflow-status-item status-${statusClass}">
              <div class="workflow-status-item-header">
                <div class="workflow-status-name">${workflowName}</div>
                <span class="workflow-status-badge status-${statusClass}">${statusLabel}</span>
              </div>
              <div class="workflow-status-definition-description">${description}</div>
              <div class="workflow-status-definition-meta">
                ID: ${workflowId} · Initial state: ${initialState} · Source: ${source}
              </div>
              <div class="workflow-status-definition-meta">${escapeHtml(usageMeta)}</div>
              ${executionMeta}
              <div class="workflow-status-definition-actions">${copyCardJsonButton}${episodesButton}</div>
            </div>
        `;
    }).join('');

    body.innerHTML = `${bannerHtml}${html}`;
}

function bindWorkflowStatusConceptLinks() {
    const { body } = getWorkflowStatusElements();
    if (!body) {
        return;
    }
    bindConceptSelectionClicks(body, {
        selector: '.workflow-status-concept-link',
        datasetKey: 'conceptLinkBound'
    });
    if (body.dataset.workflowStatusActionBound === 'true') {
        return;
    }

    body.addEventListener('click', (event) => {
        const target = event.target;
        if (!target || !(target instanceof HTMLElement)) {
            return;
        }
        const groupToggle = target.closest('.workflow-status-group-toggle');
        if (groupToggle) {
            event.preventDefault();
            const workflowId = String(groupToggle.dataset.workflowId || '').trim();
            if (!workflowId) {
                return;
            }
            const currentlyExpanded = groupToggle.getAttribute('aria-expanded') === 'true';
            workflowStatusGroupUiState.collapsedByWorkflowId.set(workflowId, currentlyExpanded);
            renderWorkflowStatusBody();
            return;
        }
        const episodesButton = target.closest('.workflow-status-episodes-btn');
        if (episodesButton) {
            event.preventDefault();
            if (episodesButton.hasAttribute('disabled')) {
                return;
            }
            const workflowId = episodesButton.dataset.workflowId;
            const workflowName = episodesButton.dataset.workflowName || '';
            if (workflowId) {
                void openWorkflowEpisodesPopup(workflowId, workflowName);
            }
            return;
        }
        const copyJsonButton = target.closest('.workflow-status-copy-card-json-btn');
        if (copyJsonButton) {
            event.preventDefault();
            const workflowId = copyJsonButton.dataset.workflowId;
            const workflowName = copyJsonButton.dataset.workflowName || '';
            if (workflowId) {
                void handleCopyWorkflowDefinitionJson(workflowId, workflowName);
            }
            return;
        }
    });

    body.dataset.workflowStatusActionBound = 'true';
}

function renderWorkflowStatusBody() {
    bindWorkflowStatusConceptLinks();
    updateWorkflowStatusActionButtons();
    if (workflowStatusGroupUiState.globallyFurled) {
        const { body } = getWorkflowStatusElements();
        if (body) {
            body.innerHTML = '';
        }
        syncWorkflowCapabilityIndexPolling();
        return;
    }
    if (workflowDefinitionsState.visible) {
        renderWorkflowDefinitionsList(workflowDefinitionsState.items);
    } else {
        renderWorkflowStatusList(Array.from(workflowStatusStreamState.items.values()));
    }
    syncWorkflowCapabilityIndexPolling();
}

function mergeWorkflowStatusPayload(existingPayload, incomingPayload) {
    const existing = (existingPayload && typeof existingPayload === 'object') ? existingPayload : {};
    const incoming = (incomingPayload && typeof incomingPayload === 'object') ? incomingPayload : {};
    const existingProgress = (existing.progress && typeof existing.progress === 'object') ? existing.progress : {};
    const incomingProgress = (incoming.progress && typeof incoming.progress === 'object') ? incoming.progress : null;

    return {
        ...existing,
        ...incoming,
        progress: incomingProgress ? { ...existingProgress, ...incomingProgress } : { ...existingProgress }
    };
}

function clearWorkflowStatusLiveRefreshTimer() {
    if (!workflowStatusStreamState.liveRefreshTimeoutId) {
        return;
    }
    clearTimeout(workflowStatusStreamState.liveRefreshTimeoutId);
    workflowStatusStreamState.liveRefreshTimeoutId = null;
}

function scheduleWorkflowStatusLiveRefresh() {
    if (!shouldAutoRefreshWorkflowStatusSnapshot()) {
        return;
    }
    clearWorkflowStatusLiveRefreshTimer();
    workflowStatusStreamState.liveRefreshTimeoutId = setTimeout(() => {
        workflowStatusStreamState.liveRefreshTimeoutId = null;
        void refreshWorkflowStatusSnapshot({ silent: true, preserveRetryAttempt: true });
    }, WORKFLOW_STATUS_LIVE_REFRESH_DEBOUNCE_MS);
}

function _activeConversationContainsRequestId(requestId) {
    const cleanRequestId = String(requestId || '').trim();
    if (!cleanRequestId || !activeChatSessionId) {
        return false;
    }
    const requestCandidates = [
        activeChatRequest?.clientRequestId,
        activeChatRequest?.latestProgress?.request_id,
        lastFinishedThinkingCard?.clientRequestId,
        lastFinishedThinkingCard?.latestProgress?.request_id
    ];
    if (requestCandidates.some(value => String(value || '').trim() === cleanRequestId)) {
        return true;
    }
    for (const debugData of llmDebugData.values()) {
        if (
            debugData
            && typeof debugData === 'object'
            && String(debugData.request_id || '').trim() === cleanRequestId
        ) {
            return true;
        }
    }
    return false;
}

function _refreshLateWorkflowObservationAfterTerminalEvent(payload) {
    const status = String(payload?.status || '').trim().toLowerCase();
    const requestId = String(payload?.source_event_id || '').trim();
    const instanceId = String(payload?.instance_id || '').trim();
    if (
        payload?.source_event_type !== 'conversation_turn'
        || !['completed', 'failed', 'cancelled', 'canceled'].includes(status)
        || !requestId
        || !instanceId
        || !_activeConversationContainsRequestId(requestId)
    ) {
        return false;
    }
    const refreshKey = `${requestId}:${instanceId}:${status}`;
    if (workflowTerminalObservationRefreshKeys.has(refreshKey)) {
        return false;
    }
    workflowTerminalObservationRefreshKeys.add(refreshKey);
    if (workflowTerminalObservationRefreshKeys.size > 200) {
        const oldest = workflowTerminalObservationRefreshKeys.values().next().value;
        workflowTerminalObservationRefreshKeys.delete(oldest);
    }
    void refreshConversationSituationForSession(activeChatSessionId).then((refreshed) => {
        if (!refreshed) {
            workflowTerminalObservationRefreshKeys.delete(refreshKey);
        }
    }).catch(() => {
        workflowTerminalObservationRefreshKeys.delete(refreshKey);
    });
    return true;
}

function applyWorkflowStatusUpdate(payload) {
    if (!payload || !payload.instance_id) return;
    const existingItem = workflowStatusStreamState.items.get(payload.instance_id) || null;
    const mergedPayload = mergeWorkflowStatusPayload(existingItem, payload);
    const status = mergedPayload.status || '';
    if (!WORKFLOW_STATUS_ACTIVE.has(status)) {
        _refreshLateWorkflowObservationAfterTerminalEvent(mergedPayload);
        workflowStatusStreamState.items.delete(payload.instance_id);
        syncWorkflowStatusSnapshotNotice();
        renderWorkflowStatusBody();
        scheduleWorkflowStatusLiveRefresh();
        return;
    }
    workflowStatusStreamState.items.set(payload.instance_id, mergedPayload);
    if (
        !existingItem
        || existingItem.status !== mergedPayload.status
        || existingItem.workflow_id !== mergedPayload.workflow_id
        || !getWorkflowStatusItemUpdatedAt(mergedPayload)
    ) {
        scheduleWorkflowStatusLiveRefresh();
    }
    syncWorkflowStatusSnapshotNotice();
    renderWorkflowStatusBody();
}

async function refreshWorkflowStatusSnapshot({ silent = false, preserveRetryAttempt = false } = {}) {
    const { panel } = getWorkflowStatusElements();
    if (!panel) return;
    if (workflowStatusStreamState.loading) return;
    if (shouldDeferWorkflowStatusSnapshotRefresh({ silent })) return;

    const params = buildWorkflowStatusQuery({ includeStatusFilter: true });
    params.set('limit', '50');

    if (!preserveRetryAttempt) {
        workflowStatusStreamState.retryAttempt = 0;
        clearWorkflowStatusSnapshotRetryTimer();
    }
    workflowStatusStreamState.loading = true;
    workflowStatusStreamState.snapshotError = '';
    syncWorkflowStatusSnapshotNotice();
    renderWorkflowStatusBody();

    try {
        const resp = await fetchWithTimeout(
            `/api/workflows/instances?${params.toString()}`,
            {
                method: 'GET',
                headers: buildChatFetchHeaders(),
                timeoutMs: WORKFLOW_STATUS_SNAPSHOT_FETCH_TIMEOUT_MS
            }
        );
        const data = await resp.json().catch(() => null);
        const payload = (data && typeof data === 'object') ? data : {};
        if (!resp.ok || payload?.degraded === true) {
            const detail = (typeof payload?.detail === 'string' && payload.detail.trim())
                ? payload.detail.trim()
                : '';
            const retryable = Boolean(payload?.retryable) || resp.status === 503;
            workflowStatusStreamState.loading = false;
            if (retryable) {
                applyWorkflowStatusSnapshotRetryableState({
                    payload: {
                        ...payload,
                        status: resp.status,
                        retryable,
                        degraded: true
                    },
                    response: resp,
                    detail
                });
            } else {
                clearWorkflowStatusSnapshotRetryTimer();
                workflowStatusStreamState.retryAttempt = 0;
                workflowStatusStreamState.lastSnapshotPayload = {
                    ...payload,
                    status: resp.status,
                    retryable: false,
                    degraded: Boolean(payload?.degraded)
                };
                workflowStatusStreamState.snapshotError = detail
                    ? `Could not load workflow monitor: ${detail}`
                    : 'Could not load workflow monitor';
                syncWorkflowStatusSnapshotNotice();
            }
            renderWorkflowStatusBody();
            if (!silent) {
                console.warn('[workflowStatus] Snapshot fetch failed', {
                    status: resp.status,
                    payload: workflowStatusStreamState.lastSnapshotPayload
                });
            }
            return;
        }
        clearWorkflowStatusSnapshotRetryTimer();
        workflowStatusStreamState.retryAttempt = 0;
        const items = Array.isArray(data?.items) ? data.items : [];
        workflowStatusStreamState.items.clear();
        items.forEach((item) => {
            if (WORKFLOW_STATUS_ACTIVE.has(item.status)) {
                workflowStatusStreamState.items.set(item.instance_id, item);
            }
        });
        workflowStatusStreamState.lastSnapshotAt = Date.now();
        workflowStatusStreamState.loading = false;
        workflowStatusStreamState.snapshotError = '';
        workflowStatusStreamState.lastSnapshotPayload = payload;
        syncWorkflowStatusSnapshotNotice();
        renderWorkflowStatusBody();
    } catch (err) {
        workflowStatusStreamState.loading = false;
        applyWorkflowStatusSnapshotRetryableState({
            payload: {
                error: 'workflow_status_snapshot_failed',
                detail: err instanceof Error ? err.message : String(err || 'unknown_error'),
                retryable: true,
                degraded: true
            },
            detail: err instanceof Error ? err.message : String(err || 'unknown_error')
        });
        renderWorkflowStatusBody();
        if (!silent) {
            console.warn('[workflowStatus] Snapshot fetch failed', err);
        }
    }
}

function parseRetryAfterHeaderSeconds(headerValue) {
    if (typeof headerValue !== 'string') return null;
    const raw = headerValue.trim();
    if (!raw) return null;
    const asNumber = Number(raw);
    if (Number.isFinite(asNumber) && asNumber > 0) {
        return asNumber;
    }
    const asDateMs = Date.parse(raw);
    if (!Number.isFinite(asDateMs)) return null;
    const seconds = (asDateMs - Date.now()) / 1000;
    if (!Number.isFinite(seconds) || seconds <= 0) return null;
    return seconds;
}

function parseWorkflowDefinitionsRetryAfterSeconds(payload, response) {
    const payloadValue = Number(payload?.retry_after_seconds);
    if (Number.isFinite(payloadValue) && payloadValue > 0) {
        return payloadValue;
    }
    const headerValue = response?.headers?.get?.('Retry-After');
    const headerSeconds = parseRetryAfterHeaderSeconds(headerValue);
    if (Number.isFinite(headerSeconds) && headerSeconds > 0) {
        return headerSeconds;
    }
    return WORKFLOW_DEFINITIONS_CONTENTION_RETRY_DEFAULT_SECONDS;
}

function parseWorkflowStatusSnapshotRetryAfterSeconds(payload, response) {
    const payloadValue = Number(payload?.retry_after_seconds);
    if (Number.isFinite(payloadValue) && payloadValue > 0) {
        return payloadValue;
    }
    const headerValue = response?.headers?.get?.('Retry-After');
    const headerSeconds = parseRetryAfterHeaderSeconds(headerValue);
    if (Number.isFinite(headerSeconds) && headerSeconds > 0) {
        return headerSeconds;
    }
    return WORKFLOW_STATUS_SNAPSHOT_RETRY_DEFAULT_SECONDS;
}

function shouldAutoRefreshWorkflowStatusSnapshot() {
    const { panel } = getWorkflowStatusElements();
    if (!panel || workflowDefinitionsState.visible || workflowStatusGroupUiState.globallyFurled) return false;
    return isDocumentVisibleForRealtimeConnections();
}

function formatRetryDelaySeconds(delayMs) {
    return Math.max(0.1, Math.round((delayMs / 1000) * 10) / 10);
}

function parseWorkflowDefinitionsCacheRetryAfterSeconds(payload) {
    const cacheValue = Number(payload?.cache?.retry_after_seconds);
    if (Number.isFinite(cacheValue) && cacheValue > 0) {
        return cacheValue;
    }
    return WORKFLOW_DEFINITIONS_CONTENTION_RETRY_DEFAULT_SECONDS;
}

function formatWorkflowDefinitionsRetryDelaySeconds(delayMs) {
    return formatRetryDelaySeconds(delayMs);
}

function clearWorkflowStatusSnapshotRetryTimer() {
    if (workflowStatusStreamState.retryTimeoutId) {
        clearTimeout(workflowStatusStreamState.retryTimeoutId);
        workflowStatusStreamState.retryTimeoutId = null;
    }
}

function scheduleWorkflowStatusSnapshotRetry({ delayMs, silent = true } = {}) {
    clearWorkflowStatusSnapshotRetryTimer();
    const boundedDelay = Math.max(50, Math.round(Number(delayMs) || 0));
    workflowStatusStreamState.retryTimeoutId = setTimeout(() => {
        workflowStatusStreamState.retryTimeoutId = null;
        void refreshWorkflowStatusSnapshot({
            silent: Boolean(silent),
            preserveRetryAttempt: true
        });
    }, boundedDelay);
}

function syncWorkflowStatusSnapshotNotice() {
    if (workflowStatusStreamState.snapshotError) {
        workflowStatusStreamState.snapshotNotice = '';
        return;
    }
    if (workflowStatusStreamState.loading) {
        workflowStatusStreamState.snapshotNotice = 'Refreshing workflow monitor...';
        return;
    }
    const payload = workflowStatusStreamState.lastSnapshotPayload;
    if (!payload || payload.degraded !== true) {
        workflowStatusStreamState.snapshotNotice = '';
        return;
    }
    const retryScheduledInMs = Number(payload?.retry_scheduled_in_ms);
    const hasRetrySchedule = Number.isFinite(retryScheduledInMs) && retryScheduledInMs > 0;
    const hasItems = workflowStatusStreamState.items.size > 0;
    if (hasItems) {
        workflowStatusStreamState.snapshotNotice = hasRetrySchedule
            ? `Workflow monitor snapshot unavailable; showing live updates while retrying in ${formatRetryDelaySeconds(retryScheduledInMs)}s...`
            : 'Workflow monitor snapshot unavailable; showing live updates from the stream.';
        return;
    }
    workflowStatusStreamState.snapshotNotice = hasRetrySchedule
        ? `Workflow monitor temporarily unavailable; retrying in ${formatRetryDelaySeconds(retryScheduledInMs)}s...`
        : 'Workflow monitor temporarily unavailable. Press Refresh to try again.';
}

function applyWorkflowStatusSnapshotRetryableState({ payload, response, detail = '' } = {}) {
    const attempt = Math.max(1, workflowStatusStreamState.retryAttempt + 1);
    const retryAfterSeconds = parseWorkflowStatusSnapshotRetryAfterSeconds(payload, response);
    const retryAfterMs = Math.max(0, Math.round(Number(retryAfterSeconds) * 1000) || 0);
    const exponentialDelayMs = Math.min(
        WORKFLOW_STATUS_SNAPSHOT_RETRY_BASE_MS * (2 ** (attempt - 1)),
        WORKFLOW_STATUS_SNAPSHOT_RETRY_MAX_MS
    );
    const retryDelayMs = Math.max(exponentialDelayMs, retryAfterMs);
    // Keep retrying while the monitor remains visible; the capped delay avoids
    // aggressive polling during extended transient store contention.
    const shouldRetry = shouldAutoRefreshWorkflowStatusSnapshot();

    workflowStatusStreamState.retryAttempt = attempt;
    workflowStatusStreamState.snapshotError = '';
    workflowStatusStreamState.lastSnapshotPayload = {
        ...(payload && typeof payload === 'object' ? payload : {}),
        detail: detail || payload?.detail || null,
        retryable: true,
        degraded: true,
        retry_attempt: attempt,
        retry_scheduled_in_ms: shouldRetry ? retryDelayMs : null
    };

    if (shouldRetry) {
        scheduleWorkflowStatusSnapshotRetry({ delayMs: retryDelayMs, silent: true });
    } else {
        clearWorkflowStatusSnapshotRetryTimer();
    }
    syncWorkflowStatusSnapshotNotice();
}

function clearWorkflowDefinitionsRetryTimer() {
    if (workflowDefinitionsState.retryTimeoutId) {
        clearTimeout(workflowDefinitionsState.retryTimeoutId);
        workflowDefinitionsState.retryTimeoutId = null;
    }
}

function scheduleWorkflowDefinitionsRetry({ delayMs, silent = true } = {}) {
    if (workflowStatusGroupUiState.globallyFurled) {
        clearWorkflowDefinitionsRetryTimer();
        return;
    }
    clearWorkflowDefinitionsRetryTimer();
    const boundedDelay = Math.max(50, Math.round(Number(delayMs) || 0));
    workflowDefinitionsState.retryTimeoutId = setTimeout(() => {
        workflowDefinitionsState.retryTimeoutId = null;
        void refreshAvailableWorkflowDefinitions({ silent: Boolean(silent) });
    }, boundedDelay);
}

function applyWorkflowDefinitionsRetryableState({
    nextRetryAttempt,
    retryAfterSeconds = 0,
    maxAttempts,
    baseDelayMs,
    maxDelayMs,
    pendingMessage,
    exhaustedMessage,
    exhaustedKind = 'notice',
    payload
} = {}) {
    const attempt = Math.max(1, Math.round(Number(nextRetryAttempt) || 1));
    const boundedBaseDelayMs = Math.max(50, Math.round(Number(baseDelayMs) || 0));
    const boundedMaxDelayMs = Math.max(
        boundedBaseDelayMs,
        Math.round(Number(maxDelayMs) || boundedBaseDelayMs)
    );
    const retryAfterMs = Math.max(0, Math.round(Number(retryAfterSeconds) * 1000) || 0);
    const exponentialDelayMs = Math.min(
        boundedBaseDelayMs * (2 ** (attempt - 1)),
        boundedMaxDelayMs
    );
    const retryDelayMs = Math.max(exponentialDelayMs, retryAfterMs);
    const retryEligible = attempt <= Math.max(1, Math.round(Number(maxAttempts) || 1));
    const shouldRetry = retryEligible && !workflowStatusGroupUiState.globallyFurled;
    const retryDelaySecondsRounded = formatWorkflowDefinitionsRetryDelaySeconds(retryDelayMs);

    workflowDefinitionsState.retryAttempt = attempt;
    workflowDefinitionsState.error = '';
    workflowDefinitionsState.notice = '';
    if (shouldRetry) {
        workflowDefinitionsState.notice = pendingMessage(retryDelaySecondsRounded);
        scheduleWorkflowDefinitionsRetry({ delayMs: retryDelayMs, silent: true });
    } else {
        clearWorkflowDefinitionsRetryTimer();
        if (exhaustedKind === 'error') {
            workflowDefinitionsState.error = exhaustedMessage;
        } else {
            workflowDefinitionsState.notice = exhaustedMessage;
        }
    }

    workflowDefinitionsState.lastPayload = {
        ...(payload && typeof payload === 'object' ? payload : {}),
        retryable: retryEligible,
        retry_attempt: attempt,
        retry_scheduled_in_ms: shouldRetry ? retryDelayMs : null
    };
}

async function refreshAvailableWorkflowDefinitions({ silent = false } = {}) {
    const { panel } = getWorkflowStatusElements();
    if (!panel) return;
    if (workflowDefinitionsState.loading) return;
    clearWorkflowDefinitionsRetryTimer();

    const now = Date.now();
    if (
        silent
        && Number.isFinite(workflowDefinitionsState.lastFetchedAt)
        && workflowDefinitionsState.lastFetchedAt > 0
        && workflowDefinitionsState.cacheState !== 'stale'
        && (now - workflowDefinitionsState.lastFetchedAt) < WORKFLOW_DEFINITIONS_SILENT_REFRESH_COOLDOWN_MS
    ) {
        return;
    }

    workflowDefinitionsState.loading = true;
    workflowDefinitionsState.error = '';
    workflowDefinitionsState.notice = '';
    if (workflowDefinitionsState.visible) {
        renderWorkflowStatusBody();
    }

    const params = buildWorkflowStatusQuery();
    params.set('limit', '200');
    workflowDefinitionsState.lastRequestQuery = params.toString();

    try {
        const resp = await fetchWithTimeout(
            `/api/workflows/definitions?${params.toString()}`,
            {
                method: 'GET',
                headers: buildChatFetchHeaders(),
                timeoutMs: WORKFLOW_DEFINITIONS_FETCH_TIMEOUT_MS
            }
        );
        const responsePayload = await resp.json().catch(() => null);
        if (!resp.ok) {
            const responseError = typeof responsePayload?.error === 'string'
                ? responsePayload.error.trim()
                : '';
            if (responseError === 'workflow_definitions_refresh_in_progress') {
                const retryAfterSeconds = parseWorkflowDefinitionsRetryAfterSeconds(responsePayload, resp);
                applyWorkflowDefinitionsRetryableState({
                    nextRetryAttempt: workflowDefinitionsState.retryAttempt + 1,
                    retryAfterSeconds,
                    maxAttempts: WORKFLOW_DEFINITIONS_CONTENTION_RETRY_MAX_ATTEMPTS,
                    baseDelayMs: WORKFLOW_DEFINITIONS_CONTENTION_RETRY_BASE_MS,
                    maxDelayMs: WORKFLOW_DEFINITIONS_CONTENTION_RETRY_MAX_MS,
                    pendingMessage: (delaySeconds) => `Workflow definitions are refreshing, retrying in ${delaySeconds}s...`,
                    exhaustedMessage: 'Workflow definitions are still refreshing. Press Refresh to try again.',
                    exhaustedKind: 'notice',
                    payload: {
                        error: 'workflow_definitions_refresh_in_progress',
                        detail: (typeof responsePayload?.detail === 'string' && responsePayload.detail.trim())
                            ? responsePayload.detail.trim()
                            : 'Workflow definitions refresh is already running; retry shortly.',
                        retry_after_seconds: retryAfterSeconds,
                        status: resp.status,
                        request_query: workflowDefinitionsState.lastRequestQuery || null
                    }
                });
                if (!silent) {
                    console.info('[workflowStatus] Workflow definitions refresh contention', workflowDefinitionsState.lastPayload);
                }
                return;
            }
            const detail = (typeof responsePayload?.detail === 'string' && responsePayload.detail.trim())
                ? responsePayload.detail.trim()
                : '';
            const err = new Error(detail ? `HTTP ${resp.status}: ${detail}` : `HTTP ${resp.status}`);
            err.name = 'WorkflowDefinitionsHttpError';
            err.status = resp.status;
            err.responsePayload = responsePayload;
            throw err;
        }
        const data = (responsePayload && typeof responsePayload === 'object') ? responsePayload : {};
        workflowDefinitionsState.lastPayload = (data && typeof data === 'object') ? data : null;
        workflowDefinitionsState.items = Array.isArray(data?.items) ? data.items : [];
        workflowDefinitionsState.lastFetchedAt = Date.now();
        workflowDefinitionsState.error = '';
        workflowDefinitionsState.notice = '';
        // Keep an embedded capability projection in the definitions snapshot for
        // diagnostics only. Definitions are actor-scoped and may complete after
        // the browser actor changes, so they must not publish shared display
        // status. The canonical capability-status coordinator is the sole
        // authority for the footer, Settings card, and workflow monitor warning.
        workflowDefinitionsState.cacheState = (
            typeof data?.cache?.state === 'string' && data.cache.state.trim() === 'stale'
        ) ? 'stale' : 'fresh';
        if (workflowDefinitionsState.cacheState === 'stale' && data?.cache?.refresh_in_progress) {
            applyWorkflowDefinitionsRetryableState({
                nextRetryAttempt: workflowDefinitionsState.retryAttempt + 1,
                retryAfterSeconds: parseWorkflowDefinitionsCacheRetryAfterSeconds(data),
                maxAttempts: WORKFLOW_DEFINITIONS_CONTENTION_RETRY_MAX_ATTEMPTS,
                baseDelayMs: WORKFLOW_DEFINITIONS_CONTENTION_RETRY_BASE_MS,
                maxDelayMs: WORKFLOW_DEFINITIONS_CONTENTION_RETRY_MAX_MS,
                pendingMessage: (delaySeconds) => (
                    `Showing cached workflow definitions while the monitor refreshes in the background. Retrying in ${delaySeconds}s...`
                ),
                exhaustedMessage: 'Showing cached workflow definitions. Press Refresh to check again.',
                exhaustedKind: 'notice',
                payload: {
                    ...data,
                    detail: 'Showing cached workflow definitions while a background refresh completes.',
                    request_query: workflowDefinitionsState.lastRequestQuery || null
                }
            });
            return;
        }
        workflowDefinitionsState.retryAttempt = 0;
        clearWorkflowDefinitionsRetryTimer();
    } catch (err) {
        const isAbortError = err && typeof err === 'object' && err.name === 'AbortError';
        const status = Number.isFinite(Number(err?.status)) ? Number(err.status) : null;
        const responsePayload = (err?.responsePayload && typeof err.responsePayload === 'object')
            ? err.responsePayload
            : null;
        const responseDetail = (typeof responsePayload?.detail === 'string' && responsePayload.detail.trim())
            ? responsePayload.detail.trim()
            : '';
        if (isAbortError) {
            const hasItems = Array.isArray(workflowDefinitionsState.items) && workflowDefinitionsState.items.length > 0;
            applyWorkflowDefinitionsRetryableState({
                nextRetryAttempt: workflowDefinitionsState.retryAttempt + 1,
                retryAfterSeconds: 0,
                maxAttempts: WORKFLOW_DEFINITIONS_TIMEOUT_RETRY_MAX_ATTEMPTS,
                baseDelayMs: WORKFLOW_DEFINITIONS_TIMEOUT_RETRY_BASE_MS,
                maxDelayMs: WORKFLOW_DEFINITIONS_TIMEOUT_RETRY_MAX_MS,
                pendingMessage: (delaySeconds) => (
                    hasItems
                        ? `Showing last loaded workflow definitions while the request catches up. Retrying in ${delaySeconds}s...`
                        : `Workflow definitions are taking longer than expected. Retrying in ${delaySeconds}s...`
                ),
                exhaustedMessage: hasItems
                    ? 'Showing last loaded workflow definitions. Press Refresh to try again.'
                    : 'Workflow definitions request timed out. Please retry.',
                exhaustedKind: hasItems ? 'notice' : 'error',
                payload: {
                    error: 'workflow_definitions_request_timed_out',
                    detail: `Request timed out after ${Math.round(WORKFLOW_DEFINITIONS_FETCH_TIMEOUT_MS / 1000)}s`,
                    status,
                    response_payload: responsePayload,
                    request_query: workflowDefinitionsState.lastRequestQuery || null
                }
            });
        } else {
            workflowDefinitionsState.error = responseDetail
                ? `Could not load available workflows: ${responseDetail}`
                : 'Could not load available workflows';
            workflowDefinitionsState.notice = '';
            workflowDefinitionsState.retryAttempt = 0;
            workflowDefinitionsState.cacheState = workflowDefinitionsState.items.length
                ? workflowDefinitionsState.cacheState
                : 'none';
            clearWorkflowDefinitionsRetryTimer();
            workflowDefinitionsState.lastPayload = {
                error: (typeof responsePayload?.error === 'string' && responsePayload.error.trim())
                    ? responsePayload.error.trim()
                    : 'workflow_definitions_fetch_failed',
                detail: responseDetail || (err instanceof Error ? err.message : String(err || 'unknown_error')),
                status,
                retryable: false,
                response_payload: responsePayload,
                request_query: workflowDefinitionsState.lastRequestQuery || null
            };
        }
        if (!silent) {
            console.warn('[workflowStatus] Available workflow fetch failed', err);
        }
    } finally {
        workflowDefinitionsState.loading = false;
        if (workflowDefinitionsState.visible) {
            renderWorkflowStatusBody();
        }
    }
}

function stopWorkflowStatusStream(source = 'workflow_stream_stopped') {
    clearWorkflowStatusLiveRefreshTimer();
    if (workflowStatusStreamState.reconnectTimeoutId) {
        clearTimeout(workflowStatusStreamState.reconnectTimeoutId);
        workflowStatusStreamState.reconnectTimeoutId = null;
    }
    if (workflowStatusStreamState.eventSource) {
        workflowStatusStreamState.eventSource.close();
        workflowStatusStreamState.eventSource = null;
    }
    publishRealtimeConnectionTelemetry(source);
}

function scheduleWorkflowStatusReconnect() {
    if (!shouldMaintainWorkflowStatusStream()) {
        workflowStatusStreamState.reconnectAttempts = 0;
        publishRealtimeConnectionTelemetry('workflow_stream_reconnect_skipped');
        return;
    }
    if (workflowStatusStreamState.reconnectTimeoutId) return;
    workflowStatusStreamState.reconnectAttempts += 1;
    const delay = Math.min(
        WORKFLOW_STATUS_RECONNECT_BASE_MS * Math.pow(2, workflowStatusStreamState.reconnectAttempts - 1),
        WORKFLOW_STATUS_RECONNECT_MAX_MS
    );
    workflowStatusStreamState.reconnectTimeoutId = setTimeout(() => {
        workflowStatusStreamState.reconnectTimeoutId = null;
        startWorkflowStatusStream();
    }, delay);
    publishRealtimeConnectionTelemetry('workflow_stream_reconnect_scheduled');
}

function startWorkflowStatusStream() {
    if (!shouldMaintainWorkflowStatusStream()) {
        stopWorkflowStatusStream('workflow_stream_not_started_visibility');
        return;
    }

    stopWorkflowStatusStream('workflow_stream_restart');

    const params = buildWorkflowStatusStreamQuery();
    const url = `/api/workflows/instances/stream?${params.toString()}`;
    const eventSource = new EventSource(url);
    workflowStatusStreamState.eventSource = eventSource;
    publishRealtimeConnectionTelemetry('workflow_stream_started');

    eventSource.onopen = () => {
        workflowStatusStreamState.reconnectAttempts = 0;
        scheduleWorkflowStatusLiveRefresh();
        publishRealtimeConnectionTelemetry('workflow_stream_open');
    };

    eventSource.onerror = () => {
        if (workflowStatusStreamState.eventSource !== eventSource) return;
        if (eventSource.readyState === EventSource.CLOSED) {
            eventSource.close();
            workflowStatusStreamState.eventSource = null;
            publishRealtimeConnectionTelemetry('workflow_stream_closed_remote');
            scheduleWorkflowStatusReconnect();
        }
    };

    eventSource.addEventListener('workflow_status', (event) => {
        let payload;
        try {
            payload = JSON.parse(event.data);
        } catch (err) {
            console.warn('[workflowStatus] Failed to parse event', err);
            return;
        }
        applyWorkflowStatusUpdate(payload);
    });
}

function initializeWorkflowStatusPanel() {
    const {
        panel,
        refreshButton,
        toggleAvailableButton,
        furlToggleButton,
        showDesignsCheckbox,
        copyJsonButton
    } = getWorkflowStatusElements();
    if (!panel) return;
    if (workflowStatusPanelInitialised) return;
    workflowStatusPanelInitialised = true;
    ensureWorkflowCapabilityIndexStatusSubscription();
    // Keep the diagnostic surface compact on first load; users can unfurl it
    // when they need the full operational detail.
    workflowStatusGroupUiState.globallyFurled = true;
    const {
        closeButton: closeEpisodesButton,
        copyJsonButton: copyEpisodesJsonButton
    } = getWorkflowEpisodesElements();

    updateWorkflowStatusActionButtons();

    if (showDesignsCheckbox) {
        showDesignsCheckbox.checked = Boolean(workflowDefinitionsState.showDesigns);
        if (showDesignsCheckbox.dataset.bound !== 'true') {
            showDesignsCheckbox.dataset.bound = 'true';
            showDesignsCheckbox.addEventListener('change', () => {
                workflowDefinitionsState.showDesigns = Boolean(showDesignsCheckbox.checked);
                if (workflowDefinitionsState.visible) {
                    renderWorkflowStatusBody();
                }
            });
        }
    }

    if (closeEpisodesButton && closeEpisodesButton.dataset.bound !== 'true') {
        closeEpisodesButton.addEventListener('click', () => {
            setWorkflowEpisodesPopupVisible(false);
        });
        closeEpisodesButton.dataset.bound = 'true';
    }

    if (copyEpisodesJsonButton && copyEpisodesJsonButton.dataset.bound !== 'true') {
        copyEpisodesJsonButton.addEventListener('click', () => {
            void handleCopyWorkflowEpisodesJson();
        });
        copyEpisodesJsonButton.dataset.bound = 'true';
    }

    if (refreshButton && refreshButton.dataset.bound !== 'true') {
        refreshButton.addEventListener('click', () => {
            void refreshWorkflowCapabilityIndexStatus({ silent: true, force: true });
            if (workflowDefinitionsState.visible) {
                void refreshAvailableWorkflowDefinitions();
                return;
            }
            void refreshWorkflowStatusSnapshot();
        });
        refreshButton.dataset.bound = 'true';
    }

    if (furlToggleButton && furlToggleButton.dataset.bound !== 'true') {
        furlToggleButton.addEventListener('click', () => {
            setWorkflowMonitorGloballyFurled(
                !workflowStatusGroupUiState.globallyFurled
            );
        });
        furlToggleButton.dataset.bound = 'true';
    }

    if (copyJsonButton) {
        copyJsonButton.classList.add('workflow-status-copy-json-btn');
        if (copyJsonButton.dataset.bound !== 'true') {
            copyJsonButton.dataset.bound = 'true';
            copyJsonButton.addEventListener('click', () => {
                void handleCopyWorkflowMonitorJson();
            });
        }
    }

    if (toggleAvailableButton && toggleAvailableButton.dataset.bound !== 'true') {
        toggleAvailableButton.addEventListener('click', () => {
            workflowDefinitionsState.visible = !workflowDefinitionsState.visible;
            updateWorkflowStatusActionButtons();
            void refreshWorkflowCapabilityIndexStatus({ silent: true });

            if (workflowDefinitionsState.visible) {
                clearWorkflowStatusSnapshotRetryTimer();
                void refreshAvailableWorkflowDefinitions({ silent: true });
            } else {
                clearWorkflowDefinitionsRetryTimer();
                renderWorkflowStatusBody();
                void refreshWorkflowStatusSnapshot({ silent: true });
            }
        });
        toggleAvailableButton.dataset.bound = 'true';
    }

    startWorkflowStatusStream();
    void refreshWorkflowCapabilityIndexStatus({ silent: true });
    void refreshWorkflowStatusSnapshot({ silent: true });
}

function startIncomingInvitePolling() {
    if (!isDocumentVisibleForRealtimeConnections()) {
        return;
    }
    if (incomingInvitePollTimerId) return;
    incomingInvitePollTimerId = window.setInterval(() => {
        void loadIncomingInvites({ silent: true });
    }, INCOMING_INVITE_POLL_INTERVAL_MS);
    publishRealtimeConnectionTelemetry('incoming_invite_polling_started');
}

function stopIncomingInvitePolling() {
    if (!incomingInvitePollTimerId) return;
    clearInterval(incomingInvitePollTimerId);
    incomingInvitePollTimerId = null;
    publishRealtimeConnectionTelemetry('incoming_invite_polling_stopped');
}

function startSharedSessionBadgePolling() {
    if (!shouldRunSharedSessionBadgePolling()) {
        return;
    }
    if (sharedSessionBadgePollTimerId) return;
    sharedSessionBadgePollTimerId = window.setInterval(() => {
        if (!shouldRunSharedSessionBadgePolling()) {
            return;
        }
        // Keep shared conversation unread badges eventually consistent even when
        // SSE is paused for inactive/hidden sessions.
        scheduleChatSessionTabsRefresh();
    }, SHARED_SESSION_BADGE_POLL_INTERVAL_MS);
    publishRealtimeConnectionTelemetry('shared_session_badge_polling_started');
}

function stopSharedSessionBadgePolling() {
    if (!sharedSessionBadgePollTimerId) return;
    clearInterval(sharedSessionBadgePollTimerId);
    sharedSessionBadgePollTimerId = null;
    publishRealtimeConnectionTelemetry('shared_session_badge_polling_stopped');
}

function handleRealtimeConnectionsVisibilityChange() {
    const visible = isDocumentVisibleForRealtimeConnections();
    if (!visible) {
        closeSharedConversationStream();
        stopWorkflowStatusStream('workflow_stream_stopped_visibility_hidden');
        clearWorkflowStatusSnapshotRetryTimer();
        stopIncomingInvitePolling();
        stopSharedSessionBadgePolling();
        stopChatPromptQueuePolling();
        try {
            incomingInviteAbortController?.abort();
        } catch (_) {
            // Ignore abort race.
        }
        publishRealtimeConnectionTelemetry('document_hidden');
        return;
    }

    syncSharedConversationStreams();
    startWorkflowStatusStream();
    startIncomingInvitePolling();
    startSharedSessionBadgePolling();
    scheduleChatSessionTabsRefresh(true);
    void loadIncomingInvites({ silent: true });
    void refreshWorkflowStatusSnapshot({ silent: true });
    void refreshChatPromptQueueFromServer({ silent: true });
    publishRealtimeConnectionTelemetry('document_visible');
}

function invalidateLlmExecutionContextForOrgSwitch() {
    return synchroniseLlmExecutionContext({ force: true, reason: 'organisation_context_changed' });
}

function detachChatWorkForOrganisationSwitch() {
    const liveRequests = Array.from(new Set(liveChatRequestsBySession.values()));
    liveChatRequestsBySession.clear();
    finishedThinkingCardsBySession.clear();
    activeChatRequest = null;
    lastFinishedThinkingCard = null;
    liveRequests.forEach((request) => {
        request.detachedForOrganisationSwitch = true;
        request.foregroundDeliveryCompleted = true;
        stopToolUseProgressPolling(request);
        stopThinkingTooltipTicker(request);
        stopForegroundTaskResultPolling(request);
        try {
            request.abortController?.abort();
        } catch (_) {
            // The durable server task, if already admitted, remains recoverable.
        }
    });

    queuedChatPrompts = [];
    stopChatPromptQueuePolling();
    queuedChatPromptClaimsInFlight.clear();
    queuedChatPromptSubmissionsInFlight.clear();
    chatPromptQueueAdmissionServerInstanceId = null;
    for (const timer of queuedChatPromptSyncTimers.values()) {
        clearTimeout(timer);
    }
    queuedChatPromptSyncTimers.clear();
    selectedChatPromptQueueEntryId = null;
    locallyHiddenChatPromptQueueEntryKeys.clear();
    renderChatTaskQueuePanel();
    refreshChatSessionTabActivityIndicators();
    updateSendButtonForCurrentChatState();
}

function startOrganisationSwitchForChatTab(detail = {}) {
    const requestedSwitchId = normaliseOrganisationSwitchId(detail);
    if (requestedSwitchId && pendingChatOrganisationSwitchId === requestedSwitchId) {
        return chatOrganisationGeneration;
    }

    chatOrganisationGeneration += 1;
    pendingChatOrganisationSwitchId = requestedSwitchId || `implicit-org-switch-${chatOrganisationGeneration}`;

    // Clear actor- and organisation-scoped state synchronously, before the
    // server switch completes.  Network aborts reduce wasted work; generation
    // checks remain the authority fence for responses which still complete.
    invalidateLlmExecutionContextForOrgSwitch();
    detachChatWorkForOrganisationSwitch();
    cancelActiveChatSessionSwitch('organisation_switch');
    cancelChatConceptMetaHydration();
    abortActiveHistoryRequest();
    abortChatSessionTabsFetches();
    try {
        chatSessionLinksLoadInFlight?.abortController?.abort?.();
    } catch (_) {
        // Ignore abort races.
    }
    chatSessionLinksLoadInFlight = null;
    const inviteController = incomingInviteAbortController;
    incomingInviteAbortController = null;
    incomingInviteLoadInFlight = false;
    try {
        inviteController?.abort();
    } catch (_) {
        // Ignore abort races.
    }

    if (pendingSessionTabsRefresh) {
        clearTimeout(pendingSessionTabsRefresh);
        pendingSessionTabsRefresh = null;
    }
    lastSessionTabsRefreshMs = 0;

    const container = getChatSessionTabsContainer();
    sessionTabsCache = [];
    sessionHistoryCache.clear();
    chatSessionLinksCache.clear();
    chatSessionFocusCache.clear();
    expandedConversationHistoryLimit = null;
    expandedConversationHistoryBaseLimit = null;
    lastRenderedSessionCount = 0;
    chatSessionMetadataOpenKey = null;
    _clearChatSessionMetadata();
    _clearConversationSituationState({ closePanel: true });

    transcriptTurns.length = 0;
    turnEditHistory.clear();
    clearLlmDebugDataEntries();
    setActiveChatSession(null, null);
    displayedHistorySessionId = null;
    historySegmentsShown = 0;
    totalHistorySegments = 0;
    clearHistoryLoadState();
    updateHistoryBanner();

    incomingInviteState = { invites: [], acceptedInvites: [], totalCount: 0 };
    setIncomingInviteBadge(0);
    setIncomingInviteStatus('');
    void renderIncomingInvitesList();

    sharedConversationUnreadSessions.clear();
    sharedConversationLastHistoryIndex.clear();
    sharedConversationResyncInFlight.clear();
    seenSharedTurnIds.clear();
    clearLatestUnreadBoundary();
    hideNewSharedMessagesIndicator();

    const scrollableField = document.getElementById('scrollableField');
    if (scrollableField) {
        scrollableField.innerHTML = '<div class="chat-session-loading">Loading conversations...</div>';
    }

    closeSharedConversationStream();
    stopIncomingInvitePolling();
    stopSharedSessionBadgePolling();
    stopWorkflowStatusStream('workflow_stream_stopped_org_switch');
    clearWorkflowStatusSnapshotRetryTimer();
    workflowStatusStreamState.items.clear();
    workflowStatusStreamState.loading = false;
    workflowStatusStreamState.retryAttempt = 0;
    workflowStatusStreamState.snapshotError = '';
    workflowStatusStreamState.snapshotNotice = '';
    workflowStatusStreamState.lastSnapshotPayload = null;
    renderWorkflowStatusBody();

    if (container) {
        renderChatSessionTabsPlaceholder('loading');
        container.hidden = false;
    }

    publishRealtimeConnectionTelemetry('org_switch_started');
    return chatOrganisationGeneration;
}

function finishOrganisationSwitchRecovery() {
    startIncomingInvitePolling();
    startSharedSessionBadgePolling();
    void loadIncomingInvites({ silent: true });
    startWorkflowStatusStream();
    void refreshWorkflowStatusSnapshot({ silent: true });
    syncSharedConversationStreams();
    void refreshChatPromptQueueFromServer({ silent: true });
}

async function handleOrgSwitchForChatTab(detail = {}) {
    const acceptedSwitchId = normaliseOrganisationSwitchId(detail);
    if (
        acceptedSwitchId
        && pendingChatOrganisationSwitchId
        && acceptedSwitchId !== pendingChatOrganisationSwitchId
    ) {
        return false;
    }

    if (pendingChatOrganisationSwitchId === null) {
        startOrganisationSwitchForChatTab(detail);
    }
    const organisationGeneration = chatOrganisationGeneration;
    pendingChatOrganisationSwitchId = null;
    const scrollableField = document.getElementById('scrollableField');

    // Wait for session tabs to refresh (loads sessions for new org)
    await refreshChatSessionTabs();
    if (!isChatOrganisationRequestCurrent(organisationGeneration)) {
        return false;
    }

    // Always reload the accepted organisation's active conversation. Session
    // identifiers are not used as proof that cached content has the same scope.
    if (activeChatSessionId) {
        console.log('[chatTab] Org switch: loading history for new session', {
            new_session: activeChatSessionId
        });
        void switchToChatSession(activeChatSessionId);
    } else if (!activeChatSessionId) {
        // No sessions in new org - clear the loading message
        if (scrollableField) {
            scrollableField.innerHTML = '';
        }
    }

    finishOrganisationSwitchRecovery();
    publishRealtimeConnectionTelemetry('org_switch_completed');
    return true;
}

async function handleOrgSwitchFailureForChatTab(detail = {}) {
    const failedSwitchId = normaliseOrganisationSwitchId(detail);
    if (
        failedSwitchId
        && pendingChatOrganisationSwitchId
        && failedSwitchId !== pendingChatOrganisationSwitchId
    ) {
        return false;
    }
    if (pendingChatOrganisationSwitchId === null) {
        return false;
    }

    const organisationGeneration = chatOrganisationGeneration;
    pendingChatOrganisationSwitchId = null;
    await refreshChatSessionTabs();
    if (!isChatOrganisationRequestCurrent(organisationGeneration)) {
        return false;
    }

    const scrollableField = document.getElementById('scrollableField');
    if (activeChatSessionId) {
        void switchToChatSession(activeChatSessionId);
    } else if (scrollableField) {
        scrollableField.innerHTML = '';
    }
    finishOrganisationSwitchRecovery();
    publishRealtimeConnectionTelemetry('org_switch_failed_recovered');
    return true;
}

try {
    window.refreshChatSessionTabsForOrgSwitch = () => {
        return handleOrgSwitchForChatTab({});
    };
} catch (_) {
    // ignore
}

function handleAuthStatusChangeForChatTab(detail) {
    synchroniseLlmExecutionContext({ force: true, reason: 'authenticated_actor_changed' });
    loadHiddenChatSessionIds();
    loadPinnedChatSessionIds();
    loadAgentCreatedSessionsVisibilityPreference();
    loadChatSessionLastAccessedMap();
    loadChatSessionTabsLayoutPreference();
    setupChatSessionTabsResponsiveLayout();
    const container = getChatSessionTabsContainer();
    sessionTabsCache = [];
    expandedConversationHistoryLimit = null;
    expandedConversationHistoryBaseLimit = null;
    lastRenderedSessionCount = 0;
    chatSessionMetadataOpenKey = null;
    _clearChatSessionMetadata();
    _clearConversationSituationState({ closePanel: true });

    if (container) {
        renderChatSessionTabsPlaceholder(detail?.authenticated ? 'loading' : 'unauthenticated');
        container.hidden = false;
    }

    closeSharedConversationStream();
    stopWorkflowStatusStream('workflow_stream_stopped_auth_change');
    clearWorkflowStatusSnapshotRetryTimer();
    workflowStatusStreamState.items.clear();
    workflowStatusStreamState.loading = false;
    workflowStatusStreamState.retryAttempt = 0;
    workflowStatusStreamState.snapshotError = '';
    workflowStatusStreamState.snapshotNotice = '';
    workflowStatusStreamState.lastSnapshotPayload = null;
    renderWorkflowStatusBody();

    if (detail?.authenticated !== false) {
        startWorkflowStatusStream();
        void refreshWorkflowStatusSnapshot({ silent: true });
        startIncomingInvitePolling();
        startSharedSessionBadgePolling();
        void refreshChatPromptQueueFromServer({ silent: true });
    } else {
        stopIncomingInvitePolling();
        stopSharedSessionBadgePolling();
        stopChatPromptQueuePolling();
        queuedChatPrompts = [];
        queuedChatPromptSubmissionsInFlight.clear();
        selectedChatPromptQueueEntryId = null;
        locallyHiddenChatPromptQueueEntryKeys.clear();
        renderChatTaskQueuePanel();
        refreshChatSessionTabActivityIndicators();
        updateSendButtonForCurrentChatState();
    }

    scheduleChatSessionTabsRefresh(true);
    void loadIncomingInvites({ silent: true });
    publishRealtimeConnectionTelemetry('auth_status_changed');
}

export function initializeChatTab() {
    if (chatTabInitialised) {
        console.warn('[chatTab] initializeChatTab called more than once; skipping duplicate initialisation.');
        return;
    }
    chatTabInitialised = true;
    console.log("Initializing chat tab...");
    bindFocusedConversationEvents();

    if (!document.__vonConversationRuntimeCostRuntimeListenerBound) {
        document.__vonConversationRuntimeCostRuntimeListenerBound = true;
        document.addEventListener('von:runtimeIdentityUpdated', (event) => {
            handleConversationRuntimeIdentityUpdate(event?.detail);
        });
    }

    // JVNAUTOSCI-1014: Load hidden session IDs from localStorage (user-scoped)
    loadHiddenChatSessionIds();
    loadPinnedChatSessionIds();
    loadAgentCreatedSessionsVisibilityPreference();
    loadChatSessionLastAccessedMap();
    loadChatSessionTabsLayoutPreference();
    setupChatSessionTabsResponsiveLayout();

    if (!conversationSearchSelectionListenerBound) {
        conversationSearchSelectionListenerBound = true;
        document.addEventListener('von:open-conversation-search-result', event => {
            void openConversationSearchResult(event?.detail?.conversation || {});
        });
        document.addEventListener('von:conversation-trash-changed', event => {
            if (event?.detail?.action === 'restored') {
                scheduleChatSessionTabsRefresh(true);
            }
        });
    }

    // Reload hidden sessions when user changes (settings change event)
    try {
        document.addEventListener('von:settingsChanged', () => {
            // Model and actor controls share this event. Invalidate the display
            // snapshot immediately; retained debug data remains available for
            // diagnostics and will be rebound only when current history loads.
            synchroniseLlmExecutionContext({ force: true, reason: 'settings_context_changed' });
            const newHiddenKey = getHiddenSessionsStorageKey();
            const newPinnedKey = getPinnedSessionsStorageKey();
            const newAgentCreatedVisibilityKey = getAgentCreatedSessionsVisibleStorageKey();
            const newAccessKey = getChatSessionLastAccessedStorageKey();
            let shouldRerenderTabs = false;

            if (newHiddenKey !== _hiddenSessionsUserKey) {
                console.log(`[chatTab] User changed, reloading hidden sessions (${_hiddenSessionsUserKey} -> ${newHiddenKey})`);
                loadHiddenChatSessionIds();
                shouldRerenderTabs = true;
            }

            if (newAccessKey !== _chatSessionLastAccessedUserKey) {
                console.log(`[chatTab] User changed, reloading conversation last-accessed map (${_chatSessionLastAccessedUserKey} -> ${newAccessKey})`);
                loadChatSessionLastAccessedMap();
                shouldRerenderTabs = true;
            }

            if (newPinnedKey !== _pinnedSessionsUserKey) {
                console.log(`[chatTab] User changed, reloading pinned sessions (${_pinnedSessionsUserKey} -> ${newPinnedKey})`);
                loadPinnedChatSessionIds();
                shouldRerenderTabs = true;
            }

            if (newAgentCreatedVisibilityKey !== _agentCreatedSessionsVisibleUserKey) {
                console.log(`[chatTab] User changed, reloading test conversation visibility (${_agentCreatedSessionsVisibleUserKey} -> ${newAgentCreatedVisibilityKey})`);
                loadAgentCreatedSessionsVisibilityPreference();
                shouldRerenderTabs = true;
            }

            if (shouldRerenderTabs && Array.isArray(sessionTabsCache)) {
                renderChatSessionTabs(sessionTabsCache, activeChatSessionId);
            }
        });
    } catch (_) {
        // Ignore in test environments
    }

    const sendButton = document.getElementById('sendButton');
    const resetButton = document.getElementById('resetButton');
    const promptInput = document.getElementById('promptInput');
    const scrollableField = document.getElementById('scrollableField');
    const annotationToggle = document.getElementById('annotationToggle');
    const dictateButton = document.getElementById('dictateButton');
    const ttsToggle = document.getElementById('ttsToggle');
    const exportConversationJsonBtn = document.getElementById('exportConversationJsonBtn');
    const copyConversationInfoJsonBtn = document.getElementById(CONVERSATION_INFO_COPY_BUTTON_ID);
    const exportConversationMarkdownBtn = document.getElementById('exportConversationMarkdownBtn');
    const uploadFileButton = document.getElementById('uploadFileButton');
    const uploadFileInput = document.getElementById('uploadFileInput');
    const uploadFileStatus = document.getElementById('uploadFileStatus');
    const chatAttachmentStatus = document.getElementById('chatAttachmentStatus');
    const pendingAttachmentStatus = document.getElementById('pendingAttachmentStatus');
    const chatTab = document.getElementById('chatTab');
    const inviteButton = document.getElementById('inviteConversationBtn');
    const inviteCloseButton = document.getElementById('closeInviteConversation');
    const inviteSearchInput = document.getElementById('inviteSearchInput');
    const inviteProgrammeFilter = document.getElementById('inviteProgrammeFilter');
    const inviteProjectFilter = document.getElementById('inviteProjectFilter');
    const incomingInvitesButton = document.getElementById('incomingInvitesBtn');
    const incomingInvitesCloseButton = document.getElementById('closeIncomingInvites');
    const importExternalConversationButton = document.getElementById('importExternalConversationBtn');
    const importExternalConversationInput = document.getElementById('importExternalConversationInput');
    const importAllExternalConversationsButton = document.getElementById('importAllExternalConversationsBtn');
    const continueImportedConversationButton = document.getElementById('continueImportedConversationBtn');

    if (!sendButton || !resetButton || !promptInput) {
        console.error("Chat tab elements not found");
        chatTabInitialised = false;
        return;
    }

    if (!orgSwitchListenerBound) {
        orgSwitchListenerBound = true;
        document.addEventListener('orgSwitchStarted', (e) => {
            const { organisation_id } = e.detail || {};
            console.log('[chatTab] Organisation switch started', { organisation_id });
            startOrganisationSwitchForChatTab(e.detail || {});
        });
        document.addEventListener('orgSwitched', (e) => {
            const { organisation_id, namespace } = e.detail || {};
            console.log('[chatTab] Organisation switched', { organisation_id, namespace });
            void handleOrgSwitchForChatTab(e.detail || {});
        });
        document.addEventListener('orgSwitchFailed', (e) => {
            const { organisation_id, error } = e.detail || {};
            console.warn('[chatTab] Organisation switch failed', { organisation_id, error });
            void handleOrgSwitchFailureForChatTab(e.detail || {});
        });
    }

    if (!authStatusListenerBound) {
        authStatusListenerBound = true;
        document.addEventListener('authStatusChanged', (e) => {
            const { authenticated, email } = e.detail || {};
            console.log('[chatTab] Auth status changed', { authenticated, email });
            handleAuthStatusChangeForChatTab(e.detail || {});
        });
    }

    if (!isAnnotationEnabled() && annotationToggle) {
        const label = annotationToggle.closest('.annotation-toggle');
        if (label) {
            label.remove();
        } else {
            annotationToggle.remove();
        }
    }

    uploadUiState.button = uploadFileButton || null;
    uploadUiState.statusEl = uploadFileStatus || null;
    uploadUiState.statusRegion = chatAttachmentStatus || null;
    uploadUiState.pendingAttachmentEl = pendingAttachmentStatus || null;
    renderPendingAttachmentState();
    renderActiveUploadUi();

    if (importExternalConversationButton && importExternalConversationInput) {
        importExternalConversationButton.addEventListener('click', () => {
            importExternalConversationInput.click();
        });
        importExternalConversationInput.addEventListener('change', async () => {
            const file = importExternalConversationInput.files?.[0] || null;
            importExternalConversationInput.value = '';
            if (!file) {
                return;
            }
            importExternalConversationButton.disabled = true;
            try {
                await handleExternalConversationFile(file);
            } catch (error) {
                console.error('[chatTab] External conversation import failed:', error);
                showToast(error?.message || 'Unable to import this conversation.', 'error');
            } finally {
                importExternalConversationButton.disabled = false;
            }
        });
    }
    if (importAllExternalConversationsButton) {
        importAllExternalConversationsButton.addEventListener('click', async () => {
            importAllExternalConversationsButton.disabled = true;
            try {
                await startExternalConversationBulkImport();
            } catch (error) {
                console.error('[chatTab] Machine conversation import failed:', error);
                showToast(error?.message || 'Unable to start the machine conversation import.', 'error');
            } finally {
                importAllExternalConversationsButton.disabled = false;
            }
        });
        document.getElementById('pauseExternalConversationBulkImportBtn')?.addEventListener('click', () => {
            void controlExternalConversationBulkImport('pause').catch((error) => showToast(error?.message || 'Unable to pause import.', 'error'));
        });
        document.getElementById('resumeExternalConversationBulkImportBtn')?.addEventListener('click', () => {
            void controlExternalConversationBulkImport('resume').catch((error) => showToast(error?.message || 'Unable to resume import.', 'error'));
        });
        document.getElementById('cancelExternalConversationBulkImportBtn')?.addEventListener('click', () => {
            if (window.confirm('Cancel this import? Completed conversations remain imported and a later run can safely continue.')) {
                void controlExternalConversationBulkImport('cancel').catch((error) => showToast(error?.message || 'Unable to cancel import.', 'error'));
            }
        });
        document.getElementById('closeExternalConversationBulkImportBtn')?.addEventListener('click', () => {
            externalConversationBulkImportPanelHidden = true;
            document.getElementById('externalConversationBulkImportPanel')?.classList.add('hidden');
        });
        void loadLatestExternalConversationBulkImport();
    }
    if (continueImportedConversationButton) {
        continueImportedConversationButton.addEventListener('click', async () => {
            continueImportedConversationButton.disabled = true;
            try {
                await continueActiveExternalConversation();
            } catch (error) {
                console.error('[chatTab] External conversation continuation failed:', error);
                showToast(error?.message || 'Unable to continue this conversation.', 'error');
            } finally {
                updateExternalConversationUi();
            }
        });
    }

    if (uploadFileButton && uploadFileInput) {
        uploadFileButton.addEventListener('click', () => {
            try {
                uploadFileInput.click();
            } catch (_) {
                // Ignore.
            }
        });

        uploadFileInput.addEventListener('change', async () => {
            const files = uploadFileInput.files;
            // Clear the input so selecting the same file again triggers change.
            uploadFileInput.value = '';
            await uploadFilesToVon(files);
        });
    }

    if (chatTab && scrollableField) {
        ensureScrollToEndButton(scrollableField);

        if (!scrollableField._sharedIndicatorWired) {
            scrollableField._sharedIndicatorWired = true;
            window.addEventListener('scroll', () => {
                handleConversationScrollPositionChange(scrollableField);
            }, { passive: true });
            window.addEventListener('resize', () => {
                updateScrollToEndButtonVisibility(scrollableField);
            }, { passive: true });
        }

        // Prevent the browser navigating away when dropping files.
        const preventIfFiles = (event) => {
            if (!isFileDragEvent(event)) return;
            event.preventDefault();
            event.stopPropagation();
        };

        // Global guards
        document.addEventListener('dragover', preventIfFiles);
        document.addEventListener('drop', preventIfFiles);

        const handleClipboardImagePaste = (event) => {
            const pastedImageFiles = extractImageFilesFromClipboardEvent(event);
            if (!pastedImageFiles.length) return;

            event.preventDefault();
            event.stopPropagation();

            // Route clipboard images through the same upload path used for
            // drag/drop and file-picker uploads so workflow handling is
            // consistent across all attachment entry points.
            void uploadFilesToVon(pastedImageFiles);
        };

        chatTab.addEventListener('paste', handleClipboardImagePaste);

        // Local UI + drop handling
        const applyDragOverState = () => {
            scrollableField.classList.add('drag-over');
            if (promptInput) {
                promptInput.classList.add('drag-over');
            }
        };

        const clearDragOverState = () => {
            scrollableField.classList.remove('drag-over');
            if (promptInput) {
                promptInput.classList.remove('drag-over');
            }
        };

        chatTab.addEventListener('dragover', (event) => {
            if (!isFileDragEvent(event)) return;
            preventIfFiles(event);
            applyDragOverState();
        });

        chatTab.addEventListener('dragleave', (event) => {
            if (!isFileDragEvent(event)) return;
            clearDragOverState();
        });

        chatTab.addEventListener('drop', async (event) => {
            if (!isFileDragEvent(event)) return;
            preventIfFiles(event);
            clearDragOverState();

            const dt = event.dataTransfer;
            const files = dt ? dt.files : null;
            await uploadFilesToVon(files);
        });

        if (promptInput) {
            promptInput.addEventListener('dragover', (event) => {
                if (!isFileDragEvent(event)) return;
                preventIfFiles(event);
                applyDragOverState();
            });

            promptInput.addEventListener('dragleave', (event) => {
                if (!isFileDragEvent(event)) return;
                clearDragOverState();
            });

            promptInput.addEventListener('drop', async (event) => {
                if (!isFileDragEvent(event)) return;
                preventIfFiles(event);
                clearDragOverState();

                const dt = event.dataTransfer;
                const files = dt ? dt.files : null;
                await uploadFilesToVon(files);
            });
        }
    }

    // Initialize LLM debug popup handlers
    initializeLlmDebugPopup();
    initializeReferenceInspector();
    bindDiagnosticsExportShortcut();
    initializeHistoryControls();
    initializeConversationSituationPanel();
    updateHistoryBanner();
    setupChatTabContextMenu();

    // Initialize export conversation button
    if (exportConversationJsonBtn) {
        exportConversationJsonBtn.addEventListener('click', handleExportConversationJson);
    }
    if (copyConversationInfoJsonBtn) {
        copyConversationInfoJsonBtn.addEventListener('click', () => {
            void handleCopyConversationInfoJson();
        });
    }
    if (exportConversationMarkdownBtn) {
        exportConversationMarkdownBtn.addEventListener('click', handleExportConversationMarkdown);
    }
    refreshConversationInfoCopyButtonState();

    if (inviteButton) {
        inviteButton.addEventListener('click', openInvitePopup);
    }
    if (inviteCloseButton) {
        inviteCloseButton.addEventListener('click', closeInvitePopup);
    }
    if (inviteSearchInput) {
        inviteSearchInput.addEventListener('input', renderInviteesList);
    }
    if (inviteProgrammeFilter) {
        inviteProgrammeFilter.addEventListener('change', renderInviteesList);
    }
    if (inviteProjectFilter) {
        inviteProjectFilter.addEventListener('change', renderInviteesList);
    }

    if (incomingInvitesButton) {
        incomingInvitesButton.addEventListener('click', openIncomingInvitesPopup);
    }
    if (incomingInvitesCloseButton) {
        incomingInvitesCloseButton.addEventListener('click', closeIncomingInvitesPopup);
    }

    void loadIncomingInvites({ silent: true });
    startIncomingInvitePolling();
    document.addEventListener('visibilitychange', handleRealtimeConnectionsVisibilityChange);
    window.addEventListener('storage', handleChatPromptQueueStorageEvent);
    window.addEventListener('beforeunload', () => {
        closeSharedConversationStream();
        stopWorkflowStatusStream('workflow_stream_stopped_unload');
        stopIncomingInvitePolling();
        stopSharedSessionBadgePolling();
        stopChatPromptQueuePolling();
    }, { once: true });

    // JVNAUTOSCI-1040: Initialize task panel
    initializeTaskPanel();
    const taskPanelToggleBtn = document.getElementById('taskPanelToggleBtn');
    if (taskPanelToggleBtn) {
        taskPanelToggleBtn.addEventListener('click', () => {
            if (!isTaskPanelVisible()) {
                toggleTaskPanel({ sessionId: activeChatSessionId });
            } else {
                toggleTaskPanel();
            }
        });
    }

    // JVNAUTOSCI-1071: Initialize message panel
    initializeMessagePanel();
    // Load initial unread count for badge
    loadUnreadCount();

    // Phase 5: Workflow monitor panel
    initializeWorkflowStatusPanel();
    handleRealtimeConnectionsVisibilityChange();

    // Load annotation toggle state from localStorage (default: false)
    const savedState = localStorage.getItem('annotationToggleEnabled');
    if (annotationToggle) {
        annotationToggle.checked = savedState === 'true';
        annotationToggle.addEventListener('change', (e) => {
            localStorage.setItem('annotationToggleEnabled', e.target.checked);
            console.log('[annotations] Toggle changed to:', e.target.checked);
        });
    }

    // Load TTS toggle state from localStorage (default: false)
    if (ttsToggle) {
        const savedTts = safeLocalStorageGet(CHAT_TTS_STORAGE_KEY);
        ttsToggle.checked = savedTts === 'true';

        if (!isTextToSpeechSupported()) {
            ttsToggle.disabled = true;
            ttsToggle.checked = false;
            ttsToggle.title = 'Text-to-speech is not supported in this browser.';
        }

        ttsToggle.addEventListener('change', (e) => {
            const enabled = !!e.target.checked;
            safeLocalStorageSet(CHAT_TTS_STORAGE_KEY, enabled ? 'true' : 'false');

            // If disabled while speaking, stop immediately.
            if (!enabled) {
                stopSpeaking();
                clearActiveTtsUi();
            }
        });
    }

    // Dictation (STT): optional browser capability.
    if (dictateButton) {
        if (!isSpeechRecognitionSupported()) {
            dictateButton.disabled = true;
            dictateButton.title = 'Dictation is not supported in this browser.';
        } else {
            dictateButton.addEventListener('click', () => {
                if (activeDictation) {
                    stopDictation();
                    return;
                }

                if (!promptInput) {
                    return;
                }

                const baseText = String(promptInput.value || '');
                dictationState = {
                    baseText,
                    finalText: '',
                    interimText: ''
                };

                dictateButton.textContent = 'Stop dictation';
                dictateButton.classList.add('active-dictation');

                try {
                    const settings = getChatSpeechSettings();
                    activeDictation = startSpeechRecognition({
                        language: settings.stt.language,
                        continuous: settings.stt.continuous,
                        interimResults: settings.stt.interimResults,
                        onResult: ({ finalText, interimText }) => {
                            if (!dictationState) {
                                return;
                            }

                            if (finalText) {
                                dictationState.finalText = [dictationState.finalText, finalText]
                                    .map(t => String(t || '').trim())
                                    .filter(Boolean)
                                    .join(' ');
                            }

                            dictationState.interimText = String(interimText || '').trim();

                            const baseText = String(dictationState.baseText || '');
                            const dictatedText = [dictationState.finalText, dictationState.interimText]
                                .map(t => String(t || '').trim())
                                .filter(Boolean)
                                // Normalise spaces/tabs, but preserve newlines.
                                .join(' ')
                                .replace(/[ \t]+/g, ' ');

                            if (!dictatedText) {
                                setPromptComposerValue(baseText, { promptInput });
                            } else {
                                const needsSpacer = baseText.length > 0 && !/[ \t\n]$/.test(baseText);
                                setPromptComposerValue(
                                    `${baseText}${needsSpacer ? ' ' : ''}${dictatedText}`,
                                    { promptInput }
                                );
                            }
                        },
                        onError: (event) => {
                            console.warn('[chatTab] Dictation error:', event);
                        },
                        onEnd: () => {
                            activeDictation = null;
                            dictationState = null;
                            dictateButton.textContent = 'Dictate';
                            dictateButton.classList.remove('active-dictation');
                        }
                    });
                } catch (err) {
                    console.warn('[chatTab] Unable to start dictation:', err);
                    activeDictation = null;
                    dictationState = null;
                    dictateButton.textContent = 'Dictate';
                    dictateButton.classList.remove('active-dictation');
                }
            });
        }
    }

    // Add event listeners
    sendButton.addEventListener('click', handleSendPrompt);
    resetButton.addEventListener('click', handleResetContext);

    ensureAbortButtonBound();
    renderChatTaskQueuePanel();
    void refreshChatPromptQueueFromServer({ silent: true });

    // Add Enter key support for prompt input
    promptInput.addEventListener('focusin', function () {
        setSelectedChatPromptQueueEntryId(null);
    });

    promptInput.addEventListener('input', function () {
        setSelectedChatPromptQueueEntryId(null);
        resizePromptComposer(promptInput);
    });
    resizePromptComposer(promptInput);

    promptInput.addEventListener('keypress', function (event) {
        if (event.key === 'Enter' && !event.shiftKey) {
            event.preventDefault();
            handleSendPrompt();
        }
    });

    // JVNAUTOSCI-2128/2163: ArrowUp/ArrowDown on an empty composer recalls
    // historical submitted prompts with cursor navigation.
    promptInput.addEventListener('keydown', handlePromptInputHistoryNavigation);

    // Initialize concept autocomplete for #V# trigger
    initializeConceptAutocomplete(promptInput);

    // Render non-trigger (#V\u200B#...) concept tokens as cartouches in the prompt.
    initializePromptCartoucheOverlay(promptInput);

    void Promise.allSettled([
        loadRecentChatPair({
            scrollToBottom: true,
            preserveScroll: false,
            showResetNotice: false,
            forceScrollToBottom: true
        }).then(() => loadChatHistory({
            segments: 1,
            scrollToBottom: false,
            preserveScroll: true,
            showResetNotice: false
        })),
        refreshChatSessionTabs()
    ]).then(async () => {
        if (activeChatSessionId && activeChatSessionId !== displayedHistorySessionId) {
            try {
                await switchToChatSession(activeChatSessionId);
            } catch (_) {
                // Leave the current transcript visible if startup activation follow-up fails.
            }
        }
        updateScrollToEndButtonVisibility();
    }).catch(() => { });
    void refreshToolUseDuringThinkingSetting();
    console.log("Chat tab initialized successfully");
}

function setThinkingState(isThinking, request = activeChatRequest, options = {}) {
    const preserveFinishedCard = !!options.preserveFinishedCard;
    const shouldResetDisplayState = options.resetDisplayState !== false;
    const wrapper = getThinkingCardWrapperEl();
    const loadingIndicator = getLoadingIndicatorEl();
    const loadingDetail = getLoadingIndicatorDetailEl();
    const toggleButton = getThinkingCardToggleButtonEl();
    const abortButton = getThinkingCardAbortButtonEl();
    const retryButton = getThinkingCardRetryButtonEl();
    const copyDiagnosticsButton = getThinkingCardCopyButtonEl();
    const criticButton = getThinkingCardCriticButtonEl();
    const statusBadge = getThinkingCardStatusBadgeEl();
    const sendButton = document.getElementById('sendButton');
    const metaEl = getThinkingCardMetaEl();
    const sizeDecreaseButton = getThinkingCardSizeDecreaseButtonEl();
    const sizeIncreaseButton = getThinkingCardSizeIncreaseButtonEl();
    const modeButtons = getThinkingCardModeButtons();

    if (isThinking && request && shouldResetDisplayState) {
        request.thinkingCardDisplayState = reduceThinkingCardDisplayState(
            request.thinkingCardDisplayState,
            { type: 'reset_for_active' }
        );
    }

    // Toggle wrapper visibility (controls the entire card)
    if (wrapper) {
        if (isThinking || preserveFinishedCard) {
            wrapper.setAttribute('aria-hidden', 'false');
        } else {
            wrapper.setAttribute('aria-hidden', 'true');
        }

        wrapper.classList.toggle('is-active-turn', !!isThinking);
        wrapper.classList.toggle('is-retained-turn', !isThinking && preserveFinishedCard);

        if (!isThinking && !preserveFinishedCard) {
            wrapper.classList.remove('has-tools');
            wrapper.classList.remove('is-collapsed');
            wrapper.classList.remove('is-expanded');
            wrapper.classList.remove('is-active-turn');
            wrapper.classList.remove('is-retained-turn');
        }
    }

    if (loadingIndicator) {
        if (isThinking) {
            setLoadingIndicatorText(DEFAULT_THINKING_TEXT);
        } else if (!preserveFinishedCard) {
            setLoadingIndicatorText(DEFAULT_THINKING_TEXT);
        }
    }

    if (loadingDetail) {
        if (!isThinking && !preserveFinishedCard) {
            loadingDetail.innerHTML = '';
            loadingDetail.setAttribute('aria-hidden', 'true');
        }
    }

    if (metaEl && !isThinking && !preserveFinishedCard) {
        metaEl.textContent = '';
    }

    if (statusBadge) {
        if (isThinking) {
            statusBadge.textContent = 'Active';
            THINKING_STATUS_CLASS_NAMES.forEach((stateClass) => statusBadge.classList.remove(stateClass));
            statusBadge.classList.add(THINKING_STATUS_ACTIVE);
            statusBadge.setAttribute('aria-hidden', 'false');
        } else {
            statusBadge.setAttribute('aria-hidden', 'true');
        }
    }

    if (sendButton) {
        updateSendButtonForCurrentChatState();
    }

    if (toggleButton) {
        toggleButton.setAttribute('aria-hidden', (isThinking || preserveFinishedCard) ? 'false' : 'true');
        toggleButton.disabled = shouldDisableThinkingCardToggle(request);
    }

    if (abortButton) {
        abortButton.setAttribute('aria-hidden', isThinking ? 'false' : 'true');
        const cancellationRequested = isThinking
            && request?.backgroundCancellationRequested === true;
        abortButton.disabled = cancellationRequested;
        abortButton.setAttribute(
            'aria-label',
            cancellationRequested ? 'Cancellation requested' : 'Stop generating'
        );
        abortButton.setAttribute(
            'title',
            cancellationRequested ? 'Waiting for the running turn to stop' : 'Stop generating'
        );
    }
    if (retryButton) {
        const canRetryThinkingRequest = isThinking
            && request?.turnKind !== 'assistant_opening'
            && request?.observingServerDispatch !== true;
        retryButton.setAttribute('aria-hidden', canRetryThinkingRequest ? 'false' : 'true');
    }
    if (copyDiagnosticsButton) {
        copyDiagnosticsButton.setAttribute('aria-hidden', (isThinking || preserveFinishedCard) ? 'false' : 'true');
        if (!isThinking && !preserveFinishedCard) {
            copyDiagnosticsButton.textContent = 'Copy diagnostic snapshot';
            copyDiagnosticsButton.setAttribute('title', 'Copy diagnostic snapshot');
            copyDiagnosticsButton.setAttribute('aria-label', 'Copy diagnostic snapshot');
            copyDiagnosticsButton.classList.remove(
                'success-feedback',
                'error-feedback',
                'copy-json-copied',
                'copy-json-copy-failed'
            );
        }
    }
    if (criticButton && !isThinking && !preserveFinishedCard) {
        criticButton.setAttribute('aria-hidden', 'true');
        criticButton.setAttribute('aria-expanded', 'false');
        criticButton.disabled = true;
    }

    [sizeDecreaseButton, sizeIncreaseButton].forEach((button) => {
        if (!(button instanceof HTMLButtonElement)) {
            return;
        }
        button.setAttribute('aria-hidden', (isThinking || preserveFinishedCard) ? 'false' : 'true');
    });
    modeButtons.forEach((button) => {
        if (!(button instanceof HTMLButtonElement)) {
            return;
        }
        button.setAttribute('aria-hidden', (isThinking || preserveFinishedCard) ? 'false' : 'true');
    });

    if (isThinking || preserveFinishedCard) {
        updateThinkingCardModeControls(request);
        syncThinkingCriticControlStateToDom(request);
        syncThinkingCardExpandedStateToDom(request);
    } else {
        updateThinkingCardModeControls(null);
        syncThinkingCriticControlStateToDom(null);
        updateThinkingCardResizeControls(request);
    }
}

function restorePromptEditingState(request, options = {}) {
    const promptInput = getPromptInputElement();
    if (!promptInput || !request) {
        return;
    }

    const currentValue = String(promptInput.value ?? '').trim();
    const shouldRestorePrompt = options.restorePrompt !== false;

    if (!currentValue && shouldRestorePrompt) {
        setPromptComposerValue(request.promptRaw || '', {
            promptInput,
            selectionStart: Number.isInteger(request.selectionStart) ? request.selectionStart : null,
            selectionEnd: Number.isInteger(request.selectionEnd) ? request.selectionEnd : null,
            focus: true
        });
        return;
    }

    try {
        promptInput.focus();
    } catch (_) {
        // Ignore focus errors.
    }
}

async function requestServerCancellation(request) {
    const requestId = (typeof request?.clientRequestId === 'string')
        ? request.clientRequestId.trim()
        : '';
    const queueId = (typeof request?.promptQueueRecordId === 'string')
        ? request.promptQueueRecordId.trim()
        : '';
    const observedServerDispatch = request?.observingServerDispatch === true;
    if (
        (!queueId && (!observedServerDispatch || !requestId))
        || request?.backgroundCancellationRequested === true
    ) {
        return false;
    }
    request.backgroundCancellationRequested = true;
    try {
        const response = await fetch(
            observedServerDispatch
                ? `/von/api/task/cancel/${encodeURIComponent(requestId)}`
                : `/von/api/chat_prompt_queue/${encodeURIComponent(queueId)}`,
            {
                method: observedServerDispatch ? 'POST' : 'DELETE',
                headers: buildChatFetchHeaders({
                    'Content-Type': 'application/json'
                }),
                credentials: 'same-origin'
            }
        );
        const payload = await response.json().catch(() => ({}));
        if (!response.ok || payload?.success !== true) {
            throw new Error(
                payload?.detail
                || payload?.error
                || `HTTP ${response.status}`
            );
        }
        publishChatPromptQueueChange('turn_cancellation_requested');
        return true;
    } catch (error) {
        request.backgroundCancellationRequested = false;
        console.warn('[chatTab] Unable to cancel observed retry:', error);
        showToast(
            'The retry is still running on the server; cancellation was not acknowledged.',
            'warning'
        );
        return false;
    }
}

function abortActiveChatRequest(options = {}) {
    if (!activeChatRequest) {
        return;
    }

    const request = activeChatRequest;
    const observingServerDispatch = request.observingServerDispatch === true;
    const canRequestServerCancellation = observingServerDispatch
        || (typeof request.promptQueueRecordId === 'string'
            && request.promptQueueRecordId.trim());
    if (canRequestServerCancellation) {
        const previousProgress = cloneThinkingLatestProgress(request.latestProgress);
        const cancellationPromise = requestServerCancellation(request);
        request.latestProgress = {
            ...(request.latestProgress && typeof request.latestProgress === 'object'
                ? request.latestProgress
                : {}),
            status: 'cancelling',
            phase: 'cancelling',
            phase_label: 'Cancelling',
            result_summary: 'Cancellation requested; waiting for the running turn to stop.'
        };
        syncActiveChatSessionThinkingState();
        void cancellationPromise.then((acknowledged) => {
            if (acknowledged || !isLiveChatRequest(request)) {
                return;
            }
            request.latestProgress = previousProgress;
            syncActiveChatSessionThinkingState();
        });
        return;
    }
    request.aborted = true;
    releaseRequestFileCopyBinding(request);

    stopToolUseProgressPolling(request);
    stopThinkingTooltipTicker(request);

    try {
        request.abortController?.abort();
    } catch (_) {
        // Ignore abort errors.
    }

    setLiveChatRequestForSession(request.sessionId, null);
    setFinishedThinkingCardForSession(request.sessionId, null);
    const latestKnownCostSummary = request.llmUsageCostSummary
        || request.latestProgress?.llm_usage_cost_summary
        || null;
    setConversationRuntimeCostLiveSummary(request, latestKnownCostSummary, {
        active: false,
        reason: 'request_aborted'
    });
    if (request.sessionId === activeChatSessionId) {
        void refreshConversationRuntimeCostSnapshot({
            observeRequestId: request.clientRequestId,
            reason: 'request_aborted'
        });
    }
    syncActiveChatSessionThinkingState();
    restorePromptEditingState(request, {
        ...options,
        restorePrompt: observingServerDispatch
            ? false
            : options.restorePrompt
    });
}

function abortActiveHistoryRequest() {
    if (!activeHistoryRequest) {
        return;
    }

    const request = activeHistoryRequest;
    activeHistoryRequest = null;
    request.aborted = true;

    try {
        request.abortController?.abort();
    } catch (_) {
        // Ignore abort errors.
    }
}

function buildThinkingDiagnosticsPayload(request) {
    if (!request || typeof request !== 'object') {
        return null;
    }

    const latestProgress = (request.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const backendElapsedMs = (latestProgress && Number.isFinite(latestProgress.elapsed_ms))
        ? Math.max(0, Math.round(Number(latestProgress.elapsed_ms)))
        : null;
    const elapsedMs = backendElapsedMs ?? getThinkingRequestElapsedMs(request);
    const locatorPayload = buildThinkingDiagnosticsLocatorPayload(request);
    const progressViewModel = buildThinkingCardProgressViewModel(request);
    const timingSummary = cloneThinkingTimingSummary(request.timingSummary)
        || cloneThinkingTimingSummary(latestProgress?.timing_summary);

    return {
        schema_version: 'thinking_diagnostics_snapshot.v1',
        generated_at_utc: new Date().toISOString(),
        request_id: request.clientRequestId || null,
        chat_session_id: activeChatSessionId || null,
        thinking_card_mode: getThinkingCardMode(request),
        available_thinking_card_modes: Array.from(THINKING_CARD_MODES),
        progress_view_model: progressViewModel,
        elapsed_ms: elapsedMs,
        prompt_preview: typeof request.promptRaw === 'string' ? request.promptRaw.slice(0, 1000) : null,
        latest_progress: cloneThinkingLatestProgress(latestProgress),
        activity_history: Array.isArray(request.activityHistory)
            ? request.activityHistory.slice(-THINKING_DIAGNOSTICS_EXPORT_EVENT_LIMIT)
            : [],
        progress_events: Array.isArray(request.progressEvents)
            ? request.progressEvents.slice(-THINKING_DIAGNOSTICS_EXPORT_EVENT_LIMIT)
            : [],
        phase_history: Array.isArray(request.phaseHistory)
            ? request.phaseHistory.slice(-THINKING_DIAGNOSTICS_EXPORT_PHASE_HISTORY_LIMIT)
            : [],
        tool_history: getCanonicalThinkingToolHistory(request).slice(-THINKING_DIAGNOSTICS_EXPORT_EVENT_LIMIT),
        workflow_discovery: request.workflowDiscovery || null,
        workflow_selection: buildThinkingWorkflowSelectionSnapshot(
            (request.workflowSelection && typeof request.workflowSelection === 'object')
                ? request.workflowSelection
                : latestProgress
        ),
        workflow_routing_diagnostics: getWorkflowRoutingDiagnostics(
            (request.workflowRoutingDiagnostics && typeof request.workflowRoutingDiagnostics === 'object')
                ? request.workflowRoutingDiagnostics
                : latestProgress
        ),
        workflow_stage_path: request.workflowStagePath || null,
        timing_summary: timingSummary,
        timing_breakdown: cloneThinkingTimingBreakdown(request.timingBreakdown),
        stage_diagnostics: buildThinkingStageDiagnosticsSnapshot(request),
        mcp_access: locatorPayload?.mcp_access || null
    };
}

function getLatestLlmDebugEntryForExport() {
    if (llmDebugData.size === 0) {
        return null;
    }

    const getTurnTimestamp = (turnId) => {
        if (typeof turnId !== 'string') {
            return 0;
        }
        const parts = turnId.split('-');
        const tail = parts.length > 1 ? Number.parseInt(parts[parts.length - 1], 10) : 0;
        return Number.isFinite(tail) ? tail : 0;
    };

    let latest = null;
    for (const [turnId, debugData] of llmDebugData.entries()) {
        const executionContextBinding = llmDebugExecutionContextBindings.get(turnId) || null;
        if (!latest) {
            latest = { turnId, debugData, executionContextBinding, timestamp: getTurnTimestamp(turnId) };
            continue;
        }
        const nextTimestamp = getTurnTimestamp(turnId);
        if (nextTimestamp >= latest.timestamp) {
            latest = { turnId, debugData, executionContextBinding, timestamp: nextTimestamp };
        }
    }
    return latest;
}

function summariseDiagnosticToolInvocation(entry) {
    if (!entry || typeof entry !== 'object') {
        return null;
    }

    const method = entry.method || entry.tool || entry.name || null;
    const argumentsPayload = (entry.arguments && typeof entry.arguments === 'object') ? entry.arguments : null;
    return {
        method,
        status: entry.status || null,
        success: (typeof entry.success === 'boolean') ? entry.success : null,
        duration_ms: (typeof entry.duration_ms === 'number' && Number.isFinite(entry.duration_ms))
            ? Math.max(0, Math.round(entry.duration_ms))
            : null,
        error: entry.error || null,
        error_type: entry.error_type || null,
        argument_keys: argumentsPayload ? Object.keys(argumentsPayload).slice(0, 50) : []
    };
}

function summariseAuxLlmCallForExport(entry) {
    if (!entry || typeof entry !== 'object') {
        return null;
    }
    return {
        type: entry.type || null,
        model: entry.model || null,
        provider: entry.provider || null,
        status: entry.status || null,
        duration_ms: (typeof entry.duration_ms === 'number' && Number.isFinite(entry.duration_ms))
            ? Math.max(0, Math.round(entry.duration_ms))
            : null,
        error: entry.error || null
    };
}

function summariseTurnDiagnosticsForExport(rawTurnDiagnostics) {
    const turnDiagnostics = (rawTurnDiagnostics && typeof rawTurnDiagnostics === 'object')
        ? rawTurnDiagnostics
        : null;
    if (!turnDiagnostics) {
        return null;
    }
    const events = Array.isArray(turnDiagnostics.events)
        ? turnDiagnostics.events.filter(event => event && typeof event === 'object')
        : [];
    const categories = Array.from(new Set(events
        .map(event => (typeof (event.type || event.category) === 'string') ? String(event.type || event.category) : '')
        .filter(Boolean)));

    return {
        event_count: events.length,
        categories,
        latest_event_type: categories.length ? categories[categories.length - 1] : null
    };
}

function buildSanitisedLlmDebugExportPayload(debugData) {
    if (!debugData || typeof debugData !== 'object') {
        return null;
    }

    if (debugData.turn_execution_diagnostics && typeof debugData.turn_execution_diagnostics === 'object') {
        return {
            type: 'turn_execution_diagnostics',
            ...debugData.turn_execution_diagnostics,
            prompt_preview: undefined
        };
    }

    const toolInvocations = Array.isArray(debugData.tool_invocations)
        ? debugData.tool_invocations
            .map(summariseDiagnosticToolInvocation)
            .filter(Boolean)
            .slice(0, 80)
        : [];

    const auxLlmCalls = Array.isArray(debugData.aux_llm_calls)
        ? debugData.aux_llm_calls
            .map(summariseAuxLlmCallForExport)
            .filter(Boolean)
            .slice(0, 80)
        : [];

    return {
        type: 'llm_debug_summary',
        request_id: debugData.request_id || null,
        model: debugData.model || null,
        error: debugData.error || null,
        warnings: Array.isArray(debugData.warnings) ? debugData.warnings.slice(0, 40) : [],
        llm_interaction: (debugData.llm_interaction && typeof debugData.llm_interaction === 'object') ? {
            requested_model: debugData.llm_interaction.requested_model || null,
            orchestrator_used: debugData.llm_interaction.orchestrator_used || null,
            duration_ms: debugData.llm_interaction.duration_ms || null,
            server_elapsed_ms: debugData.llm_interaction.server_elapsed_ms || null,
            call_count: Array.isArray(debugData.llm_interaction.calls) ? debugData.llm_interaction.calls.length : 0
        } : null,
        tool_invocations: toolInvocations,
        aux_llm_calls: auxLlmCalls,
        turn_diagnostics: summariseTurnDiagnosticsForExport(debugData.turn_diagnostics),
        workflow_discovery: (debugData.workflow_discovery && typeof debugData.workflow_discovery === 'object')
            ? debugData.workflow_discovery
            : null,
        internal_mcp: (debugData.internal_mcp && typeof debugData.internal_mcp === 'object')
            ? debugData.internal_mcp
            : null
    };
}

function buildDiagnosticsExportRequestPayload() {
    const activeThinkingRaw = buildThinkingDiagnosticsPayload(getThinkingDiagnosticsDisplayRequest());
    const activeThinking = activeThinkingRaw ? {
        ...activeThinkingRaw,
        prompt_preview: undefined
    } : null;

    const latestEntry = getLatestLlmDebugEntryForExport();
    const latestDebug = latestEntry ? buildSanitisedLlmDebugExportPayload(latestEntry.debugData) : null;

    return {
        schema_version: 'diagnostic_export_request.v1',
        capture_scope: 'current_diagnostic_snapshot',
        generated_at_utc: new Date().toISOString(),
        trigger: 'keyboard_shortcut',
        shortcut: DIAGNOSTICS_EXPORT_SHORTCUT_HINT,
        thinking_card_mode: activeThinking?.thinking_card_mode || null,
        thinking_card_progress_view_model: activeThinking?.progress_view_model || null,
        session_id: activeChatSessionId || null,
        diagnostics: {
            active_thinking: activeThinking,
            latest_turn_id: latestEntry ? latestEntry.turnId : null,
            latest_turn_debug: latestDebug
        },
        telemetry: {
            llm_debug_turn_count: llmDebugData.size,
            transcript_turn_count: Array.isArray(transcriptTurns) ? transcriptTurns.length : 0
        }
    };
}

function shouldHandleDiagnosticsExportShortcut(event) {
    if (!event || event.defaultPrevented) {
        return false;
    }
    if (!(event.ctrlKey || event.metaKey) || !event.shiftKey || event.altKey) {
        return false;
    }
    return String(event.key || '').toLowerCase() === 'd';
}

async function exportDiagnosticsSnapshotFromShortcut() {
    const payload = buildDiagnosticsExportRequestPayload();
    const hasDiagnostics = !!(
        payload.diagnostics.active_thinking
        || payload.diagnostics.latest_turn_debug
    );
    if (!hasDiagnostics) {
        showToast('No diagnostics available to export.', 'info');
        return false;
    }

    try {
        const response = await fetch(DIAGNOSTICS_EXPORT_ENDPOINT, {
            method: 'POST',
            headers: buildChatFetchHeaders({
                'Content-Type': 'application/json',
            }),
            body: JSON.stringify(payload),
        });
        const body = await response.json();
        if (!response.ok || !body?.success) {
            throw new Error(body?.error || `HTTP ${response.status}`);
        }
        const savedPath = body.path || 'data/diagnostic_latest.json';
        showToast(`Diagnostic snapshot exported to ${savedPath}`, 'success');
        return true;
    } catch (error) {
        console.error('[chatTab] Failed to export diagnostics snapshot:', error);
        showToast('Failed to export diagnostics snapshot.', 'error');
        return false;
    }
}

function bindDiagnosticsExportShortcut() {
    if (diagnosticsExportShortcutBound) {
        return;
    }

    diagnosticsExportShortcutBound = true;
    document.addEventListener('keydown', (event) => {
        if (!shouldHandleDiagnosticsExportShortcut(event)) {
            return;
        }
        const chatTab = document.getElementById('chatTab');
        if (!chatTab || !chatTab.classList.contains('active')) {
            return;
        }
        event.preventDefault();
        void exportDiagnosticsSnapshotFromShortcut();
    });
}

function retryActiveChatRequest() {
    if (!activeChatRequest) {
        return;
    }

    const request = activeChatRequest;
    if (request.observingServerDispatch === true) {
        return;
    }
    const prompt = typeof request.promptRaw === 'string' ? request.promptRaw : '';
    const fileCopyConceptId = normaliseTrustedUploadedFileCopyConceptId(
        request.pendingFileCopyConceptId
    );
    const fileCopyDisplayName = normalisePendingAttachmentDisplayName(
        request.pendingFileCopyDisplayName
    );
    request.attachmentBindingTransferred = !!fileCopyConceptId;
    abortActiveChatRequest();
    if (!prompt.trim()) {
        return;
    }
    setPromptComposerValue(prompt, { focus: true });
    setTimeout(() => {
        void handleSendPrompt({
            promptOverride: prompt,
            sessionId: request.sessionId || null,
            sessionName: request.sessionName || null,
            fileCopyConceptId,
            fileCopyDisplayName
        });
    }, 0);
}

function retryAssistantOpeningRequest(request) {
    const sessionId = normaliseHistorySessionId(request?.sessionId);
    const initiationId = String(request?.initiationId || '').trim();
    if (request?.turnKind !== 'assistant_opening' || !sessionId || !initiationId) {
        return false;
    }
    if (isChatPromptSessionBusy(sessionId, { includeQueued: true })) {
        showToast('Wait for the current response before retrying Von’s opening.', 'info');
        return false;
    }

    setFinishedThinkingCardForSession(sessionId, null);
    void handleSendPrompt({
        sessionId,
        sessionName: request?.sessionName || null,
        promptOverride: '',
        turnKind: 'assistant_opening',
        initiationId,
        allowEmptyPrompt: true,
        skipPromptQueueRecord: true
    });
    return true;
}

function appendAssistantOpeningRetryAction(request, turnId) {
    if (
        request?.turnKind !== 'assistant_opening'
        || !String(request?.initiationId || '').trim()
    ) {
        return null;
    }
    const messageContainer = getMessageContainerByTurnId(turnId);
    if (!(messageContainer instanceof HTMLElement)) {
        return null;
    }
    const existing = messageContainer.querySelector('.assistant-opening-retry-button');
    if (existing instanceof HTMLButtonElement) {
        return existing;
    }

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'btn btn-secondary assistant-opening-retry-button';
    button.textContent = 'Retry Von opening';
    button.title = 'Retry this assistant opening without adding a user message';
    button.addEventListener('click', () => {
        button.disabled = true;
        if (!retryAssistantOpeningRequest(request)) {
            button.disabled = false;
        }
    });
    messageContainer.appendChild(button);
    return button;
}

async function copyActiveThinkingDiagnostics(button = null, requestOverride = null) {
    const request = getThinkingDiagnosticsDisplayRequest(requestOverride);
    if (!request) {
        return false;
    }
    const requestId = (
        typeof request.clientRequestId === 'string'
            ? request.clientRequestId.trim()
            : ''
    ) || (
        typeof request.latestProgress?.request_id === 'string'
            ? request.latestProgress.request_id.trim()
            : ''
    );
    const turnAccess = await fetchTurnTelemetryMcpAccess({
        requestId,
        sessionId: activeChatSessionId || request.sessionId || null,
        includeLiveProgress: true
    });
    const payload = buildThinkingDiagnosticsLocatorPayload(request, {
        mcpAccess: turnAccess?.mcp_access || null,
        retrievalStatus: turnAccess?.retrieval_status || null
    });
    if (!payload) {
        showToast('No diagnostic reference is available yet.', 'info');
        return false;
    }

    const text = JSON.stringify(payload, null, 2);
    if (button instanceof HTMLButtonElement) {
        return copyJsonTextWithButtonFeedback(button, text, {
            fallbackLabel: 'Copy reference'
        });
    }

    return copyTextToClipboard(text);
}

function bindThinkingCardControls(cardRoot = null, options = {}) {
    const explicitRoot = cardRoot instanceof HTMLElement;
    const wrapper = getThinkingCardWrapperEl(cardRoot);
    if (!wrapper && explicitRoot) {
        return;
    }
    const rootRef = explicitRoot ? wrapper : null;

    const requestResolver = (typeof options.requestResolver === 'function')
        ? options.requestResolver
        : (() => getThinkingCardDisplayRequest());
    const bindAbort = options.bindAbort === true;
    const bindRetry = options.bindRetry === true;

    const toggleButton = getThinkingCardToggleButtonEl(rootRef);
    const abortButton = getThinkingCardAbortButtonEl(rootRef);
    const retryButton = getThinkingCardRetryButtonEl(rootRef);
    const copyDiagnosticsButton = getThinkingCardCopyButtonEl(rootRef);
    const criticButton = getThinkingCardCriticButtonEl(rootRef);
    const sizeDecreaseButton = getThinkingCardSizeDecreaseButtonEl(rootRef);
    const sizeIncreaseButton = getThinkingCardSizeIncreaseButtonEl(rootRef);
    const modeButtons = getThinkingCardModeButtons(rootRef);

    bindThinkingCardBodyResizePersistence(rootRef, { requestResolver });

    if (toggleButton && toggleButton.dataset.bound !== '1') {
        toggleButton.dataset.bound = '1';
        toggleButton.addEventListener('click', () => {
            toggleThinkingCardExpanded(requestResolver(), rootRef);
        });
    }

    if (copyDiagnosticsButton && copyDiagnosticsButton.dataset.bound !== '1') {
        copyDiagnosticsButton.dataset.bound = '1';
        copyDiagnosticsButton.addEventListener('click', () => {
            void copyActiveThinkingDiagnostics(copyDiagnosticsButton, requestResolver());
        });
    }

    if (criticButton && criticButton.dataset.bound !== '1') {
        criticButton.dataset.bound = '1';
        criticButton.addEventListener('click', () => {
            toggleThinkingCriticPanel(requestResolver(), rootRef);
        });
    }

    if (sizeDecreaseButton && sizeDecreaseButton.dataset.bound !== '1') {
        sizeDecreaseButton.dataset.bound = '1';
        sizeDecreaseButton.addEventListener('click', () => {
            adjustThinkingCardBodyHeight(
                requestResolver(),
                -THINKING_CARD_BODY_STEP_PX,
                rootRef
            );
        });
    }

    if (sizeIncreaseButton && sizeIncreaseButton.dataset.bound !== '1') {
        sizeIncreaseButton.dataset.bound = '1';
        sizeIncreaseButton.addEventListener('click', () => {
            adjustThinkingCardBodyHeight(
                requestResolver(),
                THINKING_CARD_BODY_STEP_PX,
                rootRef
            );
        });
    }

    modeButtons.forEach((button) => {
        if (!(button instanceof HTMLButtonElement) || button.dataset.bound === '1') {
            return;
        }
        button.dataset.bound = '1';
        button.addEventListener('click', () => {
            setThinkingCardMode(requestResolver(), button.dataset.thinkingMode, rootRef);
        });
    });
    updateThinkingCardModeControls(requestResolver(), rootRef);

    if (bindAbort && abortButton && abortButton.dataset.bound !== '1') {
        abortButton.dataset.bound = '1';
        abortButton.addEventListener('click', () => {
            abortActiveChatRequest();
        });
    }

    if (bindRetry && retryButton && retryButton.dataset.bound !== '1') {
        retryButton.dataset.bound = '1';
        retryButton.addEventListener('click', () => {
            retryActiveChatRequest();
        });
    }

    if (wrapper && wrapper.dataset.llmCallLogBound !== '1') {
        wrapper.dataset.llmCallLogBound = '1';
        wrapper.addEventListener('click', (event) => {
            const target = event.target;
            if (!(target instanceof HTMLElement)) {
                return;
            }
            const actionButton = target.closest('[data-thinking-action]');
            if (!(actionButton instanceof HTMLElement)) {
                return;
            }
            const action = normaliseThinkingActivityString(actionButton.dataset.thinkingAction);
            if (!action) {
                return;
            }
            const request = requestResolver();
            if (!request) {
                return;
            }
            if (action === 'llm-call-log-toggle') {
                event.preventDefault();
                void loadThinkingLlmCallLog(request, { append: false });
            } else if (action === 'llm-call-log-more') {
                event.preventDefault();
                void loadThinkingLlmCallLog(request, { append: true });
            } else if (action === 'critic-copy') {
                event.preventDefault();
                void copyThinkingCriticDetails(actionButton, request);
            }
        });
    }
}

function ensureAbortButtonBound() {
    bindThinkingCardControls(null, {
        requestResolver: () => getThinkingCardDisplayRequest(),
        bindAbort: true,
        bindRetry: true
    });
}

function normaliseChatPromptQueueStatus(status) {
    const cleaned = (typeof status === 'string' && status.trim())
        ? status.trim()
        : CHAT_PROMPT_QUEUE_STATUS_QUEUED;
    if ([
        CHAT_PROMPT_QUEUE_STATUS_QUEUED,
        CHAT_PROMPT_QUEUE_STATUS_IN_PROGRESS,
        CHAT_PROMPT_QUEUE_STATUS_COMPLETED,
        CHAT_PROMPT_QUEUE_STATUS_FAILED,
        CHAT_PROMPT_QUEUE_STATUS_CANCELLED
    ].includes(cleaned)) {
        return cleaned;
    }
    return CHAT_PROMPT_QUEUE_STATUS_QUEUED;
}

function normaliseChatPromptQueueEntry(rawEntry, fallback = {}) {
    if (!rawEntry || typeof rawEntry !== 'object') {
        return null;
    }
    const queueId = (typeof rawEntry.queue_id === 'string' && rawEntry.queue_id.trim())
        ? rawEntry.queue_id.trim()
        : ((typeof rawEntry.queueId === 'string' && rawEntry.queueId.trim()) ? rawEntry.queueId.trim() : null);
    const id = queueId
        || ((typeof rawEntry.id === 'string' && rawEntry.id.trim()) ? rawEntry.id.trim() : null)
        || fallback.id
        || createQueuedChatPromptId();
    const sessionId = normaliseHistorySessionId(rawEntry.session_id ?? rawEntry.sessionId ?? fallback.sessionId ?? null);
    const sessionNameRaw = rawEntry.session_name ?? rawEntry.sessionName ?? fallback.sessionName ?? null;
    const sessionName = (typeof sessionNameRaw === 'string' && sessionNameRaw.trim())
        ? sessionNameRaw.trim()
        : null;
    const fileCopyConceptId = normaliseTrustedUploadedFileCopyConceptId(
        rawEntry.file_copy_concept_id
        ?? rawEntry.fileCopyConceptId
        ?? fallback.fileCopyConceptId
        ?? null
    );
    return {
        id,
        queueId,
        promptRaw: String(rawEntry.prompt_raw ?? rawEntry.promptRaw ?? fallback.promptRaw ?? ''),
        status: normaliseChatPromptQueueStatus(rawEntry.status ?? fallback.status),
        sessionId,
        sessionKey: getChatRequestSessionKey(sessionId),
        sessionName,
        fileCopyConceptId,
        localOnly: queueId ? false : rawEntry.localOnly === true,
        syncError: rawEntry.syncError || null,
        enqueueFailed: rawEntry.enqueueFailed === true || fallback.enqueueFailed === true,
        enqueueUnconfirmed: rawEntry.enqueueUnconfirmed === true
            || fallback.enqueueUnconfirmed === true,
        deleteInFlight: rawEntry.deleteInFlight === true || fallback.deleteInFlight === true,
        retryInFlight: rawEntry.retryInFlight === true || fallback.retryInFlight === true,
        retryRequestId: rawEntry.retryRequestId
            || fallback.retryRequestId
            || null,
        acceptedRetryRequestId: rawEntry.retry_request_id
            || rawEntry.acceptedRetryRequestId
            || fallback.acceptedRetryRequestId
            || null,
        retrySourceQueueId: rawEntry.retry_source_queue_id
            || rawEntry.retrySourceQueueId
            || fallback.retrySourceQueueId
            || null,
        retrySourceTaskExecutionConceptId: rawEntry.retry_source_task_execution_concept_id
            || rawEntry.retrySourceTaskExecutionConceptId
            || fallback.retrySourceTaskExecutionConceptId
            || null,
        retriedByQueueId: rawEntry.retried_by_queue_id
            || rawEntry.retriedByQueueId
            || fallback.retriedByQueueId
            || null,
        handoffSourceQueueId: rawEntry.handoff_source_queue_id
            || rawEntry.handoffSourceQueueId
            || fallback.handoffSourceQueueId
            || null,
        handoffCompletedAt: rawEntry.handoff_completed_at
            || rawEntry.handoffCompletedAt
            || fallback.handoffCompletedAt
            || null,
        handoffEnqueueSubmissionId: rawEntry.handoffEnqueueSubmissionId
            || fallback.handoffEnqueueSubmissionId
            || null,
        supersededByQueueId: rawEntry.supersededByQueueId
            || fallback.supersededByQueueId
            || null,
        lastError: rawEntry.last_error || rawEntry.lastError || null,
        enqueueSubmissionId: rawEntry.enqueue_submission_id
            || rawEntry.enqueueSubmissionId
            || fallback.enqueueSubmissionId
            || null,
        dispatchMode: rawEntry.dispatch_mode
            || rawEntry.dispatchMode
            || fallback.dispatchMode
            || null,
        dispatchReady: typeof rawEntry.dispatch_ready === 'boolean'
            ? rawEntry.dispatch_ready
            : (typeof rawEntry.dispatchReady === 'boolean'
                ? rawEntry.dispatchReady
                : (typeof fallback.dispatchReady === 'boolean'
                    ? fallback.dispatchReady
                    : null)),
        executionEnvelopeVersion: rawEntry.execution_envelope_version
            || rawEntry.executionEnvelopeVersion
            || fallback.executionEnvelopeVersion
            || null,
        executionEnvelope: rawEntry.execution_envelope
            || rawEntry.executionEnvelope
            || fallback.executionEnvelope
            || null,
        clientRequestId: rawEntry.client_request_id || rawEntry.clientRequestId || fallback.clientRequestId || null,
        attemptId: rawEntry.attempt_id || rawEntry.attemptId || fallback.attemptId || null,
        serverInstanceId: rawEntry.server_instance_id || rawEntry.serverInstanceId || fallback.serverInstanceId || null,
        leaseAcquiredAt: rawEntry.lease_acquired_at || rawEntry.leaseAcquiredAt || fallback.leaseAcquiredAt || null,
        leaseHeartbeatAt: rawEntry.lease_heartbeat_at || rawEntry.leaseHeartbeatAt || fallback.leaseHeartbeatAt || null,
        staleAdvisory: rawEntry.stale_advisory === true || rawEntry.staleAdvisory === true,
        staleAdvisoryReason: rawEntry.stale_advisory_reason || rawEntry.staleAdvisoryReason || fallback.staleAdvisoryReason || null,
        reconciliationRequired: rawEntry.reconciliation_required === true || rawEntry.reconciliationRequired === true,
        attemptCount: Number.isFinite(Number(rawEntry.attempt_count ?? rawEntry.attemptCount))
            ? Number(rawEntry.attempt_count ?? rawEntry.attemptCount)
            : 0,
        createdAt: rawEntry.created_at || rawEntry.createdAt || null,
        updatedAt: rawEntry.updated_at || rawEntry.updatedAt || null,
        queuedAt: rawEntry.queued_at || rawEntry.queuedAt || null,
        claimedAt: rawEntry.claimed_at || rawEntry.claimedAt || null,
        completedAt: rawEntry.completed_at || rawEntry.completedAt || null
    };
}

function getLiveChatRequestForPromptQueueRecord(queueId) {
    const cleanQueueId = (typeof queueId === 'string' && queueId.trim())
        ? queueId.trim()
        : null;
    if (!cleanQueueId) {
        return null;
    }
    for (const request of liveChatRequestsBySession.values()) {
        const requestQueueId = (typeof request?.promptQueueRecordId === 'string' && request.promptQueueRecordId.trim())
            ? request.promptQueueRecordId.trim()
            : null;
        if (requestQueueId === cleanQueueId) {
            return request;
        }
    }
    return null;
}

function getChatPromptQueueEntryVisibilityKey(entry) {
    if (!entry) {
        return null;
    }
    if (typeof entry.queueId === 'string' && entry.queueId.trim()) {
        return entry.queueId.trim();
    }
    if (typeof entry.id === 'string' && entry.id.trim()) {
        return entry.id.trim();
    }
    return null;
}

function isDisplayedChatPromptQueueEntry(entry) {
    if (!entry) {
        return false;
    }
    const visibilityKey = getChatPromptQueueEntryVisibilityKey(entry);
    if (visibilityKey && locallyHiddenChatPromptQueueEntryKeys.has(visibilityKey)) {
        return false;
    }
    if (
        entry.status === CHAT_PROMPT_QUEUE_STATUS_COMPLETED
        || entry.status === CHAT_PROMPT_QUEUE_STATUS_CANCELLED
    ) {
        return false;
    }
    const liveRequest = getLiveChatRequestForPromptQueueRecord(entry.queueId);
    if (liveRequest && isRequestInActiveChatSession(liveRequest)) {
        return false;
    }
    return true;
}

function isChatPromptQueueEntryForSession(
    entry,
    sessionId = activeChatSessionId
) {
    return Boolean(
        entry
        && entry.sessionKey === getChatRequestSessionKey(sessionId)
    );
}

function isServerDispatchedChatPromptQueueEntry(entry) {
    return entry?.dispatchMode === 'server';
}

function getChatPromptQueueEntryById(entryId) {
    const cleanEntryId = (typeof entryId === 'string' && entryId.trim())
        ? entryId.trim()
        : null;
    if (!cleanEntryId) {
        return null;
    }
    return queuedChatPrompts.find((entry) => entry?.id === cleanEntryId) || null;
}

function updateChatTaskQueueSelectionUi() {
    const panel = document.getElementById(CHAT_TASK_QUEUE_PANEL_ID);
    if (!panel) {
        return;
    }
    panel.querySelectorAll('.chat-task-queue-item').forEach((item) => {
        if (!(item instanceof HTMLElement)) {
            return;
        }
        const isSelected = !!selectedChatPromptQueueEntryId
            && item.getAttribute('data-queue-id') === selectedChatPromptQueueEntryId;
        item.classList.toggle('chat-task-queue-item-selected', isSelected);
        item.setAttribute('aria-selected', isSelected ? 'true' : 'false');
    });
}

function setSelectedChatPromptQueueEntryId(entryId) {
    const cleanEntryId = (typeof entryId === 'string' && entryId.trim())
        ? entryId.trim()
        : null;
    selectedChatPromptQueueEntryId = cleanEntryId;
    updateChatTaskQueueSelectionUi();
}

function hideChatPromptQueueEntryLocally(entry) {
    const visibilityKey = getChatPromptQueueEntryVisibilityKey(entry);
    if (visibilityKey) {
        locallyHiddenChatPromptQueueEntryKeys.add(visibilityKey);
    }
    if (entry?.id && selectedChatPromptQueueEntryId === entry.id) {
        selectedChatPromptQueueEntryId = null;
    }
    renderChatTaskQueuePanel();
    refreshChatSessionTabActivityIndicators();
    updateSendButtonForCurrentChatState();
}

function getSelectedChatPromptQueueEntryForSend() {
    const activeElement = document.activeElement;
    const activeQueueId = (
        activeElement instanceof HTMLTextAreaElement
        && activeElement.classList.contains('chat-task-queue-edit')
    )
        ? String(activeElement.dataset.queueId || '').trim()
        : null;
    const selectedId = activeQueueId || selectedChatPromptQueueEntryId;
    const entry = getChatPromptQueueEntryById(selectedId);
    if (
        !entry
        || !isDisplayedChatPromptQueueEntry(entry)
        || !isChatPromptQueueEntryForSession(entry)
        || isServerDispatchedChatPromptQueueEntry(entry)
        || entry.status === CHAT_PROMPT_QUEUE_STATUS_FAILED
        || entry.enqueueFailed === true
        || entry.handoffEnqueueSubmissionId
        || entry.supersededByQueueId
    ) {
        return null;
    }
    if (getLiveChatRequestForPromptQueueRecord(entry.queueId)) {
        return null;
    }
    if (
        entry.status !== CHAT_PROMPT_QUEUE_STATUS_QUEUED
    ) {
        return null;
    }
    if (typeof entry.promptRaw !== 'string' || !entry.promptRaw.trim()) {
        return null;
    }
    return entry;
}

async function fetchChatPromptQueueJson(path = '', options = {}) {
    const response = await fetch(`${CHAT_PROMPT_QUEUE_ENDPOINT}${path}`, {
        method: options.method || 'GET',
        headers: buildChatFetchHeaders({
            'Content-Type': 'application/json',
            ...(options.headers || {})
        }),
        body: options.body,
        signal: options.signal
    });
    let data = null;
    try {
        data = await response.json();
    } catch (_) {
        // Leave data as null when the endpoint returns an empty/non-JSON response.
    }
    if (!response.ok || data?.success === false) {
        const error = new Error(data?.error || `HTTP ${response.status}`);
        error.httpStatus = response.status;
        error.errorCode = data?.error_code
            || (data?.error === 'window_context_unavailable' ? data.error : null)
            || (response.status === 401 ? 'not_authenticated' : null);
        error.details = data?.details && typeof data.details === 'object' ? data.details : {};
        if (
            response.status === 409
            && error.errorCode === 'window_context_unavailable'
            && options.windowContextRepairAttempted !== true
        ) {
            await repairCurrentWindowOrganisationBinding();
            return fetchChatPromptQueueJson(path, {
                ...options,
                windowContextRepairAttempted: true
            });
        }
        throw error;
    }
    return data || {};
}

function describeChatPromptQueueApiError(error, fallbackMessage) {
    const code = typeof error?.errorCode === 'string' ? error.errorCode : null;
    const details = error?.details && typeof error.details === 'object' ? error.details : {};
    const currentStatus = typeof details.current_status === 'string' ? details.current_status : null;
    if (code === 'not_authenticated') {
        return 'Queue sync needs a signed-in browser session.';
    }
    if (code === 'backend_unavailable') {
        return 'Queue storage is temporarily unavailable.';
    }
    if (code === 'scope_mismatch') {
        return 'This queued task belongs to a different browser or organisation scope.';
    }
    if (code === 'wrong_state') {
        if (currentStatus === CHAT_PROMPT_QUEUE_STATUS_COMPLETED) {
            return 'This queued task already completed on the server.';
        }
        if (currentStatus === CHAT_PROMPT_QUEUE_STATUS_FAILED) {
            return 'This queued task is already marked failed on the server.';
        }
        if (currentStatus === CHAT_PROMPT_QUEUE_STATUS_CANCELLED) {
            return 'This queued task is already cancelled on the server.';
        }
        if (currentStatus === CHAT_PROMPT_QUEUE_STATUS_IN_PROGRESS) {
            return 'This queued task is already running on the server.';
        }
        return 'This queued task is no longer in the expected server state.';
    }
    if (code === 'not_found') {
        return 'This queued task is no longer on the server.';
    }
    if (code === 'invalid_input') {
        return 'This queued task could not be saved because its stored data is invalid.';
    }
    return fallbackMessage;
}

function isAmbiguousChatPromptQueueEnqueueError(error) {
    const status = Number(error?.httpStatus);
    return !Number.isInteger(status) || status >= 500;
}

function isCanonicalChatPromptQueueAbsenceError(error) {
    return error?.errorCode === 'not_found'
        || (
            error?.errorCode === 'wrong_state'
            && error?.details?.current_status === CHAT_PROMPT_QUEUE_STATUS_CANCELLED
        )
        || (
            Number(error?.httpStatus) === 404
            && error?.errorCode !== 'scope_mismatch'
        );
}

function publishChatPromptQueueChange(reason = 'changed') {
    try {
        localStorage.setItem(CHAT_PROMPT_QUEUE_SYNC_STORAGE_KEY, JSON.stringify({
            changed_at_ms: Date.now(),
            nonce: Math.random().toString(36).slice(2),
            reason
        }));
    } catch (_) {
        // Queue durability remains server-owned when browser storage is blocked.
    }
}

function handleChatPromptQueueStorageEvent(event) {
    if (event?.key !== CHAT_PROMPT_QUEUE_SYNC_STORAGE_KEY) {
        return;
    }
    // Storage events fire only in the other same-origin tabs. Refreshing the
    // actor/window-scoped canonical list is enough to unblock that tab's FIFO;
    // no prompt content or queue identifier is broadcast between documents.
    void refreshChatPromptQueueFromServer({ silent: true });
}

function isCanonicalChatPromptQueuePollingEntry(entry) {
    return Boolean(
        entry?.queueId
        && isServerDispatchedChatPromptQueueEntry(entry)
        && (
            entry.status === CHAT_PROMPT_QUEUE_STATUS_QUEUED
            || entry.status === CHAT_PROMPT_QUEUE_STATUS_IN_PROGRESS
        )
    );
}

function stopChatPromptQueuePolling({ abortInFlight = true } = {}) {
    if (chatPromptQueuePollTimerId !== null) {
        clearTimeout(chatPromptQueuePollTimerId);
        chatPromptQueuePollTimerId = null;
    }
    if (abortInFlight && chatPromptQueuePollAbortController) {
        const controller = chatPromptQueuePollAbortController;
        chatPromptQueuePollAbortController = null;
        chatPromptQueuePollInFlight = false;
        try {
            controller.abort();
        } catch (_) {
            // Ignore abort races; the controller identity still retires this poll.
        }
    }
}

function syncChatPromptQueuePolling() {
    const shouldPoll = (
        pendingChatOrganisationSwitchId === null
        && isDocumentVisibleForRealtimeConnections()
        && queuedChatPrompts.some(isCanonicalChatPromptQueuePollingEntry)
    );
    if (!shouldPoll) {
        stopChatPromptQueuePolling();
        return;
    }
    if (chatPromptQueuePollTimerId !== null || chatPromptQueuePollInFlight) {
        return;
    }
    chatPromptQueuePollTimerId = window.setTimeout(async () => {
        chatPromptQueuePollTimerId = null;
        const controller = new AbortController();
        chatPromptQueuePollAbortController = controller;
        chatPromptQueuePollInFlight = true;
        try {
            await refreshChatPromptQueueFromServer({
                silent: true,
                pollTriggered: true,
                signal: controller.signal
            });
        } finally {
            if (chatPromptQueuePollAbortController === controller) {
                chatPromptQueuePollAbortController = null;
                chatPromptQueuePollInFlight = false;
                syncChatPromptQueuePolling();
            }
        }
    }, CHAT_PROMPT_QUEUE_POLL_INTERVAL_MS);
}

function getChatPromptQueueStatusByIdForSession(entries, sessionId) {
    const statusById = new Map();
    const sessionKey = getChatRequestSessionKey(sessionId);
    entries.forEach((entry) => {
        if (
            !entry?.queueId
            || entry.sessionKey !== sessionKey
            || !isServerDispatchedChatPromptQueueEntry(entry)
        ) {
            return;
        }
        statusById.set(entry.queueId, entry.status);
    });
    return statusById;
}

function activeConversationQueueStateChanged(previousEntries, nextEntries) {
    const sessionId = normaliseHistorySessionId(activeChatSessionId);
    if (!sessionId) {
        return false;
    }
    const previousStatusById = getChatPromptQueueStatusByIdForSession(
        previousEntries,
        sessionId
    );
    if (previousStatusById.size === 0) {
        return false;
    }
    const nextStatusById = getChatPromptQueueStatusByIdForSession(
        nextEntries,
        sessionId
    );
    return Array.from(previousStatusById.entries()).some(([queueId, status]) => (
        (
            status === CHAT_PROMPT_QUEUE_STATUS_QUEUED
            || status === CHAT_PROMPT_QUEUE_STATUS_IN_PROGRESS
        )
        && nextStatusById.get(queueId) !== status
    ));
}

function isObservableServerDispatchedRetry(entry) {
    return Boolean(
        entry?.queueId
        && entry?.retrySourceQueueId
        && entry?.clientRequestId
        && entry?.attemptId
        && entry.status === CHAT_PROMPT_QUEUE_STATUS_IN_PROGRESS
        && isServerDispatchedChatPromptQueueEntry(entry)
        && isChatPromptQueueEntryForSession(entry)
    );
}

function syncServerDispatchedRetryObserver() {
    const entry = queuedChatPrompts.find((candidate) => (
        isObservableServerDispatchedRetry(candidate)
        && !getLiveChatRequestForPromptQueueRecord(candidate.queueId)
        && !liveChatRequestsBySession.has(candidate.sessionKey)
        && !serverDispatchedRetryObserversInFlight.has(candidate.queueId)
    ));
    if (!entry) {
        return false;
    }

    serverDispatchedRetryObserversInFlight.add(entry.queueId);
    void handleSendPrompt({
        promptOverride: entry.promptRaw,
        fromQueue: true,
        observeServerDispatch: true,
        sessionId: entry.sessionId || null,
        sessionName: entry.sessionName || null,
        promptQueueRecordId: entry.queueId,
        enqueueSubmissionId: entry.enqueueSubmissionId || null,
        clientRequestId: entry.clientRequestId,
        attemptId: entry.attemptId,
        fileCopyConceptId: entry.fileCopyConceptId || null,
        claimedAt: entry.claimedAt || null
    }).finally(() => {
        serverDispatchedRetryObserversInFlight.delete(entry.queueId);
    });
    return true;
}

function refreshActiveConversationHistoryAfterQueueChange() {
    const sessionId = normaliseHistorySessionId(activeChatSessionId);
    if (!sessionId) {
        return;
    }
    invalidateSessionHistoryCache(sessionId);
    scheduleSharedHistoryResync(sessionId);
}

function mergePersistedChatPromptQueueEntry(entry) {
    const normalised = normaliseChatPromptQueueEntry(entry);
    if (!normalised) {
        return null;
    }
    const existingIndex = queuedChatPrompts.findIndex((candidate) => (
        (normalised.queueId && candidate.queueId === normalised.queueId)
        || (
            normalised.enqueueSubmissionId
            && candidate.enqueueSubmissionId === normalised.enqueueSubmissionId
        )
        || candidate.id === normalised.id
    ));
    if (existingIndex >= 0) {
        queuedChatPrompts[existingIndex] = {
            ...queuedChatPrompts[existingIndex],
            ...normalised
        };
    } else {
        queuedChatPrompts.push(normalised);
    }
    syncChatPromptQueuePolling();
    return normalised;
}

async function refreshChatPromptQueueFromServer(options = {}) {
    if (pendingChatOrganisationSwitchId !== null) {
        return false;
    }
    const organisationGenerationAtStart = chatOrganisationGeneration;
    const previousEntries = [...queuedChatPrompts];
    try {
        const data = await fetchChatPromptQueueJson('', {
            signal: options.signal
        });
        if (!isChatOrganisationRequestCurrent(organisationGenerationAtStart)) {
            return false;
        }
        chatPromptQueueAdmissionServerInstanceId = (
            typeof data?.turn_admission?.server_instance_id === 'string'
            && data.turn_admission.server_instance_id.trim()
        )
            ? data.turn_admission.server_instance_id.trim()
            : null;
        const existingByQueueId = new Map(
            queuedChatPrompts
                .filter((entry) => entry?.queueId)
                .map((entry) => [entry.queueId, entry])
        );
        const canonicalPersistedEntries = Array.isArray(data.items)
            ? data.items
                .map((item) => normaliseChatPromptQueueEntry(
                    item,
                    existingByQueueId.get(item?.queue_id) || {}
                ))
                .filter(Boolean)
            : [];
        const canonicalRecentFailedEntries = Array.isArray(data.recent_failed_items)
            ? data.recent_failed_items
                .map((item) => normaliseChatPromptQueueEntry(
                    item,
                    existingByQueueId.get(item?.queue_id) || {}
                ))
                .filter(Boolean)
            : [];
        const recentFailedQueueIds = new Set(
            canonicalRecentFailedEntries
                .map((entry) => entry?.queueId)
                .filter(Boolean)
        );
        const persistedEntries = canonicalPersistedEntries
            .filter((entry) => !entry?.queueId || !recentFailedQueueIds.has(entry.queueId))
            .filter(isDisplayedChatPromptQueueEntry);
        const recentFailedEntries = canonicalRecentFailedEntries
            .filter(isDisplayedChatPromptQueueEntry);
        const canonicalSubmissionIds = new Set(
            [...persistedEntries, ...recentFailedEntries]
                .map((entry) => entry?.enqueueSubmissionId)
                .filter(Boolean)
        );
        const localOnlyEntries = queuedChatPrompts.filter((entry) => (
            entry?.localOnly === true
            && (
                !entry.enqueueSubmissionId
                || !canonicalSubmissionIds.has(entry.enqueueSubmissionId)
            )
        ));
        queuedChatPrompts = [...persistedEntries, ...localOnlyEntries, ...recentFailedEntries];
        const shouldRefreshActiveHistory = activeConversationQueueStateChanged(
            previousEntries,
            queuedChatPrompts
        );
        renderChatTaskQueuePanel();
        refreshChatSessionTabActivityIndicators();
        updateSendButtonForCurrentChatState();
        syncServerDispatchedRetryObserver();
        syncChatPromptQueuePolling();
        if (shouldRefreshActiveHistory) {
            refreshActiveConversationHistoryAfterQueueChange();
        }
        return {
            items: canonicalPersistedEntries,
            recentFailedItems: canonicalRecentFailedEntries
        };
    } catch (error) {
        if (!isChatOrganisationRequestCurrent(organisationGenerationAtStart)) {
            return false;
        }
        if (!options.silent && error?.name !== 'AbortError') {
            console.warn('[chatTab] Unable to load persisted chat prompt queue:', error);
        }
        return false;
    } finally {
        syncChatPromptQueuePolling();
    }
}

function buildChatPromptExecutionEnvelope({
    fileCopyConceptId = null,
    turnKind = null,
    initiationId = null
} = {}) {
    const userContext = getUserContext() || {};
    const localModelRequestFields = buildLocalModelRequestFields(
        resolveLocalRequestedLlm()
    );
    return {
        ...(turnKind ? { turn_kind: turnKind } : {}),
        ...(initiationId ? { initiation_id: initiationId } : {}),
        language: (typeof userContext.language === 'string' && userContext.language.trim())
            ? userContext.language.trim()
            : 'en-NZ',
        ...localModelRequestFields,
        ...(fileCopyConceptId ? {
            workflow_inputs: {
                file_copy_concept_id: fileCopyConceptId
            }
        } : {}),
        presenter_mode: true,
        skip_buttonify: false,
        thinking_card_mode: getThinkingCardMode()
    };
}

async function createPersistedChatPromptQueueEntry(entry, status = CHAT_PROMPT_QUEUE_STATUS_QUEUED) {
    const serverDispatch = isServerDispatchedChatPromptQueueEntry(entry);
    let enqueueSubmissionId = null;
    if (serverDispatch) {
        enqueueSubmissionId = (
            typeof entry?.enqueueSubmissionId === 'string'
            && entry.enqueueSubmissionId.trim()
        )
            ? entry.enqueueSubmissionId.trim()
            : createClientRequestId();
        entry.enqueueSubmissionId = enqueueSubmissionId;
    }
    const body = {
        prompt_raw: entry.promptRaw,
        session_id: entry.sessionId || null,
        session_name: entry.sessionName || null,
        status
    };
    if (serverDispatch) {
        Object.assign(body, {
            enqueue_submission_id: enqueueSubmissionId,
            dispatch_mode: 'server',
            execution_envelope_version: 1,
            execution_envelope: (
                entry.executionEnvelope
                && typeof entry.executionEnvelope === 'object'
                && !Array.isArray(entry.executionEnvelope)
            )
                ? entry.executionEnvelope
                : {}
        });
        if (
            typeof entry?.handoffSourceQueueId === 'string'
            && entry.handoffSourceQueueId.trim()
        ) {
            body.handoff_source_queue_id = entry.handoffSourceQueueId.trim();
        }
    } else {
        Object.assign(body, {
            client_request_id: entry.clientRequestId || null,
            attempt_id: entry.attemptId || null
        });
    }
    const data = await fetchChatPromptQueueJson('', {
        method: 'POST',
        body: JSON.stringify(body)
    });
    if (!data.item) {
        throw new Error('Queue persistence returned no canonical record.');
    }
    return normaliseChatPromptQueueEntry(data.item, entry);
}

async function persistQueuedPromptUpdateNow(entry) {
    if (
        !entry?.queueId
        || entry.status !== CHAT_PROMPT_QUEUE_STATUS_QUEUED
        || isServerDispatchedChatPromptQueueEntry(entry)
    ) {
        return entry;
    }
    const existingTimer = queuedChatPromptSyncTimers.get(entry.id);
    if (existingTimer !== undefined) {
        clearTimeout(existingTimer);
        queuedChatPromptSyncTimers.delete(entry.id);
    }
    const data = await fetchChatPromptQueueJson(`/${encodeURIComponent(entry.queueId)}`, {
        method: 'PATCH',
        body: JSON.stringify({
            prompt_raw: entry.promptRaw,
            session_id: entry.sessionId || null,
            session_name: entry.sessionName || null
        })
    });
    return data.item ? normaliseChatPromptQueueEntry(data.item, entry) : entry;
}

function schedulePersistedQueuedPromptUpdate(entry) {
    if (
        !entry?.queueId
        || entry.status !== CHAT_PROMPT_QUEUE_STATUS_QUEUED
        || isServerDispatchedChatPromptQueueEntry(entry)
    ) {
        return;
    }
    const existingTimer = queuedChatPromptSyncTimers.get(entry.id);
    if (existingTimer !== undefined) {
        clearTimeout(existingTimer);
    }
    queuedChatPromptSyncTimers.set(entry.id, setTimeout(async () => {
        queuedChatPromptSyncTimers.delete(entry.id);
        try {
            const updated = await persistQueuedPromptUpdateNow(entry);
            if (updated) {
                mergePersistedChatPromptQueueEntry(updated);
                renderChatTaskQueuePanel();
            }
        } catch (error) {
            entry.syncError = describeChatPromptQueueApiError(
                error,
                'Queued edit is not saved on the server yet.'
            );
            console.warn('[chatTab] Unable to update persisted queued prompt:', error);
            renderChatTaskQueuePanel();
        }
    }, 300));
}

async function deletePersistedChatPromptQueueEntry(entry) {
    if (!entry?.queueId) {
        return true;
    }
    try {
        await fetchChatPromptQueueJson(`/${encodeURIComponent(entry.queueId)}`, {
            method: 'DELETE'
        });
    } catch (error) {
        if (!isCanonicalChatPromptQueueAbsenceError(error)) {
            throw error;
        }
    }
    return true;
}

async function retryFailedChatPromptQueueEntry(entry) {
    if (!entry?.queueId) {
        throw new Error('The canonical failed queue record is unavailable.');
    }
    const retryRequestId = (
        typeof entry.retryRequestId === 'string'
        && entry.retryRequestId.trim()
    )
        ? entry.retryRequestId.trim()
        : createClientRequestId();
    entry.retryRequestId = retryRequestId;
    const data = await fetchChatPromptQueueJson(
        `/${encodeURIComponent(entry.queueId)}/retry`,
        {
            method: 'POST',
            body: JSON.stringify({ retry_request_id: retryRequestId })
        }
    );
    if (!data.item) {
        throw new Error('Retry returned no canonical successor.');
    }
    return normaliseChatPromptQueueEntry(data.item);
}

async function completePersistedChatPromptQueueHandoff(entry) {
    if (!entry?.queueId) {
        throw new Error('The canonical handoff queue record is unavailable.');
    }
    const data = await fetchChatPromptQueueJson(
        `/${encodeURIComponent(entry.queueId)}/complete-handoff`,
        { method: 'POST' }
    );
    if (!data.item) {
        throw new Error('Queue handoff returned no canonical record.');
    }
    return normaliseChatPromptQueueEntry(data.item, entry);
}

function isPendingServerDispatchHandoff(entry) {
    return Boolean(
        entry?.handoffSourceQueueId
        && isServerDispatchedChatPromptQueueEntry(entry)
        && entry.dispatchReady === false
        && entry.status === CHAT_PROMPT_QUEUE_STATUS_QUEUED
    );
}

async function cancelUnresolvedChatPromptQueueHandoff(entry) {
    const sourceQueueId = (
        typeof entry?.handoffSourceQueueId === 'string'
        && entry.handoffSourceQueueId.trim()
    )
        ? entry.handoffSourceQueueId.trim()
        : null;
    const enqueueSubmissionId = (
        typeof entry?.enqueueSubmissionId === 'string'
        && entry.enqueueSubmissionId.trim()
    )
        ? entry.enqueueSubmissionId.trim()
        : null;
    if (!sourceQueueId) {
        throw new Error('The durable handoff source is unavailable.');
    }

    const data = await fetchChatPromptQueueJson('');
    const canonicalEntries = [
        ...(Array.isArray(data?.items) ? data.items : []),
        ...(Array.isArray(data?.recent_failed_items) ? data.recent_failed_items : [])
    ]
        .map((item) => normaliseChatPromptQueueEntry(item))
        .filter(Boolean);
    const replacementQueueIds = new Set();
    if (entry?.queueId && entry.queueId !== sourceQueueId) {
        replacementQueueIds.add(entry.queueId);
    }
    canonicalEntries.forEach((candidate) => {
        if (
            candidate.queueId
            && candidate.queueId !== sourceQueueId
            && enqueueSubmissionId
            && candidate.enqueueSubmissionId === enqueueSubmissionId
        ) {
            replacementQueueIds.add(candidate.queueId);
        }
    });

    // Cancel the dispatch-ineligible replacement first. The durable server
    // handoff guarantees it cannot start before its exact source is retired.
    for (const queueId of replacementQueueIds) {
        await deletePersistedChatPromptQueueEntry({ queueId });
    }
    await deletePersistedChatPromptQueueEntry({ queueId: sourceQueueId });

    queuedChatPrompts = queuedChatPrompts.filter((candidate) => (
        candidate?.queueId !== sourceQueueId
        && !replacementQueueIds.has(candidate?.queueId)
        && (
            !enqueueSubmissionId
            || candidate?.enqueueSubmissionId !== enqueueSubmissionId
            || !candidate?.handoffSourceQueueId
        )
        && (
            !enqueueSubmissionId
            || candidate?.handoffEnqueueSubmissionId !== enqueueSubmissionId
        )
    ));
    if (!getChatPromptQueueEntryById(selectedChatPromptQueueEntryId)) {
        selectedChatPromptQueueEntryId = null;
    }
    publishChatPromptQueueChange('queue_handoff_cancelled');
    renderChatTaskQueuePanel();
    refreshChatSessionTabActivityIndicators();
    updateSendButtonForCurrentChatState();
}

function ensureAdmissionDeferredSourceQueueEntry(
    handoffEntry,
    { replacementQueueId = null, syncError = null } = {}
) {
    const sourceQueueId = (
        typeof handoffEntry?.handoffSourceQueueId === 'string'
        && handoffEntry.handoffSourceQueueId.trim()
    )
        ? handoffEntry.handoffSourceQueueId.trim()
        : null;
    if (!sourceQueueId) {
        return null;
    }
    const existingIndex = queuedChatPrompts.findIndex((entry) => (
        entry?.queueId === sourceQueueId
    ));
    const existing = existingIndex >= 0 ? queuedChatPrompts[existingIndex] : {};
    const sourceEntry = normaliseChatPromptQueueEntry({
        queue_id: sourceQueueId,
        prompt_raw: handoffEntry.promptRaw,
        session_id: handoffEntry.sessionId,
        session_name: handoffEntry.sessionName,
        status: CHAT_PROMPT_QUEUE_STATUS_QUEUED,
        handoffEnqueueSubmissionId: handoffEntry.enqueueSubmissionId,
        supersededByQueueId: replacementQueueId
    }, existing);
    if (!sourceEntry) {
        return null;
    }
    sourceEntry.syncError = syncError || existing.syncError || null;
    if (existingIndex >= 0) {
        queuedChatPrompts[existingIndex] = sourceEntry;
    } else {
        queuedChatPrompts.push(sourceEntry);
    }
    return sourceEntry;
}

async function retireAdmissionDeferredSourceAfterCanonicalEnqueue(
    handoffEntry,
    persistedEntry
) {
    const sourceQueueId = (
        typeof handoffEntry?.handoffSourceQueueId === 'string'
        && handoffEntry.handoffSourceQueueId.trim()
    )
        ? handoffEntry.handoffSourceQueueId.trim()
        : null;
    const replacementQueueId = (
        typeof persistedEntry?.queueId === 'string'
        && persistedEntry.queueId.trim()
    )
        ? persistedEntry.queueId.trim()
        : null;
    if (!sourceQueueId || !replacementQueueId || sourceQueueId === replacementQueueId) {
        return false;
    }

    if (
        persistedEntry?.dispatchReady === true
        && persistedEntry?.handoffSourceQueueId === sourceQueueId
    ) {
        // The v2 server handoff activates a replacement only after the exact
        // source has been cancelled and read back. Do not issue a second
        // browser-owned cancellation or retain a phantom source row.
        queuedChatPrompts = queuedChatPrompts.filter((entry) => (
            entry?.queueId !== sourceQueueId
        ));
        publishChatPromptQueueChange('foreground_prompt_replaced_by_server_queue');
        renderChatTaskQueuePanel();
        refreshChatSessionTabActivityIndicators();
        updateSendButtonForCurrentChatState();
        return true;
    }

    // Keep the source visible and non-dispatchable during the non-atomic
    // cleanup window. It is removed from the client projection only after the
    // canonical DELETE acknowledges cancellation.
    ensureAdmissionDeferredSourceQueueEntry(handoffEntry, {
        replacementQueueId
    });
    renderChatTaskQueuePanel();
    refreshChatSessionTabActivityIndicators();
    updateSendButtonForCurrentChatState();

    try {
        await deletePersistedChatPromptQueueEntry({ queueId: sourceQueueId });
        queuedChatPrompts = queuedChatPrompts.filter((entry) => (
            entry?.queueId !== sourceQueueId
        ));
        const replacement = queuedChatPrompts.find((entry) => (
            entry?.queueId === replacementQueueId
        ));
        if (replacement) {
            replacement.handoffSourceQueueId = null;
        }
        publishChatPromptQueueChange('foreground_prompt_replaced_by_server_queue');
        renderChatTaskQueuePanel();
        refreshChatSessionTabActivityIndicators();
        updateSendButtonForCurrentChatState();
        return true;
    } catch (error) {
        const sourceEntry = ensureAdmissionDeferredSourceQueueEntry(handoffEntry, {
            replacementQueueId,
            syncError: describeChatPromptQueueApiError(
                error,
                'The prior queue record could not be retired on the server.'
            )
        });
        if (sourceEntry) {
            sourceEntry.deleteInFlight = false;
        }
        console.warn(
            '[chatTab] Unable to retire foreground queue record after server enqueue:',
            error
        );
        renderChatTaskQueuePanel();
        refreshChatSessionTabActivityIndicators();
        updateSendButtonForCurrentChatState();
        return false;
    }
}

async function requeuePersistedChatPromptQueueEntry(entry) {
    if (!entry?.queueId) {
        return entry;
    }
    const data = await fetchChatPromptQueueJson(`/${encodeURIComponent(entry.queueId)}/requeue`, {
        method: 'POST'
    });
    return data.item ? normaliseChatPromptQueueEntry(data.item, entry) : entry;
}

function createQueuedChatPromptId() {
    queuedChatPromptCounter += 1;
    return `queued-${Date.now()}-${queuedChatPromptCounter}`;
}

function ensureChatTaskQueuePanel() {
    const promptInput = getPromptInputElement();
    if (!promptInput || !promptInput.parentElement) {
        return null;
    }

    let panel = document.getElementById(CHAT_TASK_QUEUE_PANEL_ID);
    if (!panel) {
        panel = document.createElement('section');
        panel.id = CHAT_TASK_QUEUE_PANEL_ID;
        panel.className = 'chat-task-queue-panel hidden';
        panel.setAttribute('aria-live', 'polite');
        panel.setAttribute('aria-label', 'Conversation activity and queued prompts');
        panel.innerHTML = `
            <div class="chat-task-queue-header">
                <span class="chat-task-queue-title">Conversation activity</span>
                <span id="${CHAT_TASK_QUEUE_COUNT_ID}" class="chat-task-queue-count">0 queued</span>
            </div>
            <div id="${CHAT_TASK_QUEUE_LIST_ID}" class="chat-task-queue-list"></div>
        `;
        promptInput.insertAdjacentElement('afterend', panel);
    }

    if (panel.dataset.bound !== '1') {
        panel.dataset.bound = '1';

        panel.addEventListener('focusin', (event) => {
            const target = event.target;
            if (
                target instanceof HTMLTextAreaElement
                && target.classList.contains('chat-task-queue-edit')
            ) {
                setSelectedChatPromptQueueEntryId(String(target.dataset.queueId || '').trim());
            }
        });

        panel.addEventListener('mousedown', (event) => {
            const target = event.target;
            if (!(target instanceof HTMLElement)) {
                return;
            }
            const item = target.closest('.chat-task-queue-item');
            if (item instanceof HTMLElement) {
                setSelectedChatPromptQueueEntryId(String(item.getAttribute('data-queue-id') || '').trim());
            }
        });

        panel.addEventListener('input', (event) => {
            const target = event.target;
            if (!(target instanceof HTMLTextAreaElement)) {
                return;
            }
            if (!target.classList.contains('chat-task-queue-edit')) {
                return;
            }
            const queueId = String(target.dataset.queueId || '').trim();
            if (!queueId) {
                return;
            }
            const queued = queuedChatPrompts.find((entry) => entry.id === queueId);
            if (!queued || isServerDispatchedChatPromptQueueEntry(queued)) {
                if (queued) {
                    target.value = queued.promptRaw;
                }
                return;
            }
            queued.promptRaw = target.value;
            queued.syncError = null;
            schedulePersistedQueuedPromptUpdate(queued);
        });

        panel.addEventListener('click', (event) => {
            const target = event.target;
            if (!(target instanceof HTMLElement)) {
                return;
            }
            const handoffCompleteButton = target.closest('.chat-task-queue-handoff-complete');
            if (handoffCompleteButton) {
                const queueId = String(
                    handoffCompleteButton.getAttribute('data-queue-id') || ''
                ).trim();
                const queued = queuedChatPrompts.find((entry) => entry.id === queueId);
                if (!queued || !isPendingServerDispatchHandoff(queued)) {
                    return;
                }
                handoffCompleteButton.disabled = true;
                void (async () => {
                    try {
                        const completed = await completePersistedChatPromptQueueHandoff(queued);
                        mergePersistedChatPromptQueueEntry(completed);
                        await retireAdmissionDeferredSourceAfterCanonicalEnqueue(
                            queued,
                            completed
                        );
                        publishChatPromptQueueChange('queue_handoff_completed');
                        renderChatTaskQueuePanel();
                        refreshChatSessionTabActivityIndicators();
                        updateSendButtonForCurrentChatState();
                    } catch (error) {
                        queued.syncError = describeChatPromptQueueApiError(
                            error,
                            'Queue handoff could not be completed on the server.'
                        );
                        renderChatTaskQueuePanel();
                    }
                })();
                return;
            }
            const handoffCancelButton = target.closest('.chat-task-queue-handoff-cancel');
            if (handoffCancelButton) {
                const queueId = String(
                    handoffCancelButton.getAttribute('data-queue-id') || ''
                ).trim();
                const queued = queuedChatPrompts.find((entry) => entry.id === queueId);
                if (
                    !queued
                    || !queued.handoffSourceQueueId
                    || queued.deleteInFlight === true
                ) {
                    return;
                }
                queued.deleteInFlight = true;
                queued.syncError = null;
                renderChatTaskQueuePanel();
                void (async () => {
                    try {
                        await cancelUnresolvedChatPromptQueueHandoff(queued);
                    } catch (error) {
                        queued.deleteInFlight = false;
                        queued.syncError = describeChatPromptQueueApiError(
                            error,
                            'The unresolved queue handoff could not be cancelled.'
                        );
                        renderChatTaskQueuePanel();
                    }
                })();
                return;
            }
            const enqueueRetryButton = target.closest('.chat-task-queue-enqueue-retry');
            if (enqueueRetryButton) {
                const queueId = String(enqueueRetryButton.getAttribute('data-queue-id') || '').trim();
                const queued = queuedChatPrompts.find((entry) => entry.id === queueId);
                if (!queued || queued.enqueueFailed !== true) {
                    return;
                }
                enqueueRetryButton.disabled = true;
                void (async () => {
                    try {
                        const persisted = await createPersistedChatPromptQueueEntry(queued);
                        if (!persisted) {
                            throw new Error('Queue persistence returned no record.');
                        }
                        const index = queuedChatPrompts.findIndex((entry) => entry.id === queued.id);
                        if (index >= 0) {
                            queuedChatPrompts[index] = {
                                ...queued,
                                ...persisted,
                                enqueueFailed: false,
                                enqueueUnconfirmed: false,
                                syncError: null,
                                id: persisted.id || queued.id
                            };
                        }
                        await retireAdmissionDeferredSourceAfterCanonicalEnqueue(
                            queued,
                            persisted
                        );
                        renderChatTaskQueuePanel();
                        refreshChatSessionTabActivityIndicators();
                        updateSendButtonForCurrentChatState();
                        publishChatPromptQueueChange('queued_prompt_retry_saved');
                        syncChatPromptQueuePolling();
                    } catch (error) {
                        queued.enqueueUnconfirmed = isAmbiguousChatPromptQueueEnqueueError(error);
                        queued.syncError = describeChatPromptQueueApiError(
                            error,
                            queued.enqueueUnconfirmed
                                ? 'Queue acknowledgement was not received. Retry safely to reconcile this exact prompt.'
                                : 'Prompt was not queued. Retry when queue storage is available.'
                        );
                        renderChatTaskQueuePanel();
                    }
                })();
                return;
            }
            const restartButton = target.closest('.chat-task-queue-restart');
            if (restartButton) {
                const queueId = String(restartButton.getAttribute('data-queue-id') || '').trim();
                if (!queueId) {
                    return;
                }
                const queued = queuedChatPrompts.find((entry) => entry.id === queueId);
                if (!queued) {
                    return;
                }
                setSelectedChatPromptQueueEntryId(queued.id);
                restartButton.disabled = true;
                void (async () => {
                    try {
                        const requeued = await requeuePersistedChatPromptQueueEntry(queued);
                        mergePersistedChatPromptQueueEntry({
                            ...queued,
                            ...requeued,
                            status: CHAT_PROMPT_QUEUE_STATUS_QUEUED
                        });
                        renderChatTaskQueuePanel();
                        refreshChatSessionTabActivityIndicators();
                        updateSendButtonForCurrentChatState();
                        publishChatPromptQueueChange('queued_prompt_restarted');
                        syncChatPromptQueuePolling();
                    } catch (error) {
                        queued.syncError = describeChatPromptQueueApiError(
                            error,
                            'Restart could not be saved on the server.'
                        );
                        console.warn('[chatTab] Unable to restart persisted prompt:', error);
                        renderChatTaskQueuePanel();
                    }
                })();
                return;
            }
            const dismissButton = target.closest('.chat-task-queue-dismiss');
            if (dismissButton) {
                const queueId = String(dismissButton.getAttribute('data-queue-id') || '').trim();
                if (!queueId) {
                    return;
                }
                const queued = queuedChatPrompts.find((entry) => entry.id === queueId);
                if (
                    !queued
                    || queued.status !== CHAT_PROMPT_QUEUE_STATUS_FAILED
                    || queued.retryInFlight === true
                ) {
                    return;
                }
                queued.deleteInFlight = true;
                queued.syncError = null;
                dismissButton.disabled = true;
                renderChatTaskQueuePanel();
                void (async () => {
                    try {
                        await deletePersistedChatPromptQueueEntry(queued);
                        queuedChatPrompts = queuedChatPrompts.filter((entry) => entry.id !== queued.id);
                        if (selectedChatPromptQueueEntryId === queued.id) {
                            selectedChatPromptQueueEntryId = null;
                        }
                        renderChatTaskQueuePanel();
                        refreshChatSessionTabActivityIndicators();
                        updateSendButtonForCurrentChatState();
                        publishChatPromptQueueChange('failed_prompt_dismissed');
                    } catch (error) {
                        queued.deleteInFlight = false;
                        queued.syncError = describeChatPromptQueueApiError(
                            error,
                            'Failed task could not be dismissed on the server.'
                        );
                        console.warn('[chatTab] Unable to dismiss failed prompt:', error);
                        renderChatTaskQueuePanel();
                    }
                })();
                return;
            }
            const failedRetryButton = target.closest('.chat-task-queue-failed-retry');
            if (failedRetryButton) {
                const queueId = String(
                    failedRetryButton.getAttribute('data-queue-id') || ''
                ).trim();
                const failedEntry = queuedChatPrompts.find(
                    (entry) => entry.id === queueId
                );
                if (
                    !failedEntry
                    || failedEntry.status !== CHAT_PROMPT_QUEUE_STATUS_FAILED
                    || failedEntry.retryInFlight === true
                    || failedEntry.deleteInFlight === true
                ) {
                    return;
                }
                failedEntry.retryInFlight = true;
                failedEntry.syncError = null;
                renderChatTaskQueuePanel();
                void (async () => {
                    try {
                        const successor = await retryFailedChatPromptQueueEntry(
                            failedEntry
                        );
                        queuedChatPrompts = queuedChatPrompts.filter((entry) => (
                            entry.id !== failedEntry.id
                            && entry.queueId !== failedEntry.queueId
                        ));
                        const merged = mergePersistedChatPromptQueueEntry(successor);
                        selectedChatPromptQueueEntryId = merged?.id || null;
                        publishChatPromptQueueChange('failed_prompt_retried');
                        renderChatTaskQueuePanel();
                        refreshChatSessionTabActivityIndicators();
                        updateSendButtonForCurrentChatState();
                        syncChatPromptQueuePolling();
                    } catch (error) {
                        failedEntry.retryInFlight = false;
                        failedEntry.syncError = describeChatPromptQueueApiError(
                            error,
                            'Failed task could not be retried on the server.'
                        );
                        console.warn('[chatTab] Unable to retry failed prompt:', error);
                        renderChatTaskQueuePanel();
                    }
                })();
                return;
            }
            const deleteButton = target.closest('.chat-task-queue-delete');
            if (!deleteButton) {
                return;
            }
            const queueId = String(deleteButton.getAttribute('data-queue-id') || '').trim();
            if (!queueId) {
                return;
            }
            const queued = queuedChatPrompts.find((entry) => entry.id === queueId);
            if (!queued || queued.deleteInFlight === true) {
                return;
            }
            if (!queued.queueId) {
                queuedChatPrompts = queuedChatPrompts.filter((entry) => entry.id !== queueId);
                renderChatTaskQueuePanel();
                refreshChatSessionTabActivityIndicators();
                updateSendButtonForCurrentChatState();
                return;
            }
            queued.deleteInFlight = true;
            queued.syncError = null;
            renderChatTaskQueuePanel();
            void (async () => {
                try {
                    await deletePersistedChatPromptQueueEntry(queued);
                    queuedChatPrompts = queuedChatPrompts.filter((entry) => (
                        entry.id !== queueId
                        && entry.queueId !== queued.queueId
                    ));
                    if (selectedChatPromptQueueEntryId === queueId) {
                        selectedChatPromptQueueEntryId = null;
                    }
                    publishChatPromptQueueChange('queued_prompt_deleted');
                } catch (error) {
                    const retained = queuedChatPrompts.find((entry) => (
                        entry.id === queueId
                        || entry.queueId === queued.queueId
                    )) || queued;
                    retained.deleteInFlight = false;
                    retained.syncError = describeChatPromptQueueApiError(
                        error,
                        'Queued task could not be deleted on the server.'
                    );
                    console.warn('[chatTab] Unable to delete persisted queued prompt:', error);
                }
                renderChatTaskQueuePanel();
                refreshChatSessionTabActivityIndicators();
                updateSendButtonForCurrentChatState();
            })();
        });
    }

    const list = panel.querySelector(`#${CHAT_TASK_QUEUE_LIST_ID}`);
    const count = panel.querySelector(`#${CHAT_TASK_QUEUE_COUNT_ID}`);
    if (!(list instanceof HTMLElement) || !(count instanceof HTMLElement)) {
        return null;
    }

    return { panel, list, count };
}

function renderChatTaskQueuePanel() {
    const elements = ensureChatTaskQueuePanel();
    if (!elements) {
        return;
    }

    const { panel, list, count } = elements;
    const displayEntries = queuedChatPrompts.filter((entry) => (
        isDisplayedChatPromptQueueEntry(entry)
        && isChatPromptQueueEntryForSession(entry)
    ));
    const queueSize = displayEntries.length;
    let runningCount = 0;
    let interruptedCount = 0;
    let failedCount = 0;
    let queuedCount = 0;
    let enqueueFailedCount = 0;
    let enqueueUnconfirmedCount = 0;
    let cleanupPendingCount = 0;
    displayEntries.forEach((entry) => {
        if (
            entry.supersededByQueueId
            || entry.handoffEnqueueSubmissionId
            || isPendingServerDispatchHandoff(entry)
        ) {
            cleanupPendingCount += 1;
        } else if (entry.enqueueFailed === true) {
            enqueueFailedCount += 1;
            if (entry.enqueueUnconfirmed === true) {
                enqueueUnconfirmedCount += 1;
            }
        } else if (isRunningChatPromptQueueEntry(entry)) {
            runningCount += 1;
        } else if (isRestartableChatPromptQueueEntry(entry)) {
            interruptedCount += 1;
        } else if (entry.status === CHAT_PROMPT_QUEUE_STATUS_FAILED) {
            failedCount += 1;
        } else {
            queuedCount += 1;
        }
    });

    if (queueSize === 0) {
        count.textContent = '0 queued';
    } else {
        const countParts = [];
        if (runningCount > 0) {
            countParts.push(runningCount === 1 ? '1 running' : `${runningCount} running`);
        }
        if (queuedCount > 0) {
            countParts.push(queuedCount === 1 ? '1 queued' : `${queuedCount} queued`);
        }
        if (interruptedCount > 0) {
            countParts.push(interruptedCount === 1 ? '1 restartable' : `${interruptedCount} restartable`);
        }
        if (failedCount > 0) {
            countParts.push(failedCount === 1 ? '1 failed' : `${failedCount} failed`);
        }
        if (enqueueFailedCount > 0) {
            const definitelyFailedCount = enqueueFailedCount - enqueueUnconfirmedCount;
            if (enqueueUnconfirmedCount > 0) {
                countParts.push(enqueueUnconfirmedCount === 1
                    ? '1 queue unconfirmed'
                    : `${enqueueUnconfirmedCount} queues unconfirmed`);
            }
            if (definitelyFailedCount > 0) {
                countParts.push(definitelyFailedCount === 1
                    ? '1 not queued'
                    : `${definitelyFailedCount} not queued`);
            }
        }
        if (cleanupPendingCount > 0) {
            countParts.push(cleanupPendingCount === 1 ? '1 handoff pending' : `${cleanupPendingCount} handoffs pending`);
        }
        count.textContent = countParts.join(', ');
    }
    list.innerHTML = '';

    if (queueSize === 0) {
        panel.classList.add('hidden');
        return;
    }

    panel.classList.remove('hidden');

    let queuedOrdinal = 0;
    displayEntries.forEach((entry, index) => {
        const isRunning = isRunningChatPromptQueueEntry(entry);
        const isInterrupted = isRestartableChatPromptQueueEntry(entry);
        const isFailed = !isRunning && entry.status === CHAT_PROMPT_QUEUE_STATUS_FAILED;
        const isServerDispatched = isServerDispatchedChatPromptQueueEntry(entry);
        const isEnqueueFailed = entry.enqueueFailed === true;
        const isEnqueueUnconfirmed = entry.enqueueUnconfirmed === true;
        const isSuperseded = Boolean(entry.supersededByQueueId);
        const isHandoffPendingSource = Boolean(
            entry.handoffEnqueueSubmissionId
            && !entry.supersededByQueueId
        );
        const isPendingHandoffReplacement = isPendingServerDispatchHandoff(entry);
        const hasUnresolvedHandoff = Boolean(
            entry.handoffSourceQueueId
            && (isEnqueueFailed || isPendingHandoffReplacement)
        );
        const item = document.createElement('div');
        item.className = 'chat-task-queue-item';
        if (isRunning) {
            item.classList.add('chat-task-queue-item-running');
        } else if (isInterrupted) {
            item.classList.add('chat-task-queue-item-interrupted');
        } else if (isFailed) {
            item.classList.add('chat-task-queue-item-failed');
        } else if (isEnqueueFailed) {
            item.classList.add('chat-task-queue-item-enqueue-failed');
        }
        if (entry.id === selectedChatPromptQueueEntryId) {
            item.classList.add('chat-task-queue-item-selected');
        }
        item.setAttribute('data-queue-id', entry.id);
        item.setAttribute('aria-selected', entry.id === selectedChatPromptQueueEntryId ? 'true' : 'false');

        const label = document.createElement('div');
        label.className = 'chat-task-queue-item-label';
        const sessionLabel = getQueuedChatPromptSessionLabel(entry);
        if (isSuperseded) {
            label.textContent = `Superseded • ${sessionLabel}`;
        } else if (isHandoffPendingSource) {
            label.textContent = `Handoff pending • ${sessionLabel}`;
        } else if (isPendingHandoffReplacement) {
            label.textContent = `Handoff pending • ${sessionLabel}`;
        } else if (isEnqueueFailed) {
            label.textContent = isEnqueueUnconfirmed
                ? `Queue unconfirmed • ${sessionLabel}`
                : `Not queued • ${sessionLabel}`;
        } else if (isRunning) {
            label.textContent = `Running • ${sessionLabel}`;
        } else if (isInterrupted) {
            label.textContent = `Interrupted • ${sessionLabel}`;
        } else if (isFailed) {
            label.textContent = `Failed • ${sessionLabel}`;
        } else {
            queuedOrdinal += 1;
            label.textContent = queuedOrdinal === 1
                ? `Next up • ${sessionLabel}`
                : `Queue #${queuedOrdinal} • ${sessionLabel}`;
        }

        const editor = document.createElement('textarea');
        editor.className = 'chat-task-queue-edit';
        editor.rows = 2;
        editor.value = entry.promptRaw;
        editor.setAttribute('data-queue-id', entry.id);
        editor.readOnly = isRunning
            || isInterrupted
            || isFailed
            || isServerDispatched
            || isEnqueueFailed
            || isSuperseded
            || isHandoffPendingSource
            || isPendingHandoffReplacement;
        editor.setAttribute('aria-label', isEnqueueFailed ? `Prompt not queued ${index + 1}` : (isRunning ? `Running task ${index + 1}` : (isInterrupted ? `Interrupted task ${index + 1}` : (isFailed ? `Failed task ${index + 1}` : (isServerDispatched ? `Server-dispatched queued task ${index + 1}` : `Queued task ${index + 1}`)))));

        const actions = document.createElement('div');
        actions.className = 'chat-task-queue-actions';

        if (isEnqueueFailed) {
            const retryButton = document.createElement('button');
            retryButton.type = 'button';
            retryButton.className = 'btn-mini chat-task-queue-enqueue-retry';
            retryButton.textContent = isEnqueueUnconfirmed
                ? 'Reconcile queueing'
                : 'Retry queueing';
            retryButton.setAttribute('data-queue-id', entry.id);
            retryButton.setAttribute('aria-label', `Retry queueing prompt ${index + 1}`);
            actions.appendChild(retryButton);
        } else if (isPendingHandoffReplacement) {
            const retryHandoffButton = document.createElement('button');
            retryHandoffButton.type = 'button';
            retryHandoffButton.className = 'btn-mini chat-task-queue-handoff-complete';
            retryHandoffButton.textContent = 'Complete handoff';
            retryHandoffButton.setAttribute('data-queue-id', entry.id);
            retryHandoffButton.setAttribute(
                'aria-label',
                `Complete queue handoff ${index + 1}`
            );
            actions.appendChild(retryHandoffButton);
        } else if (isInterrupted) {
            const restartButton = document.createElement('button');
            restartButton.type = 'button';
            restartButton.className = 'btn-mini chat-task-queue-restart';
            restartButton.textContent = 'Restart';
            restartButton.setAttribute('data-queue-id', entry.id);
            restartButton.setAttribute('aria-label', `Restart interrupted task ${index + 1}`);
            actions.appendChild(restartButton);
        }

        if (hasUnresolvedHandoff) {
            const cancelHandoffButton = document.createElement('button');
            cancelHandoffButton.type = 'button';
            cancelHandoffButton.className = 'btn-mini chat-task-queue-handoff-cancel';
            cancelHandoffButton.textContent = entry.deleteInFlight
                ? 'Cancelling…'
                : 'Cancel prompt';
            cancelHandoffButton.disabled = entry.deleteInFlight === true;
            cancelHandoffButton.setAttribute('data-queue-id', entry.id);
            cancelHandoffButton.setAttribute(
                'aria-label',
                `Cancel unresolved queue handoff ${index + 1}`
            );
            actions.appendChild(cancelHandoffButton);
        }

        if (!isRunning && !isFailed && !isHandoffPendingSource && !hasUnresolvedHandoff) {
            const deleteButton = document.createElement('button');
            deleteButton.type = 'button';
            deleteButton.className = 'btn-mini chat-task-queue-delete';
            deleteButton.textContent = entry.deleteInFlight
                ? (isSuperseded ? 'Cleaning…' : 'Deleting…')
                : (isSuperseded ? 'Retry cleanup' : 'Delete');
            deleteButton.disabled = entry.deleteInFlight === true;
            deleteButton.setAttribute('data-queue-id', entry.id);
            deleteButton.setAttribute('aria-label', isInterrupted ? `Delete interrupted task ${index + 1}` : `Delete queued task ${index + 1}`);
            actions.appendChild(deleteButton);
        }
        if (isFailed) {
            const retryButton = document.createElement('button');
            retryButton.type = 'button';
            retryButton.className = 'btn-mini chat-task-queue-failed-retry';
            retryButton.textContent = entry.retryInFlight === true
                ? 'Retrying…'
                : 'Retry';
            retryButton.disabled = entry.retryInFlight === true
                || entry.deleteInFlight === true;
            retryButton.setAttribute('data-queue-id', entry.id);
            retryButton.setAttribute('aria-label', `Retry failed task ${index + 1}`);
            actions.appendChild(retryButton);

            const dismissButton = document.createElement('button');
            dismissButton.type = 'button';
            dismissButton.className = 'btn-mini chat-task-queue-dismiss';
            dismissButton.textContent = entry.deleteInFlight === true
                ? 'Dismissing…'
                : 'Dismiss';
            dismissButton.disabled = entry.deleteInFlight === true
                || entry.retryInFlight === true;
            dismissButton.setAttribute('data-queue-id', entry.id);
            dismissButton.setAttribute('aria-label', `Dismiss failed task ${index + 1}`);
            actions.appendChild(dismissButton);
        }

        item.appendChild(label);
        item.appendChild(editor);
        if (entry.syncError) {
            const syncWarning = document.createElement('div');
            syncWarning.className = 'chat-task-queue-sync-warning';
            syncWarning.textContent = entry.syncError;
            item.appendChild(syncWarning);
        } else if (isSuperseded) {
            const syncWarning = document.createElement('div');
            syncWarning.className = 'chat-task-queue-sync-warning';
            syncWarning.textContent = 'Server dispatch is canonical; this prior row is retained until cleanup succeeds.';
            item.appendChild(syncWarning);
        } else if (isHandoffPendingSource) {
            const syncWarning = document.createElement('div');
            syncWarning.className = 'chat-task-queue-sync-warning';
            syncWarning.textContent = 'This durable row is retained until server queueing is acknowledged.';
            item.appendChild(syncWarning);
        } else if (isPendingHandoffReplacement) {
            const syncWarning = document.createElement('div');
            syncWarning.className = 'chat-task-queue-sync-warning';
            syncWarning.textContent = 'The server is safely reconciling this durable queue handoff.';
            item.appendChild(syncWarning);
        }
        if (isFailed && entry.lastError) {
            const failureMessage = document.createElement('div');
            failureMessage.className = 'chat-task-queue-failure-message';
            failureMessage.textContent = entry.lastError;
            item.appendChild(failureMessage);
        }
        if (actions.childElementCount > 0) {
            item.appendChild(actions);
        }
        list.appendChild(item);
    });
}

async function queuePromptForLater(promptRaw, options = {}) {
    if (pendingChatOrganisationSwitchId !== null) {
        return null;
    }
    const organisationGenerationAtStart = chatOrganisationGeneration;
    const value = String(promptRaw ?? '');
    const sessionId = normaliseHistorySessionId(options.sessionId);
    const sessionName = (typeof options.sessionName === 'string' && options.sessionName.trim())
        ? options.sessionName.trim()
        : null;
    const enqueueSubmissionId = (
        typeof options.enqueueSubmissionId === 'string'
        && options.enqueueSubmissionId.trim()
    )
        ? options.enqueueSubmissionId.trim()
        : createClientRequestId();
    const fileCopyConceptId = normaliseTrustedUploadedFileCopyConceptId(
        options.fileCopyConceptId
    );
    const executionEnvelope = (
        options.executionEnvelope
        && typeof options.executionEnvelope === 'object'
        && !Array.isArray(options.executionEnvelope)
    )
        ? options.executionEnvelope
        : buildChatPromptExecutionEnvelope({ fileCopyConceptId });
    const localEntry = normaliseChatPromptQueueEntry({
        id: createQueuedChatPromptId(),
        promptRaw: value,
        prompt_raw: value,
        sessionId,
        session_id: sessionId,
        sessionKey: getChatRequestSessionKey(sessionId),
        sessionName,
        session_name: sessionName,
        enqueueSubmissionId,
        enqueue_submission_id: enqueueSubmissionId,
        dispatchMode: 'server',
        dispatch_mode: 'server',
        executionEnvelopeVersion: 1,
        execution_envelope_version: 1,
        executionEnvelope,
        execution_envelope: executionEnvelope,
        handoffSourceQueueId: (
            typeof options.handoffSourceQueueId === 'string'
            && options.handoffSourceQueueId.trim()
        )
            ? options.handoffSourceQueueId.trim()
            : null,
        fileCopyConceptId,
        status: CHAT_PROMPT_QUEUE_STATUS_QUEUED,
        localOnly: true
    });
    if (!localEntry) {
        return null;
    }
    queuedChatPrompts.push(localEntry);
    renderChatTaskQueuePanel();
    refreshChatSessionTabActivityIndicators();
    updateSendButtonForCurrentChatState();

    try {
        const persisted = await createPersistedChatPromptQueueEntry(localEntry);
        if (!isChatOrganisationRequestCurrent(organisationGenerationAtStart)) {
            return persisted;
        }
        if (persisted) {
            const index = queuedChatPrompts.findIndex((entry) => entry.id === localEntry.id);
            if (index >= 0) {
                queuedChatPrompts[index] = {
                    ...localEntry,
                    ...persisted,
                    id: persisted.id || localEntry.id
                };
            } else {
                mergePersistedChatPromptQueueEntry(persisted);
            }
            renderChatTaskQueuePanel();
            refreshChatSessionTabActivityIndicators();
            updateSendButtonForCurrentChatState();
            await retireAdmissionDeferredSourceAfterCanonicalEnqueue(
                localEntry,
                persisted
            );
            publishChatPromptQueueChange('queued_prompt_created');
            return persisted;
        }
    } catch (error) {
        localEntry.enqueueFailed = true;
        localEntry.enqueueUnconfirmed = isAmbiguousChatPromptQueueEnqueueError(error);
        localEntry.syncError = describeChatPromptQueueApiError(
            error,
            localEntry.enqueueUnconfirmed
                ? 'Queue acknowledgement was not received. Retry safely to reconcile this exact prompt.'
                : 'Prompt was not queued. Retry when queue storage is available.'
        );
        console.warn('[chatTab] Unable to persist queued prompt:', error);
        ensureAdmissionDeferredSourceQueueEntry(localEntry);
        renderChatTaskQueuePanel();
        refreshChatSessionTabActivityIndicators();
        updateSendButtonForCurrentChatState();
    }
    return localEntry;
}

function isChatPromptSessionBusy(sessionId, { includeQueued = false } = {}) {
    const sessionKey = getChatRequestSessionKey(sessionId);
    return liveChatRequestsBySession.has(sessionKey)
        || queuedChatPromptClaimsInFlight.has(sessionKey)
        || queuedChatPrompts.some((entry) => (
            entry?.sessionKey === sessionKey
            && entry.enqueueFailed !== true
            && (
                entry.status === CHAT_PROMPT_QUEUE_STATUS_IN_PROGRESS
                || (includeQueued && entry.status === CHAT_PROMPT_QUEUE_STATUS_QUEUED)
            )
        ));
}

async function sendQueuedChatPromptEntry(entryId) {
    if (pendingChatOrganisationSwitchId !== null) {
        return false;
    }
    const organisationGenerationAtStart = chatOrganisationGeneration;
    const cleanEntryId = (typeof entryId === 'string' && entryId.trim())
        ? entryId.trim()
        : null;
    if (!cleanEntryId) {
        return false;
    }

    let nextEntry = getChatPromptQueueEntryById(cleanEntryId);
    if (
        !nextEntry
        || isServerDispatchedChatPromptQueueEntry(nextEntry)
        || isChatPromptSessionBusy(nextEntry.sessionId)
    ) {
        return false;
    }
    const sessionHead = getQueuedChatPromptHeadsBySession().get(nextEntry.sessionKey);
    if (sessionHead?.id !== nextEntry.id) {
        return false;
    }
    if (!nextEntry || typeof nextEntry.promptRaw !== 'string' || !nextEntry.promptRaw.trim()) {
        queuedChatPrompts = queuedChatPrompts.filter((entry) => entry?.id !== cleanEntryId);
        renderChatTaskQueuePanel();
        refreshChatSessionTabActivityIndicators();
        updateSendButtonForCurrentChatState();
        return false;
    }

    if (getUnavailableLocalModelPreferenceForChat()) {
        nextEntry.syncError = LOCAL_MODEL_UNAVAILABLE_CHAT_MESSAGE;
        renderChatTaskQueuePanel();
        refreshChatSessionTabActivityIndicators();
        updateSendButtonForCurrentChatState();
        notifyUnavailableLocalModelForChat();
        return false;
    }

    // A queued turn is bound to its originating conversation, but executing it
    // must not navigate the user away from the conversation they are currently
    // reading. `handleSendPrompt` accepts the explicit target session and keeps
    // all live/result rendering scoped to that session.

    const sessionKey = nextEntry.sessionKey || getChatRequestSessionKey(nextEntry.sessionId);
    queuedChatPromptClaimsInFlight.add(sessionKey);
    try {
        if (nextEntry.queueId) {
            const updatedEntry = await persistQueuedPromptUpdateNow(nextEntry);
            if (!isChatOrganisationRequestCurrent(organisationGenerationAtStart)) {
                return false;
            }
            nextEntry = {
                ...nextEntry,
                ...updatedEntry
            };
            const updatedIndex = queuedChatPrompts.findIndex((entry) => entry?.id === cleanEntryId);
            if (updatedIndex < 0) {
                return false;
            }
            queuedChatPrompts[updatedIndex] = nextEntry;
        }

        // Release the short claim guard before dispatch. handleSendPrompt runs
        // synchronously until it installs the live request for this session.
        queuedChatPromptClaimsInFlight.delete(sessionKey);
        void handleSendPrompt({
            promptOverride: nextEntry.promptRaw,
            fromQueue: true,
            sessionId: nextEntry.sessionId || null,
            sessionName: nextEntry.sessionName || null,
            promptQueueRecordId: nextEntry.queueId || null,
            enqueueSubmissionId: nextEntry.enqueueSubmissionId || null,
            clientRequestId: nextEntry.clientRequestId || null,
            attemptId: nextEntry.attemptId || null,
            fileCopyConceptId: nextEntry.fileCopyConceptId || null,
            queuedSourceEntryId: cleanEntryId
        });
        return true;
    } catch (error) {
        const failedEntry = getChatPromptQueueEntryById(cleanEntryId) || nextEntry;
        failedEntry.syncError = describeChatPromptQueueApiError(
            error,
            'Could not save and claim this queued task on the server.'
        );
        console.warn('[chatTab] Unable to claim queued prompt:', error);
        renderChatTaskQueuePanel();
        refreshChatSessionTabActivityIndicators();
        updateSendButtonForCurrentChatState();
        return false;
    } finally {
        queuedChatPromptClaimsInFlight.delete(sessionKey);
    }
}

function getQueuedChatPromptHeadsBySession() {
    const heads = new Map();
    queuedChatPrompts.forEach((entry) => {
        if (!entry || ![
            CHAT_PROMPT_QUEUE_STATUS_QUEUED,
            CHAT_PROMPT_QUEUE_STATUS_IN_PROGRESS
        ].includes(entry.status)) {
            return;
        }
        const sessionKey = entry.sessionKey || getChatRequestSessionKey(entry.sessionId);
        if (!heads.has(sessionKey)) {
            heads.set(sessionKey, entry);
        }
    });
    return heads;
}

async function handleSendPrompt(options = {}) {
    if (pendingChatOrganisationSwitchId !== null) {
        return;
    }
    const promptInput = getPromptInputElement();
    if (!promptInput) {
        return;
    }

    const fromQueue = options && options.fromQueue === true;
    const observeServerDispatch = options?.observeServerDispatch === true;
    const hasPromptOverride = options && typeof options.promptOverride === 'string';
    const selectedQueueEntry = (!fromQueue && !hasPromptOverride)
        ? getSelectedChatPromptQueueEntryForSend()
        : null;
    const directComposerSubmission = (
        !fromQueue
        && !hasPromptOverride
        && !selectedQueueEntry
    );
    if (directComposerSubmission && newChatCreationInFlight) {
        const createdSession = await newChatCreationInFlight;
        if (!createdSession || pendingChatOrganisationSwitchId !== null) {
            return;
        }
    }
    let targetSessionId = normaliseHistorySessionId(
        options?.sessionId
        ?? selectedQueueEntry?.sessionId
        ?? activeChatSessionId
    );
    let targetSessionName = (typeof options?.sessionName === 'string' && options.sessionName.trim())
        ? options.sessionName.trim()
        : (
            (typeof selectedQueueEntry?.sessionName === 'string' && selectedQueueEntry.sessionName.trim())
                ? selectedQueueEntry.sessionName.trim()
                : activeChatSessionName
        );
    if (targetSessionId && isExternalConversationReadOnly(targetSessionId)) {
        showToast(
            'This imported snapshot is read-only. Choose Continue before sending a new message.',
            'info'
        );
        return;
    }
    if (selectedQueueEntry?.status === CHAT_PROMPT_QUEUE_STATUS_QUEUED) {
        if (!isChatPromptSessionBusy(targetSessionId)) {
            await sendQueuedChatPromptEntry(selectedQueueEntry.id);
        }
        return;
    }
    const promptRaw = hasPromptOverride
        ? options.promptOverride
        : (selectedQueueEntry ? selectedQueueEntry.promptRaw : promptInput.value);
    const selectionStart = hasPromptOverride
        ? null
        : (selectedQueueEntry ? null : (typeof promptInput.selectionStart === 'number' ? promptInput.selectionStart : null));
    const selectionEnd = hasPromptOverride
        ? null
        : (selectedQueueEntry ? null : (typeof promptInput.selectionEnd === 'number' ? promptInput.selectionEnd : null));
    const promptForSend = normaliseVontologyIdsForBackend(promptRaw);
    const promptText = promptForSend.trim();
    const assistantOpening = options?.turnKind === 'assistant_opening';
    const allowEmptyPrompt = assistantOpening && options?.allowEmptyPrompt === true;
    if (
        directComposerSubmission
        && getInFlightUploadStateForSession(targetSessionId)
    ) {
        showToast(ATTACHMENT_UPLOAD_SEND_BLOCK_MESSAGE, 'info');
        updateSendButtonForCurrentChatState();
        return;
    }

    ensureAbortButtonBound();

    if (!promptText && !allowEmptyPrompt) {
        if (!fromQueue) {
            alert('Please enter a prompt.');
        }
        return;
    }

    const conceptQaSession = getConceptQaSessionForChat(targetSessionId);
    if (conceptQaSession && directComposerSubmission && !assistantOpening) {
        await submitActiveConceptQaPrompt({
            session: conceptQaSession,
            promptInput,
            promptRaw,
        });
        return;
    }

    if (!observeServerDispatch && getUnavailableLocalModelPreferenceForChat()) {
        if (!fromQueue) {
            notifyUnavailableLocalModelForChat();
        }
        return;
    }

    if (!targetSessionId) {
        try {
            const ensuredTarget = await ensurePromptTargetChatSession({
                sessionId: targetSessionId,
                sessionName: targetSessionName
            });
            targetSessionId = normaliseHistorySessionId(ensuredTarget?.sessionId);
            targetSessionName = (typeof ensuredTarget?.sessionName === 'string' && ensuredTarget.sessionName.trim())
                ? ensuredTarget.sessionName.trim()
                : targetSessionName;
        } catch (error) {
            console.error('Unable to prepare a conversation session for send:', error);
            if (!fromQueue) {
                alert('Unable to prepare a conversation for this prompt.');
            }
            return;
        }
        if (!targetSessionId) {
            if (!fromQueue) {
                alert('Unable to prepare a conversation for this prompt.');
            }
            return;
        }
    }

    if (
        observeServerDispatch
        && liveChatRequestsBySession.has(getChatRequestSessionKey(targetSessionId))
    ) {
        return;
    }

    if (
        !observeServerDispatch
        && isChatPromptSessionBusy(targetSessionId, { includeQueued: !fromQueue })
    ) {
        if (fromQueue) {
            return;
        }
        if (!promptText) {
            return;
        }
        const submissionSessionKey = getChatRequestSessionKey(targetSessionId);
        if (queuedChatPromptSubmissionsInFlight.has(submissionSessionKey)) {
            return;
        }
        const enqueueSubmissionId = createClientRequestId();
        queuedChatPromptSubmissionsInFlight.set(
            submissionSessionKey,
            enqueueSubmissionId
        );
        const queuedFileCopyConceptId = takePendingUploadedFileCopyConceptId(
            targetSessionId
        );
        const executionEnvelope = buildChatPromptExecutionEnvelope({
            fileCopyConceptId: queuedFileCopyConceptId
        });
        rememberLastSubmittedUserPrompt(promptRaw);
        setPromptComposerValue('', { promptInput });
        updateSendButtonForCurrentChatState();
        try {
            await queuePromptForLater(promptRaw, {
                sessionId: targetSessionId,
                sessionName: targetSessionName,
                fileCopyConceptId: queuedFileCopyConceptId,
                executionEnvelope,
                enqueueSubmissionId
            });
        } finally {
            if (
                queuedChatPromptSubmissionsInFlight.get(submissionSessionKey)
                === enqueueSubmissionId
            ) {
                queuedChatPromptSubmissionsInFlight.delete(submissionSessionKey);
            }
            updateSendButtonForCurrentChatState();
        }
        return;
    }

    // Refresh setting in the background; default is enabled.
    void refreshToolUseDuringThinkingSetting();

    const promptQueueRecordId = (typeof options?.promptQueueRecordId === 'string' && options.promptQueueRecordId.trim())
        ? options.promptQueueRecordId.trim()
        : null;

    const clientRequestId = (typeof options?.clientRequestId === 'string' && options.clientRequestId.trim())
        ? options.clientRequestId.trim()
        : createClientRequestId();
    const attemptId = (typeof options?.attemptId === 'string' && options.attemptId.trim())
        ? options.attemptId.trim()
        : createClientRequestId();
    const enqueueSubmissionId = (
        typeof options?.enqueueSubmissionId === 'string'
        && options.enqueueSubmissionId.trim()
    )
        ? options.enqueueSubmissionId.trim()
        : createClientRequestId();
    const userTurnId = buildChatRequestTurnId('user', clientRequestId);
    const assistantTurnId = buildChatRequestTurnId('assistant', clientRequestId);
    const userTurnShouldRender = Boolean(
        !assistantOpening && !observeServerDispatch && promptText
    );
    const userTurnTimestamp = userTurnShouldRender ? new Date().toISOString() : null;
    const executionContextBinding = synchroniseLlmExecutionContext();
    const explicitFileCopyConceptId = normaliseTrustedUploadedFileCopyConceptId(
        options?.fileCopyConceptId
    );
    const pendingFileCopyBinding = (!explicitFileCopyConceptId && !fromQueue)
        ? takePendingUploadedFileCopyBinding(targetSessionId)
        : null;
    const pendingFileCopyConceptId = explicitFileCopyConceptId
        || pendingFileCopyBinding?.conceptId
        || null;
    const pendingFileCopyDisplayName = explicitFileCopyConceptId
        ? normalisePendingAttachmentDisplayName(options?.fileCopyDisplayName)
        : (pendingFileCopyBinding?.displayName || null);
    const turnKind = assistantOpening ? 'assistant_opening' : null;
    const initiationId = assistantOpening
        ? String(options?.initiationId || '').trim() || null
        : null;
    const executionEnvelope = buildChatPromptExecutionEnvelope({
        fileCopyConceptId: pendingFileCopyConceptId,
        turnKind,
        initiationId
    });
    const claimedAtMs = Date.parse(String(options?.claimedAt || ''));
    const request = {
        abortController: new AbortController(),
        organisationGeneration: chatOrganisationGeneration,
        sessionId: targetSessionId,
        sessionKey: getChatRequestSessionKey(targetSessionId),
        sessionName: targetSessionName,
        promptRaw,
        promptText,
        userTurnId,
        assistantTurnId,
        userTurnShouldRender,
        userTurnTimestamp,
        turnKind,
        initiationId,
        promptQueueRecordId,
        selectionStart,
        selectionEnd,
        pendingFileCopyConceptId,
        pendingFileCopyDisplayName,
        attachmentBindingAccepted: false,
        attachmentBindingTransferred: false,
        attachmentBindingReleased: false,
        aborted: false,
        observingServerDispatch: observeServerDispatch,
        enqueueSubmissionId,
        executionEnvelope,
        clientRequestId,
        attemptId,
        executionContextBinding,
        thinkingStartedAtMs: Number.isFinite(claimedAtMs) ? claimedAtMs : Date.now(),
        activityHistory: [],
        toolUseProgressHistory: [],
        workflowStagePath: null,
        workflowSelection: null,
        workflowRoutingDiagnostics: null,
        latestProgress: null,
        progressEvents: [],
        phaseHistory: [],
        stageDiagnostics: [],
        turnOutcome: null,
        thinkingCardMode: loadStoredThinkingCardMode(),
        thinkingCardDisplayState: reduceThinkingCardDisplayState(null, { type: 'reset_for_active' })
    };
    const queuedSourceEntryId = (
        fromQueue
        && typeof options?.queuedSourceEntryId === 'string'
        && options.queuedSourceEntryId.trim()
    )
        ? options.queuedSourceEntryId.trim()
        : null;
    let queuedSourceAcknowledged = false;
    const acknowledgeQueuedSource = () => {
        if (!queuedSourceEntryId || queuedSourceAcknowledged) {
            return;
        }
        queuedSourceAcknowledged = true;
        queuedChatPrompts = queuedChatPrompts.filter((entry) => (
            entry?.id !== queuedSourceEntryId
        ));
        if (selectedChatPromptQueueEntryId === queuedSourceEntryId) {
            selectedChatPromptQueueEntryId = null;
        }
        publishChatPromptQueueChange('legacy_queued_prompt_acknowledged');
        renderChatTaskQueuePanel();
        refreshChatSessionTabActivityIndicators();
        updateSendButtonForCurrentChatState();
    };
    request.promptQueueRecordPromise = request.promptQueueRecordId || options?.skipPromptQueueRecord === true
        ? null
        : createPersistedChatPromptQueueEntry({
            promptRaw,
            sessionId: targetSessionId,
            sessionName: targetSessionName,
            clientRequestId,
            attemptId
        }, CHAT_PROMPT_QUEUE_STATUS_QUEUED)
            .then((activeRecord) => {
                request.promptQueueRecordId = activeRecord?.queueId || null;
                return activeRecord;
            })
            .catch((error) => {
                console.warn('[chatTab] Unable to persist active prompt for restart recovery:', error);
                return null;
            });
    setFinishedThinkingCardForSession(targetSessionId, null);
    setLiveChatRequestForSession(targetSessionId, request);
    if (observeServerDispatch) {
        renderChatTaskQueuePanel();
        refreshChatSessionTabActivityIndicators();
        updateSendButtonForCurrentChatState();
    }
    setConversationRuntimeCostLiveSummary(request, null, {
        active: true,
        reason: 'request_started'
    });
    if (request.sessionId === activeChatSessionId) {
        void refreshConversationRuntimeCostSnapshot({
            excludeRequestId: request.clientRequestId,
            reason: 'request_started'
        });
    }
    if (selectedQueueEntry) {
        hideChatPromptQueueEntryLocally(selectedQueueEntry);
    }
    invalidateSessionHistoryCache(targetSessionId);

    const isRequestCurrentOrganisation = () => (
        isChatOrganisationRequestCurrent(request.organisationGeneration)
    );
    const isRequestVisible = () => (
        isRequestCurrentOrganisation() && isRequestInActiveChatSession(request)
    );

    // Show loading indicator and disable send button
    if (isRequestVisible()) {
        setThinkingState(true, request);
        setLoadingIndicatorText(
            assistantOpening
                ? 'Von is opening this discussion…'
                : formatToolUseProgressText(buildInitialThinkingProgressPlaceholder(clientRequestId), request)
        );
        setLoadingIndicatorDetailHtml(renderThinkingCardBodyHTML(request), request);
        updateThinkingCardMeta(request, null);
    } else {
        syncActiveChatSessionThinkingState();
    }

    // Add user message to chat with turnId
    if (isRequestVisible() && userTurnShouldRender) {
        appendMessage('User', promptText, userTurnId, false, false, userTurnTimestamp);
        // Fire-and-forget annotate user turn (do not await) - only if toggle is enabled
        const annotationToggle = document.getElementById('annotationToggle');
        if (annotationToggle && annotationToggle.checked) {
            try {
                annotateTurn({
                    conversation_id: elements.conversationId || 'local',
                    turn_id: userTurnId,
                    speaker: 'user',
                    text: promptText
                }).catch(e => console.info('[annotations] user annotate error', e));
            } catch (e) { console.info('[annotations] annotate user failed', e); }
        }
    }

    const claimForegroundDelivery = () => {
        if (request.foregroundDeliveryCompleted) {
            return false;
        }
        request.foregroundDeliveryCompleted = true;
        return true;
    };

    const deliverSuccessfulResponseData = (data, source = 'generate_response') => {
        if (!isRequestCurrentOrganisation()) {
            request.foregroundDeliveryCompleted = true;
            return false;
        }
        if (!claimForegroundDelivery()) {
            return false;
        }
        _acceptConversationSituationPayload(data, request.sessionId);
        const responsePresenterState = resolveResponsePresenterState(data);
        const responseChannels = responsePresenterState.presenterChannels;
        const screenText = responsePresenterState.screenText;
        const spokenText = responsePresenterState.spokenText;
        const displayElements = responsePresenterState.displayElements;
        const turnExecutionDiagnostics = (
            data?.llm_debug?.turn_execution_diagnostics
            && typeof data.llm_debug.turn_execution_diagnostics === 'object'
        )
            ? data.llm_debug.turn_execution_diagnostics
            : null;
        const completionGateDecision = normaliseThinkingProgressStatusValue(
            turnExecutionDiagnostics?.completion_gate?.decision
            || turnExecutionDiagnostics?.completion_gate_decision
        );
        const payloadTerminalStatus = normaliseThinkingProgressStatusValue(data?.terminal_status);
        const partialEffectOutcome = payloadTerminalStatus === 'effect_partially_completed';
        const turnOutcomeStatus = canonicalThinkingTerminalStatus(completionGateDecision)
            || canonicalThinkingTerminalStatus(payloadTerminalStatus)
            || (partialEffectOutcome ? THINKING_STATUS_COMPLETED : null)
            || (data?.success === false ? THINKING_STATUS_FAILED : null)
            || THINKING_STATUS_COMPLETED;
        const typedNonSuccess = data?.success === false;
        request.turnOutcome = {
            status: turnOutcomeStatus,
            phase_label: partialEffectOutcome
                ? 'Partially complete'
                : (
                    turnOutcomeStatus === THINKING_STATUS_FAILED
                        ? (typedNonSuccess ? 'Turn incomplete' : 'Turn failed')
                        : (turnOutcomeStatus === 'follow_up_required' ? 'Follow-up required' : 'Turn completed')
                ),
            summary: turnOutcomeStatus === 'follow_up_required'
                ? 'The turn completed, but a follow-up step is still required.'
                : (
                    partialEffectOutcome
                        ? 'A useful response was delivered with an explicitly partial effect outcome.'
                        : typedNonSuccess
                        ? `Response returned with status ${payloadTerminalStatus || 'incomplete'}`
                        : 'Response generated'
                )
        };
        if (source === 'task_result' && !typedNonSuccess) {
            request.turnOutcome.summary = 'Response generated from completed task result';
        }
        if (turnExecutionDiagnostics) {
            syncThinkingCanonicalStateFromTurnExecutionDiagnostics(request, turnExecutionDiagnostics);
            syncThinkingCriticOutputFromSource(request, turnExecutionDiagnostics);
        }
        applyImmediateThinkingTerminalOutcome(request);

        // Store LLM debug data if available
        if (data.llm_debug) {
            const enriched = enrichDebugDataWithSpeechPlanning(data.llm_debug, {
                presenterChannels: responseChannels,
                screenText,
                spokenText,
                displayElements
            });
            enriched.foreground_delivery_source = source;
            request.llmUsageCostSummary = (
                enriched.llm_usage_cost_summary
                && typeof enriched.llm_usage_cost_summary === 'object'
            ) ? { ...enriched.llm_usage_cost_summary } : null;
            setConversationRuntimeCostLiveSummary(request, request.llmUsageCostSummary, {
                active: false,
                reason: 'terminal_summary'
            });
            syncThinkingCriticOutputFromSource(request, enriched);
            setLlmDebugDataEntry(assistantTurnId, enriched, request.executionContextBinding);
            if (isRequestVisible()) {
                refreshThinkingCardProgressUi(request);
            }
            console.log('[chatTab] Stored LLM debug data for turn:', assistantTurnId, {
                hasButtonify: !!data.llm_debug?.buttonify,
                buttonifyOptions: data.llm_debug?.buttonify?.options,
                enrichedHasButtonify: !!enriched?.buttonify,
                foregroundDeliverySource: source
            });
        }

        const fastpathMeta = data.fastpath || (data.llm_debug && data.llm_debug.fastpath) || null;

        const toolProgressEnabled = data?.llm_debug?.internal_mcp?.tool_use_progress?.enabled;
        if (toolProgressEnabled === false) {
            stopToolUseProgressPolling(request);
            setLoadingIndicatorText(DEFAULT_THINKING_TEXT);
        }

        // Append assistant message with turnId and llm_debug flag
        request.resultTurnId = assistantTurnId;
        if (isRequestVisible()) {
            appendMessage('Von', screenText, assistantTurnId, !!data.llm_debug, false, null, fastpathMeta, spokenText);
            // Annotate assistant turn and render suggestions when returned - only if toggle is enabled
            const annotationToggle = document.getElementById('annotationToggle');
            if (annotationToggle && annotationToggle.checked) {
                try {
                    annotateTurn({
                        conversation_id: elements.conversationId || 'local',
                        turn_id: assistantTurnId,
                        speaker: 'assistant',
                        text: screenText
                    }).then((resp) => {
                        console.info('[annotations] annotateTurn response (chatTab)', resp);
                        if (resp && resp.suggestions) {
                            renderSpanSuggestions(assistantTurnId, resp.suggestions);
                        }
                    }).catch(e => console.info('[annotations] assistant annotate error', e));
                } catch (e) { console.info('[annotations] annotate assistant failed', e); }
            }
        }
        return true;
    };

    const deliverErrorResponseData = (data, fallbackMessage = 'An error occurred') => {
        if (!isRequestCurrentOrganisation()) {
            request.foregroundDeliveryCompleted = true;
            return false;
        }
        if (!claimForegroundDelivery()) {
            return false;
        }
        request.turnOutcome = {
            status: 'error',
            phase_label: 'Turn failed',
            summary: data?.error || data?.detail || fallbackMessage
        };
        const turnExecutionDiagnostics = (
            data?.llm_debug?.turn_execution_diagnostics
            && typeof data.llm_debug.turn_execution_diagnostics === 'object'
        )
            ? data.llm_debug.turn_execution_diagnostics
            : null;
        if (turnExecutionDiagnostics) {
            syncThinkingCanonicalStateFromTurnExecutionDiagnostics(request, turnExecutionDiagnostics);
            syncThinkingCriticOutputFromSource(request, turnExecutionDiagnostics);
        }
        applyImmediateThinkingTerminalOutcome(request);
        // Store LLM debug data if available even on error
        const errorTurnId = `e-${Date.now()}`;
        if (data?.llm_debug) {
            request.llmUsageCostSummary = (
                data.llm_debug.llm_usage_cost_summary
                && typeof data.llm_debug.llm_usage_cost_summary === 'object'
            ) ? { ...data.llm_debug.llm_usage_cost_summary } : null;
            setConversationRuntimeCostLiveSummary(request, request.llmUsageCostSummary, {
                active: false,
                reason: 'terminal_summary'
            });
            syncThinkingCriticOutputFromSource(request, data.llm_debug);
            setLlmDebugDataEntry(errorTurnId, data.llm_debug, request.executionContextBinding);
            if (isRequestVisible()) {
                refreshThinkingCardProgressUi(request);
            }
            console.log('[chatTab] Stored LLM debug data for error turn:', errorTurnId);
        }
        request.resultTurnId = errorTurnId;
        if (isRequestVisible()) {
            appendMessage('Error', data?.error || data?.detail || fallbackMessage, errorTurnId, !!data?.llm_debug);
            appendAssistantOpeningRetryAction(request, errorTurnId);
        }
        return true;
    };

    const deliverCancelledResponseData = (data = {}) => {
        if (!isRequestCurrentOrganisation()) {
            request.foregroundDeliveryCompleted = true;
            return false;
        }
        if (!claimForegroundDelivery()) {
            return false;
        }
        const cancellationSummary = normaliseThinkingActivityString(
            data?.progress?.result_summary
            || data?.result_summary
            || data?.detail
            || data?.error
        ) || 'Turn stopped.';
        request.turnOutcome = {
            status: THINKING_STATUS_CANCELLED,
            phase_label: 'Turn stopped',
            summary: cancellationSummary
        };

        const reportedProgress = (
            data?.progress && typeof data.progress === 'object'
                ? data.progress
                : data
        );
        if (isTerminalThinkingProgress(reportedProgress)) {
            applyThinkingProgressUpdate(request, reportedProgress);
        }
        applyImmediateThinkingTerminalOutcome(request);
        return true;
    };

    const foregroundTaskResultHandlers = {
        onCompleted: async (generateBody) => {
            request.serverQueueTerminalObserved = true;
            request.attachmentBindingAccepted = true;
            acknowledgeQueuedSource();
            const delivered = deliverSuccessfulResponseData(generateBody, 'task_result');
            if (delivered) {
                try {
                    request.abortController.abort();
                } catch (_) {
                    // Ignore; the original fetch or observer may already be resolving.
                }
            }
        },
        onFailed: async (statusPayload, status) => {
            request.serverQueueTerminalObserved = true;
            acknowledgeQueuedSource();
            const delivered = status === 'cancelled'
                ? deliverCancelledResponseData(statusPayload)
                : deliverErrorResponseData(
                    statusPayload,
                    'Task failed before the response reached the chat UI.'
                );
            if (delivered) {
                try {
                    request.abortController.abort();
                } catch (_) {
                    // Ignore; the original fetch or observer may already be resolving.
                }
            }
        }
    };

    if (!fromQueue) {
        // Clear input only for direct sends; queued execution should preserve current draft text.
        if (promptText) {
            rememberLastSubmittedUserPrompt(promptRaw);
        }
        setPromptComposerValue('', { promptInput });
    }

    try {
        setLoadingIndicatorTooltip(formatToolUseHistoryTooltip(request));

        startThinkingTooltipTicker(request);

        if (observeServerDispatch) {
            if (
                request.aborted
                || !isLiveChatRequest(request)
                || !isRequestCurrentOrganisation()
            ) {
                return;
            }
            startToolUseProgressPolling(request);
            await new Promise((resolve) => {
                let settled = false;
                const settle = () => {
                    if (settled) {
                        return;
                    }
                    settled = true;
                    request.abortController.signal.removeEventListener('abort', settle);
                    resolve();
                };
                request.abortController.signal.addEventListener('abort', settle, { once: true });
                startForegroundTaskResultPolling(request, foregroundTaskResultHandlers);
            });
            return;
        }

        // Get user context from localStorage to send to backend
        const userContext = getUserContext();

        // The server queue record is the authoritative admission/correlation
        // carrier. Await its creation before generate; if persistence is
        // unavailable the server can still create a direct compatibility row.
        if (!request.promptQueueRecordId && request.promptQueueRecordPromise) {
            const activeRecord = await request.promptQueueRecordPromise;
            request.promptQueueRecordId = activeRecord?.queueId || null;
        }

        // Queue persistence can yield before the server turn starts. Honour an
        // abort in that window and remove only this still-queued record so a
        // later tab refresh cannot replay a prompt the user already stopped.
        if (
            request.aborted
            || !isLiveChatRequest(request)
            || !isRequestCurrentOrganisation()
        ) {
            if (request.promptQueueRecordId) {
                try {
                    await deletePersistedChatPromptQueueEntry({
                        queueId: request.promptQueueRecordId
                    });
                    request.promptQueueRecordId = null;
                    publishChatPromptQueueChange('queued_prompt_cancelled');
                } catch (cancelError) {
                    console.warn('[chatTab] Unable to cancel pre-dispatch queued prompt:', cancelError);
                }
            }
            return;
        }

        // Start the generate request before polling progress so the first
        // /von/progress read is less likely to outrun request initialisation.
        const responsePromise = fetch('/von/generate', {
            method: 'POST',
            headers: buildChatFetchHeaders({
                'Content-Type': 'application/json',
            }),
            signal: request.abortController.signal,
            body: JSON.stringify({
                prompt: promptText,
                client_request_id: request.clientRequestId,
                attempt_id: request.attemptId,
                conversation_session_id: targetSessionId,
                conversation_session_name: targetSessionName,
                ...(request.promptQueueRecordId ? {
                    prompt_queue_id: request.promptQueueRecordId
                } : {}),
                user_id: userContext.user_id,
                org_id: userContext.org_id,
                ...request.executionEnvelope
            })
        });
        startToolUseProgressPolling(request);
        startForegroundTaskResultPolling(request, foregroundTaskResultHandlers);
        // Give an already-available first progress response a chance to land
        // before an immediate generate response tears down the active card.
        await Promise.resolve();
        await Promise.resolve();
        const response = await responsePromise;
        if (response?.ok) {
            request.attachmentBindingAccepted = true;
        }

        // Defensive: some tests or environments may provide a non-standard fetch
        // mock that doesn't return a Response-like object. Guard before calling
        // `response.json()` so we surface a friendly server error message instead
        // of falling through to the network-error catch path.
        if (!response || typeof response.json !== 'function') {
            request.resultTurnId = `e-${Date.now()}`;
            if (isRequestVisible()) {
                appendMessage('Error', 'Server error', request.resultTurnId);
                appendAssistantOpeningRetryAction(request, request.resultTurnId);
            }
            return;
        }

        let data = null;
        try {
            data = await response.json();
        } catch (parseError) {
            console.warn('[chatTab] Unable to parse /von/generate response JSON:', parseError);
            data = {
                error: response.ok
                    ? 'Server returned an unreadable response.'
                    : 'Server returned a non-JSON error response.',
                response_parse_error: parseError && parseError.message ? parseError.message : String(parseError || '')
            };
        }
        console.log('[chatTab] fetch response.ok=', response.ok, 'data=', data);

        if (request.aborted) {
            return;
        }

        if (response.ok) {
            request.serverQueueTerminalObserved = true;
            acknowledgeQueuedSource();
            deliverSuccessfulResponseData(data, 'generate_response');
        } else if (String(data?.terminal_status || '').toLowerCase() === 'cancelled') {
            request.serverQueueTerminalObserved = true;
            acknowledgeQueuedSource();
            deliverCancelledResponseData(data);
        } else if (
            data?.retryable === true
            || response.status === 429
        ) {
            // Admission backpressure is not a failed user task. Restore the
            // durable row to queued state; the server-side dispatcher owns
            // its next attempt while other conversations remain usable.
            request.admissionDeferred = true;
            request.foregroundDeliveryCompleted = true;
            request.turnOutcome = {
                status: CHAT_PROMPT_QUEUE_STATUS_QUEUED,
                phase_label: 'Queued',
                summary: data?.detail || 'Waiting for this conversation or server capacity.'
            };
            // Only a row created and read back for this exact request is safe
            // to retire. An admission error's queue id may identify the turn
            // currently holding the conversation fence rather than this prompt.
            const foregroundQueueRecordId = request.promptQueueRecordId;
            let deferredServerQueueAcknowledged = false;
            if (data?.error === 'window_context_unavailable') {
                try {
                    await repairCurrentWindowOrganisationBinding();
                } catch (repairError) {
                    console.warn('[chatTab] Unable to rebind this tab organisation:', repairError);
                }
            }
            try {
                const requeued = await queuePromptForLater(request.promptRaw, {
                    sessionId: request.sessionId,
                    sessionName: request.sessionName,
                    fileCopyConceptId: request.pendingFileCopyConceptId,
                    enqueueSubmissionId: request.enqueueSubmissionId,
                    executionEnvelope: request.executionEnvelope,
                    handoffSourceQueueId: foregroundQueueRecordId
                });
                if (requeued?.queueId) {
                    request.promptQueueRecordId = requeued?.queueId || null;
                    deferredServerQueueAcknowledged = true;
                    request.attachmentBindingTransferred = Boolean(
                        request.pendingFileCopyConceptId
                    );
                }
            } catch (requeueError) {
                console.info('[chatTab] Admission-deferred row recovery:', requeueError);
            }
            if (isRequestVisible()) {
                showToast(
                    deferredServerQueueAcknowledged
                        ? 'Prompt queued until this conversation is free.'
                        : 'Prompt remains durable; retry server queueing from the queue panel.',
                    'info'
                );
            }
        } else {
            request.serverQueueTerminalObserved = true;
            deliverErrorResponseData(data, 'An error occurred');
        }
    } catch (error) {
        if (request?.foregroundDeliveryCompleted) {
            return;
        }
        if (request && (request.aborted || (error && error.name === 'AbortError'))) {
            return;
        }
        const failureSummary = resolveGenerateCatchFailureSummary(request, error);
        request.turnOutcome = {
            status: 'error',
            phase_label: 'Turn failed',
            summary: failureSummary
        };
        retainGenerateFailureSummaryInLatestProgress(request, failureSummary);
        applyImmediateThinkingTerminalOutcome(request);
        console.error('Error:', error);
        request.resultTurnId = `e-${Date.now()}`;
        if (isRequestVisible()) {
            appendMessage('Error', failureSummary, request.resultTurnId);
            appendAssistantOpeningRetryAction(request, request.resultTurnId);
        }
    } finally {
        releaseRequestFileCopyBinding(request);
        stopForegroundTaskResultPolling(request);
        if (!request?.promptQueueRecordId && request?.promptQueueRecordPromise) {
            try {
                const activeRecord = await request.promptQueueRecordPromise;
                request.promptQueueRecordId = activeRecord?.queueId || request.promptQueueRecordId || null;
            } catch (_) {
                // The promise already logs failures; proceed without restart recovery.
            }
        }
        // `/von/generate` now terminalises the exact bound queue attempt.
        // Client-side inference is not authoritative, especially after a tab
        // switch, aborted response stream, or background reconciliation.
        if (isLiveChatRequest(request)) {
            stopToolUseProgressPolling(request);
            stopThinkingTooltipTicker(request);
            const persisted = !request.aborted && persistFinishedThinkingCard(request);
            if (!persisted) {
                setFinishedThinkingCardForSession(request.sessionId, null);
            }
            setLiveChatRequestForSession(request.sessionId, null);
            renderChatTaskQueuePanel();
            refreshChatSessionTabActivityIndicators();
            updateSendButtonForCurrentChatState();
            if (request.sessionId === activeChatSessionId) {
                void refreshConversationRuntimeCostSnapshot({
                    observeRequestId: request.clientRequestId,
                    reason: 'terminal_baseline_refresh'
                });
            }
        }
        syncActiveChatSessionThinkingState();
        updateHistoryLength();
        scheduleChatSessionTabsRefresh(true);
        if (request.serverQueueTerminalObserved) {
            publishChatPromptQueueChange('turn_terminal');
        }
        syncChatPromptQueuePolling();
    }
}

async function handleResetContext() {
    try {
        const response = await fetch('/von/reset', {
            method: 'POST',
            headers: buildChatFetchHeaders()
        });

        const data = await response.json();

        if (response.ok) {
            historySegmentsShown = 1;
            const loaded = await loadChatHistory({
                segments: 1,
                scrollToBottom: true,
                showResetNotice: true,
                forceScrollToBottom: true
            });

            if (!loaded) {
                const scrollableField = document.getElementById('scrollableField');
                appendResetNotice(scrollableField);
            }

            transcriptTurns.length = 0;
            clearLlmDebugDataEntries();
            setFinishedThinkingCardForSession(activeChatSessionId, null);
            syncActiveChatSessionThinkingState();
            updateHistoryLength();
            scheduleChatSessionTabsRefresh(true);
            // JVNAUTOSCI-2128: ArrowUp recall is per-conversation; clear on reset.
            clearLastSubmittedUserPromptForActiveSession();

            // Trigger immediate health poll to update RAG cartouche with new session context
            // Dispatch custom event that main.js health polling can listen for
            document.dispatchEvent(new CustomEvent('von:contextReset', {
                detail: { trigger: 'chat_reset', session_id: activeChatSessionId || null, session_name: activeChatSessionName || null }
            }));
        } else {
            alert('Error resetting context: ' + (data.error || 'Unknown error'));
        }
    } catch (error) {
        console.error('Error:', error);
        alert('Network error occurred while resetting context');
    }
}

function formatChatTimestamp(isoString) {
    if (!isoString) return new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const date = new Date(isoString);
    const now = new Date();
    const diffMs = now - date;
    const diffDays = diffMs / (1000 * 60 * 60 * 24);

    // Check if it's the same calendar day
    const isToday = now.getDate() === date.getDate() &&
        now.getMonth() === date.getMonth() &&
        now.getFullYear() === date.getFullYear();

    // Check if it was yesterday
    const yesterday = new Date(now);
    yesterday.setDate(now.getDate() - 1);
    const isYesterday = yesterday.getDate() === date.getDate() &&
        yesterday.getMonth() === date.getMonth() &&
        yesterday.getFullYear() === date.getFullYear();

    if (isToday) {
        // Today: "Today HH:MM"
        return 'Today ' + date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    } else if (isYesterday) {
        // Yesterday: "Yesterday HH:MM"
        return 'Yesterday ' + date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    } else if (diffDays < 7) {
        // Within a week: Day + Time
        return date.toLocaleString([], { weekday: 'short', hour: '2-digit', minute: '2-digit' });
    } else {
        // Older: Date + Time
        return date.toLocaleString([], { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
    }
}

function appendMessage(sender, message, turnId, hasLlmDebug = false, isHistory = false, timestampStr = null, fastpathMeta = null, ttsText = null, messageOptions = null) {
    const scrollableField = document.getElementById('scrollableField');
    if (!scrollableField) {
        console.error('[chatTab] appendMessage: scrollableField not found!');
        return;
    }

    const options = (messageOptions && typeof messageOptions === 'object')
        ? messageOptions
        : {};
    const externalActor = (
        options.externalActor && typeof options.externalActor === 'object'
    ) ? options.externalActor : null;
    const normalisedTurnId = normaliseChatTurnId(turnId);
    if (normalisedTurnId) {
        const matchingContainers = Array.from(
            scrollableField.querySelectorAll('.message-container[data-turn-id]')
        ).filter((container) => container.dataset.turnId === normalisedTurnId);
        if (matchingContainers.length > 0) {
            if (isHistory) {
                return matchingContainers[0];
            }
            matchingContainers.forEach((container) => container.remove());
            for (let index = transcriptTurns.length - 1; index >= 0; index -= 1) {
                if (transcriptTurns[index]?.turnId === normalisedTurnId) {
                    transcriptTurns.splice(index, 1);
                }
            }
        }
    }
    const renderAsAssistant = sender === 'Von'
        || (isHistory && sender === 'assistant')
        || options.assistantMessage === true;
    const shouldFollowNewMessage = !isHistory && isScrollableFieldNearBottom(scrollableField);

    try {
        const displayTimestamp = formatChatTimestamp(timestampStr);
        const historySuffix = isHistory ? ' (history)' : '';

        if (renderAsAssistant) {
            // Create a container for Von's response with image
            const messageContainer = document.createElement('div');
            messageContainer.style.cssText = 'display: flex; align-items: flex-start; margin-bottom: 15px; padding: 10px; background-color: #f8f9fa; border-radius: 8px; border-left: 4px solid #007bff;';
            messageContainer.className = 'message-container';
            messageContainer.classList.add('assistant-turn');
            let assistantAvatar;
            if (externalActor) {
                assistantAvatar = document.createElement('span');
                assistantAvatar.className = 'chat-imported-actor-avatar';
                assistantAvatar.textContent = String(sender || 'Agent').trim().slice(0, 1).toUpperCase() || 'A';
                assistantAvatar.setAttribute('aria-label', `${sender} (imported actor)`);
            } else {
                assistantAvatar = document.createElement('img');
                assistantAvatar.src = '/static/VonImageBig.png';
                assistantAvatar.alt = 'Von';
                assistantAvatar.style.cssText = 'width: 40px; height: 40px; border-radius: 50%; margin-right: 12px; flex-shrink: 0; object-fit: cover;';
            }

            // Add message content
            const messageContent = document.createElement('div');
            messageContent.className = 'message-body';
            // IMPORTANT: in a flex row, children default to min-width:auto, which can
            // force horizontal overflow and clip the header control buttons when the
            // left header text is long. min-width:0 allows proper wrapping/shrinking.
            messageContent.style.cssText = 'flex: 1 1 auto; min-width: 0; line-height: 1.5;';

            const rawText = String(message ?? '');

            const screenTextForTurn = rawText;
            let spokenTextForTurn = (typeof ttsText === 'string' && ttsText.trim()) ? ttsText : null;
            if (!spokenTextForTurn && turnId) {
                const debugDataForTurn = llmDebugData.get(turnId);
                const channels = resolvePresenterChannels(
                    debugDataForTurn?.presenter_channels,
                    debugDataForTurn?.display_elements
                );
                if (channels?.spoken && channels.spoken.trim()) {
                    spokenTextForTurn = channels.spoken;
                }
            }

            async function ensureHistorySpokenTalkTrack() {
                if (!isHistory || !turnId) {
                    return null;
                }

                const recentFailure = historySpokenBackfillFailures.get(turnId);
                if (recentFailure && (Date.now() - recentFailure.at) < HISTORY_SPOKEN_BACKFILL_FAILURE_COOLDOWN_MS) {
                    return null;
                }

                const debugDataForTurn = llmDebugData.get(turnId);
                const historyLocation = debugDataForTurn?.history_location;
                if (!historyLocation || typeof historyLocation !== 'object') {
                    return null;
                }

                try {
                    const resp = await fetch('/von/history/backfill_spoken', {
                        method: 'POST',
                        headers: buildChatFetchHeaders({ 'Content-Type': 'application/json' }),
                        body: JSON.stringify({ history_location: historyLocation })
                    });

                    const data = await resp.json().catch(() => ({}));
                    if (!resp.ok) {
                        const errMsg = (data && typeof data.error === 'string' && data.error.trim())
                            ? data.error.trim()
                            : `HTTP ${resp.status}`;
                        historySpokenBackfillFailures.set(turnId, { at: Date.now(), error: errMsg, shownAt: null });
                        console.warn('[chatTab] backfill_spoken failed:', data);
                        return null;
                    }

                    const displayElements = resolveDisplayElementsContract(data);
                    const channels = resolvePresenterChannels(
                        data?.presenter_channels,
                        displayElements
                    );
                    if (!channels?.spoken || !channels.spoken.trim()) {
                        return null;
                    }

                    // Cache the generated channels in-memory so subsequent clicks work.
                    const existing = llmDebugData.get(turnId);
                    const merged = {
                        ...(existing && typeof existing === 'object' ? existing : {}),
                        presenter_channels: channels
                    };
                    if (displayElements) {
                        merged.display_elements = displayElements;
                    }
                    setLlmDebugDataEntry(turnId, merged);

                    // Clear any previous failure cool-down.
                    historySpokenBackfillFailures.delete(turnId);

                    return channels.spoken;
                } catch (err) {
                    console.warn('[chatTab] backfill_spoken request failed:', err);
                    const errMsg = err && typeof err.message === 'string' && err.message.trim()
                        ? err.message.trim()
                        : 'Request failed';
                    historySpokenBackfillFailures.set(turnId, { at: Date.now(), error: errMsg, shownAt: null });
                    return null;
                }
            }

            const messageHeader = document.createElement('div');
            messageHeader.className = 'message-header';
            messageHeader.style.cssText = 'font-weight: bold; color: #007bff; margin-bottom: 5px; font-size: 0.9em; display: flex; flex-wrap: wrap; align-items: flex-start; gap: 8px; min-width: 0;';

            const headerText = document.createElement('span');
            headerText.textContent = `${externalActor ? sender : 'Von'} • ${displayTimestamp}${historySuffix}`;
            headerText.style.minWidth = '0';
            setUnambiguousTimestampTooltip(
                headerText,
                timestampStr || new Date().toISOString(),
                'Timestamp: '
            );
            messageHeader.appendChild(headerText);

            // Add fast-path indicator if the server bypassed the LLM.
            const fastpath = fastpathMeta;
            if (fastpath && fastpath.bypassed_llm) {
                const badge = document.createElement('span');
                const fastpathName = fastpath.name ? String(fastpath.name) : 'fast-path';
                badge.textContent = `Fast-path: ${fastpathName}`;
                badge.title = 'Deterministic fast-path used; LLM was bypassed.';
                badge.style.cssText = 'display: inline-flex; align-items: center; padding: 1px 6px; border-radius: 10px; font-size: 0.8em; background: #fff3cd; border: 1px solid #ffeeba; color: #856404;';
                messageHeader.appendChild(badge);
            }

            const copyMarkdownButton = document.createElement('button');
            copyMarkdownButton.className = 'btn-mini chat-copy-markdown';
            copyMarkdownButton.textContent = 'MD';
            copyMarkdownButton.title = 'Copy this agent message as Markdown to clipboard';
            copyMarkdownButton.addEventListener('click', (e) => {
                e.preventDefault();
                e.stopPropagation();

                const originalContent = copyMarkdownButton.innerHTML;
                const markdownString = rawText.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
                if (!markdownString.trim()) {
                    indicateClipboardResult(copyMarkdownButton, originalContent, false);
                    return;
                }

                const markSuccess = () => indicateClipboardResult(copyMarkdownButton, originalContent, true);
                const markFailure = (err) => {
                    console.error('[chatTab] Failed to copy agent Markdown:', err);
                    indicateClipboardResult(copyMarkdownButton, originalContent, false);
                };

                if (navigator.clipboard && navigator.clipboard.writeText) {
                    navigator.clipboard.writeText(markdownString)
                        .then(markSuccess)
                        .catch((err) => {
                            if (copyTextFallback(markdownString)) {
                                markSuccess();
                            } else {
                                markFailure(err);
                            }
                        });
                } else if (copyTextFallback(markdownString)) {
                    markSuccess();
                } else {
                    markFailure(new Error('Clipboard unsupported'));
                }
            });

            let copyButtonAppended = false;

            const debugData = turnId ? llmDebugData.get(turnId) : null;
            const hasHistoryLocation = !!debugData?.history_location;
            const shouldShowDebug = !!turnId && (hasLlmDebug || hasHistoryLocation);

            // Add LLM debug button if debug data is available or can be loaded on demand.
            if (shouldShowDebug) {
                const hasPayload = hasLlmDebugPayload(debugData);

                // Compact model badge (visible at-a-glance)
                if (hasPayload && debugData && debugData.model) {
                    const modelBadge = document.createElement('span');
                    modelBadge.className = 'chat-llm-model-badge';
                    modelBadge.textContent = String(debugData.model);
                    modelBadge.title = 'LLM model used for this turn';
                    messageHeader.appendChild(modelBadge);
                }

                const llmDebugButton = document.createElement('button');
                llmDebugButton.className = 'btn-mini llm-debug-button';
                llmDebugButton.textContent = 'LLM ℹ';
                llmDebugButton.dataset.turnId = turnId;
                setLlmDebugButtonCopyState(llmDebugButton, 'available');
                llmDebugButton.addEventListener('click', (event) => {
                    event.preventDefault();
                    event.stopPropagation();
                    if (event.shiftKey) {
                        void showLlmDebugPopup(turnId, { button: llmDebugButton });
                        return;
                    }
                    void copyLlmDebugJsonForTurn(turnId, llmDebugButton);
                });
                messageHeader.appendChild(llmDebugButton);

                messageHeader.appendChild(copyMarkdownButton);
                copyButtonAppended = true;

                if (hasPayload) {
                    const warnings = deriveLlmDebugWarnings(debugData);
                    const warningIndicator = createChatDebugWarningIndicator(warnings);
                    if (warningIndicator) {
                        messageHeader.appendChild(warningIndicator);
                    }
                }
            }
            if (!copyButtonAppended) {
                messageHeader.appendChild(copyMarkdownButton);
            }

            // JVNAUTOSCI-1043: Add Edit button for user editing of AI outputs
            if (options.readOnly !== true) {
                const editButton = document.createElement('button');
                editButton.className = 'btn-mini chat-edit-button';
                editButton.textContent = '✎';
                editButton.title = 'Edit this response';
                editButton.dataset.turnId = turnId;
                editButton.addEventListener('click', handleEditButtonClick);
                messageHeader.appendChild(editButton);
            }

            // Show "edited" indicator if this turn was previously edited
            const existingEdit = turnId ? turnEditHistory.get(turnId) : null;
            if (existingEdit && existingEdit.editedText) {
                const editedBadge = document.createElement('span');
                editedBadge.className = 'chat-edited-badge';
                editedBadge.textContent = 'edited';
                editedBadge.title = `Edited ${existingEdit.editCount || 1} time(s) — last at ${new Date(existingEdit.editedAt).toLocaleString()}`;
                messageHeader.appendChild(editedBadge);
            }

            const rightControls = document.createElement('span');
            rightControls.className = 'chat-message-controls';
            rightControls.style.cssText = 'margin-left: auto; display: inline-flex; align-items: center; gap: 6px; flex: 0 1 auto; flex-wrap: wrap; justify-content: flex-end; max-width: 100%;';

            const showTtsNotice = (text, options = {}) => {
                const msg = String(text ?? '').trim();
                if (!msg) {
                    return;
                }

                const existing = rightControls.querySelector('.chat-tts-notice');
                if (existing) {
                    try { existing.remove(); } catch (_) { /* ignore */ }
                }

                const notice = document.createElement('span');
                notice.className = 'chat-tts-notice';
                notice.textContent = msg;
                notice.title = msg;
                notice.setAttribute('role', 'status');
                notice.setAttribute('aria-live', 'polite');
                notice.style.cssText = [
                    'display: inline-flex',
                    'align-items: center',
                    'max-width: 320px',
                    'padding: 1px 6px',
                    'border-radius: 10px',
                    'font-size: 0.78em',
                    'line-height: 1.2',
                    'background: #fff3cd',
                    'border: 1px solid #ffeeba',
                    'color: #856404',
                    'white-space: nowrap',
                    'overflow: hidden',
                    'text-overflow: ellipsis'
                ].join(';');

                rightControls.insertBefore(notice, rightControls.firstChild);

                const durationMs = Number.isFinite(options.durationMs) ? options.durationMs : 4500;
                if (durationMs > 0) {
                    setTimeout(() => {
                        try { notice.remove(); } catch (_) { /* ignore */ }
                    }, durationMs);
                }
            };

            // Render-mode badge: shows whether this message is in Rendered/Text mode.
            const renderModeBadge = document.createElement('span');
            renderModeBadge.className = 'chat-render-mode-badge';
            rightControls.appendChild(renderModeBadge);

            // TTS controls (optional).
            const ttsSupported = isTextToSpeechSupported();
            const speakButton = document.createElement('button');
            speakButton.className = 'btn-mini chat-tts-button';
            speakButton.type = 'button';
            speakButton.textContent = 'Speak';
            speakButton.title = 'Speak the talk track aloud (Shift+click to speak the on-screen text)';
            if (!ttsSupported) {
                speakButton.disabled = true;
                speakButton.title = 'Text-to-speech is not supported in this browser.';
            }
            speakButton.addEventListener('click', async (e) => {
                e.preventDefault();
                e.stopPropagation();

                const wantsScreen = !!(e && e.shiftKey);
                const getScreenTextForSpeech = () => {
                    const displayed = (messageText && (messageText.innerText || messageText.textContent))
                        ? (messageText.innerText || messageText.textContent)
                        : screenTextForTurn;
                    return stripMarkdownForSpeech(displayed);
                };

                let desiredText = wantsScreen ? getScreenTextForSpeech() : (spokenTextForTurn || '');
                if (!wantsScreen && !String(desiredText ?? '').trim() && isHistory) {
                    // For legacy history turns, try to backfill a talk track on-demand.
                    const originalLabel = speakButton.textContent;
                    const originalTitle = speakButton.title;
                    const originalDisabled = speakButton.disabled;
                    try {
                        speakButton.disabled = true;
                        speakButton.textContent = 'Generating…';
                        speakButton.title = 'Generating talk track…';

                        const backfilled = await ensureHistorySpokenTalkTrack();
                        if (typeof backfilled === 'string' && backfilled.trim()) {
                            spokenTextForTurn = backfilled;
                            desiredText = backfilled;
                        }
                    } finally {
                        speakButton.disabled = originalDisabled;
                        speakButton.textContent = originalLabel;
                        speakButton.title = originalTitle;
                    }
                }

                // If no talk track is available, derive a plain narration from the screen text.
                // Never speak raw markdown.
                if (!String(desiredText ?? '').trim() && !wantsScreen) {
                    const failure = turnId ? historySpokenBackfillFailures.get(turnId) : null;
                    const reason = failure?.error ? ` (talk track unavailable: ${failure.error})` : '';
                    desiredText = getLegacyCanonicalOutcomeReportLead(screenTextForTurn)
                        ? deriveLegacyCanonicalOutcomeNarration(screenTextForTurn)
                        : deriveNarrationFromScreenText(screenTextForTurn);
                    speakButton.title = `Speaking a derived narration${reason}. Shift+click speaks the on-screen text.`;

                    if (failure && typeof failure === 'object') {
                        const shouldShow = !failure.shownAt || (typeof failure.at === 'number' && failure.shownAt < failure.at);
                        if (shouldShow) {
                            const errShort = typeof failure.error === 'string' ? failure.error.trim() : '';
                            const msg = errShort
                                ? `Talk track unavailable — speaking on-screen text (${errShort})`
                                : 'Talk track unavailable — speaking on-screen text';
                            showTtsNotice(msg);
                            historySpokenBackfillFailures.set(turnId, { ...failure, shownAt: Date.now() });
                        }
                    }
                }

                if (!String(desiredText ?? '').trim()) {
                    speakButton.title = 'Nothing to speak.';
                    return;
                }

                toggleSpeakTurn(turnId, desiredText, speakButton);
            });
            rightControls.appendChild(speakButton);

            const messageText = document.createElement('div');
            messageText.className = 'chat-message-text';
            messageText.style.cssText = 'color: #333; white-space: pre-wrap; text-align: left; font-weight: 400; overflow-wrap: anywhere; word-break: break-word; min-width: 0;';
            try {
                const debugData = turnId ? llmDebugData.get(turnId) : null;
                const canRenderMarkdown = shouldRenderMarkdownForAssistant(rawText, debugData);

                if (canRenderMarkdown) {
                    const toggleButton = document.createElement('button');
                    toggleButton.className = 'btn-mini chat-render-toggle';
                    toggleButton.textContent = 'Text';
                    toggleButton.title = 'Show the original (raw) text';
                    toggleButton.addEventListener('click', (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        const currentMode = messageText?.dataset?.renderMode || 'rendered';
                        const nextMode = currentMode === 'text' ? 'rendered' : 'text';
                        setVonMessageRenderMode(messageText, nextMode, rawText, debugData);
                        toggleButton.textContent = nextMode === 'text' ? 'Rendered' : 'Text';
                        toggleButton.title = nextMode === 'text'
                            ? 'Show the rendered markdown view'
                            : 'Show the original (raw) text';

                        updateChatRenderModeBadge(renderModeBadge, messageText, {
                            canRenderMarkdown: true,
                            shouldRenderMarkdown: shouldRenderMarkdownForAssistant(rawText, debugData),
                            model: debugData?.model
                        });
                    });
                    rightControls.appendChild(toggleButton);
                }

                // Add delete button after the toggle so the close (✕) is right-most.
                if (turnId && options.readOnly !== true) {
                    const deleteButton = document.createElement('button');
                    deleteButton.className = 'btn-mini btn-delete-exchange';
                    deleteButton.type = 'button';
                    deleteButton.textContent = '✕';
                    deleteButton.title = 'Delete this exchange';
                    deleteButton.addEventListener('click', (e) => {
                        e.stopPropagation();
                        deleteExchange(turnId, false);
                    });
                    rightControls.appendChild(deleteButton);
                }

                renderAssistantMessageContent(messageText, rawText, debugData);

                updateChatRenderModeBadge(renderModeBadge, messageText, {
                    canRenderMarkdown,
                    shouldRenderMarkdown: shouldRenderMarkdownForAssistant(rawText, debugData),
                    model: debugData?.model
                });

                // Auto-speak new assistant responses when enabled.
                if (!isHistory && turnId && ttsSupported && isChatTtsEnabled()) {
                    // Auto-speak uses the talk track only (never the screen channel).
                    if (spokenTextForTurn && spokenTextForTurn.trim()) {
                        toggleSpeakTurn(turnId, spokenTextForTurn, speakButton);
                    }
                }
            } catch (e) {
                console.error('[chatTab] Failed to render Von message:', e);
                messageText.textContent = String(message);
            }

            messageHeader.appendChild(rightControls);

            const thinkingCardSlot = turnId ? document.createElement('div') : null;
            if (thinkingCardSlot) {
                thinkingCardSlot.className = 'thinking-card-inline-slot';
            }
            messageContent.appendChild(messageHeader);
            messageContent.appendChild(messageText);
            try {
                const debugData = turnId ? llmDebugData.get(turnId) : null;
                console.log('[chatTab] Quick reply check:', {
                    turnId,
                    hasDebugData: !!debugData,
                    buttonifyExists: debugData?.buttonify !== undefined,
                    buttonifyOptions: debugData?.buttonify?.options
                });
                appendQuickReplyButtons(messageContent, debugData?.buttonify);
                renderConceptQaReceipt(
                    messageContent,
                    options.conceptQaReceipt || debugData,
                    {
                        onConfirm: confirmActiveConceptQaFormalisation,
                        getConfirmationState: (receipt) => (
                            getConceptQaConfirmationUiState(receipt)
                        ),
                    },
                );
            } catch (err) {
                console.warn('[chatTab] Assistant turn enrichment rendering failed:', err);
            }
            if (thinkingCardSlot) {
                messageContent.appendChild(thinkingCardSlot);
            }
            messageContainer.appendChild(assistantAvatar);
            messageContainer.appendChild(messageContent);

            if (turnId) messageContainer.dataset.turnId = turnId;
            scrollableField.appendChild(messageContainer);
        } else {
            // For user messages and errors, use simpler styling
            const messageContainer = document.createElement('div');
            messageContainer.style.cssText = 'margin-bottom: 15px; padding: 10px; background-color: #fff; border-radius: 8px; border-left: 4px solid #28a745;';
            messageContainer.className = 'message-container';
            messageContainer.classList.add(sender === 'Error' ? 'error-turn' : 'user-turn');

            if (sender === 'Error') {
                messageContainer.style.borderLeftColor = '#dc3545';
                messageContainer.style.backgroundColor = '#fff5f5';
            }

            const messageHeader = document.createElement('div');
            messageHeader.className = 'message-header';
            messageHeader.style.cssText = 'font-weight: bold; margin-bottom: 5px; font-size: 0.9em; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; min-width: 0;';
            messageHeader.style.color = sender === 'Error' ? '#dc3545' : '#28a745';

            const headerText = document.createElement('span');
            headerText.textContent = `${sender} • ${displayTimestamp}${historySuffix}`;
            setUnambiguousTimestampTooltip(
                headerText,
                timestampStr || new Date().toISOString(),
                'Timestamp: '
            );
            messageHeader.appendChild(headerText);

            // Add LLM debug button for errors if debug data available
            if (sender === 'Error' && hasLlmDebug && turnId) {
                const llmDebugButton = document.createElement('button');
                llmDebugButton.className = 'btn-mini llm-debug-button';
                llmDebugButton.textContent = 'LLM ℹ';
                llmDebugButton.dataset.turnId = turnId;
                setLlmDebugButtonCopyState(llmDebugButton, 'available');
                llmDebugButton.addEventListener('click', (event) => {
                    event.preventDefault();
                    event.stopPropagation();
                    if (event.shiftKey) {
                        void showLlmDebugPopup(turnId, { button: llmDebugButton });
                        return;
                    }
                    void copyLlmDebugJsonForTurn(turnId, llmDebugButton);
                });
                messageHeader.appendChild(llmDebugButton);

                const debugData = llmDebugData.get(turnId);
                const warnings = deriveLlmDebugWarnings(debugData);
                const warningIndicator = createChatDebugWarningIndicator(warnings);
                if (warningIndicator) {
                    messageHeader.appendChild(warningIndicator);
                }
            }

            if (sender === 'Error' && options.diagnosticsPayload && typeof options.diagnosticsPayload === 'object') {
                const copyDiagnosticsButton = document.createElement('button');
                copyDiagnosticsButton.className = 'btn-mini chat-error-copy-diagnostics-btn';
                copyDiagnosticsButton.type = 'button';
                copyDiagnosticsButton.textContent = 'Copy diagnostic snapshot';
                copyDiagnosticsButton.title = 'Copy structured diagnostics as JSON';
                copyDiagnosticsButton.addEventListener('click', () => {
                    void copyJsonPayloadToClipboard(
                        options.diagnosticsPayload,
                        copyDiagnosticsButton,
                        'Copy diagnostic snapshot'
                    );
                });
                messageHeader.appendChild(copyDiagnosticsButton);
            }

            // Add delete button for user messages
            if (turnId && options.readOnly !== true) {
                const deleteButton = document.createElement('button');
                deleteButton.className = 'btn-mini btn-delete-exchange';
                deleteButton.type = 'button';
                deleteButton.textContent = '✕';
                deleteButton.title = 'Delete this exchange';
                deleteButton.addEventListener('click', (e) => {
                    e.stopPropagation();
                    deleteExchange(turnId, true);
                });
                messageHeader.appendChild(deleteButton);
            }

            const messageText = document.createElement('div');
            messageText.className = 'chat-message-text';
            messageText.style.cssText = 'color: #333; white-space: pre-wrap; text-align: left; font-weight: 400; overflow-wrap: anywhere; word-break: break-word; min-width: 0;';
            const userText = String(message ?? '');
            const shouldRenderUserMarkdown = sender === 'User' && detectMarkdown(userText);
            if (shouldRenderUserMarkdown) {
                messageText.classList.add('markdown-rendered', 'chat-markdown');
                messageText.style.whiteSpace = 'normal';
                messageText.textContent = userText;
                void renderChatMarkdownIntoContainer(messageText, userText).catch((err) => {
                    console.error('[chatTab] Server markdown render failed for user message; falling back to plain text:', err);
                    messageText.textContent = userText;
                });
            } else {
                try {
                    cartouchifyElementText(messageText, userText);
                    if (!messageText.textContent && messageText.childNodes.length === 0 && userText) {
                        messageText.textContent = userText;
                    }
                    hydrateChatConceptCartouches(messageText);
                    void resolveInlineVontologyAliasesInElement(messageText);
                } catch (e) {
                    console.error('[chatTab] cartouchifyElementText failed for User/Error message:', e);
                    messageText.textContent = userText;
                }
            }

            messageContainer.appendChild(messageHeader);
            messageContainer.appendChild(messageText);
            try {
                renderConceptQaReceipt(
                    messageContainer,
                    options.conceptQaReceipt,
                    {
                        onConfirm: confirmActiveConceptQaFormalisation,
                        getConfirmationState: (receipt) => (
                            getConceptQaConfirmationUiState(receipt)
                        ),
                    },
                );
            } catch (err) {
                console.warn('[chatTab] User turn representation receipt rendering failed:', err);
            }
            if (turnId && sender === 'Error') {
                const thinkingCardSlot = document.createElement('div');
                thinkingCardSlot.className = 'thinking-card-inline-slot';
                messageContainer.appendChild(thinkingCardSlot);
            }
            if (turnId) messageContainer.dataset.turnId = turnId;
            scrollableField.appendChild(messageContainer);
        }

        recordTranscriptTurn(sender, message, { turnId, isHistory, timestamp: timestampStr || new Date().toISOString() });

        // Follow new output only when the reader had not deliberately moved away.
        if (shouldFollowNewMessage) {
            scrollConversationToEnd(scrollableField, { smooth: false });
        }
        updateScrollToEndButtonVisibility(scrollableField);
    } catch (err) {
        console.error('[chatTab] appendMessage crashed:', err);
    }
}

function appendResetNotice(scrollableField) {
    if (!scrollableField) {
        return;
    }

    const resetMessage = document.createElement('div');
    resetMessage.className = 'reset-notice';
    resetMessage.textContent = 'Context reset successfully. You can start a new conversation.';
    scrollableField.appendChild(resetMessage);
}

function setLlmDebugButtonCopyState(button, state) {
    if (!(button instanceof HTMLButtonElement)) {
        return;
    }
    const defaultLabel = button.dataset.defaultLabel || button.textContent || 'LLM ℹ';
    button.dataset.defaultLabel = defaultLabel;
    delete button.dataset.copyFeedback;
    button.classList.remove(
        LLM_DEBUG_BUTTON_COPY_AVAILABLE_CLASS,
        LLM_DEBUG_BUTTON_COPIED_CLASS,
        LLM_DEBUG_BUTTON_COPY_FAILED_CLASS
    );

    if (state === 'copied') {
        button.textContent = 'Copied';
        button.dataset.copyFeedback = 'Copied';
        button.classList.add(LLM_DEBUG_BUTTON_COPIED_CLASS);
        button.setAttribute('title', 'Copied bounded turn capsule JSON. Shift-click to open details.');
        button.setAttribute('aria-label', 'Bounded turn capsule JSON copied. Shift-click to open details.');
        return;
    }
    if (state === 'failed') {
        button.textContent = 'Copy failed';
        button.dataset.copyFeedback = 'Copy failed';
        button.classList.add(LLM_DEBUG_BUTTON_COPY_FAILED_CLASS);
        button.setAttribute('title', 'Copy failed. Shift-click to open LLM details.');
        button.setAttribute('aria-label', 'Copy bounded turn capsule JSON failed. Shift-click to open details.');
        return;
    }

    button.textContent = defaultLabel;
    button.classList.add(LLM_DEBUG_BUTTON_COPY_AVAILABLE_CLASS);
    button.setAttribute('title', 'Copy bounded turn capsule JSON. Shift-click to open details.');
    button.setAttribute('aria-label', 'Copy bounded turn capsule JSON. Shift-click to open details.');
}

// Initialize LLM debug popup handlers
function initializeLlmDebugPopup() {
    const popup = document.getElementById('chatLlmDebugPopup');
    const closeBtn = document.getElementById('closeChatLlmDebug');
    const copyBtn = document.getElementById('copyChatLlmDebugJson');

    if (!popup || !closeBtn || !copyBtn) {
        console.warn('[chatTab] LLM debug popup elements not found');
        return;
    }

    // Close button handler
    closeBtn.addEventListener('click', () => {
        popup.classList.add('hidden');
        popup.setAttribute('aria-hidden', 'true');
    });

    // Copy JSON button handler
    copyBtn.addEventListener('click', async () => {
        const currentDebugData = popup.dataset.currentDebugData;
        if (currentDebugData) {
            await copyJsonTextWithButtonFeedback(copyBtn, currentDebugData);
        }
    });

    // Close on escape key
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && !popup.classList.contains('hidden')) {
            closeBtn.click();
        }
    });
}

function _getWorkflowExecutionTelemetry(debugData) {
    const normaliseTraceRef = (entry, source) => {
        if (!entry || typeof entry !== 'object') {
            return null;
        }
        const executionId = typeof entry.execution_id === 'string'
            ? entry.execution_id.trim()
            : (typeof entry.execution_trace_id === 'string' ? entry.execution_trace_id.trim() : '');
        const instanceId = typeof entry.instance_id === 'string'
            ? entry.instance_id.trim()
            : (typeof entry.workflow_instance_id === 'string' ? entry.workflow_instance_id.trim() : '');
        if (!executionId && !instanceId) {
            return null;
        }
        return {
            ...entry,
            execution_id: executionId || null,
            instance_id: instanceId || null,
            workflow_id: (
                typeof entry.workflow_id === 'string'
                    ? entry.workflow_id
                    : (
                        typeof entry.selected_workflow_id === 'string'
                            ? entry.selected_workflow_id
                            : null
                    )
            ),
            trace_source: source
        };
    };

    const selectedWorkflowCandidates = [
        debugData?.turn_execution_diagnostics?.workflow_selection?.selected_workflow_id,
        debugData?.turn_execution_diagnostics?.workflow_routing_diagnostics?.selected_workflow_id,
        debugData?.workflow_routing_diagnostics?.selected_workflow_id,
        debugData?.workflow_routing?.workflow_id,
        debugData?.selected_workflow_trace?.selected_workflow_id,
        debugData?.selected_workflow_trace?.workflow_id,
        debugData?.turn_execution_record?.workflow_selection?.selected_workflow_id
    ];
    const selectedWorkflowId = selectedWorkflowCandidates.find((value) => (
        typeof value === 'string' && value.trim()
    ))?.trim() || '';

    const traces = [];
    const seenTraceRefs = new Set();
    const appendTrace = (trace) => {
        if (!trace) {
            return;
        }
        const key = `${trace.execution_id || ''}|${trace.instance_id || ''}`;
        if (seenTraceRefs.has(key)) {
            return;
        }
        seenTraceRefs.add(key);
        traces.push(trace);
    };

    appendTrace(normaliseTraceRef(debugData?.selected_workflow_trace, 'selected_workflow_trace'));
    appendTrace(normaliseTraceRef(
        debugData?.turn_execution_record?.execution?.selected_workflow_trace,
        'turn_execution_record.execution.selected_workflow_trace'
    ));
    if (Array.isArray(debugData?.aux_llm_calls)) {
        debugData.aux_llm_calls.forEach((entry) => {
            if (!entry || typeof entry !== 'object') {
                return;
            }
            if (entry.type === 'workflow_execution_trace') {
                appendTrace(normaliseTraceRef(entry, 'aux_llm_calls'));
            } else if (entry.type === 'workflow_use_episode') {
                appendTrace(normaliseTraceRef(entry, 'workflow_use_episode'));
            }
        });
    }

    const primaryTrace = traces.find((entry) => (
        entry.trace_source === 'selected_workflow_trace'
        || entry.trace_source === 'turn_execution_record.execution.selected_workflow_trace'
    )) || traces.find((entry) => (
        selectedWorkflowId
        && typeof entry.workflow_id === 'string'
        && entry.workflow_id.trim().toLowerCase() === selectedWorkflowId.toLowerCase()
    )) || null;

    return {
        traces,
        primaryTrace
    };
}

function _buildLlmDebugCopyPayload(debugData, metadata, workflowExecutionTelemetry) {
    return buildLlmDebugLocatorPayload({
        turnId: null,
        debugData,
        metadata,
        workflowExecutionTelemetry
    });
}

function buildLlmDebugMetadata(debugData) {
    const metadata = {
        model: debugData?.model || 'Unknown',
        message_count: debugData?.messages?.length || 0
    };

    const renderPlan = (debugData && typeof debugData === 'object') ? debugData.render_plan : null;
    const renderPlanMetadata = buildRenderPlanMetadataSummary(renderPlan);
    if (renderPlanMetadata) {
        metadata.render_plan = renderPlanMetadata;
    }

    const turnDiagnostics = (debugData && typeof debugData === 'object') ? debugData.turn_diagnostics : null;
    if (turnDiagnostics && typeof turnDiagnostics === 'object') {
        const events = Array.isArray(turnDiagnostics.events)
            ? turnDiagnostics.events.filter(event => event && typeof event === 'object')
            : [];
        const categories = toUniqueStringList(
            events.map(event => {
                const value = event.type ?? event.category;
                return (typeof value === 'string') ? value : '';
            })
        );
        metadata.turn_diagnostics = {
            event_count: events.length,
            categories,
            latest_event_type: categories.length ? categories[categories.length - 1] : null
        };
    }

    // JVNAUTOSCI-1070: Only include speech_planning summary (has char counts).
    // Do NOT copy full presenter_channels text - it's already at top level.
    if (debugData?.speech_planning) {
        metadata.speech_planning = debugData.speech_planning;
    }
    if (debugData?.speech_playback) {
        metadata.speech_playback = debugData.speech_playback;
    }

    // LLM interaction telemetry (JVNAUTOSCI-877)
    const llmInteraction = (debugData && typeof debugData === 'object') ? debugData.llm_interaction : null;
    if (llmInteraction && typeof llmInteraction === 'object') {
        const calls = Array.isArray(llmInteraction.calls) ? llmInteraction.calls : [];

        const callTypeCounts = {};
        const callModels = new Set();
        for (const call of calls) {
            if (!call || typeof call !== 'object') {
                continue;
            }
            const t = typeof call.type === 'string' ? call.type : 'unknown';
            callTypeCounts[t] = (callTypeCounts[t] || 0) + 1;

            if (typeof call.model === 'string' && call.model.trim().length > 0) {
                callModels.add(call.model.trim());
            }
        }

        metadata.llm_interaction = {
            requested_model: llmInteraction.requested_model ?? null,
            requested_model_parameters: llmInteraction.requested_model_parameters ?? null,
            orchestrator_used: llmInteraction.orchestrator_used ?? null,
            duration_ms: llmInteraction.duration_ms ?? null,
            server_elapsed_ms: llmInteraction.server_elapsed_ms ?? null,
            usage: llmInteraction.usage ?? null,
            call_count: calls.length,
            call_type_counts: callTypeCounts,
            call_models: Array.from(callModels)
        };
    }

    // Add context statistics if available
    if (debugData?.context_stats) {
        const sentStats = debugData.context_stats.sent_to_llm;
        const storedStats = debugData.context_stats.stored_context;

        if (sentStats) {
            metadata.context_sent_to_llm = {
                total_messages: sentStats.total_messages,
                total_chars: sentStats.total_chars,
                largest_message: sentStats.largest_message
            };
        }

        if (storedStats) {
            metadata.stored_context = {
                total_messages: storedStats.total_messages,
                total_chars: storedStats.total_chars
            };
        }
    }

    // Add tool statistics if available
    if (debugData?.tool_stats) {
        metadata.mcp_tools_used = {
            tool_count: debugData.tool_stats.tool_count,
            total_chars: debugData.tool_stats.total_chars,
            truncated_count: debugData.tool_stats.truncated_count
        };
    }

    // Surface internal MCP execution caps + usage in the visible debug metadata.
    const internalMcp = (debugData && typeof debugData === 'object') ? debugData.internal_mcp : null;
    if (internalMcp && typeof internalMcp === 'object') {
        const caps = internalMcp.execution_caps;
        const progress = internalMcp.tool_use_progress;
        const toolInvocationsCount = Array.isArray(debugData.tool_invocations) ? debugData.tool_invocations.length : 0;

        const maxToolInvocations = (caps && Number.isFinite(caps.max_tool_invocations)) ? caps.max_tool_invocations : null;
        const toolBatchCap = (caps && Number.isFinite(caps.tool_batch_cap)) ? caps.tool_batch_cap : null;

        const usageAgainstCaps = {
            tool_invocations_done: toolInvocationsCount,
            tool_invocations_cap: maxToolInvocations,
            tool_invocations_remaining: (typeof maxToolInvocations === 'number') ? Math.max(0, maxToolInvocations - toolInvocationsCount) : null,
            tool_invocations_exceeded: (typeof maxToolInvocations === 'number') ? toolInvocationsCount > maxToolInvocations : null,
            tool_batch_cap: toolBatchCap,
            estimated_batches: (typeof toolBatchCap === 'number' && toolBatchCap > 0) ? Math.ceil(toolInvocationsCount / toolBatchCap) : null,
            estimated_last_batch_size: (typeof toolBatchCap === 'number' && toolBatchCap > 0)
                ? (toolInvocationsCount === 0 ? 0 : (toolInvocationsCount % toolBatchCap || toolBatchCap))
                : null
        };

        if (caps || progress) {
            metadata.internal_mcp = {
                execution_caps: caps || null,
                usage_against_caps: usageAgainstCaps,
                tool_use_progress: progress || null
            };
        }
    }

    if (debugData?.error !== undefined) {
        metadata.error = debugData.error;
    }

    return metadata;
}

export function __testOnly_buildLlmDebugMetadata(debugData) {
    return buildLlmDebugMetadata(debugData);
}

export async function __testOnly_buildLlmDebugClipboardJsonForTurn(turnId, options = {}) {
    return buildLlmDebugClipboardJsonForTurn(turnId, options);
}

export async function __testOnly_copyLlmDebugJsonForTurn(turnId, button) {
    return copyLlmDebugJsonForTurn(turnId, button);
}

function hasLlmDebugPayload(debugData) {
    if (!debugData || typeof debugData !== 'object') {
        return false;
    }
    return Boolean(
        debugData.model
        || debugData.response
        || debugData.error !== undefined
        || (Array.isArray(debugData.messages) && debugData.messages.length > 0)
        || (Array.isArray(debugData.tool_invocations) && debugData.tool_invocations.length > 0)
        || (Array.isArray(debugData.aux_llm_calls) && debugData.aux_llm_calls.length > 0)
        || debugData.llm_interaction
        || debugData.context_stats
        || resolveStoredTurnFailureCapsule(debugData)
        || extractThinkingCriticOutput(debugData)
    );
}

function hasLlmDebugLocatorReference(debugData) {
    if (!debugData || typeof debugData !== 'object') {
        return false;
    }
    return Boolean(
        hasLlmDebugPayload(debugData)
        || debugData.history_location
        || resolveConversationTelemetryRequestId(debugData)
    );
}

async function loadLlmDebugDataForTurn(turnId, options = {}) {
    const existing = llmDebugData.get(turnId);
    if (hasLlmDebugPayload(existing)) {
        return existing;
    }

    const historyLocation = existing?.history_location;
    if (!historyLocation || !historyLocation.session_id || historyLocation.history_index === undefined || historyLocation.history_index === null) {
        return null;
    }

    if (llmDebugFetchInFlight.has(turnId)) {
        return llmDebugFetchInFlight.get(turnId);
    }

    const button = options.button;
    const originalText = button?.textContent;
    const originalTitle = button?.title;
    if (button) {
        button.disabled = true;
        button.classList.add('loading');
        button.textContent = 'LLM ...';
        button.title = 'Loading LLM interaction details';
    }

    const fetchPromise = (async () => {
        try {
            const historyAccessArgs = buildChatHistoryAccessArgs({
                sessionId: historyLocation.session_id,
                historyIndex: historyLocation.history_index
            });
            const params = new URLSearchParams();
            Object.entries(historyAccessArgs).forEach(([key, value]) => {
                if (value === undefined || value === null || value === '') {
                    return;
                }
                params.set(key, String(value));
            });
            console.log('[chatTab] loadLlmDebugDataForTurn request:', { turnId, session_id: historyLocation.session_id, history_index: historyLocation.history_index });
            const response = await fetch(`/von/history/debug?${params.toString()}`, {
                cache: 'no-store',
                headers: buildChatFetchHeaders()
            });
            let data = null;
            try {
                data = await response.json();
            } catch (_) {
                data = null;
            }
            console.log('[chatTab] loadLlmDebugDataForTurn response:', { status: response.status, ok: response.ok, success: data?.success, error: data?.error, hasLlmDebugData: !!data?.llm_debug_data });
            if (!response.ok) {
                if (response.status === 404 && data?.error === 'debug_not_available') {
                    showToast('No LLM debug data stored for this turn.');
                    renderRetainedThinkingUnavailableState(turnId);
                }
                return null;
            }
            if (data?.success === false && data?.error === 'debug_not_available') {
                showToast('No LLM debug data stored for this turn.');
                renderRetainedThinkingUnavailableState(turnId);
                return null;
            }
            if (!data || typeof data.llm_debug_data !== 'object') {
                renderRetainedThinkingUnavailableState(turnId);
                return null;
            }
            const merged = {
                ...data.llm_debug_data,
                history_location: historyLocation,
                timestamp: (
                    data.llm_debug_data.timestamp !== undefined
                    && data.llm_debug_data.timestamp !== null
                )
                    ? data.llm_debug_data.timestamp
                    : (existing?.timestamp || null)
            };
            setLlmDebugDataEntry(turnId, merged);
            refreshInspectableReferencesForTurn(turnId, merged);
            if (!renderRetainedThinkingCardForDebugData(turnId, merged)) {
                renderRetainedThinkingUnavailableState(turnId);
            }
            return merged;
        } catch (err) {
            console.warn('[chatTab] Failed to load LLM debug data:', err);
            renderRetainedThinkingUnavailableState(turnId, 'Thinking details could not be loaded for this turn');
            return null;
        } finally {
            if (button) {
                button.disabled = false;
                button.classList.remove('loading');
                button.textContent = originalText || 'LLM ℹ';
                if (originalTitle) {
                    button.title = originalTitle;
                } else {
                    button.title = 'Load LLM interaction details';
                }
            }
        }
    })();

    llmDebugFetchInFlight.set(turnId, fetchPromise);
    fetchPromise.finally(() => {
        llmDebugFetchInFlight.delete(turnId);
    });
    return fetchPromise;
}

function utf8ByteLength(value) {
    let byteLength = 0;
    for (const character of String(value ?? '')) {
        const codePoint = character.codePointAt(0);
        if (codePoint <= 0x7f) {
            byteLength += 1;
        } else if (codePoint <= 0x7ff) {
            byteLength += 2;
        } else if (codePoint <= 0xffff) {
            byteLength += 3;
        } else {
            byteLength += 4;
        }
    }
    return byteLength;
}

function truncateUtf8Text(value, maxBytes) {
    const text = String(value ?? '');
    if (utf8ByteLength(text) <= maxBytes) {
        return { text, truncated: false };
    }

    let result = '';
    let byteLength = 0;
    for (const character of text) {
        const characterBytes = utf8ByteLength(character);
        if (byteLength + characterBytes > maxBytes) {
            break;
        }
        result += character;
        byteLength += characterBytes;
    }
    return { text: result, truncated: true };
}

function unicodeCharacterCount(value) {
    let count = 0;
    for (const _character of String(value ?? '')) {
        count += 1;
    }
    return count;
}

function redactCredentialLikeText(value) {
    let text = String(value ?? '');
    let redactedCount = 0;
    const replace = (pattern, replacement) => {
        text = text.replace(pattern, (...args) => {
            redactedCount += 1;
            return typeof replacement === 'function'
                ? replacement(...args)
                : replacement;
        });
    };

    replace(/\b(?:Authorization\s*[:=]\s*)?(?:Bearer|Basic)\s+[A-Za-z0-9._~+/-]+=*/gi, '[REDACTED-AUTHORIZATION]');
    replace(/\bsk-[A-Za-z0-9_-]{8,}\b/g, '[REDACTED]');
    replace(/\beyJ[A-Za-z0-9_-]+\.eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b/g, '[REDACTED]');
    replace(
        /\b(api[_-]?key|access[_-]?token|refresh[_-]?token|id[_-]?token|password|passwd|secret|client[_-]?secret|cookie|session[_-]?token|signature|nonce)(\s*[:=]\s*)("[^"]*"|'[^']*'|[^\s,;&]+)/gi,
        (_match, label, separator) => `${label}${separator}[REDACTED]`
    );
    replace(
        /\b((?:mongodb(?:\+srv)?|postgres(?:ql)?|mysql|redis):\/\/)[^@\s/]+@/gi,
        (_match, scheme) => `${scheme}[REDACTED]@`
    );
    replace(
        /-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z0-9 ]*PRIVATE KEY-----/gi,
        '[REDACTED-PRIVATE-KEY]'
    );
    return { text, redactedCount };
}

function projectCapsuleToken(value, { maxBytes = 256, pattern = null } = {}) {
    if (typeof value !== 'string') {
        return null;
    }
    const redacted = redactCredentialLikeText(value);
    if (redacted.redactedCount > 0) {
        return null;
    }
    const token = redacted.text.trim();
    if (!token || utf8ByteLength(token) > maxBytes) {
        return null;
    }
    if (pattern && !pattern.test(token)) {
        return null;
    }
    return token;
}

function projectCapsuleTextSurface(value, { maxBytes, requireNonAuthoritative = false } = {}) {
    if (!value || typeof value !== 'object' || Array.isArray(value) || typeof value.text !== 'string') {
        return null;
    }
    if (requireNonAuthoritative && value.authority !== 'non_authoritative') {
        return null;
    }

    const redacted = redactCredentialLikeText(value.text);
    const bounded = truncateUtf8Text(redacted.text, maxBytes);
    const locallyChanged = redacted.redactedCount > 0 || bounded.truncated;
    const projected = {
        text: bounded.text
    };
    if (locallyChanged) {
        projected.char_count = unicodeCharacterCount(bounded.text);
    } else if (Number.isSafeInteger(value.char_count) && value.char_count >= 0) {
        projected.char_count = value.char_count;
    }
    if (
        !locallyChanged
        && typeof value.sha256 === 'string'
        && /^[a-f0-9]{64}$/i.test(value.sha256.trim())
    ) {
        projected.sha256 = value.sha256.trim().toLowerCase();
    }
    if (typeof value.truncated === 'boolean' || bounded.truncated) {
        projected.truncated = Boolean(value.truncated || bounded.truncated);
    }
    if (requireNonAuthoritative) {
        projected.authority = 'non_authoritative';
    }
    return {
        projected,
        redactedCount: redacted.redactedCount,
        truncated: bounded.truncated
    };
}

function projectCapsuleError(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        return null;
    }
    const code = projectCapsuleToken(value.code, {
        maxBytes: 160,
        pattern: /^[A-Za-z0-9][A-Za-z0-9_.:-]*$/
    });
    const projected = {};
    if (code) {
        projected.code = code;
    }
    let redactedCount = 0;
    let truncated = false;
    const preview = projectCapsuleTextSurface(value.preview, { maxBytes: 600 });
    if (preview) {
        projected.preview = preview.projected;
        redactedCount += preview.redactedCount;
        truncated = preview.truncated;
    }
    if (Object.keys(projected).length === 0) {
        return null;
    }
    return { projected, redactedCount, truncated };
}

function projectCapsuleEffect(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        return null;
    }
    const projected = {};
    const identifierFields = [
        'effect_id',
        'recovered_by_effect_id',
        'workflow_id',
        'instance_id',
        'evidence_id'
    ];
    identifierFields.forEach((fieldName) => {
        const projectedValue = projectCapsuleToken(value[fieldName], { maxBytes: 256 });
        if (projectedValue) {
            projected[fieldName] = projectedValue;
        }
    });
    const name = projectCapsuleToken(value.name, { maxBytes: 320 });
    if (name) {
        projected.name = name;
    }
    [
        'initial_status',
        'status',
        'current_outcome_status',
        'reconciliation_status',
        'canonical_readback_verdict'
    ].forEach((fieldName) => {
        const projectedValue = projectCapsuleToken(value[fieldName], {
            maxBytes: 128,
            pattern: /^[A-Za-z0-9][A-Za-z0-9_.:-]*$/
        });
        if (projectedValue) {
            projected[fieldName] = projectedValue;
        }
    });
    ['changed', 'outcome_resolved'].forEach((fieldName) => {
        if (typeof value[fieldName] === 'boolean') {
            projected[fieldName] = value[fieldName];
        }
    });

    let redactedCount = 0;
    let truncated = false;
    const error = projectCapsuleError(value.error);
    if (error) {
        projected.error = error.projected;
        redactedCount += error.redactedCount;
        truncated = error.truncated;
    }
    if (Object.keys(projected).length === 0) {
        return null;
    }
    return { projected, redactedCount, truncated };
}

function projectTurnFailureCapsule(value, { expectedRequestId = null } = {}) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        return null;
    }
    if (value.schema_version !== TURN_FAILURE_CAPSULE_SCHEMA_VERSION) {
        return null;
    }

    const requestId = projectCapsuleToken(value.request_id, { maxBytes: 256 });
    const terminalStatus = projectCapsuleToken(value.terminal_status, {
        maxBytes: 128,
        pattern: /^[A-Za-z0-9][A-Za-z0-9_.:-]*$/
    });
    const responseAuthority = projectCapsuleToken(value.response_authority, {
        maxBytes: 128,
        pattern: /^[A-Za-z0-9][A-Za-z0-9_.:-]*$/
    });
    const cleanExpectedRequestId = typeof expectedRequestId === 'string'
        ? expectedRequestId.trim()
        : '';
    if (
        !requestId
        || !terminalStatus
        || !responseAuthority
        || (cleanExpectedRequestId && requestId !== cleanExpectedRequestId)
    ) {
        return null;
    }

    const projected = {
        schema_version: TURN_FAILURE_CAPSULE_SCHEMA_VERSION
    };
    const generatedAtUtc = projectCapsuleToken(value.generated_at_utc, { maxBytes: 64 });
    if (generatedAtUtc && Number.isFinite(Date.parse(generatedAtUtc))) {
        projected.generated_at_utc = generatedAtUtc;
    }
    projected.request_id = requestId;
    projected.terminal_status = terminalStatus;
    projected.response_authority = responseAuthority;

    if (value.producer && typeof value.producer === 'object' && !Array.isArray(value.producer)) {
        const producer = {};
        ['code_version', 'git_commit'].forEach((fieldName) => {
            const projectedValue = projectCapsuleToken(value.producer[fieldName], { maxBytes: 256 });
            if (projectedValue) {
                producer[fieldName] = projectedValue;
            }
        });
        if (Object.keys(producer).length > 0) {
            projected.producer = producer;
        }
    }

    let frontendRedactedCount = 0;
    let frontendTruncated = false;
    const visibleResponse = projectCapsuleTextSurface(value.visible_response, { maxBytes: 4000 });
    if (visibleResponse) {
        projected.visible_response = visibleResponse.projected;
        frontendRedactedCount += visibleResponse.redactedCount;
        frontendTruncated = frontendTruncated || visibleResponse.truncated;
    }
    const draft = projectCapsuleTextSurface(value.pre_presentation_draft, {
        maxBytes: 4000,
        requireNonAuthoritative: true
    });
    if (draft) {
        projected.pre_presentation_draft = draft.projected;
        frontendRedactedCount += draft.redactedCount;
        frontendTruncated = frontendTruncated || draft.truncated;
    }

    const sourceEffects = Array.isArray(value.effects) ? value.effects : null;
    if (sourceEffects) {
        const projectedEffects = [];
        sourceEffects.slice(0, TURN_FAILURE_CAPSULE_MAX_EFFECTS).forEach((effect) => {
            const projectedEffect = projectCapsuleEffect(effect);
            if (!projectedEffect) {
                return;
            }
            projectedEffects.push(projectedEffect.projected);
            frontendRedactedCount += projectedEffect.redactedCount;
            frontendTruncated = frontendTruncated || projectedEffect.truncated;
        });
        projected.effects = projectedEffects;
        frontendTruncated = frontendTruncated || sourceEffects.length > TURN_FAILURE_CAPSULE_MAX_EFFECTS;
    }

    if (value.effect_summary && typeof value.effect_summary === 'object' && !Array.isArray(value.effect_summary)) {
        const effectSummary = {};
        ['total_count', 'included_count', 'omitted_count'].forEach((fieldName) => {
            if (Number.isSafeInteger(value.effect_summary[fieldName]) && value.effect_summary[fieldName] >= 0) {
                effectSummary[fieldName] = value.effect_summary[fieldName];
            }
        });
        if (Object.keys(effectSummary).length > 0) {
            projected.effect_summary = effectSummary;
        }
    }

    if (Array.isArray(value.canonical_scope_modes)) {
        const allowedModes = new Set(['user', 'organisation', 'global']);
        projected.canonical_scope_modes = Array.from(new Set(
            value.canonical_scope_modes.filter((mode) => allowedModes.has(mode))
        )).slice(0, 3);
    }

    const turnError = projectCapsuleError(value.turn_error);
    if (turnError) {
        projected.turn_error = turnError.projected;
        frontendRedactedCount += turnError.redactedCount;
        frontendTruncated = frontendTruncated || turnError.truncated;
    }

    if (value.redaction && typeof value.redaction === 'object' && !Array.isArray(value.redaction)) {
        const redaction = {};
        ['applied', 'truncated'].forEach((fieldName) => {
            if (typeof value.redaction[fieldName] === 'boolean') {
                redaction[fieldName] = value.redaction[fieldName];
            }
        });
        if (Number.isSafeInteger(value.redaction.redacted_count) && value.redaction.redacted_count >= 0) {
            redaction.redacted_count = value.redaction.redacted_count;
        }
        if (Object.keys(redaction).length > 0) {
            projected.redaction = redaction;
        }
    }

    if (frontendRedactedCount > 0 || frontendTruncated) {
        const existingRedaction = projected.redaction || {};
        projected.redaction = {
            ...existingRedaction,
            applied: Boolean(existingRedaction.applied || frontendRedactedCount > 0),
            redacted_count: (Number.isSafeInteger(existingRedaction.redacted_count)
                ? existingRedaction.redacted_count
                : 0) + frontendRedactedCount,
            truncated: Boolean(existingRedaction.truncated || frontendTruncated)
        };
    }
    return projected;
}

function serialisePrettyJsonWithinUtf8Limit(value) {
    const jsonText = JSON.stringify(value, null, 2);
    return utf8ByteLength(jsonText) <= TURN_FAILURE_CAPSULE_CLIPBOARD_MAX_UTF8_BYTES
        ? jsonText
        : null;
}

function markCapsuleFrontendTruncated(capsule) {
    const redaction = capsule.redaction && typeof capsule.redaction === 'object'
        ? capsule.redaction
        : {};
    capsule.redaction = {
        ...redaction,
        applied: Boolean(redaction.applied),
        redacted_count: Number.isSafeInteger(redaction.redacted_count)
            ? redaction.redacted_count
            : 0,
        truncated: true
    };
}

function compactCapsuleTextSurface(surface, maxBytes) {
    if (!surface || typeof surface !== 'object' || typeof surface.text !== 'string') {
        return;
    }
    const bounded = truncateUtf8Text(surface.text, maxBytes);
    surface.text = bounded.text;
    if (bounded.truncated) {
        surface.char_count = unicodeCharacterCount(bounded.text);
        delete surface.sha256;
        surface.truncated = true;
    }
}

function stringifyBoundedTurnFailureCapsule(projectedCapsule) {
    let jsonText = serialisePrettyJsonWithinUtf8Limit(projectedCapsule);
    if (jsonText) {
        return jsonText;
    }

    const capsule = JSON.parse(JSON.stringify(projectedCapsule));
    markCapsuleFrontendTruncated(capsule);
    delete capsule.effect_summary;
    delete capsule.canonical_scope_modes;
    compactCapsuleTextSurface(capsule.visible_response, 1024);
    compactCapsuleTextSurface(capsule.pre_presentation_draft, 1024);
    compactCapsuleTextSurface(capsule.turn_error?.preview, 256);
    if (Array.isArray(capsule.effects)) {
        capsule.effects.forEach((effect) => compactCapsuleTextSurface(effect?.error?.preview, 256));
    }
    jsonText = serialisePrettyJsonWithinUtf8Limit(capsule);
    if (jsonText) {
        return jsonText;
    }

    if (Array.isArray(capsule.effects)) {
        capsule.effects.forEach((effect) => {
            delete effect.initial_status;
            delete effect.changed;
            delete effect.current_outcome_status;
            delete effect.outcome_resolved;
            delete effect.reconciliation_status;
            delete effect.canonical_readback_verdict;
            delete effect.recovered_by_effect_id;
            delete effect.workflow_id;
            delete effect.instance_id;
            delete effect.evidence_id;
        });
        const failedEffects = capsule.effects.filter((effect) => effect?.error?.code);
        const otherEffects = capsule.effects.filter((effect) => !effect?.error?.code);
        capsule.effects = [...failedEffects, ...otherEffects];
    }
    delete capsule.producer;
    jsonText = serialisePrettyJsonWithinUtf8Limit(capsule);
    if (jsonText) {
        return jsonText;
    }

    delete capsule.pre_presentation_draft;
    delete capsule.visible_response;
    if (capsule.turn_error?.preview) {
        delete capsule.turn_error.preview;
    }
    if (Array.isArray(capsule.effects)) {
        capsule.effects.forEach((effect) => {
            if (effect?.error?.preview) {
                delete effect.error.preview;
            }
        });
        while (capsule.effects.length > 0) {
            jsonText = serialisePrettyJsonWithinUtf8Limit(capsule);
            if (jsonText) {
                return jsonText;
            }
            capsule.effects.pop();
        }
    }
    return serialisePrettyJsonWithinUtf8Limit(capsule);
}

function resolveStoredTurnFailureCapsule(debugData) {
    if (!debugData || typeof debugData !== 'object') {
        return null;
    }
    const candidates = [
        debugData.failure_capsule,
        debugData.turn_failure_capsule,
        debugData.turn_execution_diagnostics?.failure_capsule,
        debugData.turn_execution_record?.failure_capsule
    ];
    return candidates.find((candidate) => (
        candidate
        && typeof candidate === 'object'
        && candidate.schema_version === TURN_FAILURE_CAPSULE_SCHEMA_VERSION
    )) || null;
}

async function buildLlmDebugClipboardJsonForTurn(turnId) {
    const debugData = llmDebugData.get(turnId);
    if (!debugData || typeof debugData !== 'object') {
        return null;
    }

    const storedCapsule = resolveStoredTurnFailureCapsule(debugData);
    const storedProjection = projectTurnFailureCapsule(storedCapsule);
    const requestId = resolveConversationTelemetryRequestId(debugData)
        || storedProjection?.request_id
        || '';
    const historyLocation = cloneConversationHistoryLocation(
        debugData?.turn_execution_diagnostics?.history_location
        || debugData?.history_location
    );
    const hasExactHistoryLocation = Boolean(
        typeof historyLocation?.session_id === 'string'
        && historyLocation.session_id.trim()
        && Number.isInteger(historyLocation.history_index)
        && historyLocation.history_index >= 0
    );
    const fetchedCapsule = hasExactHistoryLocation
        ? await fetchTurnFailureCapsule({
            requestId,
            sessionId: historyLocation?.session_id || null,
            historyIndex: Number.isInteger(historyLocation?.history_index)
                ? historyLocation.history_index
                : null
        })
        : null;
    const capsule = fetchedCapsule || projectTurnFailureCapsule(storedCapsule, {
        expectedRequestId: requestId || null
    });
    if (!capsule) {
        return null;
    }
    if (fetchedCapsule && typeof turnId === 'string' && turnId.trim()) {
        setLlmDebugDataEntry(turnId, {
            ...debugData,
            turn_failure_capsule: fetchedCapsule
        });
    }
    return stringifyBoundedTurnFailureCapsule(capsule);
}

async function buildLlmDebugDeepInspectionJsonForTurn(turnId) {
    let debugDataRaw = llmDebugData.get(turnId);
    if (!hasLlmDebugLocatorReference(debugDataRaw)) {
        return null;
    }

    let debugData = await hydrateTurnHistoryLocationFromConversationLocator(turnId, debugDataRaw);
    const requestId = resolveConversationTelemetryRequestId(debugData);
    const historyLocation = cloneConversationHistoryLocation(
        debugData?.turn_execution_diagnostics?.history_location
        || debugData?.history_location
    );
    const turnAccess = await fetchTurnTelemetryMcpAccess({
        requestId,
        sessionId: historyLocation?.session_id || activeChatSessionId || null,
        historyIndex: Number.isInteger(historyLocation?.history_index)
            ? historyLocation.history_index
            : null,
        includeLiveProgress: false
    });
    if (
        turnAccess?.mcp_access
        && typeof turnAccess.mcp_access === 'object'
        && Object.keys(turnAccess.mcp_access).length > 0
    ) {
        debugData = {
            ...debugData,
            telemetry_locator_mcp_access: turnAccess.mcp_access,
            history_location: cloneConversationHistoryLocation(
                turnAccess.history_location || historyLocation
            )
        };
    }
    const metadata = buildLlmDebugMetadata(debugData);
    const workflowExecutionTelemetry = _getWorkflowExecutionTelemetry(debugData);
    const copyPayload = buildLlmDebugLocatorPayload({
        turnId,
        debugData,
        metadata,
        workflowExecutionTelemetry
    });
    if (!copyPayload) {
        return null;
    }
    return JSON.stringify(copyPayload, null, 2);
}

async function copyLlmDebugJsonForTurn(turnId, button) {
    if (!turnId) {
        setLlmDebugButtonCopyState(button, 'failed');
        return false;
    }

    const jsonText = await buildLlmDebugClipboardJsonForTurn(turnId, { button });
    if (!jsonText) {
        setLlmDebugButtonCopyState(button, 'failed');
        showToast('No bounded turn capsule is available for this turn.');
        return false;
    }

    const copied = await copyTextWithClipboardFallback(jsonText);
    setLlmDebugButtonCopyState(button, copied ? 'copied' : 'failed');
    if (!copied) {
        showToast('Unable to copy bounded turn capsule JSON.');
    }
    return copied;
}

// Show LLM debug popup for a specific turn
async function showLlmDebugPopup(turnId, options = {}) {
    let debugDataRaw = llmDebugData.get(turnId);
    if (!hasLlmDebugPayload(debugDataRaw)) {
        debugDataRaw = await loadLlmDebugDataForTurn(turnId, options);
    }
    let debugData = enrichDebugDataWithSpeechPlanning(debugDataRaw, { turnId });
    if (
        debugData
        && !cloneConversationHistoryLocation(
            debugData.turn_execution_diagnostics?.history_location || debugData.history_location
        )
    ) {
        debugData = await hydrateTurnHistoryLocationFromConversationLocator(
            turnId,
            debugData
        );
    }
    if (!debugData) {
        console.warn('[chatTab] No debug data for turn:', turnId);
        return;
    }

    const popup = document.getElementById('chatLlmDebugPopup');
    const copyBtn = document.getElementById('copyChatLlmDebugJson');
    const metaDiv = document.getElementById('chatLlmDebugMeta');
    const messagesPre = document.getElementById('chatLlmDebugMessages');
    const responsePre = document.getElementById('chatLlmDebugResponse');
    const toolsSection = document.getElementById('chatLlmDebugToolsSection');
    const toolsPre = document.getElementById('chatLlmDebugTools');
    const auxSection = document.getElementById('chatLlmDebugAuxSection');
    const auxPre = document.getElementById('chatLlmDebugAux');
    const workflowDiscoverySection = document.getElementById('chatLlmDebugWorkflowDiscoverySection');
    const workflowDiscoveryPre = document.getElementById('chatLlmDebugWorkflowDiscovery');

    if (!popup || !metaDiv || !messagesPre || !responsePre || !toolsSection || !toolsPre || !auxSection || !auxPre) {
        console.error('[chatTab] LLM debug popup elements missing');
        return;
    }
    if (copyBtn) {
        resetCopyJsonButtonPreCopyState(copyBtn);
    }

    // Display metadata
    const metadata = buildLlmDebugMetadata(debugData);
    const hasError = debugData.error !== undefined;

    let workflowExecutionTelemetry = _getWorkflowExecutionTelemetry(debugData);
    let workflowStages = [];
    if (Array.isArray(debugData.aux_llm_calls)) {
        workflowStages = debugData.aux_llm_calls.filter((entry) => {
            if (!entry || typeof entry !== 'object') {
                return false;
            }
            return entry.type === 'workflow_stage';
        });
    }

    // Build metadata HTML display
    let metadataHtml = '';
    const promptGroups = extractPromptConceptGroups(debugData);
    metadataHtml += buildPromptConceptLinksHtml(promptGroups);
    metadataHtml += buildRenderPlanSummaryHtml(metadata.render_plan);
    metadataHtml += buildTurnDiagnosticsSummaryHtml(metadata.turn_diagnostics);
    if (workflowExecutionTelemetry.traces.length > 0) {
        const workflowSummary = workflowExecutionTelemetry.traces.map((trace) => ({
            workflow_id: trace.workflow_id ?? null,
            execution_id: trace.execution_id ?? null,
            instance_id: trace.instance_id ?? null,
            trace_role: workflowExecutionTelemetry.primaryTrace === trace
                ? 'selected_workflow'
                : 'auxiliary_workflow',
            stored: trace.stored ?? null,
            status: trace.status ?? null
        }));
        metadataHtml += '<div class="llm-debug-metadata-section">';
        metadataHtml += '<strong>Workflow execution traces</strong>';
        if (workflowExecutionTelemetry.primaryTrace) {
            const executionId = typeof workflowExecutionTelemetry.primaryTrace.execution_id === 'string'
                ? workflowExecutionTelemetry.primaryTrace.execution_id.trim()
                : '';
            const instanceId = typeof workflowExecutionTelemetry.primaryTrace.instance_id === 'string'
                ? workflowExecutionTelemetry.primaryTrace.instance_id.trim()
                : '';
            const displayId = executionId || instanceId;
            if (executionId) {
                const href = `/api/workflows/executions/${encodeURIComponent(executionId)}`;
                metadataHtml += '<div>';
                metadataHtml += `<a href="${escapeHtml(href)}" target="_blank" rel="noopener noreferrer">${escapeHtml(executionId)}</a>`;
                metadataHtml += ' <span>(selected workflow)</span>';
                metadataHtml += '</div>';
            } else if (displayId) {
                metadataHtml += '<div>';
                metadataHtml += `<span>${escapeHtml(displayId)}</span>`;
                metadataHtml += ' <span>(selected workflow)</span>';
                metadataHtml += '</div>';
            }
        }
        metadataHtml += '<pre>';
        metadataHtml += escapeHtml(JSON.stringify(workflowSummary, null, 2));
        metadataHtml += '</pre>';
        metadataHtml += '</div>';
    }

    if (workflowStages.length > 0) {
        const stageSummary = workflowStages.map((entry) => ({
            stage: entry.stage ?? null,
            source: entry.source ?? null,
            reason: entry.reason ?? null,
            format: entry.format ?? null
        }));

        metadataHtml += '<div class="llm-debug-metadata-section">';
        metadataHtml += '<strong>Workflow stages</strong>';
        metadataHtml += '<pre>';
        metadataHtml += escapeHtml(JSON.stringify(stageSummary, null, 2));
        metadataHtml += '</pre>';
        metadataHtml += '</div>';
    }

    metadataHtml += '<div class="llm-debug-metadata-section"><strong>Metadata</strong><pre>';
    metadataHtml += escapeHtml(JSON.stringify(metadata, null, 2));
    metadataHtml += '</pre></div>';

    const warnings = deriveLlmDebugWarnings(debugData).filter(w => !String(w).startsWith('Backend error:'));
    if (warnings.length > 0) {
        const warningItems = warnings.map(warning => `<li>${escapeHtml(warning)}</li>`).join('');
        metadataHtml = `
            <div class="llm-debug-warning-box">
                <div class="llm-debug-warning-box-title">Warnings</div>
                <ul class="llm-debug-warning-list">${warningItems}</ul>
            </div>
        ` + metadataHtml;
    }

    metaDiv.innerHTML = metadataHtml;

    bindConceptSelectionClicks(metaDiv, {
        selector: '.llm-debug-prompt-link',
        datasetKey: 'promptLinkBound'
    });

    // Display messages
    try {
        messagesPre.textContent = JSON.stringify(debugData.messages || [], null, 2);
    } catch (_e) {
        messagesPre.textContent = 'Error formatting messages';
    }

    // Display response or error message
    if (hasError) {
        responsePre.textContent = '(Error occurred before response was generated)';
        responsePre.style.color = '#dc3545';
    } else {
        responsePre.textContent = debugData.response || '(no response)';
        responsePre.style.color = '';
    }

    // Display tool invocations if any
    if (debugData.tool_invocations && debugData.tool_invocations.length > 0) {
        toolsSection.classList.remove('hidden');
        try {
            toolsPre.textContent = JSON.stringify(debugData.tool_invocations, null, 2);
        } catch (_e) {
            toolsPre.textContent = 'Error formatting tool invocations';
        }
    } else {
        toolsSection.classList.add('hidden');
    }

    // Display auxiliary LLM calls if any
    if (debugData.aux_llm_calls && debugData.aux_llm_calls.length > 0) {
        auxSection.classList.remove('hidden');
        try {
            auxPre.textContent = JSON.stringify(debugData.aux_llm_calls, null, 2);
        } catch (_e) {
            auxPre.textContent = 'Error formatting auxiliary LLM calls';
        }
    } else {
        auxSection.classList.add('hidden');
    }

    // Display workflow discovery results if any (JVNAUTOSCI-1076)
    if (workflowDiscoverySection && workflowDiscoveryPre) {
        const workflowDiscovery = debugData.workflow_discovery;
        if (workflowDiscovery && (workflowDiscovery.workflows?.length > 0 || workflowDiscovery.error)) {
            workflowDiscoverySection.classList.remove('hidden');
            try {
                workflowDiscoveryPre.textContent = JSON.stringify(workflowDiscovery, null, 2);
            } catch (_e) {
                workflowDiscoveryPre.textContent = 'Error formatting workflow discovery';
            }
        } else {
            workflowDiscoverySection.classList.add('hidden');
        }
    }

    // Prefer turn_execution_diagnostics for parity with active-turn diagnostic references.
    popup.dataset.currentDebugData = await buildLlmDebugDeepInspectionJsonForTurn(turnId, options) || '';

    // Show popup - update aria-hidden BEFORE showing to avoid accessibility warning
    popup.setAttribute('aria-hidden', 'false');
    popup.classList.remove('hidden');

    // Focus close button for accessibility
    const closeBtn = document.getElementById('closeChatLlmDebug');
    if (closeBtn) {
        // Small delay to ensure popup is visible before focusing
        setTimeout(() => closeBtn.focus(), 10);
    }
}

// Handle export conversation info JSON
function buildConversationInfoExportFilename() {
    const timestamp = new Date().toISOString().replace(/:/g, '-').replace(/\.\d{3}Z$/, 'Z');
    return `von_conversation_info_${timestamp}.json`;
}

function parseTurnTimestampMs(value) {
    if (value === null || value === undefined) {
        return null;
    }
    if (typeof value === 'number' && Number.isFinite(value) && value > 0) {
        return Math.floor(value);
    }
    if (typeof value === 'string') {
        const trimmed = value.trim();
        if (!trimmed) {
            return null;
        }
        const asNumber = Number.parseInt(trimmed, 10);
        if (Number.isFinite(asNumber) && asNumber > 0) {
            return asNumber;
        }
        const asDateMs = Date.parse(trimmed);
        if (Number.isFinite(asDateMs) && asDateMs > 0) {
            return asDateMs;
        }
    }
    return null;
}

function parseTurnTimestampFromTurnId(turnId) {
    if (typeof turnId !== 'string') {
        return null;
    }
    const parts = turnId.split('-');
    if (parts.length < 2) {
        return null;
    }
    return parseTurnTimestampMs(parts[parts.length - 1]);
}

function resolveTurnTimestampMs(turnId, debugData, options = {}) {
    const fromDebugData = parseTurnTimestampMs(debugData?.timestamp);
    if (fromDebugData) {
        return fromDebugData;
    }
    if (options.allowTurnIdTimestampFallback === false) {
        return null;
    }
    return parseTurnTimestampFromTurnId(turnId);
}

function buildSortedConversationLlmDebugEntries(options = {}) {
    const entries = Array.from(llmDebugData.entries()).map(([turnId, debugData], index) => ({
        turnId,
        debugData,
        timestampMs: resolveTurnTimestampMs(turnId, debugData, options),
        insertionIndex: index
    }));

    entries.sort((a, b) => {
        const left = Number.isFinite(a.timestampMs) ? a.timestampMs : -1;
        const right = Number.isFinite(b.timestampMs) ? b.timestampMs : -1;
        if (left !== right) {
            return left - right;
        }

        const idCompare = String(a.turnId).localeCompare(String(b.turnId));
        if (idCompare !== 0) {
            return idCompare;
        }

        return a.insertionIndex - b.insertionIndex;
    });

    return entries;
}

function cloneConversationHistoryLocation(historyLocation) {
    if (!historyLocation || typeof historyLocation !== 'object') {
        return null;
    }
    return { ...historyLocation };
}

function isSameConversationHistoryLocation(left, right) {
    const leftLocation = cloneConversationHistoryLocation(left);
    const rightLocation = cloneConversationHistoryLocation(right);
    if (!leftLocation || !rightLocation) {
        return false;
    }
    const leftSessionId = typeof leftLocation.session_id === 'string' ? leftLocation.session_id.trim() : '';
    const rightSessionId = typeof rightLocation.session_id === 'string' ? rightLocation.session_id.trim() : '';
    const leftHistoryIndex = Number(leftLocation.history_index);
    const rightHistoryIndex = Number(rightLocation.history_index);
    return Boolean(
        leftSessionId
        && rightSessionId
        && leftSessionId === rightSessionId
        && Number.isInteger(leftHistoryIndex)
        && Number.isInteger(rightHistoryIndex)
        && leftHistoryIndex === rightHistoryIndex
    );
}

function resolveConversationTelemetryRequestId(debugData) {
    if (!debugData || typeof debugData !== 'object') {
        return null;
    }

    const directRequestId = typeof debugData.request_id === 'string'
        ? debugData.request_id.trim()
        : '';
    if (directRequestId) {
        return directRequestId;
    }

    const turnDiagnosticsRequestId = typeof debugData.turn_diagnostics?.request_id === 'string'
        ? debugData.turn_diagnostics.request_id.trim()
        : '';
    if (turnDiagnosticsRequestId) {
        return turnDiagnosticsRequestId;
    }

    const turnExecutionRequestId = typeof debugData.turn_execution_diagnostics?.request_id === 'string'
        ? debugData.turn_execution_diagnostics.request_id.trim()
        : '';
    return turnExecutionRequestId || null;
}

function buildConversationTelemetryNamespaceContext() {
    const namespace = getSessionScopedNamespace();
    const orgContext = getSessionScopedOrgContext();
    const userId = getCurrentUserConceptId();

    return {
        namespace: namespace || null,
        user_id: userId || null,
        org_id: orgContext?.concept_id || orgContext?.id || null
    };
}

function normaliseConversationRuntimeCostString(value) {
    return (typeof value === 'string' && value.trim()) ? value.trim() : null;
}

function cloneConversationRuntimeCostValue(value) {
    if (!value || typeof value !== 'object') return null;
    try {
        return JSON.parse(JSON.stringify(value));
    } catch (_) {
        return null;
    }
}

function buildConversationRuntimeCostContext() {
    const namespaceContext = buildConversationTelemetryNamespaceContext();
    return {
        conversation_session_id: normaliseHistorySessionId(activeChatSessionId),
        window_session_id: normaliseConversationRuntimeCostString(getWindowSessionId()),
        user_concept_id: normaliseConversationRuntimeCostString(namespaceContext.user_id),
        organisation_concept_id: normaliseConversationRuntimeCostString(namespaceContext.org_id),
        namespace: normaliseConversationRuntimeCostString(namespaceContext.namespace)
    };
}

function runtimeIdentitySignature(runtime) {
    if (!runtime || typeof runtime !== 'object') return null;
    const pid = Number.isFinite(Number(runtime.pid)) ? String(Number(runtime.pid)) : '';
    const startedAt = normaliseConversationRuntimeCostString(runtime.started_at_utc || runtime.start_time);
    return (pid || startedAt) ? `${pid}|${startedAt || ''}` : null;
}

function publishConversationRuntimeCostSnapshot(reason = 'update') {
    const snapshot = {
        schema_version: CONVERSATION_RUNTIME_COST_SNAPSHOT_SCHEMA_VERSION,
        reason,
        context: cloneConversationRuntimeCostValue(conversationRuntimeCostState.context),
        runtime: cloneConversationRuntimeCostValue(conversationRuntimeCostState.runtime),
        baseline: cloneConversationRuntimeCostValue(conversationRuntimeCostState.baseline),
        live: cloneConversationRuntimeCostValue(conversationRuntimeCostState.live),
        loading: conversationRuntimeCostState.loading === true,
        error: conversationRuntimeCostState.error || null,
        as_of_utc: new Date().toISOString()
    };
    try {
        window.__vonConversationRuntimeCostSnapshot = snapshot;
    } catch (_) {
        // Publishing is best effort; rendering remains non-critical.
    }
    try {
        document.dispatchEvent(new CustomEvent('von:conversationRuntimeCostUpdated', {
            detail: snapshot
        }));
    } catch (_) {
        // Footer telemetry cannot interrupt chat execution.
    }
    return snapshot;
}

function clearConversationRuntimeCostSnapshot(reason = 'context_changed', context = buildConversationRuntimeCostContext()) {
    if (conversationRuntimeCostState.handoverRetryTimerId) {
        clearTimeout(conversationRuntimeCostState.handoverRetryTimerId);
        conversationRuntimeCostState.handoverRetryTimerId = null;
    }
    conversationRuntimeCostState.generation += 1;
    conversationRuntimeCostState.fetchSequence += 1;
    conversationRuntimeCostState.context = context;
    conversationRuntimeCostState.contextSignature = JSON.stringify(context);
    conversationRuntimeCostState.baseline = null;
    conversationRuntimeCostState.live = null;
    conversationRuntimeCostState.loading = false;
    conversationRuntimeCostState.error = null;
    conversationRuntimeCostState.inFlight = null;
    publishConversationRuntimeCostSnapshot(reason);
}

function scheduleConversationRuntimeCostHandoverRetry({ observeRequestId, retryAttempt, reason }) {
    if (retryAttempt >= 3 || conversationRuntimeCostState.handoverRetryTimerId) return;
    const contextSignature = conversationRuntimeCostState.contextSignature;
    const delayMs = 600 * (2 ** retryAttempt);
    conversationRuntimeCostState.handoverRetryTimerId = setTimeout(() => {
        conversationRuntimeCostState.handoverRetryTimerId = null;
        if (conversationRuntimeCostState.contextSignature !== contextSignature) return;
        void refreshConversationRuntimeCostSnapshot({
            observeRequestId,
            retryAttempt: retryAttempt + 1,
            reason
        });
    }, delayMs);
}

function refreshConversationRuntimeCostSnapshot({
    excludeRequestId = null,
    observeRequestId = null,
    retryAttempt = 0,
    reason = 'baseline_refresh'
} = {}) {
    const context = buildConversationRuntimeCostContext();
    const sessionId = context.conversation_session_id;
    if (!sessionId) {
        clearConversationRuntimeCostSnapshot('no_conversation_context', context);
        return Promise.resolve(null);
    }
    // Some narrowly isolated unit tests intentionally omit the browser fetch
    // surface. Do not turn a support-only footer refresh into a chat failure.
    if (typeof fetch !== 'function') {
        return Promise.resolve(null);
    }
    const signature = JSON.stringify(context);
    if (conversationRuntimeCostState.contextSignature !== signature) {
        clearConversationRuntimeCostSnapshot('context_changed', context);
    }
    const requestGeneration = conversationRuntimeCostState.generation;
    const cleanExcludedRequestId = normaliseConversationRuntimeCostString(excludeRequestId);
    const cleanObservedRequestId = normaliseConversationRuntimeCostString(observeRequestId);
    const inFlight = conversationRuntimeCostState.inFlight;
    if (inFlight && inFlight.generation === requestGeneration
        && inFlight.excludeRequestId === cleanExcludedRequestId
        && inFlight.observeRequestId === cleanObservedRequestId) {
        return inFlight.promise;
    }
    const requestFetchSequence = conversationRuntimeCostState.fetchSequence + 1;
    conversationRuntimeCostState.fetchSequence = requestFetchSequence;
    conversationRuntimeCostState.loading = true;
    conversationRuntimeCostState.error = null;
    publishConversationRuntimeCostSnapshot(reason);
    const params = new URLSearchParams({ session_id: sessionId });
    if (cleanExcludedRequestId) params.set('exclude_request_id', cleanExcludedRequestId);
    if (cleanObservedRequestId) params.set('observe_request_id', cleanObservedRequestId);
    const promise = fetch(`/von/history/cost_summary?${params.toString()}`, {
        method: 'GET',
        headers: buildChatFetchHeaders(),
        cache: 'no-store'
    })
        .then(async (response) => {
            const payload = await response.json().catch(() => null);
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            if (payload?.schema_version !== CONVERSATION_RUNTIME_COST_SNAPSHOT_SCHEMA_VERSION) {
                throw new Error('Unexpected conversation cost summary schema');
            }
            if (normaliseConversationRuntimeCostString(payload?.scope?.conversation_session_id) !== sessionId) {
                throw new Error('Conversation cost summary scope did not match the selected conversation');
            }
            return payload;
        })
        .then((payload) => {
            if (conversationRuntimeCostState.generation !== requestGeneration
                || conversationRuntimeCostState.fetchSequence !== requestFetchSequence
                || conversationRuntimeCostState.contextSignature !== signature) return null;
            conversationRuntimeCostState.baseline = payload;
            conversationRuntimeCostState.runtime = payload.runtime && typeof payload.runtime === 'object'
                ? cloneConversationRuntimeCostValue(payload.runtime)
                : null;
            conversationRuntimeCostState.runtimeIdentitySignature = runtimeIdentitySignature(conversationRuntimeCostState.runtime);
            // Retire a completed live overlay only after the server proves that
            // this exact request is present in the scoped persisted baseline.
            // This avoids a transient undercount during durable-record lag.
            const handoverObserved = payload?.handover?.observed === true;
            if (cleanObservedRequestId
                && handoverObserved
                && conversationRuntimeCostState.live?.request_id === cleanObservedRequestId
                && conversationRuntimeCostState.live?.active !== true) {
                if (conversationRuntimeCostState.handoverRetryTimerId) {
                    clearTimeout(conversationRuntimeCostState.handoverRetryTimerId);
                    conversationRuntimeCostState.handoverRetryTimerId = null;
                }
                conversationRuntimeCostState.live = null;
            } else if (cleanObservedRequestId && !handoverObserved) {
                scheduleConversationRuntimeCostHandoverRetry({
                    observeRequestId: cleanObservedRequestId,
                    retryAttempt,
                    reason: 'terminal_handover_retry'
                });
            }
            return payload;
        })
        .catch((error) => {
            if (conversationRuntimeCostState.generation === requestGeneration
                && conversationRuntimeCostState.fetchSequence === requestFetchSequence
                && conversationRuntimeCostState.contextSignature === signature) {
                conversationRuntimeCostState.error = error?.message || 'Cost estimate unavailable';
            }
            return null;
        })
        .finally(() => {
            if (conversationRuntimeCostState.generation === requestGeneration
                && conversationRuntimeCostState.fetchSequence === requestFetchSequence
                && conversationRuntimeCostState.contextSignature === signature) {
                conversationRuntimeCostState.loading = false;
                conversationRuntimeCostState.inFlight = null;
                publishConversationRuntimeCostSnapshot(reason);
            }
        });
    conversationRuntimeCostState.inFlight = {
        generation: requestGeneration,
        fetchSequence: requestFetchSequence,
        excludeRequestId: cleanExcludedRequestId,
        observeRequestId: cleanObservedRequestId,
        promise
    };
    return promise;
}

function synchroniseConversationRuntimeCostContext({ force = false, reason = 'context_refresh' } = {}) {
    const context = buildConversationRuntimeCostContext();
    const signature = JSON.stringify(context);
    if (!force && conversationRuntimeCostState.contextSignature === signature) return;
    clearConversationRuntimeCostSnapshot(reason, context);
    if (context.conversation_session_id) {
        void refreshConversationRuntimeCostSnapshot({ reason });
    }
}

function setConversationRuntimeCostLiveSummary(request, summary = null, { active = true, reason = 'live_progress' } = {}) {
    const context = buildConversationRuntimeCostContext();
    const requestSessionId = normaliseHistorySessionId(request?.sessionId);
    const requestId = normaliseConversationRuntimeCostString(
        request?.clientRequestId || request?.latestProgress?.request_id
    );
    if (!requestId || !requestSessionId || requestSessionId !== context.conversation_session_id) return;
    if (conversationRuntimeCostState.contextSignature !== JSON.stringify(context)) {
        clearConversationRuntimeCostSnapshot('context_changed', context);
    }
    conversationRuntimeCostState.live = {
        request_id: requestId,
        active: active === true,
        summary: summary && typeof summary === 'object' ? cloneConversationRuntimeCostValue(summary) : null
    };
    publishConversationRuntimeCostSnapshot(reason);
}

function handleConversationRuntimeIdentityUpdate(detail) {
    const incoming = detail && typeof detail === 'object' ? detail : null;
    const nextSignature = runtimeIdentitySignature(incoming);
    if (!nextSignature) return;
    const currentSignature = conversationRuntimeCostState.runtimeIdentitySignature;
    if (!currentSignature) {
        conversationRuntimeCostState.runtimeIdentitySignature = nextSignature;
        return;
    }
    if (currentSignature === nextSignature) return;
    conversationRuntimeCostState.runtime = {
        pid: Number.isFinite(Number(incoming.pid)) ? Number(incoming.pid) : null,
        started_at_utc: normaliseConversationRuntimeCostString(incoming.start_time || incoming.started_at_utc)
    };
    clearConversationRuntimeCostSnapshot('runtime_identity_changed');
    if (conversationRuntimeCostState.context?.conversation_session_id) {
        void refreshConversationRuntimeCostSnapshot({ reason: 'runtime_identity_changed' });
    }
}

function buildMcpToolAccess(toolName, args = {}, purpose = null) {
    const cleanArgs = {};
    if (args && typeof args === 'object') {
        Object.entries(args).forEach(([key, value]) => {
            if (value === undefined || value === null || value === '') {
                return;
            }
            cleanArgs[key] = value;
        });
    }
    const payload = {
        tool_name: toolName,
        arguments: cleanArgs
    };
    if (typeof purpose === 'string' && purpose.trim()) {
        payload.purpose = purpose.trim();
    }
    return payload;
}

function buildChatHistoryAccessArgs({ sessionId, historyIndex = undefined } = {}) {
    const namespaceContext = buildConversationTelemetryNamespaceContext();
    return {
        session_id: sessionId || activeChatSessionId || null,
        history_index: Number.isInteger(historyIndex) ? historyIndex : undefined,
        namespace: namespaceContext.namespace || null,
        user_concept_id: namespaceContext.user_id || null,
        organisation_concept_id: namespaceContext.org_id || null
    };
}

function buildThinkingDiagnosticsLocatorPayload(
    request,
    { mcpAccess = null, retrievalStatus = null } = {}
) {
    if (!request || typeof request !== 'object') {
        return null;
    }

    const namespaceContext = buildConversationTelemetryNamespaceContext();
    const latestProgress = (request.latestProgress && typeof request.latestProgress === 'object')
        ? request.latestProgress
        : null;
    const requestId = (typeof request.clientRequestId === 'string' ? request.clientRequestId.trim() : '')
        || (typeof latestProgress?.request_id === 'string' ? latestProgress.request_id.trim() : '');
    if (!requestId) {
        return null;
    }
    const executableMcpAccess = (
        mcpAccess
        && typeof mcpAccess === 'object'
    )
        ? Object.fromEntries(
            Object.entries(mcpAccess).filter(([toolName, descriptor]) => (
                [
                    'turn_execution_get_live_progress',
                    'turn_execution_get_diagnostics',
                    'conversation_telemetry_get_locator',
                    'chat_history_get_debug_entry'
                ].includes(toolName)
                && descriptor
                && typeof descriptor === 'object'
            ))
        )
        : {};

    const cleanRetrievalStatus = typeof retrievalStatus === 'string'
        ? retrievalStatus.trim()
        : '';
    const resolvedRetrievalStatus = Object.keys(executableMcpAccess).length > 0
        ? 'server_delegation_available'
        : (
            cleanRetrievalStatus === 'server_delegation_available'
                ? 'server_delegation_empty'
                : cleanRetrievalStatus || 'server_delegation_unavailable'
        );

    return {
        schema_version: TURN_LIVE_PROGRESS_LOCATOR_SCHEMA_VERSION,
        generated_at_utc: new Date().toISOString(),
        request_id: requestId,
        chat_session_id: activeChatSessionId || null,
        namespace_context: namespaceContext,
        latest_progress_summary: latestProgress ? {
            status: latestProgress.status || null,
            stage: latestProgress.stage || null,
            phase: latestProgress.phase || null,
            elapsed_ms: Number.isFinite(Number(latestProgress.elapsed_ms))
                ? Math.max(0, Math.round(Number(latestProgress.elapsed_ms)))
                : null
        } : null,
        mcp_access: executableMcpAccess,
        retrieval_status: resolvedRetrievalStatus
    };
}

