export function __testOnly_resetChatRequestState() {
    if (conversationRuntimeCostState.handoverRetryTimerId) {
        clearTimeout(conversationRuntimeCostState.handoverRetryTimerId);
    }
    conversationRuntimeCostState.generation += 1;
    conversationRuntimeCostState.fetchSequence += 1;
    conversationRuntimeCostState.contextSignature = null;
    conversationRuntimeCostState.context = null;
    conversationRuntimeCostState.runtime = null;
    conversationRuntimeCostState.runtimeIdentitySignature = null;
    conversationRuntimeCostState.baseline = null;
    conversationRuntimeCostState.live = null;
    conversationRuntimeCostState.loading = false;
    conversationRuntimeCostState.error = null;
    conversationRuntimeCostState.inFlight = null;
    conversationRuntimeCostState.handoverRetryTimerId = null;
    try {
        window.__vonConversationRuntimeCostSnapshot = null;
    } catch (_) {
        // Ignore constrained test globals.
    }
    for (const request of liveChatRequestsBySession.values()) {
        request.aborted = true;
        stopToolUseProgressPolling(request);
        stopForegroundTaskResultPolling(request);
        stopThinkingTooltipTicker(request);
        try {
            request.abortController?.abort();
        } catch (_) {
            // Ignore reset-time abort races.
        }
    }
    liveChatRequestsBySession.clear();
    finishedThinkingCardsBySession.clear();
    pendingFileCopyConceptIdsBySession.clear();
    pendingFileCopyDisplayNamesBySession.clear();
    for (const uploadState of uploadStatesBySession.values()) {
        if (uploadState?.clearTimerId) {
            clearTimeout(uploadState.clearTimerId);
        }
    }
    uploadStatesBySession.clear();
    renderActiveUploadUi();
    renderPendingAttachmentState();
    queuedChatPrompts = [];
    stopChatPromptQueuePolling();
    chatPromptQueuePollInFlight = false;
    queuedChatPromptClaimsInFlight.clear();
    queuedChatPromptSubmissionsInFlight.clear();
    serverDispatchedRetryObserversInFlight.clear();
    chatPromptQueueAdmissionServerInstanceId = null;
    for (const timer of queuedChatPromptSyncTimers.values()) {
        clearTimeout(timer);
    }
    queuedChatPromptSyncTimers.clear();
    queuedChatPromptCounter = 0;
    selectedChatPromptQueueEntryId = null;
    locallyHiddenChatPromptQueueEntryKeys.clear();
    activeChatRequest = null;
    lastFinishedThinkingCard = null;
    newChatCreationInFlight = null;
    activeChatSessionId = null;
    activeChatSessionName = null;
    activeChatSessionOwnerId = null;
    chatSessionFocusCache.clear();
    activeChatSessionFocus = [];
    renderActiveChatSessionFocusChips([]);
    _clearConversationSituationState({ closePanel: true });
    renderChatTaskQueuePanel();
    updateSendButtonForCurrentChatState();
}
